P.entries["item:99-year-old-port"] = {n="99 Jahre alter Portwein",s="An den Docks von Ratschet ist eine Flasche 99 Jahre alten Portweins verschwunden. Mad Magglish nahm sie bei einem Frachtunfall an sich und floh in Richtung der Höhlen des Wehklagens.",h="An den Docks von Ratschet ist eine Flasche 99 Jahre alten Portweins verschwunden.",kw={"99 jahre alter portwein","moppelfuzz","gazlowe","mad magglish","portwein","ratschet","revilgaz","die höhlen des wehklagens"},ang={["class:Rogue"]="Mad Magglish nutzt laienhafte Verstohlenheit, um sich im Dunkeln vor den Höhlen des Wehklagens zu verbergen. Als Schurke könnt Ihr ihn aus den Schatten treiben."},sec={{t="Wertvolle Fracht zu Bruch",b="Kranführer Moppelfuzz überlud seinen Kran, als er in Ratschet eine große Lieferung aus Beutebucht entlud. Kisten krachten über die Docks. Im Durcheinander schnappte sich Mad Magglish eine Flasche 99 Jahre alten Portweins und floh in die Hügel in Richtung der Höhlen des Wehklagens."},{t="Diplomatischer Jahrgang",b="Baron Revilgaz von den Blackwater Raiders schickte den Portwein als diplomatisches Geschenk an Gazlowe, den Chefingenieur und Herrscher von Ratschet. Sein Verlust bedroht Moppelfuzz’ Lebensunterhalt und belastet das Verhältnis zum Hafenmeister. Mad Magglish lauert mit der ungeöffneten Flasche in den äußeren Grotten der Höhlen. Die Hafenarbeiter suchen Söldner, die sie zurückholen, bevor Gazlowe von dem Missgeschick erfährt."}},faq={{q="Für wen war der 99 Jahre alte Portwein ursprünglich bestimmt?",a="Baron Revilgaz, der Herr von Beutebucht, schickte die Flasche als persönliches Geschenk an Gazlowe, den Boss von Ratschet.",al={"für wen ist der portwein","wer bekommt den portwein","gazlowes geschenk"}},{q="Wie kam Mad Magglish an den Portwein?",a="Moppelfuzz überlud beim Entladen der Fracht seinen Kran und verstreute dabei Kisten über die Docks von Ratschet. Mad Magglish schnappte sich im Durcheinander die Flasche und rannte davon.",al={"wie wurde er gestohlen","wer stahl den portwein","missgeschick am dock"}},{q="Wohin brachte Mad Magglish die Flasche?",a="Magglish floh landeinwärts durch das Brachland und versteckte sich in den felsigen Vorkammern und äußeren Tunneln, die in die Höhlen des Wehklagens führen.",al={"wo ist mad magglish","wo ist der portwein versteckt","fundort des portweins"}},{q="Warum holte Moppelfuzz den Portwein nicht selbst zurück?",a="Moppelfuzz verfolgte Magglish bis zum Eingang der Höhlen des Wehklagens, weigerte sich aber, sie zu betreten. Er fürchtete die Bestien und verderbten Druiden darin.",al={"warum verfolgt moppelfuzz ihn nicht","feiger kranführer"}}},fx={["5b0242c9"]={q="Was ist der 99 Jahre alter Portwein?",a="Es ist eine außergewöhnlich seltene und gereifte Flasche Likörwein, die den ganzen Weg aus der Beutebucht verschifft wurde. Als prestigeträchtiges persönliches Geschenk von Baron Revilgaz an Gazlowe, den Chefingenieur und Anführer von Ratschet, gesandt, stellt dieser Jahrgang ein unschätzbares Zeichen der Wertschätzung zwischen mächtigen Goblin-Handelsbaronen dar.",al={"was ist 99 jahre alter portwein","99 jahre alter portwein","flasche portwein"}}},fp="16,141,24.258.0,18.378.1,50.101.0,42.157.0,39.125.0,48.140.0"}
P.entries["item:a-bloodstained-journal-page"] = {n="Eine blutbefleckte Tagebuchseite",s="Bei den Ermittlungen gegen Stalvan Dunstmantel lässt Kommandantin Althea Schwarzhaupt eine zerrissene, blutbefleckte Tagebuchseite untersuchen. Einige Worte sind noch lesbar, also bittet sie Amtmann Daltry, die Handschrift mit dem Town Registry zu vergleichen.",h="Bei den Ermittlungen gegen Stalvan Dunstmantel lässt Kommandantin Althea Schwarzhaupt eine zerrissene...",kw={"blutbefleckt","daltry","dunkelhain","dämmerwald","schwarzhaupt","handschrift","tagebuch","stalvan"},ang={["faction:Alliance"]="Als Beschützer des Reiches könnt Ihr sehen, wie die Nachtwache von Dunkelhain dieses düstere Dokument als Beweisstück für die Ermittlungen untersucht."},sec={{t="Ein düsteres Beweisstück",b="Kommandantin Althea Schwarzhaupt wacht über Dunkelhain und bittet darum, die Handschrift auf einer zerrissenen, blutbefleckten Seite zu untersuchen. Dickes Blut bedeckt sie, doch einige Worte sind noch lesbar. Amtmann Daltry wird gebeten, sie mit dem Town Registry zu vergleichen."},{t="Handschrift und Schuld",b="Amtmann Daltry führt das Register in der Town Hall von Dunkelhain. Durch das jahrelange Archivieren von Unterschriften kennt er die örtlichen Handschriften. Er vergleicht die Seite mit städtischen Aufzeichnungen und bestätigt, dass Stalvan sie geschrieben hat. Die Schuld des Hauslehrers steht außer Zweifel."}},faq={{q="Was ist diese blutbefleckte Tagebuchseite?",a="Die zerrissene, blutbefleckte Tagebuchseite wird im Rahmen der Ermittlungen gegen Stalvan Dunstmantel untersucht. Kommandantin Althea Schwarzhaupt bittet Amtmann Daltry, die Handschrift zu überprüfen.",al={"blutbefleckte tagebuchseite","stalvans tagebuchseite","blutige seite"}},{q="Wer kann bestätigen, wer diese Seite geschrieben hat?",a="Amtmann Daltry in der Town Hall von Dunkelhain kann bestätigen, wer die Seite geschrieben hat. Er führt das Stadtregister und vergleicht die Schrift mit alten Unterschriften, um Stalvans Handschrift zu bestätigen.",al={"wer liest die seite","amtmann daltry tagebuch","wer erkennt die handschrift"}},{q="Warum muss Althea Schwarzhaupt diese Seite untersuchen lassen?",a="Kommandantin Althea Schwarzhaupt beobachtet Stalvan schon seit einiger Zeit. Sie möchte, dass Amtmann Daltry die Seite mit dem Town Registry vergleicht und herausfindet, ob beides von derselben Hand geschrieben wurde.",al={"warum althea die seite braucht","warum die handschrift prüfen"}},{q="Wohin führt diese Seite bei den Ermittlungen?",a="Die Seite geht an Amtmann Daltry in Dunkelhain, damit er sie mit dem Register vergleicht. Nachdem er die Handschrift untersucht hat, werden die Ermittlungen bei Kommandantin Schwarzhaupt fortgesetzt.",al={"was nach der seite geschieht","stalvan questreihe nächster schritt"}}},fx={e0fa872a={q="Woher stammt die Blutbefleckte Tagebuchseite und wer hat sie verfasst?",a="Die Seite ist ein abgerissenes Überbleibsel aus Stalvan Dunstmantels persönlichem Tagebuch. Die erhaltenen Worte beschreiben seine Verzweiflung und seine Absicht, Blut zu vergießen.",al={"wer schrieb die blutbefleckte tagebuchseite","herkunft der tagebuchseite von stalvan","woher stammt die blutbefleckte seite"}}},fp="27,228,24.240.0,21.232.1,39.170.0,36.167.0,50.181.0,47.165.1"}
P.entries["item:a-carefully-packed-crate"] = {n="A Carefully-packed Crate",s="Die Carefully-packed Crate bringt Eier aus Tanaris zu Erelas Ambersky in Rut’theran Village. Der Druide versorgt die Eier, bis sie schlüpfen, und bildet die jungen Hippogryphen aus.",h="Die Carefully-packed Crate bringt Eier aus Tanaris zu Erelas Ambersky in Rut’theran Village.",kw={"sorgfältig gepackte kiste","kiste","curgle","eier","erelas ambersky","hippogryph","hippogrypheneier","rut'theran","tanaris"},ang={["class:Druid"]="Als Druide kennt Ihr die Arbeit, Lebewesen zu versorgen. Erelas kümmert sich um die Eier und bildet die jungen Hippogryphen aus."},sec={{t="Die Lieferung",b="Erelas Ambersky kümmert sich in Rut’theran Village um die Eier, einem kleinen Dorf im Süden von Teldrassil. Sobald sie schlüpfen, bildet er die jungen Hippogryphen aus. Er bittet Euch, die Kiste sicher aus Tanaris zu bringen, wo Curgle die Lieferung bereitstellt."}},faq={{q="Was ist in der Kiste?",a="Die Carefully-packed Crate enthält Eier, um die sich Erelas Ambersky bis zum Schlüpfen kümmern soll.",al={"kisteninhalt","was ist drin","eier in der kiste"}},{q="Wer ist Erelas Ambersky?",a="Erelas Ambersky ist ein Druide in Rut’theran Village, der sich um die Eier kümmert und die jungen Hippogryphen ausbildet.",al={"wer ist erelas","erelas","hippogryphen-druide"}},{q="Wohin soll die Kiste gebracht werden?",a="Die Kiste soll zu Erelas Ambersky nach Rut’theran Village, einem kleinen Dorf im Süden von Teldrassil.",al={"wohin mit der kiste","ziel der kiste","lieferung nach rut'theran"}},{q="Wer schickt die Lieferung?",a="Curgle stellt die Lieferung mit Eiern für Erelas Ambersky bereit.",al={"wer hat sie gepackt","curgles kiste","woher"}},{q="Warum werden die Eier verschickt?",a="Erelas versorgt die Eier, bis sie schlüpfen, und bildet dann die jungen Hippogryphen aus.",al={"warum eier","hippogrypheneier","wofür ist die lieferung"}}},fp="24,170,12.237.0,21.83.0,23.107.0,24.98.0,23.57.0,28.74.0"}
P.entries["item:a-clue-to-sanders-treasure"] = {n="A Clue to Sanders' Treasure",s="In Westfall führt A Clue to Sanders' Treasure Suchende weiter auf Kapitän Sanders' Spur. Es markiert den zweiten Schritt einer Suche über Klippen und entlang der Küsten.",h="In Westfall führt A Clue to Sanders' Treasure Suchende weiter auf Kapitän Sanders' Spur.",kw={"fass","schornstein","hinweis","pirat","sanders","schatz","westfall"},sec={{t="Das Rätsel eines Piraten",b="Nachdem Ihr Kapitän Sanders' erster Schatzkarte gefolgt seid, findet Ihr ein Pergament, das weiter ins Landesinnere von Westfall weist. Die darauf gekritzelte Notiz schickt Euch von der Küste nach Osten und die Klippen hinauf zur Hauptstraße.\n\nNahe zerfallenden Steinruinen und einem verlassenen Schornstein markiert ein altes Fass die Stelle, an der Sanders den nächsten Hinweis versteckte. Die Spur führt tiefer in das geplagte Ackerland."}},faq={{q="Was ist dieser Hinweis?",a="Kapitän Sanders hinterließ eine handgeschriebene Notiz, um jeden, der klug genug ist, seiner Spur zu folgen, zu einem weiteren versteckten Behälter in Westfall zu führen.",al={"sanders hinweis","hinweis auf sanders' schatz","was ist ein hinweis auf sanders' schatz"}},{q="Wohin führt dieser Hinweis?",a="Der Hinweis schickt Euch von der Küste nach Osten und die Klippen hinauf zur Straße von Westfall. Ein altes Fass liegt nahe einem verfallenen Schornstein.",al={"wohin gehen","ziel des hinweises","standort des schornsteins"}},{q="Wer war Kapitän Sanders?",a="Kapitän Sanders war ein Pirat. Sein Vermächtnis lebt in den Schatzverstecken und Rätseln weiter, die er entlang der Küsten und im Landesinneren von Westfall verbarg.",al={"wer ist kapitän sanders","sanders geschichte","kapitän sanders"}}},fx={e66b6229={q="Woher stammt dieser Hinweis und wer hat ihn angefertigt?",a="Diese schriftliche Notiz wurde von Kapitän Sanders hinterlassen, einem berüchtigten Haudegen, der seine unerlaubte Beute in ganz Westfall vergrub. Anstatt eine direkte Karte zu seiner Beute zu hinterlassen, verfasste der gerissene Seekapitän eine Kette von Rätseln und Wegbeschreibungen und versteckte jede Nachricht an Wahrzeichen entlang der Küste, um jeden zu testen, der mutig oder clever genug war, seinem Vermächtnis nachzuspüren.",al={"wer erstellte den hinweis von sanders","woher kam der hinweis","ursprung des hinweises"}},["4dc920ed"]={q="Warum ist dieser Hinweis für Schatzsucher wertvoll?",a="Für sich genommen ist das Pergament nur ein kryptischer Reim, aber für einen aufstrebenden Glücksritter ist es ein entscheidender Schritt, um Captain Sanders' sagenumwobenes verstecktes Depot zu entdecken. Dem Weg zu folgen ist die einzige Möglichkeit, den nächsten Hinweis in seiner ausgeklügelten Schnitzeljagd zu finden und letztendlich die Reichtümer zu beanspruchen, die der Piratenkapitän beiseitegeschafft hat.",al={"warum den hinweis von sanders wollen","warum ist der hinweis wichtig","wozu ist der hinweis von sanders gut"}}},fp="27,161,17.359.0,18.130.0,26.124.0,24.133.0"}
P.entries["item:a-dusty-unsent-letter"] = {n="Ein verstaubter, nie abgeschickter Brief",s="In Mondbruch gibt ein nie abgeschickter Brief Aufschluss über Stalvan Dunstmantels Vergangenheit. Er wurde in einer alten Fußkiste gefunden und bestätigt, dass er vor seinem Verschwinden dort lebte.",h="In Mondbruch gibt ein nie abgeschickter Brief Aufschluss über Stalvan Dunstmantels Vergangenheit.",kw={"amtmann daltry","dunkelhain","verstaubter nie abgeschickter brief","unglückseliger geist","mondbruch","stalvan dunstmantel","the legend of stalvan"},ang={["faction:Alliance"]="Als Reisende der Allianz könnt Ihr Dunkelhain helfen, genaue Aufzeichnungen zu führen, indem Ihr Stalvans Spur zwischen den Menschensiedlungen in Westfall und im Dämmerwald nachgeht."},sec={{t="Eine Spur im Staub",b="Ermittler, die Mondbruch durchsuchen, finden einen nie abgeschickten Brief in einer alten Fußkiste. Das Stadtregister von Dunkelhain führt die Schule in Mondbruch noch immer als Stalvan Dunstmantels letzte Adresse auf. Amtmann Daltry will wissen, ob er wirklich dort lebte. Der Brief bestätigt, dass Stalvan eine Zeit lang in der Ortschaft in Westfall wohnte.\n\nDer Fund des Briefes schreckt einen rachsüchtigen Unglückseligen Geist auf. Der Geist bewacht die Überreste von Stalvans Vergangenheit mit bitterer Bosheit."},{t="Das Register wird berichtigt",b="Im Rathaus von Dunkelhain nimmt Amtmann Daltry den Brief als Beweis für das Stadtregister entgegen. Er findet es seltsam, dass die Korrespondenz nie abgeschickt wurde. Ihre Spur deutet auf Stalvans Weg durch die südlichen Königreiche der Allianz hin."}},faq={{q="Wo ist dieser Brief zu finden?",a="Der Brief liegt in einer verlassenen Fußkiste in Mondbruch in Westfall. Ringsum stehen verfallene Häuser, die von der Bruderschaft der Defias überrannt wurden.",al={"fundort des briefes","wo gibt es den verstaubten nie abgeschickten brief","brief aus mondbruch"}},{q="Warum wurde der Brief nie abgeschickt?",a="Niemand weiß, warum der Brief nie abgeschickt wurde. Amtmann Daltry findet dies verdächtig und vermutet, dass Stalvan womöglich überstürzt aus Mondbruch floh oder seine Korrespondenz zurückließ, bevor er weiterzog.",al={"warum nie abgeschickt","stalvans nie abgeschickter brief","für wen war der brief"}},{q="Wer muss diesen Brief sehen?",a="Amtmann Daltry muss den Brief sehen. Er verwaltet das Stadtregister im Rathaus von Dunkelhain.",al={"wem den brief geben","amtmann daltry brief","brief abgeben"}},{q="Warum greift beim Fund ein Geist an?",a="Wer die Fußkiste anrührt, beschwört einen Unglückseligen Geist, der mit Stalvans gespenstischem Vermächtnis verbunden ist. Er greift jeden an, der in seinem vergessenen Leben nachforscht, und belegt Eindringlinge mit dem schwächenden Curse of Stalvan.",al={"unglückseliger geist","warum erscheint ein geist","curse of stalvan"}}},fx={f7d2f799={q="Was ist Ein verstaubter, nie abgeschickter Brief?",a="Dieses abgenutzte Pergament ist ein unversandtes Schriftstück, das in einer alten Truhe in Mondbruch versteckt war. Es dient als konkreter Beweis dafür, dass der schwer fassbare Stalvan Dunstmantel einst in der Siedlung in Westfall lebte, bevor er aus der lokalen Geschichte verschwand.",al={"verstaubter nie abgeschickter brief","was ist der verstaubte nie abgeschickte brief","nicht abgeschickter brief mondbruch"}},["9d1bfc16"]={q="Woher stammt Ein verstaubter, nie abgeschickter Brief und wer hat ihn verfasst?",a="Der Brief wurde in Mondbruch hinterlassen und in einer Truhe in der verlassenen Stadt aufbewahrt. Er wurde während Stalvan Dunstmantels Aufenthalt in Westfall verfasst und von ihm geschrieben, um mit Kontakten außerhalb des Dorfes zu korrespondieren, obwohl er aus unbekannten Gründen zurückgelassen wurde, bevor er jemals versandt werden konnte.",al={"wer schrieb den verstaubten nie abgeschickten brief","woher kam der brief","ursprung des verstaubten briefes"}},ab0e7a8a={q="Warum möchte jemand Ein verstaubter, nie abgeschickter Brief haben?",a="Amtmann Daltry in Dunkelhain benötigt offizielle Beweise, um das Stadtregister bezüglich Stalvan Dunstmantel zu aktualisieren. Da die Stadtunterlagen Lücken aufweisen, bietet dieser Brief die notwendige Bestätigung, dass Stalvan in Mondbruch wohnte, was es Daltry ermöglicht, seine früheren Bewegungen ordnungsgemäß zu dokumentieren.",al={"wer will den verstaubten nie abgeschickten brief","warum den verstaubten brief behalten","warum den brief zu daltry bringen"}}},fp="21,154,18.440.0,21.237.1,27.132.0,30.184.0,29.98.0,41.199.0"}
P.entries["item:a-faded-journal-page"] = {n="Eine verblasste Tagebuchseite",s="Im Osten von Elwynn liegt in Marshal Haggards Haus eine alte Seite ungelesen, die mit Stalvan Dunstmantels düsterer Vergangenheit verbunden ist.",h="Im Osten von Elwynn liegt in Marshal Haggards Haus eine alte Seite ungelesen, die mit Stalvan Dunstmantels...",kw={"dunkelhain","wald von elwynn","verblasste tagebuchseite","marshal haggard","smitts","stalvan"},ang={["faction:Alliance"]="Als Reisende der Allianz könnt Ihr mit dieser vergessenen Aufzeichnung helfen, ein Rätsel zu lösen, das die Bewohner beiderseits des Flusses zwischen Elwynn und dem Dämmerwald beunruhigt."},sec={{t="Pergament in der Truhe",b="Jahrelang lag die verblasste Tagebuchseite in einer alten Truhe in Marshal Haggards Haus nahe der Ostgrenze des Waldes von Elwynn. Haggard hatte sich dort zur Ruhe gesetzt, doch seine schwindende Sehkraft hinderte ihn daran, das verwitterte Pergament zu lesen. Die Seite blieb unbeachtet, bis Ermittler auf der Suche nach der Wahrheit über Stalvan Dunstmantel sie bargen."},{t="Die Spur nach Dunkelhain",b="Da Marschall Haggard die brüchige Schrift nicht lesen konnte, schickte er Ermittler über den Fluss zur Scarlet Raven Tavern im Dämmerwald. Schankwart Smitts untersuchte die Seite und erkannte die Handschrift. Sie verband die Seite mit der düsteren Geschichte, die die Region heimsucht."}},faq={{q="Wo findet man die verblasste Tagebuchseite?",a="Die Seite liegt in einer Truhe im Obergeschoss eines Hauses nahe Marschall Haggard, im östlichen Wald von Elwynn an der Flussgrenze zum Dämmerwald.",al={"fundort der seite","wo ist die verblasste tagebuchseite","standort der truhe"}},{q="Warum konnte Marschall Haggard die Seite nicht selbst lesen?",a="Das Alter hat Marshal Haggards Sehkraft so sehr geschwächt, dass er die verblasste Schrift nicht mehr entziffern kann.",al={"warum las haggard sie nicht","marshal haggards blindheit"}},{q="Wer erkennt die Handschrift auf der Tagebuchseite?",a="Schankwart Smitts, der Wirt der Scarlet Raven Tavern in Dunkelhain, erkennt die Handschrift, als er die Seite untersucht.",al={"wer kennt die handschrift","wer liest die seite"}},{q="Was beschützt die Truhe mit der Seite?",a="Ein feindseliger Unglückseliger Geist greift jeden an, der die Truhe im Obergeschoss öffnet, bevor die Seite gefahrlos untersucht werden kann.",al={"geist an der truhe","was greift an der truhe an"}}},fx={["6378278c"]={q="Was ist die Verblichene Tagebuchseite?",a="Es ist ein gealtertes, verwittertes Pergament, das aus einer Truhe im Haus von Marschall Haggard geborgen wurde. Die Schrift darauf ist mit der Zeit verblasst, aber es bewahrt einen authentischen Eintrag, der die privaten Gedanken und Bewegungen von Stalvan Dunstmantel detailliert beschreibt und als konkreter Hinweis dient, um seine dunkle Geschichte aufzudecken.",al={"was ist die verblichene tagebuchseite","verblichene tagebuchseite","info zur verblichenen tagebuchseite"}},["0f9a7ce9"]={q="Woher stammt die Verblichene Tagebuchseite?",a="Die Seite wurde von Stalvan Dunstmantel selbst als Teil seines persönlichen Tagebuchs geschrieben. Sie landete in einem Bündel aufgegebener Pergamente, die in einer Truhe im Obergeschoss des Wohnhauses versteckt waren, in dem Marschall Haggard später nahe der Grenze zwischen dem Wald von Elwynn und dem Dämmerwald Quartier bezog.",al={"ursprung der verblichenen tagebuchseite","wer schrieb die verblichene tagebuchseite","woher kam die verblichene tagebuchseite"}},["200aee1d"]={q="Warum wird die Verblichene Tagebuchseite gesucht?",a="Ermittler, die nach der Wahrheit hinter der rätselhaften Figur suchen, die als Stalvan Dunstmantel bekannt ist, benötigen die Seite, um seine Vergangenheit zusammenzusetzen. Da die Handschrift darauf unverwechselbar ist, kann das Zeigen bei sachkundigen Einheimischen wie Schankwart Smitts in Dunkelhain entscheidende Hinweise bezüglich Stalvans Geschichte und Aufenthaltsort freischalten.",al={"warum die verblichene tagebuchseite wollen","warum die verblichene tagebuchseite benötigen","zweck der verblichenen tagebuchseite"}}},fp="20,112,22.316.0,22.254.1,38.133.0,51.96.0,51.126.0,44.109.0"}
P.entries["item:a-letter-to-grelin-whitebeard"] = {n="Ein Brief für Grelin Weißbart",s="Ein Brief aus Eisenschmiede erreicht Grelin Weißbart in seinem Lager im Coldridgetal. Seine Neuigkeiten und Anweisungen bringen die Berghauptstadt dem verschneiten Grenzland nahe.",h="Ein Brief aus Eisenschmiede erreicht Grelin Weißbart in seinem Lager im Coldridgetal.",kw={"das coldridgetal","dun morogh","grelin weißbart","eisenschmiede","brief","postzustellung"},ang={["race:Dwarf"]="Als Zwerg tragt Ihr womöglich Depeschen über die eisigen Pässe von Dun Morogh. Junge Gebirgsjäger und Rekruten erfüllen damit eine grundlegende Pflicht und hoffen, sich einen Namen zu machen."},sec={{t="Eine Depesche aus den Bergen",b="Grelin Weißbart erhält in seinem Lager im Coldridgetal eine Depesche aus Eisenschmiede. Ambossar bietet Schutz, doch das Tal liegt weit von dieser Sicherheit entfernt. Briefe verbinden Späher und Gelehrte im Feld mit den Hallen der Berghauptstadt. Dieser Brief ist auf den Bergpfaden nach Süden gekommen, um ihn zu erreichen."}},faq={{q="Wer ist Grelin Weißbart?",a="Grelin Weißbart ist ein zwergischer Späher und Entdecker, der im Südosten des Coldridgetals lagert. Boten aus Ambossar bringen ihm Neuigkeiten und Anweisungen aus Eisenschmiede.",al={"grelin weißbart","wer ist grelin","empfänger"}},{q="Woher stammt dieser Brief?",a="Der Brief stammt aus Eisenschmiede, der Hauptstadt der Zwerge. Ein örtlicher Postbote trägt ihn durch das Coldridgetal hinaus ins Feld.",al={"herkunft des briefs","wer hat den brief geschickt","woher stammt er"}},{q="Was steht in dem Brief?",a="König Magni Bronzebart schickt Grelin eine kurze Nachricht. Da die Zeit drängt, ermächtigt er Grelin, nach eigenem Ermessen gegen die Trolle vorzugehen, besonders wenn Grelin eine schnelle Lösung finden kann. Grelin freut sich über die Nachricht; seit er zuletzt aus Eisenschmiede gehört hat, ist einige Zeit vergangen.",al={"briefinhalt","was steht darin","brieftext"}}},fx={["163f292d"]={q="Was ist Ein Brief für Grelin Weißbart?",a="Es ist ein versiegeltes Schreiben, das aus Eisenschmiede gesandt und durch Das Coldridgetal zur Zustellung an Grelin Weißbart in seinem Lager an der Straße getragen wurde.",al={"was ist der brief für grelin weißbart","brief für grelin weißbart","was ist dieser brief"}},b0fcb20c={q="Warum möchte Grelin Weißbart diesen Brief haben?",a="Grelin ist schon seit einiger Zeit in seinem Lager im Coldridgetal stationiert, ohne Nachrichten aus der Hauptstadt. Er ist begierig darauf, Nachricht aus Eisenschmiede zu erhalten.",al={"warum den brief an grelin überbringen","warum möchte grelin den brief","wer will den brief von grelin"}}},fp="29,164,28.300.0,25.163.0,32.134.0,26.268.0"}
P.entries["item:a-mysterious-message"] = {n="Eine mysteriöse Nachricht",s="In Westfall beweist die abgefangene Nachricht eines Kuriers der Volksmiliz, wer die Bruderschaft der Defias lenkt.",h="In Westfall beweist die abgefangene Nachricht eines Kuriers der Volksmiliz, wer die Bruderschaft der Defias...",kw={"blacknails","defias messenger","edwin van cleef","gryan starkmantel","mondbruch","mysteriöse nachricht","westfall"},ang={["class:Rogue"]="Die abgefangene Depesche gewährt Schurken einen Einblick in die Sicherheitsvorkehrungen, Kurierwege und verschlüsselte Verständigung der Unterwelt der Defias.",["faction:Alliance"]="Für die Streiter der Allianz, die in Westfall helfen, beweist das abgefangene Dokument, dass die Unruhen im Ackerland des Königreichs ein geplanter Aufstand unter Edwin van Cleefs Führung sind, keine wahllose Banditerei."},sec={{t="Gerüchte über Blacknails",b="Die Depesche nennt VanCleef als Oberhaupt der Bruderschaft und erwähnt einen Verbündeten namens Blacknails. Ihr weitreichendes Netzwerk bleibt verborgen. Durch die Entschlüsselung des Dokuments gewinnt die Volksmiliz ein Druckmittel gegen gefangene Beutelschneider und einen Weg zur wahren Festung der Bruderschaft."},{t="Abgefangene Befehle",b="Ein Defias Messenger trägt die Nachricht zwischen den Stützpunkten der Defias in Mondbruch, im Goldküstensteinbruch und im Jangoschacht hin und her. Ihr Abfangen bedeutet einen Durchbruch in Gryan Starkmantels Ermittlungen. Seit Wochen vermutete die Volksmiliz, dass jemand den Banditenaufstand lenkte, hatte jedoch keine sicheren Beweise.\n\nDas Schreiben bestätigt, dass Edwin van Cleef die Unternehmungen der Bruderschaft in ganz Westfall befehligt. Dabei bedient er sich verschlüsselter Rangbezeichnungen und Mittelsmänner."}},faq={{q="Was erfährt die Volksmiliz durch diese Nachricht?",a="Die Nachricht liefert Gryan Starkmantel den Beweis, dass Edwin van Cleef die Unternehmungen der Bruderschaft der Defias in ganz Westfall lenkt. Sie bestätigt den Verdacht der Miliz darüber, wer die Gesetzlosen befehligt.",al={"was steht auf dem zettel","hintergrund zur mysteriösen nachricht","was steht in der nachricht"}},{q="Wer ist Blacknails?",a="Blacknails wird im abgefangenen Text als Verbündeter oder Agent genannt. Über die Identität oder den Aufenthaltsort ist kaum mehr bekannt, weshalb Blacknails zu den undurchsichtigen Gestalten tief im Netzwerk der Defias zählt.",al={"wer ist blacknails","hintergrund zu blacknails","defias blacknails"}},{q="Wer trägt diese Nachricht bei sich?",a="Ein Defias Messenger trägt die Nachricht auf Westfalls Straßen zwischen Mondbruch, dem Goldküstensteinbruch und dem Jangoschacht hin und her, um Banditenaktionen abzustimmen.",al={"wer hat die nachricht","wer lässt die mysteriöse nachricht fallen","kurier der defias"}},{q="Was geschieht, nachdem Gryan Starkmantel sie gelesen hat?",a="Nachdem VanCleefs Rolle bestätigt ist, macht sich die Miliz auf die Suche nach dem Hauptquartier der Defias. Ein gefangener Dieb willigt ein, Späher zum geheimen Versteck zu führen, wenn dafür sein Leben verschont wird.",al={"what comes next","starkmantels reaktion","nach der mysteriösen nachricht"}}},fx={["9bec86bb"]={q="Was ist Eine mysteriöse Nachricht?",a="Es ist ein versiegelter Brief, der von einem Defias-Boten durch Westfall getragen wird. Er ist an einen Agenten namens Blacknails adressiert und enthält entscheidende Korrespondenz unter den Verschwörern, die innerhalb der Region operieren.",al={"mysteriöse nachricht","was ist diese nachricht","notiz der defias"}},ea5b5889={q="Woher stammt Eine mysteriöse Nachricht und wer hat sie verfasst?",a="Die Nachricht stammt aus den oberen Rängen der The Defias Brotherhood, verfasst als Anweisungen an ihren Agenten Blacknails und transportiert entlang der Kurierroute, die Mondbruch, den Goldküstensteinbruch und den Jangoschacht verbindet.",al={"wer schrieb die mysteriöse nachricht","wer sandte die mysteriöse nachricht","ursprung der mysteriösen nachricht"}},f3ab4b79={q="Warum möchte Gryan Starkmantel Eine mysteriöse Nachricht haben?",a="Gryan Starkmantel und die The People's Militia sind verzweifelt darauf bedacht, das geheime Versteck der The Defias Brotherhood zu lokalisieren und deren Befehlsstruktur zu verstehen. Das Abfangen dieses Schreibens liefert ihnen konkrete schriftliche Beweise dafür, dass Edwin van Cleef die Rebellion der Bruderschaft direkt orchestriert.",al={"warum die mysteriöse nachricht wollen","warum die nachricht für starkmantel","warum die mysteriöse nachricht beschaffen"}}},fp="20,116,22.276.1,18.437.1,54.191.1,18.205.0,25.159.0,46.172.1"}
P.entries["item:a-short-note"] = {n="A Short Note",s="„Eine kurze Notiz“ bittet Euch, Daryns Brief in Tanaris zu Curgle Cranklehop zu bringen. Darin bittet sie um ein Bild von Gammerita, einem Riesenschnappkiefer im Hinterland.",h="„Eine kurze Notiz“ bittet Euch, Daryns Brief in Tanaris zu Curgle Cranklehop zu bringen.",kw={"eine kurze notiz","curgle cranklehop","daryn","gammerita","hinterland","bild","schnappkiefer","tanaris"},sec={{t="Ein Brief für Curgle",b="Daryns Forschungen halten sie im Hinterland, wo sie die Schnappkiefer entlang des Strandes untersucht. Sie möchte ein Bild von Gammerita, einem Riesenschnappkiefer, und schickt Euch mit einem Brief für Curgle Cranklehop nach Tanaris. Curgle hat eine Erfindung gemacht, mit der sich Bilder aufnehmen lassen."}},faq={{q="Wer hat die Notiz geschrieben?",a="Daryn hat den Brief geschrieben. Sie ist eine Historikerin, die Schnappkiefer im Hinterland erforscht.",al={"wer schickte den brief","daryns notiz","von wem ist es"}},{q="Wer ist Gammerita?",a="Gammerita ist ein Riesenschnappkiefer am Strand im Hinterland. Daryn möchte ein Bild von ihr.",al={"riesenschnappkiefer","wer ist gammerita","ziel schnappkiefer"}},{q="Wer ist Curgle Cranklehop?",a="Curgle Cranklehop ist in Tanaris und hat eine Erfindung gemacht, mit der sich Bilder aufnehmen lassen.",al={"curgle","wer erhält die notiz","erfinder in tanaris"}},{q="Warum möchte Daryn ein Bild?",a="Daryn möchte ein Bild von Gammerita, weil sie ihre Forschungen im Hinterland nicht verlassen kann, um den Riesenschnappkiefer selbst zu sehen.",al={"warum gammerita fotografieren","warum schnappkiefer fotografieren","was möchte daryn"}}},fp="12,152,19.266.0,19.80.0,17.91.0,25.85.0,30.125.0"}
P.entries["item:a-shrunken-head"] = {n="A Shrunken Head",s="Ein geschrumpfter Kopf aus Feralas wird Neeru Fireblade in Orgrimmar versprochen. Damit sollen die für ein Experiment benötigten Kräuter gesichert werden.",h="Ein geschrumpfter Kopf aus Feralas wird Neeru Fireblade in Orgrimmar versprochen.",kw={"die kluft der schatten","zwerg","experiment","feralas","kräuter","neeru fireblade","orgrimmar","geschrumpfter kopf","uzer'i"},sec={{t="Ein düsterer Handel",b="Bevor die Kräuter verwendet werden können, schuldet Neeru Fireblade in Orgrimmar eine düstere Gegenleistung. Der Kopf stammt von einem Zwerg, der in den Wäldern von Feralas gefunden wurde. Sein Träger bringt ihn zur Kluft der Schatten, wo Neeru eine Kräutermischung für Uzer'is Experimente vorbereitet hat."}},faq={{q="Wem gehörte der Kopf?",a="Der Kopf gehörte einem Zwerg, der in den Wäldern von Feralas gefunden wurde.",al={"von wem ist der kopf","zwergenkopf","besitzer des geschrumpften kopfes"}},{q="Wer soll ihn erhalten?",a="Neeru Fireblade in Orgrimmar wurde der Kopf versprochen.",al={"wer bekommt den kopf","wem soll ich ihn bringen","neeru kopf"}},{q="Warum will Neeru den Kopf?",a="Der Kopf ist die Bezahlung für Kräuter, die Neeru für Uzer'is Experimente vorbereitet hat.",al={"warum den kopf bringen","wofür ist er","zweck des kopfes"}},{q="Wohin soll ich den geschrumpften Kopf bringen?",a="Bringt den geschrumpften Kopf zu Neeru Fireblade in die Kluft der Schatten in Orgrimmar.",al={"wohin soll ich ihn bringen","zielort des kopfes","die kluft der schatten"}}},fp="15,124,14.261.0,17.61.0,30.50.0,29.70.0,34.78.0"}
P.entries["item:a-simple-compass"] = {n="Ein einfacher Kompass",s="Auf dem niedergebrannten Alexstons Bauernhof in Westfall liegt ein einfacher Kompass in einer kleinen Truhe. Er gehörte Baros Alexston, bevor dieser Stadtarchitekt von Sturmwind wurde.",h="Auf dem niedergebrannten Alexstons Bauernhof in Westfall liegt ein einfacher Kompass in einer kleinen Truhe.",kw={"alexston","baros","beginnings","truhe","kompass","bauernhof","sturmwind","westfall"},ang={["faction:Alliance"]="Baros Alexston bei der Bergung seines Andenkens zu helfen, zeigt das menschliche Leid durch den Aufstand der Defias. Selbst angesehene Anführer in Sturmwind haben durch die Unruhen in Westfall das Zuhause ihrer Familie verloren.",["race:Human"]="Als Mensch des Königreichs könnt Ihr im Kompass den Gegensatz erkennen: die sicheren, vergoldeten Innenhöfe von Sturmwind und das verlassene, gesetzlose Grenzland Westfalls."},sec={{t="Ein Andenken an die Jugend",b="Baros Alexston wuchs bei der Arbeit auf dem Hof seiner Familie in Westfall auf. Sein erstes Instrument zur Orientierung war ein einfacher Kompass. Vielleicht weckte er sein Interesse an Geometrie, technischem Zeichnen und Erkundung. Dann überfiel die Bruderschaft der Defias den Bauernhof und brannte ihn nieder, wobei der Kompass in einer stabilen Truhe zwischen den Ruinen zurückblieb, während Banditen das Ackerland überrannten."},{t="Ein ideeller Wert",b="Baros' Vater entkam der Zerstörung, konnte den Besitz der Familie jedoch nicht in Sicherheit bringen. Innerhalb der steinernen Mauern von Sturmwind hat der Kompass für einen Meisterbaumeister wenig Nutzen. Doch Baros bedeutet er viel. Seine Rückkehr würde eine seltene, unversehrte Verbindung zu seinen bescheidenen Anfängen und der friedlichen ländlichen Umgebung seiner Kindheit wiederherstellen."}},faq={{q="Was ist ein einfacher Kompass?",a="Als Junge auf dem Hof seiner Familie in Westfall besaß Baros Alexston einen einfachen Kompass, einen schlichten Taschenkompass ohne magische Kräfte.",al={"einfacher kompass","alexston kompass","baros kompass"}},{q="Wo befindet sich der Kompass?",a="Der Kompass liegt in Alexston's Chest in den ausgebrannten Ruinen von Alexstons Bauernhof, gleich westlich der Späherkuppe in Westfall.",al={"wo kompass finden","kompass fundort","alexston truhe fundort"}},{q="Wer möchte den Kompass zurückhaben?",a="Baros Alexston, der Stadtarchitekt von Sturmwind, möchte den Kompass zurückhaben. Er ist nahe dem Rathaus am Kathedralenplatz zu finden.",al={"wer braucht den kompass","kompass abgeben","wem gehört der kompass"}},{q="Warum blieb der Kompass auf dem Hof zurück?",a="Die Gesetzlosen der Defias überfielen den Hof der Familie Alexston und brannten ihn nieder. Baros' Vater floh um sein Leben und konnte die schwereren Besitztümer der Familie nicht mitnehmen, sodass die Truhe in den Trümmern zurückblieb.",al={"warum wurde der kompass zurückgelassen","was geschah mit dem bauernhof"}}},fp="16,160,18.345.0,17.325.0,25.116.0,29.131.0,32.127.0,44.181.0"}
P.entries["item:a-sparkling-stone"] = {n="A Sparkling Stone",s="Der Sparkling Stone befindet sich im Equinex Monolith in Feralas. Troyas Moonbreeze erkennt ihn als Morrow Stone und beginnt, seinen Zweck zu erforschen.",h="Der Sparkling Stone befindet sich im Equinex Monolith in Feralas.",kw={"equine monolith","mondfederfeste","feralas","morrow stone","sparkling stone","stock von equinex","troyas moonbreeze"},sec={{t="In Feathermoon",b="Nach Eurer Rückkehr zur Mondfederfeste bringt Ihr den Sparkling Stone und den Stock von Equinex zu Troyas Moonbreeze. Er nennt den Stein Morrow Stone und sagt, dass er noch nicht weiß, wozu er dient. Sein Platz im Equinex Monolith macht ihn zu einem lohnenden Forschungsgegenstand."}},faq={{q="Was ist der Sparkling Stone?",a="Troyas Moonbreeze erkennt den Sparkling Stone als Morrow Stone, ein Artefakt aus dem Equinex Monolith.",al={"sparkling stone","morrow stone","welcher stein"}},{q="Wo findet Ihr den Sparkling Stone?",a="Der Sparkling Stone befindet sich im Equinex Monolith in Feralas.",al={"fundort des steins","wo ist der stein","morrow stone finden"}},{q="Wer ist Troyas Moonbreeze?",a="Troyas Moonbreeze ist der Gelehrte an der Mondfederfeste, der den Morrow Stone und den Stock von Equinex zur Erforschung erhält.",al={"troyas","troyas moonbreeze","wer will den stein"}},{q="Wozu dient der Stein?",a="Troyas Moonbreeze kennt den Zweck des Morrow Stone noch nicht, hält ihn aber für bedeutsam.",al={"zweck des steins","was bewirkt er","verwendung des morrow stone"}}},fp="17,153,14.285.0,28.114.0,38.68.0,25.124.0,22.95.0"}
P.entries["item:a-stack-of-letters"] = {n="Ein Stapel Briefe",s="Im Coldridgetal ist ein Stapel Briefe für Späher in der verschneiten Wildnis durch den Bergpass eingetroffen.",h="Im Coldridgetal ist ein Stapel Briefe für Späher in der verschneiten Wildnis durch den Bergpass eingetroffen.",kw={"ambossar","das coldridgetal","coldridge valley mail delivery","grelin weißbart","ein stapel briefe","talin keeneye"},ang={["race:Dwarf"]="Als junger Gebirgsjäger am Anfang Eures Weges im Coldridgetal tragt Ihr Post zwischen verschneiten Lagern hin und her. Auf der Reise lernt Ihr die beschwerlichen Straßen und verstreuten Wachen von Dun Morogh kennen."},sec={{t="Durch den Pass",b="Briefe für das Coldridgetal kommen aus Ambossar und werden von Reisenden über den Pass gebracht. Der Weg zu den abgelegenen Lagern in den Bergen von Dun Morogh ist beschwerlich, weshalb Postläufer auf Reisende angewiesen sind, die jedes Bündel weitertragen. Dieses ist für Späher bestimmt, die tiefer im Coldridgetal stationiert sind.\n\nBis die Briefe sortiert werden, gilt Talin Keeneye in seinem Lager am See als einziger Empfänger. Darunter befindet sich eine Botschaft für den Gebirgsjäger Grelin Weißbart."}},faq={{q="Was enthält der Stapel Briefe?",a="Das Bündel enthält persönliche Briefe und Depeschen für Zwerge im Coldridgetal. Talin Keeneye in seinem Lager nahe dem zugefrorenen See gilt als einziger Empfänger, bis sich ein an Grelin Weißbart gerichteter Brief findet.",al={"was steht in den briefen","inhalt des briefstapels","für wen sind die briefe"}},{q="Wer schickt diese Briefe ins Coldridgetal?",a="Die Briefe kamen durch den Pass ins Coldridgetal und erreichten Ambossar. Von dort brachte ein Reisender sie weiter, der bereit war, sie die Straße entlangzutragen.",al={"woher kamen die briefe","wer hat die briefe geschickt"}},{q="Wer erhält die Briefe?",a="Der zwergische Späher Talin Keeneye erhält das Paket in seinem Lager am zugefrorenen See. Beim Durchsehen des Stapels findet er einen Brief für Grelin Weißbart.",al={"wer erhält die briefe","ziel der briefzustellung"}}},fx={["6f17116a"]={q="Was ist Ein Stapel Briefe?",a="Es ist ein Bündel Post, das durch den Gebirgspass im Coldridgetal ankam. Es wurde Euch in Ambossar anvertraut und der Stapel enthält Korrespondenz, die für lokale Bergsteiger bestimmt ist, die in der verschneiten Wildnis stationiert sind.",al={"was ist der stapel briefe","gegenstand stapel briefe","was sind die briefe"}},["9fce371d"]={q="Warum möchte jemand Ein Stapel Briefe haben?",a="Die Bergsteiger, die in der Kälte leben und patrouillieren, sind auf regelmäßige Post angewiesen, um informiert zu bleiben. Talin Keeneye wartet schon seit geraumer Zeit am gefrorenen See auf diese Depeschen, obwohl bei näherer Betrachtung nicht jeder Brief in dem Bündel ausschließlich ihm gehört.",al={"warum die briefe überbringen","warum möchte talin die briefe","zweck des stapels briefe"}}},fp="18,110,16.437.0,36.225.0,44.154.0,25.149.0"}
P.entries["item:a-torn-journal-page"] = {n="Eine zerrissene Tagebuchseite",s="In Sturmwind birgt eine zerrissene Tagebuchseite einen Hinweis auf Stalvan Dunstmantels Vergangenheit. Ihre verblasste Schrift verweist auf alte Aufzeichnungen im Wald von Elwynn.",h="In Sturmwind birgt eine zerrissene Tagebuchseite einen Hinweis auf Stalvan Dunstmantels Vergangenheit.",kw={"canals","dämmerwald","legende von stalvan","marshal haggard","versiegelte kiste","stalvan dunstmantel","sturmwind","zerrissene tagebuchseite"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr erkennen, wie ungelöste Verbrechen und vergessene Aufzeichnungen in Sturmwind und Elwynn bis ins bedrängte Grenzland des Dämmerwalds Unruhe tragen."},sec={{t="Ein Hinweis in Canals",b="Eine zerrissene Tagebuchseite liegt in einer versiegelten Vorratskiste an den Kanälen von Sturmwind. Vergessene persönliche Habseligkeiten umgeben sie, darunter alte Bücher, Familienerbstücke und eine Keramikvase. Die Schrift verweist auf Stalvan Dunstmantels Vergangenheit, doch die Seite ist beschädigt und schwer zu lesen. Wer im Königreich könnte diese Handschrift kennen?"},{t="Der Spur Dunstmantels folgen",b="Marschall Haggard lebt im Wald von Elwynn, weit entfernt von Sturmwind. Das Augenlicht des alternden Offiziers schwindet, doch er erinnert sich an die unverwechselbare Handschrift aus einem früheren Kapitel der tragischen Dunstmantel-Saga. Die verwitterte Seite muss jemanden erreichen, der mit den älteren Aufzeichnungen des Königreichs vertraut ist."}},faq={{q="Wo findet man die zerrissene Tagebuchseite?",a="Eine zerrissene Tagebuchseite liegt in einer versiegelten Vorratskiste an den Kanälen von Sturmwind. Vergessene Haushaltsgegenstände, Jagdtrophäen und eine alte Keramikvase liegen darunter.",al={"fundort zerrissene tagebuchseite","wo zerrissene tagebuchseite finden","versiegelte kiste sturmwind"}},{q="Aus wessen Tagebuch stammt diese Seite?",a="Die Seite stammt aus Stalvan Dunstmantels persönlichen Aufzeichnungen. Er war ein ehemaliger Hauslehrer, dessen finstere Vergangenheit und plötzliches Verschwinden Ermittlungen im Dämmerwald und im Wald von Elwynn auslösten.",al={"wer schrieb die tagebuchseite","verfasser der zerrissenen seite","wer ist stalvan"}},{q="Wer kann die Handschrift auf der zerrissenen Seite lesen?",a="Marschall Haggard kann die Handschrift erkennen. Der betagte, beinahe blinde Offizier im Ruhestand lebt nahe dem Holzfällerlager des Osttals im östlichen Wald von Elwynn und kennt sie aus der Zeit, bevor sein Augenlicht schwand.",al={"zu wem die zerrissene seite bringen","wer liest die zerrissene tagebuchseite","marshal haggard tagebuch"}},{q="Warum ist der Fund der Seite für den Dämmerwald wichtig?",a="Die Seite ist wichtig, weil der Town Council von Dunkelhain Stalvan Dunstmantels Geschichte rekonstruiert. Seine Mitglieder suchen die Wahrheit hinter beunruhigenden Vorfällen und lange verborgenen Verbrechen, die mit ihm zusammenhängen.",al={"warum ist das tagebuch für den dämmerwald wichtig","stalvans verbindung zum dämmerwald"}}},fx={["8b619691"]={q="Was ist die Zerrissene Tagebuchseite?",a="Die Zerrissene Tagebuchseite ist ein zerfetztes Blatt, das versteckt unter alten Familienerbstücken, Büchern und Jagdtrophäen in einer versiegelten Lagerkiste in Sturmwind entdeckt wurde. Sie dient als wichtiges schriftliches Beweisstück bezüglich Stalvan Dunstmantel und bietet eine unverwechselbare Handschriftprobe, die sein ruhiges früheres Leben mit den dunklen Geheimnissen verknüpft, die den Dämmerwald heimsuchen.",al={"geschichte der zerrissenen tagebuchseite","was ist die zerrissene tagebuchseite","was ist diese tagebuchseite"}}},fp="19,138,20.317.0,28.281.1,37.167.0,38.182.0,46.202.0,45.190.0"}
P.entries["item:abercrombie-s-crate"] = {n="Calvinius' Kiste",s="Nahe dem Ogerhort Vul'Gol wartet Calvinius' Kiste auf ihren Besitzer. Oger vertrieben ihn beim Kräutersammeln, und seine empfindlichen Werkzeuge blieben zurück.",h="Nahe dem Ogerhort Vul'Gol wartet Calvinius' Kiste auf ihren Besitzer.",kw={"calvinius","calvinius' kiste","dämmerwald","ogerhort","ogre thieves","vul'gol"},ang={["faction:Alliance"]="Ihr wagt Euch in den Ogerhort Vul'Gol, um verlorene Güter zurückzuholen. Oger bedrohen den südlichen Dämmerwald.",["profession:Herbalism"]="Calvinius wagt sich für seltene Pflanzen tief in den Wald. Seine Botanikerausrüstung zurückzuholen, ist für einen ortsansässigen Kräuterkundigen eine vertraute Aufgabe."},sec={{t="An die Oger verloren",b="Calvinius verließ seine Hütte im westlichen Dämmerwald, um Pflanzen zu sammeln. Weit von zu Hause traf er auf eine feindselige Ogerbande und floh um sein Leben. Seine Kiste mit Instrumenten und gesammelten Pflanzen ließ er zurück. Die Oger trugen sie zum Ogerhort Vul'Gol, wo die schwere Truhe nahe dem Höhleneingang steht."},{t="Merkwürdiger Inhalt",b="Calvinius bezeichnet die Werkzeuge und Pflanzen in seiner Kiste als harmlos. Doch als die Kiste zurückgebracht wird, verrät ihn seine Aufregung. Beinahe dankt er dem „Nek-“, bevor er sich fängt. Der Zweck seiner gestohlenen Werkzeuge bleibt fraglich."}},faq={{q="Wo befindet sich die Kiste?",a="Die Kiste steht im Freien neben dem Höhleneingang beim Ogerhort Vul'Gol, in den südlichen Hügeln des Dämmerwalds.",al={"standort der kiste","wo ist calvinius' kiste","vul'gol kiste"}},{q="Warum hat Calvinius sie verloren?",a="Calvinius sammelte weit von seinem Zuhause Kräuter, als Oger ihn angriffen. Er floh zu Fuß und ließ seine Vorräte zurück. Die Oger trugen sie in ihren Unterschlupf.",al={"wie kamen die oger an die kiste","warum ist die kiste bei den ogern"}},{q="Was ist in der Kiste?",a="Calvinius sagt, die Kiste enthalte seltene Kräuter und spezielle Erntewerkzeuge. Seine Aufregung und sein Versprecher bei ihrer Rückgabe deuten darauf hin, dass die Werkzeuge einem finstereren Zweck dienen könnten.",al={"inhalt der kiste","was hat calvinius verloren"}},{q="Warum dankt Calvinius beinahe dem „Nek-“?",a="Als Calvinius seine Kiste zurückbekommt, platzt er mit „Dem Nek- sei Dank ...“ heraus, korrigiert sich dann und dankt dem Abenteurer. Er sagt nie, wem oder was er beinahe gedankt hätte.",al={"calvinius nek versprecher","dem nek sei dank bedeutung"}}},fx={["7a42047e"]={q="Was ist Calvinius' Kiste?",a="Es ist ein hölzerner Vorratsbehälter, der Calvinius gehört, dem Einsiedler, der in einer verfallenen Hütte entlang der nördlichen Straße des Dämmerwalds wohnt. Calvinius behauptet, die Kiste enthalte seltene geerntete Kräuter und empfindliche Werkzeuge, die für sein einsames Handwerk unverzichtbar seien, obwohl sein exzentrisches Verhalten und ein geheimnisvoller Versprecher darauf hindeuten, dass er ihren Inhalt für weitaus dunklere Zwecke schätzt.",al={"kiste von calvinius","was ist die kiste","calvinius' kiste"}},c6e454ed={q="Warum möchte Calvinius, dass seine Kiste zurückgeholt wird?",a="Calvinius wurde beim Kräutersammeln von Ogern aus den südlichen Hügeln überfallen und war gezwungen, seine Vorräte zurückzulassen, um zu entkommen. Er vermisst seine Ausrüstung schmerzlich und behauptet, er könne seine Kräuterforschung ohne sie nicht wieder aufnehmen, und verspricht, dass das Zurückholen der Kiste glückliche, produktive Arbeitsnächte garantiert.",al={"warum calvinius' kiste zurückholen","warum möchte calvinius die kiste","warum die kiste wollen"}}},fp="19,149,17.291.0,17.231.1,27.107.0,28.158.0,25.181.1,45.170.1"}
P.entries["item:acceptable-basilisk-sample"] = {n="Acceptable Basilisk Sample"}
P.entries["item:acceptable-hyena-sample"] = {n="Acceptable Hyena Sample",s="Eine brauchbare Hyänenprobe besteht aus Daten, die mit Chefingenieur Bilgewhizzles Feldtestkit in Tanaris gesammelt wurden. Sie ist Teil seiner Erhebung zur Tierwelt der Wüste.",h="Eine brauchbare Hyänenprobe besteht aus Daten, die mit Chefingenieur Bilgewhizzles Feldtestkit in Tanaris...",kw={"brauchbare hyänenprobe","chefingenieur bilgewhizzle","feldprobenahme","feldtestkit","gadgetzan","hyäne","tanaris"},sec={{t="Wüstenproben",b="In Tanaris kann das Feldtestkit aus einer ungetesteten Hyänenprobe eine brauchbare Probe gewinnen. Chefingenieur Bilgewhizzle benötigt für seine Erhebung acht Hyänenproben sowie Proben von Basilisken und Skorpionen. Die Energiequelle des Kits gibt Euch zwei Stunden, um die Daten zu sammeln, bevor sie verloren gehen."}},faq={{q="Was ist eine brauchbare Hyänenprobe?",a="Eine brauchbare Hyänenprobe besteht aus Daten, die mit Bilgewhizzles Feldtestkit aus einer ungetesteten Hyänenprobe gesammelt wurden.",al={"hyänenprobe","brauchbare hyänenprobe"}},{q="Wer benötigt Hyänenproben?",a="Chefingenieur Bilgewhizzle in Gadgetzan benötigt acht brauchbare Hyänenproben für seine Felderhebung in Tanaris.",al={"wer hyänenproben benötigt","bilgewhizzle probe"}},{q="Wie viele Hyänenproben benötigt Bilgewhizzle?",a="Bilgewhizzle benötigt acht brauchbare Hyänenproben sowie jeweils acht Proben von Basilisken und Skorpionen.",al={"anzahl hyänenproben","wie viele proben"}},{q="Warum gibt es ein Zeitlimit?",a="Die Energiequelle des Feldtestkits gibt Euch zwei Stunden, um die Daten zu sammeln. Wenn sie aufgebraucht ist, gehen die darin gespeicherten Daten verloren.",al={"energielimit des kits","daten verloren"}}},fp="23,167,14.294.0,35.114.0,24.107.0,46.102.0,26.120.0"}
P.entries["item:acceptable-scorpid-sample"] = {n="Acceptable Scorpid Sample",s="Eine brauchbare Skorpidprobe enthält Daten, die mit dem Field Testing Kit in Tanaris gesammelt wurden. Chefingenieur Bilgewhizzle benötigt sie für seine Feldstudie zusammen mit den anderen Proben.",h="Eine brauchbare Skorpidprobe enthält Daten, die mit dem Field Testing Kit in Tanaris gesammelt wurden.",kw={"brauchbare skorpidprobe","bilgewhizzle","field testing kit","gadgetzan","probe","skorpid","skorpion","tanaris"},sec={{t="Daten aus der Wüste",b="Das Field Testing Kit sammelt in Tanaris Skorpiddaten für Chefingenieur Bilgewhizzle aus Gadgetzan. Eine brauchbare Probe ist eine der Datenarten, die er neben Basilisken- und Hyänenproben benötigt. Sobald die Sammlung abgeschlossen ist, bringt Ihr das Kit zu Bilgewhizzle zurück, damit er seine Energiequelle entfernen kann."}},faq={{q="Was ist eine brauchbare Skorpidprobe?",a="Eine brauchbare Skorpidprobe enthält Daten, die in Tanaris mit dem Field Testing Kit von einem Skorpid gesammelt wurden.",al={"skorpidprobe","brauchbarer skorpid","skorpiddaten"}},{q="Wer benötigt die Skorpidproben?",a="Chefingenieur Bilgewhizzle in Gadgetzan benötigt die Skorpidproben zusammen mit Basilisken- und Hyänenproben.",al={"wer will proben","bilgewhizzle-proben","wer benötigt skorpiddaten"}},{q="Wofür wird die Probe verwendet?",a="Die Probe liefert Daten für Chefingenieur Bilgewhizzles Feldstudie in Tanaris.",al={"warum skorpide beproben","skorpidtests","wofür sind die daten"}},{q="Was geschieht nach der Probenentnahme mit dem Kit?",a="Bringt das Field Testing Kit zu Chefingenieur Bilgewhizzle nach Gadgetzan zurück, damit er seine Energiequelle entfernen kann.",al={"kit zurückbringen","energiequelle des kits","was mit dem testkit tun"}}},fp="25,163,11.289.0,37.99.0,30.106.0,28.82.0,39.111.0"}
P.entries["item:admiral-proudmoore-s-orders"] = {n="Admiral Prachtmeers Befehle",s="Truppen von Kul Tiras halten noch immer die Küste Durotars und folgen Admiral Prachtmeers Befehlen. Die vor Daelin Prachtmeers Tod bei Theramore verfassten Dokumente beschreiben einen Feldzug gegen die Horde.",h="Truppen von Kul Tiras halten noch immer die Küste Durotars und folgen Admiral Prachtmeers Befehlen.",kw={"benedict","durotar","kul tiras","nazgrel","befehle","orgrimmar","prachtmeer","tiragarde"},ang={["faction:Horde"]="Für die Horde stützen diese Dokumente jene, die behaupteten, dass Waffenruhen mit Menschen nicht von Dauer sein würden. Sie zeigen, dass die Truppen von Kul Tiras vom Augenblick ihrer Landung an einen Vernichtungskrieg beabsichtigten.",["race:Troll"]="Als Troll der Dunkelspeer zeigen Euch diese Befehle, dass die Menschen an der Küste, wo Euer Volk seine Heimat hat, weiterhin eine unmittelbare Gefahr darstellen."},sec={{t="Ein Erbe des Hasses",b="In Burg Tiragarde wollen die Truppen von Kul Tiras noch immer kämpfen. Die Garnison von Lieutenant Benedict verwahrt Dokumente mit ausführlichen Plänen für langfristige Manöver und Befestigungen gegen die Horde. Daelin Prachtmeers Offensive in Durotar war ein organisierter Feldzug, der nach seinem Tod fortgesetzt werden sollte. Für die Horde offenbaren diese Dokumente Operationen von Kul Tiras und mögliche Verstärkungen entlang ihrer Grenzen."},{t="Überbringung nach Grommash Hold",b="Späher der Horde tragen die sichergestellten Befehle nach Grommash Hold in Orgrimmar. Sie bringen sie zu Nazgrel in Thralls Gemach. Die Pläne stützen Nazgrels Warnung, dass Menschen nicht zu trauen ist und sie weiterhin eine akute Gefahr darstellen. Die Anführer der Horde haben nun Grund, sich auf weitere Angriffe entlang der Küste vorzubereiten."}},faq={{q="Was sind Admiral Prachtmeers Befehle?",a="Admiral Prachtmeers Befehle sind militärische Anweisungen, die Daelin Prachtmeer verfasste, bevor er bei Theramore fiel. Sie weisen die verbliebenen Soldaten von Kul Tiras in Durotar an, Küstenstellungen zu befestigen und Krieg gegen die Horde zu führen.",al={"prachtmeers befehle","was sind die befehle","admiralsbefehle gegenstand"}},{q="Wo wurden diese Befehle sichergestellt?",a="Die Befehle wurden in Burg Tiragarde in Durotar sichergestellt, während des Kampfes gegen die Truppen von Kul Tiras nahe der südöstlichen Küste.",al={"wo die befehle finden","fundort der befehle","wer lässt die befehle fallen"}},{q="Wer muss diese Befehle sehen?",a="Nazgrel muss die Befehle sehen. Er berät Kriegshäuptling Thrall in Grommash Hold in Orgrimmars Valley of Wisdom.",al={"bei wem abgeben","wer will die befehle","befehle abgeben"}},{q="Warum kämpfen Soldaten von Kul Tiras noch immer in Durotar?",a="Soldaten von Kul Tiras bleiben in Durotar, weil Lieutenant Benedict und andere Admiral Prachtmeers Auftrag zur Ausrottung der Orcs treu blieben. Seine Befehle gaben der Garnison Pläne, Durotar auch ohne seine direkte Aufsicht weiter zuzusetzen.",al={"warum sind menschen in durotar","warum ist burg tiragarde feindlich","daelin tot warum weiterkämpfen"}}},fp="27,190,18.376.0,25.288.1,37.223.0,34.129.0,30.114.0,53.238.0"}
P.entries["item:ados-fragment"] = {n="Adosfragment",s="In Whelgars Ausgrabungsstätte liegt das Adosfragment unter drei verlorenen Stücken des Goazsteins. Die vier Splitter bilden zusammen ein uraltes Relikt mit eingemeißelten Titaneninschriften.",h="In Whelgars Ausgrabungsstätte liegt das Adosfragment unter drei verlorenen Stücken des Goazsteins.",kw={"adosfragment","ausgrabung","goazstein","alte götter","relikt","titanen","sumpfland","whelgar"},ang={["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Explorer's League Titanenrelikte wie das Adosfragment sucht, um die Ursprünge Eures Volkes und seiner uralten Schöpfer aufzudecken."},sec={{t="Ein Stück des Goazsteins",b="Das Adosfragment ist eines von vier Stücken, die Ausgrabungsleiter Whelgar braucht, um den Goazstein in Whelgars Ausgrabungsstätte wiederherzustellen. Bevor Raptoren die Ausgrabungsstätte überrannten, begann Whelgar, die Haupttafel zu übersetzen. Ihre Inschriften brachen an entscheidenden Stellen ab. Die vier Stücke heißen Ados, Modr, Golm und Neru. Sie gingen über die Ruinen verstreut in uralten Behältern und Erdhaufen verloren, zwischen umherstreifenden Bestien."},{t="Die Titanenschrift",b="Ausgrabungsleiter Whelgar kann die vollständige, in den Goazstein gemeißelte Titanenschrift lesen, sobald er das Adosfragment mit den anderen drei Stücken zusammenfügt. Der vollständige Text spricht von einem großen göttlichen Plan und einer verhängnisvollen Prophezeiung. Dann verkündet er: „Alte Götter ... unter dem Land gekettet.“ Die Worte offenbaren, dass die Titanen vor langen Zeitaltern urzeitliche Wesen unter Azeroth gefangen setzten."}},faq={{q="Was ist das Adosfragment?",a="Das Adosfragment ist ein Bruchstück des uralten Goazsteins, das in Whelgars Ausgrabungsstätte im Sumpfland gefunden wurde. Seine eingemeißelte Schrift stammt von den Titanen, die die Welt formten.",al={"adosfragment","was ist ados","goazstein fragment ados"}},{q="Wo ist das Fragment zu finden?",a="Das Adosfragment liegt im Gebiet von Whelgars Ausgrabungsstätte, östlich vom Hafen von Menethil im Sumpfland. Es befindet sich meist in uralten Relikten oder lockeren Erdstellen, nahe bei Raptoren, die ihr Revier verteidigen.",al={"wo ist das adosfragment","ados fundort","ados finden"}},{q="Was steht auf dem Fragment?",a="Die Inschrift des Adosfragments ist für sich allein unvollständig. Ausgrabungsleiter Whelgar braucht die Fragmente Modr, Golm und Neru, um die Übersetzung der Tafel fortzusetzen.",al={"adosfragment text","was steht auf ados","goazstein übersetzung"}},{q="Wer sucht dieses Fragment?",a="Ausgrabungsleiter Whelgar sucht das Adosfragment, um die Übersetzung des Goazsteins abzuschließen. Er ist ein Zwerg der Explorer's League und beaufsichtigt die verwüstete Ausgrabungsstätte.",al={"wer braucht das adosfragment","adosfragment abgeben","whelgar ados"}}},fx={f3ac27ac={q="Woher stammt das Adosfragment und wer hat es erschaffen?",a="Das Adosfragment ist ein zerbrochenes Stück des Goazsteins, eines uralten Relikts, das an der Ausgrabungsstätte im Sumpfland entdeckt wurde. Es wurde von den Titanen mit ihrer geheimnisvollen Schrift versehen, bevor es inmitten der Ruinen in vier einzelne Teile zerbrach.",al={"herkunft des adosfragments","wer hat das adosfragment erschaffen","woher stammt das adosfragment"}}},fp="13,165,25.386.0,16.361.1,26.162.0,28.180.0,27.149.1,24.148.0"}
P.entries["item:agamand-family-axe"] = {n="Axt der Familie Agamand",s="In Agamands Mühlen zählt die alte Axt der Familie zu den Waffen, die Coleman Heller sucht. Einst gehörte sie wohlhabenden Mühlenbesitzern, nun soll sie ihm helfen, den untoten Agamands ihre verbliebene Würde zu nehmen.",h="In Agamands Mühlen zählt die alte Axt der Familie zu den Waffen, die Coleman Heller sucht.",kw={"agamand","gruft der familie agamand","axt der familie agamand","agamands mühlen","coleman heller","erbstück","tirisfal"},ang={["class:Warrior"]="Als Krieger könnt Ihr an den Waffen in der Gruft die kriegerischen Traditionen des Geschlechts Agamand erkennen, neben seinem Reichtum und seinen Getreidevorräten.",["race:Undead"]="Für die Verlassenen begleicht der Raub der Erbstücke der Agamands eine offene Rechnung mit Lordaerons ehemaligem Adel, der ebenfalls der Seuche erlag."},sec={{t="Eine Waffe der Agamands",b="Vor dem Dritten Krieg besaß die Agamand-Dynastie Ländereien in den nördlichen Hügeln von Tirisfal. Gewaltige Mühlen und eine Familiengruft prägten ihr Anwesen. Die Axt der Familie Agamand ruhte bei den Waffen der Ahnen, neben den bestatteten Patriarchen und Kriegern. Die Geißel überrannte das Anwesen und schlachtete seine Bewohner ab, doch die Waffen blieben auf unterirdischen Waffenständern."},{t="Gehässige Wiedergutmachung",b="Die Geißel erweckte die gefallenen Agamands als geistlose Knechte des Lichkönigs. Ihr ehemaliger Diener Coleman Heller überlebte im Untod, voller Groll gegen seine alten Herren. Er gibt der Familie die Schuld an seinem eigenen Tod und schickt deshalb Wanderer der Verlassenen in die Gruft, um Axt, Schwert, Streitkolben und Dolch von den Waffenständern zu nehmen. Heller will jede letzte Spur des Erbes der Agamands auslöschen."}},faq={{q="Wo befindet sich die Axt der Familie Agamand?",a="Die Axt liegt auf einem Waffenständer in der Gruft der Familie Agamand, am Nordrand von Agamands Mühlen im nördlichen Tirisfal.",al={"fundort der axt","wo ist die axt","agamand axt fundort"}},{q="Wer will die Axt der Familie Agamand haben?",a="Coleman Heller, ein Verlassener in Brill, sucht die Axt sowie Dolch, Streitkolben und Schwert der Familie. Er will seinen ehemaligen Herren ihre Ehre nehmen.",al={"wer braucht die axt","coleman heller quest","wer will agamand heirlooms"}},{q="Warum hasst Coleman Heller die Familie Agamand?",a="Die Agamands beschäftigten Heller zu Lebzeiten, und er gibt ihnen die Schuld an seinem Tod. Er rächt sich, indem er ihre Gruft plündert, während sie als untote Schergen auf dem Anwesen umherstreifen.",al={"warum will heller die erbstücke","coleman heller vorgeschichte","hellers groll"}},{q="Ist die Axt der Familie Agamand eine benutzbare Waffe?",a="Nein. Die Axt ist ein Relikt der Ahnen, das als Beweis für die Schändung der Familiengruft geborgen wird.",al={"ist die axt anlegbar","werte der axt"}}},fx={e4f67fe3={q="Was ist die Axt der Familie Agamand?",a="Die Axt der Familie Agamand ist eine Erbwaffe, die der angesehenen Dynastie Agamand aus Tirisfal gehörte. Sie wurde zusammen mit anderen geschätzten Waffen in ihrer Familiengruft aufbewahrt und repräsentiert das kriegerische Erbe und die Hinterlassenschaft der Sippe aus den Tagen, bevor die Geißel über Lordaeron hinwegfegte und die lebende Familie in willenlose untote Sklaven verwandelte.",al={"axt von agamand","was ist die axt der familie agamand","erbaxt der familie agamand"}}},fp="18,202,24.350.0,20.373.0,40.130.0,33.154.0,50.162.0,42.92.0"}
P.entries["item:agamand-family-dagger"] = {n="Dolch der Familie Agamand",s="Im Norden Tirisfals sucht Coleman Heller den Dolch der Familie Agamand und die anderen Waffen des Hauses. Er will seinen einstigen Herren ihr Erbe und ihre Ehre rauben.",h="Im Norden Tirisfals sucht Coleman Heller den Dolch der Familie Agamand und die anderen Waffen des Hauses.",kw={"agamand","agamands mühlen","coleman heller","gruft","dolch","erbstück","geißel","tirisfal"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie Diebstahl zu kalter Rache werden kann, wenn Ihr an auferstandenen Toten vorbeischleicht und Klingen von den Waffenständern der Gruft nehmt.",["race:Undead"]="Als Untoter kennt Ihr die bittere Kluft zwischen den Verlassenen, die in Lordaeron überlebt haben, und ihren einstigen Herren, die nun zum willenlosen Dienst in der Geißel gezwungen sind."},sec={{t="Ein Erbe in der Gruft",b="Vor dem Dritten Krieg besaß die Familie Agamand weitläufige Ländereien und Getreidemühlen im Norden Tirisfals. Die Geißel brach ihre Macht, doch ihre Waffen blieben in der Familiengruft nördlich von Agamands Mühlen. Ruhelose Angehörige des Hauses und willenlose Diener des Lichkönigs bewachen den Dolch. Er erinnert an das kriegerische Erbe und den Rang, den die Familie einst über ihren Dienern und Pächtern einnahm."},{t="Eine gehässige Forderung",b="Coleman Heller lebt in Brill, doch er starb im Dienst der Agamands. Er gibt der Familie die Schuld an seinem Tod, daher bedeutet der Dolch für ihn Groll statt edler Abstammung. Heller schickt Abenteurer in die Gruft der Familie Agamand, um Dolch, Schwert, Axt und Streitkolben zu holen. Er will den Patriarchen der Geißel ihre letzte Würde rauben und den Namen Agamand auslöschen."}},faq={{q="Was ist der Dolch der Familie Agamand?",a="Diese Waffe der Ahnen gehörte der wohlhabenden Familie Agamand aus Tirisfal. Sie wurde mit ihren anderen Waffen in der Familiengruft niedergelegt, die nun unter der Kontrolle der Geißel steht.",al={"agamand dolch","was ist der agamand dolch","familiendolch tirisfal"}},{q="Wo ist der Dolch der Familie Agamand zu finden?",a="Der Dolch liegt auf einem Agamand Weapon Rack in der Gruft der Familie Agamand, am nördlichen Ende von Agamands Mühlen in Tirisfal.",al={"wo agamand dolch finden","agamand dolch fundort","dolch waffenständer fundort"}},{q="Warum will Coleman Heller diesen Dolch?",a="Coleman Heller diente den Agamands zu Lebzeiten und gibt ihnen die Schuld an seinem Tod. Er will den Dolch und die anderen Erbstücke, um seinen einstigen Herren ihre Ehre zu rauben und ihren Untergang zu vollenden.",al={"warum will heller den dolch","heller agamand quest","warum agamand gruft ausrauben"}},{q="Welche anderen Waffen gehören zu diesen Erbstücken?",a="Dazu gehören auch das Schwert der Familie Agamand, die Axt der Familie Agamand und der Streitkolben der Familie Agamand. Alle liegen zwischen Waffenständern in der Familiengruft.",al={"andere agamand erbstücke","agamand waffenliste","was liegt sonst in der gruft"}}},fp="21,168,21.394.0,22.355.0,34.156.0,41.132.0,43.185.0,47.148.0"}
P.entries["item:agamand-family-mace"] = {n="Streitkolben der Familie Agamand",s="In Agamands Mühlen bleibt der Streitkolben der Familie Agamand in der Familiengruft eingeschlossen. Einst war er das Erbstück einer stolzen Familie im Norden Lordaerons, nun sucht ihr ehemaliger Diener Coleman Heller nach ihm.",h="In Agamands Mühlen bleibt der Streitkolben der Familie Agamand in der Familiengruft eingeschlossen.",kw={"gruft der familie agamand","streitkolben der familie agamand","agamand heirlooms","agamands mühlen","coleman heller","tirisfal"},ang={["race:Undead"]="Als Verlassener wisst Ihr, wie ein Groll aus Lebzeiten einen der Euren dazu treiben kann, eine alte Rechnung zu begleichen."},sec={{t="Ein Erbe in Trümmern",b="Vor dem Dritten Krieg besaßen die Agamands weitläufige Ackerflächen und Windmühlen im Norden Tirisfals. Wie die anderen Adligen der Region fielen sie der Seuche des Untodes zum Opfer. Die Geißel erweckte sie als geistlose Knechte im Dienste des Lichkönigs, und nun durchstreifen sie ihr verwüstetes Anwesen. Ihre uralten Schätze bleiben in der Familiengruft eingeschlossen. Darunter liegt der Streitkolben der Familie Agamand, ein Überbleibsel eines zu Fall gebrachten Geschlechts."},{t="Die Rache eines Dieners",b="Coleman Heller sucht den Streitkolben und drei weitere Waffenerbstücke. Der ehemalige Angestellte der Agamands gibt der Familie die Schuld an seinem Tod. In den Reihen der Verlassenen wiedererweckt, will Heller den geistlosen Agamands jede Spur von Würde und Ehre rauben. Er sucht neben dem Streitkolben auch ihr überliefertes Schwert, ihre Axt und ihren Dolch, in der Hoffnung, die Erinnerung und den Stolz seiner ehemaligen Herren aus den Ländern zu tilgen, die sie einst beherrschten."}},faq={{q="Wo befindet sich der Streitkolben der Familie Agamand?",a="Der Streitkolben liegt auf einem Waffenständer in der Gruft der Familie Agamand, am äußersten Nordende von Agamands Mühlen in Tirisfal.",al={"wo ist der streitkolben","fundort des streitkolbens der familie agamand","streitkolben der familie agamand finden"}},{q="Wer will den Streitkolben der Familie Agamand haben?",a="Coleman Heller, ein in Brill lebender Verlassener, verlangt den Streitkolben und die anderen Erbstücke der Familie, um eine alte Rechnung mit seinen ehemaligen Herren zu begleichen.",al={"wer braucht den streitkolben","wer nimmt den streitkolben der familie agamand","coleman heller erbstück"}},{q="Warum will Coleman Heller die Erbstücke stehlen lassen?",a="Heller diente den Agamands zu Lebzeiten und gibt ihnen die Schuld an seinem Tod. Indem er ihre kostbaren Waffen aus der Gruft nimmt, will er die letzten Spuren ihrer Familienehre tilgen.",al={"warum die erbstücke stehlen","coleman hellers beweggrund","warum die agamands hassen"}},{q="Was ist mit der Familie Agamand geschehen?",a="Die Familie Agamand herrschte über die wohlhabenden Agamands Mühlen im Norden Lordaerons, bis die Seuche zuschlug. Ihre wiedererweckten Leichen durchstreifen nun das Anwesen und die Gruften als geistlose Knechte der Geißel.",al={"wer waren die agamands","was geschah mit den agamands","geschichte der agamands"}}},fx={["0ef93592"]={q="Was ist der Streitkolben der Familie Agamand?",a="Der Streitkolben der Familie Agamand ist ein uraltes Erbstück der einst wohlhabenden Familie Agamand aus Tirisfal. Diese Waffe wurde zusammen mit ihren anderen kriegerischen Schätzen in der Familiengruft aufbewahrt und stellt ein bleibendes Überbleibsel des früheren Ansehens und der Ehre der Sippe dar, bevor die Familie der Geißel zum Opfer fiel.",al={"streitkolben von agamand","was ist der streitkolben der familie agamand","erbstück streitkolben der familie agamand"}}},fp="19,196,16.422.0,21.393.1,41.125.0,34.141.0,52.171.0,36.194.0"}
P.entries["item:agamand-family-sword"] = {n="Schwert der Familie Agamand",s="Im nördlichen Tirisfal ruht das Schwert der Familie Agamand noch immer in der Familiengruft. Die angelaufene Klinge zeugte einst vom Reichtum und Ansehen der Dynastie der Mühlenbesitzer. Coleman Heller sucht sie nun, um ihr Vermächtnis auszulöschen.",h="Im nördlichen Tirisfal ruht das Schwert der Familie Agamand noch immer in der Familiengruft.",kw={"agamand","gruft","heller","erbstück","mühlen","geißel","schwert","tirisfal"},ang={["class:Warrior"]="Als Krieger seht Ihr eine Klinge, einst als Sinnbild von Lordaerons Adel blank poliert, nun in einem entweihten Grab vernachlässigt und von zerbrochenem Kriegerstolz gezeichnet.",["race:Undead"]="Als Verlassene holt Ihr Euch Artefakte von Tirisfals einstigem Adel zurück, um mit einer lebendigen Vergangenheit abzurechnen, die Euch nicht beschützt hat."},sec={{t="Ein Vermächtnis im Grab",b="Die Agamands besaßen einst durch ihre Mühlen im nördlichen Tirisfal Reichtum und Einfluss. Als die Geißel über Lordaeron hinwegfegte, fand die Familie ein grausames Ende. Ihre Leiber erhoben sich als geistlose Knechte des Lichkönigs.\n\nIhre Ahnenwaffen, darunter das zeremonielle Schwert, wurden in der Gruft der Familie Agamand am nördlichen Rand der Mühlen eingeschlossen. Die Klingen aus ihren Waffengestellen in der Gruft zu nehmen, soll die Erinnerung an das gefallene Haus und dessen adliges Ansehen zerstören."},{t="Rache aus dem Grab",b="Coleman Heller lebt in Brill und sucht das Schwert. Er diente den Agamands zu Lebzeiten und gibt seinen einstigen Herren die Schuld an seinem Tod. Heller schickt Abenteurer aus, um das Schwert sowie Axt, Dolch und Streitkolben der Ahnen dieser Dynastie zu holen.\n\nEr will den schlurfenden Agamands ihren letzten Rest Ehre entreißen und die Würde ihrer Blutlinie auslöschen."}},faq={{q="Was ist das Schwert der Familie Agamand?",a="Das Schwert der Familie Agamand ist eine Ahnenwaffe der Agamands, einer angesehenen Adelsfamilie, die vor Lordaerons Fall die Getreidemühlen im nördlichen Tirisfal betrieb.",al={"geschichte des agamand-schwerts","was ist das schwert der familie agamand"}},{q="Wo befindet sich das Schwert?",a="Das Schwert ruht auf einem Waffengestell in der Gruft der Familie Agamand, am nördlichen Rand von Agamands Mühlen in Tirisfal. Knechte der Geißel und auferstandene Mitglieder der Blutlinie der Agamands verteidigen die Gruft.",al={"wo ist das agamand-schwert","fundort schwert agamand"}},{q="Warum will Coleman Heller dieses Schwert?",a="Coleman Heller diente der Familie Agamand zu Lebzeiten und gibt ihr die Schuld an seinem Tod. Er sucht ihre vererbten Waffen, um ihnen die verbliebene Ehre zu entreißen und die Erinnerung an ihre Dynastie auszulöschen.",al={"wer will das schwert","warum will heller die erbstücke"}},{q="Was geschah mit der Familie Agamand?",a="Die Agamands wurden während der Invasion der Geißel in Lordaeron niedergemetzelt. Ihre Toten bleiben im geistlosen Dienst des Lichkönigs gefangen und suchen das Anwesen und die Gruft ihrer Ahnen heim.",al={"wer sind die agamands","geschichte von agamands mühlen"}}},fp="20,212,20.473.0,31.337.1,33.165.0,27.200.0,42.188.0,36.178.0"}
P.entries["item:aged-gorilla-sinew"] = {n="Aged Gorilla Sinew",s="Aged Gorilla Sinew stammt von Elder Mistvale Gorillas östlich von Beutebucht im Schlingendorntal. Scharfseher Mok'thardin benötigt eine davon als magische Fessel für seine Arbeit.",h="Aged Gorilla Sinew stammt von Elder Mistvale Gorillas östlich von Beutebucht im Schlingendorntal.",kw={"aged gorilla sinew","beutebucht","elder mistvale gorilla","scharfseher mok'thardin","gorillasehne","magische fessel","nebeltal","schlingendorntal"},sec={{t="Eine magische Fessel",b="Östlich von Beutebucht suchen Elder Mistvale Gorillas im Dschungel nach Nahrung. Scharfseher Mok'thardin benötigt eine Aged Gorilla Sinew von einem von ihnen, um Federn, Klauen und einen makellosen Fangzahn an Ort und Stelle zu halten. Die Sehne muss perfekt sein, daher kann es Geduld erfordern, eine zu finden."}},faq={{q="Wo finde ich Aged Gorilla Sinew?",a="Elder Mistvale Gorillas suchen östlich von Beutebucht im Schlingendorntal nach Nahrung, und einer von ihnen könnte eine Aged Gorilla Sinew hinterlassen.",al={"aged gorilla sinew fundort","wo gorillasehne","sehne wo"}},{q="Wer benötigt die Sehne?",a="Scharfseher Mok'thardin in Grom'gol benötigt Aged Gorilla Sinew als magische Fessel.",al={"wer braucht sehne","mok'thardin sehne","was braucht scharfseher"}},{q="Wofür wird die Sehne verwendet?",a="Mok'thardin verwendet die Sehne, um Federn, Klauen und einen makellosen Fangzahn an Ort und Stelle zu halten.",al={"warum sehne","wofür aged gorilla sinew","magische fessel"}},{q="Warum muss die Sehne perfekt sein?",a="Mok'thardin benötigt eine perfekte Sehne für seine magische Fessel.",al={"warum perfekte sehne","gute sehne","warum gealtert"}}},fp="18,159,16.238.0,36.104.0,20.81.0,27.81.0,30.60.0"}
P.entries["item:aged-kodo-hide"] = {n="Aged Kodo Hide",s="Aged Kodo Hide stammt von gealterten Kodos in Desolace. Kreldig Ungor benötigt drei Häute für Reclaimers Inc. sowie Scorpashi venom.",h="Aged Kodo Hide stammt von gealterten Kodos in Desolace.",kw={"gealterter kodo","aged kodo hide","desolace","der kodofriedhof","kreldig ungor","leftwitch","reclaimers inc","scorpashi venom"},ang={["class:Mage"]="Als Magier erkennt Ihr Aged Kodo Hide vielleicht als eines der Reagenzien auf Leftwitchs Liste für Reclaimers Inc."},sec={{t="Ein Kodo-Reagenz",b="Kreldig Ungor benötigt in Desolace drei Aged Kodo Hides sowie sieben Phiolen Scorpashi venom. Die Haut muss von einem gealterten Kodo stammen; sterbende und uralte Kodos liefern dieses Reagenz nicht."}},faq={{q="Woher stammen Aged Kodo Hides?",a="Aged Kodo Hides stammen von gealterten Kodos in Desolace.",al={"quelle für aged kodo hide","woher haut","kodohaut"}},{q="Wer benötigt Aged Kodo Hide?",a="Kreldig Ungor benötigt drei Aged Kodo Hides für Reagents for Reclaimers Inc.",al={"wer braucht die haut","kreldigs reagenzien","haut für reclaimers inc"}},{q="Liefert jeder Kodo die Haut?",a="Nein. Die Haut muss von einem gealterten Kodo stammen, nicht von einem sterbenden oder uralten Kodo.",al={"welcher kodo","haut eines sterbenden kodos","haut eines uralten kodos"}},{q="Was benötigt Kreldig noch?",a="Kreldig benötigt außerdem sieben Phiolen Scorpashi Venom.",al={"weitere reagenzien","scorpashi venom","was kreldig noch braucht"}}},fp="14,129,14.187.0,35.49.0,25.74.0,31.70.0,28.50.0"}
P.entries["item:ahanu-s-leather-goods"] = {n="Ahanus Lederwaren",s="Mit Ahanus Lederwaren gelangen fertige Lederrüstungen und Vorräte von Donnerfels zum Wegekreuz. Ahanu schickt sie an Reisende im Brachland.",h="Mit Ahanus Lederwaren gelangen fertige Lederrüstungen und Vorräte von Donnerfels zum Wegekreuz.",kw={"ahanu","das wegekreuz","devrak","jahan falkenschwinge","lederwaren","tal","donnerfels","wind rider"},ang={["race:Tauren"]="Als Tauren könnt Ihr sehen, wie diese Lieferung Mulgore, die Heimat Eurer Ahnen, mit den Gebieten der Horde im Brachland verbindet."},sec={{t="Handel zwischen den Hochebenen",b="Ahanu bereitet in Donnerfels Lederwaren für den Handel jenseits von Mulgore vor. Der Lederverarbeiter fertigt aus rohen Häuten Kleidung und Ausrüstung für Jahan Falkenschwinge, einen Händler am Wegekreuz im Brachland. Der Landweg durch die Ebenen ist langsam, deshalb schicken die Tauren das Paket durch die Luft. Die ausgebildeten Wind Rider von Tal und Devrak befördern Waren rasch über weite Strecken."}},faq={{q="Was enthalten Ahanus Lederwaren?",a="Ahanus Paket enthält fertige Lederwaren, die in Donnerfels aus rohen Häuten hergestellt wurden. Die Rüstungen und Ausrüstungsgegenstände sind bereit für den Verkauf an Reisende.",al={"was sind die lederwaren","ahanus paketinhalt","was ist im bündel"}},{q="Wer erhält dieses Paket?",a="Jahan Falkenschwinge erhält das Paket am Wegekreuz. Er verkauft fertige Waren an Jäger, Krieger und Abenteurer, die durch das zentrale Brachland reisen.",al={"wer bekommt die lederwaren","wohin geht die lieferung","jahans lederlieferung"}},{q="Warum wird dieses Paket per Wind Rider befördert?",a="Ahanu verschickt das Paket per Wind Rider, weil der Transport schwerer Handelswaren mit den Aufzügen hinab und durch das Brachland Zeit kostet. Er verweist die Kuriere an Tal, Donnerfels' Meister der Wind Rider, damit die geflügelten Boten Fracht schnell zu entfernten Posten wie dem Wegekreuz bringen können.",al={"warum das paket fliegen","wind rider lieferung donnerfels","flugmeister paket"}}},fx={["32785653"]={q="Was sind Ahanus Lederwaren?",a="Es handelt sich um ein Bündel fertiggestellter Lederwaren, die in Donnerfels hergestellt wurden. Das Paket ist für die Siedlung Das Wegekreuz im Brachland bestimmt und soll den Handel unter der wachsenden Zahl von Reisenden, die sich dort versammeln, unterstützen.",al={"was sind ahanus lederwaren","gegenstand ahanus lederwaren"}},["962e36b1"]={q="Woher stammen Ahanus Lederwaren und wer hat sie hergestellt?",a="Die Waren wurden von Ahanu zubereitet, einem Lederer, der sein Handwerk hoch oben auf den Mesas von Donnerfels ausübt. Er setzte die fertigen Waren aus Rohhäuten zusammen, die ihm aus dem Brachland geschickt wurden.",al={"wer hat ahanus lederwaren hergestellt","herkunft von ahanus lederwaren"}},["6d92aaf6"]={q="Warum möchte jemand Ahanus Lederwaren haben?",a="Jahan Falkenschwinge hat das Paket angefordert, um es an Kunden zu verkaufen, die durch das Brachland reisen. Das Wegekreuz ist zu einem geschäftigen Knotenpunkt geworden, an dem sich wandernde Jäger und Abenteurer tummeln, was eine lebhafte Nachfrage nach hochwertiger, frisch gefertigter Lederausrüstung schafft.",al={"warum ahanus lederwaren liefern","wer will ahanus lederwaren"}}},fp="21,147,22.360.0,37.138.0,25.152.0,41.276.0"}
P.entries["item:akiris-reed"] = {n="Akiris Reed",s="An den Stränden des Kap des Schlingendorntals sammeln Naga Akiris Reed, eine wertvolle Meerespflanze. Freibeuter Bloads in Beutebucht zahlt gut für Bündel davon.",h="An den Stränden des Kap des Schlingendorntals sammeln Naga Akiris Reed, eine wertvolle Meerespflanze.",kw={"akiris","akiris reed","beutebucht","kap des schlingendorntals","groy","naga","freibeuter bloads"},sec={{t="Schilf vom Ufer",b="Freibeuter Bloads in Beutebucht zahlt für Bündel Akiris Reed, das am Nordstrand gesammelt wird. Die Naga nennen das Meeresschilf akiris, und Bloads sagt, sein Freund Groy verdiene gut mit dem Verkauf. Wofür Groy das Schilf verwendet, weiß Bloads nicht; für ihn reichen zehn Halme, um ein einträgliches Geschäft zu beginnen."}},faq={{q="Was ist Akiris Reed?",a="Akiris Reed ist ein wertvolles Meeresschilf, das die Naga an den Stränden des Kap des Schlingendorntals sammeln.",al={"akiris schilf","akiris pflanze","meeresschilf"}},{q="Wer will Akiris Reed?",a="Freibeuter Bloads in Beutebucht bezahlt im Auftrag seines Freundes Groy für Bündel Akiris Reed.",al={"wer kauft akiris","akiris schilf käufer","bloads schilf"}},{q="Wofür verwendet Groy das Schilf?",a="Freibeuter Bloads sagt, er wisse nicht, wofür Groy Akiris Reed verwendet; er weiß nur, dass Groy es mit Gewinn verkauft.",al={"wofür ist akiris","groy akiris verwendung","verwendung von schilf"}},{q="Wo finde ich Akiris Reed?",a="Naga sammeln Akiris Reed an den Stränden nördlich von Beutebucht im Kap des Schlingendorntals.",al={"akiris fundort","wo schilf","naga strand"}}},fp="11,161,19.308.0,20.96.0,22.91.0,32.111.0,29.90.0"}
P.entries["item:alaric-s-remains"] = {n="Alarics sterbliche Überreste",s="Im Silberwald liegen Alarics Knochen fern der Insel Fenris, die er seine Heimat nannte. Sein Geist bittet Reisende, sie an den Gnollen der Moderfelle vorbei in Burg Fenris zu tragen.",h="Im Silberwald liegen Alarics Knochen fern der Insel Fenris, die er seine Heimat nannte.",kw={"alaric","alarics sterbliche überreste","burg fenris","moderfelle","flaches grab","silberwald","the hidden niche","thule ravenclaw"},ang={["class:Mage"]="Als Magier erkennt Ihr in Alarics enthülltem Versteck womöglich Relikte von Thule Rabenklaue und den in Dalaran ausgebildeten Arkanisten, die einst in Burg Fenris studierten und Ränke schmiedeten.",["race:Undead"]="Als Reisender der Verlassenen versteht Ihr vielleicht einen Geist, dessen Totenruhe gestört wurde. Alaric sucht friedliche Abgeschiedenheit, keinen Dienst unter der Dark Lady."},sec={{t="Eine letzte Bitte",b="Alarics Knochen wurden aus einem flachen Grab im Silberwald geborgen. Einst lebte er auf der Insel Fenris und hing sehr an diesem Ort. Nun bittet sein Geist jeden, der seine Knochen findet, seine schlecht sitzenden Stiefel zurückzulassen und seine sterblichen Überreste direkt in Burg Fenris zu tragen, außer Reichweite der Aasfresser auf dem Festland."},{t="Die Nische in der Burg",b="Alaric führt den Träger zum südwestlichen Turm von Burg Fenris, vorbei an den verseuchten unteren Bereichen in eine ruhige Kammer. Hinter einem staubigen Regal birgt eine verborgene Nische ein Artefakt, das Thule Rabenklaue und seine Magierkollegen einst schätzten. Als Gegenleistung für eine ungestörte Ruhestätte fern der Gnolle der Moderfelle schenkt Alaric jenen, die seine Knochen heimtragen, die verborgenen Schmuckstücke."}},faq={{q="Wer war Alaric?",a="Alaric lebte einst in Burg Fenris und hielt jene Zeit für die schönste seines Lebens. Nach seinem Tod wurde er in einem flachen Grab im Silberwald beigesetzt. Nun bittet sein Geist einen Vorübergehenden, seine Knochen heimzutragen.",al={"wer ist alaric","alarics geschichte","wer war dieser kerl"}},{q="Wohin sollen Alarics sterbliche Überreste gebracht werden?",a="Alarics sterbliche Überreste gehören in eine verborgene Nische hinter einem staubigen Regal im südwestlichen Turm von Burg Fenris auf der Insel Fenris.",al={"wohin alaric bringen","standort des staubigen regals","wo ist die nische"}},{q="Warum möchte Alaric seine sterblichen Überreste hinter einem Regal einschließen lassen?",a="Burg Fenris spendete Alaric zu Lebzeiten Trost, und er möchte innerhalb ihrer Steinmauern ruhen statt in einem Erdgraben. Außerdem möchte er die Nische verschließen lassen, um seine Knochen vor den Gnollen der Moderfelle zu schützen, die durch die Burg streifen.",al={"warum burg fenris","warum die nische","warum den leichnam verstecken"}},{q="Warum sollten seine Stiefel zurückbleiben?",a="Alaric sagte, seine Stiefel hätten ihm zu Lebzeiten nie gepasst, weshalb er darum bat, sie zurückzulassen, wenn seine Knochen aus dem flachen Grab getragen würden.",al={"die stiefel zurücklassen","alarics stiefel","stiefel passten nie"}},{q="Was birgt die verborgene Nische außer einer Ruhestätte?",a="Die verborgene Nische birgt einen Gegenstand, den Thule Rabenklaue und seine früheren Gefährten einst schätzten, sowie magische Besitztümer, die Alaric jedem schenkt, der seine sterblichen Überreste zur Ruhe bettet.",al={"schatz in der verborgenen nische","was ist hinter dem regal","thules gegenstand"}}},fx={["7c652925"]={q="Was sind Alarics sterbliche Überreste?",a="Dies sind die physischen Knochen und körperlichen Überreste von Alaric, einem ehemaligen Bewohner von Burg Fenris, der starb und hastig im Silberwald beerdigt wurde. Sein verweilender Geist behält das Bewusstsein in seinen Knochen und drängt Reisende dazu, ihn aus der Erde zu bergen, damit er eine letzte, friedliche Ruhestätte finden kann.",al={"was sind alarics sterbliche überreste","alarics leiche","gegenstand alarics sterbliche überreste"}},["6447c1c8"]={q="Woher stammen Alarics sterbliche Überreste?",a="Ihr grabt sie aus einem einfachen, flachen Grab in der Wildnis des Silberwalds aus, abzüglich der schlecht passenden Stiefel, mit denen er beerdigt wurde. Alaric kam in der Wildnis weit weg von seinem früheren Zuhause ums Leben, wodurch seine ungeweihten Überreste in der Erde gefangen blieben, bis jemand sie ausgrub.",al={"wo ist alaric gestorben","alarics flaches grab","wer hat alarics sterbliche überreste erschaffen"}},["5f3dd52d"]={q="Warum möchte Alaric, dass seine sterblichen Überreste geborgen werden?",a="Alaric verbrachte die glücklichsten Jahre seines Lebens in Burg Fenris, und die Ruhe in der Wildnis bringt ihm keinen Frieden. Er möchte, dass seine Überreste zurück zur Burg gebracht und sicher in einer versteckten Nische hinter einem staubigen Bücherregal untergebracht werden, geschützt vor den aasfressenden Rot Hide-Gnollen, die das Gelände verseuchen.",al={"warum alarics sterbliche überreste mitnehmen","warum möchte alaric seinen körper verlegen","warum alaric verlegen"}}},fp="16,168,15.298.0,22.360.1,15.210.0,42.123.0,55.211.0,41.133.0,57.177.0"}
P.entries["item:alien-egg"] = {n="Fremdartiges Ei",s="Windschlangen bewachen ein fremdes Gelege in Tausend Nadeln, und Taurenspäher am Freiwindposten wollen wissen, warum.",h="Windschlangen bewachen ein fremdes Gelege in Tausend Nadeln, und Taurenspäher am Freiwindposten wollen...",kw={"fremdartiges ei","freiwindposten","hagar blitzhuf","tausend nadeln","windschlange"},ang={["class:Hunter"]="Als Jäger wisst Ihr, dass Windschlangen zu den am meisten verehrten Wildtieren der Ödnis Kalimdors gehören. Eines ihrer seltensten und am strengsten bewachten Gelege aufzuspüren, stellt Eure Instinkte auf die Probe.",["race:Tauren"]="Als Tauren wacht Ihr vom Freiwindposten aus über die Schlucht. Unbekannte Kreaturen können wie ein Omen wirken oder wie eine unmittelbare Bedrohung für Eure gefährlich gelegene Heimat an den Klippen."},sec={{t="Die Brut einer Schlange",b="Das Fremdartige Ei liegt am Fuß der Felsnadeln südlich und nordöstlich vom Freiwindposten. Heimische Windschlangen bewachen es neben ihren eigenen Nestern, obwohl ein solches Gelege inmitten des Lebens am Grund der Schlucht ungewöhnlich ist. Hagar Blitzhuf, ein Taurenkrieger, der vom Freiwindposten aus Wache hält, will es bergen. Er hofft herauszufinden, ob es die Siedlungen auf den Tafelbergen bedroht oder nur ein ungewöhnliches heimisches Reptil ist."},{t="Die Brut Arikaras",b="Am Freiwindposten öffnet sich das Fremdartige Ei bei näherer Untersuchung. Arikara, die rote Windschlange aus den Legenden der Tauren, schlüpft aus der Schale. Die Tauren glauben, dass Arikara ein Geist der Rache ist. Die junge Schlange erhebt sich in die Luft, und ein erschütterter Hagar verkündet, dass die Rache nach Tausend Nadeln gekommen ist. Die örtlichen Verteidiger brechen auf, um sich ihr entgegenzustellen."}},faq={{q="Warum wird das Ei als „fremdartig“ bezeichnet?",a="Die Taurenspäher nennen das Fremdartige Ei fremdartig, weil es ihnen völlig fremd und unbekannt ist. Seine Farben und Muster unterscheiden sich von gewöhnlichen Windschlangengelegen in Tausend Nadeln.",al={"fremdartiges ei name","warum fremdartig","stammt es aus dem weltraum"}},{q="Wo ist das Fremdartige Ei zu finden?",a="Das Fremdartige Ei liegt am Grund der Schlucht nahe den Wänden der Tafelberge südlich und nordöstlich vom Freiwindposten in Tausend Nadeln. Feindselige Windschlangen umringen und bewachen es.",al={"ei fundort","wo ist das fremdartige ei","fremdartiges ei finden"}},{q="Warum bewachen die einheimischen Schlangen das Ei?",a="Niemand weiß, warum die heimischen Schlangen das Fremdartige Ei bewachen. Sie beschützen es, als wäre es ihr eigenes, und wer es gesehen hat, ist nicht nahe genug herangekommen, um es zu untersuchen.",al={"warum beschützen schlangen es","schlangen bewachen ei"}},{q="Was geschieht, wenn Ihr das Ei zu Hagar Blitzhuf bringt?",a="Wenn Ihr das Fremdartige Ei zu Hagar Blitzhuf am Freiwindposten bringt, schlüpft es vor seinen Augen. Was daraus hervorkommt, erschüttert Hagar so sehr, dass er sofort Rat bei Motega Feuermähne sucht.",al={"hagar ei abgeben","was schlüpft"}}},fx={["9259de71"]={q="Was ist das Fremdartige Ei?",a="Das Fremdartige Ei ist ein ungewöhnliches, geheimnisvolles Gelege, das bei den wilden Windschlangen der Tausend Nadeln gefunden wurde. Anders als die typischen Schlangeneier der Region erregte sein seltsames Aussehen die Aufmerksamkeit von Spähern und Schamanen am Freiwindposten. Trotz seiner fremdartigen Natur beschützen die lokalen Schlangen es erbittert, als wäre es ihre eigene Brut.",al={"was ist das fremdartige ei","informationen zum fremdartigen ei","über das fremdartige ei"}},e10e9f00={q="Warum möchte Hagar Blitzhuf das Fremdartige Ei haben?",a="Hagar Blitzhuf am Freiwindposten hörte Gerüchte über ein bizarres Ei, das von örtlichen Schlangen bewacht wurde, an das keiner seiner Späher nah genug herankam, um es zu untersuchen. Angetrieben von Neugier und Vorsicht bittet er tapfere Abenteurer, das Ei zu bergen, damit er es direkt untersuchen und herausfinden kann, was für eine Kreatur daraus schlüpfen könnte.",al={"warum das fremdartige ei haben wollen","warum will hagar das ei","zweck des fremdartigen eies"}}},fp="9,114,17.382.0,20.329.1,30.183.0,33.153.0,40.162.1,59.184.1"}
P.entries["item:alterac-granite"] = {n="Alteracgranit",s="Alteracgranit ist ein geschätzter, widerstandsfähiger Stein, der im bergigen Gelände des nördlichen Lordaeron abgebaut wird, insbesondere rund um Darrow Hill im Vorgebirge des Hügellands. Von Meistersteinmetzen für seine außergewöhnliche Beständigkeit und Maserung verehrt, wählt ihn König Magni Bronzebarts königlicher Steinmetz aus, um ein dauerhaftes Denkmal für gefallene Soldaten zu meißeln.",h="Alteracgranit ist ein geschätzter, widerstandsfähiger Stein, der im bergigen Gelände des nördlichen Lordaeron...",kw={"alteracgranit","darrow hill","hillsbrad","eisenschmiede","marblesten","sully balloo","thandol-übergang"},ang={["profession:Mining"]="Bergleute und Prospektoren schätzen Alteracgranit für seinen sauberen Bruch und seine außergewöhnliche Dichte, die ihn von gewöhnlichem Felsgestein abhebt.",["race:Dwarf"]="Zwergensteinmetze stellen Materialqualität über alles, was diesen robusten Gebirgsstein unverzichtbar macht, um einen Mitbürger von Eisenschmiede zu ehren."},sec={{t="Stein des Gedenkens",b="Als König Magni Bronzebart ein Denkmal zum Gedenken an Sully Balloo in Auftrag gab – einen tapferen zwergischen Verteidiger, der bei der Tragödie am Thandol-Übergang ums Leben kam –, genügte gewöhnlicher Bruchstein nicht. Großsteinmetz Marmorstein, der mit der Bildhauerei des Denkmals in Eisenschmiede betraut war, bestand darauf, Alteracgranit zu beschaffen. Bekannt als einer der feinsten Steine in den gesamten Östlichen Königreichen, gewährleistet seine legendäre Haltbarkeit, dass das Abbild und das Andenken an einen gefallenen Helden über Generationen hinweg unversehrt fortbestehen kann."},{t="Unter Gefahren gebrochen",b="Die Beschaffung von Alteracgranit ist alles andere als eine einfache Aufgabe. Der Stein lagert um Darrow Hill in den nördlichen Ausläufern des Vorgebirges des Hügellands, nahe den ruinierten Gebieten von Alterac. Da die Region von feindseligen Wildtieren, lauernden Briganten des Syndikats und schwelenden Konflikten heimgesucht wird, erfordert das Bergen unversehrter Platten dieses makellosen Steins kühne Abenteurer, die bereit sind, tief in umkämpfte Lande vorzudringen, um ihn für die Handwerker von Eisenschmiede zu sichern."}},faq={{q="Wofür wird Alteracgranit verwendet?",a="Alteracgranit wird von Großsteinmetz Marmorstein in Eisenschmiede in Auftrag gegeben, um ein königliches Denkmal zu Ehren von Sully Balloo zu meißeln, einem Zwergensoldaten, der bei der Verteidigung des Thandol-Übergangs fiel.",al={"alteracgranit verwendung","warum alteracgranit","marblesten stein"}},{q="Wo ist Alteracgranit zu finden?",a="Er wird von Steinvorkommen bei Darrow Hill gesammelt, gelegen im nördlichen Gebiet des Vorgebirges des Hügellands nahe der Grenze von Alterac.",al={"alteracgranit fundort","wo gibt es alteracgranit","darrow hill granit"}},{q="Warum verlangte Großsteinmetz Marmorstein ausdrücklich diesen Stein?",a="Großsteinmetz Marmorstein betrachtet Alteracgranit als einen der feinsten und widerstandsfähigsten Bildhauersteine überhaupt und hält ihn für das einzige Material, das eines von König Magni in Auftrag gegebenen, dauerhaften königlichen Denkmals würdig ist.",al={"warum marblesten granit will","warum alterac stein"}},{q="Wer war Sully Balloo?",a="Sully Balloo war ein Zwergensoldat, der während der Kämpfe am Thandol-Übergang starb. König Magni Bronzebart gab zu seinen Ehren ein Denkmal in Auftrag, um sein Opfer für die Allianz zu würdigen.",al={"sully balloo","wer starb am thandol-übergang"}}},fx={["9814170d"]={q="Was ist Alteracgranit?",a="Alteracgranit ist ein geschätzter, hochwertiger Bruchstein, der in den nördlichen Hügeln gefunden wird. Unter Steinmetzmeistern als einer der feinsten verfügbaren Bildhauersteine bekannt, besitzt er die Haltbarkeit und die makellose Maserung, die erforderlich sind, um epische, dauerhafte Denkmäler zu erschaffen, die königlicher Aufträge würdig sind.",al={"was ist alteracgranit","gegenstand alteracgranit","informationen zu alteracgranit"}},["842d3593"]={q="Woher stammt Alteracgranit und wer hat ihn hergestellt?",a="Alteracgranit ist ein Naturstein, der von Darrow Hill in den Ausläufern von Hillsbrad abgebaut wird, die an die zerklüfteten Berge von Alterac grenzen. Er wird von keinem Handwerker hergestellt; vielmehr wird er direkt aus dem uralten Gestein der Hügel geschlagen und wartet darauf, von geschickten Maurern in dauerhafte Werke geformt zu werden.",al={"herkunft von alteracgranit","wo wird alteracgranit abgebaut","wer hat alteracgranit hergestellt"}}},fp="15,220,18.398.0,17.299.0,33.156.0,35.124.0,60.185.0,21.172.0"}
P.entries["item:alterac-signet-ring"] = {n="Alterac Signet Ring",s="Ein Alterac Signet Ring kennzeichnet ein Mitglied des Syndikats als ehemaligen Adeligen der Bande. Magistrate Maleb in Süderstade sucht diese Ringe, um die Führung des Syndikats zu schwächen.",h="Ein Alterac Signet Ring kennzeichnet ein Mitglied des Syndikats als ehemaligen Adeligen der Bande.",kw={"alterac","alterac signet ring","magistrat maleb","adel","adeliger","süderstade","strahnbrad","syndikat"},ang={["faction:Alliance"]="Als Reisender der Allianz bittet Maleb Euch, Süderstade zu schützen, indem Ihr die Führung des Syndikats schwächt."},sec={{t="Das Zeichen eines Adeligen",b="In den Ruinen von Strahnbrad kennzeichnen Alterac Signet Rings Agenten des Syndikats, die einst zum Adel von Alterac gehörten. Magistrate Maleb in Süderstade will sie sammeln lassen. Er fürchtet, dass die Anführer des Syndikats die Stadt zugrunde richten wollen, und glaubt, dass die Bande ohne ihre Ringe nicht mehr zielgerichtet handeln kann."}},faq={{q="Was ist ein Alterac Signet Ring?",a="Ein Alterac Signet Ring wird von einem Agenten des Syndikats getragen, der zu den ehemaligen Adeligen der Bande gehört.",al={"alterac-ring","syndikatssiegel","was ist der ring"}},{q="Wer will diese Ringe?",a="Magistrate Maleb in Süderstade will die Ringe, um die Führung des Syndikats zu schwächen.",al={"wer will den ring","malebs ringe","wo siegel abgeben"}},{q="Wo finde ich die Ringe?",a="Mitglieder des Syndikats im Alteracgebirge tragen Alterac Signet Rings, und die Ruinen von Strahnbrad gelten als Hauptquartier der Bande.",al={"fundort des rings","wo sind die siegelringe","alterac-ring erhalten"}},{q="Warum will Maleb die Ringe?",a="Magistrate Maleb glaubt, dass das Syndikat ohne seine ehemaligen Adeligen nicht mehr entschlossen handeln kann.",al={"warum die ringe","malebs plan","warum siegel sammeln"}}},fp="19,179,14.310.0,31.91.0,22.84.0,27.137.0,30.110.0"}
P.entries["item:altered-snapjaw-shell"] = {n="Veränderte Schnappkieferschale",s="In der Blühenden und der Brackigen Oase tragen Schnappkiefer veränderte Panzer, die einen Druiden beunruhigen. Ihre Panzer könnten zeigen, wie sich die tiefen Spalten des Brachlands auf die örtliche Tierwelt auswirken.",h="In der Blühenden und der Brackigen Oase tragen Schnappkiefer veränderte Panzer, die einen Druiden beunruhigen.",kw={"altered beings","veränderte schnappkieferschale","brachland","die blühende oase","oasenschnappkiefer","die brackige oase","tonga runentotem"},ang={["class:Druid"]="Als Druide könnt Ihr die verformten Panzer der Oasentiere untersuchen, um das verborgene Ungleichgewicht aufzuspüren, das die Gewässer des Brachlands stört."},sec={{t="Zeichen der Verderbnis",b="Oasenschnappkiefer haben sich auf eine Weise verändert, die jene beunruhigt, die das Land erforschen. Man glaubt, dass die Süßwasserschildkröten der Blühenden und der Brackigen Oase aus Quellen trinken, die von geheimnisvollen unterirdischen Spalten gespeist werden. Ihre veränderten Panzer haben die Aufmerksamkeit von Forschern am Wegekreuz erregt.\n\nTonga Runentotem, ein Taurendruide, sammelt die Schalen, um mehr über den Zustand des Landes zu erfahren. Er will herausfinden, ob die aus der Tiefe aufsteigenden Energien eine unnatürliche Verderbnis oder etwas Seltsameres sind."}},faq={{q="Was macht diese Schildkrötenpanzer verändert?",a="Schnappkiefer leben in Quellen in der Blühenden und der Brackigen Oase, wo tiefe Spalten das Wasser speisen. Seltsame Energien haben die Geschöpfe verändert, die dort trinken, und ihre Panzer sichtbar verformt.",al={"warum sind die schalen verändert","was ist eine veränderte schnappkieferschale","schnappkieferschale mutation"}},{q="Wer will diese Schalen und warum?",a="Tonga Runentotem, ein Druide am Wegekreuz, bittet Jäger, die Schalen zu sammeln. Er glaubt, dass Veränderungen an heimischen Wildtieren zeigen könnten, welche Macht oder Verderbnis die Wasserversorgung des Brachlands beeinflusst.",al={"wer braucht veränderte schnappkieferschalen","tonga runentotem schalen","altered beings quest abgeben"}},{q="Wo sind diese Schnappkiefer zu finden?",a="Oasenschnappkiefer leben im Wasser und an den schlammigen Ufern der Blühenden und der Brackigen Oase, südlich und südöstlich des Wegekreuzes.",al={"oasenschnappkiefer fundort","wo gibt es veränderte schalen","schnappkieferschale fundorte"}}},fx={["1549c45f"]={q="Woher stammen veränderte Schnappkieferschalen?",a="Diese Panzer gehören zu den Oasenschnappkiefern, die um die Süßwasserquellen des Brachlands leben, insbesondere an der Üppigen Oase und der Stagnierenden Oase. Anstatt normale Schildkrötenpanzer zu sein, rührt ihr seltsamer Zustand daher, dass sie Wasser getrunken haben, das durch geheimnisvolle Spalten unter den Oasen verunreinigt oder gestärkt wurde, was die dort lebenden Kreaturen physisch mutieren ließ.",al={"woher stammen veränderte schnappkieferschalen","quelle der veränderten schnappkieferschalen","wer hat veränderte schnappkieferschalen hergestellt"}}},fp="21,168,19.484.0,39.199.0,31.193.0,31.128.0"}
P.entries["item:ambassador-infernus-bracer"] = {n="Botschafter Infernus' Armschienen",s="Im Ödland bittet Euch Berater Belgrum, ein Zeichen für die Niederlage von Botschafter Infernus zurückzubringen. Er hofft, der gefährdeten Ausgrabungsstätte in Uldaman Hilfe schicken zu können.",h="Im Ödland bittet Euch Berater Belgrum, ein Zeichen für die Niederlage von Botschafter Infernus...",kw={"berater belgrum","botschafter infernus","festung angor","ödland","armschienen","infernus-armschienen","eisenschmiede","ragnaros","shadowforge","uldaman"},ang={["race:Dwarf"]="Als Zwerg tragt Ihr den Beweis für eine Bedrohung Eisenschmiedes bei Euch: Shadowforges Suche in Uldaman hat bereits Zwergenleben gekostet."},sec={{t="Beweis aus Angor",b="Berater Belgrum schickt Euch zur Festung Angor im Ödland, um Botschafter Infernus zu vernichten. Ragnaros entsandte den Botschafter, damit er Shadowforges Suche nach verlorenen Artefakten in Uldaman überwacht. Die Ausgrabung hat bereits viele Leben gekostet, und Belgrum fürchtet, diese Artefakte könnten Eisenschmiede bedrohen. Bringt die Armschienen als Beweis zurück, damit Belgrum Hilfe zur Stätte schicken kann."}},faq={{q="Was sind Botschafter Infernus' Armschienen?",a="Botschafter Infernus' Armschienen sind der Beweis für die Niederlage des Botschafters, den Ihr zu Berater Belgrum nach Eisenschmiede bringt.",al={"infernus-armschienen","botschafter-armschienen","was sind die armschienen"}},{q="Wo finde ich die Armschienen?",a="Die Armschienen erhaltet Ihr von Botschafter Infernus an der Festung Angor im Ödland.",al={"fundort der armschienen","wo ist infernus","die armschienen holen"}},{q="Wer will die Armschienen?",a="Berater Belgrum in Eisenschmiede bittet Euch, die Armschienen als Beweis für die Niederlage von Botschafter Infernus zu bringen.",al={"wer braucht die armschienen","belgrums armschienen","armschienen abgeben"}},{q="Warum ist Botschafter Infernus im Ödland?",a="Ragnaros entsandte Botschafter Infernus, damit er Shadowforges Suche nach verlorenen Artefakten in Uldaman überwacht.",al={"warum ist infernus hier","infernus im ödland","was macht er hier"}},{q="Warum will Eisenschmiede, dass der Botschafter besiegt wird?",a="Die Ausgrabung von Shadowforge hat viele Opfer gefordert, und Berater Belgrum fürchtet, die geborgenen Artefakte könnten gegen Eisenschmiede eingesetzt werden.",al={"warum infernus töten","bedrohung für eisenschmiede","was ist die gefahr"}},{q="Was geschieht, nachdem ich es Belgrum gebracht habe?",a="Belgrum dankt Euch und sagt, er werde Historiker Karnik benachrichtigen und Hilfe für die Ausgrabungsstätte im Ödland organisieren.",al={"nach den armschienen","bei belgrum abgeben","wie geht es weiter"}}},fp="27,154,16.356.0,36.110.0,27.76.0,21.98.0,43.96.0,48.137.0,41.115.1"}
P.entries["item:ambercorn"] = {n="Bernsteinkorn",s="In ganz Mulgore sammeln Tauren unter uralten Bäumen Bernsteinkorn für das Wasser der Seher, ein Gebräu für den Rite of Vision.",h="In ganz Mulgore sammeln Tauren unter uralten Bäumen Bernsteinkorn für das Wasser der Seher, ein Gebräu für...",kw={"bernsteinkorn","dorf der bluthufe","mulgore","rite of vision","taurenprüfung","wasser der seher","zarlman zwillingsmond"},ang={["class:Shaman"]="Als Schamane ehrt Ihr natürliche Katalysatoren wie Bernsteinkorn. Nach der Überlieferung der Tauren legt die Erdenmutter spirituelle Magie in die Ernte ihrer Bäume und Böden.",["race:Tauren"]="Als junger Tauren lernt Ihr, dass Bernsteinkorn eine Zutat für den Rite of the Earth Mother ist. Das Gebräu hilft, Euren spirituellen Weg zu offenbaren."},sec={{t="Gaben des Blätterdachs",b="Unter Mulgores großen Bäumen fällt Bernsteinkorn ins Gras, wo Tauren es sammeln. Tauren betrachten diese Nüsse als Träger der spirituellen Lebenskraft und der verborgenen Magie des Landes. Ihre Mystiker verstehen und nutzen diese Kraft seit Generationen. Junge Jäger und Wanderer lernen, auf den Boden unter dem Blätterdach zu achten und die Gaben der Erdenmutter zu ehren."},{t="Das Gebräu des Sehers",b="Im Dorf der Bluthufe bereitet der Seher Zarlman Zwillingsmond junge Tauren mit Bernsteinkorn auf den Rite of Vision vor. Er verbindet es mit Steinen aus den Wasserbrunnen der Ebenen, um das Wasser der Seher herzustellen. Die Initiierten trinken das zeremonielle Gebräu vor den Flammen der Ahnen. Ihre Wahrnehmung verändert sich und offenbart ein führendes Geisttier, das sie zu ihrem nächsten Ziel geleiten soll."}},faq={{q="Was ist ein Bernsteinkorn?",a="Bernsteinkorn ist eine Nuss, die von Mulgores großen, uralten Bäumen fällt. Sie trägt natürliche Magie in sich, die mit den Geistern des Landes verbunden ist.",al={"bernsteinkorn","was sind bernsteinkörner"}},{q="Wo findet man Bernsteinkorn?",a="Bernsteinkorn liegt unter den Kronen von Mulgores mächtigen Bäumen, besonders rund um das Dorf der Bluthufe.",al={"bernsteinkorn fundort","wo bernsteinkorn finden","wie bernsteinkorn bekommen"}},{q="Wofür wird Bernsteinkorn verwendet?",a="Die Seher der Tauren verbinden Bernsteinkorn mit Brunnensteinen, um das Wasser der Seher zu brauen. Initiierte trinken es während des Rite of Vision, der spirituelle Führer offenbart.",al={"bernsteinkorn verwendung","was bewirkt bernsteinkorn"}},{q="Wer bittet im Dorf der Bluthufe um Bernsteinkorn?",a="Im Dorf der Bluthufe bittet der Seher Zarlman Zwillingsmond Initiierte, Bernsteinkorn für Prüfungen zu sammeln, die ihre Verbindung zur Erdenmutter beweisen sollen.",al={"wer braucht bernsteinkorn","bernsteinkorn questgeber"}}},fx={af22a474={q="Woher stammt Bernsteinkorn und wer hat es erschaffen?",a="Bernsteinkorn wird nicht von sterblichen Händen erschaffen; es ist eine natürliche Nuss oder ein Zapfen, der von den mächtigen Bäumen fällt, die auf den Ebenen von Mulgore stehen. Die Tauren verehren diese Samen als Geschenke der heiligen Erde, die innewohnende magische Elemente enthalten, die direkt in das Land eingewoben sind.",al={"woher stammt bernsteinkorn","herkunft von bernsteinkorn","wer hat bernsteinkorn erschaffen","wo gibt es informationen über bernsteinkorn"}},c9693aa2={q="Warum möchte jemand Bernsteinkorn haben?",a="Taurenschamanen wie Zarlman Zwillingsmond suchen Bernsteinkorn wegen seiner latenten magischen Eigenschaften. Wenn es mit heiligen Brunnensteinen kombiniert und zu dem potenten Wasser der Seher gebraut wird, führt es vor dem Stammesfeuer in eine spirituelle Trance, die jungen Tauren die Visionen gewährt, die sie für den Abschluss der heiligen Rite of Vision benötigen.",al={"warum wird bernsteinkorn benötigt","warum bernsteinkorn sammeln","wer will bernsteinkorn","verwendung von bernsteinkorn"}}},fp="9,124,19.349.0,15.369.0,21.126.0,29.101.0,27.157.0,44.150.0"}
P.entries["item:amethyst-phial"] = {n="Amethystphiole",s="In Dolanaar vertraut Corithras Mondzorn Reisenden die Amethystphiole an. Sie bringen sie zur Lichtung des Orakels und schöpfen Wasser aus dem Mondbrunnen unter dem Oracle Tree.",h="In Dolanaar vertraut Corithras Mondzorn Reisenden die Amethystphiole an.",kw={"amethystphiole","corithras mondzorn","crown of the earth","dolanaar","mondbrunnen","die lichtung des orakels","oracle tree","teldrassil"},ang={["class:Druid"]="Als Druide nutzt Ihr die Phiole, um die Lebensenergien des Weltbaums und die schleichende Verderbnis zu überwachen.",["race:NightElf"]="Als Kaldorei übernehmt Ihr eine ernste Pflicht, wenn Ihr die Phiole füllt und Euch den Makeln in Teldrassils ungesegneter Erschaffung stellt."},sec={{t="Gefäß heiliger Wasser",b="Corithras Mondzorn gibt Reisenden auf Teldrassil die Amethystphiole. Sie ist das letzte Gefäß auf der Pilgerreise von Crown of the Earth. Sie tragen sie zur Lichtung des Orakels im äußersten Nordwesten des Geästs.\n\nUnter dem uralten Blätterdach des Oracle Tree liegt der erste und mächtigste Mondbrunnen der Insel. Reisende tauchen die Phiole in seine strahlenden Wasser, um die Essenz von Elunes Gnade zu sammeln. Mit diesem Wasser erforschen und pflegen Druiden und Priesterinnen das unberechenbare Wachstum des Weltbaums."},{t="Die Last ungesegneten Wachstums",b="Erzdruide Fandral Hirschhaupt leitete die Erschaffung Teldrassils, doch die Drachenaspekte weigerten sich, ihn zu segnen. Sie hielten die Tat für anmaßend. Daher befällt Verderbnis das Geäst, und die Kaldorei bleiben sterblich.\n\nDas Füllen der Amethystphiole ist sowohl ein spiritueller Ritus als auch eine fortlaufende Untersuchung. Forscher in Dolanaar prüfen eingehend die Reinheit der heiligen Wasser Teldrassils."}},faq={{q="Wofür wird die Amethystphiole verwendet?",a="Corithras Mondzorn gibt Euch die Phiole, um Wasser aus Teldrassils erstem und mächtigstem Mondbrunnen unter dem Oracle Tree auf der Lichtung des Orakels zu schöpfen.",al={"amethystphiole zweck","was mit amethystphiole tun","amethystphiole verwendung"}},{q="Wo fülle ich die Amethystphiole?",a="Füllt die Phiole am Mondbrunnen weit nordwestlich von Dolanaar, nördlich des Eingangs nach Darnassus, auf der Lichtung des Orakels.",al={"wo amethystphiole füllen","amethystphiole fundort","lichtung des orakels mondbrunnen"}},{q="Warum ist das Wasser von der Lichtung des Orakels so wichtig?",a="Der Mondbrunnen unter dem Oracle Tree gilt als der erste und mächtigste Brunnen auf dem Weltbaum. Seine Wasser tragen die Essenz Elunes und helfen Forschern, Teldrassils geistige und körperliche Gesundheit zu überwachen.",al={"warum wasser der lichtung des orakels","oracle tree mondbrunnen macht","bedeutung des orakelbrunnens"}},{q="Wer schickt Euch los, diese Phiole zu verwenden?",a="Corithras Mondzorn, ein Nachtelfendruide in Dolanaar, gibt Euch die Phiole für ein Ritual, das Teldrassils gestörtes Wachstum ergründen soll.",al={"wer gibt amethystphiole","corithras mondzorn phiole","wer will die amethystphiole"}}},fx={f821d918={q="Was ist die Amethystphiole?",a="Die Amethystphiole ist ein leeres zeremonielles Gefäß, das Reisenden in Teldrassil gegeben wird. Speziell dafür gefertigt, reine, verzauberte Flüssigkeit zu enthalten, ist ihr Zweck, Wasser aus dem Mondbrunnen zu schöpfen und zu bewahren, der unter dem uralten Orakelbaum ruht.",al={"amethystphiole","was ist diese phiole"}},af37ef60={q="Warum möchte Corithras Mondzorn, dass die Amethystphiole gefüllt wird?",a="Corithras Mondzorn sucht Wasser aus dem erstklassigen Mondbrunnen an der Lichtung des Orakels, um den seltsamen Zustand von Teldrassil zu untersuchen. Da dem großen Weltenbaum der Segen der Drachenaspekte fehlt, bleibt sein Wachstum fehlerhaft und unvorhersehbar, was die Druiden dazu veranlasst, seine heiligsten Gewässer genau zu prüfen.",al={"warum die amethystphiole füllen","warum corithras die phiole will","zweck der amethystphiole"}}},fp="14,168,23.480.0,28.375.1,36.151.0,35.114.0,52.213.0,32.135.0"}
P.entries["item:an-undelivered-letter"] = {n="Ein niemals zugestellter Brief",s="In Goldhain wartet im Gasthaus \"Zur Höhle des Löwen\" ein alter Brief mit einem Hinweis auf Stalvan Dunstmantels Vergangenheit.",h="In Goldhain wartet im Gasthaus \"Zur Höhle des Löwen\" ein alter Brief mit einem Hinweis auf Stalvan...",kw={"kanalviertel","kurier","folsom","goldhain","gasthaus \"zur höhle des löwen\"","bote","dunstmantel","stalvan"},ang={["faction:Alliance"]="Für Ermittler der Allianz führt die vergessene Route des Kuriers vom ländlichen Herzen Goldhains zu den Vierteln der Oberschicht in Sturmwind."},sec={{t="Flucht um Mitternacht",b="Vor Jahren trieb ein Sturm einen reisenden Kurier ins Gasthaus \"Zur Höhle des Löwen\", wo er Schutz suchte. Gegen Mitternacht trieb die Angst den Boten im Nachtgewand die Treppe hinunter und hinaus in den strömenden Regen. Er verschwand und kehrte nie zurück. In einer Truhe im Obergeschoss hinterließ er seine Habseligkeiten und einen Brief von Stalvan Dunstmantel an ein Anwesen im Kanalviertel von Sturmwind."},{t="Dem Gelehrten auf der Spur",b="In den oberen Räumen des Gasthauses blieb der ungeöffnete Brief jahrelang unberührt. Nun folgen Ermittler Stalvans Spuren durch den Wald von Elwynn. Wer das Pergament zu Verwalter Folsom in der Hauptstadt bringt, trägt das Geheimnis vom Gasthaus ins Herz von Sturmwind."}},faq={{q="Wo ist der nicht zugestellte Brief zu finden?",a="Der Brief liegt in einer Vorratstruhe im zweiten Stock des Gasthauses \"Zur Höhle des Löwen\" in Goldhain, am Fußende eines Bettes in einem Gästezimmer.",al={"wo ist der brief","standort der vorratstruhe","truhe zur höhle des löwen"}},{q="Warum wurde der Brief nie zugestellt?",a="Während eines Regensturms suchte der Kurier, der den Brief bei sich trug, Schutz im Gasthaus \"Zur Höhle des Löwen\". Gegen Mitternacht geriet er in Panik, rannte im Nachtgewand die Treppe hinunter und verschwand im Sturm, wobei er seine Truhe samt Inhalt zurückließ.",al={"warum nicht zugestellt","was geschah mit dem boten","kurier geflohen"}},{q="Wer hat diesen Brief geschrieben?",a="Stalvan Dunstmantel schrieb den Brief. Er hatte etwa zur selben Zeit wie der verängstigte Kurier mehrere Nächte im Gasthaus verbracht.",al={"wer hat den brief geschickt","stalvan verfasser","absender"}},{q="Wohin soll der Brief gebracht werden?",a="Der Brief ist an das Kanalviertel von Sturmwind adressiert. Er kann zu Verwalter Folsom in der Nähe des Parks gebracht werden.",al={"wer erhält den brief","ziel sturmwind","brief kanalviertel"}}},fx={["72dbe9c7"]={q="Was ist Ein niemals zugestellter Brief?",a="Es ist ein altes, vergessenes Schreiben, das vor Jahren von Stalvan Dunstmantel verfasst wurde. Ein Kurier, der es bei sich trug, suchte in einer stürmischen Nacht Schutz im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, floh aber gegen Mitternacht in reiner Panik in die Dunkelheit. Der Brief wurde im Aufbewahrungstruhen des Boten zurückgelassen, bleibt versiegelt und ungelesen und enthält Hinweise auf Stalvans Vergangenheit.",al={"was ist ein niemals zugestellter brief","gegenstand ein niemals zugestellter brief","stalvans brief"}},e9e7c880={q="Warum wird Ein niemals zugestellter Brief gesucht?",a="Ihr benötigt ihn, um die dunkle Geschichte von Stalvan Dunstmantel aufzudecken. Da sich seine Spur im Dämmerwald und im Wald von Elwynn verliert, dient dieses vergessene Schreiben – adressiert an jemanden im Kanalviertel von Sturmwind – als der nächste wichtige Hinweis, um zusammenzusetzen, wer er war und was aus ihm wurde.",al={"warum brauche ich den niemals zugestellten brief","wer will den niemals zugestellten brief","zweck des niemals zugestellten briefes"}}},fp="21,104,17.359.0,19.256.1,38.126.0,35.227.0,22.123.0,35.117.0"}
P.entries["item:anaya-s-pendant"] = {n="Anayas Anhänger",s="In Ameth'Aran bleibt Anayas Anhänger beim gequälten Geist von Anaya Dawnrunner. Cerellean Weißklaue trauert noch immer um seine Geliebte, die er verlor, als die Zerschlagung ihre Welt zerriss.",h="In Ameth'Aran bleibt Anayas Anhänger beim gequälten Geist von Anaya Dawnrunner.",kw={"ameth'aran","anaya dawnrunner","auberdine","cerellean weißklaue","dunkelküste","for love eternal","anhänger","brunnen der ewigkeit"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Cerellean Jahrtausende an der Seite von Shan'do Sturmgrimm schlief, in der Hoffnung, seiner Trauer zu entfliehen. Als er erwachte, fand er Geister vor, die in der wachen Welt verweilten.",["race:NightElf"]="Als Nachtelf seht Ihr in dem Anhänger eine Erinnerung an den War of the Ancients und die vielen Leben und Lieben, die während der Great Sundering auseinandergerissen wurden."},sec={{t="Ein Andenken über Jahrtausende",b="Vor zehntausend Jahren wurde der Brunnen der Ewigkeit zerstört, und die uralte Kaldorei-Stadt Ameth'Aran verfiel zu Ruinen. Cerellean Weißklaue glaubte, seine geliebte Anaya sei umgekommen. Er nahm seine Trauer mit in einen langen Schlummer an der Seite von Shan'do Malfurion Sturmgrimm.\n\nNach seinem Erwachen durchstreifte Cerellean die Dunkelküste und fand Anayas gequälte Erscheinung, die mit dem Anhänger durch Ameth'Aran schwebte. Er selbst bringt es nicht über sich, die Hand gegen sie zu erheben. Deshalb bittet er Reisende, ihren Geist zu erlösen und das Erbstück zu bergen."},{t="Abschied und Frieden",b="In Auberdine nimmt Cerellean den Anhänger entgegen, und der Geist von Anaya Dawnrunner erscheint ein letztes Mal kurz vor ihm. Befreit von den Qualen, die sie an die heimgesuchten Ruinen von Ameth'Aran binden, entschwindet ihr Geist friedlich in die Nacht. Cerellean bleibt allein zurück, mit dem Anhänger und der Erinnerung an ihre uralte Liebe."}},faq={{q="Woher stammt Anayas Anhänger?",a="Anayas Anhänger stammt vom Geist von Anaya Dawnrunner, der durch die uralten Kaldorei-Ruinen von Ameth'Aran im Süden der Dunkelküste wandert.",al={"wo anayas anhänger zu finden ist","wie anayas anhänger zu bekommen ist","wer anayas anhänger fallen lässt"}},{q="Wer möchte Anayas Anhänger haben?",a="Cerellean Weißklaue möchte Anayas Anhänger haben. Der trauernde Nachtelf lebt in Auberdine, der Küstenstadt an der Dunkelküste.",al={"wem anayas anhänger geben","cerellean weißklaue quest","anayas anhänger abgeben"}},{q="Warum konnte Cerellean den Anhänger nicht selbst bergen?",a="Cerellean fand den Geist seiner verlorenen Geliebten in Ameth'Aran, brachte es aber selbst nach zehntausend Jahren voller Trauer nicht über sich, die Hand gegen sie zu erheben.",al={"warum cerellean anaya nicht tötete","warum cerellean hilfe braucht"}},{q="Was geschieht, wenn Ihr Cerellean den Anhänger zurückbringt?",a="Wenn Ihr Cerellean den Anhänger in Auberdine zurückbringt, erscheint Anayas Geist kurz zum Abschied und entschwindet dann in Frieden. Cerellean bleibt zurück und trauert um sie.",al={"was mit anaya geschieht","cerelleans reaktion"}}},fx={["2379a09f"]={q="Was ist Anayas Anhänger?",a="Anayas Anhänger ist ein altes Andenken von Anaya Dawnrunner, einer Kaldorei, die vor Jahrtausenden bei der Zerstörung von Ameth'Aran umkam. Der Anhänger, den ihr rastloser Geist inmitten der Ruinen bei sich trägt, dient als ergreifendes physisches Zeichen ihrer beständigen Liebe und des Lebens, das sie vor dem Großen Bruch mit Cerellean Weißklaue teilte, bevor ihre Welt auseinandergerissen wurde.",al={"was ist anayas anhänger","anayas anhänger lore","wem gehört der anhänger"}}},fp="15,186,27.493.0,17.305.1,37.133.0,26.116.0,52.153.0,54.165.1"}
P.entries["item:ancient-egg"] = {n="Uraltes Ei",s="Das Uralte Ei ist ein Trollrelikt, das in Jintha'Alor im Hinterland verborgen liegt. Yeh'kinya sucht danach, weil es laut der Prophecy of Mosh'aru Hakkars Essenz aufnehmen kann.",h="Das Uralte Ei ist ein Trollrelikt, das in Jintha'Alor im Hinterland verborgen liegt.",kw={"uraltes ei","hakkar","hinterland","jintha'alor","mosh'aru","trollrelikt","yeh'kinya"},ang={["race:Troll"]="Als Troll erinnert Euch das Uralte Ei an die gewaltigen Reiche Eures Volkes und die Macht, die in seinen alten Relikten gebunden ist."},sec={{t="Ein Relikt in Jintha'Alor",b="Tief in der Trollstadt Jintha'Alor liegt das Uralte Ei in einer Höhle hinter dem Amphitheater. Yeh'kinya sucht danach in Tanaris, wo er die Prophecy of Mosh'aru studiert. Die Prophezeiung bezeichnet das Ei als Gefäß für Hakkars Essenz. Yeh'kinya fürchtet, dass die Welt davon abhängen könnte."}},faq={{q="Was ist das Uralte Ei?",a="Das Uralte Ei ist ein Trollrelikt aus der Zeit der gewaltigen Trollreiche. Laut der Prophecy of Mosh'aru kann es Hakkars Essenz aufnehmen.",al={"uraltes ei","welches ei","troll ei"}},{q="Wo befindet sich das Uralte Ei?",a="Das Uralte Ei liegt tief in einer Höhle in Jintha'Alor, hinter dem Amphitheater auf dem Gipfel der Stadt im Hinterland.",al={"ei fundort","wo ei","jintha'alor ei"}},{q="Wer will das Uralte Ei?",a="Yeh'kinya in Tanaris sucht nach dem Uralten Ei wegen dessen Fähigkeiten, von denen die Prophecy of Mosh'aru berichtet.",al={"yeh'kinya ei","wer will es","ei bringen zu"}},{q="Warum will Yeh'kinya es?",a="Yeh'kinya glaubt, dass das Uralte Ei vielleicht die einzige Möglichkeit ist, die Welt vor Hakkars Bösem zu bewahren.",al={"warum ei","hakkar ei","prophezeiung ei"}}},fp="11,164,22.282.0,24.128.0,25.120.0,26.99.0,27.97.0"}
P.entries["item:ancient-moonstone-seal"] = {n="Altes Mondsteinsiegel",s="In Bashal'Aran hält das Alte Mondsteinsiegel Asterion zwischen den Ruinen gefangen. Die Hochgeborenen schmiedeten es lange vor der Zerschlagung und banden seinen Geist mit arkaner Magie.",h="In Bashal'Aran hält das Alte Mondsteinsiegel Asterion zwischen den Ruinen gefangen.",kw={"ameth'aran","altes mondsteinsiegel","asterion","athrikus","bashal'aran","dunkelküste","deth'ryll","hochgeborene","mondstein"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie uralte elfische Bannmagie ihr Bindungsfeld mehr als zehntausend Jahre lang im Mondstein aufrechterhielt.",["race:NightElf"]="Als Nachtelf könnt Ihr im Siegel die arkane Macht der Hochgeborenen und ihre grausamen Praktiken der Versklavung vor der Großen Zerschlagung erkennen."},sec={{t="Ein Gefängnis hochgeborener Zauberei",b="Athrikus Narassin, Asterions früherer Meister, schmiedete das Alte Mondsteinsiegel, um dessen Seele an die Säulen von Bashal'Aran zu binden. Der Zauberer der Hochgeborenen machte es zu einem unzerbrechlichen Anker, als der Brunnen der Ewigkeit noch stand und Königin Azshara herrschte. Mehr als zehn Jahrtausende später bleibt Asterion ein Geist, der durch seine Magie gebunden ist. Weder seine Kraft noch einer seiner Zauber kann den Schutzzauber brechen."},{t="Zerstörung in Ameth'Aran",b="Nach der Großen Zerschlagung brachten die Deth'ryll-Satyren das Siegel in die umliegende Wildnis der Dunkelküste. Der verzauberte Stein der Hochgeborenen gibt keiner gewöhnlichen Gewalt nach. Um das Relikt zu zerstören, muss es der uralten blauen Flamme ausgesetzt werden, die noch immer in Ameth'Arans Zwillingsruinen im Süden brennt. Dieses Feuer zerschlägt Athrikus' bindenden Schutzzauber und befreit Asterions Geist, sodass er die sterbliche Welt betreten kann."}},faq={{q="Was ist das Alte Mondsteinsiegel?",a="Athrikus Narassin, ein Zauberer der Hochgeborenen, fertigte das Alte Mondsteinsiegel an, um Asterions Geist an seinen Schrein in Bashal'Aran zu binden.",al={"was ist das mondsteinsiegel","siegel von asterion","siegel von bashal'aran"}},{q="Wer besitzt das Siegel, bevor es geborgen wird?",a="Bevor jemand es birgt, besitzt ein Deth'ryll-Satyr in den Ruinen um Bashal'Aran das Siegel. Seine Gegenwart erlaubt dem Satyr, niedere Grell-Diener zu befehligen.",al={"wer hat das siegel","wo ist das mondsteinsiegel zu finden","wer lässt das mondsteinsiegel fallen"}},{q="Wie lässt sich das Siegel zerstören?",a="Gewöhnliche Waffen und heutige Magie können dem Siegel nichts anhaben. Es muss in die uralte Flamme geworfen werden, die noch immer in Ameth'Arans Zwillingsruinen im Süden brennt.",al={"wie lässt sich das siegel brechen","mondsteinsiegel zerstören","wo lässt sich das siegel zerstören"}},{q="Was geschieht, wenn das Siegel zerstört wird?",a="Die Flamme in Ameth'Aran zerstört das Siegel und bricht die Verzauberungen, die Asterion binden. Nach Jahrtausenden der Gefangenschaft kann sein Geist frei durch die Welt streifen.",al={"was bewirkt das brechen des siegels","asterion befreit"}}},fx={bc236585={q="Woher stammt das Altes Mondsteinsiegel und wer hat es erschaffen?",a="Das Altes Mondsteinsiegel wurde vor Jahrtausenden auf dem Höhepunkt des Kaldorei-Imperiums, vor dem Großen Bruch, erschaffen. Es wurde durch die Hexerei eines der mächtigsten Hochgeborenen-Lords – Athrikus Narassin – geschmiedet, um als mystischer Bindungsmechanismus zu dienen.",al={"wer machte altes mondsteinsiegel","ursprung altes mondsteinsiegel","schöpfer altes mondsteinsiegel"}},a13d6402={q="Warum will Asterion das Altes Mondsteinsiegel?",a="Asterion sucht das Siegel, weil es genau der Anker ist, der seinen Geist in der zerstörten Ruinen von Bashal'Aran gefangen hält. Solange es intakt bleibt, ist er hinter unsichtbaren Gittern gefangen und kann sein altes Gefängnis nicht verlassen oder ruhen. Durch die Wiederbeschaffung des Siegels hofft er, es in den uralten Flammen von Ameth'Aran zu zerstören und endlich seine Freiheit zu erlangen.",al={"warum will asterion das siegel","warum altes mondsteinsiegel finden","wer will altes mondsteinsiegel"}}},fp="22,171,29.370.0,25.368.1,35.130.0,46.150.0,30.154.0,40.164.1"}
P.entries["item:ancient-statuette"] = {n="Antike Statuette",s="An Eschentals nordwestlichem Ufer sucht Talen nach der Antiken Statuette, die er aus Zorams versunkenen Ruinen geborgen hat. Das nachtelfische Bildnis stammt aus einer Stadt, die unter den Wellen versank.",h="An Eschentals nordwestlichem Ufer sucht Talen nach der Antiken Statuette, die er aus Zorams versunkenen...",kw={"antike statuette","eschental","naga","ruinen von zoram","statuette","talen","zoram","der zoramstrand"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Talen helfen, das Erbe der Nachtelfen zu dokumentieren und es den Naga zu entreißen, die entlang Eschentals Küste vordringen.",["race:NightElf"]="Als Nachtelf könnt Ihr die Statuette als ein Bruchstück der Zivilisation der Kaldorei aus der Zeit vor der Great Sundering betrachten, das Jahrtausende unter dem Meer bewahrt wurde."},sec={{t="Ein Relikt im seichten Wasser",b="Vor Eschentals nordwestlichem Ufer liegt Zoram unter den Wellen. Die Stadt der Nachtelfen ging bei der Zerschlagung vor zehntausend Jahren unter. Vor Kurzem erkundete der Entdecker Talen ihre Ruinen von einem kleinen Boot aus und suchte nach Relikten der Vergangenheit. Dann griffen Naga an und trieben ihn an Land.\n\nTalen floh und ließ die meisten seiner Habseligkeiten zurück. Darunter war auch die Antike Statuette, die er aus den Ruinen geborgen hatte. Sie liegt im Sand am Gezeitensaum nahe seinem versenkten Kahn."},{t="Geheimnisse von Zoram",b="Talen nennt die Statuette seinen wertvollsten Besitz. Ihretwegen wagte er sich an die von Ungeheuern heimgesuchte Küste. Er glaubt, das Bildnis könne ihm helfen, Zorams Architektur, Geschichte und arkane Geheimnisse zu entschlüsseln. All das liegt unter der Brandung des Zoramstrands verborgen."}},faq={{q="Was ist die Antike Statuette?",a="Die Antike Statuette stammt aus Zoram, einer versunkenen Stadt der Nachtelfen vor Eschentals nordwestlicher Küste.",al={"was ist die statuette","geschichte der antiken statuette","was ist dieser gegenstand"}},{q="Wer sucht nach der Statuette?",a="Der nachtelfische Entdecker Talen sucht die Statuette. Naga griffen an, als er Zorams versunkene Ruinen vom Boot aus erkundete, und auf seiner Flucht ließ er das Relikt am Strand zurück.",al={"wer will die statuette","talen statuette","wer hat die statuette verloren"}},{q="Warum ist die Statuette wichtig?",a="Talen glaubt, die Statuette könne helfen, Zorams Geschichte und die Geheimnisse zu ergründen, die in seinen Ruinen unter den Wellen verborgen liegen.",al={"warum will talen sie","zweck der statuette"}},{q="Warum treiben sich Naga in der Nähe des Fundorts herum?",a="Naga haben die Küstengewässer und Ruinen des Zoramstrands heimgesucht. Sie greifen Oberflächenbewohner an, die sich nahe an die versunkenen Überreste ihres überfluteten Gebiets wagen.",al={"warum naga am strand","zoramstrand naga"}}},fp="17,177,23.445.0,16.254.0,30.100.0,33.154.0,31.116.0,48.154.0"}
P.entries["item:andron-s-ledger"] = {n="Androns Geschäftsbuch",s="In der Unterstadt weckt Androns Geschäftsbuch die Aufmerksamkeit der Todespirscher. Ein Agent der Verlassenen hat Informationen über Bedrohungen für ihr Reich aufgedeckt.",h="In der Unterstadt weckt Androns Geschäftsbuch die Aufmerksamkeit der Todespirscher.",kw={"alterac","andron gant","androns geschäftsbuch","deathstalkers","mennet carkad","schurkenviertel","syndikat","varimathras"},ang={["class:Rogue"]="Als Schurke beweist Ihr Euren Wert, indem Ihr Androns Geschäftsbuch beschafft und entziffert. Mennet Carkad nimmt Euch formell in die Todespirscher auf, und Varimathras würdigt Eure Arbeit.",["race:Undead"]="Als Untoter erlebt Ihr, wie die Verlassenen Informationen über Bedrohungen im Umfeld ihres neuen Reiches sammeln."},sec={{t="Das Syndikat aufdecken",b="In Andron Gants Bücherregal in der Unterstadt steht ein Geschäftsbuch, mit dessen Fund die Todespirscher nicht gerechnet hatten. Seine Seiten zeigen, dass das Syndikat in der Region aktiv ist. Das Syndikat besteht aus Überresten des gestürzten menschlichen Adels von Alterac. Todespirscher Mennet Carkad erkennt sofort, dass die ruinierten Lords von Alterac wieder Ränke schmieden. Das Geschäftsbuch liefert der Führung der Verlassenen Beweise für deren Machenschaften, die über die Erwartungen der Todespirscher hinausgehen."},{t="Eine Angelegenheit für den Schreckenslord",b="Mennet Carkad schickt den Überbringer mit dem Geschäftsbuch direkt zu Varimathras ins Königsviertel. Es betrifft Bedrohungen für das Reich der Verlassenen. Varimathras ist Sylvanas Windläufers Schreckenslord-Majordomus. Er beaufsichtigt die innere Sicherheit und Spionage durch die Todespirscher. Er würdigt das Geschäftsbuch und erkennt damit die Kompetenz des Netzwerks und die Zuverlässigkeit des Agenten an, der es ans Licht gebracht hat."}},faq={{q="Was ist Androns Geschäftsbuch?",a="Androns Geschäftsbuch ist ein Aufzeichnungsbuch aus Andron Gants Bücherregal in der Unterstadt. Es enthält Informationen, nach denen die Todespirscher suchen.",al={"androns geschäftsbuch","was ist dieses buch","andron geschäftsbuch"}},{q="Wer ist Andron Gant?",a="Andron Gant ist ein Verlassener, der nahe dem Apothekarium in der Unterstadt einen Laden führt. Lord Varimathras vermutete, dass Andron heimlich eine auswärtige Gruppe unterstützte. Die Todespirscher schickten einen Agenten, der sich als der von Andron erwartete Bote ausgab, um das Geschäftsbuch zu beschaffen.",al={"wer ist andron","andron gant"}},{q="Warum wollen die Todespirscher das Geschäftsbuch?",a="Mennet Carkad will Androns Informationen auf Erkenntnisse prüfen, die den Verlassenen nützen könnten.",al={"warum das geschäftsbuch wichtig ist","warum deathstalkers das geschäftsbuch wollen"}},{q="Wer erhält das Geschäftsbuch?",a="Das Geschäftsbuch geht zuerst an Mennet Carkad im Schurkenviertel. Nachdem er den Inhalt ausgewertet hat, weist er den Überbringer an, es direkt zu Lord Varimathras in der Hall of the Dark Lady zu bringen.",al={"wer erhält androns geschäftsbuch","wem das geschäftsbuch bringen"}},{q="Was bringt die Übergabe des Geschäftsbuchs einem Schurken?",a="Die Übergabe des Geschäftsbuchs bringt dem Agenten die formelle Aufnahme in die Todespirscher ein, die geheimnisumwobene Assassinengilde der Verlassenen.",al={"aufnahme in die deathstalkers","den deathstalkers beitreten"}}},fx={["83ea0415"]={q="Woher stammt Androns Geschäftsbuch?",a="Das Geschäftsbuch gehört Andron Gant, einem Informanten, der in der Unterstadt lebt und detaillierte Aufzeichnungen über seine verdeckten Geschäfte führt. Es liegt in seinem Quartier in einem Bücherregal, bis es von einem Agenten im Auftrag der The Todespirscher geborgen wird.",al={"wer hat androns geschäftsbuch erstellt","ursprung von androns geschäftsbuch","woher stammt das geschäftsbuch"}},["45ae6031"]={q="Warum wollen die The Todespirscher Androns Geschäftsbuch?",a="Mennet Carkad und die The Todespirscher suchen nach dem Geschäftsbuch, um Informationen über Bedrohungen für die Verlassenen zu erhalten. Mennet prüft dessen Inhalt, bevor er es an Lord Varimathras schickt.",al={"warum wird androns geschäftsbuch gesucht","wer will androns geschäftsbuch","warum möchte mennet carkad das geschäftsbuch"}}},fp="15,146,24.415.1,26.382.1,24.125.0,19.246.0,41.92.0,24.188.0,52.123.0"}
P.entries["item:another-clue-to-sanders-treasure"] = {n="Another Clue to Sanders' Treasure",s="In Westfall weist ein Fetzen von Captain Sanders' Pergament zu seiner nächsten verborgenen Wegmarke.",h="In Westfall weist ein Fetzen von Captain Sanders' Pergament zu seiner nächsten verborgenen Wegmarke.",kw={"klippen","captain sanders","hinweis","pergament","sanders schatz","westfall","windmühle"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie man rätselhafte Wegbeschreibungen liest und vergessene Verstecke am Meer nach verborgener Beute durchsucht."},sec={{t="Eine Spur auf den Küstenklippen",b="Captain Sanders versteckte seine gestohlenen Reichtümer in ganz Westfall und hinterließ Rätsel und vergrabene Wegmarken statt einer einzigen Karte, die beschlagnahmt werden konnte. Dieser Fetzen führt die Spur vom vorherigen Versteck aus weiter. Er weist an, sich nach Norden zu wenden und einen weggeworfenen Krug neben einer einsamen Windmühle oberhalb der Meeresklippen zu suchen."}},faq={{q="Was steht auf diesem Hinweis?",a="Das Pergament weist an, sich vom versteckten Fass aus nach Norden zu wenden und geradeaus zu einem leeren Krug neben einer einsamen Windmühle auf den Meeresklippen zu gehen.",al={"was steht auf dem hinweis","sanders hinweistext","wegbeschreibung auf dem hinweis"}},{q="Wer war Captain Sanders?",a="Captain Sanders war ein Pirat, der entlang der Küsten und Klippen von Westfall Verstecke mit gestohlenen Waren anlegte. Er versteckte Wegmarken in der ganzen Region, statt eine vollständige Karte zu hinterlassen.",al={"wer ist sanders","captain sanders hintergrund","sanders westfall pirat"}},{q="Wohin führt dieser Hinweis als Nächstes?",a="Der Hinweis führt entlang der Küstenklippen von Westfall nach Norden zu einer einsamen Windmühle, wo ein leerer Krug den nächsten Schritt auf Sanders' Spur markiert.",al={"wohin als nächstes","sanders windmühlenhinweis","wo ist der krug"}}},fx={b0e51eff={q="Was ist Another Clue to Sanders' Treasure?",a="Es ist ein handgeschriebener Pergamentfetzen, der in einem alten Fass an der Küste von Westfall versteckt gefunden wurde. Das Papier enthält eine weitere Reihe nautischer Anweisungen, die von Kapitän Sanders verfasst wurden und jeden, der mutig genug ist, seiner Spur zu folgen, zum nächsten versteckten Teil seines Hinweises führen.",al={"was ist another clue to sanders treasure","sanders hinweis pergament","was ist dieses hinweispergament"}},["37a7a825"]={q="Woher kommt dieser Hinweis und wer hat ihn erstellt?",a="Der Hinweis wurde von Kapitän Sanders geschrieben und versteckt, einem alten Seefahrer, der eine Spur von Hinweisen über die Küste und das Land von Westfall verstreut hat. Ihr findet diesen speziellen Pergamentfetzen in einem verlassenen Fass, in dem er ihn vor langer Zeit versteckte.",al={"wer schrieb another clue to sanders treasure","wer machte sanders hinweis","woher kam dieser hinweis"}},["632540c2"]={q="Warum will jemand Another Clue to Sanders' Treasure?",a="Dem Pfad von Sanders zu folgen, ist der einzige Weg, seine vergrabene Truhe aufzudecken. Jeder Hinweis baut direkt auf dem letzten auf und bietet die genauen Orientierungspunkte, die nötig sind, um die Schritte des Kapitäns durch Westfall zu dem von ihm versteckten Schatz zu verfolgen.",al={"warum sanders hinweis finden","warum will ich sanders schatzhinweis","was ist der sinn von sanders hinweis"}}},fp="33,88,29.292.0,29.131.0,24.163.0,31.145.0"}
P.entries["item:arikara-serpent-skin"] = {n="Arikaras Schlangenhaut",s="Auf dem Düsterwolkengipfel wird Arikara in die Welt gerufen und erschlagen. Ihre Haut wird als Beweis für den Tod der Windnatter zum Weißgipfelposten gebracht.",h="Auf dem Düsterwolkengipfel wird Arikara in die Welt gerufen und erschlagen.",kw={"arikara","cairne bluthuf","düsterwolkengipfel","brandpulver","motega feuermähne","schlangenhaut","weißgipfelposten"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass verzaubertes Pulver, auf ein heiliges Feuer geworfen, eine Geisterbestie der Ahnen in die körperliche Welt locken kann.",["race:Tauren"]="Als Tauren erkennt Ihr in der Haut das Zeichen eines Konflikts zwischen uralten Mythen und der heutigen Führung. Magatha Grimmtotems Behauptungen über Cairne Bluthuf beunruhigen die Stämme."},sec={{t="Trophäe eines beschworenen Zorns",b="Arikara ist eine mächtige Windnatter, die mit uralten Legenden der Tauren verbunden ist. Manche sagen, sie suche Rache an Cairne Bluthuf, weil sich die Lebensweise der Tauren wandelt. Auf Geheiß der Ältesten Magatha Grimmtotem bereiten Champions verzaubertes Brandpulver vor. Sie werfen es auf das heilige Feuer auf den Begräbnisanhöhen des Düsterwolkengipfels und locken die Geisterbestie in die körperliche Welt. Arikaras Haut wird als Beweis für ihren Tod genommen."},{t="Eine beunruhigende Enthüllung",b="Am Weißgipfelposten nimmt Motega Feuermähne die Haut als Beweis entgegen, dass Arikara tot ist. Magatha Grimmtotem sagte, die Schlange habe Cairne Bluthuf aus dem Zorn der Ahnen heraus gejagt. Doch Arikaras Tod lässt Motega ratlos zurück. Warum sollte ein solcher Geist ihren Obersten Häuptling bedrohen? Der Balg bannt die Gefahr vorerst, doch Motega zweifelt an Magathas Darstellung."}},faq={{q="Was ist Arikaras Schlangenhaut?",a="Arikaras Schlangenhaut ist die schuppige Haut von Arikara, einer legendären Windnatter, die auf dem Düsterwolkengipfel in Tausend Nadeln beschworen und besiegt wurde.",al={"schlangenhaut","arikaras haut","was ist diese haut"}},{q="Wer möchte Arikaras Schlangenhaut haben?",a="Motega Feuermähne am Weißgipfelposten möchte die Haut und das übrige Brandpulver als Beweis dafür, dass Arikara niemanden mehr bedroht.",al={"wer nimmt die haut","bei wem abgeben","wer will arikaras haut"}},{q="Warum wurde Arikara überhaupt beschworen?",a="Magatha Grimmtotem sagte, Veränderungen der Taurentraditionen hätten die Ahnenschlange Arikara erzürnt, die dem Obersten Häuptling Cairne Bluthuf nachstellte. Sie befahl, die Schlange zu beschwören und zu erschlagen, bevor Cairne etwas zustoßen konnte.",al={"warum arikara beschwören","warum arikara töten"}},{q="Wo erhält man die Haut?",a="Die Haut stammt von Arikara, die mit verzaubertem Brandpulver beschworen wird, das auf das heilige Feuer des Lebens auf einer Begräbnisfelsnadel im Düsterwolkengipfel geworfen wird.",al={"wo arikaras schlangenhaut bekommen","arikaras standort"}}},fx={d099bc06={q="Woher stammt Arikaras Schlangenhaut?",a="Die Haut stammt direkt vom Kadaver von Arikara, einem bösartigen Windschlangengeist, der auf dem Düsterwolkengipfel in Tausend Nadeln beschworen wird. Magatha Grimmtotem verzaubert Brandpulver, das, wenn es auf das Sacred Fire des Lebens geworfen wird, wo die Toten begraben sind, Arikara herbeiruft, damit sie erschlagen und ihrer Haut beraubt werden kann.",al={"arikara haut ursprung","woher stammt arikara schlangenhaut","wer machte arikara haut"}}},fp="20,140,26.387.0,22.344.1,33.152.0,35.128.0,44.209.0,31.148.0"}
P.entries["item:arnak-s-hoof"] = {n="Arnaks Huf",s="Auf dem Düsterwolkengipfel erwartet Arnak Grimtotem seine Hinrichtung wegen Mordes und Entführung. Die Verteidiger des Freiwindpostens bestimmten ihn zum Tode, nachdem er einen anderen Tauren getötet und dessen Schwester verschleppt hatte.",h="Auf dem Düsterwolkengipfel erwartet Arnak Grimtotem seine Hinrichtung wegen Mordes und Entführung.",kw={"arnak","arnak grimtotem","arnaks huf","klippenbehüter langhorn","düsterwolkengipfel","freiwindposten","lakota windweise","tausend nadeln"},ang={["faction:Horde"]="Indem Ihr Arnak ausschaltet, wahrt Ihr die Autorität des Freiwindpostens in Tausend Nadeln. Außerdem schwächt Ihr den verräterischen Einfluss der Grimtotem, der die Nachschubrouten der Horde bedroht.",["race:Tauren"]="Als Tauren der Ebenen übt Ihr Stammesjustiz, indem Ihr Arnaks Huf an Euch nehmt. Seine Morde brachten Schande und Blutvergießen über Tausend Nadeln."},sec={{t="Kopfgeld auf einen Ausgestoßenen",b="In ganz Tausend Nadeln ist Arnak Grimtotem als Gesetzloser gefürchtet. Seine Brutalität hat selbst die erbitterten Grenzen zwischen den Taurenclans überschritten. Er ermordete einen anderen Tauren und entführte dessen Schwester, Lakota Windweise.\n\nDaraufhin bestimmten die Verteidiger des Freiwindpostens ihn zur Hinrichtung und setzten ein Kopfgeld auf seinen Tod aus. Arnak suchte auf dem Düsterwolkengipfel Zuflucht, bewacht von Grimtotem. Sein abgetrennter Huf beweist Klippenbehüter Langhorn am Freiwindposten, dass der Mörder für seine Verbrechen gebüßt hat."}},faq={{q="Wozu dient Arnaks Huf?",a="Arnaks Huf beweist, dass der Gesetzlose Arnak Grimtotem tot ist. Ihr bringt ihn zu Klippenbehüter Langhorn am Freiwindposten, um den Kopfgeldauftrag zu erfüllen und die versprochene Belohnung einzufordern.",al={"arnaks huf abgeben","was tun mit arnaks huf","wer will arnaks huf"}},{q="Wer war Arnak Grimtotem?",a="Arnak Grimtotem war ein abtrünniger Grimtotem, der wegen Mordes und Entführung gesucht wurde. Er tötete einen anderen Tauren und hielt dessen Schwester, Lakota Windweise, auf den Klippen des Düsterwolkengipfels gefangen.",al={"wer ist arnak","arnak grimtotem geschichte","warum wird arnak gesucht"}},{q="Wo ist Arnak Grimtotem zu finden?",a="Ihr findet Arnak auf den Klippen des Düsterwolkengipfels im Norden von Tausend Nadeln. Hängebrücken nahe den Felsen auf dem Weg zu den Hügeln der Klingenhauer führen dorthin. Lakota Windweise wird auf derselben Klippe gefangen gehalten.",al={"arnak grimtotem fundort","wo ist arnak","arnak finden"}}},fx={["8804d903"]={q="Was ist Arnaks Huf?",a="Dieser abgetrennte Huf dient als unbestreitbarer Beweis dafür, dass der gesetzlose Tauren Arnak Grimmtotem erschlagen wurde. Er wurde direkt von seinem Körper auf den windgepeitschten Plateaus von Tausend Nadeln genommen und wird zum Freiwindposten zurückgebracht, um zu bestätigen, dass die Gerechtigkeit den verbannten Schurken schließlich eingeholt hat.",al={"arnaks huf","was ist dieser huf"}},a4f2e55c={q="Woher stammt Arnaks Huf?",a="Er stammt von Arnak Grimmtotem, einem abtrünnigen Tauren, der auf den Klippen nahe dem Düsterwolkengipfel lauert. Anstatt geschmiedet oder gefertigt zu sein, ist er eine physische Trophäe, die beansprucht wurde, nachdem Ihr ihn in seinem Versteck mit Blick auf die Schluchten gestellt und erschlagen habt.",al={"wo bekommt man arnaks huf","wer machte arnaks huf","arnak huf ursprung"}},ffececdb={q="Warum will jemand Arnaks Huf?",a="Klippenbehüter Langhorn im Freiwindposten hat ein Kopfgeld ausgesetzt und den Beweis für Arnaks Ableben gefordert. Arnak beging abscheuliche Verbrechen – er tötete einen unschuldigen Tauren und entführte dessen Schwester, Lakota Windweise. Die Lieferung seines Hufes erfüllt das Kopfgeld und bringt Euch die Dankbarkeit und Münzen der Beschützer des Freiwindpostens ein.",al={"wer will arnaks huf","warum arnak huf abgeben","warum arnak huf wollen"}}},fp="12,191,20.484.0,30.175.0,24.192.0,31.198.0"}
P.entries["item:astor-s-letter-of-introduction"] = {n="Astors Vorstellungsschreiben",s="Astor Hadren trägt einen Brief zwischen dem Silberwald und Unterstadt hin und her. Die Todespirscher nutzen ihn, um gegen Andron Gant zu ermitteln, einen Ladenbesitzer, den Lord Varimathras verdächtigt, Geheimdienstinformationen der Verlassenen weiterzugeben.",h="Astor Hadren trägt einen Brief zwischen dem Silberwald und Unterstadt hin und her.",kw={"andron gant","das apothekarium","astor hadren","deathstalkers","mennet carkad","silberwald","unterstadt","varimathras"},ang={["class:Rogue"]="Als Schurke der Verlassenen könnt Ihr Astors Brief bei einer praktischen Aufnahmeprüfung für die Todespirscher einsetzen. Dabei werden Meuchelmord, Diebstahl und das Annehmen einer fremden Identität geprüft.",["race:Undead"]="Als Untoter könnt Ihr an diesem Plan die Paranoia innerhalb von Unterstadt erkennen. Lord Varimathras nutzt die Todespirscher, um Umtriebe unter den Verlassenen aufzuspüren."},sec={{t="Die Papiere eines Kuriers",b="Astor Hadren überbringt Nachrichten zwischen dem Silberwald und Unterstadt. Sein Brief weist den Überbringer gegenüber zwielichtigen Kontakten in der Stadt aus. Mennet Carkad, ein Ausbilder der Todespirscher, muss dort verdächtigen Informationslecks nachgehen. Astors Reisen machen ihn zum Ziel. Ein Agent kann ihn töten und seine Papiere an sich nehmen, dann seine Identität annehmen und die für ihn bestimmten geheimen Nachrichten abfangen."},{t="Die Falle beim Apothekarium",b="Mennet Carkad nutzt den beschafften Brief, um an Andron Gant heranzutreten, einen Ladenbesitzer nahe dem Apothekarium. Lord Varimathras verdächtigt Gant, Geheimdienstinformationen der Verlassenen an eine unbekannte dritte Partei weiterzugeben. Ein verdeckter Ermittler gibt sich als der erwartete Kontakt aus und legt den Brief vor. Gant vertraut dem Überbringer, wodurch der Ermittler herausfinden kann, wer seine Mitverschwörer sind, und Beweise für seinen Verrat sammeln kann."}},faq={{q="Wofür wird Astors Vorstellungsschreiben verwendet?",a="Mennet Carkad nutzt Astors Brief, um den Ladenbesitzer Andron Gant zu täuschen. Der Überbringer gibt sich als Kurier Astor Hadren aus, um Gants geheime Machenschaften aufzudecken.",al={"zweck des briefes","was bewirkt der brief","astors brief verwendung"}},{q="Wer war Astor Hadren?",a="Astor Hadren war ein Gesandter und Bote, der auf den Straßen zwischen dem Silberwald und Unterstadt private Korrespondenz überbrachte. Agenten der Todespirscher fingen ihn ab.",al={"wer ist astor","astor hadren hintergrund","wer hatte den brief"}},{q="Warum will Mennet Carkad diesen Brief?",a="Mennet Carkad braucht den Brief, um Rekruten zu prüfen, die den Todespirschern beitreten wollen, und Andron Gant eine Falle zu stellen. Lord Varimathras verdächtigt Gant des Verrats.",al={"warum braucht mennet ihn","carkads plan"}},{q="Vermutet Andron Gant, dass der Brief gestohlen ist?",a="Nein. Mennet sagt, Gant fehle der Verstand, um eine Täuschung zu vermuten. Gant hält den Überbringer für den üblichen Boten seiner Mitverschwörer.",al={"bemerkt gant es","wird andron getäuscht"}}},fx={da9b0b54={q="Was ist Astors Vorstellungsschreiben?",a="Es ist ein Beglaubigungsschreiben, das von Astor Hadren getragen wird, einem reisenden Kurier, der zwischen dem Silberwald und der Unterstadt unterwegs ist. Das Dokument identifiziert seinen Träger als erwarteten Mittelsmann für Andron Gant, einen Händler aus der Unterstadt, der verdächtigt wird, mit einer unbekannten externen Fraktion zusammenzuarbeiten.",al={"was ist astors schreiben","astors vorstellungsschreiben","was ist dieser brief"}}},fp="30,196,23.389.0,29.379.1,48.144.0,21.175.0,40.161.0,46.131.1"}
P.entries["item:ataeric-s-staff"] = {n="Ataerics Stab",s="Im Grabmal steht Ataerics Stab für einen Sieg über Dalarans Einfluss im Silberwald. Erzmagier Ataeric führte ihn, um die örtlichen Ley-Linien zu beherrschen.",h="Im Grabmal steht Ataerics Stab für einen Sieg über Dalarans Einfluss im Silberwald.",kw={"erzmagier ataeric","ataerics stab","dalaran","ley-energieknoten","das grabmal","schattenpriester allister","silberwald","the weaver"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie Dalarans Erzmagier fokussierende Hilfsmittel einsetzen, um Ley-Energieknoten zu erreichen und aus ihrem Ruhezustand zu wecken.",["race:Undead"]="Für die Verlassenen bedeutet die Bergung des Stabs, Dalarans wachsende Kontrolle über die magischen Reserven des Silberwalds einzudämmen und ihre westlichen Grenzen zu sichern."},sec={{t="Trophäe des Grabmals",b="Schattenpriester Allister fürchtete Dalarans wachsenden magischen Einfluss, befahl deshalb Ataerics Tod und verlangte den Stab. Nachdem Ataeric erschlagen und der Stab geborgen worden war, fielen die gebündelten Ley-Energien wieder in einen Ruhezustand zurück.\n\nDie Ankunft des Stabs im Grabmal markierte einen klaren Sieg über Dalarans Bestrebungen. Die Macht schlummert noch immer in der Erde, und die Verlassenen bleiben wachsam."},{t="Ein Leiter für Ley-Magie",b="Erzmagier Ataeric trug den Stab, um Ley-Energien im südlichen Silberwald zu lenken. Dalaran entsandte ihn, um einen uralten Ley-Energieknoten nahe den Grenzen seines Gebiets zu erwecken. Mit dem Stab konnte er die gewaltigen Ströme um sich herum verweben, wodurch der Erzmagier nahe gelegene Siedlungen der Verlassenen ernsthaft bedrohte."}},faq={{q="Wem gehört Ataerics Stab?",a="Erzmagier Ataeric, ein hochrangiger Magier Dalarans, der im Silberwald stationiert war, besaß den Stab. Dort sollte er die Erweckung eines mächtigen Ley-Energieknotens beaufsichtigen.",al={"wem gehört ataerics stab","ataeric besitzer","wer hat diesen stab fallen gelassen"}},{q="Warum will Schattenpriester Allister Ataerics Stab?",a="Schattenpriester Allister im Grabmal will den Stab als Beweis dafür, dass Erzmagier Ataeric tot ist. Außerdem will er Dalarans Bemühungen vereiteln, die Ley-Linien der Region zu beherrschen.",al={"warum will allister den stab","zweck des stabs im grabmal","wer nimmt den stab"}},{q="Was geschieht, sobald Erzmagier Ataeric der Stab abgenommen wird?",a="Wenn Ataeric erschlagen und der Stab an sich genommen wird, zerstreuen sich die von Dalaran verwobenen Ley-Energien und fallen in einen Ruhezustand zurück. Die unmittelbare magische Bedrohung für die Verlassenen endet.",al={"was geschieht mit der ley-linie","nach dem sieg über ataeric"}},{q="Wo findet man Ataerics Stab?",a="Erzmagier Ataerics Leichnam liegt zwischen anderen Magiern und Wächtern Dalarans im südlichen Silberwald, nahe Dalarans Stellungen. Der Stab wird von seinem Leichnam geborgen.",al={"wo findet man ataerics stab","ataeric fundort"}}},fp="15,152,23.378.0,22.298.1,35.152.1,53.171.0,59.162.1,31.160.0"}
P.entries["item:atal-ai-artifact"] = {n="Atal'ai Artifact",s="Atal'ai-Artefakte liegen verstreut im Tränenteich rund um den versunkenen Tempel von Atal'Hakkar. Fel'zerul sucht nach ihnen, um mehr über die Magie zu erfahren, die die Atal'ai dort praktizierten.",h="Atal'ai-Artefakte liegen verstreut im Tränenteich rund um den versunkenen Tempel von Atal'Hakkar.",kw={"atal'ai","atal'ai-artefakt","fel'zerul","tränenteich","steinard","sümpfe des elends","der tempel von atal'hakkar","trollmagie"},ang={["faction:Horde"]="Als Mitglied der Horde bittet Fel'zerul Euch, den versunkenen Tempel zu untersuchen und die mächtige Magie der Atal'ai zu erforschen."},sec={{t="Relikte im Teich",b="Dunkle Wasser umgeben den versunkenen Tempel von Atal'Hakkar in den Sümpfen des Elends. Atal'ai-Artefakte liegen im Tränenteich, wo Fel'zerul aus Steinard nach ihnen sucht. Die Atal'ai waren dunkle Zauberwirker, und die Magie in ihrem Tempel war mächtig. Diese Relikte könnten Fel'zerul helfen zu verstehen, was die Trolle erreichen wollten."}},faq={{q="Wo sind die Atal'ai-Artefakte?",a="Atal'ai-Artefakte liegen im Tränenteich rund um den versunkenen Tempel von Atal'Hakkar in den Sümpfen des Elends.",al={"wo artefakte finden","artefaktfundort","artefakte im tränenteich"}},{q="Wer will die Artefakte?",a="Fel'zerul in Steinard sucht nach Atal'ai-Artefakten, um die von den Atal'ai verwendete Magie zu studieren.",al={"wer braucht sie","fel'zeruls artefakte","wer will das artefakt"}},{q="Wozu dienen die Artefakte?",a="Fel'zerul hofft, dass die Artefakte ihm helfen zu verstehen, was die Atal'ai-Trolle mit ihrer mächtigen Magie erreichen wollten.",al={"artefaktzweck","warum artefakte sammeln","was verraten sie"}},{q="Wer waren die Atal'ai?",a="Die Atal'ai waren ein Trollstamm, der für die Ausübung verbotener Magie bekannt war.",al={"atal'ai-trolle","atal'ai-stamm","trolle als dunkle zauberwirker"}}},fp="16,163,18.327.0,32.107.0,24.91.0,27.131.0,21.72.0"}
P.entries["item:athrikus-narassin-s-head"] = {n="Athrikus Narassins Kopf",s="Am Turm von Althalaxx beweist Athrikus Narassins Kopf, dass der uralte Hexenmeister tot ist. Das dämonische Wirken des Zirkels im Norden der Dunkelküste wurde gestört.",h="Am Turm von Althalaxx beweist Athrikus Narassins Kopf, dass der uralte Hexenmeister tot ist.",kw={"althalaxx","athrikus narassin","kultisten","dunkelküste","teufelsmagie","abgetrennter kopf","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister wisst Ihr, dass Athrikus durch seine Beherrschung der Teufelskräfte ein gefährlicher Gegner war. Sein leichtsinnig offenes Auftreten in Althalaxx wurde ihm zum Verhängnis.",["race:NightElf"]="Als Nachtelf seht Ihr, wie Athrikus Narassins Tod uralte Ruinen der Kaldorei an Kalimdors nördlichen Küsten von dämonischer Verderbnis befreit."},sec={{t="Verderbnis über Althalaxx",b="Athrikus Narassin führte vom Turm von Althalaxx aus finstere Zauberer an. Sein Zirkel praktizierte entlang der Dunkelküste Teufelsmagie und beschwor Dämonen, die die Wildnis bedrohten. Seinen Kopf zu holen, zerschlägt ihre Führung und drängt ihren Einfluss in der Region zurück. Doch die Verderbnis bleibt, und das Land wird wachsame Augen brauchen."}},faq={{q="Wer war Athrikus Narassin?",a="Athrikus Narassin war ein uralter, mächtiger Hexenmeister, der die Kultisten im Turm von Althalaxx im Norden der Dunkelküste anführte. Von der Spitze des Turms aus leitete er die dämonischen Rituale des Zirkels.",al={"wer ist athrikus","athrikus hintergrund","wer ist der hexenmeister"}},{q="Warum wird sein Kopf benötigt?",a="Späher der Allianz, die den Turm von Althalaxx beobachten, brauchen einen Beweis, dass der Meisterhexenmeister tot ist. Sein abgetrennter Kopf bestätigt seinen Tod und den Schlag gegen die dämonischen Streitkräfte.",al={"warum den kopf holen","athrikus kopf zweck","wozu dient der kopf"}},{q="Wo befindet sich Athrikus Narassin?",a="Athrikus Narassin befindet sich auf der Spitze des Turms von Althalaxx im Norden der Dunkelküste. Seine ergebenen Kultisten und beschworenen Dämonen bewachen ihn.",al={"wo ist athrikus zu finden","athrikus aufenthaltsort","turm von althalaxx spitze"}},{q="Beseitigt sein Tod die dämonische Bedrohung vollständig?",a="Athrikus Narassins Tod trifft die finsteren Ritualisten schwer und zerschlägt ihre laufenden Unternehmungen. Doch die dämonischen Streitkräfte könnten sich erneut sammeln, und die Dunkelküste wird weiterhin verteidigt werden müssen.",al={"sind die dämonen fort","ist der turm gereinigt","wurde der kult besiegt"}}},fx={["5ecacf9e"]={q="Was ist Athrikus Narassins Kopf?",a="Es ist der abgetrennte Kopf von Athrikus Narassin, einem uralten Hexenmeister der Nachtelfen, der die dunklen Mächte befehligt, die sich im The Tower of Althalaxx verschanzt haben. Ihr nehmt ihn als unwiderlegbaren Beweis dafür, dass der Anführer des lokalen Kults erschlagen wurde.",al={"was ist athrikus kopf","athrikus narassin kopf"}},["639f8902"]={q="Woher stammt Athrikus Narassins Kopf?",a="Er wird direkt von der Spitze des The Tower of Althalaxx im nördlichen Dunkelküste geholt. Athrikus Narassin residiert auf dem Gipfel des zerstörten Bauwerks, umgeben von seinen gefährlichsten Hexenmeistern und beschworenen Teufelsdienern, bis er niedergestreckt wird.",al={"woher kam athrikus kopf","wo bekommt man athrikus kopf","wer machte athrikus kopf"}}},fp="24,154,21.323.1,26.189.1,23.170.0,35.135.1,57.180.0"}
P.entries["item:azure-agate"] = {n="Azure Agate",s="Boulderfist-Schamanen nahe dem Turm von Arathor haben Azure Agates aus dem Turm gestohlen. Lehrling Kryten braucht einen in der Zuflucht, um ihn als Schlüssel für die Verteidigungsanlagen zu verzaubern.",h="Boulderfist-Schamanen nahe dem Turm von Arathor haben Azure Agates aus dem Turm gestohlen.",kw={"edelstein","lehrling kryten","arathihochland","azure agate","boulderfist-schamane","die zuflucht","stromgarde","der turm von arathor"},sec={{t="Ein Edelstein für den Turm",b="In der Zuflucht braucht Lehrling Kryten einen Azure Agate von den Boulderfist-Schamanen in Burg Stromgarde. Die Schamanen haben die Edelsteine aus dem Turm von Arathor gestohlen, dessen Verteidigungsanlagen gegen die Oger in der Nähe aktiviert werden müssen. Bringt Kryten einen Edelstein, und er wird ihn so verzaubern, dass er als Schlüssel dienen kann."}},faq={{q="Wo finde ich einen Azure Agate?",a="Boulderfist-Schamanen in Burg Stromgarde im Arathihochland haben Azure Agates.",al={"azure agate fundort","wo edelstein","edelstein finden"}},{q="Wer braucht den Azure Agate?",a="Lehrling Kryten in der Zuflucht braucht einen Azure Agate.",al={"wer will ihn","wem den edelstein geben","kryten edelstein"}},{q="Wozu dient der Edelstein?",a="Kryten verzaubert den Azure Agate, damit er als Schlüssel für die Verteidigungsanlagen des Turms von Arathor dienen kann.",al={"zweck des edelsteins","wozu dient er","warum edelstein"}},{q="Warum braucht Kryten ihn?",a="Die Verteidigungsanlagen des Turms von Arathor müssen aktiviert werden, um den Ogern in der Umgebung standzuhalten. Kryten braucht einen Azure Agate, den er als Schlüssel verzaubern kann.",al={"warum kryten den edelstein braucht","verteidigungsanlagen des turms","oger am turm"}}},fp="11,168,19.287.0,32.83.0,26.56.0,22.92.0,24.136.0"}
P.entries["item:bag-of-empty-ooze-containers"] = {n="Tasche mit leeren Schlammbehältern",s="In Eisenschmiede stellt Laris Bummelritzel leere Gläser für seine Erforschung der Schlämme Azeroths bereit. Sie sollen sauberen Schlamm aufnehmen, der in der Wildnis gesammelt wird.",h="In Eisenschmiede stellt Laris Bummelritzel leere Gläser für seine Erforschung der Schlämme Azeroths bereit.",kw={"tasche mit leeren schlammbehältern","empty pure sample jar","eisenschmiede","laris bummelritzel","schlammbehälter","reines probenglas","schlamm"},ang={["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr Laris Bummelritzel bei seiner ökologischen Forschung in Eisenschmiede helfen. Bringt ihm Proben aus ungezähmten Gegenden wie dem Un'Goro-Krater.",["race:Gnome"]="Als Gnom könnt Ihr den Einfallsreichtum hinter diesen haltbaren, chemikalienbeständigen Gläsern erkennen. Sie ermöglichen Forschern den sicheren Transport gefährlicher, ätzender Proben von Wildlebewesen."},sec={{t="Forscherausrüstung für den Feldeinsatz",b="Laris Bummelritzel erforscht die seltsame Biologie der Schlämme Azeroths. Er entdeckte, dass sie die Verderbnis ihrer Umgebung rasch aufnehmen, darunter auch die verseuchten Rückstände des Teufelswalds. Deshalb gab er robuste Gläser in Auftrag, die säurehaltige Proben aufnehmen können, ohne ihnen zu schaden. Die Tasche enthält genügend Gläser, um sauberen Schlamm in wilden Regionen zu sammeln, besonders im Un'Goro-Krater, wo uralte klebrige Schlämme frei von dämonischer Verderbnis leben."}},faq={{q="Was befindet sich in der Tasche mit leeren Schlammbehältern?",a="Die Tasche enthält zehn Empty Pure Sample Jars. Ihr Glas kann ätzenden Schlamm aufnehmen, ohne eine Probe zu beschädigen oder zu verunreinigen.",al={"was ist in der tasche","tascheninhalt","inhalt der schlammbehälter"}},{q="Wer hat diese Behälter bereitgestellt?",a="Laris Bummelritzel, ein Gnomenforscher in der Hall of Explorers in Eisenschmiede, hat die Behälter bereitgestellt. Er erforscht, wie sich Schlämme an ihre Umgebung anpassen.",al={"wer gibt die schlammtasche","laris bummelritzel tasche","wer gibt die tasche mit leeren schlammbehältern"}},{q="Für welche Art von Schlamm sind diese Gläser bestimmt?",a="Die Gläser sind für reinen, unverdorbenen Schlamm bestimmt. Ihr könnt unberührten Schlamm von den klebrigen Schlämmen des Un'Goro-Kraters sammeln, anders als von den verseuchten Exemplaren im Teufelswald.",al={"welcher schlamm kommt in die gläser","ziel für reines probenglas","wo gläser füllen"}},{q="Warum braucht Laris reine Schlammproben?",a="Laris braucht reinen Schlamm, um zu erforschen, wie Schlämme Eigenschaften ihrer Umgebung aufnehmen. Er kann ein unverdorbenes Exemplar mit verschmutzten Schlämmen aus verseuchten Regionen vergleichen.",al={"warum reinen schlamm sammeln","bummelritzels forschungsziel","warum reine schlämme"}}},fx={["9a2213f5"]={q="Was ist die Tasche mit leeren Schlammbehältern?",a="Dieser Sack ist ein Set mit spezialisierter Feldausrüstung, das Euch von Laris Bummelritzel in Eisenschmiede überreicht wurde. Darin befinden sich zehn leere Probengläser, die dazu dienen, flüchtige Schlammproben sicher zu seinem Arbeitsplatz zu transportieren, ohne dass der Inhalt ausläuft oder kontaminiert wird.",al={"tasche mit leeren schlammbehältern","was sind schlammbehälter","laris schlammtasche"}}},fp="28,142,24.407.0,48.119.0,30.148.0,51.161.0,38.165.0"}
P.entries["item:bag-of-water-elemental-bracers"] = {n="Bag of Water Elemental Bracers",s="Ein Beutel mit Elemental Bracers des Wasserelementars wird Erzmagier Ansirem Runenweber zur Untersuchung gebracht. Ihre magischen Rückstände könnten ihm helfen, den Fluch des Stein der Gezeiten zu untersuchen.",h="Ein Beutel mit Elemental Bracers des Wasserelementars wird Erzmagier Ansirem Runenweber zur Untersuchung...",kw={"erzmagier ansirem runenweber","beutel mit armschienen eines wasserelementars","fluch","dalaran crater","gurubashi empire","magische rückstände","stein der gezeiten","armschienen eines wasserelementars"},ang={["class:Mage"]="Als Magier bringt Ihr Ansirem ein magisches Rätsel: Rückstände auf einer Armschiene eines Wasserelementars, die ihm bei der Untersuchung des Fluchs des Stein der Gezeiten helfen könnten."},sec={{t="Die Studien eines Magiers",b="Im Dalaran Crater wurde Erzmagier Ansirem Runenweber gebeten, die Armschienen eines Wasserelementars zu untersuchen. Mindestens eine davon weist magische Rückstände auf, die seiner Ansicht nach Licht auf den Fluch des Stein der Gezeiten werfen könnten. Ansirem kennt die Legenden des Gurubashi Empire und hat einen Folianten darüber verfasst. Nun widmet er sich den Armschienen."}},faq={{q="Was ist in dem Beutel?",a="Der Beutel enthält Armschienen eines Wasserelementars, die Erzmagier Ansirem Runenweber untersuchen soll.",al={"beutelinhalt","armschienenbeutel","welche armschienen"}},{q="Wer soll die Armschienen untersuchen?",a="Erzmagier Ansirem Runenweber soll die Armschienen eines Wasserelementars im Dalaran Crater untersuchen.",al={"wer untersucht sie","ansirems armschienen","magier im dalaran crater"}},{q="Warum möchte Ansirem die Armschienen?",a="Mindestens eine Armschiene weist magische Rückstände auf, die Ansirem auf Hinweise zum Fluch des Stein der Gezeiten untersuchen kann.",al={"warum armschienen","armschienen fluch","steinfluch"}},{q="Was weiß Ansirem über den Stein?",a="Ansirem sagt, dass er einiges über den Stein der Gezeiten weiß und einen Folianten über die Legenden des Gurubashi Empire verfasst hat.",al={"ansirems wissen über den stein","überlieferungen zum stein der gezeiten","gurubashi-foliant"}}},fp="30,161,16.339.0,19.81.0,37.92.0,34.115.0,39.124.0"}
P.entries["item:balia-mah-trophy"] = {n="Balia'mah Trophy",s="Die Balia'mah Trophy ist ein Trophäenschädel der Schädelspalter aus den Ruinen im Schlingendorntal. Nezzliok verlangt ihn zusammen mit zwei weiteren Trophäen am Bubbling Cauldron im Basislager Grom'gol.",h="Die Balia'mah Trophy ist ein Trophäenschädel der Schädelspalter aus den Ruinen im Schlingendorntal.",kw={"balia'mah","ruinen von balia'mah","balia'mah-trophäe","grom'gol","nezzliok","schädelspalter","trophäenschädel","ziata'jai","zul'mamwe"},sec={{t="Ein Trophäenschädel der Schädelspalter",b="In den Ruinen von Balia'mah im Schlingendorntal bewahren die Schädelspalter Trophäenschädel in einem Haufen auf. Ein Schädel daraus ist die Balia'mah Trophy, die zusammen mit Trophäen aus Ziata'jai und Zul'Mamwe begehrt ist."}},faq={{q="Was ist die Balia'mah Trophy?",a="Die Balia'mah Trophy ist ein Schädel aus dem Trophäenhaufen der Schädelspalter bei den Ruinen von Balia'mah im Schlingendorntal.",al={"balia'mah-trophäe","balia mah schädel","trophäenschädel"}},{q="Wer will die Balia'mah Trophy?",a="Der tote Hexendoktor Nezzliok verlangt die Balia'mah Trophy zusammen mit Trophäen aus Ziata'jai und Zul'Mamwe.",al={"wer will diesen schädel","nezzliok-trophäe","trophäe für nezzliok"}},{q="Woher stammt die Balia'mah Trophy?",a="Die Balia'mah Trophy stammt aus dem Haufen mit Trophäenschädeln bei den Ruinen von Balia'mah im Schlingendorntal.",al={"wo balia'mah finden","schädel aus den ruinen von balia'mah","schädelspalter-trophäe"}},{q="Wohin gehören die drei Trophäen?",a="Nezzliok verlangt, dass die Trophäen aus Balia'mah, Ziata'jai und Zul'Mamwe am Bubbling Cauldron im Basislager Grom'gol abgelegt werden.",al={"wo schädel ablegen","trophäen am bubbling cauldron","drei schädel"}}},fp="16,194,22.201.0,29.114.0,31.110.1,35.99.0,31.124.0"}
P.entries["item:balnir-snapdragons"] = {n="Balnirlöwenmäulchen",s="Auf Balnirs Bauernhof blühen noch immer Löwenmäulchen, während die Verderbnis der Geißel nach Tirisfal vordringt. Die Verlassenen untersuchen ihre Empfindlichkeit für Magie, um die Ausbreitung dieser Verderbnis zu beobachten.",h="Auf Balnirs Bauernhof blühen noch immer Löwenmäulchen, während die Verderbnis der Geißel nach Tirisfal...",kw={"anastasia hirschbrunn","balnirs bauernhof","balnirlöwenmäulchen","mage quarter","plaguelands","tirisfal"},ang={["class:Mage"]="Als Magier der Verlassenen könnt Ihr Balnirlöwenmäulchen als Leiter für Magie untersuchen. Ihre Empfindlichkeit hilft zu messen, wie magische Seuchen die umliegenden Leylinien verzerren.",["race:Undead"]="Als Verlassener könnt Ihr mit den Blumen Eure Ostgrenze überwachen. Ihre Messwerte können Forscher der Unterstadt warnen, wenn die Verderbnis des Lich Kings Tirisfals Boden erfasst."},sec={{t="Blüten in den Ruinen",b="Balnirlöwenmäulchen blühen noch immer im Garten von Balnirs Bauernhof im östlichen Tirisfal. Das Gehöft liegt in Trümmern, seit Lordaeron fiel und die Geißel aufstieg. Im Osten grenzen die Plaguelands an Tirisfal. Die Verderbnis des Lich Kings drängt hier gegen die Region, und die Blumen bieten den Verlassenen einen Ort, um ihre Ausbreitung zu beobachten."},{t="Magische Barometer",b="Balnirlöwenmäulchen reagieren ungewöhnlich empfindlich auf atmosphärische Magie und dienen daher als lebende Barometer für magische Seuchen. Anastasia Hirschbrunn und die Magier der Verlassenen in der Unterstadt suchen frische Blumen aus den Fensterkästen des Bauernhofs. Sie schicken sie zur Untersuchung an die Royal Apothecary Society und hoffen zu messen, wie weit die Seuche des Lich Kings über die Grenze in Tirisfals Boden gesickert ist."}},faq={{q="Wo sind Balnirlöwenmäulchen zu finden?",a="Balnirlöwenmäulchen wachsen in Blumenkästen und Gartenbeeten rund um die Ruinen von Balnirs Bauernhof im östlichen Tirisfal, nahe den Westlichen Pestländern.",al={"balnirlöwenmäulchen fundort","wo sind die blumen","balnirblumen fundort"}},{q="Warum will Anastasia Hirschbrunn diese Löwenmäulchen?",a="Anastasia Hirschbrunn möchte frische Löwenmäulchen an die Apotheker der Unterstadt schicken lassen. Ihre Empfindlichkeit für latente magische Energien kann dabei helfen zu messen, ob sich die Verderbnis der Plaguelands nach Tirisfal ausbreitet.",al={"warum löwenmäulchen sammeln","balnirs bauernhof questziel","anastasia hirschbrunn löwenmäulchen"}},{q="Wer hat diese Blumen ursprünglich angebaut?",a="Balnirlöwenmäulchen wachsen im Garten von Balnirs Bauernhof, dem Stammsitz der Familie, der sie ihren Namen verdanken. Die Geißel verwüstete den Bauernhof ebenso wie das übrige ländliche Lordaeron.",al={"wer pflanzte balnirlöwenmäulchen","familie balnir löwenmäulchen"}},{q="Hat die Geißel die Balnirblumen vernichtet?",a="Nein. Löwenmäulchen wachsen noch immer im Garten von Balnirs Bauernhof. Weil sie so nahe an den Plaguelands wachsen, können Anastasia Hirschbrunns Forscher untersuchen, ob die Seuche nach Tirisfal vorgedrungen ist.",al={"hat die seuche die löwenmäulchen getötet"}}},fx={ebe2752a={q="Was sind Balnirlöwenmäulchen?",a="Balnirlöwenmäulchen sind eine unverwechselbare Blumenart, die in den Blumenkästen von The Balnir Farmstead im östlichen Tirisfal gezüchtet wird. Sie sind von Natur aus empfindlich und außergewöhnlich empfänglich für magische Energien, sodass sie latente magische Strömungen aus ihrer Umgebung absorbieren, was sie zu erstklassigen Indikatoren für die Entdeckung von Umweltkorruption in der Nähe macht.",al={"was sind balnirlöwenmäulchen","balnirlöwenmäulchen blume","balnirlöwenmäulchen lore"}}},fp="18,185,15.327.0,18.391.0,38.148.0,51.202.0,34.183.0,43.194.0"}
P.entries["item:baron-longshore-s-head"] = {n="Baron Küstenschippers Kopf",s="An der Händlerküste beweist Baron Küstenschippers Kopf, dass der Piratenkapitän tot ist. Gazlowe bietet ein Kopfgeld für identifizierbare Überreste, um Ratschets Handelsschifffahrt zu schützen.",h="An der Händlerküste beweist Baron Küstenschippers Kopf, dass der Piratenkapitän tot ist.",kw={"baron küstenschipper","kopfgeld","gazlowe","gilneas","heedless","die händlerküste","ratschet","southsea freebooters"},ang={["race:Human"]="Als Mensch könnt Ihr Baron Küstenschippers Herkunft bis nach Gilneas zurückverfolgen, jener abgeschotteten Nation, die er verließ, bevor er sich den Südmeerfreibeutern anschloss."},sec={{t="Ein Kopfgeld auf einen Freibeuter",b="Von Lagern entlang der Händlerküste südlich von Ratschet aus führte Baron Küstenschipper die Überfälle der Südmeerfreibeuter an. Sein Flaggschiff, die Heedless, bedrohte die Handelsrouten der Goblins zwischen Kalimdor und den Östlichen Königreichen. Deshalb setzte Gazlowe, Ratschets Chefingenieur, ein Kopfgeld für einen Beweis von Küstenschippers Tod aus. Die Hafenbehörde zahlt eine Geldbelohnung, wenn der Kopf des Piraten abgeliefert wird."}},faq={{q="Wer war Baron Küstenschipper?",a="Baron Küstenschipper war ein Piratenkapitän aus dem Menschenkönigreich Gilneas. Von Lagern entlang der Händlerküste südlich von Ratschet aus führte er die Südmeerfreibeuter an und terrorisierte an Bord der Heedless die Schifffahrtswege.",al={"baron küstenschipper","wer ist küstenschipper","kapitän küstenschipper"}},{q="Wer will Baron Küstenschippers Kopf?",a="Gazlowe, der Goblinanführer von Ratschet, setzte öffentlich ein Kopfgeld auf Baron Küstenschippers identifizierbare Überreste aus. Die Südmeerfreibeuter überfielen Ratschets Handelsschiffe, und Gazlowe wollte den ungestörten Handel des Hafens sichern.",al={"wer will den kopf","bei wem abgeben","gazlowe kopfgeld"}},{q="Wo ist Baron Küstenschipper zu finden?",a="Baron Küstenschipper patrouilliert durch drei Lager der Südmeerpiraten an der Küste südlich von Ratschet, unmittelbar nördlich der Feste Northwatch entlang der Händlerküste.",al={"wo ist küstenschipper","kü stenschipper aufenthaltsort","baron küstenschipper erscheinungsort"}},{q="Welches Schiff befehligte Baron Küstenschipper?",a="Baron Küstenschipper befehligte die Heedless, die Handelsschiffe auf dem großen Meer vor der Küste des Brachlands überfiel.",al={"kü stenschippers schiff","die heedless","heedless schiff"}}},fx={["0986c9c0"]={q="Was ist Baron Küstenschippers Kopf?",a="Es ist der grausige, abgetrennte Kopf von Baron Küstenschipper, einem berüchtigten Piratenkapitän aus Gilneas, der Schiffe für die Südmeerfreibeuter befehligt. Ihr nehmt ihn als unwiderlegbaren Beweis für seinen Tod an, um das Kopfgeld zu erfüllen, das in Ratschet auf ihn ausgesetzt wurde, und um sicherzustellen, dass das Steamwheedle Cartel weiß, dass der berüchtigte Plünderer ihre Handelsrouten nicht länger stören wird.",al={"baron küstenschipper kopf gegenstand","was ist dieser kopf","küstenschipper kopf hintergrundgeschichte"}}},fp="22,174,22.367.0,24.204.0,33.226.0,31.148.0,38.107.0"}
P.entries["item:barrel-of-barleybrew-scalder"] = {n="Fass mit Gerstenbräu",s="In Kharanos schickt Marleth Gerstenbräu ein Fässlein mit Gerstenbräu zur Brauerei Donnerbräu. Er will beweisen, dass seine Braukunst mit der seiner Hauptkonkurrenten, der Thunderbrews, mithalten kann.",h="In Kharanos schickt Marleth Gerstenbräu ein Fässlein mit Gerstenbräu zur Brauerei Donnerbräu.",kw={"bier","gerstenbräu","brauerei","dun morogh","kharanos","marleth","starkbier","thunderbrew"},ang={["class:Rogue"]="Als Schurke könnt Ihr eine Kellerwache ablenken und schwere Schmuggelware in ein bewachtes Versteck schleusen. Hier bekommt Ihr einen Vorgeschmack auf zwergische Heimtücke, bei der wenig auf dem Spiel steht.",["race:Dwarf"]="Als Zwerg kennt Ihr das Bierbrauen als Kunst und als blutigen Wettkampf zugleich. Die Rivalitäten um Rezepte reichen in Dun Morogh bis tief in den Keller."},sec={{t="Bittere Fehde in Dun Morogh",b="Die Thunderbrews und die Gerstenbräus wetteifern in Dun Morogh erbittert um die Braukunst. Die Thunderbrews sind für ihre geschäftige Brauerei in Kharanos bekannt. Marleth Gerstenbräu will nicht in ihrem Schatten leben. Also braut er feuriges Starkbier, um zu zeigen, dass seine Rezepte mit ihren mithalten können. Er hofft, dass alle, die es kosten, erkennen, dass die Thunderbrews die Kunst edler Zwergengetränke nicht für sich gepachtet haben."},{t="Heimlichkeiten im Keller",b="Das Fass ist für die Keller unter der Brauerei Donnerbräu bestimmt. Dort soll es ein Fässlein Donnerbier ersetzen, das hier sehr beliebt ist. Verletzter Stolz hat einen Streich hervorgebracht, weder Gift noch Zerstörung. Die nächste oben ausgeschenkte Charge wird heimlich Gerstenbräus kräftiges Starkbier sein."}},faq={{q="Was enthält das Fass mit Gerstenbräu?",a="Das Fass enthält Marleth Gerstenbräus unverwechselbares Starkbier, ein kräftiges Zwergenbier, das mit den berühmten Rezepten der Familie Thunderbrew mithalten soll.",al={"gerstenbräu starkbier inhalt","welche biersorte","was ist starkbier"}},{q="Warum will Marleth dieses Fass austauschen lassen?",a="Marleth räumt ein, dass die Thunderbrews gute Getränke brauen, doch er will ihnen Bescheidenheit beibringen. Er hofft, dass die Gäste im Keller unwissentlich sein Bier kosten und Gerstenbräus Braukunst ebenso gut finden, wenn nicht sogar besser.",al={"warum fässer tauschen","bitter rivals grund","warum schmuggelt marleth bier"}},{q="Wohin kommt dieses Fass?",a="Das Fass kommt in den Keller unter der Brauerei Donnerbräu in Kharanos. Es nimmt in den Fassregalen den Platz eines Fässleins Donnerbier ein, das als Nächstes angezapft werden soll.",al={"wohin kommt das fass","starkbier fass standort","brauereikeller"}},{q="Soll das Bier jemandem schaden?",a="Nein. Das Bier ist ein starkes Zwergenbier, das mit dem der Thunderbrews mithalten soll. Die Rivalität der Familien ist erbittert, doch sie entspringt beruflichem Stolz, nicht Bosheit.",al={"ist das starkbier vergiftet","ist es gift","schadet es jemandem"}}},fx={["9f414f7e"]={q="Was ist das Fass mit Gerstenbräu?",a="Es ist ein Fass mit starkem Bier, das von Marleth Gerstenbräu hergestellt wurde. Anstatt durch den normalen Handel verkauft zu werden, dient dieses spezielle Fass als Instrument in einer Brauereirivalenz und soll heimlich in den Vorrat eines Konkurrenten eingeschmuggelt werden, um ahnungslose Trinker für sich zu gewinnen.",al={"was ist gerstenbräu","fass mit gerstenbräu"}},["00d1bcdd"]={q="Woher stammt das Fass mit Gerstenbräu und wer hat es hergestellt?",a="Das Fass wurde von Marleth Gerstenbräu gebraut und bereitgestellt. Stolz auf das Handwerk seiner Familie, erfand Marleth das Rezept, um zu beweisen, dass die Gerstenbräus den Ruf der rivalisierenden Thunderbrew-Familie erreichen oder übertreffen können.",al={"wer machte gerstenbräu","woher kam gerstenbräu","gerstenbräu ursprung"}}},fp="28,171,27.356.0,24.282.1,48.132.0,42.212.0,26.154.0,33.153.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="Fass mit Schimmerstarkbier",s="In Dun Morogh ist ein Fass Shimmer Stout für die Bergwache bestimmt. Rejold Gerstenbräu schickt sein experimentelles Bier zu den hohen Pässen, wo es Trinkern zufolge ihre Sicht erhellt.",h="In Dun Morogh ist ein Fass Shimmer Stout für die Bergwache bestimmt.",kw={"fass mit schimmerstarkbier","dun morogh","zwergenbier","loch modan","gebirgsjäger gerstenbräu","rejold gerstenbräu","shimmer stout"},ang={["profession:Cooking"]="Als Koch wisst Ihr, dass zwergische Brauer mit widerstandsfähigen Zutaten aus den Bergen und kräftiger Gärung experimentieren. Sie brauen Biere für beißende Kälte.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass das Brauen ein Grundpfeiler der Gesellschaft von Eisenschmiede ist. Einem wachhabenden Verwandten ein frisch perfektioniertes Starkbier zu bringen, ist eine ehrenvolle Tradition der Berge."},sec={{t="Der Stolz eines Brauers",b="Rejold Gerstenbräu braute Shimmer Stout aus Zutaten, die in ganz Dun Morogh gesammelt wurden. Das Rezept ist das neueste Werk der Familie Gerstenbräu. Ihre zwergischen Brauer wetteifern darum, Biere zu brauen, die kräftig genug für die Kälte der Berge sind. Rejold braute dieses Starkbier, um den Magen zu wärmen und die Sinne derer zu schärfen, die im Wind Wache halten."},{t="Vorräte für die Wache",b="Das Fass ist für Gebirgsjäger Wellart Barleybrew am südlichen Turm auf dem Pass nach Loch Modan bestimmt. Die Gebirgsjäger dort ertragen Kälte und lange Wachschichten zwischen Scharmützeln mit Troggs und wilden Tieren. Ein Fass Bier aus der Familienbrauerei bringt einen Geschmack der Heimat. Seine Wirkung kann einem müden Wachposten das Gefühl geben, im Dunkeln klar sehen zu können."}},faq={{q="Was ist im Fass mit Schimmerstarkbier?",a="Das Fass enthält Shimmer Stout, ein experimentelles Zwergenbier, das Rejold Gerstenbräu gebraut hat. Trinker sagen, seine kräftige Wirkung erhelle ihre Sicht.",al={"was ist shimmer stout","was für ein bier ist das","shimmer stout getränk"}},{q="Wer hat dieses Fass Starkbier gebraut?",a="Rejold Gerstenbräu hat das Starkbier gebraut. Er gehört zur Familie Gerstenbräu aus Dun Morogh und hat Zeit darauf verwendet, das Rezept zu verfeinern, um seine Verwandten zu beeindrucken.",al={"wer hat shimmer stout gebraut","shimmer stout brauer","rejold gerstenbräu"}},{q="Für wen ist dieses Fass bestimmt?",a="Das Fass ist für Rejolds Bruder, Gebirgsjäger Wellart Barleybrew, bestimmt. Wellart bewacht den südlichen Turm an der Straße nach Loch Modan.",al={"wer bekommt das fass","wohin geht das starkbier","wellart barleybrew"}},{q="Welche Wirkung hat Shimmer Stout auf jemanden, der es trinkt?",a="Shimmer Stout versetzt Trinker in einen kräftigen Rausch und gibt ihnen das Gefühl, in völliger Dunkelheit sehen zu können. Seine Wirkung macht es bei wachsamen Gebirgsjägern beliebt.",al={"shimmer stout wirkung","kann man dadurch im dunkeln sehen","was bewirkt shimmer stout"}}},fp="23,184,16.304.0,22.318.0,39.141.0,30.142.0,29.136.0,61.155.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="Fass mit Donnerbier",s="In Kharanos ist der Brauerei Donnerbräu ein Fass mit Donnerbier abhanden gekommen. Marleths Gerstenbräu sollte es ersetzen und machte aus einer Brauerfehde ein falsches Spiel.",h="In Kharanos ist der Brauerei Donnerbräu ein Fass mit Donnerbier abhanden gekommen.",kw={"fass mit donnerbier","bräuhall","dun morogh","kharanos","marleth gerstenbräu","donnerbier","thunderbrew"},ang={["class:Rogue"]="Als Schurke erkennt Ihr, welches Geschick es erfordert, in einen bewachten Keller zu schleichen und schwere Bierfässer auszutauschen, ohne Alarm auszulösen.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass das Brauen sowohl im Geschäft als auch in der Politik großes Gewicht hat. Das geschätzte Fass eines rivalisierenden Clans in dessen eigenem Keller auszutauschen, ist eine dreiste Beleidigung."},sec={{t="Ein bitterer Tausch",b="Die Familie Thunderbrew aus Kharanos und die Gerstenbräus aus Bräuhall sind erbitterte Rivalen. Marleth Gerstenbräu versuchte, ein Fass seines Gerstenbräus in den Keller der Familie Donnerbräu zu schmuggeln. Er hoffte, ihre Gäste würden sein Gebräu bevorzugen. Das Fass mit Donnerbier wurde bei dem Austausch entwendet, als Beweis dafür, dass der Tausch trotz der örtlichen Wachen gelungen war."}},faq={{q="Was befindet sich in diesem Fass?",a="Das Fass enthält Donnerbier, das berühmte Starkbier, das die Familie Thunderbrew in Kharanos braut. In ganz Dun Morogh ist es als kräftiges Zwergenbier bekannt.",al={"donnerbier inhalt","was ist donnerbier"}},{q="Woher stammt dieses Fass?",a="Das Fass stammt aus dem Lagerkeller der Kharanos Distillery. Es wurde während der heimlichen Lieferung von Marleths Konkurrenzgebräu entwendet.",al={"woher bekommt man es","donnerbier fundort"}},{q="Wer will dieses Fass haben?",a="Marleth Gerstenbräu will das Fass haben. Er befindet sich im westlich gelegenen Bräuhall und erwartet es als Beweis dafür, dass sein Brühheißer Gerstenbräu zwischen den Fässern der Familie Thunderbrew untergebracht wurde.",al={"zu wem bringt man donnerbier","marleth gerstenbräu quest"}},{q="Warum wurde das Fass entwendet?",a="Marleth wollte einen Beweis dafür, dass jemand in den Keller der Familie Thunderbrew eingedrungen war, sich an der Brauereiwache vorbeigeschlichen und die Vorräte seiner Rivalen sabotiert hatte.",al={"warum donnerbier stehlen","bitter rivals geschichte"}}},fp="21,170,14.341.0,27.148.0,32.132.0,22.160.0,25.134.0"}
P.entries["item:barrow-key"] = {n="Grabhügelschlüssel",s="Tief unter dem Steinkrallengipfel hüten drei druidische Schlüssel den uralten Hort des Krallenbaus. Der Grabhügelschlüssel liegt im Bau unter Verschluss.",h="Tief unter dem Steinkrallengipfel hüten drei druidische Schlüssel den uralten Hort des Krallenbaus.",kw={"grabhügelschlüssel","klauenschlüssel","torhüterschlüssel","schlüssel des schläfers","der steinkrallengipfel","krallenbau","hort des krallenbaus","der bau"},ang={["class:Druid"]="Als Druide wisst Ihr, dass der Grabhügelschlüssel zu einem uralten Sicherungsritual gehört. Die Druiden des Krallenbaus entwickelten es, um heilige Besitztümer in ihrem unterirdischen Heiligtum zu schützen.",["faction:Horde"]="Agenten der Horde im Steinkrallengebirge pressen gefangenen Nachtelfen Informationen ab, um den Grabhügelschlüssel zu finden und den privaten Hort der Druiden zu plündern."},sec={{t="Die Sicherung eines Wächters",b="Nachtelfische Druiden versahen die unterirdischen Grabhügel des Krallenbaus mit Schutzzaubern, um Eindringlinge von ihren Relikten fernzuhalten. Inmitten der Gänge ruht der Grabhügelschlüssel in einem verborgenen Versteck. Wer ihn erreichen will, muss die mehrschichtigen Schutzvorrichtungen der Druiden überwinden.\n\nNur der Torhüterschlüssel öffnet das Versteck. Ein Suchender muss wissen, wie diese Schutzvorrichtungen funktionieren, um den Grabhügelschlüssel an sich zu nehmen."},{t="Den Hort öffnen",b="Der Grabhügelschlüssel, der Klauenschlüssel und der Schlüssel des Schläfers passen in drei geschnitzte Schlüssellöcher eines Steinaltars tief im Krallenbau. Dreht Ihr alle drei zugleich, schwinden die Schutzzauber. Dann sind die druidischen Relikte im verborgenen Hort zum Greifen nah."}},faq={{q="Wofür wird der Grabhügelschlüssel verwendet?",a="Der Grabhügelschlüssel öffnet gemeinsam mit dem Klauenschlüssel und dem Schlüssel des Schläfers den Hort des Krallenbaus. Die steinerne Truhe birgt geschützte druidische Relikte tief im Steinkrallengipfel.",al={"grabhügelschlüssel zweck","was öffnet der grabhügelschlüssel","verwendung des grabhügelschlüssels"}},{q="Wo ist der Grabhügelschlüssel versteckt?",a="Der Grabhügelschlüssel liegt in einem Grabhügelversteck tief in den gewundenen Tunneln des Krallenbaus auf dem Steinkrallengipfel unter Verschluss. Das Versteck ähnelt einer verborgenen Wandfackel.",al={"grabhügelschlüssel fundort","wo ist der grabhügelschlüssel","grabhügelschlüssel finden"}},{q="Wie öffnet Ihr das Versteck mit dem Grabhügelschlüssel?",a="Ihr braucht den Torhüterschlüssel, um das Versteck zu öffnen. Die Druiden versteckten ihn in einer kleinen Laterne nahe dem Haupteingang des Krallenbaus.",al={"grabhügelversteck öffnen","grabhügelschlüssel freischließen","torhüterschlüssel grabhügel"}},{q="Wer hat den Grabhügelschlüssel im Krallenbau versteckt?",a="Nachtelfische Druiden, die im Steinkrallengipfel leben, ersannen die Schutzvorrichtungen des Krallenbaus, um ihre mächtigen Artefakte vor feindlichen Händen zu bewahren. Sie verbargen die Schlüssel in verschiedenen Teilen des Baus.",al={"wer hat den grabhügelschlüssel hergestellt","wer hat die schlüssel im krallenbau versteckt"}}},fx={["6b9fc30c"]={q="Was ist der Grabhügelschlüssel?",a="Der Grabhügelschlüssel ist einer von drei verzauberten Schlüsseln, die von den Nachtelf-Druiden im Krallenbau auf dem Steinkrallengipfel gefertigt wurden. Er dient als Teil einer komplexen Sicherheitsvorkehrung, die ihre wertvollsten und mächtigsten Relikte davor schützen soll, in Feindeshand zu geraten.",al={"was ist der grabhügelschlüssel","infos zum grabhügelschlüssel","krallenbau grabhügelschlüssel"}},["17616df0"]={q="Warum will jemand den Grabhügelschlüssel?",a="Streitkräfte der Horde im Steinkrallengebirge suchen den Grabhügelschlüssel zusammen mit seinen Schwesterschlüsseln, dem Klauenschlüssel und dem Schlüssel des Schläfers. Gemeinsam brechen die drei Schlüssel die druidischen Schutzsiegel, die den Hort des Krallenbaus verschließen, und öffnen so das Versteck mit mächtigen Gegenständen, die tief im Grabhügel aufbewahrt werden.",al={"warum den grabhügelschlüssel finden","warum den grabhügelschlüssel haben wollen","wer will den grabhügelschlüssel"}}},fp="10,128,22.337.0,19.242.1,32.165.0,31.150.0,52.121.0,43.183.0"}
P.entries["item:bartleby-s-mug"] = {n="Bartlebys Becher",s="In Sturmwind bittet Burlguard einen jungen Krieger, Bartlebys Becher dessen starrsinnigem Besitzer abzuringen. Bartleby gibt ihn erst heraus, nachdem er bei einer Kneipenschlägerei besiegt wurde.",h="In Sturmwind bittet Burlguard einen jungen Krieger, Bartlebys Becher dessen starrsinnigem Besitzer abzuringen.",kw={"bartleby","bartlebys becher","burlguard","sturmwind","kneipenschlägerei","kriegerausbildung"},ang={["class:Warrior"]="Als Krieger der Allianz verdient Ihr Euch Bartlebys Becher, indem Ihr ihn ihm abringt. Der Kampf verlangt Zähigkeit und Kraft, wenn Worte versagen."},sec={{t="Der Preis eines Raufbolds",b="Bartleby klammert sich an seinen geliebten Becher, bis er in einem Kampf besiegt wird. Selbst dann leert er ihn bis auf den letzten Tropfen, bevor er ihn übergibt. Der Becher beweist, dass der Krieger einen unkooperativen Gegner zum Aufgeben zwingen konnte."}},faq={{q="Wozu dient Bartlebys Becher?",a="Ein Krieger nimmt Bartlebys Becher als Siegesbeweis bei einer Ausbildungsprüfung an sich. Ihn dem Ausbilder zu bringen, zeigt, dass der Krieger einen starrsinnigen Kneipenraufbold besiegen und zur Herausgabe des Bechers zwingen konnte.",al={"bartlebys becher zweck","warum wird bartlebys becher benötigt","was bewirkt der becher"}},{q="Wem gehört der Becher ursprünglich?",a="Bartleby gehört der Becher. Der streitsüchtige Trunkenbold verbringt seine Zeit mit Trinken und Raufen und gibt ihn erst heraus, nachdem ein angehender Krieger ihn im Faustkampf besiegt hat. Zuerst trinkt er aus.",al={"wer ist bartleby","bartlebys besitzer","wer hat den becher"}},{q="Wer verlangt Bartlebys Becher?",a="Burlguard verlangt Bartlebys Becher. Der Kriegerlehrer in Sturmwind beobachtet die Schlägerei und fordert den Becher als Beweis, bevor er die Kampfausbildung des Kriegers fortsetzt.",al={"wer will den becher","wem bartlebys becher geben","bartlebys becher abgeben"}}},fx={["481c5411"]={q="Was ist Bartlebys Becher?",a="Bartlebys Becher ist das persönliche Trinkgefäß von Bartleby, einem raufenden Schankhausbesucher in Sturmwind. Der Becher dient als konkreter Beweis für die Fähigkeiten eines jungen Kriegers – er wurde von Bartleby erst übergeben, nachdem er im Kampf gründlich besiegt wurde, und erst nachdem er sich die Zeit genommen hatte, jeden letzten Tropfen darin auszutrinken.",al={"was ist bartlebys becher","bartleby becher","becher von bartleby"}},a3659338={q="Warum will Burlguard Bartlebys Becher?",a="Burlguard verlangt den Becher als physischen Beweis dafür, dass Ihr Euch behauptet und Bartleby in einer Schlägerei im Schankhaus besiegt habt. Den geliebten Becher eines engagierten Trinkers zu nehmen, ist keine leichte Aufgabe; ihn aufzugeben beweist, dass Ihr Bartleby mit Euren Fäusten überzeugt habt und bereit seid, Euer Kriegertraining fortzusetzen.",al={"warum will man bartlebys becher","warum will burlguard den becher","burlguard becher zweck"}}},fp="14,160,17.203.0,32.196.0,28.185.0,28.166.0"}
P.entries["item:bathran-s-hair"] = {n="Bathranshaar",s="In den Ruinen von Bathrans Schlupfwinkel im nordwestlichen Eschental bleibt Bathranshaar ein seltenes Kraut. Heiler der Nachtelfen schätzen es gegen Leiden des Fleisches und des Geistes.",h="In den Ruinen von Bathrans Schlupfwinkel im nordwestlichen Eschental bleibt Bathranshaar ein seltenes Kraut.",kw={"eschental","bathranshaar","bathrans schlupfwinkel","maestras posten","orendil rundblatt","pflanzenbündel"},ang={["profession:Herbalism"]="Ausgebildete Kräuterkundige können Bathranshaar leichter finden. Ihr geübter Blick für Wildpflanzen hilft ihnen, verborgene Pflanzenbündel zwischen den Trümmern aufzuspüren.",["race:NightElf"]="Für die Kaldorei erschweren Verlassene in den Ruinen die Bewahrung ihrer uralten Heimat, in der Heilpflanzen wie Bathranshaar wachsen."},sec={{t="Ein Heilmittel für den Geist",b="Bathranshaar wächst zwischen den uralten Ruinen nördlich von Maestras Posten, wo Heiler der Nachtelfen es seit Langem schätzen. Gewöhnliche Kräuter lindern körperliche Wunden. Bathranshaar soll auch den Geist wiederherstellen. Als ein junger Nachtelf in Astranaar schwer erkrankt, sucht der Kräuterkundige Orendil Rundblatt die seltene Pflanze, um ein Heilmittel zuzubereiten."},{t="Sammeln in den Ruinen",b="Verlassene wurden in Bathrans Schlupfwinkel nahe der Grenze zur Dunkelküste gesichtet. Ihre Anwesenheit beunruhigt Orendil Rundblatt. Bathranshaar liegt in weggeworfenen Pflanzenbündeln und unter Laubhaufen, die über die Ruinen verstreut sind, was die Suche erschwert."}},faq={{q="Wofür wird Bathranshaar verwendet?",a="Heiler der Nachtelfen verwenden Bathranshaar gegen schwere Leiden, die über gewöhnliche Krankheiten hinausgehen. Orendil Rundblatt verarbeitet es zu einem Heiltrank für ein sterbendes Kind, dessen Geist dahinschwindet.",al={"was bewirkt bathranshaar","bathranshaar zweck","bathranshaar verwendung"}},{q="Wo wächst Bathranshaar?",a="Bathranshaar wächst in Bathrans Schlupfwinkel, einer uralten Siedlungsruine im nördlichen Eschental. Die Ruinen liegen östlich der Hauptstraße, die nach Norden in die Dunkelküste führt.",al={"wo findet man bathranshaar","bathranshaar fundort","wo ist bathranshaar"}},{q="Warum interessieren sich die Verlassenen für Bathrans Schlupfwinkel?",a="Orendil Rundblatt erfährt, dass sich Verlassene in Bathrans Schlupfwinkel aufhalten, und findet ihre Anwesenheit beunruhigend, doch was sie dort wollen, wird nicht erklärt. Anderswo im Eschental berichten Nachtelfen von Verlassenen bei Ruinen und Grabhügeln und fürchten, dass sie Krankheiten im ganzen Wald verbreiten wollen.",al={"warum sind untote in bathrans schlupfwinkel","verlassene in bathrans schlupfwinkel","untote bathran"}},{q="Wer ist Orendil Rundblatt?",a="Orendil Rundblatt ist ein Kräuterkundiger in Maestras Posten im westlichen Eschental. Er erforscht einheimische Pflanzen und bereitet Arzneien für Reisende und verwundete Verteidiger des Waldes zu.",al={"orendil rundblatt","wer will bathranshaar"}}},fx={b940f392={q="Was ist Bathranshaar?",a="Bathranshaar ist ein seltenes, empfindliches Kraut, das inmitten der alten Ruinen von Bathrans Schlupfwinkel im nördlichen Eschental wächst. Bei den Kräuterkundigen der Nachtelfen bekannt, besitzt die Pflanze starke stärkende Eigenschaften, die sowohl Leiden des Geistes als auch körperliche Gebrechen heilen können.",al={"was ist bathranshaar","bathranshaar pflanze"}}},fp="14,166,23.333.0,24.243.1,32.188.0,31.162.0,51.270.0,25.171.0"}
P.entries["item:battleboar-flank"] = {n="Kampfeberflanke",s="In Mulgore sammeln junge Jäger Kampfeberflanken von Bestien, die in die Jagdgründe der Tauren eindringen. Das Fleisch ernährt die Jugend des Stammes.",h="In Mulgore sammeln junge Jäger Kampfeberflanken von Bestien, die in die Jagdgründe der Tauren eindringen.",kw={"kampfeber","kampfeberflanke","dornrankenklamm","borstennacken","camp narache","grull falkenwind","mulgore","die hochwolkenebene"},ang={["profession:Cooking"]="Kocht als Koch die Flanke langsam zu einem sättigenden Eintopf für die Lagergemeinschaft.",["race:Tauren"]="Als Tauren lehrt Euch die Jagd auf Kampfeber, die Eure Heimat bedrohen, diese zu verteidigen und die Gaben der Earth Mother mit Respekt zu nutzen."},sec={{t="Nahrung aus der Borstennacken-Bedrohung",b="Die Borstennacken-Stacheleber richten in der Dornrankenklamm Kampfeber ab, die in die Jagdgründe der Tauren eindringen sollen. Ihre Angriffe bedrohen junge Tauren in Camp Narache. Grull Falkenwind schickt unerfahrene Jäger los, um den erlegten Bestien Flanken und Schnauzen abzunehmen. Das Flankenfleisch wird zu Eintopf für die Jugend des Stammes und verwandelt so die gegen sie gerichtete Waffe der Stacheleber in Nahrung."}},faq={{q="Wofür wird eine Kampfeberflanke verwendet?",a="Auf Grull Falkenwinds Anweisung sammeln junge Jäger in Camp Narache Kampfeberflanken. Das Fleisch wird zu Eintopf für die jungen Tauren des Dorfes gekocht.",al={"kampfeberflanke verwendung","was ist eine kampfeberflanke","warum kampfeberfleisch sammeln"}},{q="Wo findet man Kampfeberflanken?",a="Jäger schneiden Kampfeberflanken aus Kampfebern und Bristleback Battleboars nahe der Dornrankenklamm, östlich von Camp Narache auf der Hochwolkenebene.",al={"kampfeberflanke herkunft","wo hinterlassen kampfeber flanken","wer hinterlässt kampfeberflanken"}},{q="Warum dringen die Kampfeber in das Land der Tauren ein?",a="Die Borstennacken-Stacheleber züchten die Kampfeber und richten sie zu feindseligem Verhalten ab. Während die Spannungen zwischen den Borstennacken und den Tauren zunehmen, treiben die Stacheleber die Bestien in die traditionellen Jagdgründe der Tauren, um die Neuankömmlinge zu bedrängen.",al={"warum greifen kampfeber an","stacheleber eber mulgore","dornrankenklamm kampfeber"}}},fx={c29b6530={q="Was ist eine Kampfeberflanke?",a="Es ist ein herzhaftes Stück Fleisch, das von den Kampfebern stammt, die durch die roten Ebenen und Schluchten von Mulgore streifen. Obwohl diese grimmigen Schweine eher für den Krieg gezüchtet und ausgebildet werden als als Vieh, ist ihr Fleisch gesund und nahrhaft genug, um die Stämme zu ernähren, wenn das Wild knapp wird.",al={"was ist kampfeberflanke","informationen zu kampfeberflanke","kampfeberfleisch"}},["4a352cac"]={q="Woher stammt eine Kampfeberflanke?",a="Diese Flanken werden von Kampfebern und Stachelhufen-Kampfebern geschnitten, die in der Nähe der Dornrankenklamm herumstreifen. Die Kreaturen werden von den feindseligen Stachelhufen-Stachelebern aggressiv aufgezogen und abgerichtet, wodurch sie von gewöhnlichem Wild zu furchterregenden territorialen Bestien werden.",al={"ursprung kampfeberflanke","woher kommen kampfeberflanken","wer hat kampfeberfleisch"}},f9e62759={q="Warum möchte Grull Falkenwind Kampfeberflanken?",a="Grull Falkenwind sammelt die Flanken, um die Jugend des Stammes in Camp Narache zu ernähren. Das Fleisch zu einem nahrhaften Eintopf zu verkochen, stellt sicher, dass nichts von der Jagd verschwendet wird, während gleichzeitig die Stachelhufen-Stacheleber dafür bestraft werden, dass sie ihre aggressiven Bestien in die angestammten Jagdgründe der Tauren treiben.",al={"warum kampfeberflanke sammeln","warum will grull flanken","wer will kampfeberflanken"}}},fp="16,129,38.345.0,36.147.0,34.142.0,51.216.0"}
P.entries["item:battleboar-snout"] = {n="Kampfeberschnauze",s="Nahe der Hochwolkenebene sammeln junge Taurenjäger Kampfeberschnauzen, während die Bristleback in ihre Jagdgründe vordringen. Die Schnauzen kommen auch in Eintöpfe für die Jungen in Camp Narache.",h="Nahe der Hochwolkenebene sammeln junge Taurenjäger Kampfeberschnauzen, während die Bristleback in ihre...",kw={"kampfeber","kampfeberschnauze","dornrankenklamm","bristleback","camp narache","grull falkenwind","die hochwolkenebene"},ang={["profession:Cooking"]="Als Koch könnt Ihr zähe Stücke wie Schnauzen langsam über einem Feuer für die Lagerfeuereintöpfe des Stammes sieden lassen.",["race:Tauren"]="Als Tauren ehrt Ihr das Gleichgewicht der Earthmother, indem Ihr neben dem Fleisch auch die Schnauze sammelt. Das gebietet einem vordringenden Raubtier Einhalt und liefert Nahrung für die Jungen in Camp Narache."},sec={{t="Trophäen und Vorräte",b="Die Bristleback-Stacheleber richten in der Dornrankenklamm unterhalb der Hochwolkenebene Kampfeber ab. Sie schicken die Bestien in die Jagdgründe der Tauren. Grull Falkenwind schickt junge Krieger aus, um sie zurückzutreiben. Eine Schnauze beweist, dass ein Kampfeber erlegt wurde, und die Tauren kochen Schnauzen mit Flankenfleisch zu gehaltvollen Eintöpfen für ihre Jungen."}},faq={{q="Wozu dienen Kampfeberschnauzen?",a="In Camp Narache bittet Grull Falkenwind junge Jäger, Kampfeberschnauzen und Flankenfleisch zu sammeln. Die Schnauzen beweisen, dass bedrohliche Eber getötet wurden, und die Tauren kochen daraus Eintopf für die Jugend des Stammes.",al={"kampfебerschnauze verwendung","warum schnauzen behalten","was macht grull mit schnauzen"}},{q="Woher stammen diese Schnauzen?",a="Kampfeberschnauzen stammen von Kampfebern und Bristleback Battleboars an den Rändern der Hochwolkenebene und überall in der östlich gelegenen Dornrankenklamm.",al={"wo kampfeber finden","wer lässt schnauzen fallen","kampfeber fundort"}},{q="Warum dringen die Kampfeber in das Land der Tauren vor?",a="Feindselige Bristleback-Stacheleber haben die Kampfeber zu außergewöhnlicher Bösartigkeit abgerichtet. Die Eber dringen aus der Dornrankenklamm in die angestammten Jagdgründe der Tauren vor.",al={"warum greifen eber an","stacheleber eber","brambleblade kampfeber"}}},fx={a852a9b9={q="Was ist eine Kampfeberschnauze?",a="Es ist die abgetrennte Schnauze eines Kampfebers, der von den Stachelhufen-Stachelebern nahe der Dornrankenklamm aufgezogen und trainiert wurde. Grull Falkenwind und die Tauren von Camp Narache schätzen diese Stücke zusammen mit den Eberflanken als herzhafte Zutaten, die für die Jugend des Stammes zu Eintopf verkocht werden können, während sie gleichzeitig als physischer Beweis dafür dienen, dass ihre Jäger die eindringenden Bestien ausdünnen.",al={"kampfeberschnauze","was ist kampfeberschnauze","was ist dieser gegenstand"}}},fp="16,180,23.312.0,36.205.0,32.148.0,51.167.0"}
P.entries["item:battleworn-axe"] = {n="Kampferprobte Axt",s="Im Rotkammgebirge zeigen Kampferprobte Äxte, wo Schwarzfelsorcs in die Berge eindringen. Marschall Marris nimmt die geborgenen Waffen in Seenhain als Beweis für die Gefahr entgegen, die dessen Bewohnern droht.",h="Im Rotkammgebirge zeigen Kampferprobte Äxte, wo Schwarzfelsorcs in die Berge eindringen.",kw={"kampferprobte axt","schwarzfels","seenhain","marris","orc","rotkammgebirge","steinwacht","waffe"},ang={["faction:Alliance"]="Für die Allianz bedeutet jede nach Seenhain gebrachte Axt einen Eindringling weniger, der die schutzlosen Bürger des Rotkammgebirges bedroht. Die Hauptstreitkräfte von Sturmwind sind andernorts.",["profession:Blacksmithing"]="Als Schmied erkennt Ihr an diesen groben Eisenklingen trotz ihrer gezackten Schneiden und Scharten die widerstandsfähige, schwere Schmiedearbeit, die für Schwarzfelswaffen typisch ist."},sec={{t="Trophäe eines Eindringlings",b="Plünderer des Schwarzfels tragen schwere, schartige Äxte, während sie aus der Brennenden Steppe nach Süden ins Rotkammgebirge vordringen. Marschall Marris und die schwer bedrängte Stadtwache von Seenhain sammeln die Klingen. Jede bestätigt, dass ein weiterer marodierender Orc gefallen ist, und zeigt, wie gut die Kriegsschar bewaffnet ist."},{t="Die Bedrohung in den Hügeln",b="Schwarzfelseindringlinge haben Burg Steinwacht befestigt und im Südosten des Rotkammgebirges Stützpunkte eingenommen. Ihr Vormarsch hat die Stadtbewohner in Seenhain eingeschlossen. Ihnen die kampferprobten Waffen abzunehmen, lässt der Kriegsschar weniger Waffen und macht die Straßen für Reisende der Allianz frei."}},faq={{q="Was ist eine Kampferprobte Axt?",a="Schwarzfelsorcs im Rotkammgebirge tragen Kampferprobte Äxte, robuste Waffen, die durch harten Gebrauch abgenutzt sind. Geborgene Klingen beweisen, dass Eindringlinge getötet wurden.",al={"kampferprobte axt infos","was sind diese äxte","schwarzfelsaxt"}},{q="Wer will diese Äxte in Seenhain?",a="Marschall Marris befehligt die Stadtwache von Seenhain und will die Äxte als Beweis dafür, dass die Schwarzfelsbedrohung aus dem Umland der Stadt zurückgedrängt wird.",al={"wer nimmt kampferprobte äxte","kampferprobte axt questgeber","marschall marris äxte"}},{q="Woher stammen diese Äxte?",a="Schwarzfelsorcs tragen diese Äxte im gesamten Rotkammgebirge, besonders nahe Burg Steinwacht im Norden und in den Orclagern im Südosten.",al={"wo werden kampferprobte äxte fallen gelassen","kampferprobte axt farmen","welche orcs haben sie"}},{q="Warum sind die Orcs überhaupt im Rotkammgebirge?",a="Der Schwarzfelsklan marschierte aus der Brennenden Steppe durch die Gebirgspässe nach Süden und eroberte Burg Steinwacht. Anschließend plünderte der Klan den Norden und Osten des Rotkammgebirges, um Seenhain in Schach zu halten.",al={"warum sind schwarzfelsorcs im rotkammgebirge","invasion von steinwacht","blackrock menace grund"}}},fp="14,182,20.267.0,23.249.0,25.150.0,34.138.0,30.138.0,48.198.0"}
P.entries["item:beast-muisek"] = {n="Beast Muisek",s="In Feralas kann das Beast Muisek Vessel ein gefallenes Tier schrumpfen und sein Muisek einfangen. Die eingefangene Essenz wird benötigt, um das Gefäß zu testen.",h="In Feralas kann das Beast Muisek Vessel ein gefallenes Tier schrumpfen und sein Muisek einfangen.",kw={"beast muisek","beast muisek vessel","feralas","ironfur bear","longtooth runner","muisek","das gefäß testen"},sec={{t="Eine eingefangene Essenz",b="Unter den Tieren von Feralas lassen sich Ironfur Bears und Longtooth Runners mit dem Beast Muisek Vessel einfangen. Wenn eines fällt, schrumpft das Gefäß es und fängt sein Muisek ein, bevor der Geist entkommen kann. Das eingefangene Muisek ist der Maßstab für die Macht des Gefäßes."}},faq={{q="Was ist Beast Muisek?",a="Beast Muisek ist die Essenz, die mit dem Beast Muisek Vessel aus einem gefallenen Tier eingefangen wird.",al={"beast muisek","muisek","tieressenz"}},{q="Wie erhaltet Ihr Beast Muisek?",a="Verwendet das Beast Muisek Vessel auf einen gefallenen Ironfur Bear oder Longtooth Runner in Feralas.",al={"beast muisek erhalten","woher muisek","muisek einfangen"}},{q="Wofür wird es verwendet?",a="Beast Muisek wird benötigt, um das Beast Muisek Vessel zu testen.",al={"beast muisek verwendung","warum tiere einfangen","das gefäß testen"}},{q="Warum wird ein Tier eingefangen, nachdem es gestorben ist?",a="Das Muisek eines Geschöpfes kann nach einem gewaltsamen Tod entkommen. Das Gefäß schrumpft das gefallene Tier und fängt sein Muisek ein, bevor es fliehen kann.",al={"warum tote tiere","muisek-geister","geist entkommt"}}},fp="12,133,18.256.0,21.86.0,28.84.0,20.55.0,34.135.0"}
P.entries["item:beast-muisek-vessel"] = {n="Beast Muisek Vessel",s="Das Beast Muisek Vessel dient dazu, den Muisek eines Wesens einzufangen. In Feralas wird es eingesetzt, um den Muisek von Bären und Läufern einzuschließen.",h="Das Beast Muisek Vessel dient dazu, den Muisek eines Wesens einzufangen.",kw={"beast-muisek-vessel","feralas","ironfur bear","longtooth runner","muisek","das gefäß testen"},sec={{t="Ein Gefäß für Muisek",b="In Feralas wird das Beast Muisek Vessel bei einem gefallenen Ironfur Bear oder Longtooth Runner eingesetzt. Es lässt das Tier schrumpfen und fängt seinen Muisek ein, bevor der Geist entkommen kann. Der eingefangene Muisek ist dann bereit zur Verwendung."}},faq={{q="Was bewirkt das Beast Muisek Vessel?",a="Das Beast Muisek Vessel lässt einen gefallenen Ironfur Bear oder Longtooth Runner schrumpfen und fängt seinen Muisek ein, bevor der Geist entkommen kann.",al={"bestiengefäß","wofür ist das gefäß"}},{q="Was ist Muisek?",a="Muisek ist der Geist eines Wesens, der nach einem gewaltsamen Tod entkommen kann.",al={"bedeutung von muisek","bestien-muisek"}},{q="Bei welchen Wesen wirkt das Gefäß?",a="Das Gefäß fängt den Muisek gefallener Ironfur Bears und Longtooth Runners in Feralas ein.",al={"welche bestien","ironfur-bear-gefäß"}}},fp="19,141,19.207.0,37.127.0,15.75.0,40.88.0"}
P.entries["item:befouled-bloodstone-orb"] = {n="Beschmutzte Blutsteinkugel",s="Die Beschmutzte Blutsteinkugel ist ein magisches Relikt, das ein Hexenmeister in Burg Stromgarde verwahrt. Tor'gan aus Hammerfall sucht sie, um ihre Macht über das Land zu brechen.",h="Die Beschmutzte Blutsteinkugel ist ein magisches Relikt, das ein Hexenmeister in Burg Stromgarde verwahrt.",kw={"arathihochland","beschmutzte blutsteinkugel","blutsteinkugel","dämonen","finstere magie","marez cowl","burg stromgarde","tor'gan","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister wisst Ihr, welche Gefahr von einem Relikt ausgeht, mit dem Dämonen beschworen werden. Tor'gan will die Kugel zerstören, bevor ihre Macht das Arathihochland weiter befleckt."},sec={{t="Ein beflecktes Relikt",b="Tor'gan fürchtet, dass ein Hexenmeister in Burg Stromgarde ein magisches Relikt benutzt, um Dämonen zu beschwören. Er sucht die Beschmutzte Blutsteinkugel, damit ihre Macht zerstört werden kann, bevor sie das Arathihochland weiter befleckt."}},faq={{q="Was ist die Beschmutzte Blutsteinkugel?",a="Die Beschmutzte Blutsteinkugel ist ein magisches Relikt, das Marez Cowl, ein Hexenmeister in Burg Stromgarde, verwahrt.",al={"blutsteinkugel","beschmutzte kugel"}},{q="Wer hat die Kugel?",a="Marez Cowl, ein Hexenmeister in Burg Stromgarde, besitzt die Beschmutzte Blutsteinkugel.",al={"marez kugel","wer besitzt die blutsteinkugel"}},{q="Warum will Tor'gan sie haben?",a="Tor'gan will die Kugel zerstören und so verhindern, dass ihre Macht das Arathihochland befleckt.",al={"tor'gan kugel","warum die kugel holen"}},{q="Wozu wird die Kugel benutzt?",a="Tor'gan glaubt, ein Hexenmeister habe die Kugel benutzt, um zahlreiche Dämonen zu beschwören.",al={"kugel dämonen","blutsteinmagie"}},{q="Wo ist die Kugel?",a="Marez Cowl verwahrt die Kugel innerhalb der Mauern von Burg Stromgarde im Arathihochland.",al={"fundort der kugel","stromgarde blutstein"}}},fp="23,147,15.210.0,36.96.0,16.80.0,25.93.0,25.78.0,17.81.0"}
P.entries["item:berard-s-journal"] = {n="Berards Tagebuch",s="In Lohenscheit birgt Berards Tagebuch Forschung, nach der die Königliche Apothekervereinigung sucht. Berard erforschte eine uralte Seuche, die das Wasserleben des Lordameresees ausgelöscht hatte.",h="In Lohenscheit birgt Berards Tagebuch Forschung, nach der die Königliche Apothekervereinigung sucht.",kw={"apotheker berard","apotheker renferrel","berards tagebuch","der lordameresee","apothekermeister faranell","lohenscheit","königliche apothekervereinigung","silberwald"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr durch die Bergung verlorener Forschung in Lohenscheit den Verlassenen, im gesamten Silberwald eine starke Verteidigungsbastion zu errichten.",["race:Undead"]="Als Untoter helft Ihr mit jedem Fetzen Wissen über Gifte der Königlichen Apothekervereinigung, eine Waffe zur Verteidigung der Verlassenen gegen die Geißel und lebende Feinde zu sichern."},sec={{t="Verschollene Forschung zum Lordameresee",b="Bevor Arugals Shadow Magic den Silberwald erreichte, gehörte Apotheker Berard zu den klügsten Köpfen der Königlichen Apothekervereinigung. Von Lohenscheit aus erforschte er eine uralte Seuche, die Jahrhunderte zuvor alles Wasserleben im Lordameresee ausgelöscht hatte. Arugals Fluch erfasste das Dorf, und Berard verlor den Verstand und wurde zu einem willenlosen Knecht. Seine Feldnotizen blieben auf einem Bücherregal in seinen Gemächern im Gasthaus von Lohenscheit zurück."},{t="Stoff für die New Plague",b="Berards Forschung blieb erhalten, obwohl Berard selbst für die Vereinigung verloren war. Im Grabmal erkennt Apotheker Renferrel ihren Wert und schickt Agenten der Verlassenen in das feindselige Dorf, um das Tagebuch zu bergen. Die Notizen über das uralte Seegift liefern Apothekermeister Faranell und der Vereinigung im Apothekarium die Grundlage für die Entwicklung einer eigenen neuen Seuche der Verlassenen."}},faq={{q="Wer war Apotheker Berard?",a="Apotheker Berard war ein begabtes Mitglied der Königlichen Apothekervereinigung und lebte in Lohenscheit. Er erforschte uralte Giftstoffe, als Erzmagier Arugal die Region verfluchte, Berards Verstand brach und ihn versklavte.",al={"wer ist berard","berards geschichte","apotheker berard"}},{q="Wo findet sich Berards Tagebuch?",a="Berards Tagebuch liegt auf einem Bücherregal in Berards altem Arbeitszimmer im Obergeschoss des Gasthauses von Lohenscheit, tief im Süden des Silberwalds.",al={"berards tagebuch finden","fundort des tagebuchs","wo ist das buch"}},{q="Welche Forschung ist im Tagebuch festgehalten?",a="Das Tagebuch enthält Berards Erkenntnisse über eine uralte Seuche, die alles Wasserleben im Lordameresee ausgelöscht hatte. Die Königliche Apothekervereinigung hofft, deren giftige Eigenschaften für ihre eigenen chemischen Waffen nutzen zu können.",al={"was steht im tagebuch","berards forschung","inhalt des tagebuchs"}},{q="Warum will Apotheker Renferrel das Tagebuch?",a="Apotheker Renferrel will nützliche Forschung bergen, bevor sie zerstört wird oder verloren geht. Berards Erkenntnisse über die Seuche des Lordameresees liefern Bestandteile, die Apothekermeister Faranell in Unterstadt zur Entwicklung der neuen Seuche der Verlassenen benötigt.",al={"warum will renferrel es","renferrels tagebuchquest"}}},fx={b3a0b77c={q="Was ist Berards Tagebuch?",a="Berards Tagebuch ist ein wissenschaftliches Forschungsnotizbuch, das von Apotheker Berard zusammengestellt wurde, einem ehemaligen Mitglied der Königlichen Apothekervereinigung. Es enthält seine detaillierten Erkenntnisse über eine uralte Seuche, die vor langer Zeit alles aquatische Leben im Lordameresee ausgelöscht hat, was die Verlassenen für ihre eigene Alchemie erforschen wollen.",al={"berard tagebuch","was ist berards tagebuch","berards tagebuch"}},["719e9fe0"]={q="Woher stammt Berards Tagebuch und wer hat es verfasst?",a="Das Tagebuch wurde von Apotheker Berard verfasst, bevor er durch die Schattenmagie von Erzmagier Arugal den Verstand verlor. Er führte seine Studien im Gasthaus in Lohenscheit, wo der Wälzer in einem Bücherregal zurückgelassen wurde, nachdem er zu einem willenlosen Sklaven geworden war.",al={"woher kommt berards tagebuch","wer schrieb berards tagebuch","ursprung berards tagebuch"}}},fp="16,167,31.428.0,23.360.1,26.208.0,32.142.0,41.207.0,47.238.0"}
P.entries["item:bernice-s-necklace"] = {n="Bernices Halskette",s="Auf dem Hof der Steinfelds im Wald von Elwynn hält Bernice die Halskette ihres verstorbenen Mannes stets nah bei sich.",h="Auf dem Hof der Steinfelds im Wald von Elwynn hält Bernice die Halskette ihres verstorbenen Mannes stets nah...",kw={"tante bernice","bernices halskette","billy maclure","tiefenschachtmine","goldtooth","glücksbringer","stonefield"},ang={["faction:Alliance"]="Für die Bauernfamilien der Allianz im Wald von Elwynn erinnert die Halskette daran, welchen Tribut Sturmwinds lange Feldzüge im Alltag fordern."},sec={{t="Der verlorene Glücksbringer eines Soldaten",b="Tante Bernice Stonefield bewahrt die Halskette ihres Mannes auf dem Hof der Steinfelds auf. Er war ein Veteran der Feldzüge von Sturmwind und trug den Glücksbringer für gutes Gelingen mit in die Schlacht. Bernice sagt, das Unglück habe ihn erst auf seinem letzten Feldzug ereilt. Das war die einzige Expedition, bei der er vergessen hatte, ihn mitzunehmen. Seit seinem Tod zählt das Andenken zu ihren wertvollsten Besitztümern."},{t="Von Plünderern gestohlen",b="Der junge Billy Maclure erkundete die Gegend nahe der Tiefenschachtmine, als ihm die glänzende Halskette aus der Hand glitt. Goldtooth, ein bedeutender Kobold in der Mine, entdeckte sie und nahm sie mit. Wie andere Kobolde fühlte er sich von glänzendem, wertvollem Schmuck angezogen. Er bewahrte die Halskette unter den Schätzen auf, die er zusammengetragen hatte."}},faq={{q="Wem gehörte diese Halskette ursprünglich?",a="Die Halskette gehörte dem verstorbenen Mann von Tante Bernice Stonefield. Er trug sie während der Feldzüge von Sturmwind als Glücksbringer.",al={"wem gehörte die halskette","bernice halskette besitzer","ehemann halskette"}},{q="Wie gelangte die Halskette zu den Kobolden?",a="Billy Maclure sah, wie ein großer Kobold mit Goldzähnen die Halskette nahe der Tiefenschachtmine aufhob und mitnahm. Tante Bernice hofft, dass sie zurückgeholt werden kann.",al={"wie ging sie verloren","warum hat goldtooth sie","wer nahm die halskette"}},{q="Warum ist die Halskette für Tante Bernice so wichtig?",a="Die Halskette ist ein kostbares Andenken an Bernices verstorbenen Mann. Er glaubte, sie schütze ihn in der Schlacht, und das einzige Mal, dass er im Krieg fiel, war an dem Tag, als er sie zurückließ.",al={"warum will bernice sie","bernice ehemann geschichte","ist die halskette magisch"}},{q="Wer ist Goldtooth?",a="Goldtooth ist ein bedeutender plündernder Kobold mit einem Unterschlupf in der Tiefenschachtmine im Wald von Elwynn. Er sammelt glänzenden Tand und nahm die Halskette mit, nachdem sie in der Nähe fallen gelassen worden war.",al={"was ist goldtooth","goldtooth hintergrundgeschichte","wer hat die halskette"}}},fp="18,85,22.368.0,20.306.1,35.131.0,45.154.0,51.165.0,17.174.0"}
P.entries["item:besseleth-s-fang"] = {n="Besseleths Fangzahn",s="Im Sishircanyon setzt Besseleths Fangzahn der tödlichen Bedrohung durch die Spinne ein Ende.",h="Im Sishircanyon setzt Besseleths Fangzahn der tödlichen Bedrohung durch die Spinne ein Ende.",kw={"arachnophobia","besseleth","besseleths fangzahn","maggran erdbinder","sishircanyon","steinkrallengebirge","sonnenfels","weberpass"},ang={["class:Hunter"]="Als Jäger könnt Ihr den fast zwei Fuß langen Giftzahn einer Spinnenmatriarchin an der Spitze der Nahrungskette als Beweis Eurer Fährtenlese- und Kampfkünste beanspruchen.",["faction:Horde"]="Die Spinne im Canyon zu beseitigen hilft, die gefährlichen Bergpfade zu sichern, die die Grenze zum Brachland mit Sonnenfels verbinden."},sec={{t="Trophäe der Schluchtenjägerin",b="Besseleth und ihre Brut machen den Sishircanyon für Reisende gefährlich. Nachts verwandelt die Riesenspinne den Weberpass in eine Todesfalle für alle, die die Schlucht durchqueren. Ihr Fangzahn ist fast zwei Fuß lang und trieft von starkem Gift. Die örtlichen Verteidiger haben unter ihren giftigen Angriffen gelitten, daher bringt ihnen sein Eintreffen Erleichterung."}},faq={{q="Wozu dient Besseleths Fangzahn?",a="Der Fangzahn beweist, dass Besseleth, die Spinnenmatriarchin, erschlagen wurde. Maggran Erdbinder in Sonnenfels setzte ein Kopfgeld auf sie aus, nachdem er einen beinahe tödlichen Angriff mit ihren Fangzähnen überlebt hatte. Er belohnt jeden, der ihm die Trophäe bringt.",al={"besseleths fangzahn verwendung","wer will besseleths fangzahn","fangzahn abgeben"}},{q="Woher stammt dieser Fangzahn?",a="Der Fangzahn stammt von Besseleth, einer riesigen Raubspinne, die im Sishircanyon haust. Der Canyon liegt westlich der Hauptstraße südlich der Scherwindklippe im Steinkrallengebirge.",al={"wie besseleths fangzahn erhalten","wo ist besseleth","besseleth fundort"}},{q="Warum wollte Maggran Erdbinder Besseleth tot sehen?",a="Besseleth und ihre Brut machen Jagd auf Reisende, die auf den Straßen nach Sonnenfels unterwegs sind, besonders nachts. Nachdem sie ihm aufgelauert und ihn mit ihren Fangzähnen verwundet hatte, setzte Maggran Erdbinder ein Kopfgeld aus, um die Wege zu sichern.",al={"warum besseleth töten","maggran kopfgeld spinne","warum kopfgeld auf besseleth"}},{q="Wer setzte das Kopfgeld für den Fangzahn aus?",a="Maggran Erdbinder setzte das Kopfgeld aus. Ein Steckbrief, der Reisende vor den Gefahren des Sishircanyons warnt, steht an der Hauptstraße südlich der Abzweigung zur Scherwindklippe.",al={"steckbrief steinkrallengebirge spinne","arachnophobia questgeber"}}},fx={f0d9a9a7={q="Was ist Besseleths Fangzahn?",a="Besseleths Fangzahn ist ein massiver, zwei Fuß langer Zahn, der der Raubspinne Besseleth entnommen wurde. Sie und ihre Brut lauern in der Sishircanyon und erbeuten nachts Reisende entlang des Weberpasses. Der Fangzahn dient als unbestreitbarer physischer Beweis dafür, dass die gefürchtete Arachnide, die die Pfade im Steinkrallengebirge terrorisierte, endlich erlegt wurde.",al={"was ist besseleths fangzahn","besseleth zahn","fangzahn von besseleth"}}},fp="16,79,28.315.0,34.227.0,31.184.0,48.220.0,35.165.0"}
P.entries["item:bethor-s-scroll"] = {n="Bethors Rolle",s="Bethor Eismacht schreibt Gegenbeschwörungen für Apotheker Renferrel im Grabmal. Die Rolle könnte ihm helfen, einen schützenden Trank gegen Thule Ravenclaws dunkle Hexerei auf der Insel Fenris zu brauen.",h="Bethor Eismacht schreibt Gegenbeschwörungen für Apotheker Renferrel im Grabmal.",kw={"apotheker renferrel","bethor eismacht","bethors rolle","insel fenris","rot hide","silberwald","das grabmal","thule ravenclaw"},ang={["class:Mage"]="Als Magier wisst Ihr, wie sich die charakteristische Magie eines Zauberwirkers gegen ihn wenden lässt. Die Rolle erinnert an die von Zwietracht geprägte Vergangenheit der Kirin Tor.",["race:Undead"]="Als Untoter seht Ihr, wie Zauberwirker und Apotheker der Verlassenen durch dieses Pergament ihre Talente vereinen. Es verbindet Dalarans alte arkane Ausbildung mit der alchemistischen Handwerkskunst des Grabmals."},sec={{t="Dem Nekromanten entgegenwirken",b="Bethor Eismacht schreibt arkane Formeln, um der Königlichen Apothekervereinigung beim Brauen eines wiederherstellenden Tranks zu helfen. Im Grabmal nimmt Apotheker Renferrel die Rolle entgegen. Ihre Beschwörungsformeln wirken den schwächenden Flüchen entgegen, die Thule um seine Festung wirkt."},{t="Der Verrat eines Kollegen",b="Verdorbener Ichor von Rot Hide-Gnollen trägt Thule Ravenclaws Handschrift, und Bethor Eismacht kennt dessen Zauberhandwerk. Thule war einst ein vielversprechender junger Magier der Kirin Tor. Als die Geißel an die Macht gelangte, verriet er seine Brüder und diente dem Lichkönig. Bethor erfährt, dass Thule überlebt hat und von der Insel Fenris aus Angriffe der Rot Hide im gesamten Silberwald lenkt. Also verfasst Bethor die Rolle und schöpft dabei aus seinem Wissen über einen ehemaligen Kollegen."}},faq={{q="Was steht auf Bethors Rolle?",a="Bethor Eismacht schreibt arkane Beschwörungsformeln nieder, die als Anleitung zum Brauen eines alchemistischen Gegentranks dienen. Er studierte gemeinsam mit Thule Rabenklaue und kennt die Zauber, die der Nekromant bevorzugt.",al={"was steht auf der rolle","inhalt von bethors rolle"}},{q="Wer erhält diese Rolle?",a="Apotheker Renferrel erhält die Rolle im Grabmal im Silberwald. Er nutzt ihre Magie, um einen schützenden Trank herzustellen.",al={"wem die rolle geben","bethors rolle abgeben","wer bekommt die rolle"}},{q="Warum braucht Apotheker Renferrel magische Beschwörungsformeln für einen Trank?",a="Apotheker Renferrel betreibt Alchemie statt herkömmlicher Zauberei und lässt solch unverhüllte Kräfte nur selten in seine Gebräue einfließen. Gewöhnliche Gegengifte können die Flüche der Geißel, die Thule schützen, nicht durchdringen. Bethors arkane Formeln können den Trank wirksam machen.",al={"warum braucht ein apotheker zauber","zaubertrank renferrel"}},{q="Wer war Thule Rabenklaue, bevor er sich der Geißel zuwandte?",a="Vor dem Dritten Krieg war Thule Rabenklaue ein vielversprechender junger menschlicher Magier und ein Gefährte von Bethor Eismacht. Als der Lichkönig seine untoten Armeen sammelte, verließ Thule seine Mitstreiter unter den Zauberwirkern und schwor der Geißel die Treue.",al={"wer ist thule ravenclaw","thules vorgeschichte","thule und bethor"}}},fx={["31160c67"]={q="Woher stammt Bethors Rolle und wer hat sie verfasst?",a="Die Rolle wurde von Bethor Eismacht geschrieben, einem untoten Magier, der den Verlassenen aus dem Magieviertel der Unterstadt dient. Als er die magische Signatur auf dem abscheulichen Ichor erkannte, das von den Fäulnisfellgnollen geborgen wurde, erkannte Bethor, dass sein ehemaliger Kollege Thule Rabenklaue überlebt hatte und sich der Geißel zugewandt hatte. Unter Rückgriff auf sein umfassendes Wissen über Thules arkaner Techniken transkribierte Bethor Gegenbeschwörungen auf dieses Pergament, um bei der Niederwerfung seines abtrünnigen ehemaligen Kollegen zu helfen.",al={"wer schrieb bethors rolle","wer fertigte bethors rolle an","woher kam bethors rolle"}},["64d2974c"]={q="Warum wird Bethors Rolle benötigt?",a="Apotheker Renferrel benötigt die magischen Beschwörungen, die auf der Rolle eingeschrieben sind, um ein schützendes Gegenmittel zu brauen. Thule Rabenklaue setzt in seiner Festung auf der Insel Fenris mächtige, lähmende Flüche ein. Indem sie Bethors arkane Formeln in einen alchemistischen Trank einfließen lassen, kann die Königliche Apothekervereinigung einen speziellen Trank herstellen, der Euch gegen Thules dunkle Zauberei schützt, wenn Ihr ihm gegenübertretet.",al={"warum will man bethors rolle","warum ist bethors rolle wichtig","wofür wird bethors rolle benutzt"}}},fp="15,191,26.240.1,22.428.1,35.183.0,25.127.0,69.250.0,54.231.0"}
P.entries["item:bingles-blastencapper"] = {n="Bingles' Superspreng",s="Troggs haben Bingles' Superspreng, seit sein Gyrokopter in den Loch stürzte. Ohne ihn sind Bingles' Pläne gefährdet, die Befreiung Gnomeregans zu unterstützen.",h="Troggs haben Bingles' Superspreng, seit sein Gyrokopter in den Loch stürzte.",kw={"bingles","superspreng","blastenheimer","sprengstoffe","gnomeregan","gyrokopter","loch modan","trogg"},ang={["profession:Engineering"]="Der Superspreng zeigt den Einfallsreichtum gnomischer Ingenieurskunst: Komplex und explosiv kann er aus großer Höhe verheerende Schäden anrichten.",["race:Gnome"]="Jedes Werkzeug und jedes Stück Munition zählt, während die Gnome um die Rückeroberung Gnomeregans ringen. Die Bergung von Bingles' Sprengsatz könnte es den Gnomen ermöglichen, mit ihrem Erfindungsreichtum aus der Luft gegen die Trogginvasoren zurückzuschlagen."},sec={{t="Eine explosive Erfindung",b="Bingles Blastenheimer baute den Superspreng, um die Troggs und Lepragnome, die Gnomeregan überrannt hatten, aus der Luft anzugreifen. Ein mechanischer Defekt ließ seinen Gyrokopter in den Loch stürzen, doch Bingles überlebte. Troggs von den nördlichen Inseln plünderten das Wrack und brachten die hochexplosive Waffe in ihre Lager."},{t="Luftunterstützung für Gnomeregan",b="Bingles braucht den Superspreng, um bei der Rückeroberung Gnomeregans zu helfen. Die verbannten Gnome bereiten sich darauf vor, ihre radioaktive Heimat zurückzuerobern, und er zählt beim Luftangriff auf seinen Gyrokopter und seine charakteristische Munition. In den Händen der Troggs könnte der Sprengsatz versehentlich eine Katastrophe in Loch Modan auslösen. Seine Bergung würde dem gnomischen Widerstand eine wertvolle Waffe erhalten."}},faq={{q="Was ist Bingles' Superspreng?",a="Bingles Blastenheimer fertigte den Superspreng an, um die Troggs und Lepragnome, die Gnomeregan besetzen, aus der Luft anzugreifen.",al={"was ist superspreng","superspreng","bingles' sprengsatz"}},{q="Wie gelangte der Superspreng in den Loch?",a="Bingles stürzte mit seinem Gyrokopter in den Loch. Troggs von nahe gelegenen Inseln plünderten das Wrack und schleppten seine Werkzeuge samt dem Sprengsatz fort.",al={"warum ist er im loch","wie hat bingles ihn verloren","absturz"}},{q="Wer hat den Superspreng derzeit?",a="Troggs von den nördlichen Inseln des Lochs nahmen den Superspreng aus dem Wrack mit und bewachen ihn in ihrem Lager.",al={"wer hat den superspreng gestohlen","wer hat ihn","troggs"}},{q="Warum braucht Bingles den Superspreng zurück?",a="Bingles braucht den Superspreng und seine Werkzeuge, um seinen Gyrokopter zu reparieren und einen Luftangriff zur Unterstützung der Rückeroberung Gnomeregans zu starten.",al={"warum wird er zurückgebraucht","warum ist superspreng wichtig","für gnomeregan"}}},fp="22,148,20.300.0,26.361.0,31.120.0,45.144.0,36.110.0,49.141.0"}
P.entries["item:bingles-hammer"] = {n="Bingles Hammer",s="An seiner Absturzstelle in Loch Modan braucht Bingles Blastenheimer Bingles Hammer von den Troggs zurück. Mit seiner Ausrüstung kann er seine Flugmaschine reparieren und bei der Befreiung Gnomeregans helfen.",h="An seiner Absturzstelle in Loch Modan braucht Bingles Blastenheimer Bingles Hammer von den Troggs zurück.",kw={"bingles","blastenheimer","gnomeregan","hammer","loch modan","werkzeugeimer","trogg"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, dass ein hochwertiger Hammer aus gnomischer Fertigung schwer zu ersetzen ist. Bingles braucht einen, um seinen experimentellen Gyrokopter in der Wildnis wieder aufzubauen.",["race:Gnome"]="Als Gnom bringt Ihr mit jedem zurückgeholten Werkzeug den Luftangriff zur Befreiung Eurer angestammten Heimat näher."},sec={{t="Werkzeug eines gestrandeten Fliegers",b="Troggs plünderten Bingles Blastenheimers Absturzstelle auf den Süßwasserinseln. Sie nahmen seinen Hammer und hochwirksame Sprengstoffe mit. Der Hammer wird gebraucht, um die verbeulte Flugzeugzelle zu reparieren und die mechanischen Teile des Gyrokopters einzustellen. Ohne seine Ausrüstung kann Bingles keine Unterstützungsflüge für die Gnomentruppen durchführen, die um die Rückeroberung Gnomeregans kämpfen."}},faq={{q="Wo ist Bingles Hammer zu finden?",a="Bingles Hammer liegt in einem der Bingles's Toolbuckets, die auf den von Troggs heimgesuchten Inseln im nördlichen Loch verstreut sind.",al={"fundort des hammers","wo ist bingles hammer","hammer finden"}},{q="Wem gehört dieser Hammer?",a="Der Hammer gehört Bingles Blastenheimer, einem gnomischen Ingenieur und Piloten. Seine Flugmaschine stürzte am Ufer von Loch Modan ab.",al={"wem gehört der hammer","besitzer von bingles hammer"}},{q="Warum ist dieses Werkzeug für Bingles so wichtig?",a="Bingles braucht seinen vollständigen Werkzeugsatz, um seinen abgestürzten Gyrokopter wieder aufzubauen. Er plant, damit gegen die Troggs und Lepragnome zu fliegen, die Gnomeregan besetzt halten.",al={"warum wird der hammer gebraucht","verwendung von bingles hammer"}},{q="Wer hat Bingles Hammer gestohlen?",a="Troggs, die auf den Seeinseln leben, plünderten die Absturzstelle. Sie nahmen Bingles' Werkzeugeimer und seine maßgefertigten blastencapper-Sprengstoffe mit.",al={"wer nahm den hammer","troggdiebe"}}},fp="15,181,28.330.0,35.122.0,31.131.0,41.146.0,26.124.0"}
P.entries["item:bingles-screwdriver"] = {n="Bingles' Schraubendreher",s="Auf den nördlichen Inseln von Loch Modan liegt Bingles' Schraubendreher zwischen der beim Absturz verlorenen Ausrüstung. Troggs schleppten ihn mit den Werkzeugen des Piloten Bingles Blastenheimer davon.",h="Auf den nördlichen Inseln von Loch Modan liegt Bingles' Schraubendreher zwischen der beim Absturz verlorenen...",kw={"bingles","blastenheimer","gyrokopter","loch modan","schraubendreher","werkzeugeimer","troggs"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, dass ein präzise gefertigter Schraubendreher für komplexe Gyrokopterrotoren und empfindliche Abzugsmechanismen unverzichtbar ist.",["race:Gnome"]="Als Gnom bringt Ihr Bingles mit jedem geborgenen Werkzeug dem Wiederaufbau seiner Maschine und dem Kampf gegen die Troggs und Lepragnome näher, die Euer Volk aus Gnomeregan vertrieben haben."},sec={{t="Unverzichtbares Werkzeug eines Piloten",b="Als Bingles Blastenheimer in Loch Modan abstürzte, verlor er die Werkzeuge, die er zur Reparatur seines Gyrokopters brauchte. Troggs auf den nahen Inseln schleppten seine Werkzeugeimer davon, und der Schraubendreher steckte in einem davon. Bingles braucht ihn für Feineinstellungen, während er die Maschine repariert und an ihrer Bewaffnung arbeitet."},{t="Vorbereitungen zur Rückeroberung",b="Bingles arbeitet daran, Gnomeregan von Troggs und Lepragnomen zu befreien. Er will seine Flugkünste mit hochexplosiver Blastencapper-Munition verbinden, um einen Luftangriff zu führen. Schraubendreher, Schraubenschlüssel und Hammer werden ihm helfen, seinen Gyrokopter wiederaufzubauen und die Gegenoffensive aus der Luft am Leben zu erhalten."}},faq={{q="Wo ist Bingles' Schraubendreher zu finden?",a="Nach Bingles' Absturz verstreuten Troggs seine Werkzeugeimer über die Inseln im Norden von Loch Modan. Der Schraubendreher liegt in einem davon.",al={"fundort des schraubendrehers","bingles' schraubendreher finden","wo ist der schraubendreher"}},{q="Warum ist der Schraubendreher für Bingles so wichtig?",a="Bingles braucht den Schraubendreher und seine anderen Werkzeuge, um seinen Gyrokopter wiederaufzubauen und Sprengstoff für den Feldzug zur Rückeroberung von Gnomeregan vorzubereiten.",al={"warum braucht bingles ihn","wofür ist er"}},{q="Wer hat den Schraubendreher ursprünglich gestohlen?",a="Nach Bingles' Bruchlandung nahmen die auf den Inseln in Loch Modan lebenden Troggs seine Werkzeugeimer und seinen Blastencapper-Sprengstoff mit.",al={"wer nahm die werkzeuge","wer stahl bingles' werkzeuge"}},{q="Welche anderen Werkzeuge verlor Bingles beim Absturz?",a="Neben dem Schraubendreher verlor Bingles seinen Schraubenschlüssel, seinen Hammer und seinen Vorrat an hochexplosivem Blastenheimer Blastencapper-Sprengstoff.",al={"bingles' andere werkzeuge","was fehlt noch"}}},fx={f72526b7={q="Was ist Bingles' Schraubendreher?",a="Bingles' Schraubendreher ist ein Ingenieurswerkzeug von Bingles Blastenheimer, einem Gnom-Flieger, der in Loch Modan gestrandet ist. Zusammen mit seinem Schraubenschlüssel und Hammer ist es eines der wichtigsten Werkzeuge, die er an Bord seines Gyrokopters bei sich trug, um seine Flugmaschine zu warten und Munition für den Gnom-Widerstand zu konstruieren.",al={"was ist bingles' schraubendreher","informationen zu bingles' schraubendreher","über bingles' schraubendreher"}}},fp="20,164,19.293.0,29.275.0,36.137.0,47.137.0,45.122.0,47.123.0"}
P.entries["item:bingles-wrench"] = {n="Bingles' Schraubenschlüssel",s="Im Loch ist Bingles' Schraubenschlüssel mit den anderen Werkzeugen des Piloten verschollen. Troggs nahmen ihn mit, nachdem Bingles Blastenheimer mit seiner Flugmaschine bruchgelandet war.",h="Im Loch ist Bingles' Schraubenschlüssel mit den anderen Werkzeugen des Piloten verschollen.",kw={"bingles","blastenheimer","gyrokopter","loch modan","werkzeugeimer","troggs","schraubenschlüssel"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, dass ein Handwerker ohne seinen maßgefertigten Schraubenschlüssel am Boden festsitzt, besonders wenn Troggs in der Nähe plündern.",["race:Gnome"]="Für Euch als Gnom bringt jedes wiedergefundene Werkzeug den Widerstand näher daran, den Kampf zurück in Gnomeregans verstrahlte Hallen zu tragen."},sec={{t="Bergung auf den Inseln",b="Bingles Blastenheimer überlebte den Absturz seines Gyrokopters in den Loch. Dann plünderten die Troggs die Absturzstelle auf den kleinen nördlichen Inseln. Sie nahmen seine Spezialvorräte mit und verteilten seine Werkzeuge auf Eimer in ihren Lagern.\n\nBingles' Schraubenschlüssel ist eines von drei unverzichtbaren Handwerkzeugen, neben seinen hochexplosiven Blastencapper-Sprengstoffen. Ohne den Schraubenschlüssel kann Bingles seinen abgestürzten Gyrokopter nicht reparieren. Seine geplante Luftoffensive zur Unterstützung der verbannten Gnome, die um die Rückeroberung von Gnomeregan kämpfen, muss warten."}},faq={{q="Wem gehört dieser Schraubenschlüssel?",a="Der Schraubenschlüssel gehört Bingles Blastenheimer, einem exzentrischen gnomischen Piloten, dessen Gyrokopter in den Loch stürzte.",al={"wer ist bingles","bingles besitzer","schraubenschlüssel besitzer"}},{q="Warum ist der Schraubenschlüssel für Bingles so wichtig?",a="Bingles braucht seine Spezialwerkzeuge, um seine beschädigte Flugmaschine zu reparieren und seine Sprengladung für einen Luftangriff auf die Troggs und Lepragnome scharfzumachen, die Gnomeregan besetzen.",al={"warum braucht bingles seinen schraubenschlüssel","schraubenschlüssel zweck","wofür ist der schraubenschlüssel"}},{q="Wo landete der Schraubenschlüssel nach dem Absturz?",a="Einheimische Troggs bargen den Schraubenschlüssel und versteckten ihn in einem von Bingles' gestohlenen Werkzeugeimern in ihren Lagern auf den nördlichen Inseln des Lochs.",al={"wo ist bingles' schraubenschlüssel","schraubenschlüssel fundort","bingles' schraubenschlüssel finden"}},{q="Was wurde zusammen mit dem Schraubenschlüssel noch gestohlen?",a="Die Troggs nahmen auch Bingles' Schraubendreher, Bingles Hammer und seine experimentellen Blastenheimer Blastencapper-Sprengstoffe mit.",al={"weitere vorräte","fehlende werkzeuge","was haben die troggs noch mitgenommen"}}},fp="15,145,22.497.0,31.109.0,42.182.0,44.141.0,43.120.0"}
P.entries["item:black-claw-stout"] = {n="Schwarzklauenbier",s="Unter Sturmwind bereitet Zardeth der Schwarzen Klaue ein Getränk für Lord Wishock zu. Das Starkbier erreicht ihn als gewöhnliches Tavernengetränk.",h="Unter Sturmwind bereitet Zardeth der Schwarzen Klaue ein Getränk für Lord Wishock zu.",kw={"schwarzklauenbier","hall of petitioners","lord wishock","gift","slaughtered lamb","burg sturmwind","zardeth"},ang={["class:Warlock"]="Für Sturmwinds verborgenen Hexenmeisterzirkel ist das Überbringen des Gebräus ein Botengang. Ein aufdringlicher Adliger will seine Zuflucht unter dem Slaughtered Lamb schließen lassen.",["faction:Alliance"]="Das Gebräu in Burg Sturmwind zu bringen, führt die Hexenmeister unter dem Slaughtered Lamb nahe an die Adligen der Hauptstadt heran."},sec={{t="Ein giftiger Trunk",b="Unter den Schankräumen des Slaughtered Lamb arbeitet Zardeth der Schwarzen Klaue unbemerkt von der Stadtwache. Lord Wishock droht immer wieder, den Betrieb schließen zu lassen, obwohl seine Zechen oben unbezahlt bleiben. Also nutzt Zardeth die Schwäche des Adligen für starke Getränke gegen ihn. Er verbirgt eine tödliche Dosis in einem gewöhnlichen Tavernengetränk."},{t="Ein stiller Meuchelmord",b="In der Hall of Petitioners in Burg Sturmwind erhält Lord Wishock das Starkbier. Sein aufgeblasener Stolz und sein Durst lassen ihn begierig annehmen, was er für die aufmerksame Gabe eines Dieners hält. Er trinkt es auf der Stelle. Das Gift wirkt fast augenblicklich und bringt einen der hartnäckigsten politischen Kritiker des Kults direkt vor den Augen des königlichen Hofes zum Schweigen."}},faq={{q="Was ist Schwarzklauenbier?",a="Zardeth der Schwarzen Klaue bereitet Schwarzklauenbier in den Katakomben unter dem Slaughtered Lamb in Sturmwinds Magierviertel für Lord Wishock zu.",al={"was ist dieses getränk","schwarzklauenbier hintergrundgeschichte","giftiges gebräu"}},{q="Für wen ist das Starkbier bestimmt?",a="Das Ziel ist Lord Wishock, ein herrischer Adliger in der Hall of Petitioners, der die Zuflucht der Hexenmeister schließen lassen will, während er dort auf Kredit trinkt.",al={"wer trinkt es","wer stirbt an schwarzklauenbier","wishock ziel"}},{q="Wer hat das Gebräu erschaffen?",a="Zardeth der Schwarzen Klaue braut das Starkbier in den Gruften unter dem Slaughtered Lamb.",al={"schöpfer des schwarzklauenbiers","wer hat das hergestellt","zardeth gebräu"}},{q="Warum wird Lord Wishock das Starkbier angeboten?",a="Zardeth schickt Lord Wishock das Starkbier in die Hall of Petitioners und bittet den Boten, herauszufinden, wie dem Adligen sein besonderes Gebräu schmeckt.",al={"stirbt wishock","schwarzklauenbier wirkung"}}},fx={a6b6f1b7={q="Warum möchte Zardeth, dass Ihr Schwarzklauenbier an Lord Wishock überbringt?",a="Lord Wishock ist ein heuchlerischer Adliger, der seine Tage damit verbringt, sich für die Schließung von The Slaughtered Lamb einzusetzen, während er seine Nächte im Obergeschoss damit zubringt, zu trinken und eine unbezahlte Zeche in der Taverne anzuhäufen. Um ihn dauerhaft zum Schweigen zu bringen, hat Zardeth dieses tödliche Spezialgebräu zusammengestellt, um Wishocks Schwäche für Alkohol auszunutzen und ihn unter dem Deckmantel eines erfrischenden Getränks aus dem Weg zu räumen.",al={"warum schwarzklauenbier überbringen","warum wishock schwarzklauenbier geben","zardeth wishock bier warum"}}},fp="16,133,15.332.1,19.338.1,25.143.0,31.151.0,21.85.0,38.128.1"}
P.entries["item:black-drake-s-heart"] = {n="Black Drake's Heart",s="In der Lethlorklamm birgt das Herz eines schwarzen Drachen die Hitze, die Sigrun Ironhew für ihre feurigen Waffenverzauberungen braucht. Sie bittet Euch, eines von den Drachen der Klamm zu bringen.",h="In der Lethlorklamm birgt das Herz eines schwarzen Drachen die Hitze, die Sigrun Ironhew für ihre feurigen...",kw={"black drake's heart","feranor steeltoe","feurige verzauberungen","die lethlorklamm","scalding whelp","scorched guardian","sigrun ironhew"},ang={["faction:Alliance"]="Sigrun Ironhew bietet Euch an, ihre feurige Waffenverzauberung beizubringen, wenn Ihr ihr ein Herz eines schwarzen Drachen aus der Lethlorklamm bringt."},sec={{t="Eine Bitte der Schmiedin",b="Sigrun Ironhew lernte eine feurige Verzauberung von ihrem früheren Lehrer Feranor Steeltoe. Um die Technik anzuwenden, braucht sie das Blut aus dem noch schlagenden Herzen eines seltenen schwarzen Drachengeschöpfs. Bringt ihr eines aus der Lethlorklamm, und sie zeigt Euch die Verzauberung."}},faq={{q="Wozu dient Black Drake's Heart?",a="Sigrun Ironhew braucht dessen Blut, um Euch eine feurige Waffenverzauberung beizubringen.",al={"nutzen von black drake heart","warum ein herz","herz für sigrun"}},{q="Wo finde ich eines?",a="Scorched Guardians und Scalding Whelps in der Lethlorklamm können ein Black Drake's Heart hinterlassen.",al={"fundort von black drake heart","wo ist das herz","drachenherz erhalten"}},{q="Wer ist Sigrun Ironhew?",a="Sigrun Ironhew ist eine Schülerin von Feranor Steeltoe, der ihr eine besondere Technik beibrachte, um Waffen mit feurigen Verzauberungen zu versehen.",al={"sigrun","ironhew wer","sigruns hintergrundgeschichte"}},{q="Was bewirkt die Verzauberung?",a="Sie lässt Waffen mit sengender Hitze zuschlagen.",al={"wirkung feuriger verzauberungen","waffenfeuer","welche verzauberung"}}},fp="19,165,17.250.0,34.71.0,21.89.0,22.132.0,29.41.0"}
P.entries["item:black-feather-quill"] = {n="Schwarzer Federkiel",s="Im Grabhügel von Ban'ethil wird der Schwarze Federkiel gebraucht, um die Druids of the Talon zu wecken.",h="Im Grabhügel von Ban'ethil wird der Schwarze Federkiel gebraucht, um die Druids of the Talon zu wecken.",kw={"athridas bearmantle","grabhügel von ban'ethil","schwarzer federkiel","chest of the black feather","dolanaar","druids of the talon","relics of wakening"},ang={["class:Druid"]="Als Druide kennt Ihr den Federkiel als eines der heiligen Werkzeuge, die die Druids of the Talon an die wache Welt binden, während ihre Geister mit dem Smaragdgrünen Traum Zwiesprache halten.",["race:NightElf"]="Als Nachtelf kennt Ihr die Entweihung von Ban'ethils Relikttruhen durch Gnarlpine-Furbolgs als weitere schmerzliche Erinnerung an Teldrassils fortschreitende Verderbnis."},sec={{t="Ein Gefäß des Erwachens",b="Der Schwarze Federkiel ist einer von vier heiligen Fokussen, die die Druids of the Talon aus dem Winterschlaf wecken. Die anderen sind der Rabenkrallentalisman, der Saphir des Himmels und die Rune des Nistens. Gemeinsam rufen die Fokusse schlummernde Druiden aus dem Smaragdgrünen Traum zurück. Ohne sie kann ein Druide im Traum gefangen bleiben und nicht in seinen wachen Körper zurückkehren."},{t="Die Bedrohung in Ban'ethil",b="Verderbte Gnarlpine-Furbolgs überrannten den Grabhügel von Ban'ethil und bedrohten die Truhen, in denen die Relikte lagen. Athridas Bearmantle in Dolanaar ordnete ihre rasche Bergung an. Die gefangenen Druiden mussten befreit werden, bevor sie im Traum verloren gingen."}},faq={{q="Wofür wird der Schwarze Federkiel verwendet?",a="Der Schwarze Federkiel ist einer von vier heiligen Fokussen, mit denen die Druids of the Talon aus dem Winterschlaf im Smaragdgrünen Traum geweckt werden.",al={"schwarzer federkiel zweck","warum schwarzer federkiel nötig","was bewirkt der federkiel"}},{q="Wo wird der Schwarze Federkiel aufbewahrt?",a="Der Schwarze Federkiel wird in der Chest of the Black Feather aufbewahrt, tief im Grabhügel von Ban'ethil im Zentrum von Teldrassil.",al={"schwarzer federkiel fundort","wo ist die chest of the black feather","federkiel fundort"}},{q="Warum können die Druiden ohne den Federkiel und die anderen Relikte nicht erwachen?",a="Der druidische Winterschlaf versetzt die Druiden unter empfindlichen Verzauberungen in den Smaragdgrünen Traum. Ohne die heiligen Fokusse finden ihre schlummernden Geister den Weg zurück in ihre Körper nicht.",al={"warum brauchen druiden relikte zum erwachen","können druiden von allein erwachen"}},{q="Wer verlangt nach dem Schwarzen Federkiel?",a="Athridas Bearmantle in Dolanaar weist Abenteurer an, den Schwarzen Federkiel und die anderen heiligen Fokusse zu bergen, um die gefährdeten Druiden zu retten.",al={"wer braucht den federkiel","schwarzer federkiel questgeber"}}},fx={["8b872c36"]={q="Was ist der Schwarze Federkiel?",a="Der Schwarze Federkiel ist eines von vier heiligen Relikten des Erwachens, die von den Nachtelf-Druiden der Kralle innerhalb des Grabhügels von Ban'ethil auf Teldrassil bewahrt werden. In einer speziellen Truhe aufbewahrt, ist er ein wesentlicher zeremonieller Bestandteil, der verwendet wird, um schlafende Druiden friedlich aus dem Smaragdgrünen Traum zu wecken.",al={"was ist der schwarze federkiel","gegenstand schwarzer federkiel","lore schwarzer federkiel"}}},fp="19,91,20.359.0,23.238.0,41.129.0,38.122.0,64.185.0,37.147.0"}
P.entries["item:blackened-skull"] = {n="Geschwärzter Schädel",s="In Agamands Mühlen zeugen geschwärzte Schädel vom Kampf der Verlassenen gegen die Geißel. Todeswache Dillinger in Brill will Beweise dafür, dass die Darkeye Bonecasters vernichtet werden.",h="In Agamands Mühlen zeugen geschwärzte Schädel vom Kampf der Verlassenen gegen die Geißel.",kw={"agamands mühlen","geschwärzter schädel","brill","darkeye bonecaster","todeswache dillinger","schartige rippe","geißel","the mills overrun"},ang={["class:Mage"]="Als Magier wisst Ihr, dass diese Schädel die Überreste der skelettierten Zauberwirker sind, die in Agamands Mühlen bekämpft werden.",["race:Undead"]="Als Verlassene kämpft Ihr gegen Darkeye Bonecasters, um zu überleben und Euren früheren Meister daran zu hindern, direkt vor Eurer Haustür eine Ausgangsbasis zu errichten."},sec={{t="Trophäe der Bonecasters",b="Darkeye Bonecasters suchen Agamands Mühlen heim. Diese skelettierten Zauberwirker richten ihre nekromantische Bosheit gegen die Lebenden und die Verlassenen. Sie wollen einen vorgeschobenen Stützpunkt für die Armeen des Lich Kings im nördlichen Tirisfal errichten. Todeswache Dillinger in Brill fordert ihre zerstörten Schädel als Beweis dafür, dass die Zauberwirker der Geißel zurückgedrängt werden."}},faq={{q="Woher stammen geschwärzte Schädel?",a="Geschwärzte Schädel stammen von Darkeye Bonecasters, skelettierten Zauberwirkern auf den Feldern und in den Gebäuden rund um Agamands Mühlen im nördlichen Tirisfal.",al={"geschwärzter schädel herkunft","wer lässt geschwärzte schädel fallen","wo gibt es geschwärzte schädel"}},{q="Warum will Todeswache Dillinger geschwärzte Schädel?",a="Todeswache Dillinger will geschwärzte Schädel und eingekerbte Rippen als Beweis dafür, dass die Verteidiger der Verlassenen gegen die Geißel kämpfen. Die Verlassenen müssen verhindern, dass die geistlosen Diener des Lich Kings so nahe an Brill und Unterstadt Fuß fassen.",al={"dillinger schädel","warum schädel sammeln","mühlen überrannt schädel"}},{q="Warum sind die Schädel geschwärzt?",a="Niemand in Brill sagt, was die Schädel geschwärzt hat. Todeswache Dillinger will sie als Beweis dafür, dass die Darkeye Bonecasters in Agamands Mühlen vernichtet werden.",al={"warum ist er geschwärzt","geschwärzter schädel hintergrundgeschichte"}},{q="Was tut die Geißel in Agamands Mühlen?",a="Die Geißel versucht, die verlassenen Agamands Mühlen als vorgeschobene Ausgangsbasis für weiter reichende Angriffe und Überfälle in ganz Tirisfal zu befestigen.",al={"agamands mühlen geißel","warum ist die geißel bei den mühlen"}}},fx={d39fbd85={q="Was ist ein Geschwärzter Schädel?",a="Ein Geschwärzter Schädel ist eine düstere Trophäe, die den Dunkelaugen-Knochenwerfern entnommen wurde, die Agamands Mühlen heimsuchen. Diese dunklen Überreste dienen den Todeswachen der Verlassenen als physischer Beweis dafür, dass ein weiterer Zauberwirker der Geißel ausgeschaltet wurde, bevor er dabei helfen konnte, eine feindliche Basis in Tirisfal zu errichten.",al={"was ist ein geschwärzter schädel","gegenstand geschwärzter schädel","lore geschwärzter schädel"}}},fp="15,179,25.332.0,36.153.0,52.236.0,29.155.0,43.141.0"}
P.entries["item:blacklash-s-bindings"] = {n="Schattenbringers Bindungen"}
P.entries["item:bloodfeather-belt"] = {n="Blutfedergürtel",s="Im Norden Teldrassils drängen sich Blutfederharpien mit groben Ledergürteln auf der Lichtung des Orakels. Schildwache Arynia Wolkenbruch sammelt die Gürtel als Beweis dafür, dass die nahen Nester geräumt werden.",h="Im Norden Teldrassils drängen sich Blutfederharpien mit groben Ledergürteln auf der Lichtung des Orakels.",kw={"arynia wolkenbruch","blutfeder","blutfedergürtel","harpyie","die lichtung des orakels","teldrassil","the enchanted glade"},ang={["faction:Alliance"]="Als Mitglied der Allianz sorgt Ihr durch Eure Hilfe für Schildwache Arynia Wolkenbruch dafür, dass lebenswichtige Berichte von Teldrassils uralten Bäumen Darnassus’ Anführer ungehindert erreichen.",["race:NightElf"]="Als Nachtelf ist es Eure Pflicht, die Lichtung des Orakels dem Hexenzirkel der Blutfederharpien zu entreißen. Ihre Nester haben Teldrassils natürliches Blätterdach entweiht."},sec={{t="Trophäen aus den Nestern",b="Blutfederharpien haben sich angriffslustig in den Ästen rund um die Lichtung des Orakels eingenistet. Ihre Anwesenheit bedroht den uralten Oracle Tree und versperrt die Wege durch das nördliche Teldrassil. Nachdem die Schar einen Läufer mit Berichten für Darnassus überfallen und getötet hatte, rief Schildwache Arynia Wolkenbruch Reisende zum Angriff auf die Nester auf. Die Gürtel gefallener Harpyien zeigen, dass die Schar dezimiert und die Wege gesichert werden, damit Nachrichten die Hauptstadt wieder erreichen können."}},faq={{q="Warum will Schildwache Arynia Wolkenbruch diese Gürtel?",a="Arynia Wolkenbruch und ihre kleine Abteilung der Sentinels bewachen den heiligen Oracle Tree gegen die Blutfederharpien aus den nahen Nestern. Nachdem die Harpyien einen Boten auf dem Weg nach Darnassus getötet haben, bittet Arynia Reisende, Gürtel als Beweis für geräumte Nester und eine dezimierte Schar zurückzubringen.",al={"warum arynia gürtel will","zweck des blutfedergürtels","warum gürtel sammeln"}},{q="Woher stammen Blutfedergürtel?",a="Blutfederharpien in den Bäumen und Felsen rund um die Lichtung des Orakels im nördlichen Teldrassil tragen diese Gürtel. Jede Art innerhalb der Schar trägt einen, darunter Windhexen, Zauberinnen, Schurkinnen und Furien.",al={"wer lässt blutfedergürtel fallen","wo gürtel bekommen","fundort blutfedergürtel"}},{q="Warum sind Harpyien auf der Lichtung des Orakels ein Problem?",a="Die Harpyien haben nahe dem Oracle Tree genistet, einem uralten Baum, der über die Gesundheit des Weltbaums wacht. Ihre Angriffslust isoliert die Sentinels, die die Lichtung bewachen, und unterbricht gewaltsam die Übermittlung von Nachrichten nach Darnassus.",al={"harpyien lichtung des orakels","warum sind harpyien in teldrassil","harpyienbedrohung oracle tree"}}},fx={["40b720b3"]={q="Was ist ein Blutfedergürtel?",a="Ein Blutfedergürtel ist ein persönliches Schmuckstück, das von den Blutfederharpyien getragen wird, die die Lichtung des Orakels im nördlichen Teldrassil befallen. Für die Nachtelfen, die auf der Lichtung stationiert sind, dienen diese groben Gürtel als Trophäen und greifbarer Beweis dafür, dass eine weitere bösartige Harpyie aus den heiligen Zweigen entfernt wurde.",al={"informationen zu blutfedergürtel","was sind blutfedergürtel","lore blutfedergürtel"}}},fp="17,183,23.458.0,54.285.0,38.201.0,46.225.0"}
P.entries["item:bloodfury-ripper-s-remains"] = {n="Überreste der Blutfurienzerfetzerin",s="In Sonnenfels braucht Maggran Erdbinder die Überreste der Blutfurienzerfetzerin, um zu wissen, dass die Harpyienanführerin tot ist. Ihr Fall bedeutet weniger Gefahr für die Taurensiedlung.",h="In Sonnenfels braucht Maggran Erdbinder die Überreste der Blutfurienzerfetzerin, um zu wissen, dass die...",kw={"bloodfury-zerfetzerin","das verbrannte tal","harpyien","maggran erdbinder","überreste","steinkrallengebirge","sonnenfels"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Wege für Karawanen und Späher zwischen dem Brachland und dem Steinkrallengebirge zu sichern, indem Ihr Gefahren wie die Bloodfury-Matriarchin beseitigt.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Bloodfury-Harpyien Sonnenfels unmittelbar bedrohen. Die Überreste ihrer Anführerin zu bergen hilft, friedliche Taurensiedlungen im Steinkrallengebirge zu schützen."},sec={{t="Die Blutlinie durchtrennen",b="Die Bloodfury-Zerfetzerin führt die Harpyien des Verbrannten Tals mit wilder, revierbezogener Aggression an. Sie nisten zwischen den versengten Ruinen und bedrohen Reisende und Schamanen im gesamten Steinkrallengebirge. Das Ausdünnen der Schar bringt nur kurze Erleichterung. Maggran Erdbinder in Sonnenfels weiß, dass die Gefahr bestehen bleibt, solange ihre Anführerin lebt.\n\nDie Bloodfury-Zerfetzerin herrscht beinahe wie eine Königin und lenkt die Angriffe der Harpyien in ihrem Revier. Ihre Überreste beweisen ihren Tod. Wenn die Schar in Unordnung gerät, können die Tauren, die ihre zerklüfteten Lande heilen und sichern wollen, mehr Seelenfrieden finden."}},faq={{q="Wozu dienen die Überreste der Blutfurienzerfetzerin?",a="Die Überreste der Blutfurienzerfetzerin beweisen, dass die Harpyienanführerin tot ist. Maggran Erdbinder in Sonnenfels sucht sie, um ihren Tod zu bestätigen.",al={"wozu dienen die überreste","zweck der überreste","wer will die überreste"}},{q="Wo ist die Bloodfury-Zerfetzerin zu finden?",a="Die Bloodfury-Zerfetzerin streift über die westlichen und nordwestlichen Hügelzüge des Verbrannten Tals im südlichen Steinkrallengebirge. Ihr blaues Gefieder hebt sie von ihrer karminrot-weißen Schar ab.",al={"bloodfury-zerfetzerin fundort","wo ist die zerfetzerin","bloodfury-zerfetzerin finden"}},{q="Warum will Maggran Erdbinder ihren Tod?",a="Maggran Erdbinder glaubt, dass das Töten gewöhnlicher Harpyien ihre Überfälle auf die umliegenden Lande nicht aufhalten kann. Er will den Tod der Bloodfury-Zerfetzerin, um ihre Rangordnung zu zerschlagen und ihre Fähigkeit zu schwächen, sich gegen Sonnenfels zu sammeln.",al={"warum die bloodfury-zerfetzerin töten","maggrans beweggründe","warum soll die zerfetzerin sterben"}}},fx={ff70f27b={q="Was sind Überreste der Blutfurienzerfetzerin?",a="Diese grausamen Überreste sind der physische Beweis, der vom Körper der Blutfurienzerfetzerin stammt, der Matriarchin und Anführerin der Blutfurienharpyien, die das verbrannte Tal befallen. Sie agiert fast wie eine Königin für ihren Schwarm und leitet deren aggressive Ausbreitung im Steinkrallengebirge. Ihr erschlagener Körper dient als unbestreitbarer Beweis dafür, dass ihre Herrschaft über die Harpyien des Tals ein blutiges Ende gefunden hat.",al={"was sind überreste der blutfurienzerfetzerin","wer ist blutfurienzerfetzerin"}},ba88af47={q="Woher stammen die Überreste der Blutfurienzerfetzerin?",a="Diese Überreste werden von der Blutfurienzerfetzerin selbst geschnitten, nachdem man sie in den westlichen Hügeln des verbrannten Tals erschlagen hat. Anders als ihre roten und weißen Verwandten führt diese unverwechselbare blau gefiederte Harpyie die Blutfurienbrut von den trostlosen Klippen des Tals aus, was sie zu einem begehrten Ziel für jeden macht, der das Kommando des Schwarms brechen will.",al={"woher stammen überreste der blutfurienzerfetzerin","wer lässt überreste der blutfurienzerfetzerin fallen","ursprung überreste der blutfurienzerfetzerin"}},["81140692"]={q="Warum möchte Maggran Erdbinder die Überreste der Blutfurienzerfetzerin?",a="Maggran Erdbinder in Sonnenfels verlangt diese Überreste als Beweis dafür, dass die Matriarchin der Blutfurienharpyien wirklich tot ist. Die bloße Reduzierung ihrer Anzahl hätte nie ausgereicht; Maggran glaubt, dass das Erschlagen ihrer Königin die überlebenden Harpyien hilflos machen und ihre Anzahl schwinden lassen wird, wodurch er von dem bitteren Zorn befreit wird, der seine Gedanken verzehrte.",al={"warum will maggran die überreste der blutfurienzerfetzerin","warum sind überreste der blutfurienzerfetzerin gesucht","wer will überreste der blutfurienzerfetzerin"}}},fp="26,161,22.583.0,45.136.0,36.184.0,43.222.0"}
P.entries["item:bloodsail-charts"] = {n="Blutsegelkarten",s="Blutsegelkarten werden aus dem Lager der Blutsegelbukaniere an den wilden Ufern genommen. Flottenmeister Seehorn möchte, dass sie zusammen mit den Blutsegelbefehlen nach Beutebucht gebracht werden, damit er erfährt, was die Piraten planen.",h="Blutsegelkarten werden aus dem Lager der Blutsegelbukaniere an den wilden Ufern genommen.",kw={"blutsegelbukaniere","blutsegelkarten","blutsegelbefehle","beutebucht","kap des schlingendorntals","flottenmeister seehorn","die wilden ufer"},sec={{t="Karten von den wilden Ufern",b="Flottenmeister Seehorn schickt Euch zum Lager der Blutsegelbukaniere an den wilden Ufern. Er möchte, dass ihre Karten und schriftlichen Befehle nach Beutebucht gebracht werden. Mit beidem in der Hand kann die Flotte den Plan der Blutsegelbukaniere erfahren, sagt er."}},faq={{q="Wo sind die Blutsegelkarten?",a="Die Blutsegelkarten befinden sich im Lager der Blutsegelbukaniere an den wilden Ufern am Kap des Schlingendorntals.",al={"fundort der blutsegelkarten","wo sind die karten","karten wilde ufer"}},{q="Wer möchte die Karten?",a="Flottenmeister Seehorn in Beutebucht möchte die Blutsegelkarten und die Blutsegelbefehle.",al={"wer braucht die karten","seahorns karten","karten für den flottenmeister"}},{q="Warum braucht Seehorn sie?",a="Seehorn möchte mit den Karten und schriftlichen Befehlen erfahren, was die Blutsegelbukaniere planen.",al={"warum die karten","wozu dienen die karten","plan der blutsegelbukaniere"}},{q="Was soll ich zusammen mit den Karten zurückbringen?",a="Bringt die Blutsegelbefehle zusammen mit den Blutsegelkarten zu Flottenmeister Seehorn nach Beutebucht.",al={"karten und was noch","auch die blutsegelbefehle","befehle zurückbringen"}}},fp="16,195,21.224.0,31.104.0,21.82.0,27.96.0,41.90.0"}
P.entries["item:bloodsail-orders-classic"] = {n="Blutsegelbefehle",s="Die Blutsegelbefehle sind schriftliche Anweisungen, die die Blutsegelbukaniere an den wilden Ufern aufbewahren. Flottenmeister Seehorn in Beutebucht sucht danach, um herauszufinden, was die Bukaniere planen.",h="Die Blutsegelbefehle sind schriftliche Anweisungen, die die Blutsegelbukaniere an den wilden Ufern...",kw={"blutsegel","blutsegelbefehle","beutebucht","bukaniere","flottenmeister seehorn","schlingendorntal","die wilden ufer","schriftliche befehle"},sec={{t="Befehle von der Küste",b="An den wilden Ufern bewahren die Blutsegelbukaniere schriftliche Befehle in ihrem südlichen Kommandoposten auf. Flottenmeister Seehorn in Beutebucht möchte, dass diese Anweisungen zusammen mit den Blutsegelkarten zurückgebracht werden. Er will herausfinden, was die Bukaniere in der Nähe des Kaps planen."}},faq={{q="Was sind die Blutsegelbefehle?",a="Es sind schriftliche Anweisungen, die die Blutsegelbukaniere in ihrem Lager an den wilden Ufern aufbewahren.",al={"blutsegelbefehle","befehlsgegenstand"}},{q="Wo befinden sich die Blutsegelbefehle?",a="Die Blutsegelbefehle befinden sich im Lager der Blutsegelbukaniere an den wilden Ufern im Schlingendorntal.",al={"wo sind die befehle","befehle wilde ufer"}},{q="Wer möchte die Befehle haben?",a="Flottenmeister Seehorn in Beutebucht möchte, dass die Blutsegelbefehle zu ihm zurückgebracht werden.",al={"wer möchte die befehle","seehorn befehle"}},{q="Warum möchte Flottenmeister Seehorn sie haben?",a="Flottenmeister Seehorn möchte anhand der schriftlichen Befehle und Karten herausfinden, was die Blutsegelbukaniere planen.",al={"warum die befehle","was sucht seehorn"}},{q="Was soll ich zusammen mit den Befehlen zurückbringen?",a="Flottenmeister Seehorn möchte auch die Blutsegelkarten aus dem Lager an den wilden Ufern.",al={"befehle und karten","was noch mitbringen"}}},fp="16,181,21.260.0,30.94.0,31.110.0,21.81.0,40.123.0,41.84.0"}
P.entries["item:bloodscalp-tusk"] = {n="Bloodscalp Tusk",s="Ein Bloodscalp Tusk stammt von einem Troll des Bloodscalp-Stammes im nördlichen Schlingendorntal. Nimboya im Basislager Grom'gol bittet Euch um Hauer als Beweis, dass Ihr bei der Suche nach Yenniku helfen könnt.",h="Ein Bloodscalp Tusk stammt von einem Troll des Bloodscalp-Stammes im nördlichen Schlingendorntal.",kw={"bloodscalp","bloodscalp tusk","grom'gol","nimboya","schlingendorntal","troll","yenniku"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr Nimboya helfen, einem Dunkelspeer, der aus Orgrimmar entsandt wurde, um den verlorenen Sohn seines Häuptlings zu suchen.",["race:Troll"]="Als Troll könnt Ihr nachempfinden, wie schwer Yennikus Verlust wiegt: Er ist ein Dunkelspeer-Kind, das von seinem Volk getrennt wurde."},sec={{t="Der Beweis eines Jägers",b="Im Basislager Grom'gol bittet Nimboya Euch, ihm neun Bloodscalp Tusks zu bringen. Er muss wissen, dass Ihr den Stamm jagen könnt, bevor er Euch vertraut, bei der Suche nach Yenniku zu helfen, dem jüngsten Sohn seines Häuptlings. Die Hauer beweisen Eure Stärke."}},faq={{q="Was ist ein Bloodscalp Tusk?",a="Ein Bloodscalp Tusk stammt von einem Troll des Bloodscalp-Stammes im Schlingendorntal.",al={"bloodscalp tusk","was sind das für hauer"}},{q="Wer möchte Bloodscalp Tusks?",a="Nimboya im Basislager Grom'gol bittet Euch, ihm neun Bloodscalp Tusks zu bringen.",al={"wer möchte hauer","nimboyas hauer"}},{q="Warum braucht Nimboya die Hauer?",a="Nimboya möchte die Hauer als Beweis, dass Ihr stark genug seid, ihm bei der Suche nach Yenniku zu helfen.",al={"warum die hauer","grund für die hauer"}},{q="Wer ist Yenniku?",a="Yenniku ist der jüngste Sohn von Nimboyas Häuptling, und Nimboya glaubt, dass der Bloodscalp-Stamm ihn gefangen hält.",al={"wer ist yenniku","nimboyas häuptlingssohn"}},{q="Wo finde ich Bloodscalp-Trolle?",a="Der Bloodscalp-Stamm lebt im nördlichen Schlingendorntal.",al={"bloodscalp-gebiet","wo sind die bloodscalp"}}},fp="15,174,16.222.0,26.83.0,27.74.0,32.91.0,15.98.0,35.58.0"}
P.entries["item:bloodstone-choker"] = {n="Blutsteinhalsreif",s="Gakin der Dunkelbinder besitzt in Sturmwind den Blutsteinhalsreif, der das Ritual eines Hexenmeisters an die Leere bindet. Seine Schülerin stahl den Talisman und floh zur Bruderschaft der Defias.",h="Gakin der Dunkelbinder besitzt in Sturmwind den Blutsteinhalsreif, der das Ritual eines Hexenmeisters an die...",kw={"blutsteinhalsreif","defias","gakin der dunkelbinder","surena caledon","the binding","the slaughtered lamb","leerwandler","hexenmeister"},ang={["class:Warlock"]="Als Hexenmeister der Allianz markiert die Rückgewinnung des Blutsteinhalsreifs für Euch den Übergang von grundlegender Zauberkunst zur Herrschaft über mächtige dämonische Diener.",["faction:Alliance"]="Surena Caledons Flucht zur Bruderschaft der Defias zeigt, dass Gesetzlose in Elwynn gefährliche okkulte Relikte suchen, um ihren Aufstand gegen Sturmwind zu stärken."},sec={{t="Ein gestohlener Ritualfokus",b="Gakin der Dunkelbinder, ein Hexenmeisterlehrer unter dem Gasthaus Slaughtered Lamb in Sturmwind, besaß einst den Blutsteinhalsreif. Seine Schülerin Surena Caledon verriet ihn und stahl ihn. Sie floh in die Wälder von Elwynn und schloss sich der Bruderschaft der Defias an, wobei sie den verzauberten Talisman mitnahm. Jetzt befindet sie sich bei Brackbrunns Kürbisbeet. Der Halsreif muss zurückgeholt werden, bevor die Banditen seine Macht nutzen."},{t="Die Leere zähmen",b="Der aus Blutstein geschnitzte Halsreif verbindet die sterbliche Welt mit den sich windenden Schatten des Wirbelnden Nethers. In den Krypten unter der Taverne kanalisiert Gakin seine Magie am Beschwörungskreis. Ein feindseliger Leerwandler antwortet aus der Leere. Ein Hexenmeister muss sich dem wütenden Wesen im direkten Kampf stellen und es bezwingen, während er den Talisman führt. Erst dann ist die Willenskraft bewiesen, einen solchen Wächter zu befehligen."}},faq={{q="Was ist der Blutsteinhalsreif?",a="Hexenmeister verwenden den Blutsteinhalsreif, eine verzauberte Halskette aus Blutstein, als Ritualfokus. Seine Magie kann die Wirklichkeit aufreißen und einen widerspenstigen Leerwandler aus dem Nether herbeirufen.",al={"blutsteinhalsreif","was ist der halsreif","was bewirkt der halsreif"}},{q="Wem gehörte der Halsreif ursprünglich?",a="Gakin der Dunkelbinder war der erste Besitzer des Halsreifs. Er bildet Hexenmeister in einem verborgenen Keller unter dem Gasthaus The Slaughtered Lamb im Magierviertel von Sturmwind aus.",al={"wem gehört der halsreif","gakin halsreif","woher stammt der halsreif"}},{q="Warum wurde der Halsreif gestohlen?",a="Surena Caledon stahl den Halsreif von ihrem Mentor Gakin und floh dann, um sich der Bruderschaft der Defias anzuschließen. Sie suchte Macht unter den Banditen, die sich im Wald von Elwynn versteckten.",al={"wer hat ihn gestohlen","warum hat surena ihn gestohlen","surena caledon halsreif"}},{q="Wie wird der Halsreif bei der Hexenmeisterausbildung eingesetzt?",a="Ein Hexenmeister aktiviert den zurückgeholten Halsreif über dem Beschwörungskreis in den Krypten unter dem Gasthaus The Slaughtered Lamb. Er lockt einen Leerwandler hervor, den der angehende Hexenmeister besiegen und unterwerfen muss, um den Dämon zu befehligen.",al={"halsreif verwenden","leerwandler ritual halsreif","the binding halsreif"}}},fx={["9d3659ea"]={q="Warum wird der Blutsteinhalsreif gesucht?",a="Gakin der Dunkelbinder schätzt den Blutsteinhalsreif als einen mächtigen magischen Katalysator, der benötigt wird, um einen Leerwandler zu beschwören und zu binden. Nachdem seine frühere Schülerin Surena Caledon ihn gestohlen hatte, um der The Defias Brotherhood zu helfen, sucht Gakin nun nach seiner Rückgabe, um seine arkanene Autorität wiederherzustellen und neue Hexenmeister in den Krypten unter dem The Slaughtered Lamb zu prüfen.",al={"warum wird der blutsteinhalsreif gesucht","wer will den blutsteinhalsreif","warum will gakin den halsreif"}}},fp="17,164,16.382.1,15.394.0,30.174.0,32.144.0,26.157.0,43.209.0"}
P.entries["item:bloody-bone-necklace"] = {n="Bloody Bone Necklace",s="Ein Bloody Bone Necklace ist eine Trophäe eines Bloodscalp-Trolls aus dem Schlingendorntal. Kin'weelay im Basislager Grom'gol nutzt die Halsketten in einem Ritual gegen den Feind seines Stammes.",h="Ein Bloody Bone Necklace ist eine Trophäe eines Bloodscalp-Trolls aus dem Schlingendorntal.",kw={"bloodscalp","bloody bone necklace","bloody bone necklaces","grom'gol","kin'weelay","schlingendorntal","trolltrophäe"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr Kin'weelay helfen, einem Troll im Lager der Horde in Grom'gol, dem Bloodscalp-Stamm entgegenzutreten.",["race:Troll"]="Als Troll könnt Ihr sehen, wie Kin'weelay eine Trophäe des Bloodscalp-Stammes in eine rituelle Waffe gegen deren Besitzer verwandelt."},sec={{t="Eine Trolltrophäe",b="Kin'weelay bittet Euch, fünfundzwanzig Bloody Bone Necklaces zum Basislager Grom'gol zu bringen. Der Bloodscalp-Stamm lebt im Norden und ist Kin'weelays Feind. Er glaubt, dass die Trophäen seines Stammes ihm Macht über sie verleihen."},{t="Kin'weelays Ritual",b="In Grom'gol kocht Kin'weelay die Halsketten aus und setzt Blutegel an ihnen an, bis sie zu einer Paste werden. Er sagt, das Ritual werde die Geister ihrer Besitzer schwächen. Für diesen Dienst begleicht er die Schuld, die ihn ins Lager brachte."}},faq={{q="Was ist ein Bloody Bone Necklace?",a="Ein Bloody Bone Necklace ist eine Trophäe, die einem Bloodscalp-Troll im Schlingendorntal abgenommen wird.",al={"bloody bone necklace","knochenhalskette","bloodscalp-trophäe"}},{q="Wer will die Halsketten?",a="Kin'weelay im Basislager Grom'gol bittet um fünfundzwanzig Bloody Bone Necklaces.",al={"wer will diese","kin'weelay halskette","halsketten-npc"}},{q="Woher stammen die Halsketten?",a="Bloodscalp-Trolle im Schlingendorntal tragen die blutigen Knochenhalsketten.",al={"woher halsketten bekommen","bloodscalp-halsketten","halsketten-herkunft"}},{q="Warum will Kin'weelay sie?",a="Kin'weelay sagt, dass Trophäen des Bloodscalp-Stammes seinem eigenen Stamm Macht über seinen Feind verleihen.",al={"warum kin knochen will","warum halskette sammeln","stammesmacht"}},{q="Was macht Kin'weelay mit den Halsketten?",a="Kin'weelay kocht die Halsketten aus und setzt Blutegel an ihnen an. Dann verarbeitet er sie in einem Ritual zu einer Paste, die die Geister ihrer Besitzer schwächen soll.",al={"was mit halsketten geschieht","halsketten auskochen","halskettenritual"}},{q="Wo ist Kin'weelay?",a="Kin'weelay ist im Basislager Grom'gol im Schlingendorntal.",al={"kin'weelay standort","grom'gol npc","kin in grom'gol"}}},fp="20,171,14.228.0,17.211.1,31.87.0,24.76.0,33.71.0,30.99.0,43.119.0,20.58.0"}
P.entries["item:blueleaf-tuber"] = {n="Blaulaubknolle",s="Tief unter dem Kral der Klingenhauer lockt die Blaulaubknolle reiche Feinschmecker und Händler aus aller Welt an.",h="Tief unter dem Kral der Klingenhauer lockt die Blaulaubknolle reiche Feinschmecker und Händler aus aller Welt...",kw={"brachland","blaulaubknolle","mebok mizzyrix","ratschet","kral der klingenhauer","schnüffelgopher","knolle"},ang={["profession:Cooking"]="Blaulaubknollen sind eine seltene kulinarische Delikatesse, die von den reichsten Feinschmeckern begehrt wird, obwohl sie im kargen Boden der Baue der Borstennacken wachsen."},sec={{t="Eine seltene unterirdische Delikatesse",b="Blaulaubknollen wachsen unter dem Kral der Klingenhauer im Brachland. Dichte Wurzeln und Dornengestrüpp der Borstennacken halten Gelegenheitssammler fern. Der Boden ist karg, doch reiche Feinschmecker und Händler aus aller Welt zahlen für ihren unverwechselbaren Geschmack einen exorbitanten Preis."},{t="Ernte mit Gopherhilfe",b="In Ratschet entwickelte der Goblin Mebok Mizzyrix eine Methode, um die verborgenen Wurzeln zu finden. Er richtet einheimische Schnüffelgopher darauf ab, Knollen aus fünfzig Schritt Entfernung zu wittern. Mit speziellen Befehlsstöcken lenken Abenteurer die Gopher und graben die Wurzeln aus, bevor Patrouillen der Borstennacken Wind von dem Eindringen bekommen."}},faq={{q="Wofür werden Blaulaubknollen verwendet?",a="Wohlhabende Kunden und Händler exotischer Waren zahlen für Blaulaubknollen wegen ihres unverwechselbaren Geschmacks und ihrer Seltenheit einen hohen Preis.",al={"knollenverwendung","warum blueleaf tubers sammeln","wofür sind knollen"}},{q="Wo sind Blaulaubknollen zu finden?",a="Blaulaubknollen wachsen tief unter der Erde im Kral der Klingenhauer im Südlichen Brachland, zwischen seinem Dornengestrüpp und seinen unterirdischen Bauen.",al={"wo wachsen blueleaf tubers","knollenfundort","wo sind knollen"}},{q="Warum braucht Ihr einen Gopher, um sie auszugraben?",a="Blaulaubknollen verbergen sich unter der obersten Erdschicht, wo Menschen und Goblins sie nicht sehen können. Abgerichtete Schnüffelgopher wittern sie aus fünfzig Schritt Entfernung und graben sie auf Befehl aus.",al={"warum schnüffelgopher","gopherzweck","warum gopher"}},{q="Wer kauft diese Knollen?",a="Der in Ratschet ansässige Goblinunternehmer Mebok Mizzyrix kauft Blaulaubknollen, um sie mit sattem Gewinn an wohlhabende Käufer und internationale Kontakte weiterzuverkaufen.",al={"wer will blueleaf tubers","wer kauft knollen","mebok knollen"}}},fx={["094c1930"]={q="Woher stammt die Blaulaubknolle?",a="Blaulaubknollen sind natürliche unterirdische Wurzeln, die ausschließlich im Südlichen Brachland heimisch sind und tief in den verworrenen Wurzelsystemen des Krals der Klingenhauer wachsen. Sie werden von niemandem hergestellt, sondern direkt aus dem unterirdischen Boden geerntet, wobei abgerichtete Schnüffelgopher eingesetzt werden, um sie aufzuspüren.",al={"ursprung blaulaubknolle","wo wachsen blaulaubknollen","wer hat blaulaubknollen gemacht"}},["9eab4987"]={q="Was ist eine Blaulaubknolle?",a="Eine Blaulaubknolle ist eine überaus seltene essbare Wurzel, die tief unter der Erde im Kral der Klingenhauer vergraben liegt. Aufgrund ihres kulinarischen Werts preiswürdig, gilt sie auf der ganzen Welt als Delikatesse, auch wenn ihre Beschaffung angesichts der Stacheleber, die ihre heimatlichen Gefilde heimsuchen, tückisch ist.",al={"was ist blaulaubknolle","blaulaubknolle lore","was sind blueleaf tubers"}}},fp="14,102,27.246.0,26.291.0,34.113.0,35.121.0,40.170.0,22.151.0"}
P.entries["item:bonegrip-s-note"] = {n="Bonegrip's Note",s="Gerrig Knochengriff notiert drei Reliquien, die er im Ödland braucht. So bleiben ihre Namen unwillkommenen Ohren verborgen.",h="Gerrig Knochengriff notiert drei Reliquien, die er im Ödland braucht.",kw={"knochengriffs notiz","gerrig knochengriff","hand von dagun","eisenschmiede","legacy heart","stern von xil'yeh","drei reliquien"},ang={["faction:Alliance"]="Als Reisende der Allianz könnt Ihr Gerrigs schriftliche Bitte aus dem Ödland zu ihm nach Eisenschmiede bringen."},sec={{t="Niedergeschriebene Namen",b="Gerrig Knochengriff bittet Euch, ihm drei mächtige Gegenstände nach Eisenschmiede zu bringen. Er spricht ihre Namen nicht laut aus, denn vielleicht lauschen Ohren. Stattdessen schreibt er sie auf Bonegrip's Note und gibt sie Euch."}},faq={{q="Was ist Bonegrip's Note?",a="Bonegrip's Note ist eine schriftliche Liste mit drei mächtigen Gegenständen, die Gerrig Knochengriff braucht.",al={"knochengriffs notiz","was ist die notiz","knochengriffs zettel"}},{q="Wer hat die Notiz geschrieben?",a="Gerrig Knochengriff schrieb die Notiz, damit er die Namen der Reliquien nicht laut aussprechen muss.",al={"wer schrieb diese notiz","gerrigs notiz","wer ist knochengriff"}},{q="Was braucht Gerrig?",a="Gerrig braucht den Stern von Xil'yeh, die Hand von Dagun und das Legacy Heart.",al={"welche gegenstände stehen darauf","drei reliquien","was steht auf der notiz"}},{q="Warum sind die Namen aufgeschrieben?",a="Gerrig sagt, dass vielleicht Ohren lauschen. Deshalb schreibt er die Namen der Reliquien auf, statt sie auszusprechen.",al={"warum spricht er sie nicht aus","ohren lauschen mit","geheime gegenstandsnamen"}}},fp="15,122,13.203.0,24.80.0,19.85.0,22.74.0,31.96.0"}
P.entries["item:book-from-sven-s-farm"] = {n="Buch von Svens Hof",s="Im Dämmerwald birgt ein verborgenes Tagebuch auf Svens zerstörtem Hof Bruchstücke des Angriffs auf seine Familie, gesehen von einem unbekannten Beobachter.",h="Im Dämmerwald birgt ein verborgenes Tagebuch auf Svens zerstörtem Hof Bruchstücke des Angriffs auf seine...",kw={"buch von svens hof","dunkelhain","bruderschaft der defias","dämmerwald","bibbers","shadowy figure","sven yorgen","worgen"},ang={["faction:Alliance"]="Als Ermittler der Allianz könnt Ihr mit diesem witterungsbeschädigten Buch den Schrecken im südlichen Dämmerwald nachgehen und erfahren, wie das wilde Worgenrudel dort Fuß fasste."},sec={{t="Eine Spur im Erdreich",b="Ein beschädigtes Tagebuch liegt unter lockerer Erde zwischen den verkohlten Überresten von Svens Hof im südlichen Dämmerwald. Sein anonymer Verfasser hinterließ hastige, unvollständige Notizen über die Tragödie auf dem Gehöft. Die Seiten stützen Sven Yorgens Verdacht, dass jemand aus den Schatten zusah, als seine Familie erschlagen wurde. Der Bericht bricht ab, ohne den Verfasser zu nennen oder zu erzählen, was danach geschah.\n\nSvens Spur führt die Ermittler dazu, das Buch nach Dunkelhain zu bringen. Sie hoffen, dass dort jemand die Handschrift erkennt."},{t="Das Rätsel um die Shadowy Figure",b="In Dunkelhain helfen Mystiker und Stadtbewohner herauszufinden, dass der Besitzer des Tagebuchs ein Fremder war, der voller Entsetzen durch die Wälder floh. Verblasste Abdrücke auf seinen Seiten führen zu Bibbers, einem Landstreicher, der sich im Wald versteckt. Bibbers' fehlende Einträge erzählen, wie die Bruderschaft der Defias mit verbotenen Artefakten hantierte und versehentlich gefräßige Worgen auf den Dämmerwald losließ. Wer ihn findet, fügt die Bruchstücke in seinem vervollständigten Tagebuch zusammen."}},faq={{q="Wo findet man das Buch von Svens Hof?",a="Das Buch liegt unter lockerer Erde auf Sven Yorgens zerstörtem Hof im südlichen Dämmerwald.",al={"wo svens buch finden","erdhaufen svens hof","svens buch fundort"}},{q="Wer schrieb das Buch, das auf Svens Hof gefunden wurde?",a="Das Buch hat weder einen Titel noch einen Verfassernamen. Sein Verfasser war ein verängstigter Mann, der vor einem Grauen anderswo im Dämmerwald floh, sich in Svens Scheune versteckte, die Ermordung von Svens Familie mitansah und sein Tagebuch verlor.",al={"verfasser von svens buch","wer schrieb das erdverschmierte buch","wer schrieb das tagebuch"}},{q="Warum will Sven Yorgen dieses Buch haben?",a="Nach dem Angriff auf seine Familie sah Sven eine unbekannte Gestalt nahe seiner Scheune. Das Buch bestätigt, dass es den Beobachter wirklich gab, und gibt Sven eine Spur, um herauszufinden, was in jener Nacht geschah.",al={"warum ist es sven wichtig","sven yorgens reaktion auf das buch"}},{q="Was geschieht mit dem Buch, nachdem Ihr es untersucht habt?",a="Nachdem Ihr das unvollständige Tagebuch den Bewohnern von Dunkelhain gezeigt und seinen Besitzer gefunden habt, tritt Bibbers' Completed Journal an seine Stelle und erzählt die ganze Geschichte.",al={"was ersetzt svens buch","behält man svens buch"}},{q="Welches größere Geheimnis hängt mit dem Inhalt des Buches zusammen?",a="Das vollständige Tagebuch erzählt, was seinen Verfasser dazu trieb, sich zu verstecken, und warum Svens Familie angegriffen wurde. Seine Geschichte reicht über einen einzelnen Hof hinaus bis zu der Dunkelheit über dem Dämmerwald.",al={"welche hintergrundgeschichte steht in svens buch","verbindung zu worgen","verbindung zu den defias"}}},fx={fd4c7f5f={q="Was ist das Buch von Svens Hof?",a="Es ist ein unbetiteltes, schmutzverschmiertes Tagebuch, das aus den Ruinen von Sven Yorgens verwüstetem Gehöft im Dämmerwald ausgegraben wurde. Obwohl es verwittert und unvollständig ist, enthalten seine handgeschriebenen Seiten einen Augenzeugenbericht über die Schrecken, die über Svens Hof und seine Familie hereinbrachen. Noch wichtiger ist, dass es als physischer Beweis dafür dient, dass während des Massakers ein schattenhafter Zuschauer anwesend war, der wichtige Antworten darauf hält, wer den Hof angriff und warum.",al={"was ist buch von svens hof","schmutzverschmiertes buch dämmerwald","was ist das schmutzverschmierte buch"}}},fp="21,125,18.498.0,29.422.1,41.83.0,40.190.1,36.175.0,50.149.1,55.161.1"}
P.entries["item:book-of-the-ancients"] = {n="Book of the Ancients"}
P.entries["item:book-stresses-of-iron"] = {n="Buch: Belastbarkeit von Eisen",s="Margulf Blaggons Metallurgiebuch aus Burg Sturmwind ist zum Abschreiben in der Abtei von Nordhain.",h="Margulf Blaggons Metallurgiebuch aus Burg Sturmwind ist zum Abschreiben in der Abtei von Nordhain.",kw={"bruder kristoff","brother paxton","margulf blaggon","metallurgie","milton garbenbund","abtei von nordhain","royal library","belastbarkeit von eisen"},ang={["profession:Blacksmithing"]="Margulf Blaggons Buch untersucht die Belastbarkeit von Eisen und die praktischen Grenzen seiner Verarbeitung."},sec={{t="Ein entliehener Band",b="Margulf Blaggon schrieb über Metallurgie in Praxis und Theorie. Milton Garbenbund betreute den Band in der Royal Library von Burg Sturmwind. Die Bibliothek verlieh ihn an die Abtei von Nordhain, wo Bruder Paxton ihn für seine eigene Sammlung von Hand abschrieb. Die Arbeit dauerte weit länger als erwartet. So wartete Bruder Kristoff auf dem Kathedralenplatz besorgt darauf, dass das Buch in die Stadt zurückkehrte."}},faq={{q="Wovon handelt das Buch?",a="Margulf Blaggons Buch behandelt Metallurgie und Metallverarbeitung in Theorie und Praxis.",al={"was ist belastbarkeit von eisen","thema von belastbarkeit von eisen","buchinhalt"}},{q="Warum war das Buch in der Abtei von Nordhain?",a="Bruder Paxton lieh sich das Buch aus Sturmwinds Royal Library, um es für seine eigene Sammlung von Hand abzuschreiben. Anschließend sollte er das Original zurückgeben.",al={"warum hatte paxton es","warum in nordhain"}},{q="Wer wollte das Buch zurückhaben?",a="Bruder Kristoff wollte das Buch zurückhaben. Er wartete auf dem Kathedralenplatz und bat dringend darum. Ein Abenteurer ging dem Verbleib des Buches zwischen der Royal Library und Nordhain nach.",al={"wer braucht das buch","wer wartet darauf"}}},fx={["7d684098"]={q="Woher stammt Stresses of Iron und wer hat es geschrieben?",a="Das Buch wurde von Margulf Blaggon als wissenschaftliche Abhandlung über Metallurgie verfasst. Sein Zuhause ist die Royal Library in Burg Sturmwind, obwohl Bruder Paxton den Band ausgeliehen und zur Abtei von Nordhain gebracht hatte, damit er für seine eigenen Regale eine Kopie mühsam transkribieren konnte.",al={"wer schrieb stresses of iron","autor von stresses of iron","ursprung von stresses of iron"}}},fp="22,98,17.376.0,23.83.0,37.146.0,29.178.0"}
P.entries["item:bottle-of-disease"] = {n="Krankheitsflasche",s="Nahe dem Dor'danil-Grabhügel in Eschental brauen Alchemisten der Verlassenen Krankheiten. Ihr Lager birgt Flaschen mit hochansteckenden Gebräuen.",h="Nahe dem Dor'danil-Grabhügel in Eschental brauen Alchemisten der Verlassenen Krankheiten.",kw={"eschental","seuche","krankheitsflasche","der dor'danil-grabhügel","forest song","verlassene","verlassenenkrankheit","kayneth stillwind"},ang={["class:Druid"]="Als Druide wisst Ihr, dass verseuchte Gemische und künstliche Seuchen dem natürlichen Gleichgewicht zuwiderlaufen. Handelt rasch, um den Wald zu bewahren.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass eine Seuche der Untoten auf Eschentals Boden ein unverzeihlicher Frevel ist, besonders nahe dem Dor'danil-Grabhügel."},sec={{t="Seuche in den heiligen Wäldern",b="Jenseits der Frontlinien der Vorhut des Kriegshymnenklans brauen Alchemisten der Verlassenen nahe dem Dor'danil-Grabhügel Seuchen. Die Flaschen liefern den Nachtelfen in Forest Song Beweise für einen Angriff auf die Wälder. Die Verlassenen wollen Boden und Tierwelt mit Krankheiten befallen, statt sich den Schildwachen im offenen Kampf zu stellen."},{t="Kayneth Stillwinds Untersuchung",b="Kayneth Stillwind ist eine nachtelfische Schildwache in Forest Song. Er sucht Beweise für die Bestrebungen der Verlassenen und möchte eine Krankheitsflasche, um ihren Inhalt zu untersuchen. Die Nachtelfen fürchten, die Gemische könnten heilige Grabhügel verderben und Geist und Körper der Verteidiger des Waldes brechen."}},faq={{q="Was steckt in der Krankheitsflasche?",a="Apotheker der Verlassenen brauen synthetische Gifte und magische Seuchen in der Flasche. Die Royal Apothecary Society führt umfassendere Experimente mit hochansteckenden Seuchen durch.",al={"was ist in der flasche","krankheitsflasche inhalt","trank der verlassenen"}},{q="Wo sind diese Flaschen zu finden?",a="Ihr findet die Flaschen in einem abgelegenen Lager der Verlassenen südlich von Forest Song, nahe dem Eingang zum Dor'danil-Grabhügel im östlichen Eschental.",al={"wo krankheitsflasche finden","krankheitsflasche fundort","lager der verlassenen eschental"}},{q="Wer möchte die Krankheitsflasche?",a="Kayneth Stillwind, ein nachtelfischer Beschützer in Forest Song, möchte, dass Ihr eine Flasche beschafft. Er hofft, ihren Inhalt zu untersuchen und die Absichten der Horde zu ergründen.",al={"wer nimmt die krankheitsflasche","krankheitsflasche abgeben","kayneth stillwind quest"}},{q="Warum brauen die Verlassenen Krankheiten in Eschental?",a="Die Nachtelfen vermuten, dass die Verlassenen den heiligen Wald infizieren und nahe gelegene Grabhügel entweihen wollen. Sie fürchten, dass dies das Ökosystem vergiften und den Widerstand der Nachtelfen von innen schwächen wird.",al={"warum verlassene in eschental","ziel der untoten in eschental","verlassene grabhügel"}}},fx={["4091970d"]={q="Was ist die Krankheitsflasche?",a="Es handelt sich um eine versiegelte Phiole, die virulente Gifte und Fäulnis enthält, welche von den Verlassenen gebraut wurden. Agenten der Unterstadt brauen diese abscheulichen Gebräue in geheimen Lagern im gesamten Eschental und füllen sie ab, um sie zu transportieren und gezielt in den uralten Wäldern der Elfen zu verbreiten.",al={"was ist die krankheitsflasche","hintergrundinformationen zur krankheitsflasche","informationen zur krankheitsflasche"}},["62494cf6"]={q="Woher stammt die Krankheitsflasche und wer hat sie hergestellt?",a="Die Flasche wird von Apothekern der Verlassenen gebraut, die in einem abgelegenen Lager südlich von Forest Song, nahe dem Dor'danil-Grabhügel, stationiert sind. Diese untoten Alchemisten lauern in der Nähe heiliger Grabhügel der Nachtelfen und ernten und destillieren aktiv gefährliche Gifte und Fäulnis auf dem Boden von Kalimdor.",al={"wer hat die krankheitsflasche hergestellt","ursprung der krankheitsflasche","woher kommt die krankheitsflasche"}},["9d281de4"]={q="Warum möchte Kayneth Stillwind die Krankheitsflasche haben?",a="Kayneth Stillwind in Forest Song benötigt eine intakte Probe, um zu analysieren, was die Verlassenen planen. Durch das Testen der alchemistischen Eigenschaften des Gebräus hoffen die Nachtelfen zu bestätigen, ob die Untoten darauf abzielen, das Eschental selbst zu verseuchen, und eine wirksame Gegenmaßnahme vorzubereiten.",al={"warum will man die krankheitsflasche","warum sollte man die krankheitsflasche holen","warum will kayneth die krankheitsflasche"}}},fp="17,129,26.290.0,33.266.1,37.163.0,30.145.0,32.152.0,51.191.0"}
P.entries["item:bottle-of-moonshine"] = {n="Flasche mit Fusel",s="In Dunkelhain ist eine Flasche mit Fusel für Seenhains Taverne bestimmt. Barkeeper Daniels braucht sie, während Schwarzfelsorcs verhindern, dass die üblichen Lieferungen den Ort erreichen.",h="In Dunkelhain ist eine Flasche mit Fusel für Seenhains Taverne bestimmt.",kw={"barkeeper daniels","flasche mit fusel","dunkelhain","dry times","dämmerwald","seenhain","fusel","scarlet raven tavern"},ang={["faction:Alliance"]="Die Reise von Dunkelhain nach Seenhain zeigt, wie anfällig die Versorgungswege zwischen Sturmwinds verstreuten Siedlungen während der Krise sind."},sec={{t="Hochprozentige Hilfe",b="Schwarzfelsorcs haben Seenhains regelmäßige Versorgungskarawanen abgeschnitten. Deshalb sucht Barkeeper Daniels Getränke aus der Region, um die Vorräte der Taverne für Wachen und Einwohner aufzufüllen. Eines stammt aus der Scarlet Raven Tavern in Dunkelhain, wo die Einheimischen starke Getränke bevorzugen."}},faq={{q="Wo kann ich eine Flasche mit Fusel finden?",a="Ihr findet eine Flasche mit Fusel in der Scarlet Raven Tavern in Dunkelhain im Dämmerwald.",al={"wo fusel kaufen","dunkelhain fusel fundort","flasche mit fusel händler"}},{q="Wer will diese Flasche?",a="Barkeeper Daniels, Seenhains Gastwirt im Rotkammgebirge, will die Flasche und weitere Getränke aus der Region für seinen Keller während der Belagerung durch die Orcs.",al={"wer braucht fusel","fusel quest abgeben","barkeeper daniels fusel"}},{q="Warum geht Seenhain der Schnaps aus?",a="Schwarzfelsorcs haben das Rotkammgebirge überrannt. Sie überfallen Reisende auf den Straßen und haben die Handelswege abgeschnitten. Die regelmäßigen Lieferungen bleiben aus, sodass die Regale in Seenhains Taverne fast leer sind.",al={"warum dry times","seenhain versorgungsengpass","rotkammgebirge alkoholmangel"}}},fx={["1eb07341"]={q="Was ist eine Flasche mit Fusel?",a="Es ist eine starke Spirituose, die im Dämmerwald in der Scarlet Raven Tavern in Dunkelhain verkauft wird. Auch wenn illegaler oder scharfer Schnaps in einem verschlafenen Rückzugsort am See fehl am Platz erscheinen mag, erfordern harte Zeiten starke Getränke.",al={"was ist fusel","informationen zur flasche mit fusel","was ist die flasche mit fusel"}},["5d3a7e66"]={q="Woher stammt diese Flasche mit Fusel?",a="Dieser spezielle Schnaps stammt aus der schattenhaften Stadt Dunkelhain im Dämmerwald und wird in der Scarlet Raven Tavern vorrätig gehalten. Da die lokalen Versorgungswege im gesamten Königreich überlastet sind, suchen die Schankwirte überall nach Möglichkeiten, ihre Regale gefüllt zu halten.",al={"wer stellt den fusel her","wo wird der fusel hergestellt","ursprung des fusels"}},["08a7d809"]={q="Warum wird eine Flasche mit Fusel in Seenhain benötigt?",a="Barkeeper Daniels benötigt sie, um den Schankbetrieb in Seenhain aufrechtzuerhalten. Zwischen der Invasion der Schwarzfelsorcs und den unterbrochenen Handelsrouten ist der Schnapsvorrat der Stadt fast völlig aufgebraucht. Daniels schickt Reisende durch das Land der Menschen, um starken Alkohol zu beschaffen – einschließlich dieses Fusels aus Dunkelhain –, um seine gestressten Gäste zufriedenzustellen.",al={"warum will seenhain fusel","warum fusel kaufen","wer benötigt fusel"}}},fp="19,158,17.250.0,39.93.0,22.147.0,39.187.0"}
P.entries["item:bottle-of-zombie-juice"] = {n="Flasche mit Zombiesaft",s="In Dunkelhain ist die Flasche mit Zombiesaft für Calvinius bestimmt, einen zurückgezogenen Einsiedler im Dämmerwald. Er sagt, der starke Schnaps aus Faulblüten halte ihn warm.",h="In Dunkelhain ist die Flasche mit Zombiesaft für Calvinius bestimmt, einen zurückgezogenen Einsiedler im...",kw={"calvinius","flasche mit zombiesaft","dunkelhain","dämmerwald","juice delivery","faulblüte","zombie juice"},ang={["faction:Alliance"]="Botengänge zwischen Dunkelhain und der schattenverhangenen Wildnis verbinden die geplagten Bewohner des Dämmerwalds, selbst wenn die Arbeit fragwürdig erscheint.",["profession:Herbalism"]="Kräuterkundige, die den Dämmerwald kennen, wissen, dass Faulblüten für gewöhnliche Stärkungsmittel ungeeignet sind. Ihre Verwendung in einem Getränk ist beunruhigend."},sec={{t="Ein stechendes Gebräu",b="Im Dämmerwald gesammelte Faulblüten werden zu diesem scharfen Gebräu verarbeitet. Der Schankwirt in Dunkelhain warnt, es sei stark genug, um die Toten zu erwecken. Die meisten Leute wollen mit solch einem abscheulichen Getränk nichts zu tun haben. Doch Calvinius, ein exzentrischer Einsiedler, sagt, nur dieser Schnaps halte ihn in kalten, feuchten Nächten bei seiner einsamen Hütte warm."},{t="Fragwürdiger Durst",b="Calvinius nennt den Schnaps einen feurigen Schlummertrunk. Als er die Flasche erhält, lobt er beinahe die Dummheit des Boten statt dessen Güte. Wozu könnte er ein so starkes Getränk brauchen?"}},faq={{q="Woraus wird Zombie Juice hergestellt?",a="Zombie Juice wird aus Faulblüten destilliert, einer übelriechenden Pflanze, die im verderbten Boden des Dämmerwalds wächst.",al={"zombie juice zutaten","was ist in zombie juice"}},{q="Wer möchte diese Flasche geliefert bekommen?",a="Calvinius möchte die Flasche zu seiner einsamen Hütte an den westlichen Grenzen des Dämmerwalds geliefert bekommen.",al={"wer braucht zombie juice","für wen ist zombie juice","zombie juice lieferung"}},{q="Warum will Calvinius Zombie Juice?",a="Calvinius behauptet, das feurige Getränk halte seine alten Knochen in den bitterkalten, dunklen Nächten des Dämmerwalds warm. Sein seltsames Gebaren lässt vermuten, dass er für ein so starkes Gebräu noch eine andere Verwendung haben könnte.",al={"warum trinkt calvinius ihn","calvinius zombie juice grund"}},{q="Können Spieler die Flasche mit Zombiesaft trinken?",a="Nein. Ihr müsst die Flasche sicher zu Calvinius' Hütte bringen und dort abliefern.",al={"kann man zombie juice trinken","ist zombie juice konsumierbar"}}},fx={f1488eba={q="Was ist die Flasche mit Zombiesaft?",a="Die Flasche mit Zombiesaft ist ein starkes Gebräu aus Faulblütenschnaps, das im Dämmerwald gemischt wird. Beschrieben als abscheulich und unglaublich stark – angeblich stark genug, um die Toten zu erwecken –, handelt es sich um eine üble Mixtur, mit der Schankwirte äußerst vorsichtig umgehen.",al={"was ist zombiesaft","hintergrundinformationen zur flasche mit zombiesaft","was ist der saft"}},b862f5ea={q="Woher stammt die Flasche mit Zombiesaft und wer hat sie hergestellt?",a="Der Saft wird in Dunkelhain vom örtlichen Schankwart, Schankwart Smitts, gebraut, der ihn aus Faulblüten destilliert. Er wird speziell auf Bestellung für die Lieferung zu Calvinius' Hütte in der verwunschenen Wildnis des Dämmerwaldes hergestellt.",al={"wer hat zombiesaft hergestellt","woher kommt der zombiesaft","wer braut zombiesaft"}}},fp="22,162,20.292.0,19.194.1,31.104.0,32.96.0,39.175.0,45.75.0"}
P.entries["item:bottom-of-gelkak-s-key"] = {n="Unterteil von Gelkaks Schlüssel",s="An der Dunkelküste liegt das untere Fragment zwischen den Überresten eines zerbrochenen Aufziehschlüssels. Er gehörte dem schiffbrüchigen Gnomenpiraten Gelkak Gyromast, und Riffkriecher lasen das Fragment am Ufer auf.",h="An der Dunkelküste liegt das untere Fragment zwischen den Überresten eines zerbrochenen Aufziehschlüssels.",kw={"kriecher","dunkelküste","erster maat","gelkak","gyromast","schlüssel","bergung","schiffbruch"},ang={["profession:Engineering"]="Ingenieure werden darin einen Teil eines speziellen Aufziehwerkzeugs erkennen, das zum Antrieb komplexer Uhrwerkautomaten gebaut wurde.",["race:Gnome"]="Als Gnom wisst Ihr vielleicht zu schätzen, dass Gyromast auf ausgeklügelte Uhrwerktechnik statt auf eine Mannschaft aus Fleisch und Blut setzt, selbst an einer feindseligen Küste gestrandet."},sec={{t="Von Kriechern erbeutet",b="Dreschadons versenkten das Schiff von Gelkak Gyromast vor der Dunkelküste. Der Gnom und seine Habseligkeiten wurden an Land gespült, darunter auch der Aufziehschlüssel, der seinen mechanischen Ersten Maat aktivierte. Die Küstenfelsen zerbrachen den Schlüssel in drei Teile, und einheimische Aasfresser stießen auf die Trümmer. Riff- und Gezeitenkriecher schnappten sich das untere Fragment, als sie den Spülsaum durchsuchten."},{t="Wieder zusammengesetzt",b="Gelkak braucht das untere Fragment zusammen mit dem mittleren und oberen Teil, um sein mechanisches Besatzungsmitglied zu aktivieren. Küstenmurlocs schleppten das mittlere Teil fort, während Waldschreiter im Landesinneren das obere an sich nahmen. Der Gnomenpirat muss dieses schwere Fragment aus den Panzern der Küstenkrabben herausbrechen, um sein Konstrukt wiederherzustellen und Rache für seine ruinierte Expedition zu nehmen."}},faq={{q="Wozu dient das Unterteil von Gelkaks Schlüssel?",a="Das Unterteil von Gelkaks Schlüssel ist eines von drei Teilen, die benötigt werden, um den Aufziehschlüssel des gestrandeten Piraten Gelkak Gyromast zu reparieren. Der reparierte Schlüssel kann seinen mechanischen Ersten Maat wieder aktivieren.",al={"was bewirkt gelkaks schlüssel","zweck des unterteils von gelkaks schlüssel","wozu wird das unterteil von gelkaks schlüssel benötigt"}},{q="Woher stammt dieses Schlüsselteil?",a="Riffkriecher lasen das Schlüsselteil an der Küste der Dunkelküste auf. Encrusted Tide Crawlers und Raging Reef Crawlers suchen am Wasser entlang.",al={"wo findet sich das unterteil von gelkaks schlüssel","wer lässt das unterteil von gelkaks schlüssel fallen","fundort des unterteils von gelkaks schlüssel"}},{q="Warum ist der Schlüssel in drei Teile zerbrochen?",a="Dreschadons zerstörten Gelkaks Schiff, und der Schlüssel schlug gegen die Küstenfelsen, als der Gnom an Land gespült wurde. Er zerbrach in Fragmente, die unter den einheimischen Wildtieren verstreut wurden.",al={"warum zerbrach gelkaks schlüssel","wie zerbrach der schlüssel"}},{q="Wer ist Gelkak Gyromast?",a="Gelkak Gyromast ist ein gestrandeter Gnomenpirat an den Ufern der Dunkelküste. Dreschadons zerstörten sein Schiff und verstreuten seine Ausrüstung.",al={"wer ist gelkak","gelkak gyromast hintergrundgeschichte"}}},fx={bb7c59d0={q="Was ist das Unterteil von Gelkaks Schlüssel?",a="Es ist das untere Fragment eines mechanischen Schlüssels, der dem schiffbrüchigen Gnom-Piraten Gelkak Gyromast gehörte. Als sein Schiff vor der Küste der Dunkelküste sank, zerbrach der Schlüssel beim Aufprall auf den gezackten Felsen, und dieses Stück wurde von den örtlichen Küstenkriechern aus den Trümmern geborgen.",al={"was ist das unterteil von gelkaks schlüssel","unterteil von gelkaks schlüssel","was ist dieses schlüsselstück"}}},fp="22,195,19.345.0,10.337.1,44.191.0,36.141.0,40.159.0,23.122.0"}
P.entries["item:bracers-of-rock-binding"] = {n="Bracers of Rock Binding",s="Bracers of Rock Binding sind steinerne Fesseln von größeren Felselementaren im Ödland. Lotwil Veriatus braucht sie, um die Stärke seiner eigenen Fesseln zu messen.",h="Bracers of Rock Binding sind steinerne Fesseln von größeren Felselementaren im Ödland.",kw={"ödland","bracers of rock binding","größere felselementare","lotwil veriatus","felsarmschienen","servo","fesseln"},sec={{t="Steinerne Fesseln",b="Lotwil Veriatus untersucht die größeren Felselementare im Ödland, um mehr über die Fesseln zu erfahren, die ihn binden. Er glaubt, ihre Armschienen könnten ihm helfen, die Stärke seiner eigenen Fesseln einzuschätzen. Fünf Stück verschaffen ihm Ersatz für seine Forschung, denn sein Assistent Servo ist dafür bekannt, Reagenzien und Notizen zu verlegen."}},faq={{q="Was sind Bracers of Rock Binding?",a="Es sind steinerne Armschienen von größeren Felselementaren im Ödland. Lotwil Veriatus untersucht sie, um die Stärke seiner eigenen Fesseln einzuschätzen.",al={"felsarmschienen","steinerne fesseln","armschienen gegenstand"}},{q="Wer braucht diese Armschienen?",a="Lotwil Veriatus braucht fünf Bracers of Rock Binding, um die Stärke seiner Fesseln zu erforschen.",al={"wer braucht sie","lotwils armschienen","wer will felsfesseln"}},{q="Warum braucht Lotwil sie?",a="Lotwil Veriatus glaubt, dass die Armschienen der größeren Felselementare ihm helfen, die Stärke seiner eigenen Fesseln zu messen.",al={"warum armschienen","lotwils forschung","wofür"}},{q="Woher stammen die Armschienen?",a="Größere Felselementare im Ödland tragen Bracers of Rock Binding bei sich.",al={"woher armschienen bekommen","armschienen der felselementare","wo sind sie"}},{q="Warum bittet Lotwil um fünf Stück?",a="Lotwil bittet um fünf Stück, damit er Ersatz für seine Forschung hat, denn sein Assistent Servo ist berüchtigt dafür, Reagenzien und Forschung zu verlegen.",al={"wie viele armschienen","fünf benötigt","warum so viele"}}},fp="23,166,14.302.0,37.146.0,24.102.0,26.117.0,31.70.0,29.129.0"}
P.entries["item:branch-of-cenarius"] = {n="Zweig des Cenarius",s="Im östlichen Eschental hält Geltharis den Zweig des Cenarius, der den Dryaden heilig ist. Anilia starb bei seiner Verteidigung, mit einem letzten Wunsch: das Relikt zurückzuerlangen.",h="Im östlichen Eschental hält Geltharis den Zweig des Cenarius, der den Dryaden heilig ist.",kw={"anilia","eschental","zweig des cenarius","dryade","forest song","geltharis","illiyana","satyr"},ang={["class:Druid"]="Als Druide teilt Ihr die Pflicht, den Zweig des Cenarius von dem Satyr zurückzuholen, der ihn entweiht hat.",["race:NightElf"]="Als Nachtelf aus dem Eschental habt Ihr die heilige Pflicht, den Dryaden beizustehen und ihre angestammten Schätze zurückzuholen."},sec={{t="Ein heiliger Zweig im Schatten",b="Der Zweig des Cenarius ist den Dryaden heilig, die dem Waldherrn folgen. Anilia und ihre Schwester Illiyana hielten ihn in Ehren. Dann überfielen verderbte Satyrn sie nahe den verseuchten Ruinen im östlichen Eschental. Ihr Anführer Geltharis riss den Zweig an sich und verwundete Anilia tödlich.\n\nIm Sterben deutete Anilia nach Norden zu dem Bogen, wo Geltharis lauert. Sie flehte um einen Champion, der den Zweig zurückholen und den Dryaden in Forest Song zurückbringen würde."}},faq={{q="Was ist der Zweig des Cenarius?",a="Der Zweig des Cenarius ist ein heiliges Relikt, das die Dryaden des Eschentals in Ehren halten. Er trägt den Namen und den Segen des Waldherrn und verkörpert ihre Verbundenheit mit dem uralten Wald.",al={"zweig des cenarius hintergrund","was ist dieser zweig","dryadenzweig"}},{q="Wer hat den Zweig des Cenarius gestohlen?",a="Geltharis stahl den Zweig des Cenarius, nachdem er einen Überfall auf die Dryaden nahe dem östlichen Eschental angeführt hatte. Er verwundete Anilia tödlich und floh dann mit dem Zweig nach Norden, jenseits eines steinernen Bogens.",al={"wer nahm den zweig","wer hat ihn gestohlen","wer lässt den zweig des cenarius fallen"}},{q="Wem gehört der Zweig?",a="Der Zweig gehört den Dryaden von Forest Song. Anilia starb bei seiner Verteidigung, und ihre Schwester Illiyana nimmt ihn gemäß Anilias letztem Wunsch entgegen.",al={"wer bekommt den zweig","wer will den zweig","wem gebe ich ihn"}},{q="Wo wird der Zweig zurückgeholt?",a="Geltharis trägt den Zweig bei sich, gleich nördlich der Ruinen im östlichen Eschental, wo Anilia fällt, nahe der Grenze zu Azshara.",al={"fundort des zweigs","wo ist geltharis","wo den zweig finden"}}},fx={["4e4ec82f"]={q="Warum ist es so wichtig, den Zweig des Cenarius zurückzuholen?",a="Die Dryaden des Eschentals betrachten den Zweig als ein unschätzbares heiliges Relikt, das mit ihrem Vater, Cenarius, verbunden ist. Als die Dryade Anilia von korrumpierten Satyrn in der Nähe von Xavian tödlich verwundet wurde, war ihr letzter Wunsch sicherzustellen, dass der gestohlene Zweig Geltharis wieder entrissen und sicher in die Hände der Dryaden in Forest Song zurückgebracht wurde.",al={"warum den zweig des cenarius zurückholen","warum wollen dryaden den zweig","zweck des zweigs des cenarius"}}},fp="18,154,31.441.0,31.174.0,33.181.0,30.149.1,30.123.0"}
P.entries["item:brass-collar"] = {n="Messinghalsband",s="Auf Brackbrunns Kürbisbeet trägt Princess das Halsband, das Mutter Steinfeld als Beweis für den Tod der Sau will.",h="Auf Brackbrunns Kürbisbeet trägt Princess das Halsband, das Mutter Steinfeld als Beweis für den Tod der Sau...",kw={"brackbrunns kürbisbeet","messinghalsband","wald von elwynn","mutter steinfeld","princess","princess muss sterben","hof der steinfelds"},ang={["faction:Alliance"]="Wenn Ihr als Abenteurer der Allianz Elwynns Landbevölkerung helft, tragt Ihr mit Princess’ Halsband dazu bei, eine Fehde zwischen benachbarten Höfen beizulegen."},sec={{t="Eine Trophäe bäuerlicher Rivalität",b="Princess ist die riesige, preisgekrönte Sau der Familie Brackwell. Sie streift östlich des Maclure-Anwesens umher, und ihr Hunger führt sie oft in die Felder auf dem Hof der Steinfelds. Nachdem Princess ihr wertvolles Gemüse gefressen hat, sucht Mutter Steinfeld jemanden, der bereit ist, sie zu töten. Das Halsband beweist, dass die Sau erlegt wurde und die Felder der Steinfelds nicht mehr plündern kann."}},faq={{q="Woher stammt das Messinghalsband?",a="Princess trägt das Halsband auf Brackbrunns Kürbisbeet im östlichen Wald von Elwynn, hinter dem Maclure-Hof.",al={"messinghalsband herkunft","wer lässt messinghalsband fallen","wo messinghalsband bekommen"}},{q="Warum will Mutter Steinfeld das Halsband?",a="Princess frisst Mutter Steinfelds preisgekröntes Gemüse. Das Halsband beweist, dass sie erlegt wurde, bevor sie noch mehr von Mutter Steinfelds Ernte vernichten kann.",al={"warum steinfeld das halsband will","mutter steinfeld halsband zweck"}},{q="Wem gehört Princess?",a="Princess gehört der Familie Brackwell und streift mit ihren kleineren Ebergefährten auf deren Kürbisbeet umher.",al={"princess besitzer","wem gehört das schwein"}},{q="Kann auch jemand anderes als Princess diesen Gegenstand fallen lassen?",a="Nur Princess kann das Halsband hinterlassen. Es wurde für die riesige, hochgeschätzte Sau der Familie Brackwell gefertigt.",al={"andere halsbandquellen","wo sonst messinghalsband finden"}}},fx={["92e34b72"]={q="Was ist das Messinghalsband?",a="Das Messinghalsband ist das charakteristische Halsband von Prinzessin, einer preisgekrönten Sau, die der Familie Brackwell gehört. Aufgrund von Prinzessins enormer Größe und ihrer Angewohnheit, die Ernte der Nachbarn zu plündern, dient das Halsband als unbestreitbarer Beweis dafür, dass die zerstörerische Bestie endlich erlegt wurde.",al={"was ist das messinghalsband","hintergrundinformationen zum messinghalsband","wer trägt das messinghalsband"}}},fp="12,103,28.356.0,38.105.0,39.144.0,18.104.0,46.97.0"}
P.entries["item:bristleback-attack-plans"] = {n="Angriffspläne der Borstennacken",s="Bei Camp Narache bereiten sich die Borstennacken darauf vor, die Taurensiedlung zu belagern. Stacheleber in der Dornrankenklamm zeichneten grobe Karten und verfassten Notizen für einen Angriff, der die Siedlung überrennen soll.",h="Bei Camp Narache bereiten sich die Borstennacken darauf vor, die Taurensiedlung zu belagern.",kw={"angriffspläne","dornrankenklamm","borstennacken","camp narache","häuptling falkenwind","mulgore","stacheleber"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr durch die Vereitelung der Borstennackenoffensive, einen sicheren Stützpunkt in den heiligen Ebenen von Mulgore zu bewahren.",["race:Tauren"]="Als Tauren helft Ihr durch die Aufdeckung des Komplotts, die Übungsplätze zu verteidigen, an denen junge Tauren ihre ersten Riten durchlaufen. Damit schützt Ihr auch Älteste und Novizen vor einer Belagerung durch die Stacheleber."},sec={{t="Ein Komplott gegen die Hochebene",b="Die Borstennacken-Stacheleber bereiten einen anhaltenden Angriff auf Camp Narache vor. Ihre Anführer wollen über Grenzscharmützel auf der Hochwolkenebene hinausgehen und die jungen Tauren auslöschen, die dort ausgebildet werden. Die Pläne liegen tief in einer Erdhöhle in der Dornrankenklamm. Häuptling Falkenwind kann Verstärkung aus dem Dorf der Bluthufe anfordern und Camp Narache damit eine Chance geben, die Invasion einzudämmen, bevor sie beginnt."}},faq={{q="Was enthalten die Angriffspläne der Borstennacken?",a="Die Pläne enthalten eine taktische Karte und grobe Anweisungen für eine Belagerung von Camp Narache. Sie zeigen, dass die Stacheleber einen anhaltenden Angriff statt vereinzelter Überfälle organisieren.",al={"was sind die angriffspläne","was steht auf der karte","schlachtpläne der borstennacken"}},{q="Wo sind diese Pläne zu finden?",a="Die Pläne liegen auf dem Erdboden einer höher gelegenen Höhle in der Dornrankenklamm. Die Höhle liegt nur ein kurzes Stück einen Seitenpfad hinauf, der von der Hütte des Borstennackenhäuptlings abzweigt.",al={"wo sind die pläne","wo ist die karte zu finden","fundort der angriffspläne der borstennacken"}},{q="Was tut Häuptling Falkenwind, sobald er die Pläne erhält?",a="Häuptling Falkenwind nutzt die Pläne, um Hilfe und Krieger aus dem Dorf der Bluthufe anzufordern. Sie werden die Verteidigung von Camp Narache verstärken.",al={"was tut falkenwind","reaktion von camp narache","reaktion von häuptling falkenwind"}},{q="Warum greifen die Borstennacken Camp Narache an?",a="Die Borstennacken beanspruchen die dornigen Schluchten als ihr Gebiet und sehen die Tauren auf der Hochebene als Eindringlinge an. Sie wollen die Siedlung vertreiben.",al={"warum greifen die stacheleber an","motiv der borstennacken"}}},fx={["166f21b1"]={q="Woher stammen die Angriffspläne der Borstennacken?",a="Die Pläne stammen aus den Tiefen der Dornrankenklamm und wurden vom Kriegshäuptling der Borstennacken-Stacheleber entworfen. Auf einer groben Karte platziert, die in ihrem Höhlensystem versteckt war, beschreiben sie den koordinierten Plan des Stammes, eine ausgedehnte Belagerung gegen die Taurensiedlung Camp Narache zu führen.",al={"wer hat die angriffspläne der borstennacken erstellt","ursprung der angriffspläne der borstennacken","wer hat die angriffspläne der borstennacken geschrieben"}},aea2975f={q="Warum benötigt Häuptling Falkenwind die Angriffspläne der Borstennacken?",a="Häuptling Falkenwind benötigt diese Pläne, weil sie das Vorhaben der Stacheleber enthüllen, Camp Narache zu belagern. Mit dem Beweis für die drohende Gefahr in der Hand kann der Häuptling sofort Verstärkung aus dem nahe gelegenen Dorf der Bluthufe anfordern, um Verteidigungsmaßnahmen vorzubereiten und den Angriff abzuwehren, bevor die Siedlung überrannt wird.",al={"warum will man die angriffspläne der borstennacken","warum will falkenwind die angriffspläne","zweck der angriffspläne der borstennacken"}}},fp="24,173,23.385.0,45.170.0,28.145.0,55.125.1,47.142.0"}
P.entries["item:bristleback-belt"] = {n="Gürtel der Borstennacken",s="In Camp Narache sammeln junge Tauren Gürtel der Borstennacken, um ihren Mut zu beweisen. Die Gürtel stammen von Quilboar in der Dornrankenklamm und markieren einen Schritt im Rite of Strength.",h="In Camp Narache sammeln junge Tauren Gürtel der Borstennacken, um ihren Mut zu beweisen.",kw={"gürtel","dornrankenklamm","bristleback","camp narache","häuptling falkenwind","quilboar","die hochwolkenebene","rite of strength"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr durch das Zurückdrängen der aggressiven Quilboar Mulg ores, die südlichen Grenzen des Kernlands der Horde im Zentrum Kalimdors zu sichern.",["race:Tauren"]="Als junger Tauren auf der Hochwolkenebene macht Ihr mit dem Gürtel eines gefallenen Bristleback Euren ersten Schritt zur Anerkennung durch die Ältesten in Donnerfels."},sec={{t="Beweis für den Ritus",b="Der Stamm der Red Cloud prüft Jugendliche, die in Donnerfels Anerkennung suchen, durch die uralten Rites of the Earthmother. Ihre erste Prüfung ist der Rite of Strength. Jeder Initiand muss den Stamm vor Bedrohungen schützen. Bristleback-Quilboar plündern Nahrungsvorräte und lauern Jagdtrupps außerhalb von Camp Narache auf, deshalb verlangt Häuptling Falkenwind ihre Gürtel. Bringt ihm zwölf, um zu beweisen, dass Ihr Gefahren trotzen und den Stamm mitverteidigen könnt."},{t="Handwerk der Quilboar",b="Bristleback-Krieger und -Schamanen in der Dornrankenklamm tragen Gürtel aus rauem Leder, Schnur und Schrott. Ein Taurenkrieger hat als Kleidungsstück wenig Verwendung dafür, doch die Machart der Quilboar kennzeichnet sie als Beweis für einen getöteten Feind. Bringt die Gürtel zum Lagerkreis zurück, um den für den Ritus erforderlichen Nachweis zu erbringen."}},faq={{q="Wozu dienen Gürtel der Borstennacken?",a="Häuptling Falkenwind in Camp Narache verlangt zwölf Gürtel der Borstennacken als Beweis, dass ein Initiand den Rite of Strength bestanden hat, die erste Prüfung der traditionellen Rites of the Earthmother.",al={"warum brauche ich gürtel der borstennacken","gürtel der borstennacken zweck","wozu dient dieser gürtel"}},{q="Woher stammen Gürtel der Borstennacken?",a="Bristleback-Quilboar und -Schamanen in der Dornrankenklamm tragen die Gürtel. Die Klamm liegt unmittelbar östlich von Camp Narache auf der Hochwolkenebene.",al={"woher bekommt man gürtel der borstennacken","wer lässt gürtel der borstennacken fallen","gürtel der borstennacken fundort"}},{q="Warum will Häuptling Falkenwind Gürtel statt Köpfen oder Waffen?",a="Die Gürtel liefern einen tragbaren Beweis dafür, dass ein Initiand Feinde des Stammes getötet hat. Der Ritus verlangt Gürtel, erklärt aber nicht, warum sie anderen Trophäen vorgezogen wurden.",al={"warum gürtel","falkenwind beweis"}},{q="Warum werden die Bristlebacks angegriffen?",a="Die Bristlebacks sind von der Dornrankenklamm aus in Stammesland eingedrungen. Sie überfallen Camp Narache bei Nacht und lauern überall auf der Hochebene Jagdtrupps der Tauren auf.",al={"warum bristlebacks töten","quilboar bedrohung mulgore"}}},fx={["69faf7fa"]={q="Was ist ein Gürtel der Borstennacken?",a="Ein Gürtel der Borstennacken ist ein einfaches Kleidungsstück, das von den Stachelebern getragen wird, die in der Dornrankenklamm leben. Diese groben Leder- oder Kordelgürtel, die gefallenen Plünderern abgenommen wurden, dienen als unbestreitbare Trophäen des Kampfes und beweisen den Stammesältesten, dass eine eindringende Bedrohung konfrontiert und getötet wurde.",al={"gürtel der borstennacken","was ist ein gürtel der borstennacken","gegenstand gürtel der borstennacken"}},d50579da={q="Woher stammt ein Gürtel der Borstennacken und wer stellt ihn her?",a="Diese Gürtel werden von den Borstennacken-Stachelebern gefertigt, die eine dornenbewachsene Siedlung in der Dornrankenklamm errichtet haben, direkt östlich von Camp Narache. Sowohl ihre Frontkrieger als auch ihre Schamanen tragen sie in Scharmützeln gegen die Tauren auf der Hochwolkenebene.",al={"woher kommen gürtel der borstennacken","wer stellt gürtel der borstennacken her","ursprung des gürtels der borstennacken"}}},fp="16,169,17.407.0,14.287.0,36.181.0,37.136.0,63.169.0,40.152.0"}
P.entries["item:bristleback-quilboar-tusk"] = {n="Stacheleberhauer der Borstennacken",s="Im nördlichen und zentralen Brachland werden Stacheleberhauer der Borstennacken von erschlagenen Stachelebern erbeutet. Mankrik sammelt sie als Beweis für das Blutbad und als Zeichen der Rache.",h="Im nördlichen und zentralen Brachland werden Stacheleberhauer der Borstennacken von erschlagenen Stachelebern...",kw={"brachland","borstennacken","consumed by hatred","das wegekreuz","mankrik","stacheleber","hauer"},ang={["faction:Horde"]="Die Stacheleber bedrohen das Wegekreuz und die Versorgungswege im gesamten Brachland. Das Sammeln der Hauer dient Mankriks Rachefeldzug und dem Bestreben der Horde, die Region zu befrieden.",["race:Orc"]="Als Orc kennt Ihr die Last von Blutschulden und die Trauer eines Kriegers. Mankriks Streben nach sechzig Stachelebertrophäen berührt ein gemeinsames Ehrgefühl."},sec={{t="Trophäen der Rache",b="Borstennackenstacheleber verteidigen ihr Territorium im gesamten Brachland gegen die Ausbreitung der Horde. Ihre gezackten Elfenbeinhauer sind Waffen im Nahkampf. Mankrik, ein erfahrener Orc-Krieger, der am Wegekreuz stationiert ist, verlor seine Frau bei einem brutalen Hinterhalt der Stacheleber. Zur Vergeltung sammelt er Dutzende Hauer und zählt damit das Leid, das er den Borstennacken heimzahlen will."}},faq={{q="Wer will diese Hauer?",a="Mankrik, ein Orc-Krieger am Wegekreuz im Brachland, will die Hauer. Er sucht Rache an den Borstennackenstachelebern, nachdem ein Hinterhalt ihn von seiner Frau getrennt hat.",al={"wer braucht hauer der borstennacken","wer nimmt stacheleberhauer der borstennacken an","hauer abgeben"}},{q="Warum will Mankrik so viele Hauer?",a="Stacheleberräuber überwältigten Mankrik und ließen ihn für tot zurück. Trauer und Zorn ergriffen ihn, und sechzig Hauer liefern ihm den Beweis, dass der Stamm der Borstennacken zur Vergeltung dezimiert wird.",al={"warum sechzig hauer","warum will mankrik hauer","mankriks rache"}},{q="Welche Stacheleber tragen diese Hauer?",a="Mitglieder des Stammes der Borstennacken tragen diese Hauer im nördlichen und zentralen Brachland, zwischen Gestrüpp und in Dornenlagern.",al={"wo werden hauer der borstennacken erbeutet","wer hinterlässt stacheleberhauer der borstennacken"}},{q="Dienen diese Hauer einem anderen Zweck als Mankriks Rachefeldzug?",a="Mankrik sammelt diese Trophäen allein aus Rache. Stacheleberhauer werden manchmal zu Stammesschmuck oder Handelswaren, doch er verwendet diese für keines von beidem.",al={"verwendung von hauern der borstennacken","herstellung mit stacheleberhauern möglich"}}},fx={a893c973={q="Was ist ein Stacheleberhauer der Borstennacken?",a="Dies sind die abgetrennten Hauer, die von getöteten Borstennacken-Stachelebern stammen, die im Brachland umherstreifen. Für die Stacheleber sind sie natürliche Merkmale und Zeichen der Wildheit, aber für Jäger in den Ebenen dienen sie als grausamer physischer Beweis für eine weitere tote Bestie.",al={"stacheleberhauer der borstennacken","was ist ein stacheleberhauer der borstennacken"}},fe8719fb={q="Woher stammt ein Stacheleberhauer der Borstennacken?",a="Sie werden direkt aus den Kiefern von Borstennacken-Stachelebern im gesamten Brachland geerntet. Stacheleber lassen diese scharfen Hauer auf natürliche Weise wachsen, und um sie zu bekommen, muss man sie nach dem Kampf von gefallenen Feinden abschneiden.",al={"woher kommen stacheleberhauer der borstennacken","wer lässt stacheleberhauer der borstennacken fallen","quelle für stacheleberhauer der borstennacken"}}},fp="25,165,21.348.0,22.171.0,36.170.0,33.123.0,63.154.0"}
P.entries["item:brock-s-list"] = {n="Brocks Liste",s="In Thelsamar verschickt Brock Steinsucher eine Liste von Bergbauschülern, die mit Hacken aus Eisenschmiedes Gildenhallen geehrt werden.",h="In Thelsamar verschickt Brock Steinsucher eine Liste von Bergbauschülern, die mit Hacken aus Eisenschmiedes...",kw={"brocks liste","golnir geröllzeh","die große schmiede","eisenschmiede","loch modan","bergbau","thelsamar","thorgrum borrelson"},ang={["profession:Mining"]="Als Schürfer erkennt Ihr, dass Brocks Liste Lehrlinge ehrt, die sich einen Platz in den Traditionen der Bergbaugilde Tiefenschacht verdient haben.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Liste junge Bergleute ehrt, die sich unter Khaz Modan der Arbeit mit Hacke und Schaufel verschrieben haben."},sec={{t="Die Auszeichnung eines Bergmanns",b="In Khaz Modan müssen Lehrlinge ihr Können beweisen, bevor sie anspruchsvolle Arbeiten in den Minen übernehmen. Brock verzeichnet jene, die sich im Unterricht hervortun. Er vertraut die Liste Reisenden an, die nach Eisenschmiede aufbrechen, wo die Namen der Geehrten in die Hacken graviert werden können."},{t="Der Weg zur Großen Schmiede",b="Ein Greif bringt Brocks Liste vom Horst in Thelsamar zu Golnir Geröllzeh bei der Bergbaugilde Tiefenschacht in Eisenschmiedes Großer Schmiede. Dort werden die Namen der Schüler in ihre Ehrenhacken graviert."}},faq={{q="Was ist Brocks Liste?",a="Brock Steinsucher, der Bergbaulehrer von Thelsamar, verfasst eine Liste von Lehrlingen, die sich im Bergbauunterricht hervortun und Ehrenhacken verdienen.",al={"brocks liste","was ist dieser gegenstand","brocks liste zweck"}},{q="Wem soll ich Brocks Liste überbringen?",a="Zeigt Brocks Liste Thorgrum Borrelson, dem Greifenmeister in Thelsamar, um einen Flug zu vereinbaren. Bringt sie dann zu Golnir Geröllzeh bei der Bergbaugilde Tiefenschacht in Eisenschmiedes Großer Schmiede.",al={"wohin mit der liste","wer bekommt brocks liste","brocks liste abgeben"}},{q="Warum braucht Golnir Geröllzeh dieses Dokument?",a="Golnir Geröllzeh verwaltet die Werkzeuge der Bergbaugilde Tiefenschacht in Eisenschmiede. Er hält Ehrenhacken bereit und braucht Brocks Liste, um den Namen jedes Schülers in eine davon zu gravieren.",al={"warum golnir","warum braucht eisenschmiede die liste"}},{q="Warum wird die Liste mit einem Greifen statt zu Fuß verschickt?",a="Die Gebirgspässe durch Loch Modan führen nach Dun Morogh. Ein Greif aus Thorgrum Borrelsons Horst bringt die Liste schnell und sicher zur Großen Schmiede.",al={"warum nach eisenschmiede fliegen","warum einen greifen nehmen"}}},fx={bca439a3={q="Woher stammt Brocks Liste und wer hat sie erstellt?",a="Die Liste wurde von Brock Steinsucher verfasst, einem erfahrenen Bergarbeiter aus der Stadt Thelsamar in Loch Modan. Wenn junge Zwerge durch seine Türen kommen, um das Handwerk zu erlernen, bewertet Brock ihren Fortschritt und erstellt diese Liste, um die außergewöhnlichen Schüler zu erfassen, die sich durch ihre harte Arbeit besondere Anerkennung verdient haben.",al={"wer hat brocks liste erstellt","woher kommt brocks liste","schöpfer von brocks liste"}}},fp="12,110,21.250.0,27.201.0,21.139.0,33.190.0,46.171.0,49.159.0"}
P.entries["item:broken-and-battered-samophlange"] = {n="Zerbrochenes und ramponiertes Samophlang",s="Im nördlichen Brachland liegt das zerbrochene und ramponierte Samophlang nach einer missglückten Inspektion beschädigt da. Es muss zu Goblinexperten in Orgrimmar gelangen, wo vielleicht jemand seine Funktionsweise versteht.",h="Im nördlichen Brachland liegt das zerbrochene und ramponierte Samophlang nach einer missglückten Inspektion...",kw={"brachland","maschinenwerkstatt","nogg","orgrimmar","rilli greasygob","samophlange","venture company","wenikee boltbucket"},ang={["faction:Horde"]="Als Mitglied der Horde bringt Ihr geborgene Maschinen der Venture Company aus dem Brachland in Orgrimmars Goblinwerkstätten, wo sie vielleicht wertvolle technische Geheimnisse preisgeben.",["profession:Engineering"]="Als Ingenieur erkennt Ihr die Gefahr, ohne Bauplan Anzeigen und Hebel an einem instabilen Mechanismus der Venture Company anzubringen."},sec={{t="Bis zur Unkenntlichkeit verbastelt",b="Die Venture Company fertigte Samophlange für ihre Arbeit im nördlichen Brachland. Wenikee Boltbucket versuchte, eines zu inspizieren und umzubauen, und fügte Messgeräte, Hebel und Anzeigen hinzu, um seine Stabilität zu messen. Ihre Änderungen schwächten den Mechanismus und hinterließen ihn ramponiert und dem Verfall nahe. Aus Sorge, weitere Ergänzungen könnten es vollständig lahmlegen, schickte sie das empfindliche Gerät zu jemandem mit Fabrikerfahrung."},{t="Der Weg nach Orgrimmar",b="Das Gerät muss von jemandem repariert werden, der die Produktionslinien der Venture Company kennt. Rilli Greasygob, ein ehemaliger Mitarbeiter der Venture Company, arbeitet in Noggs Maschinenwerkstatt im Tal der Ehre in Orgrimmar. Der ramponierte Apparat fällt dem Ingenieur ins Auge. Wer aus Goblinbetrieben etwas birgt, mag kühn erscheinen oder schlicht tollkühn."}},faq={{q="Was ist ein Samophlang?",a="Ein Samophlang ist eine Maschine, die von der Venture Company für industrielle Arbeiten im Brachland gefertigt wurde. Nur wenige Außenstehende verstehen die Geheimnisse seiner Goblintechnik.",al={"was ist dieser gegenstand","was macht ein samophlang","zweck des samophlangs"}},{q="Warum ist das Samophlang zerbrochen und ramponiert?",a="Wenikee Boltbucket versuchte, das Samophlang umzubauen, indem sie Messgeräte hinzufügte, um seine Stabilität zu messen. Die Ergänzungen schwächten es und beschädigten seine empfindlichen Innenteile.",al={"wer hat das samophlang beschädigt","warum ist es beschädigt","wenikee hat es beschädigt"}},{q="Wer kann diesen beschädigten Apparat reparieren?",a="Rilli Greasygob kann das beschädigte Gerät untersuchen. Der ehemalige Mitarbeiter der Venture Company arbeitet in Noggs Maschinenwerkstatt im Tal der Ehre in Orgrimmar.",al={"zu wem muss das gebracht werden","wohin muss das samophlang","wer repariert es"}},{q="Woher stammt diese Maschine ursprünglich?",a="Die Maschine stammt aus den Bohr- und Förderbetrieben der Venture Company im nördlichen Brachland. Gobliningenieure nutzen sie, um schwere Fördermaschinen anzutreiben.",al={"herkunft des samophlangs","wo wurde es gefunden","herkunft venture company"}}},fx={["35e2c2bf"]={q="Warum möchte Rilli Greasygob das zerbrochene und ramponierte Samophlang?",a="Wenikee Boltbucket versuchte, an dem empfindlichen Apparat herumzubasteln, indem er zusätzliche Anzeigen hinzufügte, was jedoch dessen strukturelle Integrität auf ein absolutes Minimum reduzierte. Da er zugab, dass weiteres Basteln ihn vollständig ruinieren könnte, schickt dich Wenikee, um das beschädigte Gerät zu Rilli Greasygob bei Noggs Maschinenladen in Orgrimmar zu bringen. Als ehemaliger Angestellter der Venture Company verfügt Rilli über das technische Fachwissen, um deren spezialisierte Maschinen zu reparieren.",al={"warum das samophlang zu rilli bringen","wer will das zerbrochene samophlang","warum will rilli das samophlang"}}},fp="31,182,27.375.0,21.316.0,22.151.0,43.158.0,35.144.0,46.162.0"}
P.entries["item:broken-armor-of-ana-thek"] = {n="Broken Armor of Ana'thek",s="Broken Armor of Ana'thek ist eine zerschmetterte Trophäe, die mit den Schädelspaltern des Schlingendorntals verbunden ist. Gan'zulah verlangt sie als Beweis für Ana'theks Niederlage.",h="Broken Armor of Ana'thek ist eine zerschmetterte Trophäe, die mit den Schädelspaltern des Schlingendorntals...",kw={"ana'thek","ana'thek the cruel","zerbrochene rüstung","bubbling cauldron","gan'zulah","basislager grom'gol","schädelspalter","schlingendorntal"},sec={{t="Die Forderung eines Häuptlings",b="Im Basislager Grom'gol befiehlt Euch Gan'zulahs Kopf, Euch den Schädelspaltern in den östlichen Bergen zu stellen. Er verlangt die zerbrochene Rüstung ihres Häuptlings Ana'thek the Cruel, falls Ihr den Kampf überlebt."}},faq={{q="Wer war Ana'thek?",a="Ana'thek the Cruel war der Häuptling der Schädelspalter im Schlingendorntal.",al={"wer ist ana'thek","hintergrundgeschichte von ana'thek"}},{q="Warum will Gan'zulah die Rüstung?",a="Gan'zulah verlangt Ana'theks zerschmetterte Rüstung als Beweis dafür, dass Ihr den Häuptling der Schädelspalter besiegt habt.",al={"warum die rüstung","gan'zulahs rüstung","was will gan'zulah"}},{q="Woher stammt die Rüstung?",a="Broken Armor of Ana'thek stammt von Ana'thek the Cruel im Schlingendorntal.",al={"herkunft der rüstung","woher stammt die rüstung","ana'theks rüstung"}},{q="Wohin soll ich die Rüstung bringen?",a="Bringt Broken Armor of Ana'thek zum Bubbling Cauldron im Basislager Grom'gol.",al={"rüstung abgeben","wohin die rüstung bringen","bubbling cauldron"}}},fp="24,152,20.195.0,17.77.0,34.96.0,30.81.0,27.82.0"}
P.entries["item:broken-samophlange"] = {n="Zerbrochenes Samophlang",s="Im nördlichen Brachland hat ein zerbrochenes Samophlang neugierige Ingenieure angelockt. Seine beweglichen Teile und feinen Zahnräder deuten noch immer auf einen Zweck hin, den niemand ergründet hat.",h="Im nördlichen Brachland hat ein zerbrochenes Samophlang neugierige Ingenieure angelockt.",kw={"brachland","zerbrochenes samophlang","zahnräder","der mor'shan-schutzwall","samophlange","undermine","wenikee boltbucket"},ang={["faction:Horde"]="Das Gerät taucht im Gebiet der Horde im Brachland auf und bringt örtliche Außenposten, Tüftler und neutrale Handelskontakte zusammen.",["profession:Engineering"]="Für einen Ingenieur ist das Samophlang ein unwiderstehliches Rätsel. Seine empfindlichen inneren Zahnräder offenbaren ihren Zweck womöglich erst, wenn die Maschine zerlegt und zum Laufen gebracht wird."},sec={{t="Ein rätselhafter Mechanismus",b="Aus dem nördlichen Brachland stammt ein zerbrochenes Samophlang, dessen feine Zahnräder und bewegliche Baugruppen noch immer sorgfältige Handwerkskunst erkennen lassen. Stotterspritter, ein Goblin in Ratschet, beschädigte das empfindliche Gerät versehentlich, bevor jemand seine Funktionsweise festhalten konnte. In der Hoffnung, neugierigen Kollegen in Undermine funktionierende Ergebnisse zu schicken, suchte sein Finder jemanden, der es reparieren konnte. Man wandte sich an Wenikee Boltbucket, eine kluge Tüftlerin nahe dem Mor'shan-Schutzwall."},{t="Geschickte Tüftlerhände gesucht",b="Wenikee Boltbucket kann selbst nach dem Studium seiner zerstörten Teile nicht sagen, wozu ein Samophlang dienen soll. Seine Uhrwerksgeräusche und wechselnden Bewegungen wecken ihr Interesse. Statt es als Schrott beiseitezulegen, macht sie sich daran, es zu reparieren und seine Mechanismen bei voller Leistung arbeiten zu sehen."}},faq={{q="Was ist ein Samophlang?",a="Selbst die Tüftler, die ein Samophlang zu reparieren versuchen, können nicht sagen, was es tut. Sein Name liefert keine Antwort, doch seine feinen Zahnräder und beweglichen Teile deuten auf einen unbekannten industriellen Zweck hin.",al={"zweck des samophlangs","was macht ein samophlang","definition von samophlang"}},{q="Warum ist das Samophlang zerbrochen?",a="Stotterspritter, ein Goblin in Ratschet, beschädigte die empfindliche Mechanik, als er an dem Gerät herumbastelte, das man ihm gebracht hatte. Das Samophlang blockierte, bevor seine Geheimnisse mit Kollegen in Undermine geteilt werden konnten, also suchte man einen Experten, der es wieder zum Laufen bringen konnte.",al={"wie ging es kaputt","geschichte des zerbrochenen samophlangs"}},{q="Wer ist Wenikee Boltbucket?",a="Wenikee Boltbucket ist eine wissbegierige Tüftlerin im nördlichen Brachland, unmittelbar südlich des Mor'shan-Schutzwalls an der Grenze zum Eschental. Ihre Neugier auf Ingenieurskunst treibt sie dazu, seltsame Apparaturen zu untersuchen und wieder aufzubauen.",al={"wo ist wenikee","boltbuckets standort"}},{q="Warum interessieren sich Goblins in Undermine dafür?",a="Gobliningenieure und Unternehmer brennen darauf, ungewöhnliche mechanische Geräte zu untersuchen. Die Kunde vom Samophlang erreichte Kontakte in Undermine, die neugierig waren, welche Vorteile es bieten könnte.",al={"interesse in undermine","warum interessiert es goblins"}}},fp="18,154,20.445.0,24.274.0,22.179.0,30.251.0,26.213.0,46.194.0"}
P.entries["item:broken-tears"] = {n="Broken Tears",s="Broken Tears sind Kristallfragmente aus der Höhle von Bolgans Loch im südlichen Desolace. Warug von den Magram verlangt sie als Beweis dafür, dass der Stamm zerstören kann, was die Gelkis verehren.",h="Broken Tears sind Kristallfragmente aus der Höhle von Bolgans Loch im südlichen Desolace.",kw={"bolgans loch","broken tears","zentaur","desolace","gelkis","magram","tears of theradras","warug"},sec={{t="Bei Bolgans Loch",b="In Bolgans Loch bewahren die Gelkis Kristalle auf, die als tears of Theradras bekannt sind. Warug von den Magram möchte, dass Ihr sie zerbrecht und drei Fragmente nach Magram bringt. Er behauptet, Theradras werde die Gelkis nicht beschützen, und sagt, die Magram bräuchten keinen Schutz. Ihre Fehde verleiht den zerbrochenen Kristallen ihre Bedeutung."}},faq={{q="Was sind Broken Tears?",a="Broken Tears sind Stücke der Kristalle, die als tears of Theradras bekannt sind und in einer Höhle bei Bolgans Loch aufbewahrt werden.",al={"broken tears gegenstand","was sind die tears"}},{q="Wer will die Broken Tears?",a="Warug, ein Magram-Zentaur in Magram, bittet Euch, ihm drei Broken Tears zu bringen.",al={"wer braucht sie","warug tears"}},{q="Warum will Warug sie?",a="Warug will die Kristalle zerstören lassen, um den Gelkis zu zeigen, dass Theradras sie nicht beschützen wird.",al={"warum kristalle zerbrechen","grund der magram"}},{q="Woher stammen die Broken Tears?",a="Die tears of Theradras werden in einer Höhle bei Bolgans Loch im südlichen Desolace aufbewahrt.",al={"fundort der broken tears","kristalle von bolgans loch"}},{q="Was glauben die Gelkis über Theradras?",a="Die Gelkis glauben, dass Theradras die Zentauren beschützt; Warug hält diesen Glauben für töricht.",al={"gelkis theradras","wer beschützt die gelkis"}}},fp="12,180,16.303.0,22.105.0,27.84.0,25.91.0,36.80.0,43.88.0"}
P.entries["item:broken-tools"] = {n="Zerbrochene Werkzeuge",s="Bei der Grabung nordwestlich des Dorfes der Bluthufe liegen zerbrochene Zwergenspitzhacken an der Schmiede. Baine Bluthuf sucht einen Beweis dafür, dass die Ausgrabung, die Mulgores Land und Tierwelt bedroht, zum Stillstand gekommen ist.",h="Bei der Grabung nordwestlich des Dorfes der Bluthufe liegen zerbrochene Zwergenspitzhacken an der Schmiede.",kw={"baine bluthuf","zerbrochene werkzeuge","ausgrabungsstätte","dwarven digging","schmiede","mulgore","prospector's pick"},ang={["profession:Blacksmithing"]="Als Schmied könnt Ihr Eure Schmiede und Euren Amboss gegen zwergische Eisenwaren einsetzen, um das Land zu verteidigen.",["race:Tauren"]="Als Tauren helft Ihr dabei, die Erdenmutter vor Grabungen zu schützen, die die einheimischen Tiere quälen, indem Ihr Baine zerstörte Werkzeuge bringt."},sec={{t="Sabotage an der Grabung",b="Nordwestlich des Dorfes der Bluthufe suchen zwergische Ausgräber in Mulgores Hügeln nach Spuren uralter Geschichte. Die Tauren betrachten die Grabungen als Schändung der Erdenmutter. Ihr Lärm und ihre Zerstörung beunruhigen die einheimische Tierwelt, besonders die umherstreifenden Kodoherden. Deshalb befiehlt der junge Baine Bluthuf den Verteidigern, den Prospektoren ihre eisernen Spitzhacken abzunehmen und sie an einer Schmiede zu zerbrechen. Mit zerstörten Spitzhacken kann sich die Expedition nicht tiefer in die Erde graben."}},faq={{q="Was sind diese Zerbrochenen Werkzeuge?",a="Zerbrochene Werkzeuge sind zerstörte Prospector's Picks, die den zwergischen Ausgräbern in Mulgore abgenommen und an einer Schmiede zertrümmert wurden. Ihre Köpfe sind zerstört und ihre Stiele zersplittert.",al={"zerbrochene werkzeuge","was sind zerbrochene werkzeuge","zertrümmerte spitzhacken"}},{q="Warum will Baine Bluthuf sie zerstören lassen?",a="Baine glaubt, dass die Grabungen im Boden das Land entweihen und Mulgores Tierwelt erzürnen, besonders die Kodos. Das Zerbrechen der Spitzhacken stoppt die Ausgrabung und warnt die Zwerge, dass rücksichtslose Grabungen die Weisheit des Landes nicht offenbaren werden.",al={"warum spitzhacken zerstören","warum will baine zerbrochene werkzeuge","baine dwarven digging"}},{q="Wo lassen sich diese Spitzhacken zerbrechen?",a="Ihr könnt die Spitzhacken an jeder funktionierenden Schmiede zerbrechen. Eine steht an der zwergischen Ausgrabungsstätte, weitere findet Ihr im Dorf der Bluthufe oder in Donnerfels.",al={"wie spitzhacken zerbrechen","wo ist die schmiede","prospector's pick zerbrechen"}},{q="Warum graben Zwerge in Mulgore?",a="Die Zwerge glauben, dass Mulgores Boden tiefe Geheimnisse und Relikte aus uralter Zeit birgt. Sie suchen nach ihren Ursprüngen, indem sie fremde Länder aushöhlen, ohne auf deren Bewohner Rücksicht zu nehmen.",al={"warum zwerge in mulgore","zwergische ausgrabungsstätte mulgore"}}},fx={["76aab525"]={q="Woher stammen diese zerbrochenen Werkzeuge?",a="Diese zerstörten Geräte waren ursprünglich robuste Bergbauspitzhacken, die von zwergischen Prospektoren geschmiedet und getragen wurden. Auf der Suche nach Titanenrelikten und uralten Geheimnissen unter Mulgore brachte die Expedition ihre eisernen Werkzeuge mit, um sich nordwestlich in die Erde zu graben. Indem Ihr diese intakten Spitzhacken zu einer Schmiede bringt und sie in Stücke schlagt, reduziert Ihr ihre Bergbauausrüstung zu unbrauchbarem Schrott, bevor Ihr ihn den Tauren als Beweis dafür zurückgebt, dass die Ausgrabung gestoppt wurde.",al={"ursprung der zerbrochenen werkzeuge","wer hat die zerbrochenen werkzeuge hergestellt","woher kommen die zerbrochenen werkzeuge"}}},fp="12,182,18.438.0,28.163.0,45.225.0,32.144.0,35.179.0"}
P.entries["item:bundle-of-akiris-reeds"] = {n="Bundle of Akiris Reeds",s="Ein Bundle of Akiris Reeds ist eine Lieferung, die zu Freibeuter Groy nach Theramore gebracht wird. Er prüft sie für einen Kunden, der mehr möchte.",h="Ein Bundle of Akiris Reeds ist eine Lieferung, die zu Freibeuter Groy nach Theramore gebracht wird.",kw={"akiris","akiris-schilfrohr","bloads","bundle of akiris reeds","freibeuter groy","lieferung","theramore"},sec={{t="Eine frische Lieferung",b="Freibeuter Groy erhält das Schilfrohr in Theramore, nachdem Bloads ihm eine weitere Lieferung geschickt hat. Groy sieht sich das Bündel an und ist erfreut, dass es seinen Kunden zufriedenstellen wird. Dann bezahlt er den Boten und schickt ihn von seinen Docks fort."}},faq={{q="Für wen ist das Bündel?",a="Freibeuter Groy erhält das Bundle of Akiris Reeds in Theramore für einen Kunden, der mehr davon möchte.",al={"wer das schilfrohr möchte","kunde des akiris-bündels","für wen das schilfrohr ist"}},{q="Wohin soll ich das Bündel bringen?",a="Bringt das Bundle of Akiris Reeds zu Freibeuter Groy nach Theramore.",al={"wohin das schilfrohr bringen","groys ort","wohin das bündel bringen"}},{q="Wer schickt das Bündel?",a="Bloads bittet Euch, die Lieferung zu Freibeuter Groy nach Theramore zu bringen.",al={"wer mir das schilfrohr gegeben hat","bloads' lieferung","woher"}},{q="Was macht Groy damit?",a="Groy untersucht das Schilfrohr und sagt, dass ein weiteres Bündel seinem Kunden gefallen wird.",al={"groy prüft das bündel","wofür die lieferung ist","kunde möchte mehr"}}},fp="22,120,16.215.0,22.92.0,27.64.0,21.69.0,26.71.0"}
P.entries["item:bundle-of-atal-ai-artifacts"] = {n="Bundle of Atal'ai Artifacts",s="Ein Bündel Atal’ai-Artefakte wird vom Tränenteich zu einem verbannten Priester im Hinterland gebracht, der seinen Zweck kennt.",h="Ein Bündel Atal’ai-Artefakte wird vom Tränenteich zu einem verbannten Priester im Hinterland gebracht, der...",kw={"artefakte","atal’ai","bündel","chamber of blood","verbannung","hakkar","jammal’an","tränenteich","beschwörung","witherbark"},ang={["race:Troll"]="Das Bündel betrifft Atal’ai-Riten und einen Verbannten, der bei den Witherbark-Trollen im Hinterland lebt."},sec={{t="Ein in Blut geschriebener Satz",b="Ein in Blut geschriebener Satz nahe dem Tränenteich verurteilt einen Atal’ai-Priester zur Verbannung. Die dort gesammelten Artefakte sind für den Priester bestimmt, der bei den Witherbark-Trollen im Hinterland Zuflucht gefunden hat. Er soll ihren wahren Zweck enthüllen."},{t="Der Zweck der Artefakte",b="Der Verbannte erkennt das Bündel als Beschwörungsartefakte. Jammal’an the Prophet führt die Jünger der Chamber of Blood ihrem auserwählten Schicksal entgegen, und es bleibt die Frage, ob Hakkar in den Tempel zurückgekehrt ist."}},faq={{q="Wozu dienen die Atal’ai-Artefakte?",a="Der verbannte Priester erkennt die Atal’ai-Artefakte als Beschwörungsartefakte.",al={"zweck der artefakte","wozu dienen artefakte","atal’ai-bündel"}},{q="Wer soll das Bündel erhalten?",a="Das Bündel ist für einen verbannten Atal’ai-Priester bestimmt, der bei den Witherbark-Trollen im Hinterland lebt.",al={"wer erhält die artefakte","atal’ai-verbannter","empfänger des bündels"}},{q="Warum wurde der Priester verbannt?",a="Der Atal’ai-Stamm verurteilte den Priester zur Verbannung. Der Satz nennt keinen Grund.",al={"grund für die verbannung","urteil über atal’ai-priester","was hat der priester getan"}},{q="Wer führt die Jünger der Chamber of Blood an?",a="Jammal’an the Prophet führt die Jünger der Chamber of Blood an.",al={"anführer der chamber of blood","jammal’an","wer führt die jünger an"}},{q="Ist Hakkar in den Tempel zurückgekehrt?",a="Der Priester fragt sich, ob Hakkar in den Tempel zurückgekehrt ist. Seine Rückkehr ist nicht bestätigt.",al={"hakkar zurück","hakkar im tempel","ist hakkar dort"}}},fp="27,139,24.254.0,24.213.1,37.76.1,38.105.0,26.94.1,41.68.0,34.90.1"}
P.entries["item:bundle-of-crocolisk-skins"] = {n="Bündel Krokiliskenhäute",s="Jäger im Sumpfland schicken Krokiliskenhäute nach Westen zum Hafen von Menethil. Dort verarbeiten Lederverarbeiter die Häute.",h="Jäger im Sumpfland schicken Krokiliskenhäute nach Westen zum Hafen von Menethil.",kw={"krokilisk","einar","james halloran","leder","hafen von menethil","sida","häute","sumpfland"},ang={["faction:Alliance"]="Als Reisende der Allianz könnt Ihr sehen, wie Jäger außerhalb des Hafens von Menethil dessen Garnison und Bürger im unwirtlichen Sumpf mit Materialien versorgen."},sec={{t="Handel im Sumpfland und häuslicher Zwist",b="Im Sumpfland sammeln und gerben Jäger zähe, wasserbeständige Krokiliskenhäute für den Hafen von Menethil. James Halloran gehört zu den Handwerkern, die sie erhalten. Einar hat dieses Bündel zusammengetragen, bittet aber einen Reisenden, es in die Stadt zu bringen. Er hofft, so nicht nach Hause gehen und sich dem Zorn seiner frustrierten Frau Sida stellen zu müssen."}},faq={{q="Wofür wird das Bündel Krokiliskenhäute verwendet?",a="James Halloran, ein Gerber im Hafen von Menethil, erhält die rohen und gegerbten Sumpfhäute aus dem Bündel. Er fertigt robuste Stiefel, Gürtel und Lederrüstungen, die sich für den feuchten, überschwemmten Boden des Sumpflands eignen.",al={"krokiliskenhäute verwendung","wofür sind diese häute","häutebündel zweck"}},{q="Wer hat diese Krokiliskenhäute gesammelt?",a="Jäger Einar hat die Häute in den Sümpfen gesammelt und gebündelt. Gewöhnlich trägt er seine Handelswaren selbst in die Stadt, bittet aber einen vorbeikommenden Reisenden, dieses Bündel zu bringen, um einen Streit mit seiner Frau Sida zu vermeiden.",al={"wer hat das bündel zusammengestellt","wer hat die häute gesammelt","einar krokilisk"}},{q="Wer ist James Halloran?",a="James Halloran arbeitet als Lederverarbeiter und Gerber im Hafen von Menethil. Er kauft rohe und gegerbte Häute von Jägern aus den Sümpfen und fertigt Stiefel, gegerbtes Leder und zweckmäßige Ausrüstung für Seeleute, Soldaten und Stadtbewohner.",al={"james halloran aufgabe","wer ist halloran","gerber menethil"}}},fx={["639d94c2"]={q="Was ist das Bündel Krokiliskenhäute?",a="Es handelt sich um ein verschnürtes Paket aus Rohbälgen, die von den gefährlichen Krokilisken geerntet wurden, welche im Sumpfland lauern. Einar Steingriff hat sie gesammelt und zusammengebunden, um sie an die lokalen Handwerker im Hafen von Menethil zu verkaufen, obwohl persönliche Probleme ihn daran hindern, die Waren selbst auszuliefern.",al={"was ist das bündel krokiliskenhäute","bündel krokiliskenhäute"}},["8cc4b9e1"]={q="Warum benötigt James Halloran das Bündel Krokiliskenhäute?",a="James Halloran arbeitet als Gerber im Hafen von Menethil und ist auf verlässliche Lieferungen frischer Bälge angewiesen, um hochwertige Lederstiefel und gegerbte Rüstungen für Bewohner und Reisende herzustellen. Krokiliskenrohbälge liefern das zähe, widerstandsfähige Material, das er benötigt, um sein Handwerk auszuüben und seine Vorräte aufzufüllen.",al={"warum braucht james halloran die häute","warum das bündel krokiliskenhäute haben wollen","james halloran krokiliskenhäute"}}},fp="25,113,37.308.0,47.187.0,35.211.0,22.208.0"}
P.entries["item:bundle-of-hides"] = {n="Bündel mit Bälgen",s="Ein Bündel mit Bälgen reist mit den Windreitern der Horde über das Brachland nach Donnerfels. Die gegerbten Häute sind für die Lederverarbeiter bestimmt, und ihre Lieferung zeigt Reisenden, wie das Windreiternetz Waren befördert.",h="Ein Bündel mit Bälgen reist mit den Windreitern der Horde über das Brachland nach Donnerfels.",kw={"ahanu","brachland","bündel mit bälgen","das wegekreuz","devrak","hewa's armory","jahan","lederverarbeitung","donnerfels","wind rider"},ang={["faction:Horde"]="Einfache Pelzlieferungen durchqueren den Himmel auf Wyvernflugrouten und verbinden abgelegene Außenposten der Horde mit ihren Hauptstädten.",["race:Tauren"]="Als Tauren nutzt Ihr natürliche Materialien und jagt mit Ehrfurcht. Aus den Bälgen der benachbarten Savanne entstehen Rüstungen und Handwerkswaren, die an Mulg ores Marktständen verkauft werden."},sec={{t="Handel im Grenzland",b="Jäger gerben die Häute von Bestien aus dem gesamten Brachland. Kodos grasen auf den Ebenen, während Löwen umherstreifen und Raptoren umherziehen. Die Lederverarbeiter von Donnerfels nutzen diese Häute für Ausrüstung, Beutel, Rüstungen und Riemen für die Horde."},{t="Fracht am Himmel",b="Kuriere befördern das Bündel auf Devraks abgerichteten Wyvern vom Wegekreuz nach Donnerfels. Der Landweg durch das Brachland nach Mulgore ist langsam und gefährlich, denn Borstennacken und Zentaurenräuber treiben dort ihr Unwesen. Mit dem Windreiter überqueren die Bälge Kalimdors zerklüftetes Gelände rasch."}},faq={{q="Wofür wird das Bündel mit Bälgen verwendet?",a="Das Bündel mit Bälgen bringt Häute von Tieren aus dem gesamten Brachland zu Ahanu, einem Lederverarbeiter in Donnerfels. Er fertigt Lederwaren und Rüstzeug für die Tauren und ihre Verbündeten in der Horde.",al={"bündel mit bälgen verwendung","warum bälge transportieren","wofür sind bälge"}},{q="Wer nimmt die Lieferung in Donnerfels entgegen?",a="Ahanu nimmt das Paket in Hewa’s Armory am Fuß des Windreiterhorsts von Donnerfels entgegen.",al={"wer bekommt die bälge","bündel mit bälgen empfänger","wo ist ahanu"}},{q="Warum wird dieses Bündel mit einem Windreiter verschickt?",a="Die Reise vom Wegekreuz nach Donnerfels dauert zu Fuß Tage und birgt die Gefahr von Hinterhalten durch Zentauren oder Borstennacken. Devrak, der Flugmeister am Wegekreuz, schickt die Waren auf einem Windreiter los, damit sie rasch und sicher ankommen.",al={"warum bälge fliegen","wegekreuz flug bälge","devrak windreiter"}},{q="Wer hat das Bündel im Brachland vorbereitet?",a="Jahan Falkenschwinge stellte das Bündel aus den Häuten von Tieren des Brachlands zusammen. Er verkauft Leder- und Kettenrüstungen am Wegekreuz und arbeitet mit Ahanu zusammen.",al={"wer gab die bälge","jahan bälge","wer sammelte die pelze"}}},fx={["2b9c2280"]={q="Was ist das Bündel mit Bälgen?",a="Das Bündel mit Bälgen ist eine verschnürte Lieferung von Rohfellen, die von den wilden Bestien im Brachland stammen. Es wurde lokal in der Nähe vom Wegekreuz gesammelt und aufbereitet und dient als wichtiges Handwerksmaterial, das für den Export nach Donnerfels bestimmt ist, wo geschickte Lederverarbeiter die zähen Grenzlandfelle zu Rüstungen, Kleidung und essenziellen Handelswaren verarbeiten.",al={"was ist das bündel mit bälgern","bündel mit bälgern gegenstand","bündel mit bälgern hintergrundgeschichte"}}},fp="15,223,14.223.0,15.280.0,37.194.0,43.96.0,38.215.0,39.135.0"}
P.entries["item:bundle-of-wood"] = {n="Kleinholzbündel",s="Das Holzfällerlager des Osttals muss Holz für Sturmwinds Wiederaufbau nach Westen schicken.",h="Das Holzfällerlager des Osttals muss Holz für Sturmwinds Wiederaufbau nach Westen schicken.",kw={"kleinholzbündel","eastvale","elwynn","holzfällerlager","bauholz","raelen"},ang={["faction:Alliance"]="Als Reisender der Allianz helft Ihr durch das Einsammeln der Bündel beim Wiederaufbau Sturmwinds und sichert pünktliche Lieferungen lebenswichtigen Bauholzes für Siedlungen in ganz Elwynn und Westfall."},sec={{t="Zurückgelassenes Bauholz",b="Das Holzfällerlager des Osttals schickt frisch geschlagenes Holz nach Westen, für Gebäude und andere Bauvorhaben im Königreich Sturmwind. Doch Bären und Wölfe sind in die Haine nordwestlich des Lagers eingedrungen. Die verängstigten Holzfäller flohen und ließen ihre Kleinholzbündel zwischen den Bäumen zurück. Die Lieferfrist rückt näher, und Aufseher Raelen braucht Reisende, die das Holz bergen, bevor die Holzlieferverträge gebrochen werden."}},faq={{q="Warum wurden diese Kleinholzbündel im Wald zurückgelassen?",a="Wölfe und Bären vertrieben die Holzfäller, die nordwestlich des Holzfällerlagers des Osttals Holz schlugen. Die Arbeiter ließen ihre frisch geschlagenen Kleinholzbündel auf dem Waldboden zurück.",al={"warum liegt holz am boden","warum holz zurücklassen","zurückgelassenes bauholz elwynn"}},{q="Wer braucht jemanden, der dieses Holz einsammelt?",a="Raelen, ein Aufseher im Holzfällerlager des Osttals, braucht das Holz bald, um die nahende Frist für eine Holzlieferung einzuhalten.",al={"wer will das holz","raelen bauholz","holz abgeben"}},{q="Wo sind diese Bündel zu finden?",a="Die Bündel liegen zwischen den Bäumen unmittelbar nordwestlich des Holzfällerlagers des Osttals, wo Elwynns Bären und Wölfe umherstreifen.",al={"kleinholzbündel fundort","wo ist das holz","eastvale holzfundorte"}},{q="Warum haben die Stadtwachen die wilden Tiere nicht vertrieben?",a="Raelen bat Stellvertreter Rainer um Hilfe, doch Elwynns Marschälle und Wachen sind in der gesamten Region überlastet. Die Holzfäller brauchen Hilfe von außerhalb, um die Stämme schnell zu bergen.",al={"warum keine wachen","stellvertreter rainer holz","wachen in eastvale"}}},fx={e892b12c={q="Was ist ein Kleinholzbündel?",a="Dies sind Stapel aus frisch geerntetem Holz, das von den Arbeitern des Holzfällerlagers des Osttals geschlagen und gesammelt wurde. Für den Transport und die Verarbeitung vorbereitet, repräsentieren sie die laufenden Holzarbeiten im östlichen Wald von Elwynn.",al={"was ist das kleinholzbündel","kleinholzbündel elwynn","was sind diese holzbündel"}}},fp="14,70,16.390.0,54.168.0,30.123.0,30.115.0,48.173.0"}
P.entries["item:burning-blade-medallion"] = {n="Medaillon der Brennenden Klinge",s="In Durotar bedroht das Medaillon der Brennenden Klinge die jungen Krieger der Horde. Kultisten tragen es im Tal der Prüfungen, und Yarrog Baneshadow hält es tief im Koven der Brennenden Klinge.",h="In Durotar bedroht das Medaillon der Brennenden Klinge die jungen Krieger der Horde.",kw={"koven der brennenden klinge","medaillon der brennenden klinge","durotar","teufelspirscher","talisman","das tal der prüfungen","yarrog baneshadow","zureetha fernblick"},ang={["class:Warlock"]="Als Hexenmeister der Horde übt Ihr dunkle Magie unter strenger Disziplin aus. Das Medaillon kennzeichnet die abtrünnige, ungezügelte Teufelsmagie der Burning Blade, die Durotars Stabilität bedroht.",["race:Orc"]="Als Orc erinnert Euch das Medaillon an die dämonische Verderbnis, die Euer Volk einst versklavte. Dieser Schatten bedroht nun junge Initianden, noch bevor sie das Tal der Prüfungen verlassen."},sec={{t="Ein Zeichen der Verderbnis",b="Zureetha Fernblicks Weissagungen führen zum Medaillon im Koven der Brennenden Klinge. Yarrog Baneshadow dient dem Kult der Burning Blade und trägt es tief in den verwinkelten Höhlen. Das Schmuckstück bündelt dunkle Macht inmitten der Wichtelvertrauten und Teufelspirscher des Kults. Yarrog zu besiegen und das Medaillon an sich zu nehmen, beendet den Versuch des Kults, die Übungsplätze der Horde von Durotar aus zu untergraben."}},faq={{q="Was ist das Medaillon der Brennenden Klinge?",a="Yarrog Baneshadow, ein in Durotar versteckter Agent des Kults der Burning Blade, trägt den magischen Talisman. Er bündelt dunkle Magie und kennzeichnet die Treue seines Trägers zum Kult.",al={"talisman der burning blade","medaillon des kovens","yarrogs medaillon"}},{q="Wer will das Medaillon bergen lassen?",a="Zureetha Fernblick, eine Orcseherin vor dem Den im Tal der Prüfungen, will das Medaillon bergen lassen. Sie hofft, den dämonischen Einfluss auszumerzen und die örtlichen Pläne des Kults zu untersuchen.",al={"wer nimmt das medaillon entgegen","wo das medaillon abgeben","zureetha fernblick quest"}},{q="Wo ist das Medaillon zu finden?",a="Yarrog Baneshadow hält das Medaillon tief im Koven der Brennenden Klinge, einer verborgenen Höhle nordwestlich des Den im Tal der Prüfungen. Er lauert auf den oberen Felsvorsprüngen der Höhle.",al={"wo ist yarrog baneshadow","medaillon der brennenden klinge fundort","wie das medaillon finden"}},{q="Was bedeutet die Anwesenheit des Medaillons für Durotar?",a="Das Medaillon bestätigt, dass der Kult der Burning Blade Agenten auf den Übungsplätzen der Horde eingeschleust hat. Seine Anwesenheit deutet auf die weitreichenderen, gefährlicheren Bestrebungen der Kultisten in der gesamten Heimat der Orcs hin.",al={"warum sind kultisten im tal der prüfungen","ist die burning blade in durotar"}}},fp="23,184,20.384.0,36.175.0,34.175.0,29.174.0,52.201.0"}
P.entries["item:burning-blood-quest-item"] = {n="Brennendes Blut",s="Im Dämmerwald weckt das Blut der Nightbane-Worgen Grimand Elmores Interesse. Er braucht zwanzig Phiolen für Schmiedeexperimente.",h="Im Dämmerwald weckt das Blut der Nightbane-Worgen Grimand Elmores Interesse.",kw={"burning blood","dämmerwald","furen langbart","grimand elmore","gutspill","nightbane","rolands verdammnis","worgen"},ang={["class:Warrior"]="Grimand Elmore verwendet Burning Blood, um Schmiedemethoden zu erproben. Er verspricht Kriegern, die es ihm bringen, eine haltbare Plattenrüstung.",["profession:Blacksmithing"]="Schmiede können ungewöhnliche Materialien wie brennendes Worgenblut nutzen, um schwere Metalle bei extremer Hitze abzuschrecken und zu härten."},sec={{t="Ein flüchtiges Reagenz",b="Nightbane-Worgen durchstreifen den Dämmerwald in seltsamer Raserei. Ihr Blut brennt mit echter Hitze. Es lässt sich Worgen entnehmen, die die Waldgebiete und Rolands Verdammnis heimsuchen. Rüstungsschmiede suchen seine Hitze, um widerstandsfähige Platten zu härten."},{t="Elmores Experiment",b="Grimand Elmore ist Rüstungsschmied im Zwergendistrikt von Sturmwind. Er will Schmiedemethoden erproben, die sein ehemaliger Schüler Furen Langbart entwickelt hat.\n\nFür das Experiment braucht Elmore Burning Blood und einen dichten Brennenden Fels, den der Worgenhäuptling Gutspill besitzt. Bringt ihm die brodelnde Flüssigkeit, und er verspricht Euch eine robuste Kriegerrüstung aus seiner Schmiede."}},faq={{q="Was ist Burning Blood?",a="Nightbane-Worgen im Dämmerwald haben heißes Blut. Grimand Elmore braucht es für Schmiedeexperimente.",al={"burning blood hintergrund","was ist burning blood","worgenblut"}},{q="Woher stammt Burning Blood?",a="Burning Blood stammt von Nightbane-Worgen im Dämmerwald, besonders von jenen rund um Rolands Verdammnis.",al={"wo gibt es burning blood","wer lässt burning blood fallen","burning blood fundort"}},{q="Warum braucht Grimand Elmore es?",a="Grimand Elmore braucht Burning Blood, um Schmiedemethoden zu erproben, die Furen Langbart entwickelt hat. Mit einem Brennenden Fels will er eine schützende Kettenrüstung für einen Krieger schmieden.",al={"warum will grimand burning blood","grimand elmore blutquest"}},{q="Warum brennt das Blut der Nightbane?",a="Nightbane sind unnatürliche Scheusale, die durch dunkle, chaotische Magie beschworen wurden. Der Fluch in ihrem Blut verleiht ihm eine gewaltige, unnatürliche Hitze.",al={"warum haben worgen brennendes blut","ist worgenblut feuer"}}},fp="13,119,18.206.0,19.337.0,22.94.0,35.93.0,32.159.0,42.123.0"}
P.entries["item:burning-rock"] = {n="Brennender Fels",s="Im Dämmerwald schwelt der Brennende Fels in Rolands Verdammnis. Gutspill, Anführer der Nightbane-Worgen, trägt ihn bei sich, und Grimand Elmore in Sturmwind braucht ihn zusammen mit feurigem Worgenblut, um verzauberte Rüstungen für vielversprechende Krieger zu schmieden.",h="Im Dämmerwald schwelt der Brennende Fels in Rolands Verdammnis.",kw={"brennender fels","dämmerwald","furen langbart","grimand elmore","gutspill","nightbane-worgen","rolands verdammnis"},ang={["class:Warrior"]="Als Krieger trotzt Ihr den Gefahren von Rolands Verdammnis, um den Brennenden Fels zu bergen. Grimand Elmore belohnt Eure Tapferkeit mit einer maßgefertigten Rüstung, die mithilfe seiner Hitze geschmiedet wird.",["profession:Blacksmithing"]="Als Schmied könnt Ihr den Brennenden Fels als ungewöhnliche Hitzequelle untersuchen. Rüstungsschmiede in Sturmwind und Eisenschmiede erkunden unkonventionelle Verfahren zum Schmelzen und Härten von Rüstungen."},sec={{t="Eine schwelende Beute",b="Gutspill trägt den Brennenden Fels durch die Schächte von Rolands Verdammnis. Grimand Elmore in Sturmwind will seine Hitze für Rüstungen nutzen, die mit feurigem Worgenblut gefertigt werden. Er erprobt Schmiedetechniken seines Kollegen Furen Langbart und hofft, widerstandsfähige Rüstungsplatten für erfahrene Kämpfer herzustellen."}},faq={{q="Wo ist der Brennende Fels zu finden?",a="Gutspill trägt den Brennenden Fels in Rolands Verdammnis im östlichen Dämmerwald bei sich.",al={"brennender fels fundort","wer lässt brennenden fels fallen","wo brennenden fels bekommen"}},{q="Wer will den Brennenden Fels?",a="Grimand Elmore, ein zwergischer Schmied im Zwergendistrikt von Sturmwind, will den Brennenden Fels, um experimentelle Schmiedetechniken zu erproben.",al={"wer braucht brennenden fels","wer gibt brennenden fels ab","grimand elmore brennender fels"}},{q="Warum braucht Grimand Elmore ihn?",a="Grimand will Fertigungstechniken erproben, die Furen Langbart entwickelt hat. Zusammen mit dem Blut der Nightbane-Worgen liefert der schwelende Fels die Hitze, um eine einzigartige Rüstung zu schmieden.",al={"brennender fels verwendung","warum brennender fels","was bewirkt brennender fels"}},{q="Welche Verbindung hat dieser Fels zu den Worgen?",a="Die Nightbane-Worgen in Rolands Verdammnis weisen seltsame feurige Eigenschaften auf, darunter brennendes Blut. Ihr Anführer Gutspill bewahrt den Brennenden Fels tief in der Mine auf. Wie er dorthin gelangte, ist unbekannt.",al={"warum haben worgen brennenden fels","gutspill brennender fels hintergrund"}}},fx={a40de154={q="Was ist der Brennende Fels?",a="Der Brennende Fels ist ein seltener, erhitzter Mineralbrocken, der tief in den verwunschenen Wäldern des Dämmerwalds gefunden wird. Er befindet sich im Besitz von Gutspill, dem Anführer der wilden Nightbane-Worgen, die Rolands Verdammnis besetzt halten. Dieser feurige Stein behält eine intensive Hitze bei und ist für spezialisierte Schmiedekunst und Metallurgie begehrt.",al={"was ist der brennende fels","brennender fels gegenstand","über den brennenden fels"}}},fp="12,224,18.267.0,32.71.0,27.130.0,32.170.0,50.186.0"}
P.entries["item:buzzard-gizzard"] = {n="Buzzard Gizzard",s="Geiermägen sind Reagenzien, die von den Geiern des Ödlands gesammelt werden. Jarkal Mossmeld in Kargath braucht sie, um seine alchemistischen Vorräte aufzufüllen.",h="Geiermägen sind Reagenzien, die von den Geiern des Ödlands gesammelt werden.",kw={"alchemist","ödland","geier","geiermagen","jarkal mossmeld","kargath","reagenz"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr die Reagenzien aus dem Ödland, die Jarkal Mossmeld braucht, nach Kargath bringen."},sec={{t="Ein benötigtes Reagenz",b="Jarkal Mossmeld, ein Alchemist in Kargath, bittet um fünf Geiermägen, um seine Vorräte aufzufüllen. Die Geier des Ödlands liefern sie neben den anderen Reagenzien, die er sucht. Bringt die Mägen zusammen mit den übrigen angeforderten Vorräten zu Jarkal."}},faq={{q="Wer braucht Geiermägen?",a="Jarkal Mossmeld, ein Alchemist in Kargath, braucht fünf Geiermägen, um seine Vorräte aufzufüllen.",al={"wer braucht mägen","jarkal mägen"}},{q="Woher stammen Geiermägen?",a="Geier im Ödland liefern Mägen. Giant Buzzards, Buzzards, Starving Buzzards und Wayward Buzzards haben sie nachweislich bei sich.",al={"fundort der mägen","wo mägen","geierteile"}},{q="Wofür werden Geiermägen verwendet?",a="Jarkal Mossmeld verwendet Geiermägen als alchemistische Reagenzien, um seine Vorräte aufzufüllen.",al={"verwendung von mägen","warum mägen","alchemistische reagenzien"}},{q="Wie viele Mägen braucht Jarkal?",a="Jarkal Mossmeld bittet um fünf Geiermägen.",al={"anzahl der mägen","wie viele geierteile","fünf mägen"}}},fp="15,147,16.240.0,27.94.0,36.130.0,35.85.0,35.47.0"}
P.entries["item:cache-of-zanzil-s-altered-mixture"] = {n="Behälter mit Zanzils veränderter Mixtur",s="Im Turm der Venture Company nahe dem Schlickermoor liegt ein Behälter mit Zanzils veränderter Mixtur unter Verschluss. Das starke Gift trägt den Namen von Zanzil, einem Dschungeltroll-Hexendoktor.",h="Im Turm der Venture Company nahe dem Schlickermoor liegt ein Behälter mit Zanzils veränderter Mixtur unter...",kw={"veränderte mixtur","gallywix","schatulle","gift","shattered hand","shenthul","das schlickermoor","venture company","zanzil"},ang={["class:Rogue"]="Für Schurken der Horde ist die Bergung der Mixtur eine Bewährungsprobe. Sie beweist ihre Meisterschaft im Schlossknacken, Taschendiebstahl und Umgang mit Giften im Dienst der Shattered Hand.",["faction:Horde"]="Der giftverseuchte Turm der Venture Company nördlich des Schlickermoors bedroht die Umgebung und die Sicherheit sowohl Durotars als auch des Brachlands."},sec={{t="Ein giftiges Unternehmen",b="Nördlich des Schlickermoors im Brachland unterhält die Venture Company einen Turmaußenposten. Obervorarbeiter Puzik Gallywix verwahrt ganz oben in seiner privaten Geldkassette einen Behälter mit veränderter Mixtur, die den Namen des Troll-Hexendoktors Zanzil trägt. Ein Gift hat alle im Turm geschwächt, sodass seine Goblinbewohner einem kühnen Eindringling schutzlos ausgeliefert sind."},{t="Bergung für die Shattered Hand",b="Die Shattered Hand ist eine geheimnisumwitterte Schurkengilde unter Orgrimmar. Meisterausbilder Shenthul entsendet Agenten, um den Turm zu stürmen, Gallywix zu töten und seine Schatulle aufzubrechen. Die Gilde will die Bedrohung ausschalten und die Mixtur für ihre eigene nachrichtendienstliche Arbeit untersuchen. Die Bergung des Behälters mit der instabilen Mixtur erfordert großes Geschick beim Infiltrieren. Sein verunreinigtes Gefäß kann jeden, der es anfasst, schwächenden Giftstoffen aussetzen."}},faq={{q="Was ist Zanzils veränderte Mixtur?",a="Zanzils veränderte Mixtur ist ein starkes Gift, das nach dem Troll-Hexendoktor Zanzil benannt ist. Ein Behälter liegt verschlossen im Turm der Venture Company nahe dem Schlickermoor, wo Gift alle im Inneren geschwächt hat.",al={"was ist zanzils mixtur","was ist der behälter","zanzils trank"}},{q="Wo ist der Behälter zu finden?",a="Der Behälter befindet sich in Gallywix's Lockbox ganz oben im Turm der Venture Company, nördlich des Schlickermoors im Brachland.",al={"wo ist die mixtur","wo ist zanzils behälter","fundort der mixtur"}},{q="Warum will die Shattered Hand die Mixtur?",a="Shenthul und die Shattered Hand wollen den Betrieb der Venture Company vor den Toren der Horde ausschalten und das Gemisch für eigene nachrichtendienstliche Untersuchungen bergen.",al={"wer will die mixtur","warum will shenthul sie","mission der shattered hand"}},{q="Wie öffnet Ihr die Truhe mit dem Behälter?",a="Die Truhe hat filigrane Zuhaltungsschlösser, die fortgeschrittene Fertigkeiten im Schlossknacken erfordern. Das verunreinigte Gefäß darin kann jeden, der es anfasst, schwächenden Giftstoffen aussetzen.",al={"wie gallywix's lockbox öffnen","zanzils truhe öffnen","schlossknacken zanzils behälter"}}},fx={["83dd2f73"]={q="Woher stammt Zanzils veränderte Mixtur und wer hat sie hergestellt?",a="Das Gebräu stammt von dem Hexendoktor Zanzil, obwohl es in die Hände der Venture Company gelangte, die im Brachland operiert. Großvorarbeiter Puzik Gallywix hielt den verbleibenden veränderten Vorrat in seinem persönlichen Schließfach an der Spitze ihres Bohrturms nahe dem Schlickermoor verschlossen.",al={"wer hat zanzils veränderte mixtur hergestellt","ursprung der veränderten mixtur","woher kam die zanzil-mixtur"}}},fp="33,176,18.341.0,31.410.1,33.197.0,25.115.0,45.165.0,47.152.0"}
P.entries["item:cactus-apple"] = {n="Kaktusapfel",s="Im Tal der Prüfungen bieten Kaktusäpfel Orcs eine seltene Feuchtigkeitsquelle in Durotars trockener Hitze.",h="Im Tal der Prüfungen bieten Kaktusäpfel Orcs eine seltene Feuchtigkeitsquelle in Durotars trockener Hitze.",kw={"kaktusapfel","kaktusapfel surprise","wüstenfrucht","durotar","galgar","das tal der prüfungen"},ang={["profession:Cooking"]="Als Koch in der Wildnis Durotars könnt Ihr aus Wüstenkakteen eine feuchtigkeitsspendende Mahlzeit zubereiten.",["race:Orc"]="Als junger Orc in Durotar lernt Ihr, jedes knappe bisschen Feuchtigkeit zu nutzen, das der rote Canyon bietet."},sec={{t="Ernte der Wüste",b="Überall im Tal der Prüfungen wachsen Kaktusäpfel in Büscheln um dicke Kakteen. Wer sie sammelt, muss zwischen den Dornen arbeiten, doch die Früchte stillen den Durst in Durotars Hitze. Galgar, ein Orc im Tal, sammelt die Äpfel für Kaktusapfel Surprise. Rekruten, die ihre ersten Ausbildungseinheiten durchstehen, können sich mit seiner Leckerei abkühlen."}},faq={{q="Wo wachsen Kaktusäpfel?",a="Kaktusäpfel wachsen wild im Tal der Prüfungen im Süden Durotars. Sie wachsen in Büscheln am Fuß kräftiger Kakteen, die über den Talkessel verstreut stehen.",al={"kaktusapfel fundorte","wo kaktusapfel finden","kaktusapfel fundstelle"}},{q="Was ist Kaktusapfel Surprise?",a="Kaktusapfel Surprise ist eine gekühlte Speise, die Galgar aus frisch gesammelten Kaktusäpfeln zubereitet. Die Leckerei verschafft Linderung in Durotars Wüstenhitze.",al={"was ist galgars surprise","kaktusapfel rezept","galgars leckerei"}},{q="Wer bittet um diese Äpfel?",a="Galgar, ein Orc im Tal der Prüfungen, bittet junge Rekruten, ihm sechs frische Äpfel zu bringen. Dafür gibt er ihnen Portionen seiner kühlenden Nachspeise.",al={"kaktusapfel questgeber","wer will kaktusäpfel","galgars äpfel"}}},fx={["93b3f975"]={q="Was ist ein Kaktusapfel?",a="Ein Kaktusapfel ist eine knackige, erfrischende Wildfrucht, die unter den dornigen Kakteen im Tal der Prüfungen in Durotar gedeiht. Trotz der rauen, trockenen Bedingungen in der Heimat der Orcs produzieren diese widerstandsfähigen Pflanzen saftige Früchte, die unter der sengenden Wüstensonne dringend benötigte Flüssigkeit und Nahrung bieten.",al={"was ist ein kaktusapfel","kaktusapfel hintergrundgeschichte","was sind kaktusäpfel"}},e52e1b37={q="Woher kommen Kaktusäpfel?",a="Kaktusäpfel sind heimische Wüstenfrüchte, die auf natürliche Weise am Fuß von Kakteen wachsen, die über das Tal der Prüfungen in Durotar verstreut sind. Sie werden von niemandem gezüchtet oder kultiviert, sondern sprießen direkt aus der widerstandsfähigen Flora, die sich an die roten Schluchten und das trockene Klima der Region angepasst hat.",al={"woher kommen kaktusäpfel","kaktusapfel ursprung","wer hat kaktusäpfel hergestellt"}},["0fea9150"]={q="Warum benötigt Galgar Kaktusäpfel?",a="Galgar sammelt sie, um Portionen seines berühmten Kaktusapfel Surprise zuzubereiten. Die brütende Hitze im Tal der Prüfungen setzt sowohl neuen Rekruten als auch erfahrenen Kriegern schwer zu, und das süße, kühlende Dessert aus diesen Äpfeln bietet eine wichtige Erfrischung gegen die brutale Mittagssonne.",al={"warum kaktusäpfel sammeln","warum will galgar kaktusäpfel","kaktusapfel zweck"}}},fp="12,99,14.332.0,28.147.0,30.146.0,26.149.0"}
P.entries["item:caliph-scorpidsting-s-head"] = {n="Caliph Scorpidsting's Head",s="Die Gadgetzan Water Company sucht Beweise gegen Caliph Scorpidsting und bietet über Chefingenieur Bilgewhizzle in Gadgetzan ein Kopfgeld.",h="Die Gadgetzan Water Company sucht Beweise gegen Caliph Scorpidsting und bietet über Chefingenieur...",kw={"bilgewhizzle","kopfgeld","caliph scorpidsting","gadgetzan water company","scorpidstings kopf","tanaris","gesucht","wastewander"},sec={{t="Ein Kopfgeld in Gadgetzan",b="Die Gadgetzan Water Company bezeichnet Caliph Scorpidsting als Anführer der Wastewander outlaws. Sie beschuldigt seine Bande, ihre Mitarbeiter ermordet, ihre Ressourcen gestohlen und ihr Eigentum an sich gerissen zu haben. Für einen Beweis seines Todes bietet das Unternehmen ein hohes Kopfgeld. Chefingenieur Bilgewhizzle nimmt den Kopf in Gadgetzan entgegen."}},faq={{q="Wer will Caliph Scorpidstings Kopf?",a="Die Gadgetzan Water Company bietet ein Kopfgeld für einen Beweis von Caliph Scorpidstings Tod. Chefingenieur Bilgewhizzle nimmt den Kopf in Gadgetzan entgegen.",al={"wer will den kopf","wer zahlt dafür"}},{q="Warum wird Scorpidsting gesucht?",a="Die Gadgetzan Water Company beschuldigt Caliph Scorpidsting und seine Wastewander outlaws, ihre Mitarbeiter ermordet, ihre Ressourcen gestohlen und ihr Eigentum an sich gerissen zu haben.",al={"warum gesucht","was hat er getan"}},{q="Wer ist Caliph Scorpidsting?",a="Caliph Scorpidsting führt die Wastewander outlaws in Tanaris an.",al={"scorpidsting","anführer der wastewander"}},{q="Wohin soll ich seinen Kopf bringen?",a="Bringt Caliph Scorpidsting's Head zu Chefingenieur Bilgewhizzle nach Gadgetzan.",al={"wohin mit dem kopf","bilgewhizzle"}},{q="Wofür ist der Kopf ein Beweis?",a="Der Kopf beweist Caliph Scorpidstings Tod, den die Gadgetzan Water Company als Voraussetzung für ihr Kopfgeld verlangt.",al={"proof of demise","warum der kopf"}}},fp="26,137,21.307.0,37.146.0,27.161.0,27.61.0,26.77.1,26.106.1"}
P.entries["item:calor-s-note"] = {n="Calors Notiz",s="Im Dämmerwald überbringt Calors Notiz die Empfehlung eines Waldläufers an Meister Jonathan Treuwein. Calor schreibt sie für einen bewährten Abenteurer auf einen Fetzen verblassten Pergaments und öffnet damit den Weg zu einer verborgenen Gruppe, die an der Seite von Dunkelhains Miliz kämpft, aber unabhängig von ihr bleibt.",h="Im Dämmerwald überbringt Calors Notiz die Empfehlung eines Waldläufers an Meister Jonathan Treuwein.",kw={"calor","calors notiz","dunkelhain","dämmerwald","jonathan treuwein","night watch","empfehlung","worgen"},ang={["class:Paladin"]="Jonathan Treuwein begrüßt den Überbringer mit den Worten „Ruhm unter dem Licht“, einem Zeichen gemeinsamer Ideale mit heiligen Kriegern, die den Dämmerwald von Dämonen und Untoten säubern wollen.",["faction:Alliance"]="Da die Armee von Sturmwind im Dämmerwald fehlt, bewachen Carevins Kreis und die Nachtwache als inoffizielle Fraktionen die südliche Grenze gegen die Dunkelheit."},sec={{t="Eine seltene Empfehlung",b="Calor ist schwer zu beeindrucken, und der Dämmerwald bietet Fremden wenig Herzlichkeit. Überlebt Ihr die blutrünstigen Worgen, die durch die Wälder streifen, gewährt er Euch seinen Respekt mit einer kurzen Botschaft. Auf verblasstem Pergament reist die Notiz nach Dunkelhain und stellt den Außenstehenden direkt bei Jonathan Treuwein vor."},{t="Ein privater Kreuzzug",b="Dunkelhain verlässt sich bei der öffentlichen Verteidigung auf die Nachtwache. Calor und Carevin führen abseits der Stadtwache einen finstereren, verborgenen Kampf. Calor beklagt, dass die Wache ihnen zahlenmäßig überlegen ist, und hofft, genügend fähige Kämpfer zu finden, um ihren privaten Krieg voranzutreiben. Übergebt Ihr die Notiz, nimmt Carevin Euch in seinen Feldzug gegen Dämonen, Untote und die heimlichen Sympathisanten auf, die den Niedergang des Dämmerwalds begünstigen."}},faq={{q="Was ist Calors Notiz?",a="Calors Notiz ist eine handgeschriebene Botschaft auf einem Fetzen verblassten Pergaments. Sie empfiehlt einen Abenteurer als fähig und zuverlässig im Kampf gegen die Schrecken des Dämmerwalds.",al={"calors notiz","was ist diese notiz","was steht in der notiz"}},{q="Wer erhält die Notiz?",a="Jonathan Treuwein erhält die Notiz. Er ist ein strenger Mann, der in Dunkelhain stationiert ist und den Kampf gegen die dunklen Mächte koordiniert, die die Region bedrohen.",al={"wem die notiz geben","wer bekommt calors notiz","jonathan treuwein notiz"}},{q="Was hält Calor von der Nachtwache?",a="Calor glaubt, dass die Nachtwache den wahren Bedrohungen des Dämmerwalds nicht gewachsen ist. Als er die Notiz überreicht, sagt er, dass er genügend fähige Verbündete anwerben will, um die Miliz zahlenmäßig zu übertreffen und die dringende Arbeit zu vollenden, die seine kleine Fraktion allein verrichtet.",al={"calor und night watch","warum will calor die night watch zahlenmäßig übertreffen"}},{q="Was für einen Kampf führt Jonathan Treuwein?",a="Meister Carevin bekämpft Dämonen, Untote und sterbliche Kollaborateure, die ihnen im Dämmerwald helfen. Er schätzt Wachsamkeit und Hingabe an das Heilige Licht und schenkt nur bewährten Leuten sein Vertrauen.",al={"carevins anliegen","was macht carevin","wen bekämpft carevin"}}},fx={d10add4c={q="Wer hat Calors Notiz geschrieben und woher stammt sie?",a="Die Notiz wurde von Calor geschrieben, einem grimmigen Kämpfer, der in der verwunschenen Weite des Dämmerwalds stationiert ist. Nachdem Ihr Euch gegen die bösartigen Worgen bewiesen habt, die die Wälder terrorisieren, kritzelt er diese Nachricht auf einen Zettel aus verblichenem Pergament, um Euch an seinen Vorgesetzten weiterzuleiten.",al={"calors notiz ursprung","wer hat calors notiz geschrieben","woher kommt calors notiz"}},fe7f9dd8={q="Warum benötigt Jonathan Treuwein Calors Notiz?",a="Meister Jonathan Treuwein verlangt Beweise, bevor er irgendjemandem in einem Land vertraut, das von Schatten überrannt wird. Calors Notiz dient als offizielle Empfehlung und lässt Treuwein wissen, dass Ihr Calors seltenen Respekt genießt und fähig seid, ihren verdeckten Kampf gegen Dämonen, Untote und dunklere Mächte zu unterstützen.",al={"warum calors notiz zu treuwein bringen","warum will treuwein calors notiz","calors notiz zweck für treuwein"}}},fp="12,258,21.285.0,17.387.0,21.148.0,22.153.0,38.232.0,48.196.0"}
P.entries["item:camp-mojache-zukk-ash-report"] = {n="Camp Mojache Zukk'ash Report",s="Der Camp Mojache Zukk'ash Report enthält gesammeltes Wissen über die Insektenbedrohung in Feralas. Er überbringt diese Warnung einem Experten in Orgrimmar.",h="Der Camp Mojache Zukk'ash Report enthält gesammeltes Wissen über die Insektenbedrohung in Feralas.",kw={"camp mojache","drag","feralas","horde","bericht","silithid","zilzibin drumlore","zukk'ash","zukkash"},ang={["faction:Horde"]="Als Mitglied der Horde überbringt Ihr mit diesem Bericht eine Warnung von Camp Mojache an einen Experten in Orgrimmar, der die Silithid als uralte Gefahr bezeichnet."},sec={{t="Eine überbrachte Warnung",b="Hadoken vertraut Euch den Bericht an, nachdem die Zukk'ash-Bedrohung bei Camp Mojache eingedämmt wurde. Das Dokument trägt alles zusammen, was über die Insekten bekannt ist, deren Gefahr weiter besteht. Ihr sollt ihn zu Zilzibin Drumlore in Orgrimmars Drag bringen, wo sein Wissen über seltsame Kreaturen der Horde helfen könnte, die Bedrohung zu verstehen."},{t="Die alte Bedrohung",b="Zilzibin Drumlore erkennt die im Camp Mojache Zukk'ash Report beschriebenen Kreaturen als Silithid. Er bezeichnet sie als uralte Gefahr, die die Horde zu ignorieren beschlossen hat, und hält sie für weit schlimmer als alles, was die Allianz aufbieten könnte. Er bittet um Hilfe dabei, die Bedrohung ans Licht zu bringen."}},faq={{q="Was ist der Camp Mojache Zukk'ash Report?",a="Es ist ein Dokument, das zusammenfasst, was über die Zukk'ash-Insekten erfahren wurde, die Camp Mojache bedrohen.",al={"zukkash bericht","camp mojache bericht","insektenbericht"}},{q="Wer soll den Bericht erhalten?",a="Zilzibin Drumlore in Orgrimmars Drag wartet auf den Bericht.",al={"wer erhält den bericht","zilzibin bericht","wohin den bericht bringen"}},{q="Warum will die Horde, dass dieser Bericht überbracht wird?",a="Zilzibin Drumlore ist ein Experte für seltsame Kreaturen, und die Horde hofft, dass er mit den Erkenntnissen über die Zukk'ash etwas anfangen kann.",al={"warum den bericht überbringen","wofür ist er gedacht","hordenbericht über insekten"}},{q="Was sind die Zukk'ash?",a="Zilzibin erkennt die Zukk'ash als Silithid, eine uralte Bedrohung.",al={"zukk'ash-insekten","was sind die zukk'ash","silithid"}}},fp="28,145,17.316.0,14.268.1,41.94.0,30.69.0,46.133.0,22.64.0"}
P.entries["item:candle-of-beckoning"] = {n="Kerze des Heranlockens",s="Am Blendwassersee bewahrt Gunther Arkanus eine verzauberte Kerze für eine Beschwörung auf. Entzündet sie auf einer nahen kleinen Insel, und Lillith Nefaras rastloser Geist antwortet.",h="Am Blendwassersee bewahrt Gunther Arkanus eine verzauberte Kerze für eine Beschwörung auf.",kw={"blendwassersee","kerze des heranlockens","gunther arkanus","lillith nefara","proving allegiance","the dormant shade","tirisfal"},ang={["class:Mage"]="Als Magier erkennt Ihr Gunthers Meisterschaft der Nekromantie und Beschwörung daran, wie er Geister an Ritualgegenstände wie diese Kerze bindet, jenseits der von den Kirin Tor gebilligten Lehren.",["race:Undead"]="Als Gesandter aus Unterstadt müsst Ihr Gunthers Ritualkerze handhaben, um den erbittert auf seine Unabhängigkeit pochenden Nekromanten davon zu überzeugen, dass Ihr kein Knecht des Lichkönigs seid."},sec={{t="Eine Treueprüfung",b="Gunther Arkanus bewahrt die Kerze des Heranlockens in einer Kiste neben sich auf seiner Insel im Blendwassersee auf. Er ist ein untoter Zauberer, der erbittert auf seine Unabhängigkeit pocht und sich aus eigener Kraft vom Befehl des Lichkönigs befreit hat. Noch immer misstraut Gunther sowohl der Geißel als auch den Verlassenen und bittet Euch, eine Kerze nach Südwesten zu einer kleineren Insel zu bringen. Stellt sie auf den alten, blutbefleckten Tisch und entzündet sie.\n\nDie Flamme durchdringt den Schleier zwischen den Welten und beschwört den schlummernden, rastlosen Schatten von Lillith Nefara. Sie ist eine mächtige Agentin der Geißel, und Gunther will, dass sie vernichtet wird."}},faq={{q="Wozu dient die Kerze des Heranlockens?",a="Entzündet die Kerze des Heranlockens auf dem alten, blutbefleckten Ritualtisch auf der kleineren Insel südwestlich von Gunther Arkanus' Lager. Sie beschwört den schlummernden Geist von Lillith Nefara in die körperliche Welt.",al={"was bewirkt die kerze des heranlockens","verwendung der kerze des heranlockens","wie die kerze des heranlockens benutzen"}},{q="Woher bekommt Ihr die Kerze des Heranlockens?",a="Ihr könnt eine Kerze des Heranlockens aus einer Kiste neben Gunther Arkanus auf seiner Insel im Blendwassersee im östlichen Tirisfal nehmen. Er überlässt sie Euch als Teil seiner Treueprüfung.",al={"wo die kerze des heranlockens finden","wie die kerze des heranlockens erhalten","fundort der kerzenkiste"}},{q="Wer wird von der Kerze beschworen?",a="Das Entzünden der Kerze beschwört Lillith Nefara, eine mächtige Agentin der Geißel, die den blutigen Altar vor der Südküste der Insel heimsucht. Indem Ihr sie besiegt, beweist Ihr, dass Ihr nicht der Geißel dient.",al={"wen beschwört sie","beschwörungsziel der kerze","wer ist lillith nefara"}},{q="Warum hat Gunther Arkanus diese Kerzen?",a="Gunther verwendet die Kerzen für eine Prüfung für jeden, der ein Bündnis mit ihm sucht. Er verteidigt seine Unabhängigkeit von der Geißel erbittert und misstraut Außenstehenden, weshalb er verlangt, dass Ihr Euch den rastlosen Toten stellt, die er beschwört, und sie vernichtet.",al={"warum hat gunther kerzen","gunthers ritualkerzen"}}},fx={["63af5e56"]={q="Was ist die Kerze des Heranlockens?",a="Die Kerze des Heranlockens ist ein verzauberter Ritualdocht, der auf dem isolierten Inselrückzugsort des Nekromanten Gunther Arkanus im Blendwassersee gefunden wird. In einer Kiste neben dem zurückgezogenen Magier aufbewahrt, trägt die Kerze mächtige Beschwörungsmagie in sich, die darauf zugeschnitten ist, den Schleier des Todes zu durchdringen. Wenn sie auf einen blutbefleckten Ritualtisch auf einer nahegelegenen Insel gestellt und angezündet wird, wirkt ihre Flamme wie ein übernatürlicher Köder, der die schlafende Schattengestalt von Lillith Nefara hervorruft.",al={"was ist die kerze des heranlockens","kerze des heranlockens hintergrundgeschichte","was ist die kerze zum heranlocken"}},cb4d5793={q="Warum sollte jemand eine Kerze des Heranlockens wollen?",a="Jeder, der eine Audienz oder ein Bündnis mit Gunther Arkanus sucht, muss zuerst beweisen, dass seine Loyalität nicht dem Lichkönig gilt. Gunther verlangt einen Treuebeweis, bevor er seine beeindruckenden Talente mit den Verlassenen teilt. Indem Ihr eine Kerze des Heranlockens beschafft, könnt Ihr Lillith Nefara hervorlocken und vernichten, was Eure Entschlossenheit demonstriert, Euch der Geißel entgegenzustellen, und Euch den hart erkämpften Respekt des einsiedlerischen Nekromanten einbringt.",al={"warum brauche ich die kerze des heranlockens","warum die kerze des heranlockens haben wollen","zweck der kerze des heranlockens"}}},fp="19,151,20.545.0,41.198.0,41.187.0,30.185.0,44.217.0"}
P.entries["item:cantation-of-manifestation"] = {n="Inkantation der Manifestation",s="In Unterstadt schickt Anastasia Hirschbrunn Lehrlinge aus, um unsichtbare Wesen in Algernons Laden zu enthüllen.",h="In Unterstadt schickt Anastasia Hirschbrunn Lehrlinge aus, um unsichtbare Wesen in Algernons Laden zu...",kw={"algernon","anastasia hirschbrunn","das apothekarium","inkantation der manifestation","eindämmungskassette","magieviertel","rissbrut","unterstadt"},ang={["class:Mage"]="Als Magier verwendet Ihr die Inkantation der Manifestation zu Beginn Eurer Ausbildung, um verborgene arkane Strömungen aufzuspüren und instabile Risswesen einzudämmen.",["race:Undead"]="Als Untoter wisst Ihr, dass die Zauberwirker der Verlassenen im Magieviertel arkane Schwankungen genau beobachten und die Stabilität Unterstadts vor magischen Rissen schützen."},sec={{t="Das Unsichtbare enthüllen",b="Die Inkantation der Manifestation macht Wesen sichtbar, die durch Magie verborgen sind. Anastasia Hirschbrunn bewahrt die Schriftrolle im Magieviertel auf und vertraut sie fähigen Magiern an, die ausgesandt werden, um unkontrollierte magische Anomalien einzudämmen. Im Apothekarium leidet Algernons alchemistische Werkstatt unter arkaner Instabilität. Dort laut vorgelesen, enthüllt die Inkantation verirrte Rissbruten, damit der Zaubernde sie bezwingen und für Studien in Eindämmungskassetten einschließen kann."}},faq={{q="Was bewirkt die Inkantation der Manifestation?",a="Die Inkantation der Manifestation enthüllt unsichtbare arkane Anomalien. Tragt sie dort vor, wo magische Risse oder Störungen ein Gebiet heimsuchen, und unsichtbare Kreaturen wie Rissbruten werden sichtbar, damit Ihr sie bekämpfen und einfangen könnt.",al={"was ist die inkantation der manifestation","zweck der inkantation","wie funktioniert die inkantation"}},{q="Wo finde ich die Inkantation in Unterstadt?",a="Die Inkantation liegt auf dem Boden direkt hinter Anastasia Hirschbrunn, der Magierlehrerin im Magieviertel von Unterstadt.",al={"inkantation fundort unterstadt","wo ist die inkantation der manifestation","inkantation in unterstadt finden"}},{q="Warum braucht Anastasia Hirschbrunn jemanden, der diese Schriftrolle verwendet?",a="In Algernons alchemistischem Laden im Apothekarium ist eine seltsame magische Störung ausgebrochen. Unsichtbare Wesen, die ganz aus Magie bestehen, streifen dort umher, weshalb Anastasia Hirschbrunn Euch braucht, um die Schriftrolle vor Ort vorzulesen und die Wesen zu enthüllen und einzufangen, bevor sich der Riss verschlimmert.",al={"warum die inkantation verwenden","hirschbrunn questmotiv","anastasia störung"}},{q="Darf ich die Schriftrolle nach dem Gebrauch behalten?",a="Nein. Nachdem Ihr die Rissbruten enthüllt und in Eindämmungskassetten eingefangen habt, bringt die Inkantation der Manifestation und die Kassetten zu Anastasia Hirschbrunn zurück.",al={"inkantation behalten","verliere ich die inkantation","inkantation zurückbringen"}}},fx={["1a839123"]={q="Was ist die Inkantation der Manifestation?",a="Die Inkantation der Manifestation ist eine spezialisierte arkanene Schriftrolle, die von Magiern genutzt wird. Wenn sie beschworen wird, durchdringt ihre Inkantation magische Verhüllungen und zwingt unsichtbare Entitäten, die rein aus arkaner Energie gewebt sind, sich dem bloßen Auge zu offenbaren.",al={"was ist die inkantation der manifestation","inkantation der manifestation schriftrolle","was bewirkt die inkantation"}},f236f2b5={q="Warum benötigt Anastasia Hirschbrunn die Inkantation der Manifestation?",a="Unsichtbare magische Kreaturen sind um Algernons Laden im Apothekarium aufgetaucht, was auf einen Riss im Fluss der Magie hindeutet. Magierausbilder benötigen die Inkantation, damit ein Lehrling die Entitäten enthüllen und zur Untersuchung einfangen kann, was den Magiern der Unterstadt ermöglicht festzustellen, ob diese Störung ein Unfall oder ein aktiver magischer Angriff ist.",al={"warum die inkantation haben wollen","warum die inkantation der manifestation benötigen","warum will anastasia die inkantation"}}},fp="26,98,23.426.0,44.216.0,44.118.0,50.258.0,43.155.0"}
P.entries["item:canvas-scraps"] = {n="Segeltuchreste",s="In Klingenhügel erhält Furl Hohnbraue Segeltuchreste für Reisesäcke für neue Rekruten der Horde. Der Stoff stammt von menschlichen Invasoren und Zentaurenstämmen in Durotar.",h="In Klingenhügel erhält Furl Hohnbraue Segeltuchreste für Reisesäcke für neue Rekruten der Horde.",kw={"segeltuchreste","carry your weight","durotar","furl hohnbraue","kolkar","kul tiras","klingenhügel"},ang={["faction:Horde"]="Jeder Stoffrest, der Invasoren aus Kul Tiras oder Kolkar-Plünderern abgenommen wird, hilft dabei, neue Verteidiger auszurüsten, die überall in Durotar Thralls Ruf folgen.",["profession:Tailoring"]="Krieger bergen gewebtes Segeltuch als Rohmaterial, und aus dem strapazierfähigen Stoff lassen sich praktische Taschen für die raue Wüste fertigen."},sec={{t="Trophäen von Durotars Feinden",b="Marinesoldaten und Matrosen aus Kul Tiras führen an Durotars Ostküste Segeltuch mit sich. Ihre Ausrüstung und Segel hinterlassen Stoffreste. Im Landesinneren verwenden Kolkar-Zentauren groben Stoff wieder, den sie aus Nachschubkarawanen und vergangenen Konflikten erbeutet haben. In ihren Lagern und ihrer Ausrüstung finden sich Reste, die sich bergen lassen."},{t="Das Handwerk eines Veteranen",b="Furl Hohnbraue hält vom Wachturm von Klingenhügel aus Ausschau nach Invasoren. Der alternde Veteran hat seine Kampftage hinter sich, findet aber Verwendung für den Stoff, der Feinden abgenommen wurde. Er näht daraus robuste Tragetaschen für jüngere Soldaten. Die Taschen helfen der neuen Generation, die Grenzen der Horde zu verteidigen."}},faq={{q="Woher stammen Segeltuchreste?",a="Segeltuchreste stammen von menschlichen Feinden und Zentauren in ganz Durotar. Truppen aus Kul Tiras in Burg Tiragarde und entlang der Ostküste tragen sie bei sich, ebenso wie Arbeiter und Vorläufer der Kolkar-Zentauren nahe ihren Lagern im Landesinneren.",al={"wer lässt segeltuchreste fallen","wo gibt es segeltuchreste","segeltuchreste farmen"}},{q="Warum möchte Furl Hohnbraue diese Reste haben?",a="Furl Hohnbraue ist ein alternder Orc-Veteran im Wachturm von Klingenhügel, der nicht mehr an vorderster Front kämpfen kann. Er näht aus geborgenem Stoff Reisesäcke für junge Abenteurer.",al={"wer braucht segeltuchreste","wofür werden segeltuchreste verwendet","furl hohnbraue segeltuch"}},{q="Warum tragen die Truppen aus Kul Tiras und die Zentauren Segeltuch bei sich?",a="Die Truppen aus Kul Tiras kamen auf Kriegsschiffen nach Durotar und unterhalten Lager am Meer, wo Segelstoff und gewebtes Segeltuch zum täglichen Bedarf gehören. Kolkar-Zentauren beschaffen sich grobe Stoffe, indem sie Karawanen überfallen, Küsten nach Brauchbarem absuchen und Reisende auf den trockenen Ebenen ausplündern.",al={"warum haben zentauren segeltuch","hintergrund zu segeltuchresten der menschen"}}},fx={["6d5b894e"]={q="Was sind Segeltuchreste?",a="Segeltuchreste sind Stücke aus schwerem, gewebtem Stoff, die aus den Lagern und der Ausrüstung von Feinden in ganz Durotar geborgen wurden. Zäher als einfaches Leinen, wird Segeltuch weitläufig für schwere militärische Ausrüstung, Segel und robuste Zelte verwendet. Während Reste wie diese auf dem Schlachtfeld wie bloßer Abfall aussehen mögen, können ihre haltbaren Fasern leicht von einem geschickten Schneider oder Handwerker zu praktischen Vorräten wiederverwertet werden, wie etwa zu stabilen Tragetaschen für Krieger auf dem Marsch.",al={"was sind segeltuchreste","segeltuchrest gegenstand","was ist segeltuchreste"}}},fp="13,157,29.252.0,17.288.0,33.206.0,42.178.0,53.257.0"}
P.entries["item:captain-s-documents"] = {n="Captain-Dokumente",s="Die Captain-Dokumente sind Papiere, die unter den Docks von Theramore geborgen wurden. Nazeer Bloodpike schätzt sie wegen dessen, was sie über Theramore und die Allianz enthüllen könnten.",h="Die Captain-Dokumente sind Papiere, die unter den Docks von Theramore geborgen wurden.",kw={"allianz","brackenwall","captain-dokumente","common","fußkiste","nazeer bloodpike","theramore","theramores docks"},ang={["faction:Horde"]="Als Mitglied der Horde sollt Ihr Papiere bergen, die laut Nazeer Theramores Stellung zur Allianz enthüllen und die Interessen der Horde schützen könnten."},sec={{t="Unter den Docks",b="Spione aus Brackenwall suchten an Bord eines Schiffs auf der Insel Theramore nach Papieren. Als sie entdeckt wurden, warf einer die Dokumente in eine Fußkiste und schleuderte sie unter die Docks. Nazeer Bloodpike schickt Euch nun, um die Papiere zu bergen. Er glaubt, sie könnten für die Sicherheit der Horde wichtig sein."}},faq={{q="Was sind die Captain-Dokumente?",a="Es sind Papiere, die Spione aus Brackenwall von einem Schiff auf der Insel Theramore mitnahmen. Als die Spione entdeckt wurden, warfen sie die Papiere ins Wasser unter den Docks.",al={"captain-dokumente","jene papiere","dokumente aus theramore"}},{q="Warum will Nazeer die Dokumente?",a="Nazeer Bloodpike glaubt, die Papiere enthielten Informationen über Theramores Verbindungen zur Allianz und dieses Wissen sei für die Sicherheit der Horde wichtig.",al={"warum braucht nazeer sie","wozu dienen die papiere","horden-dokumente"}},{q="Wo wurden die Dokumente gefunden?",a="Die Dokumente waren in einer Fußkiste unter den Docks der Insel Theramore versiegelt.",al={"wo sind die papiere","captains fußkiste","papiere von theramores docks"}},{q="Wer schickte die Spione nach Theramore?",a="Die Spione kamen aus Brackenwall. Nazeer Bloodpike leitet die Bemühungen, die Papiere zu bergen.",al={"wer schickte sie","spione aus brackenwall","theramore-spione"}},{q="Was steht in den Papieren?",a="Die Papiere sind in Common geschrieben, und Nazeer behält ihren Inhalt für sich. Was genau sie über Theramores Verbindungen zur Allianz aussagen, bleibt unbekannt.",al={"was steht in den dokumenten","inhalt der captain-papiere","beziehungen zwischen theramore und der allianz"}}},fp="19,164,17.278.0,33.164.0,35.150.0,31.78.0,32.99.0,23.152.0"}
P.entries["item:cask-of-merlot"] = {n="Fässlein mit Merlot",s="In Sturmwind hilft das Fässlein mit Merlot, Seenhain zu versorgen, während Schwarzfelsorcs dessen Handelswege abschneiden.",h="In Sturmwind hilft das Fässlein mit Merlot, Seenhain zu versorgen, während Schwarzfelsorcs dessen Handelswege...",kw={"barkeeper daniels","fässlein mit merlot","dry times","galina winery","seenhain","merlot","roberto pupellyverbos","sturmwind"},ang={["faction:Alliance"]="Für die Allianz zeigt das Beschaffen des Fässleins die Kluft zwischen Sturmwinds sicherem Kanalviertel und den belagerten Ortschaften im Rotkammgebirge."},sec={{t="Ein Geschmack der Hauptstadt",b="Die Galina Winery stellt ihren Merlot im Herzen des Königreichs her. Ihre Keller liegen an den Kanälen bei Sturmwinds Handelsdistrikt. Winzer Roberto Pupellyverbos pflegt die Jahrgänge für den erlesenen Geschmack der Hauptstadt. Anders als Fusel aus dem Dämmerwald oder Spirituosen aus Elwynn zeugt dieser Wein von der Handwerkskunst menschlicher Winzer innerhalb der Stadtmauern."},{t="Nachschub für Seenhain",b="Als der Schwarzfelsklan ins Rotkammgebirge einfiel, brachen die Versorgungswege zusammen, und Seenhain erhielt seine üblichen Händlerlieferungen nicht mehr. Die Einheimischen blieben durstig und verängstigt zurück. Deshalb schickt Barkeeper Daniels bereitwillige Kuriere durch das Königreich, um die Keller seiner Schenke wieder aufzufüllen. Am Immerruhsee können Verteidiger und Flüchtlinge ihre Rationen mit dem milden Wein aus dem Fässlein hinunterspülen."}},faq={{q="Wo kann ich ein Fässlein mit Merlot finden?",a="Roberto Pupellyverbos verkauft das Fässlein mit Merlot in der Galina Winery. Das Weingut liegt an den Kanälen am Rande von Sturmwinds Handelsdistrikt.",al={"fässlein mit merlot fundort","wo merlot kaufen","wer verkauft fässlein mit merlot","weinhändler sturmwind"}},{q="Warum braucht Barkeeper Daniels diesen Wein?",a="Die Invasion der Schwarzfelsorcs im Rotkammgebirge hat Seenhain von seinen regelmäßigen Lieferungen abgeschnitten, und Barkeeper Daniels geht der Alkohol aus. Er schickt Abenteurer durch den Süden Azeroths, um regionale Spezialitäten zu finden und seine Gäste zufriedenzustellen.",al={"dry times quest merlot","warum will daniels wein","merlot für seenhain zweck"}},{q="Welche anderen Getränke werden neben dem Merlot gesammelt?",a="Daniels bittet außerdem um einen Schlauch mit süßem Rum aus Goldhain, eine Flasche mit Fusel aus Dunkelhain und ein Fass Thunderbrew Lager von Schnapsbart Donnerbräu in den Hügeln von Westfall.",al={"dry times getränke","daniels alkoholliste","andere alkoholika dry times"}},{q="Ist die Galina Winery in Gefahr?",a="Die Galina Winery liegt sicher hinter Sturmwinds steinernen Wällen. Banditen und Überfälle der Orcs plagen entlegene Gebiete wie Westfall und das Rotkammgebirge, während Handel und Weinherstellung im Kanalviertel der Hauptstadt weitergehen.",al={"galina winery hintergrund","weingut in sturmwind"}}},fx={e882dee4={q="Was ist das Fässlein mit Merlot?",a="Es ist ein beträchtlicher Behälter mit feinem Rotwein, der in Sturmwind produziert und verkauft wird. Während gewöhnliche Bürger ihn als Grundnahrungsmittel genießen, schätzen entlegene Siedlungen, die in Aufruhr geraten sind, solche Massen an Spirituosen, um ihre müden Tavernen aufgestockt und die lokale Stimmung hoch zu halten.",al={"was ist das fässlein mit merlot","fässlein mit merlot gegenstand","merlot fässlein was ist das"}},["33c97a45"]={q="Woher stammt das Fässlein mit Merlot und wer hat es hergestellt?",a="Das Fass stammt aus der Galina-Kellerei, die entlang der Canals am Rande des Handelsdistrikts in Sturmwind liegt. Es wird von Roberto Pupellyverbos zubereitet und verkauft, der Stadtbewohner und reisende Händler mit den begehrten Jahrgängen der Kellerei versorgt.",al={"fässlein mit merlot ursprung","wer macht den merlot","woher stammt das fässlein mit merlot"}}},fp="14,93,22.330.0,20.362.0,34.153.0,40.233.0,53.179.0,31.210.0"}
P.entries["item:cask-of-scalder"] = {n="Fässlein mit Gerstenbräu",s="In Sturmwind ist ein Fässlein Gerstenbräu-Scalder für einen alten Bekannten bestimmt. Das feurige Bier vermittelt einen Gefallen unter Zwergen.",h="In Sturmwind ist ein Fässlein Gerstenbräu-Scalder für einen alten Bekannten bestimmt.",kw={"bier","gerstenbräu","fässlein mit gerstenbräu","der zwergendistrikt","furen langbart","schildschmied","sturmwind"},ang={["class:Warrior"]="Als Krieger könnt Ihr Furen Langbarts berühmte Schmiedekunst in Anspruch nehmen, indem Ihr ihm ein Fässlein edles Bier bringt. Für verlässlichen Schutz ist dies ein unverzichtbares Übergangsritual.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass ein frisches Fässlein von Gerstenbräus bestem Bier einen Handel besiegeln oder eine alte Verpflichtung begleichen kann."},sec={{t="Ein zwergischer Handel",b="Reisende, die sich im Rethban Gauntlet bewährt haben, bringen Gerstenbräu-Scalder zu Furen Langbart im Zwergendistrikt von Sturmwind. Furen ist ein kunstfertiger Schildschmied und findet trockene Zeiten unerträglich. Das Fässlein gibt Yorus Barleybrew die Möglichkeit, einen alten Gefallen einzufordern und sich edle zwergische Handwerkskunst zu sichern."}},faq={{q="Was steckt im Fässlein mit Gerstenbräu?",a="Das Fässlein enthält Gerstenbräu-Scalder, ein feuriges Gebräu der Familie Gerstenbräu. Zwerge schätzen seinen kräftigen Geschmack und seine wohlige Wärme.",al={"welches getränk ist darin","scalder bier","gerstenbräu-scalder"}},{q="Für wen ist dieses Fässlein bestimmt?",a="Das Fässlein ist für Furen Langbart bestimmt, einen meisterhaften zwergischen Schildschmied im Zwergendistrikt von Sturmwind.",al={"wer bekommt das fässlein","wohin das fässlein bringen","scalder empfänger"}},{q="Warum wird dieses Fässlein zu Furen Langbart gebracht?",a="Furen schuldet Yorus Barleybrew einen Gefallen. Das Fässlein stillt Furens Durst in den von ihm so genannten trockenen Zeiten und bewegt ihn dazu, dem Überbringer einen robusten, außergewöhnlichen Schild zu schmieden.",al={"warum furen scalder will","schildschmied gefallen","zweck des fässleins"}}},fx={df3534f2={q="Was ist das Fässlein mit Gerstenbräu?",a="Das Fässlein mit Gerstenbräu ist ein Holzfass gefüllt mit Gerstenbräu-Scalder, einem kräftigen Gebräu, das von der Familie Gerstenbräu hergestellt wird. Yorus Barleybrew vertraut es Euch als Geschenk und Einführung für seinen zwergischen Freund in Sturmwind, den Schildschmied Furen Langbart, an.",al={"was ist das fässlein mit gerstenbräu","fässlein mit gerstenbräu","was ist gerstenbräu-scalder"}},["1fd358f8"]={q="Woher stammt das Fässlein mit Gerstenbräu und wer hat es hergestellt?",a="Das Fass wird von Yorus Barleybrew im Rotkammgebirge nach Eurem Triumph durch The Rethban Gauntlet bereitgestellt. Dieses unverwechselbare Getränk, das vom bekannten Gerstenbräu-Clan gebraut wurde, wird als herzlicher Gefallen präsentiert, der würdig ist, ein meisterhaft gefertigtes zwergisches Schild zu sichern.",al={"wer hat das fässlein mit gerstenbräu hergestellt","fässlein mit gerstenbräu ursprung","woher kam das fässlein mit gerstenbräu"}}},fp="15,123,17.311.0,35.132.0,30.99.0,52.170.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="Fässlein mit Schimmerstarkbier",s="In Dun Moroghs kalten Höhen ist das Fässlein mit Schimmerstarkbier für die östlichen Berge bestimmt. Rejold Gerstenbräu hat das kräftige neue Bier gebraut, und sein Bruder schickt ein Fässlein als Geschenk für befreundete Zwergengebirgsjäger nach Osten.",h="In Dun Moroghs kalten Höhen ist das Fässlein mit Schimmerstarkbier für die östlichen Berge bestimmt.",kw={"fässlein mit schimmerstarkbier","dun morogh","kadrell","loch modan","rejold gerstenbräu","shimmer stout","thelsamar"},ang={["race:Dwarf"]="Als Zwerg wisst Ihr, dass das Teilen von edlem Bier zwischen den Patrouillen eine geschätzte Tradition ist. Sie verbindet die weit verstreuten Gebirgsjäger über die zerklüfteten Gipfel von Khaz Modan hinweg."},sec={{t="Eine belebende Lieferung",b="In Bräuhall von Rejold Gerstenbräu gebraut, erwarb sich Schimmerstarkbier rasch hohe Anerkennung unter den einheimischen Gästen und Gebirgsjägern, die den schneidenden Frösten von Dun Morogh trotzten. Beeindruckt vom Gebräu seines Bruders gab Gebirgsjäger Gerstenbräu ein Fässlein in Auftrag, das durch den östlichen Pass nach Loch Modan transportiert werden sollte. Zwerge schätzen starke Getränke sowohl als gesellschaftliches Grundnahrungsmittel wie auch als praktischen Schutz gegen die brennende Kälte der Berge, und das Teilen eines frischen Jahrgangs mit weit entfernten Kameraden ist eine altehrwürdige militärische Tradition."},{t="Ein zwergischer Muntermacher",b="Während seiner Wache in Thelsamar öffnet Gebirgsjäger Kadrell das Fässlein und kostet das Gebräu. Shimmer Stout macht seinem Namen alle Ehre: Ein Schluck soll die Glieder leicht machen und einem Soldaten das Gefühl geben, er könne fliegen. Ein zwergischer Späher auf einer langen, einsamen Patrouille entlang der Höhenstraßen dürfte einen solch belebenden Trunk begrüßen."}},faq={{q="Was ist Shimmer Stout?",a="Rejold Gerstenbräu braut Shimmer Stout in Dun Moroghs kalten Höhen. Seine kräftige Wirkung ist dafür bekannt, den Körper zu beleben und die Kälte fernzuhalten.",al={"was ist shimmer stout","shimmer stout hintergrundgeschichte","wer hat shimmer stout gebraut"}},{q="An wen wird das Fässlein geschickt?",a="Das Fässlein ist für Gebirgsjäger Kadrell bestimmt, einen Wächter, der an der Straße durch Thelsamar in Loch Modan stationiert ist.",al={"wer bekommt das fässlein","wohin geht das fässlein","empfänger des fässleins"}},{q="Warum Bier über die Berge schicken?",a="Zwergengebirgsjäger teilen oft edle Gebräue mit Kameraden auf fernen Patrouillen. Nachdem sein Bruder Rejold Gerstenbräus neue Schöpfung gekostet hat, möchte er, dass Kadrell sie probiert.",al={"warum die lieferung","warum bier liefern","warum an kadrell schicken"}},{q="Welche Wirkung hat Shimmer Stout auf den Trinker?",a="Shimmer Stout ist überraschend stark. Nachdem Gebirgsjäger Kadrell davon gekostet hat, sagt er, es lasse seinen Kopf schwirren, mache seine Glieder leicht und gebe ihm das Gefühl, fliegen zu können.",al={"wie stark ist shimmer stout","shimmer stout wirkung"}}},fx={aa5543f0={q="Woher stammt das Fässlein mit Schimmerstarkbier und wer hat es hergestellt?",a="Dieses wirkmächtige Gebräu wurde von Rejold Gerstenbräu in Bräuhall in Dun Morogh gebraut. Sein Bruder, Gebirgsjäger Gerstenbräu, war von dem Gebräu so beeindruckt, dass er dieses Fässlein verpackte, um es außerhalb ihrer Heimat zu teilen, und einen Abenteurer anheuerte, es den ganzen Weg bis nach Loch Modan zu tragen.",al={"wer braute shimmer stout","woher kommt shimmer stout","brauer von fässlein mit schimmerstarkbier"}},["3b29018e"]={q="Warum will jemand das Fässlein mit Schimmerstarkbier haben?",a="Gebirgsjäger Gerstenbräu liebt das neue Rezept seines Bruders und möchte, dass ein anderer Wachmann, Gebirgsjäger Kadrell, die Charge probiert. Kadrell patrouilliert auf den frostigen Straßen um Thelsamar, und ein kräftiges Zwergenbier, das das Blut wärmt, die Glieder leicht macht und den Kopf verdreht, sorgt für gute Stimmung während langer Wachen.",al={"warum shimmer stout verschicken","wer will das fässlein mit schimmerstarkbier","warum will kadrell shimmer stout"}}},fp="21,209,19.430.0,20.316.0,22.150.0,30.108.0,34.162.0,51.167.0"}
P.entries["item:catelyn-s-blade"] = {n="Catelyn's Blade",s="Nahe Beutebucht ist Catelyn's Blade ein Messer mit einer Geschichte unter den Trollen Schlingendorntals. Catelyn braucht es von den Blutsegelbukaniere zurück.",h="Nahe Beutebucht ist Catelyn's Blade ein Messer mit einer Geschichte unter den Trollen Schlingendorntals.",kw={"altar of the tides","ansirem runeweaver","blutsegelbukaniere","catelyn die klinge","catelyn's blade","pretty boy duncan","stein der gezeiten","trollrelikt"},ang={["class:Mage"]="Ansirem Runeweaver ist ein Magier, und Catelyn floh vor dem Bücherleben und den steifnackigen Magiern, für die ihr Vater sie bestimmt hatte."},sec={{t="Das Messer einer Tochter",b="Catelyn's Blade fehlt seiner Besitzerin, Catelyn der Klinge, im Schlingendorntal. Sie sagt, „Pretty Boy“ Duncan von den Blutsegelbukaniere habe es genommen, nachdem er sie bewusstlos geschlagen hatte. Ihr Vater, Ansirem Runeweaver, ließ nach ihr schicken, und sie bittet Euch, das Messer von Duncan zurückzuholen."},{t="Am versunkenen Altar",b="Das Messer ist ein Trollrelikt, das Ansirem Runeweaver im Schlingendorntal fand und seiner Tochter schenkte. Sobald Catelyn es zurückhat, leiht sie es Euch für den Altar am Finsteren Riff. Dort kann die Klinge den Altar of the Tides zerstören und Gazban sowie den Stein der Gezeiten hervorlocken. Baron Revilgaz will den Stein für seine Sammlung, und Catelyn erwartet ihr Messer zurück."}},faq={{q="Wem gehört Catelyn's Blade?",a="Catelyn die Klinge gehört das Messer. Ihr Vater, Ansirem Runeweaver, schenkte es ihr.",al={"besitzer von catelyn's blade","wem gehört das messer"}},{q="Wie kam Duncan an das Messer?",a="Catelyn sagt, „Pretty Boy“ Duncan habe sie bewusstlos geschlagen und das Messer genommen.",al={"duncan stahl die klinge","wie verlor catelyn das messer"}},{q="Wer ist Catelyn?",a="Catelyn die Klinge ist Ansirem Runeweavers Tochter. Sie verließ das gelehrte Leben ihres Vaters, um Piratin zu werden.",al={"catelyns hintergrund","wer ist das klingenmädchen"}},{q="Wofür wird die Klinge verwendet?",a="Catelyn leiht Euch das Messer, damit Ihr den Altar of the Tides am Finsteren Riff zerstören könnt.",al={"messer für altar","zweck der klinge"}},{q="Wo befindet sich der Altar?",a="Der Altar of the Tides liegt in den Ruinen einer versunkenen Trollstadt am Finsteren Riff vor der Küste Schlingendorntals.",al={"altar am finsteren riff","ort des versunkenen altars"}},{q="Warum will Baron Revilgaz den Stein der Gezeiten?",a="Baron Revilgaz will den Stein der Gezeiten für seine Sammlung uralter Trollartefakte.",al={"revilgaz und der stein","warum den stein sammeln"}}},fp="15,140,18.285.0,19.375.0,25.81.0,29.76.0,15.108.0,27.83.1,19.113.0,52.90.1"}
P.entries["item:cats-eye-emerald"] = {n="Katzenaugensmaragd",s="In der Felsadermine wird der Katzenaugensmaragd bewacht, während Werftmeister Dizzywig einen Käufer sucht. Der faustgroße Edelstein hat von den Docks in Ratschet aus seine Aufmerksamkeit erregt.",h="In der Felsadermine wird der Katzenaugensmaragd bewacht, während Werftmeister Dizzywig einen Käufer sucht.",kw={"boss copperplug","felsadermine","katzenaugensmaragd","smaragd","ratschet","das schlickermoor","venture company","wharfmaster dizzywig"},ang={["class:Rogue"]="Als Schurke bietet sich Euch eine günstige Gelegenheit, einen gewaltigen Edelstein direkt unter den Nasen korrupter Zuchtmeister der Venture Company zu stehlen.",["profession:Mining"]="Als Bergarbeiter ist der Fund eines makellosen, faustgroßen Edelsteins in einer industriellen Ausgrabung wie der Felsadermine der Glückstreffer, von dem jeder Bergarbeiter träumt."},sec={{t="Ein faustgroßes Vermögen",b="Arbeiter der Venture Company fanden einen gewaltigen Smaragd in der Felsadermine, nordöstlich des Schlickermoors. Die Nachricht verbreitete sich rasch in der Savanne. Im Land der Goblins bleiben seltene Edelsteine nicht lange geheim. Handelsklatsch trug die Kunde von den Docks in Ratschet bis nach Beutebucht, wo Werftmeister Dizzywig von dem kostbaren Fund erfuhr. Er begann Pläne zu schmieden, um ihn auf den freien Markt in Undermine zu bringen."},{t="Im Besitz der Gesellschaft",b="Die Führung der Venture Company hält den Smaragd in der Mine unter strenger Bewachung. Aufseher, Vollstrecker und leitende Mitarbeiter wie Boss Copperplug verteidigen ihn gegen rivalisierende Kartelle und Glücksritter. Dizzywig hat denen, die ihm helfen, den Edelstein zu sichern, einen Anteil von fünfzig Prozent versprochen."}},faq={{q="Was ist der Katzenaugensmaragd?",a="Der Katzenaugensmaragd ist ein ungewöhnlich großer, etwa faustgroßer Smaragd, den Bergleute im nördlichen Brachland fanden. Seine Reinheit und Größe machen ihn auf dem Weltmarkt ein Vermögen wert.",al={"was ist der katzenaugensmaragd","katzenaugenedelstein","was für ein edelstein ist das"}},{q="Wo wurde der Edelstein entdeckt?",a="Bergleute der Venture Company fanden den Edelstein in der Felsadermine, nordöstlich des Schlickermoors im nördlichen Brachland.",al={"wo wurde er gefunden","fundort des edelsteins","felsadermine smaragd"}},{q="Wer will den Smaragd in Ratschet?",a="Werftmeister Dizzywig beaufsichtigt Schifffahrt und Fracht an den Docks von Ratschet. Er will den Stein über Handelskontakte in Undermine an wohlhabende Käufer vermitteln.",al={"wer kauft den smaragd","dizzywig smaragd","wer gibt die quest für den smaragd"}},{q="Wer verwahrt den Stein in der Mine?",a="Hochrangige Aufseher der Venture Company verwahren den Smaragd in der Felsadermine. Einer der Aufseher oder Vollstrecker der Venture Co. trägt ihn bei sich.",al={"wer lässt den smaragd fallen","wer hat den katzenaugensmaragd","wo findet man den katzenaugensmaragd"}}},fx={["24f13ef4"]={q="Woher kommt der Katzenaugensmaragd?",a="Der Katzenaugensmaragd ist ein natürlicher, faustgroßer Edelstein, der tief in der Felsadermine, einer Ausgrabungsstätte der Venture Company nordöstlich des Schlickermoors im Brachland, ausgegraben wurde. Er ist kein von einem Handwerker geschmiedetes oder geschliffenes Artefakt, sondern wurde kürzlich von einem der glücklicheren Bergleute der Goblin-Firma aus der Erde geholt.",al={"ursprung von katzenaugensmaragd","wo wurde der katzenaugensmaragd gefunden","wer hat den katzenaugensmaragd hergestellt"}}},fp="16,158,20.372.0,18.275.0,29.184.0,29.115.0,33.145.0,41.135.0"}
P.entries["item:cenarion-lunardust"] = {n="Lunarstaub des Cenarius",s="Turak Runentotem gibt jungen Taurendruiden auf Donnerfels Lunarstaub des Cenarius. An einem uralten Moonkin Stone zwischen Mulgore und dem Brachland erwecken sie damit Lunaclaw.",h="Turak Runentotem gibt jungen Taurendruiden auf Donnerfels Lunarstaub des Cenarius.",kw={"body and heart","lunarstaub des cenarius","druide der klaue","lunaclaw","lunarstaub","moonkin stone","turak runentotem"},ang={["class:Druid"]="Als Taurendruide verwendet Ihr diesen Staub im Übergangsritus, der den Weg zur Verwandlung in einen Bären eröffnet.",["race:Tauren"]="Als Tauren erhaltet Ihr den Staub als junger Shu'halo und vertieft damit Eure Verbindung zu den Lehren des Zirkels des Cenarius, zur Natur und zu Kalimdors wilden Geistern."},sec={{t="Ein Ritus von Body and Heart",b="Lunarstaub des Cenarius trägt den Segen des Zirkels des Cenarius für Druiden, die bereit sind, sich den Druids of the Claw anzuschließen. Am Moonkin Stone westlich von Camp Taurajo ruft der Staub Lunaclaw herbei, eine heilige Bestie, die jeden Eingeweihten prüfen muss. Die Prüfung misst Stärke und Entschlossenheit. Indem er sich ihr stellt, lernt ein junger Druide die Stärke von Körper und Herz kennen, die nötig ist, um Bärengestalt anzunehmen."}},faq={{q="Wofür wird Lunarstaub des Cenarius verwendet?",a="Streut Lunarstaub des Cenarius über den Moonkin Stone in den Hügeln zwischen Mulgore und dem Brachland, westlich von Camp Taurajo. Der Staub beschwört Lunaclaw, den Eingeweihte besiegen müssen, um ihre Stärke zu beweisen.",al={"was bewirkt lunarstaub","wie lunarstaub des cenarius verwenden","zweck von lunarstaub"}},{q="Wer stellt den Lunarstaub des Cenarius bereit?",a="Turak Runentotem, der Druidenlehrer auf der Anhöhe der Ältesten in Donnerfels, gibt den Staub Taurendruiden, die sich der Prüfung zur Bärengestalt stellen.",al={"wer gibt lunarstaub","wo lunarstaub des cenarius erhalten","turak runentotem staub"}},{q="Was geschieht, wenn Ihr Euren Lunarstaub des Cenarius verliert?",a="Wenn Ihr den Staub verliert oder gegen Lunaclaw scheitert, kehrt zu Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels zurück, um einen weiteren Beutel zu erhalten.",al={"lunarstaub verloren","mehr lunarstaub benötigt","wo erneut lunarstaub erhalten"}},{q="Warum muss sich ein Druide Lunaclaw stellen?",a="Ein Druide stellt sich Lunaclaw, dem Beschützer des Steins, um körperliche Stärke und innere Entschlossenheit zu prüfen. Indem er die Bestie besiegt, lernt ein angehender Druide der Klaue die Lektionen von Körper und Herz, um die Macht des Great Bear Spirit einzusetzen.",al={"warum gegen lunaclaw kämpfen","wer ist lunaclaw","zweck von lunaclaw"}}},fx={ca885fb9={q="Was ist Lunarstaub des Cenarius?",a="Lunarstaub des Cenarius ist ein heiliges Pulver, das von den Druiden des Cenarius hergestellt und nur Initianden anvertraut wird, die ihre Hingabe bewiesen haben. Wenn es auf den uralten Mondkinstein nahe der Grenze zwischen dem Brachland und Mulgore gestreut wird, beschwört die Magie des Staubes Lunaklaue herauf, um zu prüfen, ob ein junger Druide über die Stärke von Körper und Geist verfügt, die erforderlich ist, um den Pfad des Druid of the Claw zu beschreiten.",al={"was ist lunarstaub","lore von lunarstaub des cenarius","staub des cenarius"}},d52557a0={q="Warum will jemand den Lunarstaub des Cenarius haben?",a="Nur aufstrebende Druiden suchen diesen Staub, da er der Schlüssel zur Beschwörung von Lunaklaue am Mondkinstein ist. Ohne ihn erscheint der Wächter nicht, was den Initianden daran hindert, sich der Prüfung zu stellen und die spirituelle Stärke zu erlangen, die notwendig ist, um ein wahrer Druid of the Claw zu werden.",al={"warum lunarstaub benötigen","wer will lunarstaub des cenarius","wozu lunarstaub verwenden"}}},fp="18,171,24.360.0,36.197.0,36.138.0,49.126.0,31.232.0"}
P.entries["item:cenarion-moondust"] = {n="Mondstaub des Cenarius",s="Am Moonkin Stone östlich von Auberdine beschwört Mondstaub des Cenarius Lunaclaw. Nachtelfendruiden nutzen ihn bei ihrer letzten Prüfung zum Druiden der Klaue.",h="Am Moonkin Stone östlich von Auberdine beschwört Mondstaub des Cenarius Lunaclaw.",kw={"auberdine","body and heart","mondstaub des cenarius","druide der klaue","lunaclaw","mathrengyl bärenfährte","mondstaub","moonkin stone"},ang={["class:Druid"]="Als Nachtelfendruide beginnt Ihr mit der Verwendung von Mondstaub des Cenarius den letzten Schritt, um ein Druide der Klaue zu werden und die Bärengestalt zu meistern.",["race:NightElf"]="Als Nachtelf begegnet Ihr im Staub den uralten Traditionen des Zirkels des Cenarius. Er verbindet Naturverehrung mit einem Mondritual, um die Tiere von Dunkelküste zu ehren."},sec={{t="Ein Ritus der Klaue",b="Mathrengyl Bärenfährte gibt jungen Druiden in Darnassus Mondstaub des Cenarius für ihre letzte Prüfung von Herz und Körper. Um Lunaclaw gegenüberzutreten, reist ein Initiand zu den Mondkinhöhlen östlich von Auberdine in Dunkelküste. Verstreut das Pulver auf dem uralten Moonkin Stone, und Lunaclaw erscheint, um den Druiden im Kampf zu prüfen. Durch die Prüfung erlangt der Initiand die beständige Stärke, die nötig ist, um die Bärengestalt zu kanalisieren."}},faq={{q="Wofür wird Mondstaub des Cenarius verwendet?",a="Nachtelfische Druideninitianden verstreuen Mondstaub des Cenarius auf dem Moonkin Stone in Dunkelküste. Er beschwört Lunaclaw und prüft ihre Stärke und Entschlossenheit auf ihrem Weg zur Bärengestalt.",al={"mondstaub verwenden","was bewirkt mondstaub des cenarius","zweck von mondstaub des cenarius"}},{q="Wo verwende ich den Mondstaub des Cenarius?",a="Verstreut Mondstaub des Cenarius auf dem Moonkin Stone in einer Mondkinhöhle in den Hügeln direkt östlich von Auberdine in Dunkelküste.",al={"wo mondstaub verwenden","moonkin stone fundort","wo ist lunaclaws stein"}},{q="Wer stellt Mondstaub des Cenarius bereit?",a="Mathrengyl Bärenfährte, ein Druidenlehrer in der Enklave des Cenarius in Darnassus, gibt Mondstaub des Cenarius an Initianden, die zur Prüfung von Körper und Herz bereit sind.",al={"wer gibt mondstaub","wo mondstaub des cenarius erhalten","mathrengyl mondstaub"}},{q="Was geschieht, wenn ich den Mondstaub verliere?",a="Wenn Ihr den Mondstaub verliert oder bei einem gescheiterten Versuch gegen Lunaclaw verbraucht, kehrt nach Darnassus zurück und bittet Mathrengyl Bärenfährte, die Prüfung zu erneuern.",al={"mondstaub des cenarius verloren","mondstaub verloren","mondstaub zurückbekommen"}}},fx={d9963f3d={q="Was ist Mondstaub des Cenarius?",a="Mondstaub des Cenarius ist ein heiliges Pulver, das vom Zirkel des Cenarius an Nachtelf-Druiden verliehen wird, die den Mantel des Druid of the Claw anstreben. Er trägt den Segen der Wildnis und wird als rituelles Reagenz verwendet, um uralte Wächtergeister zu ehren und herbeizurufen.",al={"was ist mondstaub des cenarius","lore von mondstaub des cenarius","zweck von mondstaub"}},["34087882"]={q="Woher kommt der Mondstaub des Cenarius und wer hat ihn hergestellt?",a="Der Staub wird vom Zirkel des Cenarius in Darnassus zubereitet und aufbewahrt. Er wird speziell von Druidenlehrern wie Mathrengyl Bärenfährte an Initianden verliehen, die Ehrfurcht gezeigt und sich das Recht verdient haben, ihre heiligen Prüfungen abzulegen.",al={"wer hat mondstaub des cenarius hergestellt","ursprung von mondstaub des cenarius","woher kommt mondstaub"}},["1f04d9d3"]={q="Warum wird Mondstaub des Cenarius benötigt?",a="Der Mondstaub wird benötigt, um Lunaklaue zu erwecken, das uralte Biest, das den Mondkinstein in der Dunkelküste bewacht. Lunaklaue folgt nur der Herausforderung eines Initianden, der diesen heiligen Staub auf den Stein aufträgt, was es dem Druiden ermöglicht, seine Stärke von Körper und Geist zu beweisen.",al={"warum brauche ich mondstaub des cenarius","wozu mondstaub verwenden","was ist der zweck von mondstaub des cenarius"}}},fp="17,150,18.391.0,35.167.0,37.120.0,31.152.0,36.144.0"}
P.entries["item:centaur-bracers"] = {n="Zentaurenarmschienen",s="Im ganzen Brachland werden Zentaurenarmschienen gefallenen Kolkarkriegern abgenommen. Regthar Totenfurt sammelt sie westlich des Wegekreuzes als Beweis dafür, dass die Zentaurenräuber dezimiert wurden.",h="Im ganzen Brachland werden Zentaurenarmschienen gefallenen Kolkarkriegern abgenommen.",kw={"brachland","kopfgeld","armschienen","zentauren","das wegekreuz","deathgate","kolkar","regthar"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Versorgungswege der Karawanen zwischen Durotar, Mulgore und dem Wegekreuz zu schützen, wenn Ihr Kolkarplünderer niederstreckt.",["race:Tauren"]="Als Tauren wisst Ihr, dass Euer Volk seit Generationen brutale Übergriffe durch Zentaurenclans erduldet. Die Kolkar aus dem Brachland zu vertreiben, bringt Vergeltung und Sicherheit."},sec={{t="Ein raues Kopfgeld",b="Kolkarplünderer bedrohen den Einfluss der Horde im gesamten Brachland. Ihre gefallenen Krieger hinterlassen Armschienen aus Leder und Eisen als Beweis dafür, dass ein Plünderer auf den Handelsstraßen ausgeschaltet wurde. Regthar Totenfurt ist ein Orc-Späher, der auf den Anhöhen westlich des Wegekreuzes stationiert ist. Er bietet ein dauerhaftes Kopfgeld für diese Trophäen, um die Aggression des Stammes einzudämmen."}},faq={{q="Wer will diese Armschienen?",a="Regthar Totenfurt, ein Späher der Horde auf einer Anhöhe westlich des Wegekreuzes im Brachland, nimmt die Armschienen als Beweis dafür entgegen, dass Ihr Kolkarzentauren aus der örtlichen Plündertruppe ausgeschaltet habt.",al={"wer nimmt zentaurenarmschienen","regthar deathgate abgabe","wer kauft zentaurenarmschienen"}},{q="Welche Zentauren tragen diese Armschienen?",a="Kolkarkrieger tragen diese Armschienen, während sie durch die Oasen und Lager des nördlichen Brachlands streifen, darunter die Vergessenen Teiche und die Blühende Oase.",al={"wo armschienen farmen","kolkar armschienen beute","zentaurenarmschienen herkunft"}},{q="Warum lässt Regthar sie sammeln?",a="Regthar will die Zahl der Kolkar verringern, um das Gebiet der Horde zu schützen. Die Armschienen zeigen, dass Krieger die Plünderer getötet und nicht bloß vertrieben haben.",al={"warum armschienen sammeln","regthar deathgate beweggrund","zweck der zentaurenarmschienen"}}},fx={["2b8929fb"]={q="Was sind Zentaurenarmschienen?",a="Diese Armschienen sind Teile einer groben Rüstung, die von Zentaurenkriegern im gesamten Brachland getragen wird. Sie wurden den Armen erschlagener Kolkar-Plünderer entrissen und dienen der Horde als grimmiger physischer Beweis für den Erfolg eines Jägers beim Ausdünnen ihrer aggressiven Kriegerscharen.",al={"was sind zentaurenarmschienen","lore zu zentaurenarmschienen","was ist zentaurenarmschienen"}},e954048b={q="Woher kommen Zentaurenarmschienen?",a="Sie werden von den Zentaurenclans geschmiedet oder gefertigt, die die trockenen Ebenen von Kalimdor durchstreifen, insbesondere vom feindseligen Stamm der Kolkar. Krieger rüsten sie für die Schlacht als rudimentären Schutz gegen die Klingen, Pfeile und Klauen ihrer vielen Feinde aus.",al={"wer hat zentaurenarmschienen hergestellt","ursprung von zentaurenarmschienen","woher kommen zentaurenarmschienen"}}},fp="15,175,15.349.0,24.184.0,34.145.0,37.153.0"}
P.entries["item:centaur-ear"] = {n="Centaur Ear",s="Ein Zentaurenohr gilt in Desolace als Beweis für einen getöteten Zentauren. Horde und Allianz verlangen sie, um die Schwächung der Clans zu belegen.",h="Ein Zentaurenohr gilt in Desolace als Beweis für einen getöteten Zentauren.",kw={"allianz","zentaur","zentauren kopfgeld","zentaurenohr","corporal melkins","desolace","felgur zweischneid","horde","die nijelspitze"},ang={["faction:Alliance"]="An der Nijelspitze bezeichnet Corporal Melkins das Nehmen von Zentaurenohren als Dienst an der Allianz und als Schritt zum Frieden.",["faction:Horde"]="Für die Horde soll das Bringen von Ohren zu Felgur Zweischneid die Zentaurenclans schwächen und zeigen, welches Banner hinter dem Blutvergießen steht."},sec={{t="Eine düstere Bilanz",b="In Desolace werden Zentaurenohren für Horde und Allianz gesammelt. Felgur Zweischneid fordert Horde-Reisende auf, einen großen Vorrat zusammenzutragen, denn er glaubt, dass weniger Zentauren den Widerstand der Clans schwächen. An der Nijelspitze verlangt Corporal Melkins Ohren im Dienst der Allianz und ihrer Hoffnung auf Frieden. Beide Banner machen aus einem grausigen Zeichen ein Maß für ihren Kampf gegen die Zentauren."}},faq={{q="Warum sammeln sie Zentaurenohren?",a="Offiziere der Horde und der Allianz nutzen Zentaurenohren als Beweis für getötete Zentauren und als Maß für die beabsichtigte Schwächung der Clans.",al={"warum ohren","zweck von zentaurenohren","wozu dienen ohren"}},{q="Wer will Zentaurenohren für die Horde?",a="Felgur Zweischneid in Desolace bittet Horde-Reisende, ihm einen Vorrat an Zentaurenohren zu bringen.",al={"horde ohren beauftragter","was will felgur","wer ist felgur"}},{q="Wer will Zentaurenohren für die Allianz?",a="Corporal Melkins an der Nijelspitze bittet Reisende der Allianz, ihm Zentaurenohren zu bringen.",al={"allianz ohren npc","melkins ohren","nijel ohren"}},{q="Ist es den Clans wichtig, von welchen Zentauren die Ohren stammen?",a="Felgur Zweischneid sagt, die Horde könne in Desolace jeden Zentaurenclan jagen.",al={"welcher clan","beliebige zentaurenohren","clan ohren"}}},fp="11,137,12.366.0,33.112.0,37.85.0,40.84.0,46.68.0"}
P.entries["item:centipaar-insect-parts"] = {n="Centipaar Insect Parts",s="Centipaar Insect Parts werden von silithid im Giftigen Unterschlupf von Tanaris gesammelt. Alchimist Pestlezugg in Gadgetzan untersucht sie, um mehr über die Kreaturen zu erfahren, die die Wasserbecken der Gegend leeren.",h="Centipaar Insect Parts werden von silithid im Giftigen Unterschlupf von Tanaris gesammelt.",kw={"alchimist pestlezugg","centipaar","gadgetzan","insektenteile","der giftige unterschlupf","silithid","tanaris","wasserbecken"},sec={{t="Teile aus dem Unterschlupf",b="Die Centipaar-silithid im Giftigen Unterschlupf liefern Teile für Alchimist Pestlezuggs Untersuchung. Er untersucht sie in Gadgetzan, um herauszufinden, was diese Kreaturen sind."}},faq={{q="Was sind Centipaar Insect Parts?",a="Centipaar Insect Parts sind Teile, die von silithid im Giftigen Unterschlupf von Tanaris gesammelt werden, damit Alchimist Pestlezugg sie untersuchen kann.",al={"centipaar-teile","insektenteile","käferteile"}},{q="Wo bekomme ich Centipaar Insect Parts?",a="Die Centipaar-silithid im Giftigen Unterschlupf liefern die Teile, nach denen Alchimist Pestlezugg sucht.",al={"wo teile","centipaar-teile bekommen","teile aus dem giftigen unterschlupf"}},{q="Wer will diese Insektenteile?",a="Alchimist Pestlezugg in Gadgetzan möchte Centipaar Insect Parts, damit er die Kreaturen aus dem Giftigen Unterschlupf untersuchen kann.",al={"wer braucht teile","pestlezugg teile","alchimist sucht"}},{q="Warum werden die Käfer untersucht?",a="Die silithid leeren die Wasserbecken, die einst dort lagen, wo heute der Giftige Unterschlupf steht, und Pestlezugg will herausfinden, was sie sind.",al={"warum käfer","wasserbecken","silithid-untersuchung"}}},fp="22,190,19.165.0,32.117.0,38.82.0,29.111.0,36.131.0"}
P.entries["item:chains-of-hematus"] = {n="Ketten von Hematus",s="Die Ketten von Hematus sind Fesseln, die in der Lethlorklamm gefunden werden. Garek oder Gorn sucht neben den Fesseln von Blacklash auch nach ihnen im Ödland.",h="Die Ketten von Hematus sind Fesseln, die in der Lethlorklamm gefunden werden.",kw={"ödland","schwarzer drache","ketten von hematus","hematus","die lethlorklamm","runensteine","seal of the earth"},sec={{t="Ein gebrochenes Siegel",b="In der Lethlorklamm werden die Ketten von Hematus zurückgebracht, nachdem Hematus aus dem Seal of the Earth befreit wurde. Drei Runensteine von den Säulen der Schlucht öffnen das Siegel. Garek oder Gorn sucht neben den Fesseln von Blacklash auch nach den Ketten, sobald die beiden schwarzen Drachen getötet wurden."}},faq={{q="Was sind die Ketten von Hematus?",a="Die Ketten von Hematus sind Fesseln, die dem schwarzen Drachen Hematus in der Lethlorklamm abgenommen wurden.",al={"hematus ketten","ketten gegenstand","hematus fesseln"}},{q="Wo finde ich die Ketten von Hematus?",a="Hematus in der Lethlorklamm im Ödland trägt die Ketten von Hematus.",al={"wo ketten","ketten fundort","hematus gegenstand"}},{q="Warum werden die Ketten gesucht?",a="Garek oder Gorn bittet nach dem Töten der Drachen um die Ketten von Hematus und die Fesseln von Blacklash.",al={"warum ketten gesucht","wofür ketten","hematus ketten benötigt"}},{q="Wie wird Hematus befreit?",a="Die Runensteine von den Pillars of Diamond, Opal, and Amethyst werden in das Seal of the Earth eingesetzt und befreien Hematus und Blacklash.",al={"hematus befreien","seal of the earth","runensteine"}},{q="Wer will die Ketten?",a="Garek oder Gorn sucht nach den Ketten von Hematus, je nachdem, wer Euch zur Lethlorklamm geschickt hat.",al={"wer braucht ketten","garek ketten","gorn ketten"}}},fp="17,134,13.281.0,31.88.0,38.72.0,26.105.1,21.130.1,21.87.0"}
P.entries["item:charred-horn"] = {n="Verkohltes Horn",s="In Sturmwind benötigt Furen Langbart Verkohlte Hörner von jungen Schimären aus dem Steinkrallengebirge. Ihre Widerstandskraft gegen Flammen, stumpfe Gewalt und raue Elementarkräfte macht sie für robuste Rüstungen nützlich.",h="In Sturmwind benötigt Furen Langbart Verkohlte Hörner von jungen Schimären aus dem Steinkrallengebirge.",kw={"verkohltes horn","schimäre","fire hardened mail","furen langbart","steinkrallengebirge"},ang={["class:Warrior"]="Als Krieger könnt Ihr überall auf Kalimdor Verkohlte Hörner für Furen Langbart beschaffen. Er belohnt die gefährliche Reise mit einem maßgefertigten, feuergehärteten Kettenhemd.",["profession:Blacksmithing"]="Als Schmied könnt Ihr erkennen, wie die Hörner natürlich durch Flammen gehärtetes Material von Kalimdors Raubtieren nutzen, um Kettenglieder zu härten."},sec={{t="Ein seltener Schmiedebestandteil",b="Flügge und junge Schimären im Steinkrallengebirge liefern Verkohlte Hörner. Ihre Widerstandskraft gegen Flammen und stumpfe Gewalt macht sie für Furen Langbart nützlich, einen zwergischen Rüstungsschmied an seiner Schmiede in Sturmwind. Er benötigt zwölf Hörner, um ein feuergehärtetes Kettenhemd herzustellen.\n\nFuren kombiniert sie mit giftigen Spinnenzähnen aus dem Sumpfland, Phlogiston aus dem Kral der Klingenhauer und dem Galvanisierten Horn einer Schimärenmatriarchin. Die Verkohlten Hörner verstärken die Ringe und Platten des Kettenhemds mit hitzebehandeltem Material."}},faq={{q="Welche Kreaturen lassen Verkohlte Hörner fallen?",a="Flügge und junge Schimären im Steinkrallengebirge auf Kalimdor liefern Verkohlte Hörner.",al={"wo verkohltes horn bekommen","wer lässt verkohltes horn fallen","quelle für verkohltes horn"}},{q="Wer möchte diese Hörner in Sturmwind haben?",a="Furen Langbart, ein Rüstungsschmied in Sturmwind, möchte die Hörner haben. Er schmiedet daraus ein robustes Kettenbruststück für vielversprechende Krieger.",al={"wer verwendet verkohltes horn","verkohltes horn abgeben","furen langbart hörner"}},{q="Warum benötigt Furen so viele davon?",a="Furen benötigt zwölf Verkohlte Hörner, um genügend hitzebehandeltes Material zur Verstärkung der Ringe und Platten seines feuergehärteten Kettenhemds zu erhalten.",al={"warum zwölf verkohlte hörner","zweck von verkohltem horn"}},{q="Unterscheiden sie sich vom Galvanisierten Horn?",a="Ja. Verkohlte Hörner stammen von jüngeren Schimären im Steinkrallengebirge. Das Galvanisierte Horn ist eine einzelne Trophäe von einer Schimärenmatriarchin und weitaus seltener.",al={"galvanisiertes horn gegen verkohltes horn","unterschied zwischen hörnern"}}},fx={["785d7f85"]={q="Was ist ein Verkohltes Horn?",a="Ein Verkohltes Horn ist ein zähes, geschwärztes Horn, das von jungen Chimären geerntet wird, die die Gipfel des Steinkrallengebirges durchstreifen. Durch das raue Gebirgsklima und die elementare Natur der Bestien gehärtet, besitzen diese Hörner eine einzigartige Haltbarkeit, was sie zu einem begehrten Rohmaterial für spezialisierte Schmiedekunst macht.",al={"was ist verkohltes horn","lore zu verkohltes horn","über verkohltes horn"}}},fp="12,187,25.490.0,34.92.0,35.132.0,39.133.0,45.154.0"}
P.entries["item:chest-of-containment-coffers"] = {n="Truhe mit Verwahrungskästen",s="In Unterstadt halten Magier die Truhe mit Verwahrungskästen griffbereit. Ihre verzauberten Gefäße können instabile magische Kräfte festhalten.",h="In Unterstadt halten Magier die Truhe mit Verwahrungskästen griffbereit.",kw={"anastasia hirschbrunn","das apothekarium","arkane anomalie","verwahrungskasten","magieviertel","risswesen"},ang={["class:Mage"]="Als Magier könnt Ihr mit diesen Hilfsmitteln im Feld unberechenbare arkane Erscheinungen unter Kontrolle bringen und lebende Exemplare für Untersuchungen bewahren.",["race:Undead"]="Als Verlassene könnt Ihr mit diesen Kästen magische Anomalien nahe dem Apothekarium sicher verwahren und verhindern, dass ungeprüfte arkane Kräfte Eure Arbeit verderben."},sec={{t="Gefäße für das Unsichtbare",b="Arkane Kreaturen können durch Experimente oder plötzliche Risse zwischen den Ebenen entstehen. Gewöhnliche Käfige können Wesen aus Magie nicht festhalten. Die Truhe mit Verwahrungskästen enthält verzauberte Gefäße, die überwältigte Kreaturen lebendig binden. Ranghohe Ausbilder bewahren sie in ihrer Nähe auf, darunter Anastasia Hirschbrunn in Unterstadt und Jennea Haubitz in Sturmwind. Sie geben Initianden Kästen, um Anomalien zu untersuchen, bevor diese Kräfte ihre Umgebung aus dem Gleichgewicht bringen."},{t="Arkane Verwahrungsprotokolle",b="In Algernons Laden im Apothekarium traten unsichtbare Störungen auf. Ausbilder der Verlassenen entsandten Magier mit Kästen, um sie einzudämmen. Ein Magier macht ein Risswesen mit einer besonderen Schriftrolle sichtbar, schwächt es mit Zaubern und fängt es dann in einem Kasten aus der Truhe. Forscher der Verlassenen können die gefangenen Kreaturen gefahrlos sezieren und untersuchen. Sie wollen herausfinden, ob die Störungen zufällige Risse in den Ley-Linien oder gezielte arkane Angriffe waren."}},faq={{q="Was befindet sich in der Truhe mit Verwahrungskästen?",a="Die Truhe enthält leere, verzauberte Kästen. Magier nutzen sie bei gefährlichen Felduntersuchungen, um überwältigte magische Kreaturen wie Risswesen sicher zu verwahren.",al={"was gibt die truhe","inhalt der verwahrungskästen","truheninhalt"}},{q="Wo ist diese Truhe zu finden?",a="In Unterstadt steht die Truhe hinter Magierlehrerin Anastasia Hirschbrunn im Magieviertel. Eine gleichartige Truhe steht hinter Jennea Haubitz im Magiersanktum in Sturmwind.",al={"standort der truhe mit verwahrungskästen","wo ist die truhe mit verwahrungskästen","standort der kästetruhe"}},{q="Warum brauchen Magier diese Kästen anstelle gewöhnlicher Käfige?",a="Risswesen bestehen aus ungreifbarer arkaner Energie, die gewöhnliche Materialien nicht festhalten können. Verzauberte Kästen können diese Anomalien einfangen und stabilisieren.",al={"warum kästen verwenden","wozu dienen kästen","wie funktionieren kästen"}},{q="Was geschieht mit den Kästen, sobald sie gefüllt sind?",a="Ranghohe Ausbilder erhalten gefüllte Kästen zur Untersuchung. Forscher analysieren die gefangenen Kreaturen, um herauszufinden, ob eine Störung von einem zufälligen natürlichen Riss oder einem gezielten Angriff durch äußere Kräfte herrührt.",al={"was geschieht mit gefangenen risswesen","verwendung gefüllter verwahrungskästen","warum kreaturen einfangen"}}},fx={fa57c13a={q="Was ist die Truhe mit Verwahrungskästen?",a="Es ist eine schwere Vorratstruhe, die von Magierausbildern aufbewahrt wird, um Praktizierende auszustatten, die magische Anomalien untersuchen. Darin befindet sich ein Satz verzauberter Verwahrungskästen, die speziell konstruiert wurden, um unberechenbare, nicht-physische Wesen, die rein aus arkaner Energie bestehen, zu binden und festzuhalten.",al={"was ist die truhe mit verwahrungskästen","truhe mit verwahrungskästen","truhe mit kästen"}},c9b5ba3b={q="Warum möchte Anastasia Hirschbrunn, dass Ihr die Truhe mit Verwahrungskästen nehmt?",a="Anastasia Hirschbrunn hat unsichtbare magische Wesen in Algernons Alchemieladen im Apothekarium entdeckt. Gewöhnliche Fesseln können Kreaturen, die vollständig aus roher Magie gewebt sind, nicht berühren, daher stellt sie Euch diese Truhe mit speziell vorbereiteten Kästen zur Verfügung, um die Anomalien lebend für Studienzwecke zu fangen.",al={"warum die truhe mit verwahrungskästen nehmen","warum brauche ich verwahrungskästen","warum anastasia truhe mit kästen"}}},fp="28,132,22.427.0,28.429.1,48.153.0,30.177.0,56.145.0,49.207.0"}
P.entries["item:chief-sharptusk-thornmantle-s-head"] = {n="Häuptling Spitzhauer Dornenmantels Kopf",s="Häuptling Spitzhauer Dornenmantels Kopf besiegelt das Ende einer Bedrohung für die Hochwolkenebene. Der Anführer der Bristleback bedrohte die jungen Taurenkrieger, und sein Kopf wurde als Siegesbeweis aus den Tiefen der Dornrankenklamm geborgen.",h="Häuptling Spitzhauer Dornenmantels Kopf besiegelt das Ende einer Bedrohung für die Hochwolkenebene.",kw={"brambleblade","bristleback","kopf","mulgore","sharptusk","thornmantle","windfeather"},ang={["class:Hunter"]="Für Euch als Jäger ist Sharptusk eine Beute, die selbst jagen kann. Einen so klugen Feind aufzuspüren und anzugreifen, stellt Euer Können auf die Probe.",["race:Tauren"]="Für Euch als Tauren ist es ein wichtiger Schritt als junger Verteidiger, den Kopf eines mächtigen Feindes zu erbeuten. Es beweist, dass Ihr die Entschlossenheit und das Können besitzt, die neue Heimat Eures Volkes zu schützen."},sec={{t="Trophäe der Jagd",b="Die Bristleback-Stacheleber der Dornrankenklamm greifen die Stämme von Camp Narache an. Ihr Häuptling, Sharptusk Thornmantle, führt sie an. Die Tauren bewachen ihre Heimat in Mulgore mit Wachsamkeit und Stärke. Sharptusks Kopf beweist seinen Tod und warnt die überlebenden Stacheleberklans, sich von den Grenzen der Hochebene fernzuhalten."},{t="Eine Lektion der Jagd",b="Kriegerheldin Windfeather bittet junge Jäger und Stammesverteidiger, als Übergangsritus Sharptusks Kopf zurückzubringen. Ein Feind, der zurückschlagen und eine Kriegsschar anführen kann, stellt das Kampfgeschick eines jungen Kämpfers auf die Probe. Mit dem Vorzeigen des Kopfes besteht der Kämpfer diese Prüfung und macht sich einen Namen unter den Kriegern der Hochwolkenebene."}},faq={{q="Warum will Kriegerheldin Windfeather den Kopf von Sharptusk Thornmantle?",a="Kriegerheldin Windfeather will einen Beweis dafür, dass der Häuptling der Bristleback gefallen ist. Sharptusk kann keine Überfälle auf Camp Narache mehr befehligen, und der Kopf warnt die verbliebenen Stacheleber, dass ihre Angriffe auf entschlossene Gegenwehr treffen werden.",al={"warum seinen kopf nehmen","grund für sharptusks kopf","windfeathers bitte um den kopf"}},{q="Wer war Häuptling Sharptusk Thornmantle?",a="Häuptling Sharptusk Thornmantle führte die Bristleback-Stacheleber in der Dornrankenklamm am östlichen Rand der Hochwolkenebene an. Unter seinem Befehl bedrängten die Bristleback junge Taurenkrieger und griffen sie an.",al={"wer ist sharptusk","sharptusk thornmantle geschichte","stacheleberhäuptling mulgore"}},{q="Wo erlangt man diese Trophäe?",a="Ihr erbeutet den Kopf, indem Ihr Häuptling Sharptusk Thornmantle in seinem provisorischen Stammesdorf tief in der Dornrankenklamm östlich von Camp Narache tötet.",al={"wo ist der kopf zu finden","sharptusks kopf fundort"}}},fx={["27fbe344"]={q="Woher kommt Häuptling Spitzhauer Dornenmantels Kopf?",a="Diese grimmige Trophäe stammt direkt vom Häuptling der Borstennacken-Stacheleber, die in der Dornrankenklamm, östlich von Camp Narache, nisten. Spitzhauer Dornenmantel sammelte seine behelfsmäßige Siedlung gegen die Tauren der Hochwolkenebene, was die Braves dazu veranlasste, seinen abgetrennten Kopf als unwiderlegbaren Beweis dafür zu fordern, dass die Kriegsanstrengungen der Borstennacken gebrochen sind.",al={"ursprung von spitzhauer kopf","woher kommt der kopf von spitzhauer","wer hat spitzhauer kopf"}}},fp="34,219,18.315.0,20.306.0,66.221.0,36.198.0,30.144.0"}
P.entries["item:chok-sul-s-head"] = {n="Chok'suls Kopf",s="In Thelsamar belegt der Kopf, den Magistrat Bluntnose verlangt, Chok'suls Tod. Die örtlichen Zwergenbehörden haben ein Kopfgeld ausgesetzt, und er verlangt diesen Beweis, bevor er es auszahlt.",h="In Thelsamar belegt der Kopf, den Magistrat Bluntnose verlangt, Chok'suls Tod.",kw={"chok'sul","chok'suls kopf","loch modan","magistrat bluntnose","mo'grosh","oger","der steinwerkdamm","thelsamar"},ang={["race:Dwarf"]="Als Zwerg verringert Ihr mit einem Sieg über Chok'sul die Gefahr für Eisenschmiedes ländliche Siedlungen und schützt den Steinwerkdamm vor der Zerstörung."},sec={{t="Beweis für den Fall des Häuptlings",b="Oger aus der Festung Mo'grosh bedrohen die Siedlungen von Loch Modan. Sie greifen Thelsamar, Ausgrabungsstätten und den Steinwerkdamm an. Magistrat Bluntnose setzte ein Kopfgeld auf Chok'sul aus, den Grobian, der diese Angriffe vermutlich anführt.\n\nIn den nordöstlichen Hügeln herrscht Aufruhr, weshalb der Magistrat einen Beweis verlangt, bevor er Gemeindegelder freigibt. Chok'suls abgetrennter Kopf gibt dem Zwergenrat die nötige Gewissheit, um den Kopfgeldauftrag als erfüllt anzusehen."}},faq={{q="Wer war Chok'sul?",a="Chok'sul war ein Ogerhäuptling in der Festung Mo'grosh im Nordosten von Loch Modan. Die Zwergenbeamten glauben, dass er Überfälle auf Thelsamar, den Steinwerkdamm und nahe gelegene Ausgrabungsstätten anführte.",al={"wer ist choksul","choksul hintergrundgeschichte","chok'sul identität"}},{q="Warum will Magistrat Bluntnose den Kopf?",a="Magistrat Bluntnose setzte öffentlich ein Kopfgeld auf Chok'suls Tod aus, ganz gleich, wie er herbeigeführt wird. Die Ogerüberfälle haben der Region zugesetzt, weshalb er einen eindeutigen Beweis für den Tod des Häuptlings verlangt, bevor er aus Thelsamars Kassen zahlt.",al={"warum will bluntnose den kopf","choksuls kopf zweck","wer will choksuls kopf"}},{q="Wo war Chok'sul tätig?",a="Chok'sul führte seine Kriegerschar von der Festung Mo'grosh aus an, in den zerklüfteten Hügeln im Nordosten von Loch Modan.",al={"wo ist choksul","festung mo'grosh lage","choksul aufenthaltsort"}},{q="Welche Bedrohung stellte Chok'sul für die Region dar?",a="Man glaubte, dass Chok'sul Angriffe auf Thelsamar und nahe gelegene Bauwerke und Anlagen der Zwerge anführte, darunter den Steinwerkdamm und örtliche Ausgrabungsstätten.",al={"warum wird choksul gesucht","was hat choksul getan"}}},fx={["8aed7d95"]={q="Woher kommt Chok'suls Kopf?",a="Diese grimmige Trophäe stammt direkt von dem Oger Chok'sul in der Festung Mo'grosh, die in der nordöstlichen Wildnis von Loch Modan liegt. Es ist kein Artefakt oder gefertigter Gegenstand, sondern der abgetrennte Kopf des Oger-Kriegsherrn selbst, der von Abenteurern beansprucht wurde, die das offizielle Kopfgeld der Stadt Thelsamar erfüllen wollten.",al={"ursprung von chok'suls kopf","woher kommt chok'suls kopf","wer hat chok'suls kopf hergestellt"}}},fp="15,171,29.434.0,17.190.0,44.204.0,27.97.0,45.137.0"}
P.entries["item:chucky-s-huge-ring"] = {n="Chuckys gewaltiger Ring",s="In den Ruinen von Aboraz besitzt Chucky „Ten Thumbs“ einen Ring, den Sea Wolf MacKinley haben will. Er ist einer von drei Wertgegenständen, die wegen unbezahlter Schulden gesucht werden.",h="In den Ruinen von Aboraz besitzt Chucky „Ten Thumbs“ einen Ring, den Sea Wolf MacKinley haben will.",kw={"chucky","chuckys gewaltiger ring","ruinen von aboraz","sea wolf mackinley","schlingendorntal","ten thumbs","voodoo-schulden"},sec={{t="Eine Schuld im Dschungel",b="MacKinleys Liste führt Euch zu Chucky „Ten Thumbs“ zwischen den Dschungelruinen des Schlingendorntals. Der Pirat sagt, Chucky und zwei weitere Schuldner seien verschwunden, nachdem ihre Schulden unbezahlt blieben. Er will, dass Ihr ihre Wertgegenstände zusammentragt. Chuckys gewaltiger Ring ist einer davon."}},faq={{q="Wer ist Chucky?",a="Chucky „Ten Thumbs“ ist ein Schuldner, nach dem Sea Wolf MacKinley sucht. Er streift durch die Ruinen von Aboraz im Schlingendorntal.",al={"chucky ten thumbs","wer ist chucky","ten thumbs"}},{q="Wo finde ich Chuckys Ring?",a="Chuckys gewaltiger Ring befindet sich in den Ruinen von Aboraz im Schlingendorntal, wo Chucky „Ten Thumbs“ umherstreift.",al={"fundort von chuckys ring","wo ist der ring","gewaltiger ring"}},{q="Warum will MacKinley den Ring?",a="MacKinley will Wertgegenstände von drei Schuldnern, deren Zahlungen seit Monaten überfällig sind. Chuckys Ring ist einer der Gegenstände, die er Euch nach Beutebucht bringen lässt.",al={"warum will mac kinley den ring","ringschuld","voodoo-schulden"}},{q="Wozu dient Chuckys gewaltiger Ring?",a="Der Ring ist einer von drei Wertgegenständen, die Sea Wolf MacKinley für die Schulden von Chucky und zwei weiteren Piraten verlangt.",al={"verwendung des rings","was mit chuckys ring tun","zweck des gewaltigen rings"}}},fp="18,148,20.262.0,14.119.0,31.108.0,33.150.0,31.114.0"}
P.entries["item:clarice-s-pendant"] = {n="Clarice' Anhänger",s="In den Teichen der Visionen in Donnerfels bewahrt Clarice Foster den Anhänger auf, den ihr früherer Mann ihr schenkte. Yurivs Hingabe an das Licht ließ sie und ihre Kinder zurück.",h="In den Teichen der Visionen in Donnerfels bewahrt Clarice Foster den Anhänger auf, den ihr früherer Mann ihr...",kw={"clarice foster","clarice' anhänger","verlassene","das grabmal","silberwald","grab","until death do us part","yuriv"},ang={["class:Paladin"]="Als Paladin fällt es Euch vielleicht schwer, Clarice' Verachtung für Yurivs Kreuzzug zu hören. Sein heiliger Eifer hinterließ eine zerrüttete Familie.",["race:Undead"]="Als Verlassene kennt Ihr vielleicht die Bitterkeit über geliebte Menschen, die zu Kreuzzügen aufbrachen, die niemanden schützen konnten. Viele Verlassene teilen diesen Verlust."},sec={{t="Ein bitteres Andenken",b="Bevor der Dritte Krieg Lordaeron verschlang, verließ Yuriv Clarice Foster und ihre Kinder, um gegen die Untoten zu kämpfen. Er glaubte, das Heilige Licht stehe über allem anderen. Yuriv starb, und seine Familie fiel der Geißel zum Opfer, gegen die er in den Kampf gezogen war. Jetzt ist Clarice eine Verlassene, und sie empfindet den Anhänger, den er ihr schenkte, als Beleidigung. Er erinnert sie daran, dass sie und die Kinder hinter seinem Eifer und seiner Pflicht zurückstanden."},{t="Auf Yurivs Grab gebettet",b="Clarice will ihre letzten Bande zu Yuriv und ihrem gemeinsamen Leben durchtrennen. Sie schickt einen Abenteurer los, um den Anhänger auf sein Grab beim Grabmal zu legen. Sein verwahrlostes Grab liegt unter Unkraut und Unrat und wurde geschändet. Als der Anhänger auf den gemeißelten Händen des Sarges ruht, wird sein Edelstein matt. Die letzte Wärme aus Clarice' früherem Leben erlischt."}},faq={{q="Wem gehört Clarice' Anhänger?",a="Clarice Foster, einer Verlassenen in den Teichen der Visionen in Donnerfels, gehört der Anhänger. Ihr Mann Yuriv schenkte ihn ihr, bevor er in den Krieg zog.",al={"wem gehört der anhänger","wessen anhänger ist das","clarice foster"}},{q="Wer war Yuriv?",a="Yuriv war Clarice' Mann, als sie noch am Leben waren. Er verließ sie und ihre Kinder, um im Namen des Heiligen Lichts gegen die aufkommenden Untoten zu kämpfen. Er starb und liegt in einem verwahrlosten Grab beim Grabmal.",al={"clarice ehemann","wer ist yuriv","yurivs grab"}},{q="Warum will Clarice den Anhänger loswerden?",a="Clarice nimmt Yuriv übel, dass er seinen Kreuzzug und seine Hingabe an das Licht über sie und ihre Kinder stellte. Er starb, und Clarice blieb zurück und wurde zum Untod erweckt, genau jenem Schicksal, das er verhindern wollte.",al={"warum anhänger wegwerfen","warum hasst clarice yuriv","clarice anhänger quest"}},{q="Was geschieht, wenn der Anhänger auf Yurivs Grab gelegt wird?",a="Den Anhänger auf Yurivs Grab zu legen, ermöglicht Clarice, sich von dem Andenken und der damit verbundenen schmerzhaften Bindung zu lösen.",al={"was geschieht an yurivs grab","anhänger auf grab"}}},fp="17,170,14.375.0,25.354.1,27.154.0,14.197.0,48.198.0,57.112.1"}
P.entries["item:claw-key"] = {n="Klauenschlüssel",s="Im Krallenbau auf dem Steinkrallengipfel bewachen drei druidische Schlüssel einen verzauberten Hort.",h="Im Krallenbau auf dem Steinkrallengipfel bewachen drei druidische Schlüssel einen verzauberten Hort.",kw={"grabhügelbau","klauenschlüssel","druidisches versteck","torhüterschlüssel","der steinkrallengipfel","krallenbau","talon den hoard","der bau"},ang={["class:Druid"]="Als Druide tragt Ihr einen Schlüssel, der nach den berühmten Druids of the Claw benannt ist. Er spiegelt die heiligen Traditionen und Schutzzauber der nachtelfischen Grabhügelbewohner wider.",["faction:Horde"]="Durch die Befragung gefangener Nachtelfen kann die Horde die uralten Schutzvorkehrungen der Druiden umgehen und die heiligen Artefakte auf dem Steinkrallengipfel plündern."},sec={{t="Schutzzauber des Krallenbaus",b="Nachtelfendruiden errichteten den Krallenbau hoch auf dem Steinkrallengipfel als Zuflucht und Lagerstätte für mächtige Relikte. Sie verbargen seine Schätze hinter mehreren Schutzschichten. Drei verzauberte Schlösser versiegeln den Hort: der Grabhügelschlüssel, der Schlüssel des Schläfers und der Klauenschlüssel. Jeder Schlüssel ruht in einem druidischen Versteck in Form einer Fackel, verborgen in den gewundenen Tunneln des Grabhügelbaus."},{t="Zugang zu den Verstecken",b="Die Druiden hielten die Schlüssel unter Bewachung und schwer zugänglich. Nahe dem Grabhügeleingang öffnet der Torhüterschlüssel das Versteck, das den Klauenschlüssel enthält. Der Klauenschlüssel hilft dabei, das Siegel der Druiden zu brechen und die tief im Berg verborgenen Reichtümer zu erreichen."}},faq={{q="Wozu dient der Klauenschlüssel?",a="Der Klauenschlüssel ist einer von drei Schlüsseln zum Öffnen des Talon Den Hoard, einer durch Schutzzauber gesicherten Steintruhe im Herzen des Krallenbaus auf dem Steinkrallengipfel.",al={"klauenschlüssel zweck","was öffnet der klauenschlüssel","talon den hoard schlüssel"}},{q="Wo ist der Klauenschlüssel zu finden?",a="Der Klauenschlüssel liegt in einem als Fackel getarnten druidischen Versteck in den Tunneln des Krallenbaus auf dem Steinkrallengipfel. Ihr benötigt den Torhüterschlüssel vom Eingang des Baus, um es zu öffnen.",al={"klauenschlüssel fundort","wo ist der klauenschlüssel","klauenschlüssel finden"}},{q="Welche weiteren Schlüssel werden neben dem Klauenschlüssel benötigt?",a="Für den Talon Den Hoard werden der Klauenschlüssel, der Grabhügelschlüssel und der Schlüssel des Schläfers benötigt. Die Druiden verwahrten sie jeweils in einem eigenen Versteck, über den ganzen Bau verteilt.",al={"weitere schlüssel","schlüssel des krallenbaus","schlüssel für den bau"}},{q="Warum versteckten die Druiden diese Schlüssel?",a="Nachtelfendruiden errichteten den Krallenbau, um mächtige Relikte vor neugierigen Blicken zu verbergen. Schlüssel und verborgene Verstecke halfen, Eindringlinge abzuhalten.",al={"warum sind die schlüssel versteckt","geschichte des krallenbaus"}}},fx={["31018164"]={q="Was ist der Klauenschlüssel?",a="Der Klauenschlüssel ist einer von drei verzauberten Schlüsseln, die von den Nachtelf-Druiden vom Steinkrallengipfel gefertigt wurden. Er ist in einem verborgenen Versteck innerhalb des unterirdischen Krallenbaus eingeschlossen und bildet einen wesentlichen Bestandteil eines komplexen Schutzzaubers, der dazu dient, ihre wertvollsten Schätze vor Eindringlingen zu schützen.",al={"was ist der klauenschlüssel","informationen zum klauenschlüssel","was für eine art schlüssel ist der klauenschlüssel"}},e0ebbe01={q="Woher stammt der Klauenschlüssel und wer hat ihn hergestellt?",a="Der Schlüssel wurde von den Druiden gefertigt, die den Krallenbau hoch oben auf dem Steinkrallengipfel errichteten. Um ihre Relikte zu sichern, erschufen sie diesen Schlüssel zusammen mit dem Grabschlüssel und dem Schläferschlüssel und verschlossen ihn in einem Schutzkästchen, das zum Öffnen den Torhüterschlüssel erfordert.",al={"wer hat den klauenschlüssel hergestellt","ursprung des klauenschlüssels","woher kommt der klauenschlüssel"}},["9663afaa"]={q="Warum möchte jemand den Klauenschlüssel haben?",a="Der Klauenschlüssel ist begehrt, da er benötigt wird, um den Hort im Krallenbau zu öffnen. Die Druiden verschlossen viele mächtige Artefakte in den Tiefen der Höhle hinter drei speziellen Schlüssellöchern, um sicherzustellen, dass nur jemand, der alle drei Schlüssel sammelt, die verborgenen Relikte des Horts beanspruchen kann.",al={"warum den klauenschlüssel finden","warum den klauenschlüssel besorgen","hintergrund zum zweck des klauenschlüssels"}}},fp="8,85,22.361.0,20.235.0,30.142.0,32.164.0,50.142.0,35.133.0"}
P.entries["item:cleverly-encrypted-letter"] = {n="Cleverly Encrypted Letter",s="Der Cleverly Encrypted Letter ist eine unleserliche Notiz aus dem Vorgebirge des Hügellands. Meister der Lehren Dibbs schickt sie an Ausgrabungsleiter Sturmlanze in Eisenschmiede weiter, in der Hoffnung, dass dessen Fachwissen ihre Bedeutung enthüllt.",h="Der Cleverly Encrypted Letter ist eine unleserliche Notiz aus dem Vorgebirge des Hügellands.",kw={"cleverly encrypted letter","verschlüsselter brief","hall of explorers","eisenschmiede","brief","meister der lehren dibbs","ausgrabungsleiter sturmlanze","süderstade"},ang={["faction:Alliance"]="Als Reisende der Allianz bringt Ihr den Brief von Süderstade nach Eisenschmiede und verbindet so zwei Siedlungen, deren Gelehrte vielleicht helfen können, seine Bedeutung zu enthüllen."},sec={{t="Eine unleserliche Notiz",b="Auf einem Tisch im Vorgebirge des Hügellands liegt ein Brief, der sich von den anderen abhebt. Seine Schrift ist verschlüsselt und unverständlich, also bringt Ihr ihn zu Meister der Lehren Dibbs nach Süderstade. Er hat diese Art der Verschlüsselung noch nie gesehen und zweifelt, dass sein Wissen ausreicht. Er schickt Euch zu seinem Kollegen Ausgrabungsleiter Sturmlanze in Eisenschmiede, einem Spezialisten für solche Rätsel."}},faq={{q="Woher stammt der Brief?",a="Der Brief wurde zwischen anderen Briefen auf einem Tisch im Vorgebirge des Hügellands gefunden.",al={"herkunft des briefes","fundort","verschlüsselte notiz"}},{q="Warum ist der Brief verschlüsselt?",a="Seine Schrift verwendet eine Art der Verschlüsselung, die Meister der Lehren Dibbs noch nie gesehen hat. Ihr Zweck ist unbekannt.",al={"warum verschlüsselt","was ist der code","briefcode"}},{q="Wer versucht, den Brief zu lesen?",a="Meister der Lehren Dibbs in Süderstade untersucht den Brief und schickt Euch dann zu seinem Kollegen Ausgrabungsleiter Sturmlanze in Eisenschmiede.",al={"wer entziffert ihn","wer kann ihn lesen","leser des briefes"}},{q="Wohin kann ich den Brief bringen?",a="Bringt den Brief zu Ausgrabungsleiter Sturmlanze in die Library der Hall of Explorers in Eisenschmiede. Meister der Lehren Dibbs hat Euch geschickt.",al={"wohin mit dem brief","brief an sturmlanze","wem zeige ich ihn"}}},fp="25,197,18.343.0,31.75.0,28.101.0,33.118.0,28.115.0"}
P.entries["item:cliffspring-river-sample"] = {n="Probe des Klippenquells",s="Am Wasserfall des Klippenquells in Dunkelküste sammelt sich fauliges Wasser in einem Becken. Die für Thundris Windwirker in Auberdine geschöpfte Probe zeigt, dass sich Verderbnis zur Küste hin ausbreitet.",h="Am Wasserfall des Klippenquells in Dunkelküste sammelt sich fauliges Wasser in einem Becken.",kw={"auberdine","blackwood","klippenquell","teufelswald","probe","thundris","röhrchen","wasserfall","windweaver"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Gewässer im Gleichgewicht bleiben müssen. Die unnatürliche Giftigkeit der Probe des Klippenquells erfordert dringend eine Untersuchung und Reinigung.",["race:NightElf"]="Für die Nachtelfen von Auberdine ist die Verderbnis in den Gewässern des nördlichen Kalimdor ein ernstes Zeichen dafür, dass sich die Verseuchung vom Teufelswald ausbreitet."},sec={{t="Eine verdorbene Strömung",b="Der Klippenquell fließt von den östlichen Höhen Dunkelküstes an uralten Steinbrücken vorbei und mündet am Nebelrand ins Meer. Sein klares Wasser ist faulig und sichtlich verdorben geworden. Thundris Windwirker, ein Nachtelf in Auberdine, fürchtet, dass die verdorbene Strömung die Küste und die Wasserversorgung der Siedlung erreichen wird. Er schickte Reisende aus, um Wasser aus dem Becken unter dem unteren Wasserfall des Flusses zu schöpfen. Die Probe bestätigt, dass sich unnatürliche Fäulnis flussabwärts zur Küste hin ausbreitet."},{t="Nachhall des Teufelswalds",b="Blackwood-Furbolgs leben flussaufwärts am Fluss und leiden unter seinem finsteren Einfluss. Thundris erkennt, dass die Verderbnis aus dem Teufelswald stammt, hoch über den Klippen im Osten. Die dämonische Krankheit, die die Berggipfel verheert, sickert in Dunkelküstes Wassereinzugsgebiete. Auberdines Verteidiger müssen sich auf Gegenmaßnahmen vorbereiten."}},faq={{q="Wo wird die Probe des Klippenquells gesammelt?",a="Die Probe stammt aus dem Becken unter dem ersten Wasserfall des Klippenquells, nördlich von Auberdine. Folgt dem Fluss landeinwärts bis zum Wasserfall unter einer hoch gelegenen Brücke.",al={"woher kommt die probe","klippenquell lage","wasserfall becken probe"}},{q="Warum braucht Thundris Windwirker dieses Wasser?",a="Thundris fürchtet, dass das faulige Flusswasser Auberdines Küstengewässer verseuchen wird. Mit einer Probe kann er die Verderbnis untersuchen und planen, wie er ihr entgegenwirken kann.",al={"warum das wasser sammeln","thundris fluss quest","zweck der flussprobe"}},{q="Was lässt das Wasser des Klippenquells faulig werden?",a="Die wahre Quelle liegt im Osten im Teufelswald, wo anhaltende dämonische Verderbnis in die Quellgewässer der Berge sickert. Auch verderbte Blackwood-Furbolgs leben am Fluss.",al={"was hat den fluss vergiftet","warum ist das wasser verdorben","quelle der flussverderbnis"}},{q="Sind die Blackwood-Furbolgs für das Gift verantwortlich?",a="Die Blackwood-Furbolgs verschlimmern die Probleme an den Flussufern, sind aber nicht deren eigentliche Ursache. Sie sind der weitreichenden Verderbnis zum Opfer gefallen, die aus den verheerten Landen im Osten strömt.",al={"waren es die furbolgs","blackwood-furbolgs verderbnis","vergiften furbolgs das wasser"}}},fx={["2e135e3b"]={q="Was ist die Probe des Klippenquells?",a="Es ist ein Fläschchen mit fauligem, verderbtem Flusswasser, das in einer leeren Probenröhre am Fuße des Wasserfalls entlang des The Cliffspring River gesammelt wurde. Sie dient als greifbarer Beweis dafür, dass eine faulige Verderbnis flussabwärts durch die Dunkelküste schwemmt.",al={"probe des klippenquells","was ist probe des klippenquells","probewasser vom klippenquell"}},["57059c85"]={q="Woher kommt die Probe des Klippenquells?",a="Die Probe wird aus dem Becken unter dem ersten Wasserfall des The Cliffspring River, nördlich von Auberdine, gesammelt. Während Ihr das natürliche Wasser selbst mit einer leeren Probenröhre sammelt, stammt seine unnatürliche Fäulnis von verderblichen Kräften flussaufwärts, die vom Teufelswald herabfließen.",al={"woher kommt die probe des klippenquells","ursprung der probe des klippenquells","wer hat die probe des klippenquells hergestellt"}}},fp="24,173,17.459.0,17.319.1,48.166.0,45.142.0,51.165.0,54.187.0"}
P.entries["item:cloth-request"] = {n="Stoffanforderung",s="Im Canal Tailor and Fit Shop erhält Rema Schneider Harlan Bagleys Anforderung für neue Stoffe und Strickwaren. Seine Regale leeren sich rasch.",h="Im Canal Tailor and Fit Shop erhält Rema Schneider Harlan Bagleys Anforderung für neue Stoffe und Strickwaren.",kw={"canal tailor and fit shop","stoffanforderung","harlan bagley","rema schneider","nachschub","sturmwind"},ang={["faction:Alliance"]="Sturmwinds Bürger sind beunruhigt und bereiten sich auf Auseinandersetzungen vor, obwohl die Regentschaft keine offiziellen Ankündigungen gemacht hat.",["profession:Tailoring"]="Die Anforderung verweist auf Sturmwinds Textilhandel. Örtliche Tuchmacher wie die Schneiders beliefern Gemischtwarenläden und Ausstatter mit gewebten Waren."},sec={{t="Ansturm auf robuste Waren",b="Harlan Bagley bittet Rema Schneider um neue Stoffe und gestrickte Kleidungsstücke. Der Handel hat ohne Vorwarnung stark zugenommen. Bürger und Reisende kaufen Rüstungen und strapazierfähige Kleidung, als stünde eine harte Jahreszeit bevor. Der Ansturm macht Rema ratlos und misstrauisch. Das Haus der Adligen hat keinen offenen Krieg angekündigt, weshalb sie sich fragt, warum sich die Stadtbewohner im Stillen wappnen und ob die Anführer der Krone Unruhen verheimlichen."}},faq={{q="Was ist die Stoffanforderung?",a="Harlan Bagleys schriftliche Bestellung bittet Rema Schneider, neue Stoffe und Strickwaren für seinen Laden zu liefern.",al={"was ist die stoffanforderung","stoffanforderung gegenstand","harlans bestellschein"}},{q="Warum braucht Harlan Bagley mehr Stoff?",a="In Bagleys Geschäft herrscht ungewöhnlich viel Betrieb. Stadtbewohner und Reisende haben große Mengen an Rüstungen und strapazierfähiger Kleidung gekauft, sodass seine Regale fast leer sind.",al={"warum harlan stoff braucht","warum hat bagley keine waren mehr","grund für bagleys nachbestellung"}},{q="Wohin muss diese Anforderung gebracht werden?",a="Die Bestellung geht an Rema Schneider im Canal Tailor and Fit Shop an den Wasserwegen von Sturmwind.",al={"wohin die stoffanforderung bringen","wer bekommt die stoffanforderung","stoffanforderung abliefern"}},{q="Warum kaufen die Menschen in Sturmwind so viele Rüstungen und Kleidungsstücke?",a="Weder Händler noch einfache Bürger wissen es mit Sicherheit. Der plötzliche Ansturm beunruhigt Rema Schneider, die sich fragt, ob der Adelshof aufziehende Feindseligkeiten oder Gefahren vor der Bevölkerung verbirgt.",al={"warum kaufen die leute rüstungen","ist sturmwind im krieg","rema schneiders verdacht"}}},fx={b4374b3c={q="Woher kommt die Stoffanforderung und wer hat sie geschrieben?",a="Die Anforderung wurde von Harlan Bagley, einem Ladenbesitzer in Sturmwind, verfasst. Da er einen plötzlichen Anstieg der Geschäfte erlebt, während die Bürger robuste Kleidung und Rüstungen kaufen, schreibt Bagley die Anforderung, um eine weitere Lieferung gestrickter Kleidung zu sichern und seine Regale gefüllt zu halten.",al={"wer hat die stoffanforderung geschrieben","ursprung der stoffanforderung","woher kommt die stoffanforderung"}}},fp="13,150,21.391.0,26.103.0,39.159.0,35.94.0,62.187.0"}
P.entries["item:cloven-hoof"] = {n="Gespaltener Huf",s="Tief in Tausend Nadeln bewachen die Galakzentauren den Gespaltenen Huf in der Spalthufhöhle. Taurengelehrte am Freiwindposten wollen ergründen, was seine seltsame Energie offenbart.",h="Tief in Tausend Nadeln bewachen die Galakzentauren den Gespaltenen Huf in der Spalthufhöhle.",kw={"uralte feuerschale","gespaltener huf","galak","rau klippenläufer","heilige flamme","spalthufklippe","spalthufhöhle"},ang={["class:Shaman"]="Rituelle Elemente können magische Flammen kurzzeitig löschen und Euch ermöglichen, den Gespaltenen Huf zu bergen. Solche Arbeit erfordert sorgfältige spirituelle Studien in Kalimdor.",["race:Tauren"]="Seit Generationen erdulden die nomadischen Tauren die unerbittlichen Angriffe der Zentauren. Die Ursprünge und die Magie von Relikten wie dem Gespaltenen Huf zu ergründen, könnte Euch mehr über ihre alten Widersacher lehren."},sec={{t="Ein heiliges Zentaurenrelikt",b="In der Spalthufhöhle bewahren die Galakzentauren den Gespaltenen Huf in einer uralten Feuerschale auf. Magisches Feuer umgibt ihn, und gesegnetes Wasser muss die Flamme kurzzeitig löschen, bevor jemand das Relikt berühren kann. Die Zentaurenklans sind zerstritten und gewalttätig, doch ihre Fürsorge für die Feuerschale deutet auf ein Ritual hin, das mit ihren Ursprüngen verbunden ist.\n\nAm Freiwindposten hoffen Rau Klippenläufer und andere Taurenbeobachter, durch die seltsame Aura des Hufs mehr über die Zentauren zu erfahren, die Kalimdors Ebenen seit Langem heimsuchen."}},faq={{q="Wo wird der Gespaltene Huf aufbewahrt?",a="Der Gespaltene Huf ruht in einer uralten Feuerschale im hinteren Teil der Spalthufhöhle, einer Höhle in der Spalthufklippe nördlich des Freiwindpostens. Elitekrieger der Galak bewachen ihn.",al={"gespaltener huf fundort","wo gespaltenen huf finden","spalthufhöhle relikt"}},{q="Warum will Rau Klippenläufer den Gespaltenen Huf?",a="Rau Klippenläufer will den Gespaltenen Huf untersuchen, um mehr über die Ursprünge und die Magie der Zentauren zu erfahren. Er spürt eine seltsame Energie, die von dem Relikt ausgeht, und hofft, dass es verborgene Wahrheiten über die feindseligen Klans enthüllt.",al={"warum gespaltenen huf holen","rau klippenläufer quest","wer will gespaltenen huf"}},{q="Wie wird der Gespaltene Huf aus der Feuerschale geborgen?",a="Magisches Feuer umgibt den Gespaltenen Huf, sodass er nicht direkt genommen werden kann. Gießt eine Phiole mit besonderem Wasser in die uralte Feuerschale, um die heilige Flamme kurzzeitig zu löschen, und nehmt dann den Huf, bevor das Feuer zurückkehrt.",al={"wie gespaltenen huf bekommen","heilige flamme löschen","gefüllte geätzte phiole verwendung"}},{q="Wer sind die Galakzentauren, die ihn bewachen?",a="Die Galak sind ein Zentaurenstamm, der die nördlichen Gebiete von Tausend Nadeln beherrscht. Ihre Festung ist die Spalthufklippe, wo sie ihr heiliges Feuer erbittert vor Außenstehenden schützen.",al={"galakzentauren","spalthufklippe zentauren","wer bewacht die flamme"}}},fx={b52742f5={q="Was ist der Gespaltene Huf?",a="Der Gespaltene Huf ist ein mysteriöses, uraltes Relikt, das von den Galak-Zentauren der Tausend Nadeln verehrt wird. Eingeschlossen in einer ewigen heiligen Flamme tief in der Spalthufhöhle strahlt das Objekt eine seltsame, unerforschte Energie aus, die die intensive Neugier der Tauren-Forscher weckt.",al={"was ist gespaltener huf","relikt gespaltener huf","was ist der huf"}}},fp="11,164,22.475.0,30.156.0,46.192.0,50.207.0,38.178.0"}
P.entries["item:comar-s-heart"] = {n="Comar's Heart",s="In Unterstadt suchen Hexenmeister Comar's Heart, um eine Sukkubus in ihren Dienst zu zwingen. Es gehörte Comar Villard, einem Menschen, der im Sumpfland nach seiner verschollenen Frau suchte.",h="In Unterstadt suchen Hexenmeister Comar's Heart, um eine Sukkubus in ihren Dienst zu zwingen.",kw={"carendin halgar","comar villard","comar's heart","hearts of the pure","sukkubus","tempel der verdammten","unterstadt","sumpfland"},ang={["class:Warlock"]="Wenn Ihr als Hexenmeister Comar's Heart an Euch nehmt, zeigt sich, wie Dämonologie sterbliche Tugend zum Köder für eine Sukkubus macht, die Ihr binden wollt.",["race:Undead"]="Wenn Ihr als Verlassener das Herz eines treuen menschlichen Liebenden herausschneidet, zeigt sich die Entfremdung zwischen den Lebenden und den Untoten in Lordaeron."},sec={{t="Ein Leuchtfeuer der Reinheit",b="Comar Villard sucht noch immer im Sumpfland nach seiner verschollenen Frau. Unruhen haben die Östlichen Königreiche erfasst, doch er will die Suche nicht aufgeben. Carendin Halgars Jünger in Unterstadt schätzen solche Treue als selten und rein. Um eine launische und räuberische Sukkubus zu binden, brauchen Hexenmeister Hingabe wie die seine als Köder. Comars unerschütterliche Liebe macht ihn zum Opfer, und sein Herz wird zum Lockmittel für einen dämonischen Diener."},{t="Der Preis der Verführung",b="Lehrlinge der Verlassenen reisen durch umkämpfte Lande nach Süden, überqueren den Thandol-Übergang und betreten die von der Allianz gehaltenen Sümpfe, um Comar's Heart zu erbeuten. Sie bringen es zusammen mit Dalins Herz zum Tempel der Verdammten zurück. Das Organ wirkt gewöhnlich, obwohl Güte einst den Mann antrieb, dem es gehörte. Für den Nether ist die Tugend, die in Comars Fleisch zurückbleibt, ein berauschender Köder. Sie kann eine Sukkubus durch den Schleier zwischen den Dimensionen ziehen und einem Hexenmeister unterwerfen."}},faq={{q="Wer war Comar Villard?",a="Comar Villard war ein hingebungsvoller Mensch, der im gefährlichen Sumpfland nach seiner vermissten Frau suchte. Er wollte die Hoffnung nicht aufgeben, und seine Liebe zeugte von seinem reinen Herzen.",al={"wer ist comar","comar villard geschichte","warum comar töten"}},{q="Warum brauchen Hexenmeister Comar's Heart?",a="Die Hexenmeister von Unterstadt brauchen Comar's Heart, um eine Sukkubus anzulocken und in ihren Dienst zu zwingen. Seine Hingabe macht das Herz zu einem unwiderstehlichen Köder für den Dämon.",al={"warum comar's heart benötigen","wofür ist comar's heart","sukkubus herz geschichte"}},{q="Wo ist Comar Villard zu finden?",a="Comar Villard wandert auf der Hauptstraße im nördlichen Sumpfland, unmittelbar südlich des Thandol-Übergangs zwischen dem Arathihochland und Khaz Modan.",al={"comar villard aufenthaltsort","wo ist comar","wie comar finden"}},{q="Wer schickt Hexenmeister los, um das Herz zu beschaffen?",a="Hexenmeisterlehrer in Unterstadt weisen Lehrlinge an, das Herz zu beschaffen. Carendin Halgar beaufsichtigt sie im Tempel der Verdammten, wo die Lehrlinge lernen, eine Sukkubus zu beschwören.",al={"wer will comar's heart","wer vergibt hearts of the pure","carendin halgar herz"}}},fx={["7acb4df8"]={q="Was ist Comar's Heart?",a="Comar's Heart ist das buchstäbliche Herz, das aus Comar Villard, einem treuen menschlichen Wanderer im Sumpfland, herausgeschnitten wurde. Hexenmeister schätzen es als seltenes Exemplar unbefleckter Tugend, getränkt in Treue und dauerhafter Liebe.",al={"was ist comar's heart","gegenstand comar's heart","lore zu comar's heart"}},a49b76cf={q="Woher stammt Comar's Heart?",a="Es wird direkt aus der Brust von Comar Villard entnommen, einem Mann, der die tückischen Sümpfe im Sumpfland nach jeder Spur seiner verlorenen Frau durchsuchte. Es ist kein durch Zauberei geschmiedetes Artefakt, sondern ein sterbliches Organ, dessen reine Hingabe es zu einem wirkungsvollen Reagenz für Rituale macht.",al={"woher stammt comars heart","wer fertigte comars heart","ursprung von comars heart"}}},fp="13,164,18.409.0,22.439.1,22.156.0,35.155.0,29.133.0,40.183.0"}
P.entries["item:consecrated-rune"] = {n="Geweihte Rune",s="In Ambossar im Coldridgetal ruft die Geweihte Rune angehende Zwergenpaladine zu ihren formellen Pflichten als Ritter der Silbernen Hand.",h="In Ambossar im Coldridgetal ruft die Geweihte Rune angehende Zwergenpaladine zu ihren formellen Pflichten als...",kw={"ambossar","bromos grummler","das coldridgetal","geweihte rune","heiliges licht","paladin","silberne hand"},ang={["class:Paladin"]="Als Zwergenpaladin kennzeichnet der Empfang der Rune Euren formellen Eintritt in die Reihen der Ritter der Silbernen Hand unter Bromos Grummlers Anleitung.",["race:Dwarf"]="Für Euch als Zwerg spiegelt die Rune wider, wie sich menschliche heilige Traditionen durch das gemeinsame Bündnis und den gegenseitigen Respekt zwischen Eisenschmiede und der Menschheit mit der zwergischen Kriegerkultur verbunden haben."},sec={{t="Berufung zur Silbernen Hand",b="Unter den Rittern der Silbernen Hand kennzeichnet eine Geweihte Rune den Platz eines zwergischen Novizen. Zwergenpaladine erhalten im Coldridgetal eine solche Rune, nachdem sie ihre grundlegenden Waffenfertigkeiten bewiesen haben. Heilige Worte sind darauf eingraviert, und das Heilige Licht segnet die Rune.\n\nBromos Grummler, der Paladinlehrer in Ambossar, schickt sie als offizielle Vorladung. Zwerge achten die Traditionen des Heiligen Lichts sehr, die ihre menschlichen Verbündeten ihnen nahegebracht haben. Das Lesen der Rune bestätigt den Platz eines Novizen im Orden und kennzeichnet den Beginn seines Dienstes."}},faq={{q="Wozu dient die Geweihte Rune?",a="Die Geweihte Rune ruft angehende Zwergenpaladine dazu auf, Bromos Grummler in Ambossar aufzusuchen und ihre Paladinausbildung fortzusetzen.",al={"geweihte rune zweck","was bewirkt die rune","geweihte rune questgegenstand"}},{q="Wer schickt die Geweihte Rune?",a="Bromos Grummler schickt die Geweihte Rune aus Ambossar im Coldridgetal, wo er Zwergenpaladine ausbildet.",al={"wer gab mir die geweihte rune","herkunft der rune","bromos grummler rune"}},{q="Warum folgen Zwergenpaladine den Traditionen der Silbernen Hand?",a="Zwerge lernten von menschlichen Lehrmeistern viel über das Heilige Licht und die Lehren der Silbernen Hand. Sie verehren die Geschichte und Traditionen des Ordens sowie seinen Glauben, dass ein einziges Opfer Azeroths Schicksal verändern kann.",al={"zwerg paladin silberne hand","warum sind zwerge paladine","zwerge und heiliges licht"}}},fx={dda1df9e={q="Was ist die Geweihte Rune?",a="Es ist ein beschrifteter Zwergenstein, der im Namen vom das Heilige Licht gesegnet wurde und als formelle Vorladung an Paladinanwärter gesendet wird, die im Coldridgetal trainieren. Zwerge verbinden runische Handwerkskunst mit heiligen Lehren und nutzen Steine wie diesen, um feierliche Botschaften zu übermitteln und angehende Verteidiger von das Licht zu ihren Mentoren zu rufen.",al={"was ist die geweihte rune","gegenstand geweihte rune","bedeutung geweihte rune"}},["924bde77"]={q="Warum möchte Bromos Grummler, dass Ihr die Geweihte Rune erhaltet?",a="Bromos Grummler sendet die Rune, um Eure Bereitschaft zu prüfen und Euch für die formelle Ausbildung nach Ambossar zu schicken. In ganz Dun Morogh braut sich Ärger zusammen und die Ritter der Silbernen Hand benötigen fähige, disziplinierte Hände, die bereit sind, ihre heilige Pflicht zu erfüllen und Azeroth vor Schaden zu bewahren.",al={"warum geweihte rune","warum bromos die geweihte rune will","warum erhalte ich die geweihte rune"}}},fp="16,140,28.522.0,38.129.0,31.111.0,65.197.0"}
P.entries["item:console-key"] = {n="Konsolenschlüssel",s="An der Ausgrabungsstätte der Venture Company im Brachland verwahrt Tüftler Sniggles den Konsolenschlüssel. Er öffnet das Hauptsteuerterminal und gibt den Samophlansch frei, nachdem die Vorrichtung abgeschaltet wurde.",h="An der Ausgrabungsstätte der Venture Company im Brachland verwahrt Tüftler Sniggles den Konsolenschlüssel.",kw={"brachland","konsolenschlüssel","steuerkonsole","samophlange","tüftler sniggles","venture company"},ang={["faction:Horde"]="Tüftler Sniggles den Konsolenschlüssel abzunehmen hilft dabei, die ausbeuterische Industriearbeit der Venture Company im Herzen des Brachlands zu stören.",["profession:Engineering"]="Die Venture Company verwendet Schlösser mit eigens angefertigten Schlüsseln, um empfindliche technische Prototypen wie den Samophlansch vor Konkurrenten zu schützen."},sec={{t="Sicherung der Vorrichtung",b="Die Venture Company betreibt im nördlichen Brachland einen Industrieaußenposten, der von dampfbetriebenen Maschinen angetrieben wird. In seinem Herzen befindet sich ein Gerät namens Samophlansch. Die Konsole ist verschlossen, und nur Tüftler Sniggles, der leitende Techniker vor Ort, trägt den Konsolenschlüssel bei sich. Er öffnet das Terminalgehäuse, damit die Anlage abgeschaltet werden kann."},{t="Abschalten der Anlage",b="Sobald die Hilfsventile betätigt wurden und die Vorrichtung abgekühlt zum Stillstand kommt, unterbricht der Konsolenschlüssel die letzten Schaltkreise. Wird er gedreht, entzieht er dem Terminal die verbleibende Energie und entriegelt dessen Gehäuse. Dann kann der Samophlansch aus der Maschinerie herausgehebelt werden."}},faq={{q="Was entriegelt der Konsolenschlüssel?",a="Der Konsolenschlüssel öffnet die Hauptsteuerkonsole an der Anlage der Venture Company im nördlichen Brachland. Sobald die Maschinerie stillsteht, entzieht er dem Terminal die Energie und legt den Samophlansch frei.",al={"wofür ist der konsolenschlüssel","was öffnet der konsolenschlüssel","konsolenschlüssel verwenden"}},{q="Wer trägt den Konsolenschlüssel bei sich?",a="Tüftler Sniggles trägt den Konsolenschlüssel bei sich. Der Ingenieur der Venture Company hält sich in einer Hütte unmittelbar nordöstlich der Hauptkonsolenvorrichtung auf.",al={"wer lässt den konsolenschlüssel fallen","wo gibt es den konsolenschlüssel","tüftler sniggles schlüssel"}},{q="Warum ist die Konsole überhaupt verschlossen?",a="Die Venture Company verschließt das Terminal, damit Rivalen und aufsässige Arbeiter weder ihre Maschinerie manipulieren noch wertvolle Teile wie den Samophlansch entwenden können.",al={"warum brauche ich einen schlüssel","warum ist der samophlansch eingeschlossen"}},{q="Könnt Ihr den Schlüssel benutzen, bevor die Ventile geschlossen sind?",a="Benutzt den Konsolenschlüssel, nachdem die Ventile geschlossen wurden und die Anzeigen auf null stehen. Die aktive Konsole kann eine mechanische Fehlzündung verursachen.",al={"schlüssel zuerst benutzen","kann ich die konsole einfach entriegeln"}}},fx={["4424a0fd"]={q="Was ist der Konsolenschlüssel?",a="Der Konsolenschlüssel ist ein mechanischer Sicherheitsschlüssel, den der Tüftler der Venture Company besitzt, der die Steuerkonsole im Brachland überwacht. Er passt in das verschlossene Gehäuse, das die Samophlange umschließt, und stellt sicher, dass nur autorisiertes Personal Zugang zu der empfindlichen Maschinerie und dem Terminal-Inneren hat.",al={"konsolenschlüssel","was ist der konsolenschlüssel"}},["81c16021"]={q="Warum möchte jemand den Konsolenschlüssel haben?",a="Sobald die Apparatur abgeschaltet wurde und der Strom von der Steuerkonsole abgeflossen ist, bleibt das Gehäuse fest verschlossen. Ihr benötigt den Konsolenschlüssel, um das Bedienfeld selbst aufzuschließen, was der letzte notwendige Schritt ist, um die Samophlange sicher aus dem Terminal zu lösen und zu bergen.",al={"warum den konsolenschlüssel besorgen","warum brauche ich den konsolenschlüssel","zweck des konsolenschlüssels"}}},fp="11,180,22.320.0,21.240.1,33.189.0,28.132.0,45.158.0,52.128.0"}
P.entries["item:control-console-operating-manual"] = {n="Steuerkonsolenbedienungsanleitung",s="Am Standort der Venture Company südwestlich des Schlickermoors nutzen Arbeiter die Steuerkonsolenbedienungsanleitung, um die Maschinen zu bedienen. Sie beschreibt die Reihenfolge der Ventilbetätigungen zum Abschalten des Samophlanschs.",h="Am Standort der Venture Company südwestlich des Schlickermoors nutzen Arbeiter die...",kw={"brachland","steuerkonsole","gobliningenieurskunst","bedienungsanleitung","samophlange","das schlickermoor","venture company"},ang={["faction:Horde"]="Die Anleitung gewährt Ermittlern der Horde Einblick in die rücksichtslosen industriellen Aktivitäten der Venture Company im gesamten nördlichen Brachland.",["profession:Engineering"]="Die Anleitung zeigt, wie Goblins an die Ingenieurskunst herangehen. Systeme unter hohem Druck, die kaum als sicher gelten können, werden über ein chaotisches Geflecht aus Hebeln und Ventilen statt über ausgewogene Sicherheitsmechanismen gesteuert."},sec={{t="Goblinmaschinen entschlüsseln",b="Die Venture Company betreibt eine Bohr- und Forschungsstätte im nördlichen Brachland, südwestlich des Schlickermoors. Messgeräte und Druckventile sind mit Mechanismen verbunden, die ein Gerät namens Samophlansch antreiben. Ohne die richtigen Anweisungen können die störanfälligen Steuerelemente auf gefährliche Weise versagen oder das System blockieren. Die Anleitung zeigt den Arbeitern, wie sie den Kernapparat abschalten, ohne eine Explosion auszulösen."}},faq={{q="Wozu dient die Steuerkonsolenbedienungsanleitung?",a="Die Steuerkonsolenbedienungsanleitung führt Euch durch die Bedienung der Konsole der Venture Company südwestlich des Schlickermoors. Sie zeigt, wie Ihr die Ventile schließt und den Samophlansch abschaltet.",al={"wozu dient die anleitung","verwendung der anleitung","warum habe ich eine bedienungsanleitung"}},{q="Was ist ein Samophlansch?",a="Forscher außerhalb der Venture Company verstehen nicht vollständig, was ein Samophlansch tut. Offenbar handelt es sich um einen von Goblins entwickelten Kernmechanismus, der mit Bohrungen und industriellen Arbeiten im Brachland zusammenhängt.",al={"was macht der samophlansch","samophlansch hintergrund","was ist diese maschine"}},{q="Wer hat diese Anleitung verfasst?",a="Techniker der Venture Company, die den Forschungsaußenposten beaufsichtigen, haben die Anleitung verfasst. Sie hilft den Arbeitern, die Konsole zu bedienen und den Druck in ihren Steuerventilen auf den vorgesehenen Werten zu halten.",al={"wer hat die anleitung verfasst","verfasser der anleitung"}},{q="Was passiert, wenn ich die Anleitung verliere?",a="Die Konsole verfügt über Messgeräte und Anzeigen für den Ventildruck. Ein geschickter Abenteurer kann die Anzeigen auf der Vorderseite ablesen und die Schalter ohne die Anleitung bedienen.",al={"anleitung verloren","bedienungsanleitung gelöscht"}}},fx={["4b9f7b43"]={q="Was ist die Steuerkonsolenbedienungsanleitung?",a="Es ist eine Anleitung, die von der Venture Company geborgen wurde und den Betrieb der Steuerkonsole in ihrer Forschungseinrichtung südwestlich von Das Schlickermoor detailliert beschreibt. Sie erläutert die Funktionsweise ihrer Maschinerie, damit ein Techniker deren Ventile sicher bedienen und die Apparatur entkoppeln kann.",al={"was ist die steuerkonsolenbedienungsanleitung","steuerkonsolenbedienungsanleitung","anleitung der venture company"}},["5e9de40e"]={q="Warum wird die Steuerkonsolenbedienungsanleitung gesucht?",a="Die Anleitung liefert die genauen Bedienschritte, die erforderlich sind, um die mysteriöse Samophlange der Venture Company abzuschalten und zu entkoppeln. Ohne die Entschlüsselung ihrer Anweisungen wäre ein blindes Herumspielen an den unberechenbaren Hebeln, Knöpfen und druckgesteuerten Ventilen an der Konsole nahezu unmöglich.",al={"warum die steuerkonsolenbedienungsanleitung suchen","warum wird die anleitung benötigt","warum ist die anleitung nützlich"}}},fp="32,191,28.383.0,54.172.0,22.193.0,22.180.0,34.143.0"}
P.entries["item:corroded-shrapnel"] = {n="Zerfressenes Schrapnell",s="Im Steinkrallengebirge stecken gezackte Splitter in den verderbten Urtumen des Waldes. Die Munition der Venture Company hinterließ sie dort, als die Goblins flohen.",h="Im Steinkrallengebirge stecken gezackte Splitter in den verderbten Urtumen des Waldes.",kw={"verkohlter urtum","zerfressenes schrapnell","gaxim","kaela schattenspeer","steinkrallengebirge","urtum","venture company"},ang={["class:Druid"]="Als Druide seht Ihr an Kalimdors Urtumen den Preis ungebremster Ausbeutung, gezeichnet von Goblinmunition und eiternden Metallsplittern.",["race:Gnome"]="Als Gnom könnt Ihr Gaxims Untersuchung verunreinigten Schrapnells als praktischen, wissenschaftlichen Weg betrachten, einem ökologischen Rätsel nachzugehen, das die Wächter des Waldes nicht erklären können."},sec={{t="Überreste industrieller Verwüstung",b="Die Goblins der Venture Company flohen aus den Hainen des Steinkrallengebirges im Schutz rücksichtslos eingesetzter Munition. Ihre Explosionen trieben Schrapnell in die Urtume, die das Tal verteidigten, wo es sich tief in Rinde und Kernholz bohrte. Die uralten Wächter erlagen langsam der Verderbnis. Ihr Holz verdunkelte sich, und sie richteten ihren Zorn gegen jeden, der das Tal betrat. Kaela Schattenspeer sucht die verrosteten Splitter für Gaxim Rostknirsch, einen Gnom, der untersuchen will, wie die Waffen die Verderbnis der Urtume auslösten."}},faq={{q="Woher stammt dieses Schrapnell?",a="Das Schrapnell stammt von verderbten Urtumen im Steinkrallengebirge, darunter Verkohlte Urtume, Geschwärzte Urtume und Vengeful Ancients.",al={"wo findet man schrapnell","zerfressenes schrapnell beute","wer lässt schrapnell fallen"}},{q="Warum steckt das Schrapnell in den Urtumen?",a="Die explosive Munition der Venture Company traf die Urtume, als die Waldwächter die Holzfäller der Goblins aus dem Tal vertrieben. Während des Kampfes bohrten sich Splitter in ihre Rinde und blieben dort stecken.",al={"wie kam schrapnell in die urtume","warum sind urtume voller metall"}},{q="Ist das Schrapnell für die Verderbnis der Urtume des Waldes verantwortlich?",a="Kaela Schattenspeer sagt, der Gnom Gaxim glaube, die Verderbnis der Urtume hänge mit der üblen chemischen oder metallischen Zusammensetzung der Waffen zusammen, die die Goblins bei ihrem Rückzug einsetzten.",al={"hat schrapnell die urtume verderbt","warum sind urtume wütend"}},{q="Wer will das Schrapnell untersuchen?",a="Kaela Schattenspeer, eine Nachtelfe, möchte eine Probe für Gaxim, einen gnomischen Erfinder. Er will ihre Eigenschaften untersuchen und herausfinden, woran die Urtume leiden.",al={"wer braucht das schrapnell","schrapnell abgeben"}}},fx={["1f081bfa"]={q="Was ist Zerfressenes Schrapnell?",a="Zerfressenes Schrapnell besteht aus gezackten Metallfragmenten, die von Goblin-Waffen hinterlassen wurden. Eingebettet tief in der vernarbten Rinde der Treants vom Steinkrallengebirge, wird vermutet, dass diese zersetzten, verrosteten Stücke explosiver Munition ein verweilendes Gift oder einen üblen Makel tragen, der die Beschützer des Waldes heimsucht.",al={"was ist zerfressenes schrapnell","hintergrund zu zerfressenem schrapnell","gegenstand zerfressenes schrapnell"}}},fp="17,153,27.478.0,35.141.0,44.188.0,63.166.0,34.145.0"}
P.entries["item:corrupt-manifestation-s-bracers"] = {n="Verderbte Manifestationsarmschienen",s="An der Küste des Silberwalds bleiben Verderbte Manifestationsarmschienen von einem verderbten Wasserelementar zurück. Während Call of Water werfen Schamanen-Initianden sie mit reinem Wasser in das Kohlenbecken von Everfount, reinigen so den Schrein und beschwören einen reinen Wassergeist.",h="An der Küste des Silberwalds bleiben Verderbte Manifestationsarmschienen von einem verderbten Wasserelementar...",kw={"kohlenbecken von everfount","call of water","verderbte manifestationsarmschienen","schamanenquest","silberwald","wasserelementar"},ang={["class:Shaman"]="Als Schamane bergt und reinigt Ihr diese Armschienen als letzte Prüfung von Call of Water. Die Prüfung beweist Eure Macht, entstellte Elemente zu besänftigen und wiederherzustellen."},sec={{t="Eine reinigende Opfergabe",b="Die Seuche der Geißel erreichte Lordaerons Geister. An der Küste des Silberwalds, westlich vom Grabmal, befiel Verderbnis einen heiligen Wasserschrein. Seine Wassermanifestation wurde zu einem angriffslustigen Schatten, und Schamanen-Initianden müssen sie besiegen, um die Armschienen zu bergen. Am Kohlenbecken von Everfount werfen sie die Fesseln mit reinem Wasser in die Flamme. Das Ritual befreit den Schrein von der Verderbnis und ruft einen makellosen Wassergeist hervor."}},faq={{q="Wofür werden diese Armschienen verwendet?",a="Während eines Reinigungsrituals werden die Armschienen mit reinem Wasser in das Kohlenbecken von Everfount geworfen. Dies reinigt den Schrein im Silberwald von Verderbnis und ruft einen reinen Wassergeist hervor.",al={"was bewirken armschienen","call of water armschienen","verderbte armschienen verwendung"}},{q="Woher stammen die Armschienen?",a="Die Armschienen stammen von einer verderbten Schwachen Wassermanifestation nahe einem verderbten Elementarschrein an der Küste des Silberwalds, westlich vom Grabmal.",al={"wo gibt es armschienen","verderbte manifestation fundort"}},{q="Warum wurde der Wasserelementar verderbt?",a="Die Seuche und die dunklen Mächte, die Lordaeron verheerten, entstellten den Elementar und trennten die örtlichen Geister von ihrer Verbindung zu den Schamanen.",al={"warum ist das wasser verderbt","silberwald wasserverderbnis"}}},fx={["0d8aeb2f"]={q="Was sind die Verderbte Manifestationsarmschienen?",a="Diese Armschienen sind physische Überreste, die an eine verderbte Schwache Wassermanifestation gebunden sind, die entlang der verseuchten Küste vom Silberwald gefunden wurde. Wie viele Elementarwesen, die an die sterbliche Ebene gebunden sind, trägt die Manifestation Armschienen, die ihre wässrige Form verankern und formen. Selbst nachdem die Kreatur zerstört wurde, behalten die Armschienen den spirituellen Rückstand der verderbten Existenz des Elementars, was sie zu lebenswichtigen Katalysatoren für rituelle Reinigungen macht.",al={"was sind die verderbte manifestationsarmschienen","verderbte manifestationsarmschienen","was sind diese armschienen"}}},fp="31,260,20.436.0,32.179.0,31.147.0,43.130.0"}
P.entries["item:corrupted-brain-stem"] = {n="Verderbter Hirnstamm",s="In der Tiefschwarzen Grotte und an der Küste von Eschental stammen Verderbte Hirnstämme von Naga und Satyren, die durch Magie entstellt wurden. Gershala Nachtraunen aus Auberdine untersucht ihre Missbildungen und hofft, dass nachtelfische Gelehrte lernen können, die Blutelfen vor demselben Schicksal zu bewahren.",h="In der Tiefschwarzen Grotte und an der Küste von Eschental stammen Verderbte Hirnstämme von Naga und Satyren...",kw={"eschental","auberdine","tiefschwarze grotte","verderbter hirnstamm","gershala nachtraunen","naga","researching the corruption","satyr"},ang={["faction:Alliance"]="Als Kundschafter der Allianz in Eschental trotzt Ihr den Tiefen von Blackfathom, um Auberdines Gelehrten zu helfen, wachsende Bedrohungen in ganz Azeroth zu verstehen.",["race:NightElf"]="Für Nachtelfen erinnern diese Überreste an die tragische Geschichte ihres Volkes und die monströsen Folgen ungezügelter Eingriffe mit arkaner Magie und Teufelsmagie."},sec={{t="Anatomie der Verwandlung",b="Verbotene Magie und dämonische Pakte zeichnen die Naga und Satyren. Vor langer Zeit wurden leichtfertige Hochgeborene der Kaldorei zu schlangenartigen Wasserbestien und dämonischen, gehörnten Unholden. Ihre Hirnstämme weisen schwere Mutationen auf und zeigen, wie tief verderbende Energien die Nervensysteme von Wesen veränderten, die einst als Elfen bekannt waren."},{t="Gershalas Warnung",b="Von Auberdine aus verfolgt Gershala Nachtraunen beunruhigende Gerüchte über die Blutelfen der Östlichen Königreiche. Er fürchtet, ihre dämonische Zauberei werde eine weitere Generation von Monstern auf Azeroth hervorbringen. Deshalb schickt er Abenteurer in die Tiefschwarze Grotte, um Gewebe von Naga und Satyren zu untersuchen. Er hofft, die magische Degeneration nachzuvollziehen, bevor eine weitere elfische Kultur verloren geht."}},faq={{q="Welche Kreaturen liefern einen Verderbten Hirnstamm?",a="Naga und Satyren in der Tiefschwarzen Grotte und an der Küste von Eschental liefern Verderbte Hirnstämme. Dazu zählen Blackfathom-Orakel, Meerhexen und Fallenroot-Satyren.",al={"wer lässt hirnstämme fallen","verderbter hirnstamm beute","wo gibt es hirnstämme"}},{q="Wer braucht diese Hirnstämme und warum?",a="Gershala Nachtraunen in Auberdine benötigt die Hirnstämme für anatomische Forschungen zur magischen Verderbnis.",al={"wer braucht verderbten hirnstamm","gershala quest","hirnstämme abgeben"}},{q="Was hoffen Nachtelfen aus diesen Proben zu lernen?",a="Nachtelfen hoffen zu lernen, wie dämonische Energien die elfische Biologie verändern. Gershala fürchtet, die Blutelfen könnten zu Monstern werden, so wie die einstigen Hochgeborenen zu Naga und Satyren wurden.",al={"warum naga und satyr erforschen","researching the corruption hintergrundgeschichte","verbindung zu blutelfen"}},{q="Sind sie auch außerhalb der Höhlen der Tiefschwarzen Grotte zu finden?",a="Ja. Einige Fallenroot-Satyren und Blackfathom-Gezeitenpriesterinnen außerhalb des Höhleneingangs an der Küste von Eschental tragen sie bei sich.",al={"außerhalb von blackfathom","eschental hirnstämme","lassen gegner an der oberfläche sie fallen"}}},fx={["3ff1da04"]={q="Was ist ein Verderbter Hirnstamm?",a="Ein Verderbter Hirnstamm ist ein anatomisches Exemplar, das von den Satyrn und Naga geerntet wurde, die in und um die Tiefschwarze Grotte hausen. Beide Völker waren einst Nachtelfen, deren Körper und Geist durch dämonische Pakte oder uralte, schattenhafte Tiefen gewaltsam verändert wurden. Diese Hirnstämme tragen die physischen Merkmale dieser magischen Verformung, was sie zu wertvollen anatomischen Objekten für Gelehrte macht, die untersuchen, wie dunkle Zauberei sterbliches Fleisch verkrümmt.",al={"was ist ein verderbter hirnstamm","gegenstand verderbter hirnstamm","hintergrund zu verderbtem hirnstamm"}},["53f0c38a"]={q="Woher stammt ein Verderbter Hirnstamm?",a="Diese Hirnstämme stammen von den Fallenroot-Satyrn und den Blackfathom-Naga, die die unterirdischen Grotten und Ruinen um die Tiefschwarze Grotte entlang der Küste von Eschental bewohnen. Anstatt hergestellte Gegenstände zu sein, sind sie biologische Überreste von Kreaturen, die über Jahrtausende durch Verderbnis, Teufelsmagie und dunkle Transformationen verformt wurden.",al={"woher stammen verderbte hirnstämme","wer lässt den verderbten hirnstamm fallen","ursprung des verderbten hirnstamms"}}},fp="20,272,25.297.0,18.354.0,44.165.0,36.99.0,58.168.0,60.126.0"}
P.entries["item:corrupted-kor-gem"] = {n="Verderbter Koredelstein",s="Nahe der Tiefschwarzen Grotte verderben die Riten der Naga Kor-Edelsteine. Zauberer schätzen ihre arkane Kraft, doch die Verderbnis muss getilgt werden, bevor ein Edelstein für rechtschaffene Schmiedekunst verwendet werden kann.",h="Nahe der Tiefschwarzen Grotte verderben die Riten der Naga Kor-Edelsteine.",kw={"tiefschwarze grotte","verderbter koredelstein","kor-edelstein","naga","reinigung","thundris windweaver","gezeitenpriesterin"},ang={["class:Paladin"]="Als Paladin müsst Ihr einen Kor-Edelstein bergen und reinigen, um eine heilige Waffe zu schmieden. Dabei beweist Ihr, dass Ihr dem Bösen entgegentreten und durch Reinigung Dunkelheit in rechtschaffene Stärke verwandeln könnt.",["race:NightElf"]="Als Nachtelf kennt Ihr die Gefahr, die Relikte der Naga für die Dunkelküste bergen. Gelehrte wie Thundris Windwirker bewahren das Wissen, das zur Reinigung der uralten Steine nötig ist."},sec={{t="Gefäße verdorbener Macht",b="Kor-Edelsteine bergen große Mengen an Magie und sind dadurch für Zauberer und verzauberte Schmiede nützlich. Nahe den Ruinen der Tiefschwarzen Grotte beanspruchen Naga-Orakel und Gezeitenpriesterinnen die Steine für ihre Riten. Ihre Verzauberungen verderben jeden Edelstein mit Magie aus dem Meer. Die Verderbnis lässt die schlummernde Kraft des Steins unversehrt, weshalb jene, die einen mächtigen Fokus suchen, noch immer unter den Naga danach suchen."},{t="Reinigung und Schmiedekunst",b="Thundris Windwirker verlangt, dass ein Verderbter Koredelstein gereinigt wird, bevor er zu Jordan Stillbrunn gebracht wird. In Auberdine tilgt der Nachtelf die böse Magie der Naga. Er versichert dem Paladin, dass die Kraft des Edelsteins für das Ritual des Schmieds unversehrt bleibt."}},faq={{q="Wozu dient ein Kor-Edelstein?",a="Kor-Edelsteine speichern arkane Energie für Zauberwirker. Geschickte Schmiede können sie in verzauberte Waffen einsetzen, um Magie zu kanalisieren.",al={"was sind kor-edelsteine","verwendung von kor-edelsteinen","geschichte der kor-edelsteine"}},{q="Wo findet man Verderbte Koredelsteine?",a="Zauberwirker der Naga tragen Verderbte Koredelsteine bei sich, innerhalb und außerhalb der uralten Ruinen der Tiefschwarzen Grotte an der Grenze zwischen Eschental und Dunkelküste. Blackfathom Tide Priestesses und Blackfathom Oracles tragen sie bei sich.",al={"wo findet man verderbte koredelsteine","fundort von kor-edelsteinen","wer lässt kor-edelsteine fallen"}},{q="Warum muss der Edelstein gereinigt werden?",a="Die Riten der Naga erfüllen die Edelsteine mit übler Magie. Bevor ein Edelstein in eine Waffe eingearbeitet werden kann, muss ein Meister der Natur oder des Lichts wie Thundris Windwirker das Böse austreiben.",al={"kor-edelstein reinigen","warum kor-edelstein reinigen","ist der edelstein böse"}},{q="Bleibt die Kraft des Edelsteins bei der Reinigung erhalten?",a="Ja. Thundris Windwirker versichert dem Paladin, dass die Kraft des Edelsteins bei der Reinigung für Jordan Stillbrunns Ritual unversehrt bleibt.",al={"zerstört die reinigung den edelstein","schwächer nach der reinigung"}}},fx={["114a4618"]={q="Was ist ein Verderbter Koredelstein?",a="Ein Verderbter Koredelstein ist ein magisches Gefäß, das ursprünglich dazu gedacht war, rohe arkan- oder zauberwirkende Energie zu speichern, aber durch dunkle Zauberei verdreht wurde. Naga-Zauberwirker haben den Stein mit ihrer eigenen abscheulichen Kraft durchdrungen und ein ansonsten neutrales Leitmedium in ein verderbtes Relikt verwandelt, das vor bösartiger Energie strotzt.",al={"was ist ein verderbter koredelstein","informationen zum verderbten koredelstein","erzählt mir mehr über den verderbten koredelstein"}},["1218ae71"]={q="Woher stammt ein Verderbter Koredelstein und wer hat ihn hergestellt?",a="Während Koredelsteine ursprünglich als Leitmedien für Zauberwirker zur Speicherung magischer Energie hergestellt wurden, werden diese verderbten Versionen von den Naga gehalten und verändert, die um die Tiefschwarze Grotte im nordwestlichen Eschental hausen. Naga-Priesterinnen und Orakel haben die Edelsteine mit ihrer eigenen üblen Magie gesättigt und sie in Werkzeuge für dunkle Rituale verwandelt.",al={"wer fertigte den verderbten koredelstein","ursprung des verderbten koredelsteins","woher kommt der koredelstein"}},["1d7ce70e"]={q="Warum möchte jemand einen Verderbten Koredelstein haben?",a="Heilige Paladine suchen auf Geheiß des Schmieds Jordan Stillbrunn nach dem Edelstein, um beim Schmieden einer Waffe der Rechtschaffenheit zu helfen, obwohl er zuerst von Thundris Windwirker von seiner bösen Magie gereinigt werden muss. Seine Fähigkeit, magische Energie zu speichern, macht ihn wertvoll für rituelle Handwerkskunst, sobald er ordnungsgemäß gereinigt wurde.",al={"warum den verderbten koredelstein beschaffen","wer will den verderbten koredelstein","warum brauche ich den koredelstein"}}},fp="17,173,24.365.0,25.250.1,27.119.0,35.213.0,29.158.0,42.119.0"}
P.entries["item:cougar-claws"] = {n="Pumaklauen",s="In Mulgores zentralen Ebenen sammeln Taurenjäger Pumaklauen für ein Läuterungsritual. Die Klauen stammen von Flachlandcougars, die zu den Spitzenjägern des Graslands zählen.",h="In Mulgores zentralen Ebenen sammeln Taurenjäger Pumaklauen für ein Läuterungsritual.",kw={"läuterungstotem","pumaklauen","flachlandcougar","mulgore","mull donnerhorn","thunderhorn totem"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass die Essenz heimischer Raubtiere mit den Geistern der Ebenen verbunden bleibt. Sie kann deren Kraft in reinigende Schutzzauber und Läuterungstotems tragen.",["race:Tauren"]="Das Sammeln von Pumaklauen lehrt junge Tauren, dass die Jagd dem Gleichgewicht und spirituellen Bedürfnissen dient. Diese Lehre steht im Gegensatz zur Verschmutzung durch Goblinunternehmen."},sec={{t="Ein Gefäß natürlichen Gleichgewichts",b="Flachlandcougars jagen in Mulgores Grasland ihrem Instinkt folgend. Für die Tauren ist das Sammeln ihrer Klauen weder sinnloses Abschlachten noch Trophäenjagd. Dabei sammeln sie den natürlichen Geist der Tiere.\n\nAls Goblinbetriebe die angestammten Gewässer der Ebenen entweihen, bittet Mull Donnerhorn junge Jäger, Pumaklauen und Präriepirscherklauen zu sammeln. Die Tauren weben die reinen Jagdinstinkte heimischer Tiere in ein Ritualtotem ein. Es soll Giftstoffe und üble Zauberei aus dem vergifteten Brunnen der Donnerhörner tilgen."}},faq={{q="Wofür werden Pumaklauen verwendet?",a="Mull Donnerhorn verwendet Pumaklauen zusammen mit Pirscherklauen, um das Läuterungstotem der Donnerhörner herzustellen. Die Tauren weben den Geist heimischer Raubtiere in Ritualgegenstände ein, um von der Goblinindustrie vergiftete Brunnen zu reinigen.",al={"pumaklauen verwendung","warum pumaklauen sammeln","pumaklauen zweck"}},{q="Woher stammen Pumaklauen?",a="Flachlandcougars durchstreifen die wogenden Ebenen von Mulgore, besonders östlich und westlich vom Dorf der Bluthufe. Von ihnen stammen die Pumaklauen.",al={"wo pumaklauen bekommen","pumaklauen herkunft","wer lässt pumaklauen fallen"}},{q="Warum braucht Mull Donnerhorn Raubtierklauen, um einen Brunnen zu reinigen?",a="Die schamanischen und druidischen Traditionen der Tauren ehren die Reinheit der Jagd wilder Tiere. Heimische Raubtiere leben im Gleichgewicht mit dem Land, anders als Goblins, die es ausbeuten und entweihen. Ihre Essenz kann künstlicher Verderbnis entgegenwirken.",al={"warum raubtierklauen","mull klauen grund","totem raubtierklauen"}},{q="Sind Pumaklauen noch für etwas anderes nützlich?",a="Außer zur Herstellung des Ritualtotems für den Brunnen der Donnerhörner haben Pumaklauen keinen besonderen Verwendungszweck. Üblicherweise werden sie an örtliche Händler verkauft.",al={"weitere verwendungen pumaklauen","pumaklauen verkaufen"}}},fx={ad1b83a1={q="Was sind Pumaklauen?",a="Dies sind die natürlichen Krallen, die von den Pfoten der Flachland-Pumas stammen, die durch die Ebenen von Mulgore streifen. Anstatt bloße Trophäen zu sein, werden diese Klauen von Tauren-Schamanen als Symbole der natürlichen Jagd angesehen, die das reine und unberührte Gleichgewicht der Bestien verkörpern, die durch die Wildnis streifen.",al={"was sind pumaklauen","hintergrund zu pumaklauen","was sind diese klauen"}}},fp="12,169,27.517.0,31.208.0,32.131.0,64.221.0,42.144.0"}
P.entries["item:courser-eye"] = {n="Rennerauge",s="Im Hochland des Steinkrallengebirges werden Renner für ein Gebräu gejagt, das Hexendoktor Jin'Zil Waldmagie nennt. In Malaka'jin verlangt er viele Augen für seine Mixtur.",h="Im Hochland des Steinkrallengebirges werden Renner für ein Gebräu gejagt, das Hexendoktor Jin'Zil Waldmagie...",kw={"geweihter renner","rennerauge","waldmagie","great courser","jin'zil","malaka'jin","steinkrallengebirge"},ang={["race:NightElf"]="Als Nachtelf könnt Ihr die Tötung der Renner für die grausamen Experimente eines Hexendoktors an gefangenen Nachtelfen als Affront gegen Eure Ehrfurcht vor der Natur empfinden.",["race:Troll"]="Als Troll wisst Ihr, dass Jin'Zils grobe Verwendung von Tierteilen eine dunklere, pragmatische Seite der Trollalchemie und der Mojokunst gegen die Feinde der Horde widerspiegelt."},sec={{t="Die Mixtur eines Trolls",b="Hexendoktor Jin'Zil mischt in Malaka'jin Stammesgebräue, um die Nachtelfen zu bekämpfen, die um die Region streiten. Hirschaugen sind im Voodoo und in der Volksalchemie üblich, doch Jin'Zil verlangt dreißig Renneraugen auf einmal. Das ist weit mehr, als gewöhnliche Zauberei erfordert.\n\nEr vermischt die Augen mit Feendrachenschuppen, Harz und Katzenschnurrhaaren. Das Gebräu ist für die gefangenen Nachtelfen bestimmt, die im hinteren Teil seiner Höhle in Käfigen gehalten werden."}},faq={{q="Wo findet man Renneraugen?",a="Geweihte Renner und Great Coursers durchstreifen die höheren Lagen des Steinkrallengebirges. Man findet sie besonders in der Nähe des Mirkfallonsees und des Steinkrallengipfels.",al={"renneraugen fundorte","wo renneraugen bekommen","wie renneraugen bekommen"}},{q="Warum braucht Hexendoktor Jin'Zil so viele Augen?",a="Jin'Zil sagt, ein ordentliches Gebräu könne niemals zu viele Augen enthalten. Für seine Mixtur, die er Waldmagie nennt, vermischt er sie mit Teilen heimischer Tiere.",al={"warum dreißig augen","warum braucht jinzil augen","was macht jinzil mit renneraugen"}},{q="Was geschieht, wenn Jin'Zil seinen Waldmagietrank fertigstellt?",a="Jin'Zil will sein Waldmagiegebräu an den gefangenen Nachtelfen anwenden, die in seiner Höhle in Käfigen sitzen. Was aus ihnen wird, zeigt sich, wenn er das Experiment durchführt.",al={"jinzil waldmagie ergebnis","was geschieht mit den gefangenen in malakajin"}}},fx={["5cdf5ac9"]={q="Was ist ein Rennerauge?",a="Ein Rennerauge ist ein alchemistisches Reagenz, das von den heimischen hirschartigen Renngestalten geerntet wird, die im Steinkrallengebirge umherstreifen. Für die meisten Waldbewohner sind sie lediglich Teil der lokalen Tierwelt, aber in den Händen eines gerissenen Praktikers dienen diese zahlreichen Augen als Rohzutat für wirkungsvolle Gebräue.",al={"was ist ein rennerauge","gegenstand rennerauge","was sind renneraugen"}},a4aa468a={q="Woher stammt ein Rennerauge?",a="Diese Augen werden direkt von den geweihreichen Renngestalten und großen Renngestalten gesammelt, die im Steinkrallengebirge grasen, insbesondere um den Mirkfallonsee und in der Nähe vom Steinkrallengipfel. Sie sind natürliche Teile, die von den wilden Bestien des Gebirges stammen, anstatt hergestellte oder verzauberte Artefakte zu sein.",al={"woher stammen renneraugen","wer fertigte das rennerauge","ursprung des rennerauges"}}},fp="11,152,20.401.1,29.153.0,48.149.1,60.157.1"}
P.entries["item:covert-ops-pack"] = {n="Geheimdienstpack",s="Im Steinkrallengebirge nutzen Agenten der Allianz das Geheimdienstpack, um Anlagen der Venture Company zu sabotieren und ihre Pläne zu stehlen. Seine Sprengladungen und Baupläne zielen auf die Arbeiten des Unternehmens in der Scherwindklippe ab.",h="Im Steinkrallengebirge nutzen Agenten der Allianz das Geheimdienstpack, um Anlagen der Venture Company zu...",kw={"geheimdienstpack","felskesselsee","ng-5-sprengstoff","plan alpha","plan beta","venture co","die scherwindklippe"},ang={["faction:Alliance"]="Als Mitglied der Allianz unterstützt Ihr den Kampf der Schildwachen gegen die kommerzielle Verwüstung im Steinkrallengebirge.",["profession:Engineering"]="Für Ingenieure richtet das Pack gnomischen Erfindergeist gegen die Industrie der Goblins. Seine maßgeschneiderten NG-5-Sprengladungen helfen aufzudecken, wie die Maschinen der Venture Company funktionieren."},sec={{t="Geplante Sabotage",b="Das Geheimdienstpack bringt Sprengladungen und Pläne ins Gebiet der Venture Company. Roter und blauer NG-5-Sprengstoff kommen mit Fernzündern, während Plan Alpha und Plan Beta die Angriffe anleiten. Die Sprengladungen zielen auf das Sägewerk am Felskesselsee und die östliche Mine. Wenn Goblins herbeieilen, um Brände zu löschen und beschädigte Maschinen zu untersuchen, kann ein Infiltrator im Durcheinander eindringen und Dokumente und Baupläne entwenden."},{t="Gemeinsame Interessen",b="Die Schildwachen der Nachtelfen und die Ingenieure der Allianz im Steinkrallengebirge profitieren beide vom Geheimdienstpack. Seine Explosionen und die gestohlenen Pläne behindern Kahlschlag und Grabungen am heiligen Berghang. Die Konstruktionspläne der Venture Company verraten außerdem, wie die schweren Maschinen der Goblins funktionieren. Sie zeigen, wo die Maschinen versagen können, und liefern den Ingenieuren der Allianz Ideen, die sie für ihre eigenen Entwürfe anpassen können."}},faq={{q="Was steckt im Geheimdienstpack?",a="Das Geheimdienstpack enthält roten und blauen NG-5-Sprengstoff mit passenden Fernzündern sowie schriftliche Anweisungen für Plan Alpha und Plan Beta.",al={"inhalt des geheimdienstpacks","was enthält das pack","gegenstände im geheimdienstpack"}},{q="Welchen taktischen Zweck erfüllt der Sprengstoff?",a="Der Sprengstoff sorgt an den Arbeitsstätten der Venture Company für lautstarke Ablenkung. Während die Wachleute fortgelockt werden, kann ein Agent ungesehen ins Sägewerk und in die Mine eindringen.",al={"warum bomben einsetzen","wozu dient ng-5-sprengstoff","alpha beta sprengung"}},{q="Welche Informationen soll dieser Einsatz beschaffen?",a="Der Einsatz soll Konstruktionspläne der Venture Company aus dem Sägewerk südlich des Felskesselsees beschaffen, dann Briefe der Geschäftsleitung aus der Scherwindmine am östlichen Ende der Klippe.",al={"was stehlen wir","einsatzziel des packs","ziele verdeckter einsätze"}},{q="Wem nützen die mit diesem Pack beschafften Unterlagen?",a="Die Schildwachen der Nachtelfen und die Ingenieure der Allianz profitieren beide. Sabotage behindert die Abholzung, während Ingenieure die Baupläne nach Schwachstellen der Schredder der Venture Company und nach Ideen für ihre eigene Technik durchforsten.",al={"wer will die pläne der venture company","für wen ist das pack","schildwachen verdeckte einsätze"}}},fx={["8d787d42"]={q="Was ist das Geheimdienstpack?",a="Das Geheimdienstpack ist ein spezialisiertes Sabotage-Set, das für Infiltrationsoperationen in Die Scherwindklippe vorbereitet wurde. Es enthält farbcodierte NG-5-Sprengstoffe, passende Fernzünder und detaillierte Missionspläne, die darauf ausgelegt sind, zeitlich abgestimmte Ablenkungen zu inszenieren, während wichtige Dokumente der Venture Company direkt unter deren Nase geborgen werden.",al={"was ist das geheimdienstpack","informationen zum geheimdienstpack","sabotage-set geheimdienstpack"}},["23fc442d"]={q="Woher stammt das Geheimdienstpack und wer hat es hergestellt?",a="Das Pack wurde von einem Tüftler der Allianz zusammengestellt, der die Nachtelf-Wächterinnen im Steinkrallengebirge unterstützt. Durch die Kombination von Präzisionstechnik mit taktischer Sprengung fertigten sie die flüchtigen NG-5-Ladungen und Fernzünder speziell an, um operative Schläge gegen Installationen der Venture Company zu unterstützen.",al={"wer fertigte das geheimdienstpack","woher stammt das geheimdienstpack","schöpfer des geheimdienstpacks"}},ca775219={q="Warum wird das Geheimdienstpack benötigt?",a="Ein direkter Angriff auf befestigte Standorte der Venture Company wie ihr Sägewerk und ihre Mine wäre selbstmörderisch oder würde die Wachen alarmieren, bevor Vital Intelligence beschlagnahmt werden kann. Das Pack bietet die Werkzeuge, um ferngezündete Sprengsätze zu platzieren und anderswo ein kontrolliertes Chaos auszulösen, wodurch Verteidiger weggelockt werden, damit Ihr hineinschlüpfen und deren technische Pläne und Korrespondenz bergen könnt.",al={"warum brauche ich das geheimdienstpack","warum geheimdienstpack","zweck des geheimdienstpacks"}}},fp="15,189,18.402.0,25.372.0,35.149.0,47.156.0,45.173.0,58.214.0"}
P.entries["item:coyote-jawbone"] = {n="Coyote Jawbone",s="Ein Koyote-Kieferknochen kennzeichnet einen im Ödland gejagten crag coyote. Neeka Bloodscar sucht sie, damit die Bestien nicht Kargaths Nahrungsvorräte plündern.",h="Ein Koyote-Kieferknochen kennzeichnet einen im Ödland gejagten crag coyote.",kw={"ödland","coyote jawbone","koyoten-diebe","crag coyote","nahrungsvorräte","kargath","neeka bloodscar"},sec={{t="Ein Andenken aus Kargath",b="Crag coyotes streifen durch die staubigen Ebenen des Ödlands, und einige schleichen sich auf der Suche nach Nahrung nach Kargath. Neeka Bloodscar bittet Euch, ihr ihre Kieferknochen zu bringen. Sie sagt, die Bestien seien zähe Beute, und die Jagd könne zeigen, ob Ihr in diesem rauen Land überleben könnt."}},faq={{q="Was ist ein Coyote Jawbone?",a="Ein Coyote Jawbone stammt von einem crag coyote im Ödland. Neeka Bloodscar bittet in Kargath darum.",al={"koyotenknochen","kieferknochen-gegenstand","koyotenkiefer"}},{q="Warum will Neeka die Kieferknochen?",a="Crag coyotes schleichen sich nach Kargath und stehlen Reste aus den Nahrungsvorräten. Neeka will ihre Kieferknochen als Beweis für die Jagd, die dabei hilft, die Coyoten fernzuhalten.",al={"warum kieferknochen","neeka will knochen","wofür"}},{q="Wo finde ich die Coyoten?",a="Crag coyotes streifen durch die staubigen Ebenen des Ödlands.",al={"koyoten-fundort","wo coyoten","ödland-coyoten"}},{q="Wer ist Neeka Bloodscar?",a="Neeka Bloodscar ist in Kargath und bittet um Kieferknochen von crag coyotes, um die Nahrungsvorräte des Außenpostens zu schützen.",al={"neeka","bloodscar","wer will knochen"}},{q="Sind crag coyotes leichte Beute?",a="Nein. Neeka nennt crag coyotes eine zähe Art und sagt, sie seien keine leichte Beute.",al={"zähe coyoten","zähe beute","koyoten-schwierigkeit"}}},fp="14,144,18.246.0,25.100.0,33.154.0,29.51.0,23.103.0,27.75.0"}
P.entries["item:crag-coyote-fang"] = {n="Crag Coyote Fang",s="Ein Crag Coyote Fang stammt von Kojoten im Ödland. Jarkal Mossmeld in Kargath braucht zehn davon für seine alchemistischen Vorräte.",h="Ein Crag Coyote Fang stammt von Kojoten im Ödland.",kw={"ödland","crag coyote","crag coyote fang","elder crag coyote","feral crag coyote","jarkal mossmeld","rabid crag coyote","reagenz"},sec={{t="Ein Reagenz aus dem Ödland",b="Jarkal Mossmeld, ein Alchemist in Kargath, bittet um Crag Coyote Fangs, um seine Vorräte aufzufüllen. Die Fänge stammen von Crag Coyotes, Elder Crag Coyotes, Feral Crag Coyotes und Rabid Crag Coyotes im Ödland. Er braucht zehn davon sowie Bussardmägen und Felsenelementarsplitter."}},faq={{q="Woher stammen Crag Coyote Fangs?",a="Crag Coyote Fangs stammen von Crag Coyotes, Elder Crag Coyotes, Feral Crag Coyotes und Rabid Crag Coyotes im Ödland.",al={"fundort von crag coyote fangs","kojotenzähne","woher fang"}},{q="Wer braucht Crag Coyote Fangs?",a="Jarkal Mossmeld, ein Alchemist in Kargath, bittet um zehn Crag Coyote Fangs, um seine Vorräte aufzufüllen.",al={"wer braucht fänge","jarkal fänge","für wen fänge"}},{q="Warum braucht Jarkal die Fänge?",a="Jarkal Mossmeld braucht Crag Coyote Fangs als Reagenzien, um seine alchemistischen Vorräte aufzufüllen.",al={"warum fänge","was braucht jarkal","alchemistische vorräte"}},{q="Worum bittet Jarkal noch?",a="Jarkal bittet außerdem um fünf Buzzard Gizzards und fünf Rock Elemental Shards.",al={"weitere reagenzien","was noch jarkal","zutaten aus dem ödland"}}},fp="16,120,18.276.0,37.121.0,28.97.0,31.87.0,30.74.0"}
P.entries["item:crate-of-crash-helmets"] = {n="Kiste mit Sturzhelmen",s="Auf der Schimmernden Ebene brauchen Wizzel Kupferbolz und sein Bruder Helme für ihre Raketenwagen-Testfahrer. Schwere zwergische Siege Engine-Helme sind nach Tausend Nadeln unterwegs, um Piloten vor Gehirnerschütterungen zu schützen.",h="Auf der Schimmernden Ebene brauchen Wizzel Kupferbolz und sein Bruder Helme für ihre Raketenwagen-Testfahrer.",kw={"kiste mit sturzhelmen","illusionenrennbahn","raketenwagen","die schimmernde ebene","siege engine","tausend nadeln","wizzel kupferbolz"},ang={["profession:Engineering"]="Ingenieure kennen das Gleichgewicht zwischen Antrieb und Versagen. Sie wissen, wie wichtig schwere Panzerung ist, wenn Sicherheitsvorkehrungen an zweiter Stelle stehen.",["race:Gnome"]="Als Gnom an der Illusionenrennbahn seht Ihr, dass Gehirnerschütterungen bei Piloten dazugehören, wenn man auf der Salzebene goblinische Rivalen mit Erfindungsreichtum übertrumpfen will."},sec={{t="Sicherheit bei hohem Tempo",b="Gnomische Ingenieure fahren mit Raketenwagen Rennen über die Schimmernde Ebene. Wizzel Kupferbolz und sein Bruder bauen Maschinen, die schneller fahren, als ihre Fahrer lenken können. Unfälle führen bei Testpiloten zu Kopfverletzungen, und Lederkappen reichen nicht mehr aus. Deshalb werden schwere zwergische Siege Engine-Helme über das Meer verschifft, damit die Fahrer bei Bewusstsein und am Leben bleiben."}},faq={{q="Was befindet sich in der Kiste mit Sturzhelmen?",a="Die Kiste enthält schwere Siege Engine-Helme aus zwergischen Militärbeständen. Ihre dicke Panzerung schützt bei Hochgeschwindigkeitstests vor Druckwellen und harten Aufprallen.",al={"kisteninhalt","was sind das für helme","art der sturzhelme"}},{q="Wer braucht diese Helme?",a="Wizzel Kupferbolz und sein Bruder brauchen die Helme an der Illusionenrennbahn auf der Schimmernden Ebene. Ihre Konstruktionen führen bei Testpiloten zu Kopfverletzungen, deshalb brauchen die Fahrer wirksamen Schutz.",al={"wer bekommt die helme","für wen ist die kiste","zielort der helme"}},{q="Warum bauen die Brassbolts Brothers so viele Unfälle?",a="Die Brassbolts Brothers bauen auf Geschwindigkeit und gehen an die Grenzen gnomischer Ingenieurskunst, ohne viel auf stabiles Fahrverhalten zu achten. Ihr Raketenwagen fährt so schnell, dass Zusammenstöße auf der Salzebene fast unvermeidlich sind.",al={"warum bauen sie unfälle","probleme mit raketenwagen","unfälle bei gnomischen rennen"}},{q="Wohin werden die Helme geliefert?",a="Die Helme sind für die Schimmernde Ebene bestimmt, eine weite Salzebene im Südosten von Tausend Nadeln in Kalimdor.",al={"lieferort","wo ist wizzel","wohin werden sie geliefert"}}},fx={["94078cd5"]={q="Woher stammt die Kiste mit Sturzhelmen und wer hat sie hergestellt?",a="Die Kiste wurde von dem Zwergeningenieur Pilot Langbart in Dun Morogh gepackt und bereitgestellt. Langbart sammelte einen Vorrat an robusten zwergischen Belagerungsmaschinenhelmen, um seinen alten Freunden, den Brassbolts Brothers, zu helfen, die für ihre Testpiloten in der schimmernden Ebene dringend Kopfschutz benötigen.",al={"wer stellte kiste mit sturzhelmen her","woher stammt die kiste mit sturzhelmen","ursprung der sturzhelme"}}},fp="22,209,21.345.0,42.177.0,24.189.0,49.212.0,38.109.0"}
P.entries["item:crate-of-ghost-magnets"] = {n="Crate of Ghost Magnets",s="Die Crate of Ghost Magnets lockt Magram-Geister zu einem Sammelplatz im Tal der Knochen. Hornizz Brimbuzzle hofft, dass das eingefangene Geisteroplasma den Zentauren einen guten Preis wert ist.",h="Die Crate of Ghost Magnets lockt Magram-Geister zu einem Sammelplatz im Tal der Knochen.",kw={"crate of ghost magnets","dead goliaths","geistermagnete","geisteroplasma","hornizz brimbuzzle","magram","tal der knochen"},sec={{t="Geisterköder",b="Hornizz Brimbuzzle gibt Euch die Crate of Ghost Magnets für den Einsatz im Tal der Knochen. Zwischen den beiden Dead Goliaths aufgestellt, lockt sie Magram-Geister so nahe heran, dass ihr Geisteroplasma gesammelt werden kann. Hornizz will die seltsame Substanz an die Zentauren verkaufen."}},faq={{q="Was bewirkt die Kiste?",a="Die Crate of Ghost Magnets lockt Magram-Geister im Tal der Knochen zu sich.",al={"kiste mit geistermagneten","wofür sind geistermagnete"}},{q="Wer gibt Euch die Crate of Ghost Magnets?",a="Hornizz Brimbuzzle gibt Euch die Crate of Ghost Magnets.",al={"wo gibt es geistermagnete","hornizz kiste"}},{q="Wo wird die Kiste eingesetzt?",a="Die Kiste wird im Tal der Knochen zwischen den beiden Dead Goliaths eingesetzt.",al={"fundort der geistermagnete","wo die kiste aufstellen"}},{q="Warum will Hornizz Geisteroplasma?",a="Hornizz hofft, Geisteroplasma an die Magram-Zentauren zu verkaufen.",al={"warum geisterplasma sammeln","was macht hornizz"}}},fp="22,190,12.259.0,23.80.0,41.56.0,24.72.0,36.59.0"}
P.entries["item:crate-of-grimtotem-horns"] = {n="Crate of Grimtotem Horns",s="Die Crate of Grimtotem Horns enthält Beweise für den Grimtotem Clan in Feralas. Belgrom Rockmaul in Orgrimmar will hören, was Ihr gefunden habt.",h="Die Crate of Grimtotem Horns enthält Beweise für den Grimtotem Clan in Feralas.",kw={"belgrom rockmaul","crate of grimtotem horns","feralas","grimtotem","grimtotem-hörner","orgrimmar","tal der ehre"},sec={{t="Nachrichten aus Feralas",b="Im Tal der Ehre in Orgrimmar nimmt Belgrom Rockmaul die Crate of Grimtotem Horns entgegen. Ihr habt die Hörner bei der Jagd in Feralas gefunden, wo der Grimtotem Clan Aufmerksamkeit erregt hat. Belgrom will hören, was Ihr gesehen habt, und wird Euch für die Nachricht bezahlen."}},faq={{q="Was ist in der Kiste?",a="Die Kiste enthält Grimtotem-Hörner aus Feralas.",al={"kisteninhalt","hornkiste"}},{q="Wer will die Kiste?",a="Belgrom Rockmaul im Tal der Ehre in Orgrimmar will die Crate of Grimtotem Horns.",al={"wer bekommt die hörner","belgrom kiste"}},{q="Warum will Belgrom die Hörner?",a="Belgrom will hören, was Ihr über den Grimtotem Clan in Feralas gesehen habt.",al={"warum hörner","nachrichten vom grimtotem clan"}},{q="Woher stammen die Hörner?",a="Ihr habt die Grimtotem-Hörner bei der Jagd in Feralas gefunden.",al={"woher die hörner","hörner aus feralas"}},{q="Was bietet Belgrom an?",a="Belgrom sagt, er werde Euch Münzen abzählen, während Ihr ihm vom Grimtotem erzählt.",al={"belgrom belohnung","münzen für hörner"}}},fp="24,139,17.245.0,21.51.0,20.83.0,32.68.0,30.55.0,24.75.0"}
P.entries["item:crate-of-horseshoes"] = {n="Kiste mit Hufeisen",s="In Elwynn bringt die Kiste mit Hufeisen fünfzig eiserne Hufeisen nach Seenhain.",h="In Elwynn bringt die Kiste mit Hufeisen fünfzig eiserne Hufeisen nach Seenhain.",kw={"kiste mit hufeisen","wald von elwynn","goldhain","seenhain","rotkammgebirge","schmied argus","verner gutmark"},ang={["faction:Alliance"]="Kuriere, die Waren zwischen Elwynn und dem Rotkammgebirge befördern, halten die gefährdeten Handelswege des Königreichs offen und versorgen entlegene Garnisonen mit Ausrüstung, obwohl Sturmwind militärische Verstärkung zurückhält.",["profession:Blacksmithing"]="Die Lieferung zeigt den stetigen Bedarf an einfachen Schmiedewaren entlang der Grenzstraßen zwischen den Ortschaften. Seenhain ist auf den Amboss von Goldhain angewiesen, damit seine Zugtiere weiterarbeiten können."},sec={{t="Eine Lieferung nach Seenhain",b="Schmied Argus schmiedete in Goldhain fünfzig neue Hufeisen, packte sie dann in eine Kiste und hämmerte sie zu. Verner Gutmark bestellte sie für Seenhain, wo der Druck durch Gnolle und Orks die örtlichen Handwerker bei lebenswichtigen Metallwaren von Elwynn abhängig macht. Die Lieferung deckt Verners dringenden Bedarf an Ausrüstung, und Argus legt eine mahnende Rechnung bei, damit der Handwerker aus dem Rotkammgebirge weiß, dass das Überleben an der Grenze einen hohen Preis hat."}},faq={{q="Was befindet sich in der Kiste mit Hufeisen?",a="Schmied Argus schmiedete in Goldhain fünfzig eiserne Hufeisen und packte sie in die Kiste. Eine beigefügte Rechnung fordert den Käufer zur Zahlung auf.",al={"inhalt der kiste","was ist in der kiste","inhalt der kiste mit hufeisen"}},{q="Wer hat diese Kiste bestellt?",a="Verner Gutmark gab die Hufeisen in Auftrag. Er ist Händler und Handwerker in Seenhain im Rotkammgebirge und braucht sie, um seine Arbeit und die örtlichen Zugtiere im Einsatz zu halten.",al={"wer will die hufeisen","verner hufeisen","empfänger der kiste"}},{q="Wer hat diese Hufeisen gefertigt?",a="Schmied Argus, der Schmied von Goldhain im Wald von Elwynn, schmiedete die Hufeisen, packte die Kiste und bereitete sie für die Lieferung vor.",al={"wer hat die hufeisen gemacht","schmied in goldhain","schmied argus"}},{q="Warum braucht Verner Hufeisen aus Elwynn?",a="Feindliche Schwarzfelsorcs und Gnolle belagern Seenhain, wodurch die Grenzsiedlung abgeschnitten ist und es ihr an Rohstoffen und Handelswaren mangelt. Die örtlichen Arbeiter müssen grundlegende Vorräte aus sichereren Siedlungen wie Goldhain herbeischaffen.",al={"warum braucht das rotkammgebirge hufeisen","warum hufeisen einführen","versorgungsproblem in seenhain"}}},fx={["50a21bee"]={q="Was ist die Kiste mit Hufeisen?",a="Die Kiste mit Hufeisen ist eine schwere hölzerne Lieferkiste, die fünfzig neu geschmiedete Hufeisen enthält, zusammen mit einer Rechnung. Schmied Argus bereitete die Lieferung in Goldhain vor, um einen Auftrag von Verner Gutmark zu erfüllen, der in der Nähe in Seenhain dringend neues Eisen benötigt, um Zugtiere und Reittiere zu beschlagen.",al={"was ist die kiste mit hufeisen","hintergrund zur kiste mit hufeisen","wofür sind die hufeisen"}}},fp="19,73,23.425.0,39.132.0,23.179.0,29.124.0,44.219.0"}
P.entries["item:crate-of-inn-supplies"] = {n="Kiste mit Gasthausvorräten",s="Im Coldridgetal werden Reisende gebraucht, die die Kiste mit Gasthausvorräten nach Kharanos bringen. Troggs haben den Gebirgspass versperrt, sodass die Brauerei Donnerbräu auf ihre Hilfe angewiesen ist.",h="Im Coldridgetal werden Reisende gebraucht, die die Kiste mit Gasthausvorräten nach Kharanos bringen.",kw={"ambossar","coldridge","kiste","frosthammer","hands","kharanos","federspross","vorräte","tannok","troggs"},ang={["race:Dwarf"]="Als junger Zwerg leistet Ihr mit dem Transport dieser Vorräte Euren ersten Dienst jenseits des Coldridgetals. Ihr trotzt dem von Troggs verstopften Pass, um Euren Verwandten in Kharanos zu helfen.",["race:Gnome"]="Als neu angekommener Gnom könnt Ihr Euch mit dem Transport von Hands Federspross' Paket auf praktische Weise das Wohlwollen der einheimischen Zwerge verdienen, die die Gasthäuser von Dun Morogh betreiben."},sec={{t="Durch den Troggpass",b="Nahe Ambossar wartet die Kiste mit Gasthausvorräten auf einen sicheren Transport durch die Eisklamm. Troggs haben den Weg abgeschnitten und hindern zivile Kuriere daran, Waren zu befördern, bis die Gebirgsjäger die Straße freimachen. Hands Federspross hat Tavernenvorräte für Tannok Frosthammer in Kharanos gepackt, wo die Vorräte gebraucht werden."}},faq={{q="Was ist in der Kiste?",a="Die Kiste enthält allgemeine Tavernenvorräte für das Gasthaus in Kharanos, wo Reisende und Einheimische Wärme suchen.",al={"kisteninhalt","inhalt der gasthausvorräte","was ist in der kiste"}},{q="Wer schickt die Kiste nach Kharanos?",a="Hands Federspross packt die Kiste nahe Ambossar und bittet Reisende, die das Coldridgetal verlassen, sie durch den Gebirgspass zu tragen.",al={"wer gibt die kiste","hands federspross","absender"}},{q="Warum konnte der übliche Kurier sie nicht zustellen?",a="Troggs haben die Eisklamm überrannt und machen sie für gewöhnliche Kuriere ohne Geleitschutz der Gebirgsjäger zu gefährlich. Reisende, die sich hindurchkämpfen können, sind die unmittelbare Hoffnung des Gasthauses auf die Lieferung der Vorräte.",al={"warum kann hands sie nicht liefern","pass versperrt","warum einen abenteurer einsetzen"}},{q="Wer nimmt die Vorräte entgegen?",a="Tannok Frosthammer, der Gehilfe des Gastwirts in der Brauerei Donnerbräu in Kharanos, nimmt das Paket entgegen.",al={"wer bekommt die kiste","tannok frosthammer","gastwirt in kharanos"}}},fx={e676223e={q="Warum wird die Kiste mit Gasthausvorräten in Kharanos benötigt?",a="Tannok Frosthammer, Gehilfe im Gasthaus von Kharanos, wartet auf frischen Nachschub aus dem Coldridgetal, während durch den Trogg-Aufstand kaum Nachrichten durchkamen. Da die regulären Kurierrouten abgeschnitten sind, muss das Gasthaus diese Vorräte durch den Pass erhalten, um Reisende und Einheimische am Kamin versorgen zu können.",al={"warum will tannok die kiste","warum werden gasthausvorräte benötigt","zweck der kiste mit gasthausvorräten"}},bc2f2ebd={q="Was ist die Kiste mit Gasthausvorräten?",a="Sie enthält Waren, die Hands Federspross an der Eisklamm für die Brauerei Donnerbräu und das Gasthaus drüben in Kharanos gepackt hat. Weil Troggs den Pass aus dem Coldridgetal versperrt hatten, blieb die Lieferung liegen, bis ein kräftiger Reisender sie hindurchtragen konnte.",al={"was ist die kiste mit gasthausvorräten","kiste mit gasthausvorräten questgegenstand","was ist diese kiste"}}},fp="21,187,22.318.0,25.104.0,32.133.0,43.198.0,26.109.0"}
P.entries["item:crate-of-lightforge-ingots"] = {n="Kiste mit Lichtschmiedeblöcken",s="In Sturmwind trägt die Kiste mit Lichtschmiedeblöcken die Hoffnung des Dämmerwalds gegen Morbent Fel.",h="In Sturmwind trägt die Kiste mit Lichtschmiedeblöcken die Hoffnung des Dämmerwalds gegen Morbent Fel.",kw={"kiste","der zwergendistrikt","grimand elmore","barren","eisen","lightforge","morbent fel","sturmwind"},ang={["class:Paladin"]="Diese Barren sprechen auf das Heilige Licht an. Daraus geschmiedete Waffen sind ein natürlicher Fluch für Nekromanten und ihre untoten Diener.",["profession:Blacksmithing"]="Die Verarbeitung von Lightforge Iron ist eine seltene Kunst. Selbst Grimand Elmore bekommt das heilige Metall mitunter jahrelang nicht in die Hände."},sec={{t="Eine heilige Lieferung",b="Lightforge Iron ist selten, und sein geweihtes Metall kanalisiert heilige Macht gegen dunkle Wesen. Morbent Fels Schutz lässt gewöhnlichen Stahl abprallen, also setzt der Dämmerwald gegen den Nekromanten auf diese Barren. Nur ein Handwerker, der die Beschaffenheit des Metalls kennt und seine heilige Natur achtet, kann es verarbeiten."},{t="Der Waffenschmied von Sturmwind",b="Die Kiste ist für Grimand Elmore bestimmt, einen geschickten zwergischen Waffenschmied im Zwergendistrikt von Sturmwind. Er hat seit Jahren nicht mehr mit Lightforge Iron gearbeitet, willigt aber ein, daraus eine geweihte Waffe zu schmieden. Die Waffe soll Morbent Fels Schutz durchbrechen und ihn niederstrecken."}},faq={{q="Was befindet sich in dieser Kiste?",a="Die Kiste enthält geweihtes Lightforge Iron für eine Waffe, die Morbent Fels magischen Schutz durchdringen soll.",al={"kisteninhalt","was ist lightforge iron","was ist in der kiste"}},{q="Wer soll diese Kiste erhalten?",a="Die Kiste ist für Grimand Elmore bestimmt, einen geschickten zwergischen Waffenschmied im Zwergendistrikt von Sturmwind.",al={"wem die kiste bringen","empfänger der kiste","wohin kommt die kiste"}},{q="Warum wird Lightforge Iron benötigt?",a="Morbent Fels Schutz lässt gewöhnlichen Stahl abprallen. Lightforge Iron kanalisiert heilige Macht gegen dunkle Wesen.",al={"warum lightforge iron","warum kein normales eisen","morbent fels schwäche"}},{q="Wer hat die Kiste hergestellt?",a="Glorin Stahlbraue hat das Lightforge Iron, das Ihr geborgen habt, für die Lieferung an Grimand Elmore in Sturmwind in die Kiste gepackt.",al={"wer hat die barren eingepackt","wer hat die kiste gegeben"}}},fp="26,89,17.292.0,28.272.1,26.104.0,38.101.0,30.111.0,22.117.0"}
P.entries["item:crate-with-holes"] = {n="Kiste mit Löchern",s="In Ratschet bereitet Mebok Mizzyrix eine Kiste für einen Snufflenose Gopher vor.",h="In Ratschet bereitet Mebok Mizzyrix eine Kiste für einen Snufflenose Gopher vor.",kw={"blaulaubknollen","kiste mit löchern","mebok mizzyrix","ratschet","kral der klingenhauer","snufflenose gopher"},sec={{t="Ein Schnüffler in der Kiste",b="Mebok Mizzyrix schickt abgerichtete Snufflenose Gophers in den Kral der Klingenhauer, um Blaulaubknollen zu finden. Die Erdhörnchen können einen Abenteurer nicht zu Fuß durch das Brachland begleiten, also setzt Mebok jedes in eine Holzkiste mit Luftlöchern. In der Festung der Stacheleber wird die Kiste geöffnet. Das Erdhörnchen folgt seiner feinen Nase zu den vergrabenen Knollen."}},faq={{q="Was ist in der Kiste mit Löchern?",a="Ein lebender Snufflenose Gopher, den Mebok Mizzyrix abgerichtet hat, reist darin mit. Löcher in der Kiste lassen ihn auf der Reise durch das Brachland atmen.",al={"was ist in der kiste","kisteninhalt","was ist darin"}},{q="Wo bekomme ich die Kiste mit Löchern?",a="Nehmt eine Kiste vom Stapel neben Mebok Mizzyrix in Ratschet, der Hafenstadt an der Ostküste des Brachlands.",al={"fundort der kiste","wo kiste mit löchern finden","meboks kiste"}},{q="Wie funktioniert die Kiste im Kral der Klingenhauer?",a="Öffnet die Kiste im Kral der Klingenhauer, um den Snufflenose Gopher freizulassen. Lenkt ihn mit einem Schnüffelnasenleitstecken, und er wird mit seiner Nase unter der Erde vergrabene Blaulaubknollen finden.",al={"wie kiste mit löchern benutzen","kiste benutzen","erdhörnchen beschwören"}},{q="Warum sind Blaulaubknollen ohne das Erdhörnchen so schwer zu finden?",a="Blaulaubknollen wachsen tief unter der Erde zwischen den Wurzeln des Krals der Klingenhauer, wo man sie mit bloßem Auge nicht sieht. Snufflenose Gophers können sie aus fünfzig Schritt Entfernung riechen.",al={"warum erdhörnchen nötig","knollen finden","fundort der knollen"}}},fx={["08415caf"]={q="Warum will Mebok Mizzyrix die Kiste mit Löchern zurückhaben?",a="Mebok erwartet die Rückgabe der Kiste zusammen mit seinem Kommandostab und den geernteten Blaulaubknollen, da trainierte Schnüffelnasengophers eine Investition sind, die er sich nicht leisten kann zu verlieren. Die Knollen sind weltweit eine außergewöhnlich seltene Delikatesse, und ohne seine trainierten Gophers und deren spezialisierte Transportkisten ist es praktisch unmöglich, sie tief im Kral der Klingenhauer vergraben zu finden.",al={"warum will mebok die kiste","warum wird die kiste mit löchern gesucht","zweck der kiste mit löchern"}},["39b6cc8f"]={q="Woher stammt die Kiste mit Löchern und wer hat sie hergestellt?",a="Die Kiste wird von Mebok Mizzyrix bereitgestellt, einem geschäftstüchtigen Goblinhändler, der in der Hafenstadt Ratschet im Brachland ansässig ist. Um die wertvollen Wurzeln zu ernten, die in der Festung der Stacheleber im Kral der Klingenhauer verborgen sind, ersann Mebok eine Möglichkeit, ausgebildete Rüsselschnüffler sicher ins Einsatzgebiet zu transportieren. Dazu ließ er Löcher in gewöhnliche Versandkisten schlagen, damit seine geschätzten Tiere während des Transports atmen können.",al={"herkunft der kiste mit löchern","wer stellte die kiste mit löchern her","woher stammt die kiste mit löchern"}}},fp="16,68,18.332.0,36.136.0,36.105.0,46.184.0,59.148.0"}
P.entries["item:crawler-leg"] = {n="Kriecherbein",s="An der nebligen Küste der Dunkelküste verlieren Krabben Beine, für die die meisten Reisenden keine Verwendung haben. Ihre zähen Gliedmaßen können das Kommunikationsgerät eines Gnoms am Laufen halten.",h="An der nebligen Küste der Dunkelküste verlieren Krabben Beine, für die die meisten Reisenden keine Verwendung...",kw={"auberdine","buzzbox 827","kriecherbein","dunkelküste","riffkriecher","tide crawler","hexknall kurbeldreh"},ang={["profession:Engineering"]="Hexknall Kurbeldreh nutzt Krabbenbeine als behelfsmäßige Hebel und zeigt damit, wie Gnome vor Ort mit Materialien aus der Umgebung anstelle gewöhnlicher Metallgestänge improvisieren.",["race:Gnome"]="Als Gnom seht Ihr vielleicht an einem Strand aggressive Krustentiere und erkennt in ihren Beinen mögliche Bauteile für ein empfindliches Fernkommunikationsnetz."},sec={{t="Gnomischer Erfindergeist an der Küste",b="Die Krabben der Dunkelküste hinterlassen kräftige Beine am Ufer, von Zwerggezeitenkriechern bis hin zu Riffkriechern. Die Nachtelfenschildwachen schenken ihnen wenig Beachtung. Doch der Gnomeningenieur Hexknall Kurbeldreh hat eine Verwendung für sie gefunden.\n\nVon Auberdine aus entwarf er Prototypen von Fernkommunikationsgeräten namens Dröhnkisten, die mit improvisierten Teilen aus der Umgebung funktionieren sollten. Kriecherbeine haben gegliederte Gelenke und widerstandsfähiges Chitin, die für die nötige Reibung und Hebelwirkung sorgen, um Buzzbox 827 am Ufer südlich der Stadt zu reparieren."}},faq={{q="Wofür werden Kriecherbeine verwendet?",a="Kriecherbeine helfen bei der Reparatur von Buzzbox 827, einer experimentellen Kommunikationsstation an der Küste der Dunkelküste südlich von Auberdine. Der gnomische Erfinder Hexknall Kurbeldreh stellte sie dort auf.",al={"kriecherbein verwendung","warum kriecherbeine behalten","dröhnkiste kriecherbein"}},{q="Woher stammen Kriecherbeine?",a="Kriecherbeine stammen von Krabben an den Stränden der Dunkelküste. Dazu gehören Zwerggezeitenkriecher, Young Reef Crawlers, Encrusted Tide Crawlers und Riffkriecher.",al={"kriecherbein herkunft","welche krabben lassen kriecherbeine fallen","wo kriecherbein finden"}},{q="Warum braucht eine mechanische Dröhnkiste Krabbenbeine?",a="Hexknall Kurbeldreh entwarf seine Maschinen so, dass sie sich vor Ort mit Teilen von Wildtieren aus der Umgebung reparieren lassen. Kriecherbeine haben starre Gelenke und Chitinsegmente, die in die mahlenden Zahnräder der Dröhnkiste passen und ihre Mechanik wieder in Gang bringen.",al={"warum krabben für maschine","dröhnkiste krabbenbeine hintergrund","wie repariert kriecherbein dröhnkiste"}}},fx={bab31e79={q="Was ist ein Kriecherbein?",a="Ein Kriecherbein ist ein abgetrenntes Gliedmaß, das von den verschiedenen Arten von Kriechern geerntet wird, die an den nebelverhangenen Ufern der Dunkelküste entlanghuschen. Mit ihren starren, chitinartigen Panzern und robusten Gelenken sind diese Beine erstaunlich widerstandsfähig und eignen sich für raue, improvisierte mechanische Reparaturen.",al={"was ist ein kriecherbein","gegenstand kriecherbein","über kriecherbeine"}}},fp="11,145,30.488.0,31.178.0,32.155.0,45.214.0"}
P.entries["item:creeper-ichor"] = {n="Krabblersekret",s="In den Wäldern von Hillsbrad liefern Mooskrabbler Krabblersekret für die Königliche Apothekervereinigung in Tarrens Mühle. Die Vereinigung sucht die Flüssigkeit als biologisches Kampfmittel für neue Seuchen gegen die Lebenden.",h="In den Wäldern von Hillsbrad liefern Mooskrabbler Krabblersekret für die Königliche Apothekervereinigung in...",kw={"apotheker lydon","krabblersekret","creepthess","elixier des leidens","vorgebirge des hügellands","mooskrabbler","tarrens mühle"},ang={["race:Undead"]="Als treuer Anhänger der Verlassenen beschafft Ihr tödliche Zutaten wie Krabblersekret und fördert damit den Feldzug der Königlichen Apothekervereinigung, die Lebenden aus Lordaeron zu tilgen."},sec={{t="Apothekerforschung in Hillsbrad",b="Apotheker Lydon in Tarrens Mühle sucht natürliche Gifte und Katalysatoren für tödliche neue Mixturen. Er will die menschliche Bevölkerung der Umgebung ausrotten, und die reine Luft und das blühende Leben des Vorgebirges widern ihn an. Unter den riesigen Spinnentieren des Waldes bergen ausgewachsene Mooskrabbler ein schwer zu findendes Sekret. Es bildet eine ideale Grundlage für sein Elixier des Leidens. Vermischt mit Graubärenzungen und anderen Reagenzien hilft die Flüssigkeit den Verlassenen, ihre tödliche Alchemie zu perfektionieren."}},faq={{q="Welche Kreaturen liefern Krabblersekret?",a="Mooskrabbler im gesamten Vorgebirge des Hügellands liefern Krabblersekret. Dazu gehören Giant Moss Creepers, Forest Moss Creepers, Elder Moss Creepers und das bemerkenswerte Spinnentier Creepthess.",al={"wo krabblersekret finden","wer lässt krabblersekret fallen","krabblersekret gegner"}},{q="Warum braucht Apotheker Lydon diese Flüssigkeit?",a="Apotheker Lydon verwendet Krabblersekret als tödliches Mittel in seiner alchemistischen Forschung. Es hilft ihm, das Elixier des Leidens zu brauen, das die lebenden Menschen in Hillsbrad mit Seuchen heimsuchen und ausrotten soll.",al={"warum lydon sekret will","elixier des leidens zweck","wofür wird krabblersekret verwendet"}},{q="Warum ist Krabblersekret so schwer zu finden?",a="Mooskrabbler sind in den Wäldern um Tarrens Mühle weit verbreitet, doch brauchbare Mengen ihres hochgiftigen Sekrets sind selten. Jäger müssen womöglich viele Spinnentiere töten, bevor sie ein brauchbares Exemplar finden.",al={"warum selten","krabblersekret dropchance"}}},fx={f45507cb={q="Was ist Krabblersekret?",a="Krabblersekret ist eine außergewöhnlich seltene Körperflüssigkeit, die von den Mooskrabblern geerntet wird, die das Vorgebirge des Hügellands heimsuchen. Diese riesigen Spinnentiere durchstreifen die Wälder und Felder um Tarrens Mühle, doch nur selten liefert eines Sekret, das potent und rein genug ist, um als brauchbares alchemistisches Reagenz zu dienen. Für die Königliche Apothekergesellschaft stellt diese schädliche Essenz einen erstklassigen tödlichen Wirkstoff dar, der wegen seiner natürlichen Giftigkeit und seines volatilen Braupotenzials geschätzt wird.",al={"was ist krabblersekret","hintergrund zu krabblersekret","mooskrabblersekret"}},["3620ba85"]={q="Woher stammt Krabblersekret?",a="Krabblersekret wird nicht von Hand hergestellt, sondern direkt von den verschiedenen Arten von Mooskrabblern geerntet, die im Vorgebirge des Hügellands heimisch sind, darunter Riesen-, Wald- und Ältestenkrabbler sowie berüchtigte Bestien wie Creepthess. Es ist eine natürliche biologische Flüssigkeit, die sich in diesen riesigen räuberischen Spinnen bildet, wenngleich das Auffinden eines Exemplars, das eine verwendbare, konzentrierte Menge enthält, das Aufspüren und Töten Dutzender dieser Kreaturen in der Wildnis erfordert.",al={"woher stammt krabblersekret","ursprung von krabblersekret","wer stellte krabblersekret her"}}},fp="13,197,32.446.0,35.183.0,42.189.0,42.189.0"}
P.entries["item:crocolisk-skin-classic"] = {n="Krokiliskenhaut",s="An der Weitschreiter-Lodge in Loch Modan wagen sich Jäger an die Krokilisken des Lochs, deren Häute Händler und Lederverarbeiter begehren.",h="An der Weitschreiter-Lodge in Loch Modan wagen sich Jäger an die Krokilisken des Lochs, deren Häute Händler...",kw={"crocolisk hunting","krokiliskenhaut","die weitschreiter-lodge","loch crocolisk","loch modan","marek eisenherz","der loch"},ang={["class:Hunter"]="Als Jäger verdient Ihr Euch den Respekt der Weitschreiter-Lodge, indem Ihr zu den Inseln watet und einen um sich schlagenden Krokilisken seiner Haut wegen bezwingt.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Krokilisken von Loch Modan den Bergsteigern und Waldläufern der Lodge einiges an Standhaftigkeit abverlangen."},sec={{t="Ein gefährlicher Handel",b="Krokilisken bauen ihre Nester auf den Inseln und an den Ufern der kalten Gewässer des Lochs. Ihre scharfen Zähne und dicken Schuppen machen sie zu gefährlicher Jagdbeute. Dennoch jagen die Jäger der Weitschreiter-Lodge sie wegen ihrer zähen Häute. Schneider und Händler aus der Ferne suchen die Häute für strapazierfähige Kleidung und Rüstungen, weshalb eine unbeschädigte Haut in der Umgebung einen guten Preis erzielt."}},faq={{q="Woher stammen Krokiliskenhäute?",a="Loch Crocolisks und Large Loch Crocolisks liefern die Häute. Sie leben in den Gewässern von Loch Modan und auf seinen Inseln.",al={"wo krokiliskenhäute bekommen","krokiliskenhäute aus dem loch","wer lässt krokiliskenhaut fallen"}},{q="Wer kauft oder handelt diese Häute in Loch Modan?",a="Marek Eisenherz, ein zwergischer Jäger an der Weitschreiter-Lodge, sammelt Krokiliskenhäute und Fleisch, um sie an durchreisende Händler und Handwerker zu verkaufen.",al={"wer will krokiliskenhäute","weitschreiter-lodge krokiliskenhäute","marek eisenherz häute"}},{q="Warum sind diese Häute gefragt?",a="Händler suchen die zähen, schuppigen Häute für strapazierfähige Kleidung und Rüstungen. Krokilisken sind wild und schwer zu töten, weshalb gute Häute ein verlässliches Einkommen bringen.",al={"wofür werden krokiliskenhäute verwendet","krokiliskenleder verwendung","warum krokilisken jagen"}},{q="Gilt die Jagd auf Krokilisken im Loch als gefährlich?",a="Ja. Die Krokilisken des Lochs sind aggressiv und haben kräftige Kiefer und gezackte Zähne, die Gliedmaßen abtrennen können. Einheimische Jäger wie Marek Eisenherz erzählen einander von beinahe tödlichen Begegnungen bei dem Versuch, ihre Beute festzusetzen.",al={"sind krokilisken im loch gefährlich","krokiliskenjagd gefahr"}}},fx={c6e655b9={q="Was ist eine Krokiliskenhaut?",a="Eine Krokiliskenhaut ist das zähe, geschuppte Fell, das von den Krokilisken geerntet wird, die die Gewässer und Inseln von Loch Modan bewohnen. Wegen ihrer Haltbarkeit und unverwechselbaren Textur geschätzt, dient sie als wertvoller Rohstoff für Lederverarbeiter und Schneider, die robuste Kleidung, Schutzausrüstung oder spezialisierte Rüstungen herstellen wollen.",al={"was ist eine krokiliskenhaut","krokiliskenfell","was sind krokiliskenschuppen"}}},fp="14,122,17.342.0,35.115.0,45.132.0,30.140.0,55.210.0"}
P.entries["item:crocolisk-tear-classic"] = {n="Krokiliskenträne",s="Am Steinwerkdamm braucht Chefingenieur Hinderweir eine Krokiliskenträne gegen Sprengstoffe der Dunkeleisenzwerge.",h="Am Steinwerkdamm braucht Chefingenieur Hinderweir eine Krokiliskenträne gegen Sprengstoffe der...",kw={"krokiliskenträne","dunkeleisenzwerge","hinderweir","loch modan","reagenz","der steinwerkdamm","der loch"},ang={["profession:Engineering"]="Zwergische Ingenieure wie Chefingenieur Hinderweir verwenden ungewöhnliche alchemistische Verbindungen, um hochentwickelte Sprengstoffe zu neutralisieren, wenn gewöhnliche Werkzeuge nicht ausreichen."},sec={{t="Eine sonderbare Zutat",b="Krokiliskentränen stammen von Reptilien in den Gewässern von Loch Modan. Chefingenieur Hinderweir fand eine weitere Verwendung für ihre Sekrete. Mit starkem Spinnengift und resonanten Ogermineralien vermischt, erhält eine Träne die nötigen chemischen Eigenschaften, um den instabilen Sprengladungen der Dunkeleisenzwerge entgegenzuwirken, die den Steinwerkdamm bedrohen."}},faq={{q="Wofür wird eine Krokiliskenträne verwendet?",a="Am Steinwerkdamm braucht Chefingenieur Hinderweir eine Krokiliskenträne für eine Mischung, die von Saboteuren der Dunkeleisenzwerge gelegte Sprengsätze entschärfen soll.",al={"krokiliskenträne verwendung","wofür wird krokiliskenträne benötigt","wer sucht krokiliskentränen"}},{q="Wo lassen sich Krokiliskentränen sammeln?",a="Lochkrokilisken und Large Loch Crocolisks leben in den Gewässern und flachen Uferbereichen von Loch Modan. Ihre Tränen lassen sich dort sammeln.",al={"wo werden krokiliskentränen erbeutet","krokiliskenträne fundort","wie erhält man krokiliskentränen"}},{q="Welche weiteren Materialien werden mit der Träne vermischt?",a="Hinderweir vermischt die Träne mit Lauerergift von heimischen Waldspinnen und einem Kristall der Mo'grosh von Ogern in den nordöstlichen Hügeln. Zusammen ergeben sie das Entschärfungsmittel.",al={"hinderweir zutaten","materialien zum entschärfen","was wird zusätzlich zur krokiliskenträne benötigt"}}},fx={["27a8e6d1"]={q="Was ist eine Krokiliskenträne?",a="Eine Krokiliskenträne ist ein seltenes alchemistisches Reagenz, das direkt von den Krokilisken geerntet wird, die die Gewässer von Loch Modan bewohnen. Trotz des alten Sprichworts über unaufrichtiges Weinen besitzen diese körperlichen Sekrete ungewöhnliche Eigenschaften, die sie in spezialisierten Mischungen nützlich machen, insbesondere wenn sie mit anderen potenten lokalen Reagenzien kombiniert werden, um flüchtige Sprengstoffe zu neutralisieren.",al={"krokiliskenträne","was ist eine krokiliskenträne","gegenstand krokiliskenträne"}}},fp="14,104,19.314.0,34.146.0,38.118.0,48.173.0"}
P.entries["item:crossroads-supply-crate"] = {n="Vorratskisten des Wegekreuzes",s="Am Wegekreuz fehlen nach einem Karawanenüberfall Nahrung, Werkzeuge und lebensnotwendige Dinge. Gestohlene Vorräte liegen nun verstreut in Lagern der Razormane im Brachland.",h="Am Wegekreuz fehlen nach einem Karawanenüberfall Nahrung, Werkzeuge und lebensnotwendige Dinge.",kw={"das wegekreuz","vorratskisten des wegekreuzes","stacheleber","razormane","supplies for the crossroads","brachland","thork"},ang={["faction:Horde"]="Das Wegekreuz verbindet Durotar, Mulgore und die nördliche Wildnis. Seine Vorräte helfen, Reisen und Logistik der Horde in ganz Kalimdor abzusichern."},sec={{t="Geplünderte Vorräte",b="Razormane-Stacheleber überfielen eine Karawane auf dem Weg zum Wegekreuz und schleppten ihre Vorräte in nahe gelegene Lager. Die Kisten liegen zwischen Unterholz und Erdbauten. Thork, der Kommandant der Siedlung, will sie zurückholen lassen, bevor Nahrung, Werkzeuge und lebensnotwendige Dinge im Außenposten gefährlich knapp werden."}},faq={{q="Was sind diese Vorratskisten?",a="Die Kisten enthalten Nahrung, Werkzeuge und andere Vorräte für die Hordensiedlung am Wegekreuz. Razormane-Stacheleber verstreuten sie, nachdem sie eine Versorgungskarawane auf den Straßen des Brachlands überfallen hatten.",al={"vorräte des wegekreuzes","was ist in den kisten","infos zur vorratskiste"}},{q="Wer hat die Vorratskisten gestohlen?",a="Razormane-Stacheleber griffen die Karawane an und schleppten die Kisten in ihre nahe gelegenen, dornigen Lager, um zu schlemmen und die Beute zu horten.",al={"wer hat die kisten genommen","wer hat die karawane überfallen","stacheleberdiebe"}},{q="Wer sucht nach diesen Kisten?",a="Thork, ein am Wegekreuz stationierter Orcoffizier, sucht die gestohlenen Kisten, um die Garnison und die örtlichen Bewohner zu versorgen.",al={"wer will die kisten","vorratskisten abgeben","thorks vorräte"}},{q="Wo befinden sich die Kisten?",a="Die Kisten liegen verstreut in Lagern der Razormane-Stacheleber im umliegenden Brachland.",al={"fundorte der kisten","wo sind vorratskisten zu finden","fundorte der vorratskisten des wegekreuzes"}}},fp="23,172,20.278.0,29.186.0,28.122.0,32.127.0,29.83.0"}
P.entries["item:crude-charm"] = {n="Crude Charm",s="Ein Crude Charm wird von Zentauren der Kolkar in Desolace getragen. Uthek die Weise bittet darum, damit die Gelkis ihren Stand unter den Clans behaupten können.",h="Ein Crude Charm wird von Zentauren der Kolkar in Desolace getragen.",kw={"zentaur","crude charm","desolace","gelkis","kolkar","ungewöhnliches bündnis","uthek die weise"},sec={{t="Talismane der Kolkar",b="Uthek die Weise möchte, dass die Talismane der Kolkar ins Dorf der Gelkis gebracht werden. Die Gelkis wollen ihren Stand bei ihren Nachbarn behaupten, und Uthek will die Talismane verbrennen, um zu beweisen, dass die Magie der Kolkar sie nicht beschützen kann. Ihre Verachtung für die Kolkar ist offensichtlich, und sie erwartet, dass deren Angst sie weiter schwächen wird."}},faq={{q="Was ist ein Crude Charm?",a="Ein Crude Charm wird von Zentauren der Kolkar in Desolace getragen und von Uthek der Weisen im Dorf der Gelkis gesucht.",al={"crude charm","talisman der kolkar"}},{q="Wer will die Talismane?",a="Uthek die Weise aus dem Dorf der Gelkis will die Crude Charms der Kolkar.",al={"wer will crude charms","uthek talismane"}},{q="Warum will Uthek Crude Charms?",a="Uthek will die Talismane der Kolkar verbrennen, um zu zeigen, dass ihre Magie schwach ist.",al={"warum talismane","wozu dienen talismane"}},{q="Was wollen die Gelkis von den Kolkar?",a="Die Gelkis wollen ihren Stand unter den Clans behaupten, und Uthek glaubt, dass ein geschwächtes Selbstvertrauen der Kolkar dabei hilft.",al={"gelkis kolkar","warum die kolkar überfallen"}}},fp="11,145,20.303.0,22.103.0,21.65.0,33.71.0,40.117.0"}
P.entries["item:crude-flint"] = {n="Kunstloser Feuerstein",s="Im ganzen Sumpfland verbrennen Mooshautgnolle lebendes Sumpfholz, und Rethiel der Sumpfhüter will sie aufhalten. Sie tragen Kunstlosen Feuerstein bei sich, um ihre Feuer zu entzünden.",h="Im ganzen Sumpfland verbrennen Mooshautgnolle lebendes Sumpfholz, und Rethiel der Sumpfhüter will sie...",kw={"kunstloser feuerstein","fire taboo","gnoll","greenwarden","mooshaut","rethiel","schlagstein","sumpfland"},ang={["class:Druid"]="Als Druide wisst Ihr, dass es gegen die Gebote der Natur verstößt, lebende Pflanzen für die Behaglichkeit von Gnollen zu fällen. Die Feuersteine an sich zu nehmen und zu zerschlagen, ist eine natürliche Pflicht für einen Hüter der Wildnis."},sec={{t="Zunder im Morast",b="Mooshautgnolle schlagen im feuchten Sumpfland Funken aus Kunstlosem Feuerstein, um sich zu wärmen und Fleisch zu garen. Sie fällen lebende Bäume für ihre Herdfeuer und Freudenfeuer. Rethiel der Sumpfhüter sieht jeden Funken als Angriff auf das natürliche Gleichgewicht des Sumpfes."},{t="Die Vergeltung des Greenwarden",b="Rethiel der Sumpfhüter will die Mooshautgnolle daran hindern, die Bäume des Sumpfes zu fällen. Er bittet vorbeiziehende Abenteurer, dem Rudel die Feuersteine abzunehmen. Dann will er jeden Feuerstein zu Staub zerschlagen und die Bruchstücke ins Meer werfen, damit die Gnolle kein lebendes Holz des Sumpflands mehr verbrennen können."}},faq={{q="Wofür wird Kunstloser Feuerstein verwendet?",a="Mooshautgnolle schlagen Funken aus Kunstlosem Feuerstein, um sich zu wärmen und Fleisch zu garen. Rethiel der Sumpfhüter bittet Reisende, die Feuersteine zu sammeln und die Gnolle daran zu hindern, lebende Bäume in Brand zu setzen.",al={"kunstloser feuerstein verwendung","was bewirkt kunstloser feuerstein","kunstloser feuerstein zweck"}},{q="Welche Kreaturen tragen Kunstlosen Feuerstein bei sich?",a="Die meisten erwachsenen Mooshautgnolle und jene mit besonderen Aufgaben tragen Kunstlosen Feuerstein bei sich. Dazu gehören Mosshide Brutes, Trappers, Fenrunners, Mistweavers, Mystics, Alphas und Gnawbone. Kleinere Mooshautgnolle und Mischlinge tragen ihn nicht bei sich.",al={"wer lässt kunstlosen feuerstein fallen","wo gibt es kunstlosen feuerstein","welche gnolle haben feuerstein"}},{q="Warum will Rethiel die Feuersteine vernichtet sehen?",a="Rethiel der Sumpfhüter ist entsetzt, dass die Gnolle lebende Sumpfbäume fällen und das Holz verbrennen, um sich zu wärmen. Er will ihre Feuersteine zerstören und die Splitter ins Meer werfen, damit sie keine Feuer mehr entfachen können.",al={"warum kunstlosen feuerstein zerstören","rethiel feuerstein grund","fire taboo grund"}},{q="Sind diese Feuersteine für die Handwerkskunst wertvoll?",a="Nein. Kunstloser Feuerstein ist ein grober Stein, der sich nur dazu eignet, eine einfache Flamme zu entfachen. Ihm fehlen die Reinheit und die Form, die Schmiede und Ingenieure benötigen.",al={"kunstlosen feuerstein zum schmieden verwenden","ist kunstloser feuerstein handwerksmaterial"}}},fx={b9abde94={q="Was ist ein Kunstloser Feuerstein?",a="Ein Kunstloser Feuerstein ist ein grober, primitiver Stein zum Feuermachen, den die Mosshide-Gnolle im Sumpfland bei sich tragen. Mit diesen einfachen Werkzeugen schlagen die Gnolle Funken, um ihre Lagerfeuer zu entzünden und die lebenden Zweige des Sumpflandes zu verbrennen, um sich warm zu halten.",al={"was ist ein kunstloser feuerstein","hintergrund zu kunstloser feuerstein","was sind diese feuersteine"}},e1f52dc4={q="Woher stammt der Kunstlose Feuerstein und wer hat ihn hergestellt?",a="Diese Steine werden von den Mosshide-Gnollen, die die Moore des Sumpflands bewohnen, behauen und getragen. Nahezu jeder erwachsene Mosshide-Plünderer, Fallensteller und Mystiker trägt einen als essentielles Überlebenswerkzeug bei sich, um im feuchten Sumpf Feuer zu schlagen.",al={"wer stellte kunstlosen feuerstein her","woher bekommen gnolle kunstlosen feuerstein","ursprung von kunstloser feuerstein"}}},fp="11,156,20.231.1,29.299.1,29.181.1,34.211.0,43.222.1,39.128.0"}
P.entries["item:crudely-dried-meat"] = {n="Crudely Dried Meat",s="Crudely Dried Meat ist eingelagerte Nahrung aus dem Lager der Magram in Desolace. Die Gelkis nutzen die gestohlenen Vorräte, um ihren Kampf gegen die Magram fortzuführen.",h="Crudely Dried Meat ist eingelagerte Nahrung aus dem Lager der Magram in Desolace.",kw={"crudely dried meat","desolace","getrocknetes fleisch","gelkis","magram","vorräte stehlen","uthek die weise"},sec={{t="Fleischvorräte",b="Die Jäger der Magram machen überschüssiges Fleisch haltbar, damit ihr Volk zwischen den Jagden kämpfen kann. Uthek die Weise bittet Euch, diese Vorräte aus dem Lager der Magram zu holen und zum Dorf der Gelkis zu bringen. Er gibt das Fleisch den Gelkis, die mit vollem Bauch kämpfen wollen."}},faq={{q="Was ist Crudely Dried Meat?",a="Crudely Dried Meat ist haltbar gemachte Nahrung, die die Magram in Desolace lagern.",al={"getrocknetes fleisch","grobes fleisch","was ist das für fleisch"}},{q="Wer will das Fleisch?",a="Uthek die Weise möchte, dass Ihr ihm das eingelagerte Fleisch der Magram ins Dorf der Gelkis bringt.",al={"wer braucht dieses fleisch","uthek fleisch","fleisch für gelkis"}},{q="Warum wollen die Gelkis es?",a="Die Gelkis wollen das Fleisch essen, damit sie viele Tage lang ohne Rast gegen die Magram kämpfen können.",al={"warum das fleisch stehlen","gelkis hungrig","wofür verwenden sie es"}},{q="Woher stammt das Fleisch?",a="Die Magram lagern überschüssiges Fleisch in ihrem Lager in Desolace, östlich des Dorfes der Gelkis.",al={"wo getrocknetes fleisch finden","magram fleisch","fleischsäcke"}}},fp="18,149,11.243.0,27.70.0,19.84.0,26.88.0,30.78.0"}
P.entries["item:crumpled-scroll-fragment"] = {n="Crumpled Scroll Fragment",s="Das Crumpled Scroll Fragment ist ein Teil der zerstörten Rolle von Myzrael, nach der Theldurin der Verirrte im Ödland sucht. Die Fragmente könnten nötig sein, um der Gefahr durch Myzrael zu begegnen.",h="Das Crumpled Scroll Fragment ist ein Teil der zerstörten Rolle von Myzrael, nach der Theldurin der Verirrte...",kw={"ödland","crumpled scroll fragment","wütender felselementar","myzrael","schriftrollenfragment","rolle von myzrael","theldurin der verirrte"},sec={{t="Ein Fragment gefunden",b="Wütende Felselementare im Ödland tragen Stücke der zerstörten Rolle von Myzrael. Theldurin der Verirrte sucht nach den zerrissenen, angesengten und zerknitterten Fragmenten, in der Hoffnung, sie wieder zusammensetzen zu können. Er fürchtet, Myzrael könnte bereits frei sein, und sagt, die Rolle könnte nötig sein, um sie erneut einzusperren."}},faq={{q="Was ist das Crumpled Scroll Fragment?",a="Das Crumpled Scroll Fragment ist eines von drei Stücken der zerstörten Rolle von Myzrael. Es wurde bei Wütenden Felselementaren im Ödland gefunden.",al={"zerknittertes fragment","schriftrollenstück","was ist dieses fragment"}},{q="Wer will das Fragment?",a="Theldurin der Verirrte bittet Euch, ihm das Crumpled Scroll Fragment sowie die Torn and Singed Scroll Fragments zu bringen.",al={"wer braucht das","wem das fragment geben","theldurins fragmente"}},{q="Woher stammen die Schriftrollenfragmente?",a="Wütende Elementare stahlen die Rolle von Myzrael und zerrissen sie in Stücke. Nun kämpfen sie um ihre Fragmente.",al={"herkunft des fragments","warum haben elementare eine schriftrolle","schriftrolle zerrissen"}},{q="Warum will Theldurin die Fragmente?",a="Theldurin hofft, dass die Fragmente wieder zusammengesetzt werden können. Er glaubt, die Rolle von Myzrael könnte nötig sein, um Myzrael einzusperren, falls sie frei ist.",al={"warum diese sammeln","warum braucht er die schriftrolle","zweck der rolle von myzrael"}}},fp="24,182,16.285.0,37.140.0,23.118.0,41.106.0,38.130.0"}
P.entries["item:crystal-kelp-frond"] = {n="Kristalltangwedel",s="Murlocs tragen Kristalltangwedel aus dem Ozean zum Kristallsee im Wald von Elwynn. William Pestle in Goldhain sucht sie für einen Unsichtbarkeitsschnaps.",h="Murlocs tragen Kristalltangwedel aus dem Ozean zum Kristallsee im Wald von Elwynn.",kw={"kristalltang","kristalltangwedel","kristallsee","goldhain","unsichtbarkeitsschnaps","murloc","william pestle"},ang={["profession:Herbalism"]="Kristalltangwedel wachsen im Wasser, anders als Kräuter, die im Boden wurzeln, und wachsen nicht an gewöhnlichen Kräutervorkommen in Elwynn. Kräuterkundige und Sammler müssen sie den örtlichen Murlocs entreißen, die die Wedel aufbewahren."},sec={{t="Ein seltenes Wasserreagenz",b="Kristalltangwedel stammen aus salzigen Ozeanen, weshalb sie im Süßwasser des Walds von Elwynn ungewöhnlich sind. An den Ufern des Kristallsees sammeln Murloc-Stämme die Wedel und bewahren sie aus ihren eigenen Gründen auf. Alchemisten schätzen die Wedel für ihre seltsame Kraft, die Sicht zu verzerren. William Pestle in Goldhain verwendet sie als Hauptzutat für einen Unsichtbarkeitsschnaps, der Liebenden helfen soll, an den wachsamen Augen ihrer Familien vorbeizuschlüpfen."}},faq={{q="Wo wächst Kristalltang von Natur aus?",a="Kristalltang wächst in salzigen Ozeanen. Er wächst nicht von Natur aus in Süßwasserseen, doch Murlocs sammeln die Abschnitte und tragen sie an Orte wie den Kristallsee.",al={"wo wächst kristalltang","herkunft von kristalltang","lebensraum von tang"}},{q="Warum haben die Murlocs am Kristallsee Tang aus dem Ozean?",a="Der Eintrag nennt keinen Grund dafür, warum die Murlocs am Kristallsee Tang aus dem Ozean haben. Er besagt, dass sie die Wedel aus ihren eigenen Gründen sammeln und aufbewahren.",al={"warum haben murlocs tang","grund für tang bei murlocs"}},{q="Wer möchte Kristalltangwedel in Goldhain haben?",a="William Pestle, ein Apotheker im Gasthaus \"Zur Höhle des Löwen\" in Goldhain, möchte Kristalltangwedel haben. Er braut daraus Unsichtbarkeitsschnaps für Maybell Maclure, damit sie sich vom Weinberg ihrer Familie davonschleichen kann, um Tommy Joe Steinfeld zu treffen.",al={"wer braucht kristalltang","william pestle tang"}},{q="Welche Eigenschaften besitzt Kristalltang?",a="Alchemisten schätzen Kristalltangwedel für ihre Fähigkeit, die Sicht zu verzerren. William Pestle verwendet sie in einem Unsichtbarkeitsschnaps, der Liebenden helfen soll, ungesehen vorbeizukommen.",al={"wirkung von tang","was bewirkt kristalltang"}}},fx={e295764f={q="Was ist ein Kristalltangwedel?",a="Ein Kristalltangwedel ist ein Ableger von Kristalltang, einer seltenen Wasserpflanze, die im Ozean beheimatet ist. Obwohl es sich primär um marine Vegetation handelt, werden diese Wedel manchmal von Murlocs um Süßwassergewässer wie den Kristallsee herum gesammelt und aufbewahrt. Alchemisten schätzen die Wedel für ihre potenten, durchscheinenden Eigenschaften, die zur Herstellung spezialisierter Gebräue wie Unsichtbarkeitsschnaps genutzt werden können.",al={"was ist ein kristalltangwedel","info zu kristalltang","was ist kristalltang"}},["8bde59b0"]={q="Warum benötigt jemand Kristalltangwedel?",a="William Pestle, der Alchemist in Goldhain, benötigt Kristalltangwedel, um einen potenten Unsichtbarkeitsschnaps zu brauen. Er beabsichtigt, das Gebräu zu verwenden, um der jungen Maybell Maclure zu helfen, sodass sie unbemerkt vom wachsamen Weinberg ihrer Familie wegschlüpfen kann, um sich heimlich mit ihrem verbotenen Verehrer Tommy Joe Steinfeld zu treffen.",al={"wer benötigt kristalltang","warum kristalltangwedel sammeln","nutzen von kristalltang"}}},fp="18,149,22.420.0,39.169.0,51.136.0,43.232.1,42.162.0"}
P.entries["item:crystal-phial"] = {n="Kristallphiole",s="Im Laubschattental gibt Tenaron Sturmgewalt jungen Nachtelfen eine Kristallphiole für einen nahen Mondbrunnen. Dort schöpfen sie heiliges Wasser für Riten, die Teldrassil ehren und nähren.",h="Im Laubschattental gibt Tenaron Sturmgewalt jungen Nachtelfen eine Kristallphiole für einen nahen Mondbrunnen.",kw={"aldrassil","crown of the earth","kristallphiole","mondbrunnen","laubschattental","teldrassil","tenaron sturmgewalt"},ang={["class:Druid"]="Als Druide bringt Ihr Mondbrunnen tiefe Ehrfurcht entgegen. Ihre stillen Wasser helfen Euch, natürliche Energien zu kanalisieren und neues Wachstum zu fördern, ohne arkaner Zauberei zu verfallen.",["race:NightElf"]="Als junger Kaldorei ist das Füllen dieser Phiole für Euch ein erster Übergangsritus jenseits von Aldrassil. Er verbindet Euch mit den Wassern von Elune und der Erholung Eures Volkes nach dem Dritten Krieg."},sec={{t="Ein Gefäß für heilige Wasser",b="Hoch oben auf Aldrassil gibt Tenaron Sturmgewalt jungen Nachtelfen eine Kristallphiole. Er schickt sie zum Mondbrunnen direkt nördlich des Astes, um dessen leuchtendes Wasser zu schöpfen. Das zarte Gefäß birgt Wasser, das vom heiligen Vermächtnis des Brunnens der Ewigkeit berührt ist.\n\nWenn sie mit einer Gefüllten Kristallphiole zurückkehren, beginnt die Pilgerreise Crown of the Earth. Die jungen Kaldorei lernen das Gleichgewicht von Magie, Geschichte und Natur in ihrer neuen Inselheimat kennen."}},faq={{q="Wofür wird die Kristallphiole verwendet?",a="Mit der Kristallphiole wird gesegnetes Wasser aus dem Mondbrunnen direkt nördlich von Aldrassil im Laubschattental geschöpft. Ihr bringt die gefüllte Phiole für die Pilgerreise Crown of the Earth zu Tenaron Sturmgewalt zurück.",al={"zweck der kristallphiole","verwendung der kristallphiole","was tun mit der phiole"}},{q="Wer gibt Euch die Kristallphiole?",a="Tenaron Sturmgewalt gibt Euch die leere Kristallphiole hoch oben auf Aldrassil.",al={"wer gibt die kristallphiole","wo gibt es die kristallphiole"}},{q="Warum ist das Schöpfen von Mondbrunnenwasser bedeutsam?",a="Mondbrunnenwasser ist mit dem Brunnen der Ewigkeit und der Gnade von Elune verbunden. Indem Ihr es schöpft, erfahrt Ihr mehr über die Folgen des Dritten Krieges und nehmt an Riten teil, die Teldrassil nähren.",al={"warum mondbrunnenwasser","bedeutung von mondbrunnenwasser","zweck des mondbrunnens"}},{q="Was geschieht, nachdem die Phiole gefüllt ist?",a="Sobald das Gefäß gefüllt ist, wird es zu einer Gefüllten Kristallphiole. Ihr bringt sie zu Tenaron Sturmgewalt zurück, besteht damit Eure erste Prüfung und erschließt Euch weitere Lehren über die Erschaffung und Pflege des Weltbaums in ganz Teldrassil.",al={"nach dem füllen der phiole","verwendung der gefüllten kristallphiole"}}},fx={d56aa813={q="Was ist die Kristallphiole?",a="Die Kristallphiole ist ein zerbrechliches, speziell gefertigtes Gefäß, das von Tenaron Sturmgewalt auf Aldrassil im Laubschattental bereitgestellt wird. Entwickelt, um heilige Flüssigkeiten sicher zu transportieren, stellt ihre Konstruktion aus reinem Kristall sicher, dass die empfindlichen magischen Energien des Mondbrunnenwassers rein bleiben, während Ihr es von den heiligen Schreinen des Waldes zurückbringt.",al={"was ist die kristallphiole","gegenstand kristallphiole"}},["819f868c"]={q="Warum möchte Tenaron Sturmgewalt die Kristallphiole gefüllt haben?",a="Tenaron Sturmgewalt bittet Euch, die Kristallphiole als ersten Schritt Eurer Initiation in die Nachtelfengesellschaft und die weitere Welt zu füllen. Mondbrunnen enthalten Wasser, das mit dem Vermächtnis des Brunnens der Ewigkeit gesegnet ist, das von den Sentinels als Schreine für Elune verehrt und von Druiden gepflegt wird. Das Sammeln seines Wassers lehrt Euch über die Opfer, die am Hyjal gebracht wurden, und testet Eure Bereitschaft, den fragilen Zustand von Teldrassil zu verstehen.",al={"warum kristallphiole füllen","warum will tenaron mondbrunnenwasser","tenaron kristallphiole warum"}}},fp="13,178,26.432.0,35.184.0,32.67.0,44.182.0,39.211.0"}
P.entries["item:crystalized-scales"] = {n="Kristallisierte Schuppen",s="In Kalimdor liefern Basilisken Kristallisierte Schuppen für arkane Arbeiten. Ihre mineralisierten Häute stammen aus dem Verbrannten Tal und Tausend Nadeln, und Collin Mauren sucht sie in Sturmwind.",h="In Kalimdor liefern Basilisken Kristallisierte Schuppen für arkane Arbeiten.",kw={"basilisk","das verbrannte tal","collin mauren","kristallisierte schuppen","reagenz","steinkrallengebirge","sturmwind","tausend nadeln"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie raue Umgebungen die magische Natur eines Tieres verändern und Reagenzien für ungewöhnliche Zauber hervorbringen.",["faction:Alliance"]="Als Reisender der Allianz tragt Ihr diese Schuppen zwischen Sturmwind und der Wildnis Kalimdors hin und her."},sec={{t="Ein seltenes Reagenz Kalimdors",b="Basilisken trotzen Hitze und Asche im Verbrannten Tal im Steinkrallengebirge und in den Salzebenen von Tausend Nadeln. An beiden Orten verhärten sich ihre Häute unter einer Kristallkruste. Die Schuppen bergen eine latente arkane Resonanz, und Magier jenseits des großen Meeres schätzen sie für Experimente mit seltenen Zauberkünsten."},{t="Maurens arkane Arbeit",b="In Sturmwind sucht der Magier Collin Mauren Reisende mit Ziel Kalimdor, die ihm diese Schuppen bringen sollen. Er zermahlt ihre kristallinen Mineralschichten zu Staub und verwendet das Pulver dann als Reagenz für neu ersonnene Zauber und seine eigenen arkanen Forschungen."}},faq={{q="Welche Kreaturen liefern Kristallisierte Schuppen?",a="Basilisken, die an raue Gegenden angepasst sind, liefern Kristallisierte Schuppen. Dazu gehören die versengten, angesengten und geschwärzten Basilisken im Verbrannten Tal im Steinkrallengebirge sowie die saltstone basilisks in Tausend Nadeln.",al={"wo werden schuppen erbeutet","wer liefert kristallisierte schuppen","herkunft der basiliskenschuppen"}},{q="Wer sucht diese Schuppen in Sturmwind?",a="Collin Mauren, ein Magier in Sturmwind, sucht für seine magischen Experimente die Schuppen bei Reisenden, die ins Steinkrallengebirge aufbrechen.",al={"wer will kristallisierte schuppen","collin mauren schuppen","wer verwendet diese schuppen"}},{q="Wie werden die Schuppen beim Zaubern verwendet?",a="Mauren zermahlt die kristallinen Schuppen zu feinem Staub. Er verwendet den Staub als wirkungsvolles Reagenz für besondere Zauber seiner eigenen Schöpfung.",al={"warum sind kristallisierte schuppen magisch","schuppen als zauberreagenz"}},{q="Sind Kristallisierte Schuppen nur im Steinkrallengebirge zu finden?",a="Mauren bittet Reisende mit Ziel Verbranntes Tal im Steinkrallengebirge, nach den Schuppen zu suchen. Saltstone basilisks in Tausend Nadeln besitzen ähnliche kristalline Häute.",al={"tausend nadeln schuppen","weitere fundorte für schuppen"}}},fx={cec6ea6a={q="Was sind Kristallisierte Schuppen?",a="Kristallisierte Schuppen sind gehärtete, kristalline Außenplatten, die von bestimmten Basiliskenarten geerntet werden. Sie finden sich insbesondere bei Basilisken, die in rauen Regionen wie dem verbrannten Tal innerhalb des Steinkrallengebirges leben; diese zähen Schuppen besitzen einzigartige mineralähnliche Eigenschaften, die sie für Gelehrte und Zauberwirker wertvoll machen.",al={"was sind kristallisierte schuppen","hintergrund zu kristallisierte schuppen","über kristallisierte schuppen"}},["5be8a367"]={q="Woher kommen Kristallisierte Schuppen?",a="Diese Schuppen wachsen auf natürliche Weise bei bestimmten Basiliskenarten. Sie werden üblicherweise von den versengten, geschwärzten und angesengten Basilisken geerntet, die die feurigen Einöden des verbrannten Tals im Steinkrallengebirge durchstreifen, sowie von Salzsteinbasilisken, die in den Salzwüsten der Tausend Nadeln zu finden sind.",al={"ursprung von kristallisierte schuppen","woher bekommt man kristallisierte schuppen","quelle für kristallisierte schuppen"}}},fp="18,180,23.279.0,20.246.0,40.205.0,41.127.0,40.137.0,51.154.0"}
P.entries["item:curative-animal-salve"] = {n="Heilende Tiersalbe",s="An der Dunkelküste und im Brachland versorgen Druiden kranke Wildtiere mit Heilender Tiersalbe. Kräuterkundige stellen sie in beiden Gebieten her, während der Zirkel des Cenarius die Leiden der Tiere als Zeichen einer größeren Verderbnis deutet.",h="An der Dunkelküste und im Brachland versorgen Druiden kranke Wildtiere mit Heilender Tiersalbe.",kw={"alanndarian nachtweise","heilende tiersalbe","curing the sick","power over poison","kränkliche rehe","kränkliche gazelle","tonga runentotem"},ang={["class:Druid"]="Als Druide stellt Ihr bei der Behandlung von Wildtieren mit dieser Salbe Eure Hingabe zur Arbeit des Zirkels des Cenarius in ganz Kalimdor und Euer Geschick beim Reinigen von Gift auf die Probe.",["race:Tauren"]="Als Tauren folgt Ihr mit der Anwendung der Salbe im Brachland den Lehren von Cenarius. Taurendruiden arbeiten im Einklang mit den überlieferten Riten des Zirkels, um die Erde zu heilen."},sec={{t="Heilung der Wildnis",b="Druiden wenden Heilende Tiersalbe bei kranken Wildtieren an der Dunkelküste und im Brachland an. Alanndarian Nachtweise weist junge Druiden an, kranke Rehe zwischen dem Klippenquell und den Grenzen des Eschentals zu behandeln. Im Brachland braut Tonga Runentotem dasselbe Heilmittel für kranke Gazellen nördlich vom Wegekreuz.\n\nBeide Kräuterkundigen sammeln heimische Kräuter und bereiten die Salbe in Mengen von jeweils zehn Dosen zu. Druiden im Einsatz tragen sie direkt auf die Tiere auf. Beide Kräuterkundigen arbeiten mit den örtlichen Autoritäten zusammen, um größere Vorräte herzustellen."},{t="Zeichen eines tieferen Übels",b="Die Salbe lindert das Leid der Tiere, doch der Zirkel des Cenarius erkennt eine umfassendere Störung. In Mondlichtung stellt Dendrite Sternenschauer fest, dass die erkrankten Rehe an der Küste und die leidenden Gazellen in der Savanne keine zufälligen Opfer sind. Sie sind ahnungslose Opfer einer Verderbnis, die sich aus mehreren Richtungen über Kalimdor ausbreitet.\n\nFür Initianden prüft die Behandlung der Tiere ihre Hingabe zum Schutz der Natur und ihr Geschick beim Reinigen von Gift."}},faq={{q="Wozu dient Heilende Tiersalbe?",a="Druiden tragen Heilende Tiersalbe direkt auf erkrankte Wildtiere auf, um ihre Beschwerden zu lindern. An der Dunkelküste wenden sie sie bei kranken Rehen an; im Brachland behandeln sie kranke Gazellen, die nördlich vom Wegekreuz grasen.",al={"heilende tiersalbe zweck","heilende tiersalbe anwenden","was bewirkt die salbe"}},{q="Wer stellt die Salbe her?",a="Alanndarian Nachtweise stellt die Salbe an der Dunkelküste aus gesammelten Kräutern her. Im Brachland braut Tonga Runentotem sie am Wegekreuz für Druiden der Horde.",al={"wer stellt die salbe her","woher kommt die salbe"}},{q="Warum sind die Rehe und Gazellen überhaupt krank?",a="Dendrite Sternenschauer vom Zirkel des Cenarius sagt, die Wildtiere seien Opfer einer zunehmenden Verderbnis, die sich über Kalimdor ausbreitet. Die Rehe und Gazellen sind frühe Opfer einer ökologischen Plage.",al={"warum sind die tiere kränklich","was vergiftet die rehe an der dunkelküste","krankheit der gazellen im brachland"}},{q="Wie viele Dosen enthält eine Zubereitung?",a="Eine gewöhnliche Zubereitung enthält zehn Dosen, genug für zehn Anwendungen.",al={"wie viele aufladungen","wie viele anwendungen hat die salbe"}}},fx={a20a877c={q="Was ist eine Heilende Tiersalbe?",a="Eine Heilende Tiersalbe ist ein pflanzliches Heilmittel, das zusammengestellt wurde, um betroffene Wildtiere zu behandeln, die unter einer sich ausbreitenden unnatürlichen Krankheit leiden. Von druidischen Verbündeten unter Verwendung lokaler Reagenzien zubereitet, reinigt sie das Siechtum, das unschuldige Kreaturen wie die Hirsche der Dunkelküste und die Gazellen des Brachlands vergiftet.",al={"heilende tiersalbe","was ist tiersalbe","hintergrund zu heilende tiersalbe"}}},fp="21,211,17.495.0,28.447.0,39.203.0,23.151.0,54.185.0,36.65.0"}
P.entries["item:daffodil-bouquet"] = {n="Narzissenstrauß",s="In Seenhain überbringt der Narzissenstrauß den Dank von Wache Parker an Darcy dafür, dass sie sein Mittagessen packt. Martie Jainrose sammelt die Blumen, und ihre Wahl sorgt für Getuschel zwischen den beiden Frauen.",h="In Seenhain überbringt der Narzissenstrauß den Dank von Wache Parker an Darcy dafür, dass sie sein...",kw={"narzissenstrauß","narzissen","darcy","wache parker","seenhain","martie jainrose","rotkammgebirge"},ang={["profession:Herbalism"]="Als Kräuterkundiger in Seenhain erkennt Ihr vielleicht Martie Jainroses Handarbeit. Sie sammelt Wildblumen für ihr Gewerbe."},sec={{t="Ein verworrenes Dankeszeichen",b="Wache Parker möchte Darcy im Gasthaus von Seenhain dafür danken, dass sie ihm täglich sein Mittagessen packt. Also bittet er Martie Jainrose, die Kräuterkundige der Stadt, einen Narzissenstrauß vorzubereiten. Martie bezeichnet sie als ihre Lieblingsblumen. Darcy erkennt darin Marties typische Blume und vermutet Eifersucht. Im Halbscherz fragt sie sich, ob Martie die Stängel aus Bosheit vergiftet hat."}},faq={{q="Wofür wird der Narzissenstrauß verwendet?",a="Wache Parker schickt Darcy im Gasthaus von Seenhain den Narzissenstrauß. Damit dankt er ihr dafür, dass sie sein Mittagessen packt und ihm schickt, während er im Dienst ist.",al={"narzissenstrauß verwendung","was tun mit narzissenstrauß","wer bekommt die narzissen"}},{q="Wer hat diesen Strauß vorbereitet?",a="Martie Jainrose, die Kräuterkundige von Seenhain, sammelt und bindet den Strauß auf Bitten von Wache Parker. Sie wählt Narzissen, weil es ihre Lieblingsblumen sind.",al={"wer hat den strauß gemacht","narzissenstrauß herkunft","woher stammen die blumen"}},{q="Warum reagiert Darcy misstrauisch auf die Blumen?",a="Darcy erkennt Marties Lieblingsblumen und vermutet, dass sie nicht eigens für sie ausgewählt wurden. Sie nennt Martie eine eifersüchtige Rivalin und scherzt, die Stängel könnten aus Bosheit vergiftet sein, nimmt die Geste aber dennoch an.",al={"warum ist darcy wütend","darcy vergiftete blumen","darcy und martie rivalität"}},{q="Sind die Narzissen tatsächlich vergiftet?",a="Nein. Die Blumen sind harmlos. Darcys Verdacht ist Ausdruck theatralischer Eifersucht zwischen den beiden Frauen in Seenhain.",al={"ist der strauß vergiftet","hat martie die narzissen vergiftet"}}},fx={d233835e={q="Was ist der Narzissenstrauß?",a="Der Narzissenstrauß ist ein Bündel frischer gelber Blüten, die im Rotkammgebirge gesammelt wurden. Da er speziell als Arrangement der Lieblingsblumen von Martie Jainrose ausgewählt wurde, dient er als Zeichen der Dankbarkeit, das als Gegenleistung für eine Mahlzeit an Darcy im Gasthaus von Seenhain überbracht werden soll.",al={"was ist ein narzissenstrauß","narzissenstrauß hintergrund","narzissen gegenstand"}},c8a417a4={q="Warum möchte Darcy den Narzissenstrauß?",a="Darcy hat nicht ausdrücklich nach Blumen gefragt, aber Wache Parker wollte sich erkenntlich zeigen, nachdem sie ihm ein warmes Mittagessen zum Wachposten an den Drei Ecken geschickt hatte. Er schickt Euch los, um einen Strauß zu besorgen, um ihr den Tag zu verschönern, obwohl sie ihn eifrig entgegennimmt und ins Wasser stellt, bevor ihr klar wird, welcher Kräuterkundige ihn zusammengestellt hat.",al={"warum narzissenstrauß liefern","warum möchte darcy blumen","wer möchte den narzissenstrauß"}}},fp="16,182,15.349.0,38.135.0,26.161.0,49.212.1,36.108.1"}
P.entries["item:daggerspine-scale"] = {n="Säbelflossenschuppe",s="An der Südküste des Vorgebirges des Hügellands liefern umherstreifende Säbelflossen-Naga zähe Reptilienschuppen, die die Königliche Apothekervereinigung begehrt. Die Schuppen helfen, virulente Gebräue in den laufenden Seuchenexperimenten der Verlassenen zu aktivieren.",h="An der Südküste des Vorgebirges des Hügellands liefern umherstreifende Säbelflossen-Naga zähe...",kw={"säbelflossen","säbelflossenschuppe","elixir of agony","hillsbrad","lydon","naga","königliche apothekervereinigung","unterstadt"},ang={["faction:Horde"]="Als Mitglied der Horde müsst Ihr Euch vorsichtig entlang der Südküste bewegen. Die Lager der Säbelflossen liegen gefährlich nahe am Allianzhafen Süderstade.",["race:Undead"]="Als Untoter helft Ihr der Königlichen Apothekervereinigung, verheerende neue Seuchen gegen die Feinde der Verlassenen zu erforschen."},sec={{t="Apothekerforschung",b="Die Königliche Apothekervereinigung sucht Reagenzien für ihre Toxine, Seuchen und Gebräue. Bei der Verfeinerung des experimentellen Elixir of Agony entdeckten ihre Apotheker, dass die Schuppen der Säbelflossen-Naga auf nützliche Weise reagieren. Zusammen mit regenerativen Elixieren der Trolle und Murloc-Organen aktivieren die Schuppen auf chemischem Wege ruhende Krankheitserreger, die in rohen Mischungen schweben.\n\nUm die Schuppen zu sammeln, müsst Ihr entlang der felsigen Küste östlich von Süderstade jagen. Sowohl der bösartige Naga-Stamm als auch Streitkräfte der Allianz befinden sich in der Nähe. Die Apotheker brauchen die Schuppen für ihre Forschung."}},faq={{q="Wofür werden Säbelflossenschuppen verwendet?",a="Apotheker Lydon in Tarrens Mühle sammelt Säbelflossenschuppen für die Forschung zum Elixir of Agony. Zusammen mit anderen Reagenzien aktivieren sie die verseuchenden Eigenschaften einer alchemistischen Morastschnauzenmixtur.",al={"säbelflossenschuppe verwendung","warum säbelflossenschuppen sammeln","was bewirken säbelflossenschuppen"}},{q="Woher stammen diese Schuppen?",a="Säbelflossenschuppen stammen von Säbelflossen-Naga an der Küste des Vorgebirges des Hügellands, unmittelbar östlich von Süderstade. Shorestalkers, shorehunters, screamers, sirens und ihre Anführerin Lady Zephris liefern sie alle.",al={"wo säbelflossenschuppen finden","wer lässt säbelflossenschuppen fallen","säbelflossenschuppe fundort"}},{q="Warum will die Königliche Apothekervereinigung Naga-Schuppen?",a="Die Königliche Apothekervereinigung will Säbelflossenschuppen, weil diese widerstandsfähigen Schuppen die nötigen chemischen Eigenschaften besitzen, um bestimmte Krankheitserreger in experimentellen Seuchen- und Krankheitsgebräuen zu aktivieren.",al={"warum naga-schuppen","apotheker naga-schuppen"}}},fx={["8e2c4377"]={q="Was ist eine Säbelflossenschuppe?",a="Eine Säbelflossenschuppe ist eine zähe aquatische Schuppe, die von den Säbelflossen-Naga geerntet wird, welche die Küste im Vorgebirge des Hügellands unsicher machen. Diese schlangenartigen Kreaturen besitzen einzigartige biologische Eigenschaften, die ihre abgestoßenen und geernteten Schuppen zu wertvollen Reagenzien für die finsteren Gebräue der Apothekervereinigung machen.",al={"was sind säbelflossenschuppen","säbelflossenschuppe gegenstand","über säbelflossenschuppen"}}},fp="17,227,19.552.0,37.205.0,32.212.0,55.206.0"}
P.entries["item:dal-bloodclaw-s-skull"] = {n="Dal Blutklaues Schädel",s="Im nördlichen Eschental erwartet Raene Wolfsläufer den Beweis, dass Astranaar vor Angriffen sicher ist. Dal Blutklaues Schädel liefert diesen Beweis.",h="Im nördlichen Eschental erwartet Raene Wolfsläufer den Beweis, dass Astranaar vor Angriffen sicher ist.",kw={"eschental","astranaar","dal bloodclaw","furbolg","raene wolfsläufer","schädel","thistlefur"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Astranaars Nordflanke zu sichern. Die Siedlung ist der wichtigste Zufluchtsort der Allianz im zentralen Eschental.",["race:NightElf"]="Als Nachtelf empfindet Ihr vielleicht Trauer, wenn gefallene Anführer der Furbolgs besiegt werden. Die Verderbnis hat diese uralten Verbündeten entstellt, und nun bedrohen sie Siedlungen wie Astranaar."},sec={{t="Der Fall eines Häuptlings",b="Die Thistlefur-Furbolgs nördlich von Astranaar sind zahlreicher und aggressiver geworden. Wie weite Teile des uralten Waldes im Eschental sind sie der Verderbnis verfallen. Raene Wolfsläufer, eine Schildwache der Nachtelfen, fürchtet, dass sie bald gegen Astranaar ziehen werden. Deshalb befiehlt sie, ihre Reihen auszudünnen und ihren Anführer, Dal Bloodclaw, zu töten. Sein Schädel beweist, dass ihr Häuptling tot ist, und verschafft Astranaars Verteidigern Zeit."}},faq={{q="Wer war Dal Bloodclaw?",a="Dal Bloodclaw führte die Thistlefur-Furbolgs in Thistlefur Hold, unmittelbar nördlich von Astranaar. Unter seiner Führung wuchs der feindselige Stamm rasch und bedrohte den nahe gelegenen Außenposten der Nachtelfen.",al={"dal bloodclaw","wer ist bloodclaw","thistlefur-häuptling"}},{q="Warum will Raene Wolfsläufer den Schädel?",a="Raene Wolfsläufer will einen Beweis dafür, dass der Häuptling der Thistlefur tot ist. Die Nachtelfen hoffen, dass die überlebenden Furbolgs in Unordnung geraten und ihre geordneten Pläne für einen Angriff auf Astranaar aufgeben.",al={"warum schädel","raene wolfsläufer schädel","todesbeweis"}},{q="Warum sind die Thistlefur-Furbolgs so feindselig?",a="Wie viele Furbolgstämme im Eschental sind die Thistlefur der Verderbnis erlegen, die sich im Wald ausbreitet. Sie sind gewalttätig geworden und verteidigen ihr Revier erbittert, wodurch sie jene bedrohen, die einst neben ihnen lebten.",al={"warum furbolgs aggressiv","furbolg-verderbnis","thistlefur wahnsinnig"}}},fx={b1ad26a7={q="Was ist Dal Blutklaues Schädel?",a="Es ist der abgetrennte Schädel von Dal Blutklaue, dem Häuptling der korrumpierten Thistlefur-Furbolgs, die in Thistlefur Hold nördlich von Astranaar leben. Er dient als grausiger physischer Beweis für seinen Tod.",al={"was ist dal blutklaues schädel","dal schädel","was ist dieser schädel"}},fa2f0114={q="Woher stammt Dal Blutklaues Schädel?",a="Der Schädel wird direkt von den Überresten von Dal Blutklaue selbst in Thistlefur Hold tief im nördlichen Eschental genommen, nachdem er erschlagen wurde, um die Führung seines wachsenden Stammes zu brechen.",al={"woher stammt dal blutklaues schädel","wer hat dal blutklaues schädel hergestellt","ursprung von dal blutklaues schädel"}}},fp="21,130,22.388.0,22.184.0,41.185.0,43.200.0"}
P.entries["item:dalaran-mana-gem"] = {n="Manaedelstein aus Dalaran",s="Nahe Mühlenbern tragen Magier der Kirin Tor Manaedelsteine aus Dalaran, um ihre arkane Kraft zu erneuern. Schneider der Verlassenen nutzen die Edelsteine, um verzauberte Roben zu weben.",h="Nahe Mühlenbern tragen Magier der Kirin Tor Manaedelsteine aus Dalaran, um ihre arkane Kraft zu erneuern.",kw={"mühlenbern","manaedelstein aus dalaran","josef gregorian","kirin tor","leinen","manaedelstein","silberwald","spellfire robes"},ang={["class:Mage"]="Als Magier der Verlassenen werdet Ihr ausgesandt, diese Edelsteine als Übergangsritus zu erbeuten. Ihr beweist Euer Kampfgeschick und Eure Beherrschung erbeuteter arkaner Kraft.",["race:Undead"]="Als untoter Reisender wisst Ihr, dass die Verlassenen ihre Gefühle für ihre einstigen menschlichen Kollegen in Dalaran zurückstellen, um das Überleben ihrer Fraktion zu sichern."},sec={{t="Gestohlene arkane Macht",b="Auch die Beschwörer und Wachen der Kirin Tor tragen die Edelsteine bei sich. Im Magieviertel von Unterstadt schätzen Zauberkundige der Verlassenen die Edelsteine als griffbereite Speicher konzentrierter Magie. Einige untote Magier teilen ein akademisches Erbe mit Dalaran. Doch das Überleben geht vor, und die Verlassenen sehen die Kirin Tor als Rivalen, deren Magievorräte sie an sich nehmen können."},{t="Zauberfeuer verweben",b="Verlassene bringen Manaedelsteine von gefallenen Agenten der Kirin Tor zu Schneidern wie Josef Gregorian in Unterstadt. Sie bringen auch einfaches Leinen mit. Ein Schneider kann arkane Kraft nicht direkt kanalisieren, wohl aber einen Edelstein in Stoff einbinden. Die Magie stärkt die Verbindung des Trägers zum Arkanen."}},faq={{q="Woher stammen Manaedelsteine aus Dalaran?",a="Streitkräfte der Kirin Tor tragen Manaedelsteine aus Dalaran im Silberwald, besonders nahe ihren Lagern und Außenposten um Mühlenbern, südöstlich des Grabmals.",al={"wo manaedelsteine farmen","edelstein aus dalaran beute","wer lässt manaedelsteine fallen"}},{q="Wofür werden diese Edelsteine verwendet?",a="Magier der Verlassenen bringen die Edelsteine zusammen mit Leinen zu Josef Gregorian in Unterstadt. Er verwendet sie, um Spellfire Robes zu weben.",al={"verwendungszweck von manaedelsteinen","wofür braucht man manaedelsteine aus dalaran"}},{q="Warum tragen die Kirin Tor im Silberwald diese Edelsteine bei sich?",a="Mitglieder der Kirin Tor tragen Manaedelsteine als persönliche Speicher arkaner Kraft bei sich. Die Edelsteine versorgen ihre Zauber, Schutzbarrieren und Beschwörungen im feindseligen Silberwald mit Energie.",al={"warum haben zauberer aus dalaran edelsteine","geschichte der manaedelsteine der kirin tor"}},{q="Warum nehmen die Verlassenen für diese Edelsteine Magier aus Dalaran ins Visier?",a="Die Verlassenen und Dalaran teilen ein akademisches Erbe, doch die Verlassenen sehen ihre lebenden Gegenstücke als Rivalen. Mentoren in Unterstadt glauben, dass ein Magier, der seine arkanen Reichtümer nicht verteidigen kann, zu schwach zum Überleben ist. Also nehmen sie ihm seine Komponenten ab.",al={"verlassene gegen magier aus dalaran","warum für roben magier aus dalaran töten"}}},fx={["02094a76"]={q="Was ist ein Manaedelstein aus Dalaran?",a="Ein Manaedelstein aus Dalaran ist ein magisch aufgeladener Stein, der von den Agenten der Kirin Tor getragen wird, die im Silberwald stationiert sind. Diese mit arkaner Energie durchdrungenen Kristalle sind wesentliche Komponenten für die Herstellung verzauberter Kleidungsstücke, wie etwa der Spellfire Robes, die von den Schneidern der Verlassenen in der Unterstadt genäht werden.",al={"was ist ein manaedelstein aus dalaran","manaedelstein aus dalaran","manaedelstein silberwald"}}},fp="16,140,13.342.0,21.290.0,37.155.0,29.116.0,56.168.0,56.239.0"}
P.entries["item:dalaran-pendant"] = {n="Anhänger aus Dalaran",s="In Mühlenbern bündeln Anhänger aus Dalaran die Magie der Kirin Tor. Die Verlassenen suchen sie, um die Zauberer zu bremsen und die Quelle ihrer Macht aufzuspüren.",h="In Mühlenbern bündeln Anhänger aus Dalaran die Magie der Kirin Tor.",kw={"allister","mühlenbern","anhänger aus dalaran","kirin tor","das grabmal","silberwald"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie die Kirin Tor mit diesen Anhängern ihre Magie bündeln und komplexe Zauber aufeinander abstimmen.",["race:Undead"]="Als Untoter könnt Ihr helfen, den Silberwald gegen menschliche Zauberer zu sichern, die dort wieder Fuß fassen wollen, indem Ihr den Kirin Tor diese Anhänger abnehmt."},sec={{t="Amulette von Mühlenbern",b="Zauberer, Beschwörer und Beschützer der Kirin Tor weben mächtige Zauber in Mühlenbern. Ihr Wirken bedroht die Kontrolle der Verlassenen über den südlichen Silberwald. Jeder trägt einen eingestimmten Anhänger aus Dalaran. Im Grabmal entsendet Schattenpriester Allister Agenten der Verlassenen, um die Anhänger zu beschaffen. Er hofft, die Magier zu bremsen und herauszufinden, wer ihr magisches Gewebe lenkt."}},faq={{q="Was ist der Anhänger aus Dalaran?",a="Beschwörer, Magier und Beschützer der Kirin Tor in Mühlenbern tragen Anhänger aus Dalaran. Die Verlassenen suchen sie, um das Wirken der Zauberer zu behindern und ihre Magie zu untersuchen.",al={"was ist der anhänger aus dalaran","kirin tor halskette silberwald"}},{q="Wer trägt diese Anhänger?",a="Menschliche Magier, Beschwörer und Beschützer Dalarans tragen die Anhänger in Mühlenbern im Silberwald.",al={"wer lässt anhänger aus dalaran fallen","wo anhänger aus dalaran bekommen"}},{q="Warum will Schattenpriester Allister sie haben?",a="Schattenpriester Allister und sein Verbündeter Dalar brauchen die Anhänger, um die Zauber der Magier zu verlangsamen und den mächtigen Magier aufzuspüren, der Mühlenberns magisches Gewebe lenkt.",al={"warum allister anhänger will","nachforschungen in mühlenbern anhänger"}},{q="Wo liegt Mühlenbern?",a="Mühlenbern liegt im südlichen Silberwald. Folgt vom Grabmal aus der Hauptstraße nach Süden und nehmt die östliche Abzweigung, um das Dorf zu erreichen.",al={"mühlenbern lage","wie nach mühlenbern gelangen"}}},fp="15,139,20.355.0,28.155.0,27.104.0,42.155.0,27.141.0"}
P.entries["item:dalaran-status-report"] = {n="Statusbericht von Dalaran",s="In Mühlenbern bauen die Kirin Tor Dalaran unter freiem Himmel wieder auf, während die Todespirscher ihren Bericht suchen.",h="In Mühlenbern bauen die Kirin Tor Dalaran unter freiem Himmel wieder auf, während die Todespirscher ihren...",kw={"mühlenbern","mühlenbern geldkassette","statusbericht von dalaran","deathstalkers","kirin tor","mennet carkad","tools of the trade","varimathras"},ang={["class:Rogue"]="Als Schurke beweist Ihr unter Mennet Carkad Eure Fähigkeiten im Schlossknacken und in der Infiltration, indem Ihr den Bericht von wachsamen Magiern beschafft.",["race:Undead"]="Als Untoter wisst Ihr, dass die Überreste der Kirin Tor in Mühlenbern den Verlassenen im Silberwald Schwierigkeiten bereiten. Aufklärungsinformationen über ihre Unternehmungen sind für die Sicherheit von Unterstadt von Bedeutung."},sec={{t="Die Stadt im Wiederaufbau",b="Während des Dritten Krieges plünderte die Geißel Dalaran, und Archimonde brachte seine hoch aufragenden Türme zum Einsturz. Zu Beginn des Wiederaufbaus entfernten die überlebenden Magier den Schutzschild der Stadt und begannen ihre Arbeit unter freiem Himmel.\n\nDie Kirin Tor unterhalten Enklaven wie Mühlenbern im südöstlichen Silberwald. Ihre Zauberer stellen den Statusbericht von Dalaran zusammen, der den Zustand der Stadt festhält. Die Todespirscher suchen die darin enthaltenen Aufklärungsinformationen."},{t="Die Prüfung eines Deathstalkers",b="Lord Varimathras hält nach Überresten der Allianz und der Kirin Tor Ausschau und sichert mit ständiger Wachsamkeit die Herrschaft der Verlassenen über Lordaeron. Vernehmungsbeamte der Verlassenen zwangen einen gefangenen Magier der Kirin Tor zu Geständnissen, und der Schreckenslord befahl den Todespirschern, den Bericht zu beschaffen.\n\nDas Dokument liegt in einer verschlossenen Geldkassette tief im Inneren von Mühlenbern. Auch frisch aufgenommene Schurken beschaffen es als Initiationsritus und meistern dabei das Schlossknacken unter Mennet Carkad im Schurkenviertel."}},faq={{q="Was ist der Statusbericht von Dalaran?",a="Der Statusbericht von Dalaran ist eine Sammlung vertraulicher Dokumente der Kirin Tor über Dalarans Zustand, die Wiederaufbauarbeiten und die aktuelle Lage. Magier am Außenposten Mühlenbern stellten ihn zusammen.",al={"was ist dieser bericht","dalaran bericht","mühlenbern dokumente"}},{q="Wo wird der Bericht aufbewahrt?",a="Der Bericht ist in einer Geldkassette in Mühlenbern im südöstlichen Silberwald eingeschlossen.",al={"wo ist der bericht","mühlenbern geldkassette fundort","wie den statusbericht finden"}},{q="Warum will Unterstadt diesen Bericht?",a="Lord Varimathras und die Verlassenen sehen in den überlebenden Kirin Tor eine akute Bedrohung direkt vor ihrer Haustür. Der Bericht hilft den Todespirschern, Dalarans militärische Stärke und die geheimen Wiederaufbauarbeiten einzuschätzen.",al={"warum wollen die verlassenen das","varimathras dalaran bericht","ziel der deathstalkers"}},{q="Wie erfuhren die Todespirscher von dem Dokument?",a="Ein in Unterstadt verhörter Gefangener der Kirin Tor erzählte den Todespirschern von dem Dokument und seinem Aufbewahrungsort.",al={"wie hat unterstadt davon erfahren","geständnis des gefangenen"}}},fx={f1fae308={q="Woher stammt der Statusbericht von Dalaran und wer hat ihn erstellt?",a="Der Bericht wurde von den Zauberern der Kirin Tor verfasst, die in Mühlenbern im südlichen Silberwald stationiert sind. Nach der Verwüstung von Dalaran während des Dritten Krieges unterhalten die überlebenden Magier Außenposten in den umliegenden Regionen, um ihre gefallene Stadt zu überwachen, laufende Angelegenheiten zu dokumentieren und ihre verbleibenden Streitkräfte zu koordinieren.",al={"wer schrieb statusbericht von dalaran","ursprung statusbericht von dalaran","wer erstellte statusbericht von dalaran"}}},fp="21,99,27.420.0,21.456.1,34.173.0,25.84.0,40.202.0,51.122.0"}
P.entries["item:dalin-s-heart"] = {n="Dalins Herz",s="Nahe dem Greymane-Wall im Silberwald beschützt Dalin Forgewright Flüchtlinge mit ehrenhaftem Herzen.",h="Nahe dem Greymane-Wall im Silberwald beschützt Dalin Forgewright Flüchtlinge mit ehrenhaftem Herzen.",kw={"carendin halgar","dalin forgewright","dalins herz","der greymane-wall","hearts of the pure","silberwald","sukkubus","unterstadt"},ang={["class:Warlock"]="Als Hexenmeister der Verlassenen vollzieht Ihr diesen Ritus, um zu lernen, einen Sukkubus zu unterwerfen, und erntet unbefleckte Tugend zur Beherrschung von Dämonen.",["race:Undead"]="Als Untoter seht Ihr die bittere Wirklichkeit Lordaerons nach der Geißel: Lebende, selbstlose Menschen vor dem Greymane-Wall werden zur Beute der Verlassenen."},sec={{t="Ein reines Herz für dunkle Künste",b="Die Hexenmeister von Unterstadt suchen die Herzen wahrhaft tugendhafter Sterblicher. Damit rufen sie einen Sukkubus herbei und binden ihn an ihren Dienst. Dalin Forgewright verbringt seine Tage damit, verzweifelte Flüchtlinge aus Lordaeron zu verteidigen, denen der versiegelte Greymane-Wall den Weg in die Sicherheit versperrt. Seine selbstlose Hingabe macht ihn zu einer seltenen Opfergabe von makelloser Reinheit, und sein Herz wird für Riten im Temple of the Damned herausgeschnitten."}},faq={{q="Wer war Dalin Forgewright?",a="Dalin Forgewright war ein ehrenhafter Mensch, der Flüchtlinge aus Lordaeron beschützte, die vor den verschlossenen Toren des Greymane-Walls im südlichen Silberwald gestrandet waren.",al={"dalin forgewright","wer ist dalin","dalins geschichte"}},{q="Warum brauchen Hexenmeister Dalins Herz?",a="Die Hexenmeister von Unterstadt nutzen Dalins Herz als rituellen Köder, um einen Sukkubus anzulocken und ihn dann an ihren Dienst zu binden.",al={"warum dalins herz","zweck von dalins herz","warum wollen hexenmeister dalins herz"}},{q="Wer nimmt Dalins Herz entgegen?",a="Carendin Halgar, ein Hexenmeisterlehrer im Temple of the Damned in Unterstadt, nimmt Dalins Herz entgegen.",al={"wer nimmt das herz","dalins herz abgeben","wohin dalins herz bringen"}},{q="Welche weitere Zutat wird neben diesem Herzen benötigt?",a="Carendin Halgar benötigt Dalins Herz und Comar's Heart. Comar Villard ist ein treuer Ehemann, der auf der Suche nach seiner verschollenen Frau durch das Sumpfland wandert.",al={"hearts of the pure anderes herz","anderes benötigtes herz","zweites herz"}}},fx={["5b5f5201"]={q="Was ist Dalins Herz?",a="Es ist das buchstäbliche, physische Herz, das Dalin Forgewright herausgeschnitten wurde, einem ehrenhaften Mann, der sich in der Nähe des Greymane-Walls im Silberwald um Flüchtlinge aus Lordaeron kümmerte. Obwohl es sich physisch nicht von jedem anderen menschlichen Herzen unterscheidet, besitzt es die unverwechselbare spirituelle Reinheit einer selbstlosen und tugendhaften Seele.",al={"was ist dalins herz","beschreibung von dalins herz","dalin herz gegenstand"}},d7d2edf8={q="Woher stammt Dalins Herz?",a="Das Herz stammt von Dalin Forgewright, einem rechtschaffenen Mann, der die Flüchtlinge aus Lordaeron am geschlossenen Greymane-Wall im südlichen Silberwald betreut. Ein Hexenmeister muss ihn aufspüren und töten, um das Organ direkt aus seiner Leiche zu entnehmen.",al={"wo bekommt man dalins herz","herkunft von dalins herz","wer lässt dalins herz fallen"}}},fp="13,103,26.378.0,26.159.0,35.105.0,26.107.0,52.144.0"}
P.entries["item:darkhound-blood"] = {n="Schattenhundblut",s="Auf Tirisfals Feldern und in seinen Wäldern liefern verderbte Schattenhunde Schattenhundblut, eine Körperflüssigkeit. Die Royal Apothecary Society sammelt es als frühes Reagenz für Experimente zur Entwicklung einer tödlichen neuen Seuche.",h="Auf Tirisfals Feldern und in seinen Wäldern liefern verderbte Schattenhunde Schattenhundblut, eine...",kw={"a new plague","apotheker johaan","brill","schattenhund","schattenhundblut","royal apothecary society","tirisfal"},ang={["faction:Horde"]="In Brill betreibt die Royal Apothecary Society finstere Experimente, deren giftiges Potenzial außerhalb des inneren Kreises der Verlassenen nur wenige vollständig begreifen.",["race:Undead"]="Das Sammeln von Reagenzien wie Schattenhundblut ist eine unverzichtbare Arbeit für die Verlassenen. Es hilft Fürstin Sylvanas und der Royal Apothecary Society, ihre ultimative Waffe gegen die Geißel zu schmieden."},sec={{t="Nährstoff für die New Plague",b="Unter Fürstin Sylvanas Windläufer sucht die Royal Apothecary Society nach einer hochansteckenden Seuche, die Arthas und seine Geißel auslöschen kann. Apotheker Johaan ist in Brill stationiert. Er vermutet, dass die einheimischen Bestien, von dunklen Energien verderbt und gegen den umgebenden Verfall widerstandsfähig, ungewöhnliche biologische Eigenschaften besitzen.\n\nDurch das Destillieren von Blut wilder Schattenhunde hofft Johaan, Verbindungen zu entdecken, die virulenten nekrotischen Erregerstämmen widerstehen oder sie verbreiten können."}},faq={{q="Wofür wird Schattenhundblut verwendet?",a="Apotheker Johaan in Brill verwendet Schattenhundblut als frühes Reagenz bei den Forschungen der Royal Apothecary Society, um eine neue Seuche zu brauen, die tödlicher ist als alles, was Azeroth je gesehen hat.",al={"schattenhundblut verwendung","warum schattenhundblut sammeln","schattenhundblut zweck"}},{q="Welche Kreaturen liefern dieses Blut?",a="Schattenhundblut stammt von den verfluchten, gefräßigen und altersschwachen Schattenhunden, die durch Tirisfal streifen.",al={"woher schattenhundblut bekommen","wer lässt schattenhundblut fallen","schattenhundblut herkunft"}},{q="Warum werden Schattenhunde für die Seuchenforschung herangezogen?",a="Apotheker Johaan vermutet, dass das Blut von Bestien, die an Tirisfals verderbte Lande angepasst sind, die biologischen Geheimnisse zur Herstellung einer unaufhaltsamen Seuche bergen könnte.",al={"warum schattenhunde","apotheker johaans theorie","schattenhund eigenschaften"}}},fx={db825c3d={q="Was ist Schattenhundblut?",a="Schattenhundblut ist die verseuchte Lebensflüssigkeit, die von den wilden Schattenhunden geerntet wird, die durch das Tirisfal streifen. Diese von dunkler Magie und dem verweilenden Untod gezeichneten, elenden Hunde besitzen Blut, das einzigartige, widerstandsfähige Eigenschaften aufweist. Obwohl es für gewöhnliche Lebewesen abstoßend und gefährlich ist, finden Alchemisten und Forscher es ein ideales Medium für biologische Experimente, insbesondere bei der Untersuchung virulenter Verbindungen oder bei der Abwehr von nekrotischem Verfall.",al={"was ist schattenhundblut","schattenhundblut hintergrund","erklärung schattenhundblut"}},["93cde5f9"]={q="Woher stammt Schattenhundblut und wer hat es hergestellt?",a="Dieses Blut wird auf natürliche Weise von den verfluchten, gefräßigen und verfallenen Schattenhunden geerntet, die die heimgesuchten Wälder und zerstörten Gehöfte von Tirisfal durchstreifen. Es ist kein künstliches Gebräu, sondern die Körperflüssigkeit von Bestien, die sich an die Fäule angepasst und sie in sich aufgenommen haben, die die Region seit dem Dritten Krieg vergiftet.",al={"quelle von schattenhundblut","woher stammt schattenhundblut","wer hat schattenhundblut erschaffen"}}},fp="15,200,23.432.0,33.180.0,33.99.0,48.172.0"}
P.entries["item:darkshore-grouper"] = {n="Dunkelküstenbarsch",s="Entlang der Dunkelküste sind Dunkelküstenbarsche ein häufiger Fang, doch Murlocangriffe haben die Fischer von ihren Booten vertrieben. Die Fische werden als Nahrung und beim Sportangeln geschätzt, und ein guter Fang erfordert Geduld.",h="Entlang der Dunkelküste sind Dunkelküstenbarsche ein häufiger Fang, doch Murlocangriffe haben die Fischer von...",kw={"auberdine","angel der familie blump","dunkelküste","dunkelküstenbarsch","angeln","barsch","gubber blump","murloc"},ang={["profession:Cooking"]="Dunkelküstenbarsche sind eine praktische Zutat für einfache Küstenrezepte. Sie geben reisenden Köchen die Möglichkeit, ihr Handwerk entlang der Küste zu üben.",["race:Dwarf"]="Als Zwerg erkennt Ihr Gubber Blump vielleicht wieder. Mit seiner Fischerei an Kalimdors Küsten führt er das stolze Erbe seiner Familie fort. Er belohnt jene, die beim Fischfang ebenso geschickt sind wie seine Verwandten."},sec={{t="Grundnahrungsmittel der nebligen Küste",b="In den kalten Gewässern der Dunkelküste sind Dunkelküstenbarsche ein willkommener Fang. Rund um Auberdine schätzen Angler sie für die einfachen Gerichte, die sich daraus zubereiten lassen. Reisende und Bewohner genießen diese Mahlzeiten gleichermaßen. Eine Angelschnur und einfache Ausrüstung reichen aus, um einen an Land zu ziehen. Für viele Fischer ist es ebenso erfreulich, einen Barsch zu fangen, wie ihn zu essen."},{t="Die Bedrohung durch Murlocs",b="Fischer wie Gubber Blump ruderten einst mit kleinen Booten in tiefere Gewässer und kehrten mit Dutzenden Barschen zurück. Jetzt sind die Murlocs an der Küste aggressiver, und die meisten Boote rund um Auberdine bleiben an Land. Angler fischen stattdessen vom Ufer und von den Stegen aus. Die Einheimischen vermuten, dass die Murlocs die Barsche fressen, daher erfordert ein guter Fang Geduld."}},faq={{q="Wo sind Dunkelküstenbarsche zu finden?",a="Werft Eure Angelschnur im Salzwasser der Dunkelküste aus, auch in den Gewässern rund um Auberdine, um Dunkelküstenbarsche zu fangen.",al={"wo barsche angeln","dunkelküstenbarsch fundort","wie dunkelküstenbarsche fangen"}},{q="Wer möchte Dunkelküstenbarsche in Auberdine?",a="Gubber Blump, ein zwergischer Fischer, der sich in Auberdine aufhält, bittet Reisende, Dunkelküstenbarsche für ihn zu fangen. Dafür bietet er eine geschätzte Angel der Familie Blump an.",al={"wer braucht barsche","gubber blump fische","barsch questgeber"}},{q="Warum nutzen Fischer keine Boote, um Barsche zu fangen?",a="Aggressive Murlocs entlang der Dunkelküste machen Bootsfahrten für die einheimischen Fischer zu gefährlich.",al={"warum bleiben boote an land","auberdine fischerboote","murlocs barsche"}},{q="Müsst Ihr eine Quest haben, um einen Dunkelküstenbarsch zu fangen?",a="Nein. Dunkelküstenbarsche sind gewöhnliche Salzwasserfische, und jeder Angler kann sie in den Gewässern der Dunkelküste fangen. Einheimische wie Gubber Blump bitten Euch vielleicht, sie zu fangen.",al={"ist barsch ein questgegenstand","barsche jederzeit angeln"}}},fx={bdb033c0={q="Was ist ein Dunkelküstenbarsch?",a="Der Dunkelküstenbarsch ist ein lokaler Salzwasserfisch, der vor der nebligen Küste der Dunkelküste schwimmt. Er wird von einheimischen Anglern wie Gubber Blump sehr geschätzt und ist sowohl als großartiger Fang aus der Brandung als auch als vielseitiges Gericht für die heimische Küche beliebt.",al={"was ist ein dunkelküstenbarsch","dunkelküstenbarsch fisch","über dunkelküstenbarsch"}},["97e4a4d8"]={q="Woher stammt der Dunkelküstenbarsch?",a="Der Dunkelküstenbarsch ist ein wilder Salzwasserfisch, der in den Küstengewässern entlang der Dunkelküste heimisch ist. Er wird von niemandem hergestellt oder erschaffen, obwohl das Fangen das Auswerfen einer Angel in die Brandung vor der Küste und den Docks erfordert.",al={"ursprung dunkelküstenbarsch","woher stammt der dunkelküstenbarsch","woher kommt der dunkelküstenbarsch"}},f987244e={q="Warum möchte Gubber Blump Dunkelküstenbarsch?",a="Gubber Blump liebt es einfach, sie zu fangen und zu essen, und prahlt damit, dass es viele feine Gerichte gibt, die man mit einem frischen Fang zubereiten kann. Da feindselige Murlocs die örtlichen Fischerboote aus dem Wasser vertrieben haben, ist er auf hilfreiche Reisende angewiesen, um sie von der Küste zu holen.",al={"warum dunkelküstenbarsch haben wollen","warum möchte gubber den barsch","wofür wird der dunkelküstenbarsch verwendet"}}},fp="17,190,30.313.0,17.326.0,37.111.0,41.162.0,50.95.0,58.160.0"}
P.entries["item:darksoul-shackle"] = {n="Dunkelseelenfessel",s="Moonrage Darksouls im Silberwald tragen verzauberte Fesseln, die unter Erzmagier Arugals Anleitung geschmiedet wurden. Im Grabmal suchen Magier der Verlassenen nach ihnen, um zu erfahren, wie sich die Magie aufheben lässt, die die Region im Griff hält.",h="Moonrage Darksouls im Silberwald tragen verzauberte Fesseln, die unter Erzmagier Arugals Anleitung...",kw={"arugal","dalar morgenweber","dunkelseelenfessel","moonrage darksoul","das grabmal","silberwald","worgen"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie ein verzweifelter Zauberer grobe verzauberte Artefakte nutzte, um unbeständige Beschwörungszauber zu stützen, die er nicht richtig beherrschen konnte.",["race:Undead"]="Für die Verlassenen ist es entscheidend, Arugals Herrschaft über den Silberwald zu brechen, um ihre südlichen Grenzen zu schützen und angesichts von Dalarans Fehlschlägen die Überlegenheit der arkanen Gelehrsamkeit Unterstadts zu beweisen."},sec={{t="Eine Krücke für schwächelnde Magie",b="Erzmagier Arugal konnte die Worgen, die er auf den Silberwald losließ, weder vollständig beherrschen noch dauerhaft erhalten. Also band er verzauberte Werkzeuge wie Dunkelseelenfesseln an die Bestien. Die Fesseln leiten fremde Zauberei in die Moonrage Darksouls, stärken sie und verankern den Fluch, der sie in der Knechtschaft von Burg Shadowfang hält."},{t="Prüfung der Kirin Tor",b="Im Grabmal hält Dalar Morgenweber, ein Magier der Verlassenen, Arugal für einen gefährlichen Stümper. Er glaubt, dass Arugals Einmischung die Verteidigung der Kirin Tor gegen die Geißel ruinierte. Forscher der Verlassenen sammeln Dunkelseelenfesseln und Fesseln, die Moonrage Gluttons entrissen wurden, und ziehen dann die im Metall verbliebenen Verzauberungen heraus. Ihre Untersuchung offenbart Mängel in Arugals Zauberkunst und liefert den Verlassenen arkane Erkenntnisse, um eine Gegenmaßnahme gegen seine Wolfsplage zu entwickeln."}},faq={{q="Was ist eine Dunkelseelenfessel?",a="Die Moonrage Darksoul-Worgen im Silberwald tragen verzauberte Metallfesseln, die Dunkelseelenfesseln genannt werden. Erzmagier Arugal fertigte sie an, um seine Zauberkunst zu verstärken und die Bestien seiner Kontrolle zu unterwerfen.",al={"was sind dunkelseelenfesseln","dunkelseelenfessel gegenstand hintergrund","was ist diese fessel"}},{q="Wer sucht Dunkelseelenfesseln?",a="Dalar Morgenweber, ein Magier der Verlassenen im Grabmal im Silberwald, sucht Dunkelseelenfesseln. Er untersucht ihre Verzauberungen, um eine Lösung für Arugals Worgenplage zu finden.",al={"wer braucht dunkelseelenfesseln","wer nimmt die fesseln","dalar morgenweber quest"}},{q="Woher stammen diese Fesseln?",a="Moonrage Darksouls, aggressive Worgen, die den nördlichen und östlichen Silberwald heimsuchen, tragen diese Fesseln.",al={"wer lässt dunkelseelenfesseln fallen","dunkelseelenfessel gegner","wo bekommt man eine dunkelseelenfessel"}},{q="Warum legte Arugal den Worgen Fesseln an?",a="Dalar Morgenweber sagt, Arugal habe das Talent gefehlt, die Bestien allein durch schiere Macht zu beherrschen. Arugal verließ sich auf verzauberte Gegenstände wie diese Fesseln, um die unbeständige Magie zu kanalisieren und aufrechtzuerhalten, die das Rudel zusammenhielt.",al={"warum tragen worgen fesseln","arugal fesseln zweck"}}},fp="16,207,28.323.0,18.453.1,27.193.0,28.177.0,34.107.0,42.219.0"}
P.entries["item:darnassus-marzipan"] = {n="Marzipan aus Darnassus",s="Zu den Schlotternächten bieten Gastwirte in Darnassus Besuchern nach einem Tanz Marzipan an. Er wird in der Hauptstadt der Nachtelfen für das Herbstfest hergestellt und ist eine von vier Leckereien, die Jesper braucht.",h="Zu den Schlotternächten bieten Gastwirte in Darnassus Besuchern nach einem Tanz Marzipan an.",kw={"süßigkeiten","darnassus","marzipan aus darnassus","schlotternächte","jesper","marzipan","leckereien"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Leckereien aus Darnassus, Eisenschmiede und Sturmwind sammeln. Die Schlotternächte bringen die weit verstreuten Völker der Allianz zu gemeinsamen Feierlichkeiten zusammen.",["race:NightElf"]="Als kaldorei könnt Ihr die unbeschwerten Bräuche des Herbstes teilen. Gastwirte in Darnassus bieten Reisenden zuckersüßen Marzipan an, wenn sie ihre Gastfreundschaft mit einem lebhaften Tanz würdigen."},sec={{t="Ein Geschmack des Weltbaums",b="Zu den Schlotternächten teilen die Hauptstädte der Allianz einen ausgelassenen Streiche-oder-Süßes-Brauch. Zwerge bieten scharfe Minzbonbons an, Sturmwind stellt zähen Nougat her, und Gastwirte in Darnassus bereiten zarten Marzipan zu. Tanzt, wenn ein Gastwirt Euch darum bittet, und Ihr erhaltet ein Stück.\n\nJesper braucht die Süßigkeit als eine von vier regionalen Leckereien. Er ist ein kranker Waisenjunge auf Sturmwinds Kathedralenplatz und kann nicht selbst losziehen, um sie zu sammeln."}},faq={{q="Wofür wird Marzipan aus Darnassus verwendet?",a="Während der Schlotternächte braucht Jesper Marzipan aus Darnassus als eine von vier verschiedenen Süßigkeiten. Er ist ein kranker Waisenjunge im Waisenhaus auf Sturmwinds Kathedralenplatz. Bringt ihm den Marzipan zusammen mit Süßigkeiten aus Eisenschmiede, Gnomeregan und Sturmwind, und Ihr erhaltet ein Bündel festlicher Kürbisleckereien.",al={"marzipan aus darnassus verwendung","was tun mit marzipan"}},{q="Wie erhaltet Ihr Marzipan aus Darnassus?",a="Während der Schlotternächte bitten Euch die Gastwirte in Darnassus um einen kurzen Tanz und geben Euch danach Marzipan aus Darnassus.",al={"wie marzipan aus darnassus bekommen","wo marzipan bekommen"}},{q="Warum kann Jesper den Marzipan nicht selbst holen?",a="Jesper ist krank und kann nicht losziehen, um mit Streichen Süßigkeiten zu sammeln. Er ist im Waisenhaus von Sturmwind am Kathedralenplatz und ist auf Abenteurer angewiesen, die ihm die Leckereien aus der Ferne bringen.",al={"warum braucht jesper süßigkeiten","warum kann jesper nicht losziehen"}}},fx={cf1db7fa={q="Woher stammt Marzipan aus Darnassus und wer hat es hergestellt?",a="Das Konfekt stammt aus der Hauptstadt der Nachtelfen, Darnassus, auf den Zweigen von Teldrassil. Während der Schlotternächte verteilt der Gasthauswirt der Stadt die süße Leckerei an Besucher, die die Taverne mit einem Tanz unterhalten, was die Verbundenheit und Fröhlichkeit der Allianz in ganz Kalimdor und den Östlichen Königreichen feiert.",al={"woher stammt marzipan aus darnassus","wer macht marzipan aus darnassus","ursprung von marzipan aus darnassus"}},["1983589f"]={q="Warum möchte irgendjemand Marzipan aus Darnassus?",a="Neben der Tatsache, dass es eine elfenhafte Festtagsdelikatesse ist, ist es bei denjenigen begehrt, die die Schlotternächte nicht allein feiern können. Jesper, ein kranker Waisenjunge am Kathedralenplatz in Sturmwind, bittet Reisende, in seinem Namen „Süßes oder Saures“ zu spielen, damit er Leckereien aus der ganzen Allianz genießen kann.",al={"warum marzipan aus darnassus haben wollen","wer möchte marzipan aus darnassus","warum marzipan aus darnassus sammeln"}},["06b4a124"]={q="Was ist Marzipan aus Darnassus?",a="Marzipan aus Darnassus ist eine festliche Süßigkeit, die in der Nachtelfenhauptstadt Darnassus hergestellt wird. Diese Süßigkeit aus Mandelmasse wird während des Herbstfestes Hallow's End an Feiernde verteilt und gehört zu den vier traditionellen Festsüßigkeiten für Reisende, die dafür festliche Kunststücke vorführen.",al={"was ist marzipan aus darnassus","marzipan aus darnassus hintergrundgeschichte","was für eine süßigkeit ist marzipan aus darnassus"}}},fp="18,175,25.396.0,36.271.0,37.102.0,42.169.0"}
P.entries["item:darthalia-s-sealed-commendation"] = {n="Darthalias versiegelte Belobigung",s="In Tarrens Mühle meldet Darthalia dem Oberkommando von Unterstadt Siege gegen Hillsbrads menschliche Verteidiger.",h="In Tarrens Mühle meldet Darthalia dem Oberkommando von Unterstadt Siege gegen Hillsbrads menschliche...",kw={"belobigung","darthalia","hillsbrad","süderstade","tarrens mühle","unterstadt","varimathras"},ang={["faction:Horde"]="Für die Horde hält die Belobigung einen strategischen Sieg in Lordaeron fest. Sie zeigt Unterstadts Führung, dass die Festungen der Allianz im südlichen Vorgebirge zerschlagen werden können.",["race:Undead"]="Als Untoter verbessert Ihr Euer Ansehen in der wachsenden Militärhierarchie der Dark Lady, indem Ihr Darthalias Lob verdient und die Belobigung zum Thronsaal bringt."},sec={{t="Bericht ans Oberkommando",b="Nach den Kämpfen im Vorgebirge des Hügellands versiegelt Hochexekutorin Darthalia eine Depesche über Siege gegen die menschlichen Verteidiger und die Zerstörung ihrer Stellungen. Sie schickt sie an Varimathras, den Schreckenslord, der Fürstin Sylvanas Windläufer berät. Im Königsviertel von Unterstadt liefert der Bericht den Anführern der Verlassenen den Beweis, dass Enklaven der Allianz südlich von Lordaeron gebrochen werden können. Dann können sich die nördlichen Garnisonen der Geißel zuwenden."}},faq={{q="Was ist Darthalias versiegelte Belobigung?",a="In Tarrens Mühle verfasst Hochexekutorin Darthalia eine versiegelte Belobigung für die Leistungen eines Kämpfers gegen die Allianz in der Battle of Hillsbrad. Sie schickt sie an das Oberkommando von Unterstadt.",al={"versiegelte belobigung","darthalias brief","hillsbrad bericht"}},{q="Wer erhält diese Belobigung?",a="Varimathras erhält die Belobigung. Er ist der Schreckenslord, der Fürstin Sylvanas Windläufer im Königsviertel von Unterstadt berät.",al={"wem das bringen","belobigung abgeben","wer erhält darthalias belobigung"}},{q="Warum sind die Kämpfe in Hillsbrad für Varimathras von Bedeutung?",a="Die Verlassenen stehen im Norden dem Lich King und seiner Geißel gegenüber. Unterdessen stören die Menschen von Hillsbrad ihre Versorgungslinien und gefährden die Sicherheit ihrer Südgrenze. Varimathras schätzt Siege, die dieses Hindernis beseitigen und Unterstadts Truppen erlauben, sich auf den größeren Krieg zu konzentrieren.",al={"warum es varimathras interessiert","hillsbrad schreckenslord","strategie der verlassenen in hillsbrad"}}},fx={fd99e080={q="Woher stammt Darthalias versiegelte Belobigung und wer hat sie verfasst?",a="Dieser Brief wurde von Darthalia geschrieben und versiegelt, einer Kommandantin der Verlassenen, die die Streitkräfte der Horde im Vorgebirge des Hügellands koordiniert. In Anerkennung Eurer Tapferkeit und unermüdlichen Ausdauer während des erbitterten Feldzugs gegen die Siedlungen der Menschen im Hillsbrad hat sie dieses offizielle Schreiben verfasst, um Eure Leistungen auf dem Schlachtfeld persönlich vor dem Oberkommando zu loben.",al={"wer schrieb darthalias belobigung","woher stammt darthalias belobigung","wer gab versiegelte belobigung"}},["9dfe1fb6"]={q="Warum will Varimathras Darthalias versiegelte Belobigung?",a="Darthalia sendet das Dokument direkt an Varimathras in der Unterstadt, damit die Führung der Verlassenen von Eurer tödlichen Effektivität Notiz nimmt. Während der Schreckenslord die Geißel im Norden als die größte Bedrohung ansieht, stören die Menschen der Allianz im Hillsbrad ihre umfassenderen strategischen Pläne. Diese Belobigung beweist offiziell, dass entscheidende Schläge gegen menschliche Siedlungen unter fähigen Feldchampions wie Euch erfolgreich sein können.",al={"warum versiegelte belobigung überbringen","warum will varimathras die belobigung","zweck von darthalias belobigung"}}},fp="31,114,22.419.0,40.187.0,31.124.0,58.260.0"}
P.entries["item:deadmire-s-tooth"] = {n="Schlammwühlers Zahn",s="In den Düstermarschen zeugt Schlammwühlers Zahn von einer vollendeten Jagd. Melor Steinhuf auf der Anhöhe der Jäger in Donnerfels nimmt ihn als Beweis entgegen, dass das Leiden des uralten Krokilisken beendet ist.",h="In den Düstermarschen zeugt Schlammwühlers Zahn von einer vollendeten Jagd.",kw={"krokilisk","deadmire","düstermarschen","die anhöhe der jäger","melor steinhuf","donnerfels","zahn"},ang={["class:Hunter"]="Als Jäger lernt Ihr von den Lehrmeistern der Anhöhe der Jäger, dass die Jagd neben dem Streben nach Trophäen auch Respekt und Barmherzigkeit verlangt.",["race:Tauren"]="Als Tauren seht Ihr die Jagd auf Deadmire als Teil des Kreislaufs des Gleichgewichts der Earth Mother. Alte Raubtiere werden zum Frieden geleitet, statt ihrem Leiden überlassen zu werden."},sec={{t="Eine Trophäe der Barmherzigkeit",b="Taurenjäger auf der Anhöhe der Jäger sehen die Jagd als einen Bund aus Gleichgewicht, Ehrfurcht und Barmherzigkeit. Deadmire zählte einst zu den prächtigsten Krokilisken der Düstermarschen. Das Alter machte seine letzten Jahre zur Qual, doch der wilde Geist seiner besten Jahre blieb erhalten. Seine gewaltigen Knochen und sein nachlassender Körper waren zu einem Gefängnis voller Schmerzen geworden. Schlammwühlers Zahn beweist Melor Steinhuf, dass eine ehrenvolle Jagd das Leiden der Bestie beendet hat."}},faq={{q="Wofür wird Schlammwühlers Zahn verwendet?",a="Bringt Schlammwühlers Zahn zu Melor Steinhuf auf der Anhöhe der Jäger in Donnerfels. Er schließt die von ihm aufgetragene Jagd ab und beweist, dass Deadmire eine barmherzige Erlösung gewährt wurde.",al={"schlammwühlers zahn abgeben","wer will schlammwühlers zahn","was tun mit schlammwühlers zahn"}},{q="Woher stammt Schlammwühlers Zahn?",a="Schlammwühlers Zahn stammt von Deadmire, einem gewaltigen, uralten Krokilisken im Süden der Düstermarschen. Er durchstreift die Gewässer östlich von Tabetha's Farm.",al={"wo schlammwühlers zahn bekommen","wer lässt schlammwühlers zahn fallen","deadmire fundort"}},{q="Warum will Melor Steinhuf Deadmire töten lassen?",a="Melor Steinhuf sieht in Deadmire ein edles Geschöpf, das im hohen Alter schrecklich leidet. Die Jagd gewährt Barmherzigkeit und lässt die Flamme des Krokilisken friedlich erlöschen, statt ihn unter Qualen dahinsiechen zu lassen.",al={"warum deadmire töten","melor steinhuf grund","ist deadmire böse"}}},fx={["4f19a846"]={q="Was ist Schlammwühlers Zahn?",a="Schlammwühlers Zahn ist eine Trophäe aus dem Kiefer von Schlammwühler, einem massiven und uralten Krokodil, das in den Sümpfen der Düstermarschen lauert. Für Jäger, die sich an den Traditionen der Tauren in Donnerfels orientieren, dient der Zahn als physischer Beweis dafür, dass die mächtige Bestie aufgespürt und ihr ein gnädiges Ende bereitet wurde.",al={"schlammwühlers zahn","was ist der zahn von schlammwühler","infos zu schlammwühlers zahn"}},["200b2360"]={q="Warum will überhaupt jemand Schlammwühlers Zahn haben?",a="Melor Steinhuf, ein Jägerlehrer auf der Anhöhe der Jäger in Donnerfels, verlangt nach dem Zahn als Beweis für Eure Jagd. Deadmire lebt aufgrund seines extremen Alters und knirschender alter Knochen in ständigen, quälenden Schmerzen. Die Tauren verehren die Natur und betrachten Gnade als Teil der heiligen Pflicht eines Jägers; das Vorzeigen des Zahns versichert Melor, dass Ihr das Leiden der edlen Bestie beendet habt.",al={"warum schlammwühlers zahn bringen","wer will schlammwühlers zahn","warum will melor den zahn"}}},fp="16,199,17.401.0,34.162.0,38.141.0,46.198.0"}
P.entries["item:death-cap"] = {n="Todeskappe",s="In Dunkelküste wächst die Todeskappe in einer Höhle hinter den Cliffspring Falls. Kräuterkundige der Nachtelfen suchen den seltenen Pilz, doch der Hain der Uralten warnt davor, sich den Wasserfällen zu nähern.",h="In Dunkelküste wächst die Todeskappe in einer Höhle hinter den Cliffspring Falls.",kw={"auberdine","barithras mondschatten","cave mushrooms","cliffspring falls","dunkelküste","todeskappe","der hain der uralten","schorfstängling"},ang={["profession:Herbalism"]="Um Todeskappen für Barithras zu sammeln, braucht es keine besondere Sichel. Kräuterkundige kennen die Gefahr, in feuchten, verderbten Höhlen nach seltenen Pilzen zu suchen.",["race:NightElf"]="Als Nachtelf könnt Ihr Barithras in Auberdine Todeskappen bringen und die Warnung des Hains der Uralten beherzigen."},sec={{t="Giftige Blüte im Dunkeln",b="Die Todeskappe wächst in einer feuchten Höhle hinter den Cliffspring Falls, entlang der nordöstlichen Gebirgskämme von Dunkelküste. Schorfstänglinge bedecken den Höhlenboden, doch die Todeskappe ist selten. Kräuterkundige der Nachtelfen wie Barithras Mondschatten schätzen sie für experimentelle Gebräue. Um auch nur ein Exemplar zu finden, müsst Ihr eine Höhle betreten, vor der der Hain der Uralten warnt und in der Verderbnis Wurzeln schlägt."},{t="Omen von Cliffspring",b="Wächter des Hains der Uralten warnten die einheimischen Kaldorei davor, sich den Cliffspring Falls zu nähern. Sie spürten eine finstere Präsenz, die in der Dunkelheit Wurzeln schlug. Wer die Höhle auf der Suche nach einer Todeskappe betritt, muss sich den Kräften stellen, die die feuchte Höhlung als ihren Unterschlupf beansprucht haben."}},faq={{q="Wo kann ich eine Todeskappe finden?",a="Die Todeskappe wächst in einer verborgenen Höhle hinter den Cliffspring Falls, an der Gebirgswand im Nordosten von Dunkelküste.",al={"todeskappe fundort","wo ist die todeskappe","cliffspring höhlenpilz"}},{q="Wer sucht diesen Pilz?",a="Barithras Mondschatten, ein Alchemist in der Küstensiedlung Auberdine, sucht die Todeskappe für einen besonderen Trank.",al={"wer braucht todeskappen","barithras pilzquest"}},{q="Warum hat Barithras Mondschatten sie nicht selbst gesammelt?",a="Wächter aus dem Hain der Uralten warnten Barithras davor, die Höhle hinter den Cliffspring Falls zu betreten. Sie spürten dort ein vordringendes Übel.",al={"warum holt er sie nicht selbst","barithras warnung"}},{q="Wie unterscheidet sich die Todeskappe von einem Schorfstängling?",a="Schorfstänglinge wachsen reichlich auf dem Boden der Höhle von Cliffspring, während die Todeskappe selten und schwerer zu finden ist.",al={"todeskappe oder schorfstängling","unterschied zwischen den pilzen"}}},fx={["508b05a0"]={q="Was ist eine Todeskappe?",a="Die Todeskappe ist ein überaus seltener und starker Pilz, der tief in den schattigen Winkeln der Dunkelküste gefunden wird. Im Gegensatz zu gewöhnlichen Waldpilzen gedeiht er nur in bestimmten, versteckten Höhlen, wie zum Beispiel der Höhle hinter den Cliffspring Falls. Sein unheilvoller Name spiegelt sowohl seine Seltenheit als auch seine potenzielle Gefahr wider und macht ihn zu einem geschätzten Exemplar für Alchemisten und Kräuterkundige, die die einzigartige Flora der Region studieren.",al={"was ist eine todeskappe","todeskappe pilz","was für ein pilz ist die todeskappe"}}},fp="9,179,25.367.0,19.265.1,29.111.0,24.113.0,50.140.0,50.115.0"}
P.entries["item:deathstalker-report"] = {n="Todespirscherbericht",s="Im Silberwald meldet Deathstalker Rane Yorick Hochexekutor Hadrec Widerstand der Geißel.",h="Im Silberwald meldet Deathstalker Rane Yorick Hochexekutor Hadrec Widerstand der Geißel.",kw={"todespirscherbericht","hadrec","quinn","rane yorick","geißel","das grabmal","silberwald"},ang={["class:Rogue"]="Als Schurke könnt Ihr erkennen, wie die verdeckte Aufklärung der Todespirscher dazu beiträgt, das Militär der Verlassenen funktionsfähig zu halten.",["race:Undead"]="Als Untoter kennt Ihr die Gefahr, der sich Todespirscher aussetzen, wenn sie für Sylvanas an Lordaerons Grenzen Informationen sammeln."},sec={{t="Nachrichten von der Front",b="Die Todespirscher Rane Yorick und Quinn Yorick gerieten im nördlichen Silberwald in einen tödlichen Hinterhalt. Von der Geißel zwischen den Kiefern festgesetzt, fassten sie ihre Erkenntnisse in einer eiligen Depesche zusammen. Der Bericht beschreibt stärkeren Widerstand, als die Verlassenen bei ihrem Versuch erwartet hatten, die Region für sich zu beanspruchen.\n\nQuinn wurde schwer verletzt, weshalb Rane den Bericht vorbeikommenden Verbündeten anvertraute. Sie müssen ihn unverzüglich zu Hochexekutor Hadrec am Grabmal bringen."}},faq={{q="Was ist der Todespirscherbericht?",a="Der Bericht hält die Aktivitäten der Geißel sowie die Gefahren und Hindernisse fest, denen die Späher der Verlassenen im Silberwald begegneten.",al={"was ist dieser bericht","todespirscherbericht hintergrund","was ist der todespirscherbericht"}},{q="Wer hat den Bericht verfasst?",a="Deathstalker Rane Yorick verfasste den Bericht, nachdem sie ihren verletzten Bruder, Deathstalker Quinn, nach ihrer Begegnung mit der Geißel versorgt hatte.",al={"wer hat den todespirscherbericht verfasst","verfasser des berichts","wer hat ihn verfasst"}},{q="Wem wird der Bericht überbracht?",a="Der Bericht ist an Hochexekutor Hadrec am Grabmal gerichtet, wo er die Streitkräfte der Verlassenen im Silberwald befehligt.",al={"wohin geht der bericht","wer bekommt den bericht","hadrec bericht"}},{q="Warum wird der Bericht so dringend benötigt?",a="Hadrec hatte die Präsenz der Geißel im Silberwald unterschätzt. Der Bericht beschreibt diese feindlichen Streitkräfte und liefert ihm Informationen, um die Besetzungsbemühungen der Verlassenen in der Region abzusichern.",al={"warum ist er wichtig","warum braucht hadrec ihn","welche informationen enthält er"}}},fp="19,104,22.444.0,32.107.0,21.143.0,31.121.0,37.186.0"}
P.entries["item:decrypted-letter"] = {n="Decrypted Letter",s="Der Decrypted Letter ist eine rätselhafte Botschaft, die unter Dieben des Syndikats in den Ausläufern des Alteracgebirges gefunden wurde. Magistrat Maleb in Süderstade fürchtet, dass die Diebe einer anderen Macht dienen.",h="Der Decrypted Letter ist eine rätselhafte Botschaft, die unter Dieben des Syndikats in den Ausläufern des...",kw={"ausläufer des alteracgebirges","rätselhafte botschaft","decrypted letter","weitere geheimnisse","magistrat maleb","süderstade","syndikat"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr die Botschaft aus den Ausläufern des Alteracgebirges zu Magistrat Maleb nach Süderstade bringen, wo er die Bedrohung einschätzen kann."},sec={{t="Eine seltsame Botschaft",b="In den Ausläufern des Alteracgebirges gibt es mehr als nur Diebe: Der Decrypted Letter, gefunden in einem Lager des Syndikats, beunruhigt Magistrat Maleb aus Süderstade. Seine Worte sind rätselhaft, und Maleb erkennt, dass weder ein Dieb noch ein Adliger aus Alterac sie verfasst hat. Er vermutet, dass das Syndikat Verbindungen zu einer anderen Macht hat, doch der Brief lässt ihn fürchten, was das bedeuten könnte."}},faq={{q="Wo wurde der Decrypted Letter gefunden?",a="Der Decrypted Letter wurde in einem Lager des Syndikats in den Ausläufern des Alteracgebirges gefunden.",al={"fundort","fundort des briefes","brief des syndikats"}},{q="Wer soll den Brief erhalten?",a="Magistrat Maleb in Süderstade soll den Decrypted Letter erhalten.",al={"wer erhält ihn","wohin den brief bringen","magistrat maleb"}},{q="Was hält Maleb von dem Brief?",a="Maleb sagt, der Brief sei weder von einem Dieb noch von einem Adligen aus Alterac verfasst worden. Er vermutet, dass das Syndikat Verbindungen zu einer anderen Macht hat.",al={"was steht darin","malebs reaktion","bedeutung des rätselhaften briefes"}},{q="Wer hat den Brief verfasst?",a="Maleb sagt, der Brief sei weder von einem Dieb noch von einem Adligen aus Alterac verfasst worden. Sein Verfasser bleibt unbekannt.",al={"verfasser des briefes","wer hat ihn geschickt","kein dieb"}}},fp="16,190,17.351.0,37.82.0,30.67.0,35.127.0,21.102.0"}
P.entries["item:deepfury-s-orders"] = {n="Tiefenzorns Befehle",s="Unter dem Thandol-Übergang liegen Tiefenzorns Befehle neben dem gefallenen Ol' Rustlocke. Dunkeleisenzwerge ließen das zerknitterte Pergament zurück, nachdem sie dem kundschaftenden Verteidiger aufgelauert hatten.",h="Unter dem Thandol-Übergang liegen Tiefenzorns Befehle neben dem gefallenen Ol' Rustlocke.",kw={"dunkeleisen","deepfury","befehle","rhag garmason","rustlocke","thandol-übergang","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz erkennt Ihr, dass die abgefangenen Befehle einen Sabotageversuch gegen die wichtigste Landverbindung zwischen Dun Morogh, dem Sumpfland und den nördlichen Allianzaußenposten offenbaren.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass die Machenschaften der Dunkeleisenzwerge unter dem Thandol-Übergang Eisenschmiede tief treffen. Der Übergang ist eine der größten Ingenieursleistungen Eures Königreichs und eine lebenswichtige Handelsverbindung nach Norden."},sec={{t="Ein Griff unter dem Übergang",b="Ol' Rustlocke war ein zwergischer Verteidiger, der die Fundamente des Thandol-Übergangs auskundschaftete. Dunkeleisenzwerge trieben ihn dort in die Enge und erschlugen ihn. Neben seiner geballten Faust lagen zerknitterte Befehle, verfasst von ihrem Anführer Deepfury. Die Befehle offenbaren ein koordiniertes Komplott gegen die Brücke zwischen dem Sumpfland und dem Arathihochland."},{t="Die Bedrohung aufdecken",b="Als Rhag Garmason die Befehle erhält, bestätigen sie die schlimmsten Befürchtungen der Brückengarnison. Dunkeleisenzwerge haben Einsätze unter dem Mauerwerk des Thandol-Übergangs geplant. Rhag fordert dringend Verstärkung aus Eisenschmiede und Sturmwind an."}},faq={{q="Was sind Tiefenzorns Befehle?",a="Tiefenzorns Befehle sind militärische Anweisungen, die der Dunkeleisenkommandant Deepfury verfasst hat. Sie wurden neben Ol' Rustlockes Leichnam unter dem Thandol-Übergang gefunden.",al={"tiefenzorns befehle","was sind diese befehle","deepfurys pergament"}},{q="Wo werden die Befehle gefunden?",a="Das zerknitterte Pergament lag neben Ol' Rustlockes geballter Faust in den höhlenartigen Stützbauten unter dem Thandol-Übergang im nördlichen Sumpfland.",al={"wo sind die befehle","rustlockes standort","tiefenzorns befehle finden"}},{q="Wer war Ol' Rustlocke?",a="Ol' Rustlocke war ein zwergischer Späher, der am Thandol-Übergang stationiert war. Er untersuchte seltsame Aktivitäten an den Brückenstützen, wo ihm Dunkeleisenzwerge auflauerten.",al={"wer ist rustlocke","ol' rustlockes geschichte"}},{q="Wer erhält Tiefenzorns Befehle?",a="Tiefenzorns Befehle werden zu Rhag Garmason gebracht, dem zwergischen Kommandanten, der in Dun Modr nahe dem Thandol-Übergang ausharrt. Er liest sie, um die Bedrohung durch die Dunkeleisenzwerge einzuschätzen.",al={"zu wem die befehle bringen","rhag garmason"}}},fx={["21094d89"]={q="Woher stammen Tiefenzorns Befehle?",a="Diese schriftlichen Befehle stammen vom Dunkeleisenclan und sind nach Tiefenzorn benannt, einem Agenten oder Anführer, der die Feindseligkeiten rund um The Thandol Span orchestriert. Sie wurden von den Dunkeleisenzwergen mitgeführt, die den Bergsteiger Ol' Rustlocke überfielen und ermordeten, und wurden neben seinem gefallenen Körper im Dreck zurückgelassen.",al={"wer hat tiefenzorns befehle geschrieben","quelle von tiefenzorns befehlen","wer hat tiefenzorns befehle erstellt"}},ac08f373={q="Warum will Rhag Garmason Tiefenzorns Befehle?",a="Rhag Garmason benötigt greifbare Beweise dafür, was seinem vermissten Späher Ol' Rustlocke zugestoßen ist. Das Pergament liefert eine düstere Bestätigung für den Tod des Bergsteigers und deckt die feindseligen Machenschaften auf, die die Dunkeleisenzwerge in der Nähe der Brücke in die Wege leiten.",al={"warum tiefenzorns befehle zu rhag bringen","warum werden tiefenzorns befehle gesucht","rhag garmason befehle"}}},fp="17,165,24.310.0,21.239.1,27.158.0,27.140.0,22.170.0,31.161.0"}
P.entries["item:deepmoss-egg"] = {n="Kluftmoosei",s="Im Steinkrallengebirge locken Kluftmooseier Goblinhändler aus Ratschet an. Kluftmoosspinnen legen dicht gedrängte Gelege in den Klippen und Schluchten ab, und die Piraten von Beutebucht schätzen sie für Omelettes.",h="Im Steinkrallengebirge locken Kluftmooseier Goblinhändler aus Ratschet an.",kw={"beutebucht","kluftmoosei","kluftmoosspinne","mebok mizzyrix","ratschet","sishircanyon","steinkrallengebirge","die scherwindklippe"},ang={["profession:Cooking"]="Als Koch zögert Ihr vielleicht, Spinneneier zu verwenden. Die Gäste von Beutebucht schätzen aufgeschlagene Eier als abenteuerliche Delikatesse und zahlen dafür Goblinpreise."},sec={{t="Eine Delikatesse der Klippen",b="Kluftmoosspinnen nisten im ganzen Steinkrallengebirge, besonders im Sishircanyon und unter den verbliebenen Bäumen der Scherwindklippe. Dort hinterlassen sie dicht gedrängte Gelege lebensfähiger Eier in dicken Gespinstsäcken, geschützt von feuchtem Bergmoos. Die meisten Reisenden haben wenig Verwendung dafür, doch Goblinhändler wittern Gewinn."},{t="Beutebuchts kulinarische Mode",b="Beutebucht hat Gefallen an Spinnenei-Omelettes gefunden, einer ausgefallenen Mode unter wohlhabenden Piraten und abenteuerlustigen Feinschmeckern. Die Vorräte vor Ort können ihren Appetit nicht stillen, deshalb organisiert Mebok Mizzyrix aus Ratschet Lieferungen über Werftmeister Dizzywig. Sammler trotzen der giftigen Brut des Steinkrallengebirges, um frische Gelege zu beschaffen, und die Eier werden zu wertvoller Fracht."}},faq={{q="Wo findet man Kluftmooseier?",a="Kluftmooseier findet man im Steinkrallengebirge, nordwestlich des Brachlands. Gelege häufen sich unter den verbliebenen Bäumen der Scherwindklippe und tiefer in den von giftigen Spinnen bewohnten Nestern des Sishircanyons.",al={"fundorte der eier","wo bekommt man kluftmooseier","kluftmoosei fundort"}},{q="Wer lässt diese Eier sammeln?",a="Mebok Mizzyrix, ein Goblinhändler in Ratschet, heuert Sammler an, um Kluftmooseier zusammenzutragen. Er sorgt dafür, dass Werftmeister Dizzywig die Gelege über das Meer verschifft.",al={"wer braucht kluftmooseier","wer kauft kluftmooseier","mebok mizzyrix quest"}},{q="Wofür werden die Eier eigentlich verwendet?",a="Die Eier gehen nach Beutebucht, wo Spinnenei-Omelettes unter Piraten und anderen Gästen zu einer beliebten, wenn auch bizarren Mode geworden sind.",al={"verwendung von spinneneiern","warum spinneneier sammeln","spinnenei-omelettes"}},{q="Warum wird beim Eiersammeln vor dem Sishircanyon gewarnt?",a="Der Sishircanyon ist voller ausgewachsener Spinnen, Netze und aufgefressener Beute. Mebok rät allen mit empfindlichem Magen, die Eier stattdessen unter den spärlichen Bäumen der Scherwindklippe zu sammeln.",al={"sishircanyon warnung","empfindlicher magen sishir"}}},fx={["19ff336a"]={q="Was ist ein Kluftmoosei?",a="Ein Kluftmoosei ist das in Gelegen gelegte Ei der Kluftmoosspinnen, die im Steinkrallengebirge beheimatet sind. Diese seidenverpackten Eier, die sich in Baumgruppen und tief in den Gebirgsschluchten befinden, werden hauptsächlich von wagemutigen Abenteurern gesammelt, die auf dem skurrilen kulinarischen Markt auf der anderen Seite des Meeres Kasse machen wollen.",al={"was sind kluftmooseier","kluftmoosei","kluftmooseier"}},["80df5d4f"]={q="Woher kommen Kluftmooseier?",a="Diese Eier werden von den Kluftmoosspinnen gelegt, die die Klippen und Täler des Steinkrallengebirges heimsuchen, insbesondere Die Scherwindklippe und den gefährlichen Sishircanyon. Sie werden auf natürliche Weise in Gelegen in der Nähe überlebender Baumwurzeln und Arachniden-Nester abgelegt, anstatt von einem denkenden Sterblichen hergestellt zu werden.",al={"ursprung der kluftmooseier","woher kommen kluftmooseier","wer legt kluftmooseier"}}},fp="12,192,23.325.0,24.333.0,30.190.0,32.161.0,36.123.0,54.177.0"}
P.entries["item:defiant-orc-head"] = {n="Defiant Orc Head",s="Der Defiant Orc Head liegt nahe dem Swamplight-Anwesen am Hexenhügel in den Düstermarschen. Es ist der abgetrennte Kopf eines Orcs, dessen Tod Nazeer Bloodpike aufklären will.",h="Der Defiant Orc Head liegt nahe dem Swamplight-Anwesen am Hexenhügel in den Düstermarschen.",kw={"brackenwall","defiant orc head","düstermarschen","kin'weelay","marg nighteye","nazeer bloodpike","swamplight-anwesen","troll-hexendoktor","hexenhügel"},ang={["race:Orc"]="Als Orc ist Margs Tod eine düstere Erinnerung daran, dass sein Volk fern der Heimat gefährliche Aufgaben übernimmt.",["race:Troll"]="Als Troll wisst Ihr, dass Kin'weelay wegen seiner Hexenmagie und seiner Fähigkeit, mit Geistern zu sprechen, gesucht wird."},sec={{t="Eine düstere Entdeckung",b="Nazeer Bloodpike in Brackenwall erkennt den Kopf als den von Marg Nighteye. Die zerfetzte Wunde lässt ihn zweifeln, ob eine Waffe oder ein Tier den Orc getötet hat. Er fürchtet, Marg könnte der Allianz zum Opfer gefallen sein, und gibt die Angelegenheit weiter, damit Antworten gefunden werden."}},faq={{q="Wem gehört der Kopf?",a="Der Kopf gehört Marg Nighteye, einem Orc-Agenten, dessen Tod Nazeer Bloodpike beunruhigt.",al={"wer ist der orc","margs kopf","trotziger kopf"}},{q="Wo finde ich den Defiant Orc Head?",a="Er liegt in lockerer Erde neben dem Swamplight-Anwesen am Hexenhügel in den Düstermarschen, nachdem der verlorene Bericht geborgen wurde.",al={"wo ist der kopf","fundort des kopfes","kopf am hexenhügel"}},{q="Wer will den Kopf?",a="Nazeer Bloodpike in Brackenwall will den Kopf, damit er Marg Nighteyes Tod untersuchen kann.",al={"wer braucht ihn","kopf für nazeer","wohin den kopf bringen"}},{q="Warum soll ich ihn zu Kin'weelay bringen?",a="Kin'weelay ist ein mächtiger Hexendoktor der Dunkelspeer, von dem Nazeer glaubt, dass er mit Marg Nighteyes Geist sprechen kann.",al={"warum troll-hexendoktor","kinweelay kopf","mit marg sprechen"}},{q="Wie starb Marg?",a="Nazeer sieht einen zerfetzten Schnitt an Margs Hals und fragt sich, ob eine Waffe oder ein Tier ihn getötet hat. Er fürchtet, die Allianz könnte dafür verantwortlich sein.",al={"wer hat marg getötet","was geschah mit marg","margs tod"}}},fp="16,169,16.246.0,17.84.1,37.120.0,19.99.0,26.106.1,17.133.0"}
P.entries["item:defias-docket"] = {n="Liste der Defias",s="Agenten der Defias versteckten ihre Befehle in Addles Siedlung im westlichen Dämmerwald. Die Liste liefert Sturmwind bei der Suche nach seinem vermissten Gesandten eine Spur zu den Plänen der Bruderschaft.",h="Agenten der Defias versteckten ihre Befehle in Addles Siedlung im westlichen Dämmerwald.",kw={"addles siedlung","liste der defias","geldkassette der defias","dämmerwald","elling trias","the missing diplomat","behüter backus"},ang={["class:Rogue"]="Als Schurke könnt Ihr erkennen, wie die Bruderschaft der Defias hinter dem Anschein gewöhnlichen Banditentums Verschlüsselung und verdeckte Logistik einsetzt.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr erkennen, dass diese Dokumente ein koordiniertes Komplott der Defias enthüllen, das weit über gewöhnliches Banditentum hinausreicht."},sec={{t="Eine Spur ins Dunkel",b="Meister Elling Trias weist Ermittler in Richtung Dämmerwald, während sie Spuren zum vermissten Diplomaten des Königreichs verfolgen. Behüter Backus hat ungewöhnliche Bewegungen der Defias verfolgt, die in Addles Siedlung zusammenlaufen, dem verfallenen Gehöft südlich der Straße aus Westfall. Eine Geldkassette dort enthält die Liste der Defias. Ihre Aufzeichnungen zeichnen die Bewegungen der Bruderschaft nach und zeigen, dass ihre Unternehmungen über Straßenraub und örtliches Banditentum hinausgehen."},{t="Das Netz der Verschwörung",b="Die Unterlagen sind kompliziert und politisch brisant, weshalb Behüter Backus sich weigert, sie zu behalten. Er fürchtet schwere Strafen seiner Vorgesetzten, wenn sie ihn beim Umgang mit der Liste ertappen. Zurück in Trias' Käseladen in Sturmwind enthüllen die Unterlagen einen ausgeklügelten Entführungsplan, der durch umfangreiche Mittel der Defias gestützt wird. Sie nennen auch Akteure der Unterwelt, darunter einen mit dem Decknamen 'Fist.'"}},faq={{q="Was ist die Liste der Defias?",a="Die Liste der Defias ist ein Bündel offizieller Befehle und Dokumente der Bruderschaft der Defias. Sie beschreibt ausführlich ihre Pläne und verdeckten Einsätze im Dämmerwald und in Westfall.",al={"was ist die liste","unterlagen der defias","vermisster diplomat liste"}},{q="Wo findet man die Liste der Defias?",a="Die Liste liegt verschlossen in einer Geldkassette der Defias im verfallenen Bauernhaus in Addles Siedlung, südlich der Straße von Westfall in den westlichen Dämmerwald.",al={"fundort der liste","wo findet man die liste der defias","addles siedlung liste"}},{q="Warum wurde die Liste im Dämmerwald aufbewahrt?",a="Agenten der Defias nutzten Addles Siedlung als abgelegenen Sammelpunkt zwischen Westfall und dem Dämmerwald. Dort koordinierten sie einen Einsatz von hoher Priorität, abseits der Hauptpatrouillen Sturmwinds.",al={"warum ist sie im dämmerwald","defias in addles siedlung"}},{q="Wer untersucht die Liste?",a="Behüter Backus untersucht die Liste kurz und schickt sie dann an Elling Trias in Sturmwind. Trias' privates Spionagenetz ist darauf spezialisiert, geheime Mitteilungen der Unterwelt zu entschlüsseln.",al={"wer bekommt die liste","wer liest die liste"}}},fx={b7a864a3={q="Woher stammt die Liste der Defias und wer hat sie erstellt?",a="Die Liste ist ein offizielles Schriftstück, das von der The Defias Brotherhood selbst verfasst wurde. Sie wurde entworfen, um ihre verdeckten Machenschaften zu skizzieren und Agenten in verschiedenen Regionen zu koordinieren. Agenten haben die Dokumente sicher in einer Geldkassette in Addles Siedlung versteckt, einem ruhigen Gehöft direkt hinter der Grenze zum Dämmerwald, wo sich Mitglieder der Bruderschaft trafen, bevor Ihr sie entdeckt habt.",al={"wer schrieb die liste der defias","ursprung der liste der defias","woher stammt die liste"}},["4693de43"]={q="Warum will jemand die Liste der Defias haben?",a="Ermittler, die den Fall um den verschwundenen Diplomaten untersuchen, benötigen handfeste Beweise für die Verschwörung. Behüter Backus erkennt, dass die Liste viel zu komplex ist, um ein einfaches Ablenkungsmanöver zu sein, und Elling Trias in Sturmwind nutzt ihren Inhalt, um die Geheimhaltung der Pläne der Bruderschaft zu durchbrechen, einschließlich der Aufdeckung von Hinweisen auf Schlüsselfiguren wie 'Faust'.",al={"warum ist die liste wichtig","warum die liste der defias haben wollen","wer will die liste der defias"}}},fp="13,170,21.409.0,21.377.1,26.174.0,33.150.0,36.181.0,24.189.0"}
P.entries["item:defias-tower-key"] = {n="Turmschlüssel der Defias",s="In Westfall steht der Turmschlüssel der Defias für einen unbemerkten Weg vorbei an den Wachen von Klaven's Tower. Sturmwinds Agenten brauchen ihn als Beweis dafür, dass ein Eindringling ungesehen vorbeigeschlichen ist.",h="In Westfall steht der Turmschlüssel der Defias für einen unbemerkten Weg vorbei an den Wachen von Klaven's...",kw={"agentin kearnen","turmschlüssel der defias","dämmerwaldtruhe","klaven jagdruf","klaven's tower","deformierte defiasdrohne","mathias shaw","si:7"},ang={["class:Rogue"]="Als Schurke im Dienst des SI:7 nutzt Ihr Verstohlenheit und Taschendiebstahl, um den Turmschlüssel der Defias zu erlangen. Denkt an tödliche Gifte.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr Sturmwind, die seltsamen Lieferungen der Bruderschaft der Defias aus dem Dämmerwald zu untersuchen. Beschafft geheime Informationen aus Klaven's Tower."},sec={{t="Eine Beute der entstellten Wache",b="Klaven's Tower ist eine Festung der Bruderschaft der Defias an der Küste von Westfall. Jüngste Lieferungen aus dem Dämmerwald brachten deformierte Defiasdrohnen als Wachen dorthin. Die Drohnen sind untot und mit Stacheln übersät.\n\nBeobachter des SI:7 weisen Außendienstagenten an, die Taschen der Wachposten zu leeren, statt sie zu bekämpfen. So wird kein Alarm ausgelöst, wenn die Verteidigung des Turms überwunden wird."},{t="Die Verbindung zum Dämmerwald",b="Der Schlüssel führt zu einer Truhe in Klaven's Tower, die mit Lieferungen aus dem Dämmerwald in Verbindung steht. Darin liegt Klaven Jagdrufs Tagebuch. Sobald Meister Mathias Shaw in Sturmwind es erhält, enthüllt das Tagebuch eine Verschwörung, die über gewöhnlichen Straßenraub hinausgeht.\n\nDie Defias haben sich mit der Venture Company zusammengeschlossen, um mit besonderen Trollgiften zu handeln, die Zanzil the Outcast entdeckt hat. Diese Gemische können Tote erwecken und erklären so die grotesken, hustenden Abscheulichkeiten rund um den Turm."}},faq={{q="Wie erhaltet Ihr den Turmschlüssel der Defias?",a="Bestehlt eine der deformierten Defiasdrohnen, die Klaven's Tower in Westfall bewachen. Der Schlüssel kann keinem besiegten Gegner abgenommen werden.",al={"wo gibt es den schlüssel","wie bekommt man den turmschlüssel der defias","wer lässt den turmschlüssel der defias fallen"}},{q="Was öffnet der Turmschlüssel der Defias?",a="Der Schlüssel öffnet weder die Turmtür noch die Dämmerwaldtruhe im Inneren. Meister Mathias Shaw verlangt ihn als Beweis dafür, dass ein Agent die äußere Bewachung ungesehen überwunden hat.",al={"öffnet er die dämmerwaldtruhe","welche tür öffnet dieser schlüssel","was öffnet der defiasschlüssel"}},{q="Was sind die deformierten Defiasdrohnen, die den Turm bewachen?",a="Die deformierten Defiasdrohnen sind groteske, stachelbesetzte untote Wachen rund um Klaven's Tower. Agentin Kearnen weiß nicht, wodurch sie entstanden sind, und bittet Agenten, die von ihnen bewachte Lieferung zu untersuchen.",al={"wer hat den schlüssel","was sind die turmwachen","was ist der stachelbesetzte zombie"}},{q="Wer schickt Agenten aus, um diesen Schlüssel zu beschaffen?",a="Agentin Kearnen, eine Späherin des SI:7, beobachtet den Außenbereich von Klaven's Tower und weist Schurken im Außendienst an, den Schlüssel zu beschaffen und den Inhalt der Dämmerwaldtruhe für Meister Mathias Shaw in Sturmwind zu bergen.",al={"wer vergibt die quest","wer will den schlüssel"}}},fx={a3164c95={q="Was ist der Turmschlüssel der Defias?",a="Es ist ein eiserner Schlüssel, den die grotesken Wachen tragen, die Klaven's Tower in Westfall umgeben. Die Agentin Kearnen vom SI:7 entdeckte ihn im Besitz des mit Stacheln versehenen untoten Monsters, das den Ort bewacht, und identifizierte ihn als entscheidenden Beweis für die verdeckten Operationen der The Defias Brotherhood an dieser Befestigung.",al={"turmschlüssel der defias","was ist der turmschlüssel der defias","defias-schlüssel"}},["2bb6b303"]={q="Warum will das SI:7 den Turmschlüssel der Defias?",a="Meister Mathias Shaw und Agentin Kearnen benötigen Schurken, die den Schlüssel sicherstellen, während sie den Turm infiltrieren, um mysteriöse Lieferungen aus dem Dämmerwald zu untersuchen. Ihn zurückzubringen beweist, dass Ihr erfolgreich in den Perimeter eingedrungen seid und die finsteren Geheimnisse geborgen habt, die in der Festung von Klaven Mortwake eingeschlossen sind.",al={"warum den turmschlüssel der defias holen","wer will den turmschlüssel der defias","warum den defias-schlüssel bergen"}}},fp="16,164,30.348.0,34.455.1,39.129.0,36.156.0,56.189.1,42.182.0"}
P.entries["item:deliah-s-ring"] = {n="Deliahs Ring",s="Im Silberwald liegt Deliahs Ring zwischen den Leichenhaufen der Rot Hide-Gnolle. Seine Inschrift verweist auf ein Seuchenopfer, das aus den Massengräbern von Tirisfal geraubt wurde.",h="Im Silberwald liegt Deliahs Ring zwischen den Leichenhaufen der Rot Hide-Gnolle.",kw={"brill","deliah","deliahs ring","gravierter ring","insel fenris","hadrec","magistrat sevren","rot hide-gnolle"},ang={["race:Undead"]="Als Untoter wisst Ihr, dass sterbliche Bindungen mit dem Fleisch verblassen können. Einige wenige halten noch immer an der Erinnerung an jene fest, die sie zu Lebzeiten liebten."},sec={{t="Ein Andenken im Morast",b="Zwischen den Leichenhaufen der Rot Hide-Gnolle im Silberwald steckt ein Ring an der Hand einer recht frischen Leiche. Der Ring trägt eine schlichte Inschrift: „Für Deliah.“ Die Gnolle plündern nicht nur Schlachtfelder. Sie plündern die Massengräber von Tirisfal und bringen Leichen von Menschen und Verlassenen für ihre eigenen Zwecke nach Süden zur Insel Fenris."},{t="Verbindungen nach Brill",b="Hochexekutor Hadrec schickt den Ring nach Brill, wo Magistrat Sevren Aufzeichnungen über die kürzlich Verstorbenen führt. Sevren bestätigt, dass Deliah in Brill lebte und an der Seuche starb. Sie wurde bestattet, bevor Leichenräuber ihre sterblichen Überreste ausgruben. Der Ring führt zur Trauer derer, die sie zurückließ, und zur Frage, ob sterbliche Hingabe den Untod überdauern kann."}},faq={{q="Wo wird Deliahs Ring gefunden?",a="Deliahs Ring steckt an der Hand eines Seuchenopfers zwischen den Leichenhaufen der Rot Hide-Gnolle im nördlichen Silberwald. Die Toten dort wurden geplündert und unverhüllt zurückgelassen.",al={"wo deliahs ring finden","deliahs ring fundort","wie bekommt man deliahs ring"}},{q="Wer war Deliah?",a="Deliah lebte in Brill und starb an der Seuche. Sie wurde in den örtlichen Massengräbern bestattet, bevor Rot Hide-Gnolle ihren Leichnam stahlen und in den Silberwald zerrten.",al={"wer ist deliah","deliahs geschichte","deliah aus brill"}},{q="Warum hatten die Rot Hide-Gnolle ihren Leichnam?",a="Die Rot Hide-Gnolle sind mit der Geißel verbündet und plündern die Gemeinschaftsgräber in Tirisfal. Sie häufen Leichen an und bringen sie zu ihrer Festung auf der Insel Fenris.",al={"warum stehlen gnolle leichen","rot hide leichenraub","was machen gnolle mit leichen"}},{q="Welche Inschrift trägt der Ring?",a="Der Ring trägt auf seiner Innenseite die Worte „Für Deliah“. Ein Geliebter oder Ehemann schenkte ihn ihr vor ihrem Tod.",al={"ringgravur","was steht auf dem ring","ring für deliah"}}},fx={c1c1eafc={q="Was ist Deliahs Ring?",a="Deliahs Ring ist ein graviertes persönliches Schmuckstück, das an der Hand einer verstorbenen Frau bei den Rot Hide-Gnollen im Silberwald gefunden wurde. Mit der einfachen Inschrift \"Für Deliah\" ist er ein seltenes, bleibendes Zeichen von Zuneigung und Leben aus Lordaeron, bevor die Seuche Einzug hielt.",al={"was ist deliahs ring","deliahs ring hintergrundgeschichte","über deliahs ring"}},a38bd9ea={q="Warum wird Deliahs Ring gesucht?",a="Hochexekutor Hadrec schätzt den Ring als wichtigen Beweis dafür, dass die Rot Hide-Gnolle Massengräber der Seuche in Tirisfal plündern, um an frische Leichen zu gelangen. Über diesen militärischen Hinweis hinaus dient der Ring dazu, die tote Frau anhand der Aufzeichnungen von Brill zu identifizieren, was die Möglichkeit bietet, herauszufinden, wer sie einst liebte und ob dieser Trauernde noch existiert.",al={"warum deliahs ring behalten","wer will deliahs ring","warum deliahs ring abgeben"}}},fp="13,167,22.333.0,13.355.1,29.167.0,15.162.0,42.178.0,36.109.0"}
P.entries["item:delivery-to-mathias"] = {n="Lieferung für Mathias",s="Keryn Sylvius schickt ein versiegeltes Paket aus Goldhain an Meister Mathias Shaw in Sturmwind. Die Lieferung gewährt einem vielversprechenden Schurken einen ersten Einblick in die inneren Abläufe des SI:7.",h="Keryn Sylvius schickt ein versiegeltes Paket aus Goldhain an Meister Mathias Shaw in Sturmwind.",kw={"lieferung für mathias","goldhain","keryn sylvius","mathias shaw","die altstadt","paket","si:7","sturmwind"},ang={["class:Rogue"]="Als Schurke tragt Ihr ein Paket, das den Übergang von belanglosen Prügeleien in Hintergassen zum königlichen Geheimdienst unter Mathias Shaw markiert.",["faction:Alliance"]="Als Agent der Allianz befördert Ihr geheime Depeschen zwischen regionalen Spähern und der Hauptstadt. Eure Arbeit hilft Sturmwinds verschwiegenem Spionageapparat, der Unterwanderung von innen entgegenzuwirken."},sec={{t="Die Prüfung eines Kuriers",b="Ein Paket muss vom Gasthaus \"Zur Höhle des Löwen\" zu den Kasernen von Sturmwind gelangen. Für einen jungen Schurken ist die Reise eine Prüfung für den Geheimdienst von Sturmwind. Keryn Sylvius vertraut das Paket unerfahrenen Beutelschneidern an und ermöglicht ihnen damit ihre erste Begegnung mit Meister Mathias Shaw. Sie müssen die Hauptstadt leise durchqueren, unauffällig bleiben und diskreten Befehlen ohne Nachfragen folgen."},{t="Zugang zum SI:7",b="Die Übergabe führt einen Agenten zum Hauptquartier des SI:7 in der Altstadt. Mathias Shaw nutzt diese Lieferungen, um Blender von wahren Talenten zu unterscheiden. Wer das Paket ohne Zögern überreicht, erhält Feldeinsätze. Den Anfang machen verdeckte Aufklärung und Infiltration gegen die Schmuggelnetzwerke der Defias im Wald von Elwynn."}},faq={{q="Was steckt in der Lieferung für Mathias?",a="Das Paket bleibt für seinen Kurier versiegelt. Es könnte Geheimdienstberichte, Beurteilungen von Rekruten oder vertrauliches Material über örtliche Bedrohungen wie die Bruderschaft der Defias in Elwynn enthalten.",al={"was ist im paket","inhalt der lieferung","paketinhalt"}},{q="Wer schickt diese Lieferung?",a="Keryn Sylvius übergibt die Lieferung. Sie ist eine Schurkenagentin und Ausbilderin im Obergeschoss des Gasthauses \"Zur Höhle des Löwen\" in Goldhain.",al={"wer hat mir dieses paket gegeben","paketabsender","keryn sylvius paket"}},{q="Wo hat Mathias Shaw sein Hauptquartier?",a="Mathias Shaw hat sein Hauptquartier im zweiten Stock des SI:7-Gebäudes. Es liegt in der südöstlichen Ecke der Altstadt auf dem Gelände der Kasernen von Sturmwind.",al={"wo ist mathias shaw","wo paket abliefern","shaw standort"}},{q="Was geschieht nach der Übergabe des Pakets an Shaw?",a="Nachdem Shaw sich von Euren Fähigkeiten überzeugt hat, führt er Euch in die Spionage im Felde ein und schickt Euch zur Infiltration von Jerods Anlegestelle. Dort stehlt Ihr einem Hafenmeister der Defias einen Frachtplan.",al={"nächste quest nach der lieferung","was macht shaw","nach lieferung für mathias"}}},fx={["1dd6c783"]={q="Was ist die Lieferung für Mathias?",a="Es ist ein versiegeltes Paket, das Euch von Keryn Sylvius, dem Schurkenlehrer in Goldhain, anvertraut wurde. Es wird unter dem Vorwand eines Botengangs übergeben und dient hauptsächlich als Eure Vorstellung und Kompetenzprüfung vor Meister Mathias Shaw im Hauptquartier des SI:7 in Sturmwind.",al={"was ist die lieferung für mathias","paket für die lieferung für mathias","paket von keryn sylvius"}},["2bd7511f"]={q="Warum will Mathias Shaw diese Lieferung?",a="Meister Mathias Shaw leitet das SI:7, die Gilden-Geheimdienstorganisation von Sturmwind, und Keryn Sylvius wurde damit beauftragt, Arbeit weiterzuleiten und vielversprechende Rekruten zu ihm zu schicken. Das Paket sicher in Die Altstadt zu bringen beweist, dass Ihr verdeckte Anweisungen befolgen und sensible Aufträge für den Spymaster der Krone handhaben könnt.",al={"warum will shaw die lieferung","warum paket an mathias liefern","warum will mathias das"}}},fp="19,164,16.356.0,15.314.0,39.184.0,24.122.0,46.164.0,49.182.1"}
P.entries["item:demon-pick"] = {n="Demon Pick",s="Demon Pick öffnet einen roten Kristall in der Festung Donneraxt. Taiga Klugmähne braucht ihn, um an den Dämonenkasten der Burning Blade zu gelangen.",h="Demon Pick öffnet einen roten Kristall in der Festung Donneraxt.",kw={"burning blade","dämonenkasten","demon pick","hand of iruxos","mannorocs koven","roter kristall","schattenflucht","taiga klugmähne","festung donneraxt"},sec={{t="Der rote Kristall",b="Jenseits der Festungsmauern versperrt der rote Kristall den Weg zum Dämonenkasten. Demon Pick öffnet ihn und gewährt Zugang zu dem, was die Burning Blade in der Festung Donneraxt aufbewahrt. Taiga Klugmähne wartet in Schattenflucht auf Demon Pick und den Kasten, damit die Bedrohung beim Mannorocs Koven bekämpft werden kann."}},faq={{q="Was öffnet Demon Pick?",a="Demon Pick öffnet einen roten Kristall in der Festung Donneraxt und ermöglicht so den Zugang zum Dämonenkasten.",al={"demon pick verwenden","demon pick für roten kristall"}},{q="Wo setze ich Demon Pick ein?",a="Setzt Demon Pick am roten Kristall in der Festung Donneraxt ein.",al={"wo demon pick einsetzen","fundort von demon pick"}},{q="Wer braucht Demon Pick?",a="Taiga Klugmähne in Schattenflucht bittet um Demon Pick und den Dämonenkasten.",al={"wer will den pick","taiga pick"}},{q="Warum will Taiga Demon Pick?",a="Taiga braucht Demon Pick, um an den Dämonenkasten zu gelangen, den die Burning Blade in der Festung Donneraxt aufbewahrt.",al={"warum demon pick","grund für demon pick"}},{q="Was ist im Dämonenkasten?",a="Die mächtige Hand of Iruxos befindet sich im Dämonenkasten.",al={"inhalt des dämonenkastens","was ist im kasten"}},{q="Warum ist der Dämonenkasten gefährlich?",a="Die Burning Blade nutzt die Hand of Iruxos im Kasten, um beim Mannorocs Koven dämonische Portale zu öffnen.",al={"kasten der burning blade","dämonische portale"}}},fp="10,137,15.290.0,30.91.0,30.66.0,25.86.0,35.105.0,25.54.1,31.99.1"}
P.entries["item:deviate-hide"] = {n="Deviatbalg",s="In den Höhlen des Wehklagens trägt Deviatbalg das Mal von Naralex' Traum. Druiden wollen seine Verderbnis in nützliche Lederwaren verwandeln.",h="In den Höhlen des Wehklagens trägt Deviatbalg das Mal von Naralex' Traum.",kw={"brachland","deviatbalg","leder","nalpak","naralex","alptraum","felle","die höhlen des wehklagens"},ang={["class:Druid"]="Als Druide könnt Ihr an diesen Häuten erkennen, wie die Macht des Smaragdgrünen Alptraums die Natur verdirbt. Nalpak will die verderbten Materialien läutern und für das Überleben nutzbar machen."},sec={{t="Verderbte Felle des Alptraums",b="Naralex' Schlummer unter dem Brachland veränderte die Bestien der Höhlen des Wehklagens. Der Traum des Nachtelfendruiden wurde zu einem Smaragdgrünen Alptraum, und Deviaträuber mit zähen, mutierten Häuten entstanden. Ihre Felle tragen Böses in sich, bleiben aber geschmeidig und widerstandsfähig für die Lederverarbeitung.\n\nNalpak sammelt die Häute von seinem Hochsitz weit über dem Höhleneingang aus, in einer schädelförmigen Felsformation. Er untersucht ihre Eigenschaften und verarbeitet sie zu robusten Gebrauchstaschen."}},faq={{q="Was unterscheidet einen Deviatbalg von gewöhnlichem Leder?",a="Der Smaragdgrüne Alptraum, der aus Naralex' Schlummer dringt, hat die Bestien verformt, die Deviatbälge tragen. Ihr Fleisch ist seltsam widerstandsfähig und elastisch, anders als gewöhnliche Tierfelle.",al={"deviatbalg hintergrund","warum sind deviatbälge seltsam","beschaffenheit von deviatfellen"}},{q="Wer sammelt diese Häute?",a="Nalpak sammelt die Häute. Als Schüler von Naralex lagert er in der Augenhöhle über dem Eingang zu den Höhlen des Wehklagens. Er glaubt, dass sich die bösen Materialien der Deviatbestien läutern und zu nützlichen Lederwaren verarbeiten lassen.",al={"wer will deviatbälge","nalpak häute","wer braucht deviatbalg"}},{q="Wo findet man Deviatbälge?",a="Deviatbälge stammen von Bestien, die in den Höhlen des Wehklagens unter dem Brachland umherstreifen, darunter Raptoren, Vipern, Krokolisken und dreadfangs.",al={"wo werden deviatbälge fallen gelassen","wie bekommt man deviatbälge"}}},fx={["8b5833f5"]={q="Woher stammt der Deviatbalg und wer hat ihn hergestellt?",a="Deviatbälge werden von den seltsamen, verformten Bestien genommen, die tief in Die Höhlen des Wehklagens umherstreifen. Diese Kreaturen wurden nicht von sterblichen Händen erschaffen; sie entstanden vielmehr unter dem Brachland, mutiert durch den abscheulichen Albtraum, der den Druiden Naralex verzehrte, als er in seinen tiefen Schlaf fiel. Die unnatürliche Verderbnis veränderte die einheimische Tierwelt und verlieh ihren Fellen seltsame und jenseitige Eigenschaften.",al={"woher kommen deviate hides","ursprung von deviate hides","wer machte deviate hides"}}},fp="12,126,30.446.0,56.173.0,30.208.0,30.142.0"}
P.entries["item:devlin-s-remains"] = {n="Devlins sterbliche Überreste",s="Nahe Agamands Mühlen zeugen Devlins sterbliche Überreste von einem bitteren Erbe. Der jüngere Sohn der wohlhabenden Familie, der die Mühlen gehörten, streifte als geistloser Knecht der Geißel über die Straße bei seinem zerstörten Heim. Ein Reisender streckte ihn nieder und brachte seine Knochen zu einem Überlebenden in Brill, der nach Rache dürstete.",h="Nahe Agamands Mühlen zeugen Devlins sterbliche Überreste von einem bitteren Erbe.",kw={"agamands mühlen","brill","coleman heller","devlin agamand","devlins sterbliche überreste","the haunted mills","tirisfal"},ang={["race:Undead"]="Für die Verlassenen verkörpern die Agamands Lordaerons alten, privilegierten Adel. Das Versagen der Familie ließ einfache Leute sterben und als Monster auferstehen, weshalb die Schändung von Devlins sterblichen Überresten ein Akt der Vergeltung einer Gesellschaftsschicht ist."},sec={{t="Ein bitteres Erbe",b="Devlin Agamand lebte im Schatten seines älteren Bruders Thurman. Thurman war sanftmütig und groß, Devlin dagegen gebrechlich und scharfzüngig. Als die Seuche des Untodes das nördliche Tirisfal heimsuchte, versäumte es die Familie Agamand, ihre Ländereien und Arbeiter zu schützen. Devlin gehörte zu den ersten Opfern. Die Geißel erweckte ihn als unersättlichen Ghul, und sein wahnsinniges Geplapper suchte den Straßenrand auf dem Weg zu Agamands Mühlen heim."},{t="Rache auf dem Kaminsims",b="Coleman Heller lebt in Brill und hegt einen tiefen Groll gegen die Blutlinie der Agamands. Er wirft der Familie vor, seine eigene im Stich gelassen zu haben, als die Seuche kam. Heller schickte Reisende aus, um Devlin zur Ruhe zu betten und seine sterblichen Überreste zu sammeln. Er wollte Devlins Knochen auf seinem Kaminsims haben, um auszukosten, wie seine einstigen Herren unter seiner Ferse zu Staub und zerschmetterten Bruchstücken geworden waren."}},faq={{q="Wer war Devlin Agamand zu Lebzeiten?",a="Devlin war der jüngere Sohn der wohlhabenden Familie Agamand, der Agamands Mühlen im nördlichen Tirisfal gehörten. Sein sanftmütiger, breitschultriger Bruder Thurman stand in scharfem Gegensatz zu Devlin, der gebrechlich, kränklich, mürrisch und scharfzüngig war.",al={"wer ist devlin","devlin agamand hintergrundgeschichte","über devlin"}},{q="Wo wurden Devlins sterbliche Überreste geborgen?",a="Devlins sterbliche Überreste stammten von seinem durch die Geißel beherrschten Leichnam, südlich von Agamands Mühlen am Rand der Straße durch Tirisfal.",al={"wo ist devlin","wo devlin finden","devlin agamand aufenthaltsort"}},{q="Warum will Coleman Heller diese Knochen?",a="Coleman Heller verachtet die Familie Agamand und glaubt, dass sie ihn und seine Angehörigen während der Seuche im Stich ließ. Er will Devlins Knochen als Trophäe der Rache und Genugtuung auf seinem Kaminsims in Brill haben.",al={"warum heller die überreste will","coleman hellers beweggrund","warum agamand-knochen sammeln"}},{q="Gehört Devlin zu den Verlassenen?",a="Nein. Die Seuche raubte Devlin den Verstand, und die Geißel machte ihn zu einem geistlosen Ghul. Er wanderte nahe den Mühlen umher und plapperte im Wahn, bis er vernichtet wurde.",al={"ist devlin ein verlassener","gehörte devlin zur geißel"}}},fx={["0d9d3e5c"]={q="Was sind Devlins sterbliche Überreste?",a="Devlins sterbliche Überreste sind die Skelettknochen von Devlin Agamand, dem jüngeren Sohn der angesehenen Dynastie Agamand. Nachdem er der Geißelseuche zum Opfer gefallen war, wurde Devlin zu einem gedankenlosen Elend der Geißel, das an der Straße zu den zerstörten Mühlen seiner Familie verweilte, bis er zur Strecke gebracht und eingesammelt wurde.",al={"was sind devlins sterbliche überreste","gegenstand devlins sterbliche überreste","wer ist devlins sterbliche überreste"}}},fp="16,280,15.406.0,23.358.0,31.253.0,42.121.0,43.209.0,31.146.0"}
P.entries["item:dirt-caked-pendant"] = {n="Schmutzverkrusteter Anhänger",s="Im Brachland gibt Dogran den Schmutzverkrusteten Anhänger her, den er bei sich trug. Er gelangt zu Gan'rul Blutauge in Orgrimmar, wo das Andenken dazu dient, einen Sukkubus anzulocken.",h="Im Brachland gibt Dogran den Schmutzverkrusteten Anhänger her, den er bei sich trug.",kw={"devourer of souls","schmutzverkrusteter anhänger","dogran","gan'rul blutauge","love's gift","sukkubus","zankaja"},ang={["class:Warlock"]="Als angehender Hexenmeister seht Ihr, wie Trauer und Hingabe der Sterblichen helfen können, Dämonen aus dem Twisting Nether zu befehligen.",["race:Orc"]="Als Orc seht Ihr Dograns bittersüße Entscheidung. Er weigert sich, seinem Klan und seiner Gefährtin als Krüppel zur Last zu fallen, und gibt sein Andenken für einen letzten Kampf als Krieger her."},sec={{t="Ein tragisches Andenken",b="Dogran gibt den Schmutzverkrusteten Anhänger her, während er im Brachland gefangen gehalten wird. Vergiftet und ohne Hoffnung auf Genesung verkrüppelt, will er seiner Gefährtin Zankaja bei seiner Rückkehr nicht zur Last fallen. Stattdessen entscheidet er sich, im Kampf gegen seine Peiniger zu sterben. Der Anhänger trägt seine unausgesprochene Liebe zu ihr in sich.\n\nEin Hexenmeister bringt das Andenken nach Orgrimmar. Dort machen sich die Hexenmeister der Kluft der Schatten den darin liegenden Herzschmerz und die Hingabe zunutze."},{t="Köder für einen Dämon",b="In der Kluft der Schatten erkennt Gan'rul Blutauge, wie der Anhänger einen Sukkubus anlocken kann. Diese Dämonen folgen der Sehnsucht, der Romantik und der Tragik der Sterblichen. Der Hexenmeister reinigt und poliert Dograns Anhänger, bis er glänzt, und verwandelt so ein Zeichen hingebungsvoller Liebe in einen Köder.\n\nDann ruft der Hexenmeister einen Sukkubus herbei, der sich einem rituellen Kampf stellen und unterworfen werden soll."}},faq={{q="Woher stammt der Schmutzverkrustete Anhänger?",a="Dogran, ein gefangener Orc-Krieger im Brachland, gibt Euch den Anhänger, nachdem Ihr ihm Ken'ziglas Trunk gegeben und seine Sinne wiederbelebt habt.",al={"herkunft des anhängers","wo gibt es den anhänger","wer gibt den anhänger"}},{q="Welche Verbindung hat der Anhänger zu Zankaja?",a="Zankaja ist Dograns Gefährtin in Orgrimmar. Er gibt den Anhänger her und verheimlicht, dass er überlebt hat, damit sie ihn nicht als kriegsversehrten Krieger pflegen muss.",al={"wer ist zankaja","dogran und zankaja","bedeutung des anhängers"}},{q="Warum braucht Gan'rul Blutauge genau diesen Anhänger?",a="Sukkubi reagieren auf starke Gefühle der Sterblichen, besonders auf Romantik, Herzschmerz und Hingabe. Nach der Reinigung kann Dograns Anhänger den Ruf bündeln, der einen Sukkubus in den Beschwörungskreis lockt.",al={"warum wird der anhänger gebraucht","anhänger als sukkubusköder","ganrul blutauge anhänger"}},{q="Was geschieht, nachdem der Anhänger nach Orgrimmar gebracht wurde?",a="Nachdem Ihr den Anhänger nach Orgrimmar gebracht habt, reinigt Gan'rul Blutauge ihn und nutzt seine Anziehungskraft, um Binding einzuleiten. Ein Sukkubus wird in den Kreis unter der Kluft der Schatten gelockt, damit Ihr ihn besiegt und unterwerft.",al={"was folgt nach dem anhänger","was mit dem anhänger tun"}}},fx={cbd86f91={q="Was ist das Dirt-Caked Pendant?",a="Das Dirt-Caked Pendant ist ein angelaufenes persönliches Erinnerungsstück, das der gefangene Orc Dogran bei sich trägt. Als Zeichen für seine Gefährtin Zankaja gegeben, trägt es die starke emotionale Resonanz von Liebe und Sehnsucht in sich – genau die Eigenschaften, die ein Hexenmeister benötigt, wenn er sich darauf vorbereitet, einen Sukkubus anzulocken und zu unterwerfen.",al={"was ist das dirt-caked pendant","dirt-caked pendant hintergrundgeschichte","was für ein gegenstand ist dirt-caked pendant"}}},fp="18,155,14.386.1,16.333.1,44.129.0,44.150.1,53.185.0,57.209.1"}
P.entries["item:dirty-knucklebones"] = {n="Schmutzige Knöchelknochen",s="Schmutzige Knöchelknochen werden von Crushridge-Ogern im Alteracgebirge getragen. Marshal Redpath in Süderstade zahlt ein Kopfgeld auf sie, damit die Oger die Ausläufer nicht bedrohen.",h="Schmutzige Knöchelknochen werden von Crushridge-Ogern im Alteracgebirge getragen.",kw={"alteracgebirge","kopfgeld","crushridge","schmutzige knöchelknochen","marshal redpath","oger","süderstade"},sec={{t="Eine Belohnung des Marshals",b="Marshal Redpath bittet um Schmutzige Knöchelknochen von den Crushridge-Ogern nahe der zerstörten Stadt Alterac. Er fürchtet, die Oger könnten in die Ausläufer vordringen, wenn sie sich in den Ruinen sicher fühlen. Die gesammelten Knochen sollen sie zumindest eine Weile von Süderstade fernhalten."}},faq={{q="Wer trägt Schmutzige Knöchelknochen?",a="Crushridge-Oger im Alteracgebirge tragen Schmutzige Knöchelknochen.",al={"wer hat knöchelknochen","welche oger tragen sie"}},{q="Warum will Marshal Redpath sie haben?",a="Marshal Redpath zahlt ein Kopfgeld auf die Knochen, um die Crushridge-Oger davon abzuhalten, in die Ausläufer vorzudringen.",al={"warum knöchelknochen","wofür sind sie"}},{q="Wohin bringt Ihr Schmutzige Knöchelknochen?",a="Bringt Schmutzige Knöchelknochen zu Marshal Redpath nach Süderstade.",al={"wohin mit den knochen","redpath knöchelknochen"}},{q="Wo sind die Crushridge-Oger?",a="Die Crushridge-Oger haben ein Ogerlager im Alteracgebirge nahe der zerstörten Stadt Alterac.",al={"crushridge ort","oger in alterac"}}},fp="18,179,20.277.0,31.67.0,35.115.0,36.58.0,31.97.0"}
P.entries["item:disarming-colloid"] = {n="Entschärfungspaste",s="Am Steinwerkdamm kann Entschärfungspaste verhindern, dass Seaforium bei Nässe explodiert. Ashlan Schmunzelstein stellt sie im Sumpfland bereit, um das Pulver zu neutralisieren.",h="Am Steinwerkdamm kann Entschärfungspaste verhindern, dass Seaforium bei Nässe explodiert.",kw={"ashlan schmunzelstein","dunkeleisen","entschärfungspaste","sprengstoffe","hinderweir","seaforium","der steinwerkdamm","sumpfland"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, dass Seaforium gewaltige Zerstörung anrichten kann. Ein gezielt wirkendes chemisches Gegenmittel wie diese Paste kann das verhindern.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass das gegen den Steinwerkdamm gerichtete Seaforium die zwergische Ingenieurskunst und die Sicherheit des oberhalb gelegenen Loch Modan bedroht."},sec={{t="Ein chemisches Neutralisierungsmittel",b="Am Steinwerkdamm in Loch Modan erkennt Ashlan Schmunzelstein das von Dunkeleisenzwergen-Sprengmeistern zurückgelassene Pulver als Seaforium. Sein Geruch und die feinen Silberkristalle verraten es. Trocken ist das Pulver harmlos. Feuchtigkeit macht es ungeheuer zerstörerisch, eine ernste Gefahr am durchnässten Damm.\n\nSchmunzelstein stellt Entschärfungspaste bereit, um die Reaktion vor der Detonation zu stoppen. Vermischt mit Lauerergift, zerstoßenem Kristall der Mo'grosh und einer Krokiliskenträne neutralisiert die Paste die explosiven Eigenschaften von Seaforium."}},faq={{q="Wozu wird Entschärfungspaste verwendet?",a="Entschärfungspaste hilft, Seaforium zu entschärfen. Vermischt mit Lauerergift, zerstoßenem Kristall der Mo'grosh und einer Krokiliskenträne neutralisiert sie die explosive Reaktion des Pulvers bei Nässe.",al={"zweck der paste","was bewirkt entschärfungspaste","seaforium entschärfen"}},{q="Wer hat diese Paste hergestellt oder bereitgestellt?",a="Ashlan Schmunzelstein stellt die Paste bereit. Er ist ein Sprengstoffexperte, der dem Regiment zugeteilt ist, das Dun Modr im Sumpfland bewacht. Er erkennt den Plan der Dunkeleisenzwerge, den Steinwerkdamm zu zerstören.",al={"wer gibt die paste","ashlans paste"}},{q="Warum ist Seaforium im Sumpfland so gefährlich?",a="Trocken ist Seaforium harmlos, doch Feuchtigkeit lässt es heftig explodieren. Das Sumpfland ist mit Wasser durchtränkt, und das Pulver soll gegen den Steinwerkdamm eingesetzt werden. Feuchtes Seaforium droht gewaltige Verwüstungen anzurichten.",al={"warum ist seaforium gefährlich","nasses seaforium"}},{q="Wem muss diese Paste gebracht werden?",a="Ashlan Schmunzelstein sagt, die Paste und die Nachricht vom Seaforium-Komplott müssen direkt zu Chief Engineer Hinderweir am Steinwerkdamm gebracht werden.",al={"zu wem muss die paste","paste abgeben"}}},fx={["6b4ad5ab"]={q="Was ist die Entschärfungspaste?",a="Die Entschärfungspaste ist eine spezielle neutralisierende Mischung, die von Ashlan Schmunzelstein zubereitet wurde. Wenn sie mit drei anderen wirksamen Reagenzien kombiniert wird – Lauerergift, zerkleinerter Kristall der Mo'grosh und einer Krokiliskenträne –, entschärft sie sicher die flüchtige chemische Reaktion von Seaforium-Sprengpulver, bevor die explosive Verbindung durch Feuchtigkeit ausgelöst werden kann.",al={"was ist die entschärfungspaste","identität der entschärfungspaste","hintergrundgeschichte der entschärfungspaste"}},["1c3f9fc5"]={q="Warum wird die Entschärfungspaste benötigt?",a="Chefingenieur Hinderweir benötigt die Paste dringend, um eine Katastrophe am Steinwerkdamm in Loch Modan abzuwenden. Dunkeleisensabotöre haben flüchtiges Seaforium am Damm platziert, und ohne dieses chemische Mittel zur Entschärfung der Reaktion könnte der Kontakt mit Wasser den Damm sprengen.",al={"warum entschärfungspaste benötigen","warum wird die paste gesucht","wer will die entschärfungspaste"}}},fp="17,158,22.482.0,35.170.0,37.201.0,46.204.0,38.136.0"}
P.entries["item:disarming-mixture"] = {n="Entschärfungsmixtur",s="Am Steinwerkdamm bereitet Chief Engineer Hinderweir die Entschärfungsmixtur zu, um eine von Saboteuren der Dunkeleisen platzierte Seaforium-Ladung unschädlich zu machen.",h="Am Steinwerkdamm bereitet Chief Engineer Hinderweir die Entschärfungsmixtur zu, um eine von Saboteuren der...",kw={"dunkeleisen","entschärfungsmixtur","sprengstoffe","hinderweir","loch modan","pulverfass","seaforium","der steinwerkdamm"},ang={["profession:Engineering"]="Für einen Ingenieur zeigt die Entschärfungsmixtur, wie chemische Neutralisierung eine instabile Seaforium-Ladung unschädlich machen kann, ohne sie zu zünden.",["race:Dwarf"]="Als Zwerg helft Ihr, die Täler und das Tiefland rund um den Steinwerkdamm zu schützen. Der schnelle Einsatz des Neutralisierungsmittels hilft, sie zu verteidigen."},sec={{t="Ein chemisches Neutralisierungsmittel",b="Die schwere Seaforium-Ladung liegt unter dem Fundament des Damms, und keine Mountaineers sind nahe genug, um zu helfen. Hinderweir greift auf Zutaten zurück, die der Sprengstoffexperte Ashlan Schmunzelstein genannt hat. Er verrührt sie zu einem chemischen Neutralisierungsmittel und mischt es dann unter Wasser mit dem Inhalt des Pulverfasses. Die reaktiven Verbindungen werden neutralisiert, und die Ladung wird unschädlich."}},faq={{q="Wofür wird die Entschärfungsmixtur verwendet?",a="Die Mixtur neutralisiert ein großes Seaforium-Sprengstofffass, das Aufständische der Dunkeleisen unter Wasser am Fundament des Steinwerkdamms platziert haben.",al={"was bewirkt die entschärfungsmixtur","verwendung der entschärfungsmixtur","zweck der entschärfungsmixtur"}},{q="Wer stellt die Entschärfungsmixtur her?",a="Chief Engineer Hinderweir mischt die Zutaten, während er die Instandhaltung und Verteidigung des Steinwerkdamms beaufsichtigt.",al={"wer stellt die entschärfungsmixtur her","wer gibt die entschärfungsmixtur","hinderweirs mixtur"}},{q="Warum war die Mixtur nötig, statt die Bombe einfach zu entschärfen?",a="Trockenes Seaforium-Pulver ist harmlos, doch nasses Pulver kann mit gewaltiger Kraft explodieren. Die Mixtur neutralisiert das reaktive Pulver, während das Fass unter dem Damm im Wasser bleibt.",al={"warum nicht normal entschärfen","warum chemikalien an der bombe verwenden","warum entschärfungsmixtur"}}},fx={["8d78f743"]={q="Was ist die Entschärfungsmixtur?",a="Die Entschärfungsmixtur ist ein spezielles chemisches Gebräu, das speziell zur Neutralisierung flüchtiger explosiver Verbindungen zubereitet wurde. Wenn sie unter Seaforium oder hochwertiges Sprengpulver gemischt wird, reagiert sie mit den explosiven Materialien und deaktiviert sie chemisch, wodurch die Ladungen mit einem harmlosen Zischen anstatt mit einer katastrophalen Detonation inaktiv werden.",al={"was ist die entschärfungsmixtur","gegenstand entschärfungsmixtur","über die entschärfungsmixtur"}}},fp="17,132,22.349.0,39.134.0,34.110.0,67.176.0"}
P.entries["item:discarded-knife"] = {n="Discarded Knife",s="Das Discarded Knife ist eine gut gepflegte Klinge, die nahe einem vermissten Boot in Feralas unter Wasser gefunden wurde. Ginro Hearthkindle hofft, dass sie einen Hinweis auf Raschals Schicksal geben könnte.",h="Das Discarded Knife ist eine gut gepflegte Klinge, die nahe einem vermissten Boot in Feralas unter Wasser...",kw={"bootswrack","discarded knife","mondfederfeste","feralas","ginro hearthkindle","messer","psychometrie","quintis jonespyre","raschal"},ang={["class:Druid"]="Als Druide erkennt Ihr Quintis Jonespyres Psychometrie vielleicht als ungewöhnliche Kunst, die auf die Geheimnisse der Natur zurückgreift."},sec={{t="Unter Wasser",b="Am Grund des Wassers in Feralas liegt das Discarded Knife nahe einem großen Teil eines vermissten Bootes. Sein Griff ist im Schlamm leicht zu finden, und die Klinge scheint gut gepflegt. Ihr bringt es zu Ginro Hearthkindle in der Mondfederfeste, der nach Hinweisen auf Raschals Schicksal sucht."},{t="Ein Hinweis in der Hand",b="Ginro glaubt, dass das Discarded Knife Raschal gehört haben könnte, doch der Fund nahe dem Boot reicht nicht aus, um Gewissheit zu schaffen. Er schickt Euch zu Quintis Jonespyre, dem ansässigen Druiden der Feste, damit er die Klinge durch Berührung untersucht. Quintis nennt diese Kunst Psychometrie und hofft, dass sie einen Einblick in die Geschehnisse gewährt."}},faq={{q="Woher stammt das Messer?",a="Das Discarded Knife wurde im Schlamm unter Wasser in Feralas gefunden, nahe einem großen Teil eines vermissten Bootes.",al={"messerfundort","fundort","messer unter wasser"}},{q="Wem könnte das Messer gehören?",a="Ginro Hearthkindle glaubt, dass das Discarded Knife Raschal gehört haben könnte, dessen Schicksal ungewiss bleibt.",al={"wem gehört das messer","raschals messer","messerbesitzer"}},{q="Warum möchte Ginro das Messer?",a="Ginro sucht nach Hinweisen auf Raschals Schicksal und hofft, dass das Messer helfen könnte, die Geschehnisse aufzudecken.",al={"ginros messer","warum das messer bringen","welcher hinweis"}},{q="Wer kann die Geschichte des Messers lesen?",a="Quintis Jonespyre, der ansässige Druide der Mondfederfeste, nutzt Psychometrie, um durch Berührung nach der Geschichte eines Gegenstands zu suchen.",al={"messer lesen","psychometrie","quintis' messer"}},{q="Was ist Psychometrie?",a="Psychometrie ist Quintis Jonespyres Kunst, durch Berührung Einblicke in die Geschichte eines Gegenstands zu gewinnen.",al={"was ist psychometrie","gegenstand lesen","objekt lesen"}}},fp="15,162,17.288.0,14.303.0,30.108.0,30.107.0,30.100.0,35.122.0,20.99.0"}
P.entries["item:divined-scroll"] = {n="Bestimmte Rolle",s="In der Silberwindzuflucht hilft die Bestimmte Rolle den Schildwachen, der Verderbnis des Mystralsees nachzugehen. Intakte Armschienen von Wasserelementaren steuern ihre Magie bei, um die Identität des Beschwörers zu enthüllen.",h="In der Silberwindzuflucht hilft die Bestimmte Rolle den Schildwachen, der Verderbnis des Mystralsees...",kw={"eschental","bestimmte rolle","rolle der bestimmung","elemental bracers","mystralsee","silberwindzuflucht","velene sternenschlag"},ang={["class:Mage"]="Als Magier erkennt Ihr das zugrunde liegende Prinzip: Elementare Bindungen tragen die arkane Signatur des Zauberers, der sie erschaffen hat.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Weissagungswerkzeuge den Schildwachen helfen, sterbliche Verschmutzer aufzuspüren, deren arkane Einmischung die heiligen Gewässer des Eschentals bedroht."},sec={{t="Dem Beschwörer auf der Spur",b="Die verdorbenen Gewässer des Mystralsees beunruhigen die Schildwachen, die Eschental bewachen. Schildwache Velene Sternenschlag gibt Reisenden eine unbeschriebene Rolle der Bestimmung, um herauszufinden, wer die Wasserelementare beherrscht, die den See heimsuchen. Sammelt intakte Armschienen von den getöteten Elementaren und verwendet sie als arkanes Reagenz. Die darin nachwirkenden Bindungen gehen auf das Pergament über, und die Bestimmte Rolle enthüllt die magische Signatur des abtrünnigen Zauberers."},{t="Der entlarvte Magier",b="Die Schrift der Bestimmten Rolle weist Schildwache Velene auf einen sterblichen Schuldigen hin: einen rücksichtslosen Magier, der die Waldtümpel absichtlich verdirbt. Nun können die Schildwachen Vergeltung planen und Späher aussenden, um den Beschwörer zu jagen, der ihre heilige Wildnis schändet."}},faq={{q="Wozu dient die Bestimmte Rolle?",a="Die Bestimmte Rolle enthüllt den Zauberwirker, der feindselige Wasserelementare in den Seen des Eschentals beschwört und bindet. Schildwache Velene Sternenschlag kann dann gezielt gegen den Schuldigen vorgehen.",al={"was bewirkt die bestimmte rolle","zweck der bestimmten rolle","warum die bestimmte rolle herstellen"}},{q="Wie wird die Bestimmte Rolle hergestellt?",a="Wirkt die unbeschriebene Rolle der Bestimmung von Schildwache Velene Sternenschlag auf fünf Intact Elemental Bracers, die Ihr von besiegten Wasserelementaren rund um den Mystralsee gesammelt habt.",al={"wie die bestimmte rolle herstellen","herstellung der bestimmten rolle","wie die bestimmte rolle erhalten"}},{q="Warum werden die Armschienen der Elementare benötigt, um die Rolle zu bestimmen?",a="Die Armschienen binden die Elementare an die Ebene der Sterblichen. Ihre nachwirkenden Verzauberungen verleihen der Rolle die magische Signatur, die benötigt wird, um den Zauberer zu identifizieren, der sie beschworen hat.",al={"warum intakte armschienen","zweck der elemental bracers"}},{q="Wem bringe ich die Bestimmte Rolle?",a="Bringt die fertige Bestimmte Rolle zu Schildwache Velene Sternenschlag in der Silberwindzuflucht an der Straße im südlichen Eschental.",al={"wo die bestimmte rolle abgeben","wer will die bestimmte rolle"}}},fx={["155064fc"]={q="Was ist die Bestimmte Rolle?",a="Die Bestimmte Rolle ist das Ergebnis der Verwendung einer Rolle der Bestimmung zusammen mit intakten Elemental Bracers, die von Wasserelementaren geerntet wurden, die die Gewässer im Eschental verunreinigen. Durchdrungen von arkane Spuren, die noch an diesen Bindungen haften, offenbart die Rolle mystische Informationen über den spezifischen Beschwörer, der dafür verantwortlich ist, die Elementare herbeizurufen und zu verderben.",al={"was ist die bestimmte rolle","zweck der bestimmten rolle","was macht die bestimmte rolle"}},ebb5ddd6={q="Woher stammt die Bestimmte Rolle und wer hat sie erstellt?",a="Ihr erschafft die Bestimmte Rolle selbst, indem Ihr die Rolle der Bestimmung der Schildwache Velene Sternenschlag auf mehrere intakte Elemental Bracers kanalisiert. Die Armschienen dienen als arkanes Reagenz, das es der Weissagungsmagie der Rolle ermöglicht, die magischen Signaturen des Erschaffers der Elementare zu fokussieren und aufzuzeichnen.",al={"wer machte die bestimmte rolle","ursprung der bestimmten rolle","wie wurde die bestimmte rolle erstellt"}}},fp="14,177,20.411.0,16.249.1,36.169.0,34.153.0,58.168.0,37.123.0"}
P.entries["item:divining-scroll"] = {n="Rolle der Bestimmung",s="In der Silberwindzuflucht gibt Schildwache Velene Sternenschlag Ermittlern die Rolle der Bestimmung, um herauszufinden, wer die verderbten Elementare beschworen hat.",h="In der Silberwindzuflucht gibt Schildwache Velene Sternenschlag Ermittlern die Rolle der Bestimmung, um...",kw={"eschental","bestimmte rolle","rolle der bestimmung","elemental bracers","silberwindzuflucht","velene sternenschlag","wasserelementare"},ang={["class:Mage"]="Die Rolle nutzt Weissagung, um arkaner Resonanz nachzuspüren. Sie enthüllt, dass ein anderer Magiekundiger die Elementarbeschwörung in heiligen Hainen der Kaldorei missbraucht.",["race:NightElf"]="Für die Schildwachen, die Eschental beschützen, kann die Rolle Fremde entlarven, die die unberührten Gewässer des Waldes mit unnatürblicher Verderbnis besudeln."},sec={{t="Unnatürlichen Elementaren auf der Spur",b="Verderbte Wasserelementare steigen aus Eschentals Tümpeln empor, und die Schildwachen wissen, dass diese Störung unnatürlich ist. Schildwache Velene Sternenschlag beschafft eine Rolle, um herauszufinden, wer dafür verantwortlich ist. Mit fünf intakten Elemental Bracers als Fokus bringt ihre Magie die Signatur des Beschwörers zum Vorschein. Das leere Pergament wird zu einer Bestimmten Rolle und nennt den Schuldigen."}},faq={{q="Wofür wird die Rolle der Bestimmung verwendet?",a="Die Rolle der Bestimmung ermittelt, wer die verderbten Wasserelementare in Eschental erschaffen hat. Fünf intakte Elemental Bracers bündeln ihre Magie, die die Aura des Zaubernden liest und dessen Identität festhält.",al={"was bewirkt die rolle","zweck der rolle der bestimmung","warum die rolle der bestimmung verwenden"}},{q="Wer stellt die Rolle der Bestimmung bereit?",a="Schildwache Velene Sternenschlag gibt die Rolle Ermittlern der Allianz in der Silberwindzuflucht im südlichen Eschental, während sie die verseuchten Gewässer untersucht.",al={"wer gibt die rolle der bestimmung","wo gibt es die rolle","velene sternenschlag rolle"}},{q="Warum werden intakte Elemental Bracers benötigt?",a="Die meisten Armschienen zersplittern im Kampf bis zur Unkenntlichkeit. Einige bleiben intakt und bewahren genug von der Bindungsmagie ihres Beschwörers, um den Weissagungszauber zu bündeln.",al={"warum armschienen","intakte elemental bracers","reagenz für die rolle"}},{q="Was geschieht, nachdem die Rolle verwendet wurde?",a="Wird die Rolle in Gegenwart von fünf intakten Armschienen verwendet, wird sie verbraucht und zu einer Bestimmten Rolle. Sie enthüllt, dass ein abtrünniger Magier absichtlich verderbte Elementare in die Seen des Waldes beschwört.",al={"bestimmte rolle","nach verwendung der rolle","in was verwandelt sie sich"}}},fx={af5653e2={q="Warum wird die Rolle der Bestimmung benötigt?",a="Schildwache Velene Sternenschlag benötigt die Rolle, um herauszufinden, wer die Seen und Tümpel des Eschentals mit korrupten Wasserelementaren füllt. Ohne die divinatorische Magie der Rolle können die Nachtelfen weder den verantwortlichen Magier ausfindig machen noch die fortwährende Schändung ihrer heiligen Wildnis stoppen.",al={"warum wird die rolle der bestimmung benötigt","warum wird die rolle gebraucht","zweck der rolle der bestimmung"}},["51ca655d"]={q="Was ist die Rolle der Bestimmung?",a="Die Rolle der Bestimmung ist ein verzaubertes Pergament, das verwendet wird, um magische Ursprünge aufzudecken. Wenn sie unter Verwendung von intakten Elemental Bracers als Reagenz fokussiert wird, kann ihre Magie die Bindungssignaturen der Wasserelementare zurückverfolgen, die das Eschental plagen, und den abtrünnigen Zauberwirker identifizieren, der sie in die unberührten Gewässer des Waldes beschworen hat.",al={"was ist die rolle der bestimmung","hintergrundgeschichte der rolle der bestimmung","gegenstand rolle der bestimmung"}}},fp="15,135,28.348.0,37.192.0,33.152.0,40.153.0,38.198.1"}
P.entries["item:dogran-s-pendant"] = {n="Dograns Anhänger",s="In der Kluft der Schatten lockt Dograns Anhänger eine Sukkubus zu den Hexenmeistern von Orgrimmar. Verwundet und von seiner Gefährtin Zankaja getrennt, trägt Dogran den Kummer, der an ihn gebunden ist.",h="In der Kluft der Schatten lockt Dograns Anhänger eine Sukkubus zu den Hexenmeistern von Orgrimmar.",kw={"die kluft der schatten","dogran","dograns anhänger","gan'rul blutauge","orgrimmar","sukkubus","the binding","zankaja"},ang={["class:Warlock"]="Als Hexenmeister der Horde nutzt Ihr Dograns Anhänger, um Eure Beherrschung des Nethers zu beweisen und zu lernen, eine Sukkubus zu beschwören.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr die Verbindungen des Anhängers zu persönlichen Tragödien im Brachland und in Durotar sowie zum Hexenmeisterzirkel in Orgrimmar erkennen."},sec={{t="Ein Kanal des Herzschmerzes",b="Dograns Anhänger trägt den Kummer eines Orcs, der von Zankaja getrennt ist. Gefangenschaft und lähmende Wunden haben ihre Liebe überschattet. Die Hexenmeister der Kluft der Schatten wissen, dass Sukkubi Liebe, Sehnsucht und Verletzlichkeit ausnutzen. Deshalb nutzen sie den Kummer des Anhängers, um eine Sukkubus durch den Wirbelnden Nether in Neeru Fireblades Beschwörungskreis zu locken."},{t="Unterwerfung und Erinnerung",b="Unter Gan'rul Blutauges Anleitung benutzt ein angehender Hexenmeister den Anhänger, um eine Sukkubus zu beschwören und im Kampf zu unterwerfen. Die Prüfung stellt seine Beherrschung der verführerischen Manipulationen des Dämons auf die Probe. Nach dem Ritual kehrt der Anhänger zu Gan'rul zurück, der ihn Zankaja überbringen soll."}},faq={{q="Wozu dient Dograns Anhänger?",a="Hexenmeister nutzen Dograns Anhänger, um in Neeru Fireblades Zelt in der Kluft der Schatten eine Sukkubus zu beschwören. Sobald der Dämon beschworen und besiegt ist, kehrt der Anhänger zu Gan'rul Blutauge zurück.",al={"verwendung des anhängers","was tun mit dograns anhänger","dograns anhänger quest"}},{q="Warum reagiert eine Sukkubus auf den Anhänger?",a="Eine Sukkubus nährt sich von Verlangen, Liebe und Leidenschaft und weiß, wie sie diese manipulieren kann. Dograns und Zankajas tragische Liebe haftet dem Anhänger an und lockt den Dämon durch den Nether.",al={"warum will sukkubus anhänger","warum beschwört anhänger dämon","hintergrund des anhängers"}},{q="Wer war Dogran?",a="Dogran ist ein Orc, dessen Gefangenschaft und Verletzungen Hexenmeister der Horde mithilfe von Kontakten wie Blind Cazul und Ken'zigla untersuchen. Er liebt Zankaja, weigert sich aber, sie mit der Pflege eines Invaliden zu belasten.",al={"wer ist dogran","dograns geschichte"}},{q="Was geschieht nach dem Beschwörungsritual mit dem Anhänger?",a="Nachdem der Hexenmeister die beschworene Sukkubus besiegt hat, kehrt der Anhänger zu Gan'rul Blutauge zurück, der ihn Zankaja überbringen kann.",al={"wer bekommt den anhänger","dograns anhänger zurückgeben"}}},fx={f4378ded={q="Was ist Dograns Anhänger?",a="Dograns Anhänger ist ein persönliches Andenken, das mit dem tragischen Schicksal des Orcs Dogran und seiner Geliebten, Zankaja, verbunden ist. Dieses kleine Medaillon, durchdrungen von roher Sehnsucht und Kummer, dient als mächtiger Fokus für dunkle Magie und ist in der Lage, während der Beschwörungsrituale von Hexenmeistern eine Sukkubus aus dem Leerenraum anzulocken.",al={"was ist dograns anhänger","infos zu dograns anhänger","lore von dograns anhänger"}},bd6e6859={q="Warum wird Dograns Anhänger benötigt?",a="Hexenmeister suchen nach dem Anhänger, da seine emotionale Resonanz ihn zu einem idealen Köder für eine Sukkubus macht, der den Dämon direkt in einen Beschwörungskreis zieht, wo er gebrochen und gebunden werden kann. Sobald das Ritual abgeschlossen ist, verlangt Gan'rul Blutauge die Rückgabe, damit er Dograns Gefährtin, Zankaja, die Nachricht überbringen kann.",al={"warum wollen sie dograns anhänger","wer will dograns anhänger","zweck von dograns anhänger"}}},fp="16,166,23.341.0,27.271.1,34.186.0,43.173.0,15.195.0,55.120.0"}
P.entries["item:dolanaar-delivery"] = {n="Lieferung für Dolanaar",s="In Laubschattental sind frische Kräuter für Dolanaar bestimmt. Porthannius vertraut jungen Reisenden das Bündel für Gastwirt Keldamyr an.",h="In Laubschattental sind frische Kräuter für Dolanaar bestimmt.",kw={"aldrassil","lieferung","dolanaar","kräuter","keldamyr","porthannius","laubschattental"},ang={["profession:Herbalism"]="Kräuter aus der Umgebung von Aldrassil sind stetig gefragt, da die abgelegenen Siedlungen von Teldrassil ihre Vorräte auffüllen.",["race:NightElf"]="Als junger kaldorei tragt Ihr das Paket über die schützenden Äste von Laubschattental hinaus in die weite Welt."},sec={{t="Ein Bündel aus Laubschattental",b="Frische Kräuter, die in Aldrassil gesammelt wurden, müssen Dolanaar erreichen. Porthannius ist bei den Druiden von Laubschattental beschäftigt, deshalb gibt er das Bündel jungen Reisenden, die auf der Straße nach Süden ziehen. Sie bringen es zu Gastwirt Keldamyr."},{t="Willkommen am Herdfeuer",b="Im Gasthaus von Dolanaar nimmt Keldamyr das Paket dankbar entgegen. Das Gasthaus bietet müden Reisenden Rast, Seelenfrieden und Zuflucht, bevor sie sich tiefer nach Teldrassil vorwagen."}},faq={{q="Was enthält die Lieferung für Dolanaar?",a="Das Paket enthält frische Kräuter, die in Laubschattental für Gastwirt Keldamyr und die Gäste des Gasthauses von Dolanaar gesammelt wurden.",al={"welche kräuter sind enthalten","inhalt der lieferung für dolanaar","was ist im paket"}},{q="Wer schickt diese Lieferung?",a="Porthannius bereitet das Bündel vor, während er sich um Angelegenheiten bei den Druiden in Laubschattental kümmert. Ihm fehlt die Zeit, selbst nach Süden zu reisen.",al={"wer übergibt die lieferung","wer hat die kräuter geschickt","porthannius lieferung"}},{q="Wer nimmt das Paket in Dolanaar entgegen?",a="Gastwirt Keldamyr nimmt das Paket im gemeinschaftlichen Gasthaus von Dolanaar entgegen.",al={"an wen gehen die kräuter","empfänger der lieferung für dolanaar","keldamyr kräuter"}},{q="Warum konnte Porthannius das Paket nicht selbst ausliefern?",a="Porthannius ist mit unerledigten Angelegenheiten bei den Druiden rund um Aldrassil beschäftigt. Deshalb sucht er einen Reisenden, der auf der Waldstraße nach Süden zieht.",al={"warum bleibt porthannius","warum hat porthannius mich geschickt"}}},fx={["432231a6"]={q="Was ist die Lieferung für Dolanaar?",a="Die Lieferung für Dolanaar ist ein Paket mit frischen Kräutern, die im Laubschattental gesammelt wurden und für die Siedlung Dolanaar im Süden bestimmt sind. Sie wurde Euch von Porthannius anvertraut und stellt den routinemäßigen Handel und die Versorgung dar, die von den geschützten Hainen des Laubschattentals hinunter zur größeren Gemeinschaft der Nachtelfen fließt.",al={"was ist die lieferung für dolanaar","paket für dolanaar","paket aus dem laubschattental"}},["7521a0db"]={q="Warum möchte Gastwirt Keldamyr die Lieferung für Dolanaar?",a="Gastwirt Keldamyr ist auf diese frischen Kräuter aus dem Laubschattental angewiesen, um die Vorräte im Gasthaus von Dolanaar aufrechtzuerhalten. Kräuter sind unerlässlich für das Brauen von Tränken, die Zubereitung stärkender Mahlzeiten und die Pflege müder Reisender und Verteidiger, die auf Teldrassil Ruhe und Heilung suchen.",al={"warum braucht keldamyr kräuter","zweck der kräuter für dolanaar","warum die lieferung für dolanaar"}}},fp="17,125,24.218.0,21.173.0,37.103.0,24.138.0,37.67.0,52.143.0"}
P.entries["item:doomwarder-blood"] = {n="Doomwarder Blood",s="Doomwarder Blood wird bei mächtigen Dämonen nahe Mannorocs Koven in Desolace gesammelt. Kreldig Ungor benötigt zehn Phiolen für die Experimente eines Magiers.",h="Doomwarder Blood wird bei mächtigen Dämonen nahe Mannorocs Koven in Desolace gesammelt.",kw={"desolace","doomwarder blood","doomwarder captain","felhound brain","kreldig ungor","mannorocs koven","nether wing","reagents for reclaimers inc"},sec={{t="Das Blut eines Dämons",b="Kreldig Ungor in Desolace bittet um zehn Phiolen Doomwarder Blood als letzten Teil seines Auftrags Reagents for Reclaimers Inc. Das Blut stammt von Doomwarder Captains oder Lords unter den Dämonen nahe Mannorocs Koven. Kreldig warnt, dass das Sammeln schwieriger ist als das Beschaffen der anderen Reagenzien und die Dämonen weit entfernt von den Zentaurenlagern des Landes sind."}},faq={{q="Wer benötigt Doomwarder Blood?",a="Kreldig Ungor benötigt zehn Phiolen Doomwarder Blood für Reagents for Reclaimers Inc., eine Reihe von Reagenzien für die Experimente eines Magiers.",al={"wer möchte das blut","kreldigs reagenzien","blut für kreldig"}},{q="Woher stammt Doomwarder Blood?",a="Doomwarder Blood stammt von Doomwarder Captains und Lords nahe Mannorocs Koven im Süden von Desolace.",al={"wo doomwarder blood finden","fundort des bluts","quelle von doomwarder blood"}},{q="Warum möchte Kreldig das Blut?",a="Kreldig sammelt das Blut als eines von drei Reagenzien für die Experimente eines Magiers.",al={"warum blut","wofür ist es","experimente eines magiers"}},{q="Wie viele Phiolen werden benötigt?",a="Kreldig bittet um zehn Phiolen Doomwarder Blood.",al={"wie viel blut","anzahl der phiolen","wie viele doomwarder"}},{q="Ist das Blut das einzige Reagenz, das Kreldig benötigt?",a="Nein. Kreldig bittet außerdem um zehn Felhound Brains und zehn Nether Wings.",al={"andere reagenzien","was benötigt er noch","gehirne und flügel"}}},fp="16,140,17.352.0,27.139.0,38.99.0,32.78.0,26.47.0,44.67.0"}
P.entries["item:draenethyst-crystal"] = {n="Draenethyst Crystal",s="Draenethyst-Kristalle sind heilige Steine, die den Orcs im Sicheren Hafen gestohlen wurden. Die Orcs fürchten, ohne sie in einem fernen Land die Orientierung zu verlieren.",h="Draenethyst-Kristalle sind heilige Steine, die den Orcs im Sicheren Hafen gestohlen wurden.",kw={"draenethyst","draenethyst-kristall","draenethyst-kristalle","zuflucht der verirrten","der sichere hafen","verirrte","magtoor","orcs","sümpfe des elends"},sec={{t="Von den Verirrten gestohlen",b="Im Sicheren Hafen in den Sümpfen des Elends sucht Magtoor nach den Draenethyst-Kristallen, die die Verirrten genommen haben. Die Verirrten leben östlich davon in der Zuflucht der Verirrten, wo sie jene fangen oder töten, die sich in ihre Nähe verirren. Einst waren sie Brüder der Orcs, doch die Reise nach Azeroth trieb sie in den Wahnsinn. Die Orcs können die Kristalle nicht mit Gewalt zurückholen und fürchten, ohne sie die Orientierung zu verlieren."}},faq={{q="Warum sind die Kristalle den Orcs heilig?",a="Die Orcs im Sicheren Hafen nennen Draenethyst-Kristalle heilig und fürchten, ohne sie die Orientierung zu verlieren.",al={"bedeutung von draenethyst","warum kristalle wichtig sind","heilige kristalle der orcs"}},{q="Wer nahm die Draenethyst-Kristalle?",a="Die Verirrten aus der Zuflucht der Verirrten stahlen den Orcs die Draenethyst-Kristalle.",al={"wer draenethyst stahl","kristalle der verirrten","wer die kristalle stahl"}},{q="Wo finde ich Magtoor?",a="Magtoor ist im Sicheren Hafen in den Sümpfen des Elends.",al={"magtoors aufenthaltsort","wo magtoor ist","orcs im sicheren hafen"}},{q="Wer sind die Verirrten?",a="Die Verirrten waren einst Brüder der Orcs. Die Strapazen ihrer Reise nach Azeroth trieben sie in den Wahnsinn, und nun leben sie in der Zuflucht der Verirrten.",al={"hintergrund der verirrten","wer die verirrten sind","verirrte und orcs"}}},fp="19,153,20.370.0,40.96.0,34.79.0,25.52.0,22.137.0"}
P.entries["item:draenethyst-shard"] = {n="Draenethyst Shard",s="Ein Draenethyst Shard ist ein roter Kristall, der aus den Sümpfen des Elends zu den Gelkis-Kentauren in Desolace gebracht wurde. Uthek die Weise sucht seine Magie, um die Gelkis gegen ihre Feinde zu stärken.",h="Ein Draenethyst Shard ist ein roter Kristall, der aus den Sümpfen des Elends zu den Gelkis-Kentauren in...",kw={"desolace","draenethyst","draenethyst shard","gelkis","ongeku","roter kristall","sümpfe des elends","uthek die weise"},ang={["faction:Horde"]="Die Gelkis suchen den Splitter in den Sümpfen des Elends nahe Steinard, einer Stadt der Horde im südlichen Sumpf."},sec={{t="Ein roter Kristall",b="Uthek die Weise sagt, Draenethyst sei neu auf der Welt und stamme aus einem fernen Land, in dem Dämonen herrschen. Er bittet Euch, ihm einen Splitter aus den Sümpfen des Elends zu bringen, den Ongeku bei sich trägt, den die Gelkis den Verlorenen nennen. Uthek glaubt, seine Magie könne seinem Volk im Kampf gegen seine Feinde helfen."}},faq={{q="Was ist ein Draenethyst Shard?",a="Ein Draenethyst Shard ist ein Stück roter Kristall, das laut Uthek der Weisen aus einem fernen, von Dämonen beherrschten Land stammt.",al={"draenethyst","roter kristall","was ist dieser splitter"}},{q="Wer will den Splitter?",a="Uthek die Weise von den Gelkis in Desolace will den Splitter. Er glaubt, seine Magie könne sein Volk stärken.",al={"wer braucht draenethyst","uthek splitter","gelkis-kristall"}},{q="Wo finde ich einen Draenethyst Shard?",a="Ongeku trägt einen Draenethyst Shard in den Sümpfen des Elends bei sich.",al={"wo ist der splitter","ongeku splitter","draenethyst fundort"}},{q="Wer ist Ongeku?",a="Ongeku ist der Verlorene, der den Draenethyst Shard in den Sümpfen des Elends bei sich trägt.",al={"wer ist ongeku","der verlorene","wer hat den kristall"}},{q="Warum will Uthek ihn?",a="Uthek glaubt, die Magie des Splitters werde ihn stärken und den Gelkis helfen, ihre Feinde zu bekämpfen.",al={"warum der kristall","was bewirkt der splitter","gelkis-magie"}}},fp="17,184,13.282.0,28.112.0,20.104.0,36.57.0,14.79.0,23.93.0"}
P.entries["item:dragonmaw-war-banner"] = {n="Kriegsflagge des Drachenmals",s="Banner der Dragonmaw ragen nun über den Orclagern im Sumpfland auf. Ihre Zeichen zeigen den zwergischen Verteidigern des Hafens von Menethil, wie die Bedrohung wächst.",h="Banner der Dragonmaw ragen nun über den Orclagern im Sumpfland auf.",kw={"dragonmaw","grim batol","menethil","nek'rosh","starkfaust","kriegsflagge","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz schwächt Ihr einen alten Feind, bevor die Dragonmaw die schreckliche Stärke wiedererlangen können, über die sie im Zweiten Krieg verfügten.",["race:Dwarf"]="Als Zwerg aus Khaz Modan helft Ihr, die Banner der Dragonmaw aus dem Sumpf zu entfernen und die Handelswege zum Hafen von Menethil vor Orc-Räubern zu schützen."},sec={{t="Zeichen einer anhaltenden Bedrohung",b="Nach dem Zweiten Krieg zerbrach der Dragonmaw-Clan, als seine Orcs die Kontrolle über ihre versklavten roten Drachen verloren. Die erzürnten Drachen wandten sich gegen ihre Häscher und vertrieben die Überlebenden aus Grim Batol in die östlichen Hügel. Nun sammeln die verbliebenen Orcs unter Kriegshäuptling Nek'rosh neue Kräfte. Ihre Banner ragen über Lagern nordöstlich vom Hafen von Menethil auf und warnen die Sumpfsiedlungen vor ihrem Trotz."},{t="Beweis der Eroberung",b="Hauptmann Starkfaust im Hafen von Menethil schickt Abenteurer der Allianz in die Sumpflager, um Banner der Dragonmaw zurückzubringen. Räuber, Zenturionen und Knochenbehüter tragen diese Trophäen. Sie beweisen der Zwergengarnison, dass die Lager zerschlagen werden, bevor der Clan koordinierte Überfälle starten kann."}},faq={{q="Warum will Hauptmann Starkfaust diese Banner?",a="Hauptmann Starkfaust will die Banner als Beweis, dass Abenteurer das Lager der Dragonmaw nordöstlich vom Hafen von Menethil angegriffen und seine Reihen gelichtet haben.",al={"warum banner sammeln","zweck der war banners","warum starkfaust banner will"}},{q="Wer trägt die War Banners der Dragonmaw?",a="Räuber, Sumpfläufer, Zenturionen, Kampfmeister, Schattenbehüter und Knochenbehüter der Dragonmaw sowie Kriegshäuptling Nek'rosh tragen die Banner in ihren Lagern im Sumpfland.",al={"wer hinterlässt banner der dragonmaw","wo war banners bekommen","welche orcs haben banner"}},{q="Warum sind die Orcs der Dragonmaw im Sumpfland?",a="Gegen Ende des Zweiten Krieges verloren die Dragonmaw die Kontrolle über ihre gefangenen roten Drachen. Die befreiten Drachen jagten ihre einstigen Herren und zwangen die überlebenden Orcs, aus Grim Batol zu fliehen und sich in die östlichen Hügel, die Sumpfgebiete und die umliegenden Berge zu zerstreuen.",al={"warum sind die dragonmaw hier","geschichte der dragonmaw im sumpfland","hintergrund der dragonmaw"}},{q="Wer führt den Dragonmaw-Clan jetzt an?",a="Kriegshäuptling Nek'rosh führt den Clan an. Er ist der Sohn des früheren Häuptlings Nekros und hat den roten Drachen Rache geschworen, die sich gegen seinen Vater wandten und ihn töteten.",al={"anführer der dragonmaw","wer ist nek'rosh","kriegshäuptling nek'rosh"}}},fx={abf078db={q="Was ist eine Kriegsflagge des Drachenmals?",a="Diese Standarten dienen als Sammelsymbole des Drachenmalklans im Sumpfland. Markiert mit den Siegeln eines Orc-Clans, der berüchtigt dafür ist, einst den roten Drachenschwarm versklavt zu haben, repräsentieren die Flaggen ihren militärischen Stolz und ihren anhaltenden Trotz. Für die Verteidiger der Allianz im Hafen von Menethil beweist das Erbeuten dieser Flaggen, dass ein Lager zerschlagen und seine Krieger in die Flucht geschlagen wurden.",al={"was ist die kriegsflagge des drachenmals","drachenmalflagge","kriegsflaggen des drachenmals"}},["2c481a00"]={q="Woher kommen die Kriegsflaggen des Drachenmals und wer hat sie hergestellt?",a="Sie werden von den überlebenden Orcs des Drachenmalklans hergestellt und getragen. Nachdem sie ihre Festung Grim Batol verloren hatten und vor dem Zorn der befreiten roten Drachen geflohen waren, gruppierten sich die Drachenmal-Orcs in den Bergen und Sümpfen nordöstlich des Hafens von Menethil neu. Dort fertigen ihre Plünderer, Zenturios und Schamanen diese Standarten an, um ihr neu beanspruchtes Territorium zu markieren und ihre wachsenden Kriegstrupps unter Häuptling Nek'rosh zu versammeln.",al={"wer hat die drachenmalflaggen hergestellt","ursprung der kriegsflagge des drachenmals","woher kommen die kriegsflaggen"}}},fp="20,150,29.391.0,17.290.0,46.144.0,38.153.0,43.262.0,33.166.0"}
P.entries["item:dried-seeds"] = {n="Getrocknete Samenkörner",s="Am Wegekreuz gibt Tonga Runentotem Reisenden Getrocknete Samenkörner, um die Kraft unter den Gewässern des Brachlands zu prüfen.",h="Am Wegekreuz gibt Tonga Runentotem Reisenden Getrocknete Samenkörner, um die Kraft unter den Gewässern des...",kw={"brachland","blubbernde spalte","das wegekreuz","getrocknete samenkörner","die brackige oase","tonga runentotem"},ang={["class:Druid"]="Als Druide könnt Ihr die toten Samen nutzen, um die seltsamen Energien zu erforschen, die aus der Erde des Brachlands aufsteigen.",["faction:Horde"]="Als Abenteurer der Horde könnt Ihr Tonga Runentotem helfen, die Veränderungen in den trockenen Böden des Brachlands zu untersuchen."},sec={{t="Die Samen und die Oase",b="Tonga Runentotem erforscht seltsame Schlote unter den Gewässern des Brachlands. Bei den Vergessenen Teichen fand er Spalten unter der Wasseroberfläche. Nun will er herausfinden, ob auch unter der Brackigen Oase im Südosten eine liegt.\n\nDie Getrockneten Samenkörner wirken leblos. Tonga bittet Reisende, sie in die blubbernde Spalte zu legen und zu beobachten, was geschieht. Ihre Reaktion könnte zeigen, ob die Energie unter den Oasen Leben in toten Samen wecken kann."}},faq={{q="Wofür werden die Getrockneten Samenkörner verwendet?",a="Ihr verwendet Getrocknete Samenkörner, um die blubbernde Spalte unter der Brackigen Oase zu prüfen. Legt sie dort ins Wasser und seht, ob die Energie sie wiederbeleben kann.",al={"getrocknete samenkörner verwendung","was tun mit getrockneten samenkörnern","getrocknete samenkörner zweck"}},{q="Wer stellt die Getrockneten Samenkörner bereit?",a="Tonga Runentotem, ein Taurendruide am Wegekreuz, gibt Reisenden Getrocknete Samenkörner. Er erforscht das plötzlich auftretende Pflanzenwachstum im Brachland.",al={"wer gibt getrocknete samenkörner","woher kommen getrocknete samenkörner"}},{q="Wo liegt die Spalte, an der sie verwendet werden?",a="Die Spalte liegt unter dem Wasser der Brackigen Oase, südöstlich vom Wegekreuz im Brachland.",al={"wo getrocknete samenkörner einpflanzen","brackige oase spalte fundort","blubbernde spalte getrocknete samenkörner"}},{q="Was geschieht, wenn die Samen der Spalte ausgesetzt werden?",a="Tonga bittet Euch, die toten Samen in die blubbernde Spalte zu legen und sie zu beobachten. Ihre Reaktion zeigt das Ergebnis seines Experiments.",al={"wachsen die samen","getrocknete samenkörner ergebnis"}}},fx={aa7d6cee={q="Was sind die Getrockneten Samenkörner?",a="Dies sind völlig tote und unfruchtbare Pflanzensamen, die Euch für ein ökologisches Experiment zur Verfügung gestellt wurden. Sie sind von Natur aus so verdorrt, dass keine Hoffnung auf Keimung besteht, was sie zu einem idealen Kontrollsubjekt macht, um zu testen, ob die mysteriösen sprudelnden Spalten in den Oasen des Brachlands unnatürliche, lebensspendende Eigenschaften besitzen.",al={"was sind getrocknete samenkörner","gegenstand getrocknete samenkörner","lore zu getrockneten samenkörnern"}},f2970934={q="Warum möchte Tonga Runentotem, dass Ihr die Getrockneten Samenkörner testet?",a="Tonga Runentotem versucht, die wahre Natur der seltsamen Spalten aufzudecken, die unter dem Wasser der Oasen des Brachlands sprudeln. Indem er leblose, unfruchtbare Samen direkt der Spalte in der The Stagnant Oasis aussetzt, hofft er zu beobachten, ob die Gewässer das Wachstum anregen können, wo natürliches Leben völlig versagt hat.",al={"warum getrocknete samenkörner","warum getrocknete samenkörner benutzen","zweck der tonga-samen"}}},fp="11,109,23.414.1,34.151.0,29.134.0,36.102.0,55.133.1"}
P.entries["item:durnan-s-scalding-mornbrew"] = {n="Durnans kochend heißes Morgengebräu",s="In Ambossar wartet Durnan Pelznaht auf seinen Becher Morgengebräu, während die Bergkälte droht, ihn schon vor der Ankunft abzukühlen.",h="In Ambossar wartet Durnan Pelznaht auf seinen Becher Morgengebräu, während die Bergkälte droht, ihn schon vor...",kw={"ambossar","das coldridgetal","dun morogh","durnan pelznaht","morgengebräu","kochend heiß"},ang={["race:Dwarf"]="Als Zwerg aus Dun Morogh wisst Ihr, wie bitter es ist, gutes Bier oder Morgengebräu im Bergfrost kalt werden zu lassen."},sec={{t="Ein Wettlauf gegen die Kälte",b="Ein Bote verspätet sich auf dem Weg zu Grelin Weißbart, und der frische Becher ist dem Frost des Coldridgetals ausgesetzt. Tragt ihn binnen weniger Minuten den verschneiten Pfad hinauf in die Berghalle, sonst wird Durnans Gebräu kalt."}},faq={{q="Für wen ist das Gebräu bestimmt?",a="Das Gebräu ist für Durnan Pelznaht bestimmt, einen Zwerg, der in Ambossar im Coldridgetal stationiert ist.",al={"wer bekommt morgengebräu","durnan morgengebräu empfänger","wohin kommt das gebräu"}},{q="Warum muss die Lieferung so schnell erfolgen?",a="Die eisige Luft Dun Moroghs kühlt einen offenen Becher rasch ab. Durnan hat kochend heißes Morgengebräu bestellt, und ein lauwarmer Becher wird ihn nicht zufriedenstellen.",al={"warum zeitlimit","gebräu wird kalt","warum eilt das morgengebräu"}},{q="Wo beginnt die Lieferung?",a="Das Getränk wird nahe Grelin Weißbarts Lager außerhalb von Ambossar übergeben, nachdem der Bote erkennt, dass er die Schmiedehalle allein nicht rechtzeitig erreichen kann.",al={"woher kommt das morgengebräu","wer schenkt das gebräu ein"}},{q="Was geschieht, sobald Durnan den Becher erhält?",a="Durnan unterbricht seine Pflichten in Ambossar, um das dampfende Getränk zu genießen, solange es noch heiß ist.",al={"durnans reaktion","morgengebräu abgeben"}}},fx={["93832100"]={q="Was ist Durnans kochend heißes Morgengebräu?",a="Es ist ein frisch eingeschenkter Becher heißes Zwergen-Morgengebräu, der speziell für Durnan Pelznaht in Ambossar bestimmt ist. Gebraut, um die Knochen gegen die beißende Bergkälte des Coldridgetals zu wärmen, muss es kochend heiß getrunken werden, um wirklich den richtigen Geschmack zu entfalten.",al={"was ist das kochend heiße morgengebräu","gegenstand durnans morgengebräu","morgengebräu-getränk"}},c7c22f23={q="Warum möchte Durnan das kochend heiße Morgengebräu?",a="Durnan Pelznaht hat das dampfende Gebräu bestellt, um es während einer wohlverdienten Pause von seiner Arbeit in Ambossar zu genießen. Zwerge nehmen ihr morgendliches Getränk sehr ernst, und einen solch herzhaften Becher kalt werden zu lassen, würde die ganze Erfrischung ruinieren.",al={"warum will durnan morgengebräu","warum wird das morgengebräu benötigt","zweck des getränks für durnan"}}},fp="26,124,23.208.0,29.94.0,48.122.0,34.153.0,42.91.0"}
P.entries["item:durotar-tiger-fur"] = {n="Durotartigerfell",s="Auf den Echoinseln vor Durotars Südostküste sichert Durotartigerfell das Überleben der wachsenden Siedlung der Dunkelspeer. Die Trolle fertigen aus den Fellen Decken, Zelte und Rüstungen.",h="Auf den Echoinseln vor Durotars Südostküste sichert Durotartigerfell das Überleben der wachsenden Siedlung...",kw={"durotar-tiger","durotartigerfell","die echoinseln","practical prey","sen'jin","trollfell","vel'rin fang"},ang={["class:Hunter"]="Als Jäger braucht Ihr Geduld und Tarnung, um Euch auf den Echoinseln an Tiger anzupirschen. Die Jagd erinnert an traditionelle Jagdriten der Trolle, wenn Ihr den lautlosen Inselraubtieren auflauert.",["race:Troll"]="Für die Dunkelspeer bedeuten Tigerhäute das Überleben in Sen'jin. Sie erinnern auch an den schmerzlichen Verlust ihrer Heimat auf den Echoinseln."},sec={{t="Ein lebenswichtiger Rohstoff für die Dunkelspeer",b="In Sen'jin müssen die Dunkelspeer mit knappen Vorräten auskommen. Deshalb lassen sie die örtlichen Tiger gedeihen, bis ihr Bedarf eine Ausdünnung erfordert. Die Trolle gerben die dicken Häute und fertigen daraus benötigte Güter, darunter Rüstungen und warme Decken für jahreszeitliche Wetterumschwünge."},{t="Jagd auf den Echoinseln",b="Die Echoinseln liegen südlich von Durotar, jenseits des offenen Wassers. Die Dunkelspeer nannten die Inseln einst ihre Heimat, bis der Hexendoktor Zalazane sie vertrieb. Jäger müssen sich vor Zalazanes Knechten und vor Tigern im dichten Blattwerk hüten. Erfahrene Jäger wie Vel'rin Fang berichten davon, ganze Tage regungslos im Dschungeldickicht zu verharren, um einen einzigen sauberen Abschuss zu erzielen."}},faq={{q="Wo erhält man Durotartigerfelle?",a="Jäger erbeuten Durotartigerfell von Tigern auf den Echoinseln vor Durotars Südostküste.",al={"wo werden tigerfelle erbeutet","durotartigerfell fundort","wie erhält man tigerfelle"}},{q="Warum brauchen die Trolle von Sen'jin diese Felle?",a="Vel'rin Fang sammelt Felle für die wachsende Siedlung der Dunkelspeer. Die Trolle fertigen daraus Decken, Zelte und schützende Lederrüstungen gegen jahreszeitliche Witterung.",al={"warum tigerfelle sammeln","wer braucht tigerfell","practical prey zweck"}},{q="Warum jagen die Trolle nicht zu viele Tiger?",a="Die Dunkelspeer lassen den Tigerbestand gedeihen und dünnen ihn erst aus, wenn der Bedarf ihrer wachsenden Gemeinschaft die Vorräte an Unterkünften und Kleidung übersteigt.",al={"tigerschutz","herde ausdünnen"}}},fx={e997b985={q="Was ist Durotartigerfell?",a="Durotartigerfell ist das Fell, das von den wilden Tigern geerntet wird, die auf den Echoinseln vor der südöstlichen Küste von Durotar schleichen. Diese robusten, warmen und widerstandsfähigen Felle sind ein wesentlicher Rohstoff für die Dunkelspeertrolle von Sen'jin, die sie zu Gegenständen des täglichen Bedarfs verarbeiten, um ihr Volk vor den rauen Elementen zu schützen.",al={"was ist durotartigerfell","tigerfell durotar","was ist dieses fell"}},c85f7978={q="Woher kommt Durotartigerfell?",a="Diese Felle werden direkt von den Durotartigern abgezogen, die durch das dichte Unterholz der Echoinseln pirschen. Sie werden nicht von Handwerkern hergestellt, sondern in freier Wildbahn von Pirschern und Spähern gejagt, die den Gewässern südlich von Sen'jin trotzen.",al={"ursprung von durotartigerfell","woher kommen tigerfelle","wer verarbeitet durotartigerfell"}}},fp="17,179,34.260.0,22.365.0,38.102.0,53.160.0,41.137.0"}
P.entries["item:duskbat-wing"] = {n="Nachtsaugerflügel",s="Rund um Todesend helfen Nachtsaugerflügel frisch auferstandenen Verlassenen, Schutz zu finden.",h="Rund um Todesend helfen Nachtsaugerflügel frisch auferstandenen Verlassenen, Schutz zu finden.",kw={"todesend","dämmerfledermaus","nachtsaugerflügel","novize elreth","aasfressertatze","the damned","tirisfal"},ang={["profession:Tailoring"]="Novize Elreth zeigt, wie Schneider in Tirisfal zähe Fledermausflügel als brauchbaren Ersatz für Leder und Stoff verwenden.",["race:Undead"]="Als frisch erwachter Verlassener sammelt Ihr diese Flügel als eine Eurer ersten Aufgaben zum Überleben. Sie helfen Euch, Eure ersten Scharmützel in einem Stück zu überstehen."},sec={{t="Notdürftiger Schutz in Todesend",b="Neue Verlassene erheben sich aus Todesends Erde mit kaum mehr als Lumpen und brüchigen Knochen. Geistlose Diener der Geißel und feindselige Wildtiere streifen in der Nähe umher, also sammeln sie jeden Schutz, den sie finden können. Novize Elreth, die Gehilfin von Schattenpriester Sarvis, sammelt Nachtsaugerflügel und Wolfspfoten. Gemeinsam verarbeiten sie die Materialien zu stärkerer Kleidung und Rüstung für frisch erweckte Krieger, bevor diese zum Kampf in die Wildnis ziehen."}},faq={{q="Wofür werden Nachtsaugerflügel verwendet?",a="In Todesend verwendet Novize Elreth Nachtsaugerflügel und Aasfresserpfoten, um Kleidung und Rüstung für frisch erwachte Rekruten der Verlassenen herzustellen, zu flicken und zu verstärken.",al={"nachtsaugerflügel verwendung","warum nachtsaugerflügel sammeln","zweck von nachtsaugerflügeln"}},{q="Woher stammen Nachtsaugerflügel?",a="Dämmerfledermäuse und Mangy Duskbats in den Hainen und Hügeln rund um Todesend in Tirisfal liefern diese Flügel.",al={"wo nachtsaugerflügel finden","nachtsaugerflügel herkunft","wer lässt nachtsaugerflügel fallen"}},{q="Wer benötigt diese Flügel in Todesend?",a="Novize Elreth bittet Rekruten, die Flügel zu sammeln. Unter der Leitung von Schattenpriester Sarvis versorgt sie in der Kapelle von Todesend die Verwundeten und stellt Ausrüstung her.",al={"wer braucht nachtsaugerflügel","nachtsaugerflügel abgeben","nachtsaugerflügel questgeber"}},{q="Warum verwenden die Verlassenen Fledermausteile für Rüstungen?",a="Todesend hat kaum Nachschubwege oder herkömmliche Fertigung, daher sammeln örtliche Helfer Häute, Fell und ledrige Fledermausflügel von Tirisfals heimischen Raubtieren. Aus diesen Materialien fertigen sie einfache Schutzkleidung für Rekruten, die in den Kampf ziehen.",al={"warum fledermausflügel für rüstungen","fledermausleder rüstung verlassene"}}},fx={d5eef861={q="Was ist ein Nachtsaugerflügel?",a="Ein Nachtsaugerflügel ist der lederartige Flügel, der von Nachtsaugern geerntet wird, die durch die verwunschenen Wälder von Tirisfal flattern. In Todesend, wo hergestellte Waren knapp sind, dienen diese Flügel als wichtiger Rohstoff. Schneider und Betreuer der Verlassenen nähen und gerben das Fledermausfell zu strapazierfähiger Kleidung und leichter Rüstung für neu erwachte Untote, bevor sie diese aussenden, um den Gefahren der Lichtungen zu begegnen.",al={"was ist ein nachtsaugerflügel","gegenstand nachtsaugerflügel","über nachtsaugerflügel"}}},fp="12,79,35.408.0,32.153.0,33.109.0,39.152.0,48.266.0"}
P.entries["item:dusky-crab-cakes"] = {n="Schwärzliche Krebsküchlein",s="In Dunkelhain bereitet Küchenchef Grual Schwärzliche Krebsküchlein für den hungrigen Bibbers zu. Bibbers findet die örtliche Delikatesse exquisit.",h="In Dunkelhain bereitet Küchenchef Grual Schwärzliche Krebsküchlein für den hungrigen Bibbers zu.",kw={"dunkelhain","dämmerwald","schwärzliche krebsküchlein","grual","bibbers","spinnenbeine"},ang={["profession:Cooking"]="Gruals Küchlein zeigen, wie ein Koch aus Zutaten, die im Dämmerwald zu finden sind, eine würzige örtliche Spezialität zubereiten kann."},sec={{t="Eine fragwürdige Delikatesse",b="Küchenchef Grual bereitet Schwärzliche Krebsküchlein für Bibbers zu, einen verängstigten Landstreicher, den der Hunger überwältigt hat. Im Dämmerwald gibt es kaum frische Vorräte, also behelfen sich die Köche mit Fleisch aus dem Wald.\n\nDie Küchlein sehen wie gewöhnliche Meeresfrüchtefrikadellen aus, doch Grual verwendet Fleisch aus den Beinen der monströsen Spinnentiere des Dämmerwalds. Bibbers verschlingt sie, ohne zu wissen, was er da isst."}},faq={{q="Woraus bestehen Schwärzliche Krebsküchlein eigentlich?",a="Küchenchef Grual behält sein Rezept für sich. Seine geheime Zutat kommt ans Licht, während im Dämmerwald Vorräte für ihn gesammelt werden.",al={"krebsküchlein zutaten","was ist in schwärzlichen krebsküchlein","spinnenfleisch"}},{q="Wer isst die Schwärzlichen Krebsküchlein?",a="Küchenchef Grual bereitet die Küchlein für Bibbers zu, einen ängstlichen Mann, der in Rabenflucht Unterschlupf sucht und über Magenknurren klagt.",al={"wer bekommt die krebsküchlein","für wen sind sie","bibbers essen"}},{q="Wie reagiert Bibbers auf die Küchlein?",a="Ausgehungert verschlingt Bibbers die Küchlein voller Freude, ohne ihr Rezept zu hinterfragen. Er ist dankbar für eine Mahlzeit, die seinen Hunger stillt.",al={"bibbers reaktion","schmecken bibbers die küchlein"}},{q="Wer bereitet die Schwärzlichen Krebsküchlein zu?",a="Küchenchef Grual, Koch in der Scarlet Raven Tavern in Dunkelhain, bereitet die Küchlein aus Vorräten zu, die für ihn gesammelt werden.",al={"wer macht die krebsküchlein","küchenchef grual","koch dunkelhain"}}},fp="16,115,23.346.1,43.125.0,30.116.0,36.130.0,31.109.0"}
P.entries["item:dust-devil-debris"] = {n="Staubteufeltrümmer",s="Überall in Westfall hinterlassen Staubteufel geladenen Sand. Magier verzaubern damit Pergament und binden Nachrichtenzauber in Schriftrollen.",h="Überall in Westfall hinterlassen Staubteufel geladenen Sand.",kw={"collin mauren","staubteufeltrümmer","staubteufel","nachrichtenzauber","schriftrolle","sturmwind","westfall"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, wie elementare Überreste die Schreibkunst und Kommunikationsmagie unterstützen und dabei rohes elementares Chaos mit arkaner Disziplin verbinden."},sec={{t="Zu Pergament gesponnene Luft",b="Staubteufel fegen als heftige Wirbelstürme über die Ebenen von Westfall. Wenn einer fällt, zerfällt der lebende Sturm zu geladenem Staub und Sand, den sogenannten Staubteufeltrümmern. Eine schwache Spur des elementaren Wirbels bleibt in den Rückständen erhalten.\n\nIn Sturmwind schätzen Anwender der arkanen Künste wie Collin Mauren den Sand für besondere Zauberei. Vermischt mit verzauberter Tinte und Pergament hilft er einem Magier, einen luftigen Nachrichtenzauber an eine Schriftrolle zu binden, der Worte durch das Königreich trägt."}},faq={{q="Wofür werden Staubteufeltrümmer verwendet?",a="Collin Mauren verwendet Staubteufeltrümmer, um eine besondere Nachrichtenschriftrolle herzustellen. Ihre verbliebene elementare Energie hilft ihm, feine Kommunikationsmagie an Papier zu binden.",al={"staubteufeltrümmer verwendung","warum staubteufeltrümmer sammeln","trümmer zweck"}},{q="Woher stammen diese Trümmer?",a="Staubteufeltrümmer stammen von Staubteufeln, feindseligen Luftelementaren, die über Westfalls karges Ackerland und seine Straßen streifen.",al={"wo trümmer finden","staubteufel beute","westfall trümmer"}},{q="Warum sind Staubteufel gefährlich?",a="Staubteufel sind feindselige Luftelementare, die durch Westfall streifen. Collin Mauren warnt, dass man sich gefährlichen Kreaturen stellen muss, um ihre Trümmer zu sammeln.",al={"warum elementare in westfall","westfall staubteufel ursprung"}},{q="Wer ist Collin Mauren?",a="Collin Mauren ist ein menschlicher Magier im Magierviertel von Sturmwind. Mit seinem arkanen Wissen stellt er verzauberte Schriftrollen und magische Komponenten für andere Anwender der arkanen Künste und neugierige Forscher her.",al={"collin mauren","wer will trümmer"}}},fx={["2f6e3759"]={q="Was sind Staubteufeltrümmer?",a="Staubteufeltrümmer bestehen aus dem wirbelnden Sand, Schmutz und den magischen Rückständen, die zurückbleiben, wenn ein Staubteufel in Westfall besiegt wird. Diese elementaren Wirbelstürme durchkämmen die trockenen Ebenen und ihre Überreste behalten genügend Umgebungsmacht, um als wirkungsvolle Reagenzien für Verzauberer und Schriftgelehrte zu dienen.",al={"was sind staubteufeltrümmer","staubteufeltrümmer","gegenstand staubteufeltrümmer"}}},fp="17,129,23.458.0,35.162.0,33.115.0,30.140.0,21.189.0"}
P.entries["item:dwarven-tinder"] = {n="Zwergenzunder",s="Im Sumpfland tragen Saboteure der Allianz Zwergenzunder bei sich, um Belagerungsmaschinen des Dragonmawklans zu verbrennen, bevor sie den Hafen von Menethil erreichen.",h="Im Sumpfland tragen Saboteure der Allianz Zwergenzunder bei sich, um Belagerungsmaschinen des Dragonmawklans...",kw={"katapulte","dragonmaw","zwergenzunder","hafen von menethil","nek'rosh","sabotage","sumpfland"},ang={["faction:Alliance"]="Als Mitglied der Allianz wisst Ihr, dass das Verbrennen feindlicher Kriegsmaschinen vor dem Erreichen des Hafens von Menethil hilft, Euren wichtigsten Hafen im Sumpfgebiet zu halten, während die Pässe von Dun Algaz umkämpft sind.",["race:Dwarf"]="Als Zwerg wisst Ihr, wie wichtig zuverlässige Feueranzünder im Sumpfland sind, wo Regen und Moore das Land ständig durchnässt halten."},sec={{t="Sabotage am Dragonmawklan",b="Späher der Allianz entdeckten die schweren Katapulte von Häuptling Nek'rosh im Lager des Dragonmawklans, und der Hafen von Menethil stand vor einer Krise. Kämpfe in Dun Algaz hatten den Hafen von Verstärkung aus dem Süden abgeschnitten. Seine Verteidiger konnten einer langen Belagerung nicht standhalten, also beschlossen sie, die Katapulte zu sabotieren, bevor diese eingesetzt werden konnten.\n\nFreiwillige trugen Zwergenzunder in orkisches Gebiet und entzündeten ihn mit einem geschlagenen Funken. Seine Flammen verbrannten die verstärkten hölzernen Maschinen innerhalb von Minuten."}},faq={{q="Wofür wird Zwergenzunder verwendet?",a="Saboteure der Allianz verwenden Zwergenzunder, um Katapulte des Dragonmawklans im Sumpfland zu verbrennen, bevor diese den Hafen von Menethil angreifen können.",al={"zwergenzunder verwendung","warum zwergenzunder verwenden","was bewirkt zwergenzunder"}},{q="Warum werden die Katapulte verbrannt, statt sie zu erbeuten?",a="Die Verteidiger können tief im Gebiet des Dragonmawklans keine schweren Belagerungsmaschinen erbeuten. Zahlenmäßig unterlegen und durch die Blockade bei Dun Algaz von Verstärkung aus Eisenschmiede abgeschnitten, sehen sie in der Zerstörung der Katapulte ihre einzige erfolgversprechende Verteidigung.",al={"warum die katapulte zerstören","warum die belagerungsmaschinen nicht erbeuten"}},{q="Wer hat diesen Zunder vorbereitet?",a="Die Zwergengarnison im Hafen von Menethil liefert den Zunder, der so präpariert ist, dass er bei Sabotageeinsätzen schnell und zuverlässig Feuer fängt.",al={"wer hat den zunder hergestellt","woher kommt zwergenzunder"}}},fx={["5fa2c489"]={q="Was ist Zwergenzunder?",a="Zwergenzunder ist ein leicht entzündliches, speziell vorbereitetes Anzündholz, das von den Verteidigern des Hafens von Menethil bereitgestellt wird. Von Zwergen-Milizionären hergestellt, um selbst von einem verirrten Funken schnell Feuer zu fangen, stellt es sicher, dass gewaltige hölzerne Kriegsmaschinen im feuchten Sumpfland schnell und gründlich in Brand gesetzt werden können, bevor feindliche Streitkräfte reagieren können.",al={"was ist zwergenzunder","gegenstand zwergenzunder","über zwergenzunder"}},f9865b90={q="Warum wird Zwergenzunder gerade jetzt benötigt?",a="Die Drachenmal-Orcs unter Nek'rosh haben massive Belagerungskatapulte gebaut, um den Hafen von Menethil zu stürmen. Da Verstärkungen aus Eisenschmiede durch heftige Kämpfe in Dun Algaz abgeschnitten sind, kann Menethil einen langwierigen Angriff nicht überstehen. Ihr müsst diesen Zunder benutzen, um das Lager der Drachenmals zu infiltrieren und ihre Kriegsmaschinen zu Asche zu verbrennen, bevor sie aufbrechen können.",al={"warum zwergenzunder","warum wird zwergenzunder benötigt","warum benötigen wir zunder"}}},fp="14,123,24.470.0,32.121.0,49.225.0,25.126.0"}
P.entries["item:ear-of-balgaras"] = {n="Balgaras' Ohr",s="In Dun Modr beweist Balgaras' Ohr, dass die Herrschaft des Hexenmeisters beendet ist. Eisenschmiedes Gebirgsjäger bergen es vom Leichnam des Dunkeleisenkommandanten.",h="In Dun Modr beweist Balgaras' Ohr, dass die Herrschaft des Hexenmeisters beendet ist.",kw={"balgaras der niederträchtige","dunkeleisen","dun modr","balgaras' ohr","langzopf der grimmige","thandol-übergang","sumpfland"},ang={["class:Warlock"]="Balgaras wirkte Schatten- und Teufelsmagie aus seinem Versteck heraus. Seine Niederlage beendet die Bedrohung durch einen Hexenmeister, der Verderben über die nördliche Straße brachte.",["race:Dwarf"]="Für die Zwerge von Eisenschmiede begleicht die Inbesitznahme des Ohrs eine blutige Rechnung für ihre bei der Sabotage des Thandol-Übergangs getöteten Verwandten."},sec={{t="Eine düstere Trophäe",b="Balgaras der Niederträchtige führte den Angriff der Dunkeleisenzwerge auf Dun Modr an. Seine Truppen sabotierten den Thandol-Übergang und vernichteten die Zwergengarnison, sodass der Vorposten in Trümmern lag. Als ränkeschmiedender Hexenmeister lenkte Balgaras seine Truppen aus den Schatten heraus und mied den persönlichen Kampf. Langzopf der Grimmige, der Offizier des Bergkönigs außerhalb der Ruinen, will einen Beweis dafür, dass der Rädelsführer gefallen ist. Balgaras' abgetrenntes Ohr zeigt, dass seine Herrschaft an der nördlichen Grenze vorüber ist."},{t="Gerechtigkeit für die Gefallenen",b="Der Fall von Dun Modr kostete Langzopf seinen Bruder und Dutzende tapfere Soldaten, als die Westbrücke einstürzte. Das Ohr kann weder die Brücke wiederherstellen noch die Toten zurückbringen. Ohne Balgaras als Anführer können Eisenschmiedes Späher die überlebenden, im nördlichen Sumpfland verstreuten Dunkeleisentruppen leichter in Schach halten, bevor ein weiterer Kommandant aus dem Süden eintrifft."}},faq={{q="Wer war Balgaras der Niederträchtige?",a="Balgaras der Niederträchtige war ein Hexenmeister der Dunkeleisenzwerge, dessen Kriegstrupp Dun Modr angriff und die Westbrücke des Thandol-Übergangs zerstörte. Für seine Feigheit bekannt, schickte er Welle um Welle von Soldaten in den Tod, während er sich vor Patrouillen der Allianz versteckte.",al={"wer ist balgaras","balgaras geschichte","balgaras der niederträchtige"}},{q="Warum will Langzopf der Grimmige ausgerechnet sein Ohr?",a="Langzopf der Grimmige will einen Beweis dafür, dass der schwer zu fassende Hexenmeister tot ist. Ein abgetrenntes Ohr ist eine klassische Trophäe im Grenzland und bestätigt den erfüllten Auftrag, ohne dass sein Überbringer einen Leichnam zum Zwergenlager zurückschleppen muss.",al={"warum ein ohr","warum das ohr abschneiden","langzopf beweis"}},{q="Was geschieht mit den Dunkeleisenzwergen, sobald Balgaras tot ist?",a="Ohne ihren berechnenden Anführer verlieren die überlebenden Dunkeleisentruppen in Dun Modr ihren Zusammenhalt. Sie treiben noch immer in den Ruinen ihr Unwesen, doch Langzopf glaubt, dass die Allianz sie in Schach halten kann, bevor Eisenschmiedes Feinde einen Ersatzkommandanten schicken.",al={"was geschieht nach balgaras' tod","dunkeleisenzwerge in dun modr"}}},fx={a51409b4={q="Woher stammt Balgaras' Ohr?",a="Dieses abgeschnittene Ohr stammt direkt von Balgaras dem Scheußlichen, einem feigen Hexenmeister der Dunkeleisenzwerge, der in den nördlichen Ausläufern des Sumpflands operiert. Balgaras befehligt die feindseligen Zwerge, die Dun Modr angriffen und die westliche Spannweite der The Thandol Span zerstörten, zieht es jedoch vor, sich zu verstecken, während er seine Schergen in den Kampf schickt.",al={"ursprung von balgaras' ohr","wo bekommt man balgaras' ohr","wer hat balgaras' ohr"}}},fp="15,153,13.440.0,22.358.0,26.229.0,54.202.0,53.231.0"}
P.entries["item:ebonlocke-s-response-to-solomon"] = {n="Schwarzhaupts Antwort an Solomon",s="In Dunkelhain lehnt Lord Ello Schwarzhaupt Solomons Hilfsgesuch für das Rotkammgebirge ab. Sein Brief besagt, dass die Nachtwache den Dämmerwald nicht unverteidigt zurücklassen kann.",h="In Dunkelhain lehnt Lord Ello Schwarzhaupt Solomons Hilfsgesuch für das Rotkammgebirge ab.",kw={"dunkelhain","dämmerwald","schwarzhaupt","seenhain","brief","bote","night watch","rotkammgebirge","solomon"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr sehen, wie Sturmwinds Königshof das Rotkammgebirge, den Dämmerwald und Westfall sich selbst überlassen hat."},sec={{t="Eine bittere Absage",b="Magistrat Solomon bat den Dämmerwald um Verstärkung gegen die Schwarzfelsorcs, nachdem Sturmwind seine Gesuche ignoriert hatte. Lord Ello Schwarzhaupt antwortet voller Zorn und sagt keinerlei Hilfe zu. Er erinnert Solomon daran, dass die Nachtwache entstand, weil Sturmwind Dunkelhain im Stich ließ, als verderbliche Magie erstmals die Wälder ergriff. Wenn seine Verteidiger ins Rotkammgebirge ziehen, bleibt der Dämmerwald schutzlos zurück und fällt dem Bösen anheim, bevor die Miliz den Waldrand erreicht."},{t="Die zerfallende Grenze",b="Solomon ist erschüttert, als Schwarzhaupts Brief ihn erreicht. Die Armee von Sturmwind hat sich aus Westfall zurückgezogen, und die königliche Garde fehlt in Dunkelhain. Die gesamte südliche Grenze wurde dem Verfall preisgegeben. Solomon erkennt ein schreckliches Muster in Sturmwinds Vernachlässigung seiner entlegenen Gebiete und vermutet Verrat in den höchsten Machtkreisen des Königreichs."}},faq={{q="Was ist Schwarzhaupts Antwort an Solomon?",a="Lord Ello Schwarzhaupt aus Dunkelhain schickt Magistrat Solomon aus Seenhain einen versiegelten Brief. Er weigert sich, die Nachtwache zur Verteidigung des Rotkammgebirges zu entsenden, da der Dämmerwald seine eigenen Albträume kaum zurückhalten könne.",al={"schwarzhaupt brief","schwarzhaupt antwort","brief an solomon"}},{q="Warum schickt Dunkelhain keine Hilfe nach Seenhain?",a="Dunkelhain hat keine eigenen königlichen Truppen. Die Nachtwache besteht aus Freiwilligen aus der Gegend, denen die Verteidigung der Region überlassen wurde, nachdem Sturmwind sie im Stich ließ. Lord Schwarzhaupt warnt, dass Untote und abscheuliche Kreaturen Dunkelhain überrennen werden, wenn die Wache abzieht, noch bevor ihre Mitglieder den Wald verlassen.",al={"warum hilft die night watch nicht","warum lehnte dunkelhain ab","schwarzhaupt lehnt solomon ab"}},{q="Wie reagiert Magistrat Solomon auf den Brief?",a="Magistrat Solomon ist schockiert und beunruhigt. Das Fehlen der königlichen Garde in Dunkelhain und der Rückzug der Armee aus Westfall lassen ihn dunkle Machenschaften oder Verrat unter Sturmwinds Anführern vermuten.",al={"solomons reaktion","was sagt solomon"}},{q="Wer hat diesen Brief geschrieben?",a="Lord Ello Schwarzhaupt, Dunkelhains bedrängter Bürgermeister und Anführer des Council of Darkshire, hat den Brief geschrieben. Er leitet die Verteidigung der Stadt.",al={"wer ist schwarzhaupt","lord schwarzhaupt"}}},fx={de19eb29={q="Warum möchte Magistrat Solomon eine Antwort von Schwarzhaupt?",a="Magistrat Solomon sucht verzweifelt nach Verstärkung, um Seenhain gegen die Schwarzfels-Orcs zu verteidigen. Nachdem Sturmwind seine Bitten um militärische Hilfe wiederholt ignoriert hatte, wandte er sich an Dunkelhain, in der Hoffnung, dass Lord Ello Schwarzhaupt die The Nachtwache entbehren könnte. Solomon wartet sehnsüchtig auf diesen Brief, um zu erfahren, ob Hilfe aus dem Dämmerwald kommt, nur um festzustellen, dass Dunkelhain genauso verlassen und bedrängt ist wie das Rotkammgebirge.",al={"warum benötigt solomon den brief","warum die antwort von schwarzhaupt überbringen","warum die antwort an solomon senden"}}},fp="31,143,16.441.0,22.336.1,40.201.0,43.276.0,48.204.1,22.140.0"}
P.entries["item:echeyakee-s-hide"] = {n="Echeyakees Balg",s="Im Wegekreuz erwartet Sergra Dunkeldorn Echeyakees Balg, erbeutet vom legendären weißen Löwen des Brachlands. Die Tauren ehren Weißnebel als Verkörperung von Barmherzigkeit und Tod, während Jäger sein Fell als Beweis ihres Könnens bringen.",h="Im Wegekreuz erwartet Sergra Dunkeldorn Echeyakees Balg, erbeutet vom legendären weißen Löwen des Brachlands.",kw={"brachland","das wegekreuz","echeyakee","echeyakees balg","sergra darkthorn","weißer löwe","weißnebel"},ang={["class:Hunter"]="Als Jäger erbeutet Ihr das Fell des überlegenen Schleichjägers der Savanne als frühes Übergangsritual. Als Fährtenleser der Horde lernt Ihr die Feinheiten der Wildnis kennen.",["race:Tauren"]="Als Taure ehrt Ihr Weißnebels flinken Geist, wenn Ihr Echeyakee jagt. Es ist eine heilige Prüfung der Barmherzigkeit und der Heimlichkeit."},sec={{t="Trophäe von Weißnebel",b="Echeyakee bedeutet Weißnebel in der Sprache Taur-ahe. Unter den Raubtieren der Savanne verdiente sich der Löwe diesen Namen durch sein unauffälliges weißes Fell und seine schnellen Tötungen. Er beendete das Leben seiner Beute, bevor Angst oder Schmerz einsetzen konnten.\n\nEin Jäger ruft die scheue Katze nahe den riesigen Kodoknochen nordöstlich vom Wegekreuz mit einem zeremoniellen Horn herbei und erbeutet dann ihr Fell. Es Sergra Dunkeldorn zu bringen, beweist kriegerisches Geschick und ehrt Weißnebels lautloses, barmherziges Ende."}},faq={{q="Woher stammt Echeyakees Balg?",a="Echeyakees Balg stammt von Echeyakee, dem weißen Löwen, dessen Lager zwischen riesigen Kodoskeletten nordöstlich vom Wegekreuz im Brachland liegt. Sergra Dunkeldorn stellt das Horn von Echeyakee bereit, um ihn herbeizurufen.",al={"wo bekomme ich echeyakees balg","wie bekommt man echeyakees balg","echeyakees fell fundort"}},{q="Wer will Echeyakees Balg?",a="Sergra Dunkeldorn, eine Orcjägerin im Wegekreuz, will Echeyakees Balg. Sie schickt aufstrebende Jäger der Horde los, um die große Katze aufzuspüren und mit ihrem Fell als Beweis ihrer Verbundenheit mit der Wildnis zurückzukehren.",al={"wer gibt echeyakees balg ab","echeyakees balg abgeben","wer braucht echeyakees balg"}},{q="Was bedeutet der Name Echeyakee?",a="Echeyakee bedeutet Weißnebel in der Sprache der Tauren. Der Name ehrt das blasse Fell der Katze und den Glauben, dass sie wie wogender Nebel durch die Savanne zog und ohne anhaltenden Schrecken oder Qualen tötete.",al={"echeyakee übersetzung","bedeutung von echeyakee","taurenname echeyakee"}}},fx={["718fd4d1"]={q="Was ist Echeyakees Balg?",a="Es ist das Fell von Echeyakee, dem verehrten weißen Löwen, der den Tauren als Weißnebel bekannt ist. Er gilt als der König der Savannenkatzen im Brachland, Echeyakee jagt mit unübertroffener Heimlichkeit und Schnelligkeit und wird sowohl als Gnade als auch als Tod angesehen. Sein Fell zu nehmen dient als physischer Beweis dafür, dass ein Jäger das Geschick und den Mut besaß, das legendäre Raubtier zu beschwören und zu besiegen.",al={"was ist echeyakees balg","echeyakees balg","weißlöwenfell"}}},fp="16,228,19.447.0,38.203.0,27.197.0,34.196.0"}
P.entries["item:egalin-s-grimoire"] = {n="Egalins Zauberfoliant",s="In Unterstadt leitet Egalins Zauberfoliant Hexenmeister an, die einen Leerwandler beschwören und beherrschen wollen. Ein Meisterhexenmeister schrieb ihn für den Unterricht im Tempel der Verdammten.",h="In Unterstadt leitet Egalins Zauberfoliant Hexenmeister an, die einen Leerwandler beschwören und beherrschen...",kw={"carendin halgar","creature of the void","egalin","egalins zauberfoliant","perrine","tempel der verdammten","leerwandler"},ang={["class:Warlock"]="Als Hexenmeister könnt Ihr aus Egalins Zauberfoliant lernen, wie Ihr einen Leerwandler aus dem Nether beschwört und Eurem Willen unterwerft. Dieser Ritus markiert einen Übergang für jene, die diese Kunst ausüben.",["race:Undead"]="Als Untoter helft Ihr mit der Rückgewinnung des Buches, ein mächtiges magisches Artefakt der Magiewirker Unterstadts vor dem Zugriff des Scharlachroten Kreuzzugs zu bewahren."},sec={{t="Das Werk eines Meisters",b="Egalins Zauberfoliant enthält die Mittel, um ein Wesen des Chaos aus dem Nether herbeizurufen. Egalin war ein Meisterbeschwörer, berühmt dafür, Leerwandler mühelos zu beherrschen. Er gab sein Können an seine Schüler weiter, darunter Carendin Halgar. Ohne die Formeln und Kanalisierungsmethoden des Buches kann ein unvorbereiteter Beschwörer von dem herbeigerufenen Wesen zerrissen werden."},{t="Der Diebstahl des Kreuzzugs",b="Perrine, ein Agent des Scharlachroten Kreuzzugs, stahl Egalins Zauberfoliant von den Hexenmeistern der Verlassenen und versteckte ihn in einer Truhe in einem Turm im westlichen Tirisfal. Der Kreuzzug hasste dunkle Magie, doch Perrine schien wenig über die wahre Bedeutung des Buches zu wissen. Der Foliant wurde als beschlagnahmtes ketzerisches Beutegut behandelt, bis Initianden der Verlassenen ihn zurückholten, die die Leere meistern wollten."}},faq={{q="Wer war Egalin?",a="Egalin war ein begabter Hexenmeister, der Carendin Halgar unterwies. Er war der Erste unter ihnen, der einen Leerwandler beschwor, und beherrschte Wesen des Chaos mit Leichtigkeit.",al={"wer ist egalin","egalins geschichte","wer schrieb den zauberfolianten"}},{q="Warum ist Egalins Zauberfoliant so gefährlich?",a="Egalins Zauberfoliant enthält die Beschwörungsformeln und Kanalisierungsmethoden, die zur Beschwörung eines Leerwandlers nötig sind. Ein Hexenmeister, der den Ritus versucht, ohne diese Anweisungen zu beherrschen, riskiert, von dem beschworenen Leerenwesen zerrissen zu werden.",al={"was bewirkt der zauberfoliant","gefahr des leerwandlerfolianten","warum gefährlich"}},{q="Wie kam der Scharlachrote Kreuzzug an das Buch?",a="Perrine, ein Agent des Scharlachroten Kreuzzugs, stahl Egalins Zauberfoliant von den Hexenmeistern der Verlassenen. Perrine versteckte ihn in einer Truhe in einem Wachturm des Kreuzzugs im westlichen Tirisfal und schien seinen wahren magischen Wert nicht zu kennen.",al={"wer stahl das buch","perrine zauberfoliant","warum haben die kreuzfahrer ihn"}},{q="Wer braucht diesen Zauberfolianten zurück?",a="Carendin Halgar, der Hexenmeisterlehrer im Tempel der Verdammten unter Unterstadt, braucht den Zauberfolianten, um neue Initianden in der Beschwörung und Bindung von Leerwandlern zu unterweisen.",al={"wer will den zauberfolianten","wer gibt egalins zauberfoliant ab","carendin halgar buch"}}},fx={["29951967"]={q="Woher stammt Egalins Zauberfoliant und wer hat ihn erschaffen?",a="Der Foliant wurde von Egalin verfasst, einem Hexenmeistermeister, der unter den Praktizierenden in der Unterstadt dafür gefeiert wurde, als Erster einen Leerwandler beschworen zu haben. Egalin unterrichtete andere prominente Hexenmeister, darunter Carendin Halgar, die die mühelose Kontrolle ihres Mentors über beschworene Schrecken bewunderten.",al={"wer hat egalins zauberfoliant geschrieben","ursprung von egalins buch","wer hat egalins zauberfoliant erschaffen"}},c5f2fef1={q="Warum wird Egalins Zauberfoliant gesucht?",a="Die Hexenmeister im Tempel der Verdammten benötigen den Folianten, um angehende Praktizierende in der Beschwörung von Leerwandlern zu unterweisen. Nachdem ein Agent des Scharlachroten Kreuzzugs namens Perrine ihn gestohlen und in einem nahegelegenen Turm versteckt hatte, wurde die Bergung des Textes entscheidend, um seine gefährlichen Rituale aus feindlichen Händen fernzuhalten und den Verlassenen lebenswichtiges Wissen zurückzugeben.",al={"warum wird egalins zauberfoliant gesucht","wer will den zauberfolianten","warum egalins buch bergen"}},cc7caae6={q="Was ist Egalins Zauberfoliant?",a="Egalins Zauberfoliant ist ein muffiges, spezialisiertes Zauberbuch, das die Geheimnisse enthält, Wesen aus dem Chaos jenseits zu rufen. Es beschreibt im Detail den komplizierten Prozess und die Zauberstruktur, die erforderlich sind, um einen Leerwandler zu beschwören und zu binden – ein Wesen, das in der Lage ist, einen unvorbereiteten Beschwörer in Stücke zu reißen.",al={"was ist egalins zauberfoliant","egalins buch","was ist der zauberfoliant"}}},fp="17,160,15.337.0,17.369.1,15.152.0,38.221.0,41.216.0,33.161.0"}
P.entries["item:eldritch-shackles"] = {n="Geisterhafte Fesseln",s="Die Geisterhaften Fesseln werden zusammen mit den Shards of Myzrael am Kreis der Inneren Bindung im Arathihochland verwendet. Die Steine bergen eine Macht, die erwacht, wenn die Fesseln angelegt werden.",h="Die Geisterhaften Fesseln werden zusammen mit den Shards of Myzrael am Kreis der Inneren Bindung im...",kw={"arathihochland","kreis der inneren bindung","geisterhafte fesseln","myzrael","shards of myzrael","die prinzessin beschwören"},sec={{t="Bei den Shards",b="Am Kreis der Inneren Bindung werden die Geisterhaften Fesseln zusammen mit den Shards of Myzrael verwendet. Myzrael muss beschworen und besiegt werden, bevor die Fesseln sie erneut binden können."},{t="Ein Heulen aus der Tiefe",b="Als die Fesseln um die Shards gelegt werden, steigt ein unmenschliches Heulen aus weiter Tiefe empor, gefolgt von einem Brüllen. Die Steine pulsieren bedrohlich, und das Wesen unter ihnen scheint der Oberfläche übel gesinnt zu sein."}},faq={{q="Wozu dienen die Geisterhaften Fesseln?",a="Die Geisterhaften Fesseln werden um die Shards of Myzrael gelegt, um Myzrael erneut gefangen zu halten.",al={"wozu dienen fesseln","zweck der geisterhaften fesseln"}},{q="Wo verwende ich die Geisterhaften Fesseln?",a="Die Geisterhaften Fesseln werden bei den Shards of Myzrael am Kreis der Inneren Bindung im Arathihochland verwendet.",al={"wo fesseln verwenden","fundort der fesseln"}},{q="Wer ist Myzrael?",a="Myzrael wird die Prinzessin genannt und unter den Shards of Myzrael gefangen gehalten.",al={"myzrael wer","wer ist die prinzessin"}},{q="Warum muss Myzrael besiegt werden?",a="Myzrael muss besiegt werden, bevor sie genug Macht sammelt, um ihre Bezwinger herauszufordern.",al={"warum myzrael töten","myzrael aufhalten"}},{q="Was geschieht, wenn die Fesseln Myzrael binden?",a="Ein unmenschliches Heulen steigt aus weiter Tiefe empor, gefolgt von einem Brüllen, und die Shards pulsieren bedrohlich.",al={"wirkung der fesseln","was geschieht bei den shards"}}},fp="17,178,13.168.0,12.205.1,35.83.1,37.112.0,15.78.1,29.82.1,44.91.1"}
P.entries["item:electropeller"] = {n="Elektropeller",s="An der Dunkelküste liegen Elektropeller im Süßwasser verstreut, seit ein nächtlicher Ausflug schiefging.",h="An der Dunkelküste liegen Elektropeller im Süßwasser verstreut, seit ein nächtlicher Ausflug schiefging.",kw={"auberdine","der klippenquell","dunkelküste","entenattrappe","elektropeller","electropellers","der wildbend","hexknall kurbeldreh"},ang={["profession:Engineering"]="Für einen Ingenieur zeigt der Elektropeller den Ehrgeiz und die Gefahren gnomischer Ingenieurskunst. Hexknall Kurbeldreh entwarf ihn als Antrieb für eine explodierende Entenattrappe, doch er landete noch vor einem richtigen Test im Fluss.",["race:Gnome"]="Als Gnom erkennt Ihr vielleicht Hexknall Kurbeldrehs kühnen technischen Ehrgeiz wieder. Er bittet vorbeikommende Angler, die Ergebnisse seiner nächtlichen Experimente zu bergen."},sec={{t="Missgeschicke am Flussufer",b="Hexknall Kurbeldreh baute die Elektropeller als Antrieb für eine experimentelle, explodierende Entenattrappe. Der gnomische Erfinder arbeitet von Auberdine aus. Nach zu vielen Drinks erkundete er die Wasserläufe der Dunkelküste und erlitt einen Filmriss. Stunden später erwachte er mit versengtem Haar und einem leeren Rucksack. Seine Elektropeller waren in die Süßwasserströmungen gefallen, wo sie über Flüsse und Seen verstreut bleiben, bis geduldige Angler sie bergen."}},faq={{q="Wofür wird ein Elektropeller verwendet?",a="Hexknall Kurbeldreh entwarf Elektropeller als Antrieb für eine experimentelle, selbstangetriebene, explodierende Entenattrappe, die er an der Dunkelküste entwickelte.",al={"elektropeller zweck","was macht ein elektropeller","warum eine entenattrappe"}},{q="Wie gelangten diese Bauteile in die Flüsse der Dunkelküste?",a="Nach zu vielen Drinks ging Hexknall Kurbeldreh nachts an der Dunkelküste auf Erkundung und erlitt einen Filmriss. Stunden später erwachte er mit versengtem Haar und einem leeren Rucksack. Seine Elektropeller waren in die Süßwasserströmungen gefallen.",al={"warum im wasser","wie gingen elektropeller verloren","kurbeldrehs fehler"}},{q="Wo lassen sich Elektropeller bergen?",a="Angler können Elektropeller aus den Süßgewässern der Dunkelküste bergen, darunter aus dem Klippenquell und dem Wildbend.",al={"wo elektropeller angeln","elektropeller fundorte","angeln im klippenquell"}},{q="Wer möchte diese Bauteile zurückhaben?",a="Hexknall Kurbeldreh, ein Gnom in Auberdine, möchte zwölf Elektropeller zurückhaben, damit er seine Forschungen an der Attrappe fortsetzen kann.",al={"wer braucht elektropeller","wer ist kurbeldreh","auberdine gnom quest"}}},fx={["3f720660"]={q="Was ist ein Elektropeller?",a="Ein Elektropeller ist eine spezialisierte mechanische Antriebskomponente aus der Gnomentechnik. Diese motorisierten Teile sind dazu konzipiert, aquatische Geräte anzutreiben, insbesondere die exzentrischen Erfindungen von Hexknall Kurbeldreh, wie etwa seine motorisierten Entenattrappen.",al={"was ist ein elektropeller","elektropeller gegenstand","was sind elektropellers"}}},fp="13,99,27.427.0,34.139.0,54.213.0,38.126.0,36.118.0"}
P.entries["item:elemental-shard-sample"] = {n="Elemental Shard Sample",s="Elemental Shard Sample trägt Markierungen, die Lotwil Veriatus bei der Untersuchung der Maschinen in der Brennenden Steppe helfen könnten. Es bringt einen Hinweis aus dem Ödland zu einem Gelehrtenlager östlich von Euch.",h="Elemental Shard Sample trägt Markierungen, die Lotwil Veriatus bei der Untersuchung der Maschinen in der...",kw={"brennende steppe","elementarwissenschaften","elementarsplitter","elemental shard sample","g.l.a.","lotwil veriatus","rang iv"},sec={{t="Ein markierter Splitter",b="Die Initialen G.L.A. und eine Rangmarkierung unterscheiden den Splitter von den Maschinen aus der Brennenden Steppe. Elemental Shard Sample erreicht Lotwil Veriatus in seinem Lager im Osten, wo der Gelehrte Elementarwissenschaften studiert. Die Markierung könnte bei der Suche nach den Erbauern der Maschinen helfen."}},faq={{q="Was ist Elemental Shard Sample?",a="Es ist ein Splitter mit den Initialen G.L.A. und einer Rangmarkierung, der einer Maschine in der Brennenden Steppe entnommen wurde.",al={"elementarsplitter","splitterprobe"}},{q="Wofür steht G.L.A.?",a="G.L.A. ist in die Elementarsplitter eingeprägt, doch seine Bedeutung ist hier nicht bekannt.",al={"bedeutung von gla","splitterinitialen"}},{q="Welchen Rang haben die Maschinen?",a="Die in der Brennenden Steppe zerstörten Maschinen tragen Markierungen mit Rang IV, der für einen niedrigen Rang gehalten wird.",al={"rang iv","maschinenrang"}},{q="Wer soll die Probe erhalten?",a="Lotwil Veriatus, ein Gelehrter von einigem Ruf auf dem Gebiet der Elementarwissenschaften, soll die Probe untersuchen.",al={"wer will den splitter","lotwil splitter"}},{q="Wo befindet sich Lotwil Veriatus?",a="Lotwil Veriatus ist in einem Lager östlich von Euch stationiert.",al={"lotwils standort","lager im osten"}},{q="Warum ist die Probe wichtig?",a="Die Markierungen des Splitters könnten Lotwil bei der Suche im Zusammenhang mit den Maschinen in der Brennenden Steppe helfen.",al={"warum der splitter wichtig ist","maschinenhinweis"}}},fp="22,189,14.286.0,35.106.0,22.79.0,27.94.0,30.96.0,25.51.0,27.105.0"}
P.entries["item:elixir-of-pain"] = {n="Elixier der Schmerzen",s="In Tarrens Mühle brauen Apotheker der Verlassenen das Elixier der Schmerzen für gefährliche Versuche. Sie testen biologische Wirkstoffe, die Lady Sylvanas' dunkleren Zielen dienen sollen.",h="In Tarrens Mühle brauen Apotheker der Verlassenen das Elixier der Schmerzen für gefährliche Versuche.",kw={"apotheker","elixier der schmerzen","bauer ray","die felder von hillsbrad","königliche apothekergesellschaft","stanley","sylvanas","tarrens mühle"},ang={["faction:Horde"]="Als Verbündete der Horde könnt Ihr bei diesen düsteren Versuchen die verstörenden Methoden der Forscher von Tarrens Mühle miterleben.",["race:Undead"]="Die skrupellosen Feldversuche der Königlichen Apothekergesellschaft zeigen, dass die Verlassenen bereit sind, jedes nötige Mittel einzusetzen, um chemische Waffen gegen die Lebenden zu entwickeln."},sec={{t="Experimente der Apotheker",b="Die Königliche Apothekergesellschaft sucht nach Formeln, um die Verlassenen gegen ihre sterblichen Nachbarn und die Geißel zu stärken. Das Elixier der Schmerzen ist einer dieser Versuche, hergestellt aus frisch gesammelten Zutaten aus dem Vorgebirge des Hügellands. Seine Schöpfer nehmen kaum Rücksicht auf die lebenden Versuchssubjekte. Sie testen instabile Substanzen, die der Dunklen Fürstin helfen sollen."},{t="Feldversuch an Stanley",b="Die Apotheker wollen einen unauffälligen Versuch durchführen, bevor sie militärische Ressourcen riskieren oder ihre Arbeit den Verteidigern von Hillsbrad offenbaren. Sie verabreichen das Elixier der Schmerzen Stanley, Bauer Rays scheinbar harmlosem Haushund auf dem nördlichen Gehöft der Felder von Hillsbrad. Das Gebräu tötet ihn nicht still und leise. Es verwandelt Stanley in eine rasende, monströse Bestie."}},faq={{q="Welchem Zweck dient das Elixier der Schmerzen?",a="Mit dem Elixier der Schmerzen werden biologische Verbindungen für die Königliche Apothekergesellschaft getestet. Seine Schöpfer hoffen, aus den Mischungen verheerende Gebräue für Lady Sylvanas zu gewinnen und die Vorherrschaft der Verlassenen zu sichern.",al={"warum das elixier der schmerzen herstellen","zweck des elixiers","was bewirkt das elixier"}},{q="Wer ist Stanley?",a="Stanley ist Bauer Rays Haushund auf dem nördlichen Bauernhof der Felder von Hillsbrad. Apotheker der Verlassenen wählen den scheinbar harmlosen Hund als ahnungsloses Versuchssubjekt für ihr neues Elixier aus.",al={"wer ist stanley","bauer rays hund","stanley hund"}},{q="Warum wird das Elixier an Stanley getestet?",a="Apotheker Lydon will sein frisch gemischtes Elixier im Feld testen. Er schickt es zu Bauer Rays kleinem Hund Stanley, um zu sehen, wie das Tier darauf reagiert.",al={"was passiert mit stanley","stirbt stanley","stanleys verwandlung in einen wolf"}},{q="Wo wird das Elixier getestet?",a="Der Versuch findet vor Bauer Rays nördlichem Bauernhaus auf den Feldern von Hillsbrad statt, südwestlich von Tarrens Mühle. Stanley ruht gewöhnlich nahe der Veranda am Eingang.",al={"wohin das elixier bringen","stanleys aufenthaltsort","bauer rays bauernhof"}}},fx={["5a45fd3d"]={q="Was ist das Elixier der Schmerzen?",a="Das Elixier der Schmerzen ist ein experimentelles alchemistisches Gebräu, das für die Kriegsanstrengungen der Verlassenen im Vorgebirge des Hügellands gebraut wurde. Es wird aus frisch geerntetem Blut kombiniert mit flüchtigen Reagenzien hergestellt und dient als frühes Prototyp für die dunklen Seuchen und Toxine, die die Gesellschaft der Königlichen Apotheker für Fürstin Sylvanas Windläufer entwickeln möchte.",al={"was ist das elixier der schmerzen","elixier der schmerzen gegenstand","schmerztrank"}},["52862df0"]={q="Woher stammt das Elixier der Schmerzen und wer hat es hergestellt?",a="Das Elixier wird im Außenposten der Verlassenen, Tarrens Mühle, gebraut. Ein Apotheker mischt frisches Kreaturenblut aus dem umliegenden Vorgebirge mit anderen ätzenden Zutaten, mit der Absicht, eine virulente Waffe zu erschaffen, um die Eroberung der Region durch die Dunkle Fürstin voranzutreiben.",al={"wer hat das elixier der schmerzen hergestellt","erschaffer des elixiers der schmerzen","woher stammt das elixier der schmerzen"}}},fp="14,162,26.333.0,24.335.1,42.192.0,15.178.0,36.146.1,27.151.0"}
P.entries["item:elixir-of-suffering"] = {n="Elixier des Leidens",s="In Tarrens Mühle testet Apotheker Lydon einen neuen Trank für die Royal Apothecary Society. Die Gesellschaft sucht nach einer Seuche, die lebende Menschen und die Geißel töten wird.",h="In Tarrens Mühle testet Apotheker Lydon einen neuen Trank für die Royal Apothecary Society.",kw={"apotheker lydon","elixier des leidens","seuche der verlassenen","vorgebirge des hügellands","royal apothecary society","tarrens mühle","umpi"},ang={["race:Undead"]="In ganz Lordaeron arbeitet die Royal Apothecary Society an einer Waffe, die den Verlassenen ihre Unabhängigkeit von der Geißel und der lebenden Menschheit sichern wird. Lydons Experimente in Tarrens Mühle sind Teil dieser Arbeit."},sec={{t="Experimente des Apothekers",b="Rund um das zerstörte Tarrens Mühle sammelt Apotheker Lydon rohe Reagenzien aus der Wildnis und mischt daraus giftige Tränke. Seine Arbeit folgt dem Auftrag der Royal Apothecary Society, eine Seuche zu entwickeln, die Lebende wie Tote gleichermaßen auslöschen wird. Um ein Gebräu zu testen, gibt Lydon es Umpi, seinem Froschassistenten."}},faq={{q="Welchem Zweck dient das Elixier des Leidens?",a="Apotheker Lydon braut das Elixier als Experiment für die Royal Apothecary Society. Die Gesellschaft sucht nach einer Seuche, um lebende Menschen und die Geißel auszurotten.",al={"warum das elixier des leidens herstellen","was bewirkt das elixier","zweck des elixiers des leidens"}},{q="Wer ist Umpi?",a="Umpi ist ein Frosch, den Apotheker Lydon in Tarrens Mühle hält. Lydon nennt Umpi seinen Assistenten, doch der Frosch dient unwissentlich als Versuchstier für seine frisch gebrauten Gifte.",al={"wer ist der frosch","wer ist die kröte","lydons assistent"}},{q="Was geschieht, wenn Umpi das Elixier trinkt?",a="Als Umpi das Elixier des Leidens trinkt, quakt der Frosch und erliegt fast augenblicklich dem Gift. Der Versuch zeigt, wie tödlich Lydons Gebräu ist.",al={"stirbt umpi","was geschieht mit der kröte"}}},fx={["14f85f3d"]={q="Was ist das Elixier des Leidens?",a="Das Elixier des Leidens ist ein experimentelles Gebräu der Gesellschaft der Königlichen Apotheker in Tarrens Mühle. Dieses tödliche Gemisch wurde als Teil des ständigen Strebens der Verlassenen nach einer neuen Seuche entwickelt, um sowohl Lebenden als auch Untoten qualvolle Schmerzen und den Tod zuzufügen.",al={"was ist das elixier des leidens","hintergrund zum elixier des leidens","was bewirkt das elixier des leidens"}},fa4e475a={q="Woher stammt das Elixier des Leidens und wer hat es hergestellt?",a="Das Elixier wird von Apotheker Lydon gebraut, der in Tarrens Mühle im Vorgebirge des Hügellands stationiert ist. Im Auftrag der Gesellschaft der Königlichen Apotheker und Fürstin Sylvanas Windläufer sammelt Lydon im gesamten Vorgebirge lokale Komponenten, um den tödlichen Trank zu formulieren und zu verfeinern.",al={"wer hat das elixier des leidens hergestellt","erschaffer des elixiers des leidens","woher stammt das elixier des leidens"}},["1d085d8d"]={q="Warum möchte Apotheker Lydon das Elixier des Leidens erschaffen?",a="Apotheker Lydon braut das Elixier, um den großen Plan der Dunklen Fürstin zu erfüllen: eine Waffe zu erschaffen, die mächtig genug ist, um sowohl die Geißel als auch die Menschheit auszurotten. Er testet dessen Tödlichkeit an lokalen Subjekten, um sicherzustellen, dass das Gebräu maximale Qualen und ein schnelles Ende herbeiführt.",al={"warum das elixier des leidens brauen","zweck des elixiers des leidens","warum will lydon das elixier"}}},fp="19,159,26.309.0,47.155.0,12.158.0,41.145.1"}
P.entries["item:elune-s-tear"] = {n="Elunes Träne",s="Im Eschental greifen Heiler der Nachtelfen auf Elunes Träne zurück, wenn Krankheit und Verderbnis gewöhnlichen Heilmitteln widerstehen.",h="Im Eschental greifen Heiler der Nachtelfen auf Elunes Träne zurück, wenn Krankheit und Verderbnis...",kw={"eschental","astranaar","heilmittel","elunes träne","irissee","orendil","pelturas","relara"},ang={["class:Priest"]="Als Priester erkennt Ihr die Macht des Steins, Schatten und Fäulnis zu tilgen. Seine Heilkraft spiegelt die heilenden Wunder wider, die der Priesthood of Elune zugeschrieben werden.",["race:NightElf"]="Als Nachtelf kennt Ihr Relikte, die Elunes Namen tragen, als heilige Gaben. Die Macht des Steins, ein unschuldiges Kind zu retten, spiegelt die Verbundenheit der Kaldorei mit der heilenden Gnade der Moon Mother wider."},sec={{t="Ein heiliger Reinigungsstein",b="Auf einem kleinen Eiland im Irissee, östlich von Astranaar, ruht ein Stein, den die Nachtelfen heilig halten. Sie glauben, dass er die Reinheit der Mondgöttin in sich trägt. Verderbnis hat den See grün gefärbt, und entstellte Moormonster streifen an seinen Ufern umher. Örtliche Kräuterkundige und Heiler, darunter Orendil Rundblatt, suchen den Stein, wenn Umschläge aus Waldkräutern tief sitzende Verderbnis nicht läutern können."},{t="Ein verzweifeltes Heilmittel",b="Relara Whitemoon, eine junge Nachtelfe in Astranaar, siecht an einer geheimnisvollen Krankheit dahin. Ihr Vater Pelturas hat jede gewöhnliche Arznei versucht, die er finden konnte. Auf den Rat des Apothekers Orendil hin sucht Pelturas Elunes Träne, um daraus einen stärkenden Eintopf zu brauen. Der Stein schenkt unmittelbare Hoffnung, doch die hartnäckige Verderbnis des Eschentals erfordert oft mächtigere Riten der Läuterung."}},faq={{q="Was ist Elunes Träne?",a="Elunes Träne ist ein seltenes magisches Mineral auf einer Insel im Irissee im Eschental. Die Nachtelfen halten sie als Elune geweihten Stein heilig und nutzen sie, um unnatürliche Verderbnis und tödliche Krankheiten zu heilen.",al={"elunes träne","was ist dieser stein","was bewirkt elunes träne"}},{q="Wo lässt sich Elunes Träne finden?",a="Elunes Träne liegt auf der Insel mitten im Irissee, östlich von Astranaar im Herzen des Eschentals. Folgt von der Hauptstraße aus dem Pfad am Bach nach Norden, um dorthin zu gelangen.",al={"wo ist elunes träne","fundort stein irissee","elunes träne finden"}},{q="Warum braucht Pelturas Weißmond die Träne?",a="Pelturas sucht Elunes Träne, um seiner kranken Tochter Relara zu helfen. Als gewöhnliche Kräuterheilmittel gegen ihre seltsame Krankheit versagen, rät ihm Apotheker Orendil, die stärkende Kraft des Steins zu nutzen.",al={"warum will pelturas sie","relara heilen","wer braucht elunes träne"}},{q="Was bewacht den Stein am Irissee?",a="Entstellte Moormonster streifen an den Ufern des Irissees umher, dessen Wasser sich durch die ausbreitende Verderbnis des Eschentals grün gefärbt hat.",al={"gegner am irissee","was schützt elunes träne"}}},fp="12,104,24.355.0,18.370.1,21.176.0,32.160.0,42.195.0,35.119.0"}
P.entries["item:elven-gem"] = {n="Elven Gem",s="Elven Gems sind verkalkte Steine, die nahe Faldir’s Cove auf dem Meeresboden liegen. Doktor Draxlegauges Brille hilft Euch, sie für Captain O’Breens Suche nach verlorenem Schatz zu finden.",h="Elven Gems sind verkalkte Steine, die nahe Faldir’s Cove auf dem Meeresboden liegen.",kw={"verkalkte elven gems","captain o'breen","doktor draxlegauge","elven gem","elven gems","die faldirbucht","edelsteinjagdschutzbrille","versunkener schatz"},sec={{t="Steine in der Tiefe",b="Das Meer hat den Schatz so lange bedeckt, dass seine Edelsteine in dickem Gestein eingeschlossen und hart geworden sind. Nahe Faldir’s Cove leiht Euch Doktor Draxlegauge seine Edelsteinjagdschutzbrille, damit Ihr sie findet. Er bittet Euch, zehn Elven Gems für Captain O’Breen zu sammeln und die Brille anschließend zurückzubringen."}},faq={{q="Woher stammen Elven Gems?",a="Elven Gems liegen nahe Faldir’s Cove auf dem Meeresboden, eingeschlossen in verkalktem Gestein.",al={"elven gems finden","herkunft der elven gems"}},{q="Warum sind die Edelsteine verkalkt?",a="Der Schatz liegt schon so lange auf dem Meeresboden, dass die Edelsteine zu dickem Gestein verkalkt sind.",al={"warum steinerne edelsteine","warum verkalkte edelsteine"}},{q="Wer möchte die Elven Gems haben?",a="Doktor Draxlegauge bittet Euch, zehn Elven Gems für Captain O’Breens Suche nach verlorenem Schatz zu sammeln.",al={"wer braucht edelsteine","captain obreen und edelsteine"}},{q="Wie findet Ihr die Edelsteine?",a="Doktor Draxlegauge leiht Euch die Edelsteinjagdschutzbrille, mit der Ihr die verkalkten Edelsteine aufspüren könnt.",al={"edelsteine finden","funktion der brille"}},{q="Wer ist Doktor Draxlegauge?",a="Doktor Draxlegauge ist ein Gnom in Faldir’s Cove, der Euch seine Edelsteinsuchbrille leiht. Er bleibt lieber auf sicherem, trockenem Land.",al={"draxlegauge","wer ist der doktor"}}},fp="9,178,12.269.0,30.80.0,27.95.0,25.105.0,25.98.0,26.125.0"}
P.entries["item:elven-gems"] = {n="Elven Gems",s="Elven Gems sind Schätze aus einem gesunkenen Schiff im Arathihochland. Captain O'Breen wartet darauf, sie zu begutachten.",h="Elven Gems sind Schätze aus einem gesunkenen Schiff im Arathihochland.",kw={"arathihochland","captain o'breen","elven gems","piraten","professor","versunkener schatz"},sec={{t="Der Schatz eines Piraten",b="Der Professor und der Sprecher haben wochenlang unter Captain O'Breens Piraten gelebt. Nun fürchten sie, mit dem Schatz erwischt zu werden, und schicken Euch, die Elven Gems zum Captain zu bringen. O'Breen wartet auf der Brücke."}},faq={{q="Was sind die Elven Gems?",a="Es sind Schätze aus einem gesunkenen Schiff, die Captain O'Breen begutachten soll.",al={"elven gems","welche edelsteine","edelsteinschatz"}},{q="Wer will die Elven Gems?",a="Captain O'Breen möchte die Elven Gems mit eigenen Augen sehen.",al={"wer will edelsteine","edelsteine für captain obreen","wohin edelsteine bringen"}},{q="Warum trage ich die Edelsteine?",a="Der Professor und der Sprecher fürchten, mit dem Schatz der Piraten erwischt zu werden, und schicken Euch zu Captain O'Breen.",al={"warum edelsteine bringen","warum ich","zweck der edelsteine"}},{q="Wohin soll ich die Elven Gems bringen?",a="Bringt die Elven Gems zu Captain O'Breen auf der Brücke.",al={"fundort der edelsteine","wohin mit den edelsteinen","brücke des captains"}}},fp="10,119,19.216.0,24.90.0,25.54.0,27.115.0,31.53.0"}
P.entries["item:embalming-ichor"] = {n="Einbalsamierungssekret",s="Im nördlichen Tirisfal tragen Rot Hide-Gnolle eine Flüssigkeit in sich, die ihre verwesenden Körper konserviert. Die Apotheker der Verlassenen wollen sie erforschen, um sie gegen die Geißel einzusetzen.",h="Im nördlichen Tirisfal tragen Rot Hide-Gnolle eine Flüssigkeit in sich, die ihre verwesenden Körper...",kw={"apotheker","brill","einbalsamierungssekret","garrens schlupfwinkel","grabräuber","magistrat sevren","massengräber","rot hide"},ang={["profession:Herbalism"]="Als Kräuterkundige könnte Euch die Konservierungsflüssigkeit im Inneren der Rot Hides interessieren. Sie bietet einen Forschungsgegenstand für das Studium finsterer alchemistischer Methoden und der Reagenzien der Seuche.",["race:Undead"]="Als Verlassene verwehrt Ihr der Geißel frische Leichen aus den Massengräbern. Ihr helft, Tirisfal zu schützen, und sichert Rohstoffe für Euer eigenes Überleben."},sec={{t="Unnatürliche Konservierung",b="In Garrens Schlupfwinkel und den nahen Massengräbern graben Rot Hide-Gnolle Seuchenopfer für die Geißel aus. Sie sind verrottende Knechte, ausgesandt, um den Schergen des Lichkönigs zu dienen.\n\nEinbalsamierungssekret fließt durch ihre verwesten Adern. Es konserviert ihr Fleisch und erhält ihr Untotendasein aufrecht. Magistrat Sevren in Brill will Phiolen von den Grabräubern beschaffen lassen, damit die Königliche Apothekervereinigung frische Proben untersuchen und Wege finden kann, die Flüssigkeit gegen die Geißel einzusetzen."}},faq={{q="Was ist Einbalsamierungssekret?",a="Rot Hide-Gnolle in Tirisfal tragen Einbalsamierungssekret in ihren belebten Körpern. Die Flüssigkeit konserviert ihr verrottendes Fleisch und erhält ihr Untotendasein im Dienst der Geißel aufrecht.",al={"einbalsamierungssekret","was ist sekret","gnollflüssigkeit"}},{q="Wer lässt dieses Sekret sammeln?",a="Magistrat Sevren in Brill befiehlt den Streitern der Verlassenen, Sekret von getöteten Rot Hides zu sammeln, damit die Königliche Apothekervereinigung es untersuchen kann.",al={"wer braucht einbalsamierungssekret","magistrat sevren sekret","wer will sekret"}},{q="Warum graben die Rot Hide-Gnolle Gräber aus?",a="Die Geißel schickt Rot Hide-Gnolle aus, um Seuchenopfer in den nördlichen Massengräbern nahe Garrens Schlupfwinkel auszugraben. Die Geißel sucht Leichen, um ihre Reihen zu verstärken.",al={"warum plündern gnolle gräber","massengräber tirisfal","verbindung zwischen gnollen und geißel"}},{q="Was haben die Verlassenen mit der Flüssigkeit vor?",a="Die Apotheker in Unterstadt untersuchen das Sekret auf Möglichkeiten, der Geißel entgegenzuwirken, und auf neue alchemistische Formeln.",al={"was macht sevren mit sekret","apotheker erforschen sekret","verwendung von einbalsamierungssekret"}}},fx={e6b7bf5e={q="Woher stammt das Einbalsamierungssekret und wer hat es hergestellt?",a="Einbalsamierungssekret wird von den Rotpelzgnollen geerntet, die im Massengrab und in Garrens Schlupfwinkel in Tirisfal spuken. Es ist die abscheuliche, unnatürliche Flüssigkeit, die von der Geißel verwendet wird, um diese untoten Gnoll-Diener zu beleben und zu konservieren, wodurch das Pseudoleben erhalten bleibt, das sie dazu antreibt, Leichen für die Armeen ihrer Meister auszugraben.",al={"ursprung von einbalsamierungssekret","wer hat einbalsamierungssekret hergestellt","woher kommt das sekret"}}},fp="15,153,22.452.0,24.165.0,31.133.0,46.154.0,47.114.0"}
P.entries["item:emerald-dreamcatcher"] = {n="Smaragdgrüner Traumfänger",s="In Sternenhauch liegt der Smaragdgrüne Traumfänger vergessen, seit die Gnarlpine-Furbolgs die Bewohner vertrieben haben. Druiden der Grabhügel von Ban'ethil gaben Tallonkai Flinkwurzel das Amulett in der Hoffnung, es würde Lebenskraft aus dem Smaragdgrünen Traum schöpfen.",h="In Sternenhauch liegt der Smaragdgrüne Traumfänger vergessen, seit die Gnarlpine-Furbolgs die Bewohner...",kw={"grabhügel von ban'ethil","dolanaar","smaragdgrüner traumfänger","furbolg","gaerolas talvethren","sternenhauch","tallonkai flinkwurzel","teldrassil"},ang={["class:Druid"]="Als Druide könnt Ihr erkennen, wie das Amulett die schlafenden Druiden der Grabhügel von Ban'ethil mit den Siedlungen der Kaldorei unter ihnen verbindet. Durch ihre Verbundenheit mit dem Smaragdgrünen Traum bringen sie diesen Siedlungen Hilfe.",["race:NightElf"]="Als Nachtelf ist die Bergung des Relikts für Euch ein kleiner Sieg gegen die um sich greifende Krankheit in Sternenhauch und den umliegenden Ästen Teldrassils."},sec={{t="Ein Geschenk aus Ban'ethil",b="Gaerolas Talvethren, der druidische Wächter der Grabhügel von Ban'ethil, beaufsichtigte die Herstellung des Smaragdgrünen Traumfängers. Die Druiden gaben dieses verzauberte Amulett nur wenigen Auserwählten. Es schöpft Energie aus dem Smaragdgrünen Traum und bringt seinem Träger Glück und Schutz. Als wahnsinnige Gnarlpine-Furbolgs Sternenhauch überrannten, blieb das Amulett in einer Kommode zurück, mitten in feindseligem, verdorbenem Gebiet."}},faq={{q="Was bewirkt der Smaragdgrüne Traumfänger?",a="Tallonkai Flinkwurzel sagt, das Amulett schöpfe rohe Energie aus dem Smaragdgrünen Traum. Es bringt jedem, der es besitzt, Glück und Lebenskraft, und die Druiden des Cenarius betrachten es als seltenes Zeichen der Gunst.",al={"kräfte des smaragdgrünen traumfängers","wozu dient der traumfänger","geschichte des traumfängers"}},{q="Wer hat den Smaragdgrünen Traumfänger hergestellt?",a="Gaerolas Talvethren, der Druidenwächter, der über den schlafenden Zirkel des Cenarius in den Grabhügeln von Ban'ethil wacht, gab Tallonkai den Smaragdgrünen Traumfänger.",al={"wer hat den traumfänger hergestellt","wer gab tallonkai den traumfänger"}},{q="Warum blieb der Traumfänger in Sternenhauch zurück?",a="Tallonkai bewahrte das Amulett in seiner Kommode in Sternenhauch auf. Als die Verderbnis die örtlichen Gnarlpine-Furbolgs erfasste und gewalttätig machte, musste die Siedlung aufgegeben werden, bevor er es holen konnte.",al={"warum ließ tallonkai ihn zurück","wo ging der traumfänger verloren"}},{q="Warum sind die Furbolgs in Sternenhauch feindselig?",a="Der Stamm der Gnarlpine ist überall auf Teldrassil einer dunklen, sich ausbreitenden Verderbnis verfallen. Sie versetzt den Stamm in einen aggressiven Blutrausch und zwingt Nachtelfen, aus abgelegenen Siedlungen wie Sternenhauch zu fliehen.",al={"warum fiel sternenhauch","furbolgs in sternenhauch"}}},fx={["54ca5db1"]={q="Warum möchte Tallonkai Flinkwurzel den Smaragdgrünen Traumfänger zurück?",a="Tallonkai Flinkwurzel musste das Amulett in seiner Kommode zurücklassen, als die Gnarlpine-Furbolgs der Verderbnis anheimfielen und Sternenhauch überrannten. Über seine spirituelle Kraft hinaus, Glück aus dem Smaragdgrünen Traum zu ziehen, besitzt der Talisman für ihn als seltenes Geschenk von Gaerolas Talvethren, dem Wächter des Grabhügels von Ban'ethil, große persönliche Bedeutung.",al={"warum will tallonkai den traumfänger","warum traumfänger bergen","warum ist der traumfänger wichtig"}},a335891d={q="Was ist der Smaragdgrüne Traumfänger?",a="Der Smaragdgrüne Traumfänger ist ein seltenes, mächtiges verzaubertes Amulett, gefertigt von den Druiden Teldrassils. Er kann seine Kraft direkt aus dem Smaragdgrünen Traum schöpfen und bündelt lindernde Naturmagie, die seinem Träger Glück und Klarheit schenkt. Tallonkai Flinkwurzel aus Dolanaar betrachtet ihn als kostbares persönliches Geschenk, das nur wenigen Auserwählten zuteilwird.",al={"was ist der smaragdgrüne traumfänger","smaragdgrüner traumfänger gegenstand","was für ein gegenstand ist der traumfänger"}}},fp="20,238,21.399.0,38.189.0,34.151.0,59.204.0,51.197.0"}
P.entries["item:empty-blue-waterskin"] = {n="Leerer blauer Wasserschlauch",s="Brine schickt den Leeren blauen Wasserschlauch vom Brachland nach Norden, um heiliges Wasser zu sammeln. Die Flüssigkeit hilft ihr, den Trank zuzubereiten, der benötigt wird, um den Wassergeist zu beschwören und zu besänftigen.",h="Brine schickt den Leeren blauen Wasserschlauch vom Brachland nach Norden, um heiliges Wasser zu sammeln.",kw={"eschental","brachland","brine","call of water","leerer blauer wasserschlauch","die sternenstaubruinen","wassertotem"},ang={["class:Shaman"]="Als Schamane tragt und füllt Ihr den Wasserschlauch als entscheidenden Schritt auf dem Weg zur Beherrschung der Wassergeister. Seine reine Flüssigkeit wird benötigt, um Euer dauerhaftes Wassertotem herzustellen.",["faction:Horde"]="Als Mitglied der Horde müsst Ihr aus dem Brachland in feindliches Nachtelfengebiet im westlichen Eschental reisen, um das Wasser zu holen."},sec={{t="Ein heiliges Gefäß",b="Brine gibt einem Schamaneninitianden den Leeren blauen Wasserschlauch bei ihrer Hütte auf einem Hügel im südlichen Brachland. Das Gefäß steht für die letzte und gefährlichste Sammelaufgabe der frühen Ausbildung. Um mit dem Geist des Wassers Zwiesprache zu halten, muss der Initiand reine, ungestörte Quellen in ganz Kalimdor aufsuchen. Der Wasserschlauch ist für einen abgelegenen Brunnen tief in den Sternenstaubruinen bestimmt, in den umkämpften Grenzgebieten von Eschental."},{t="Der Brunnen im Wald",b="Der Initiand muss die Sicherheit des Hordengebiets verlassen und in uralte Haine reisen, die von Naturbestien und Nachtelfen bewacht werden. An einem Brunnen im verfallenen Heiligtum tief in den Sternenstaubruinen wird der Wasserschlauch gefüllt und zu einem Vollen blauen Wasserschlauch. Zusammen mit Wasserproben aus dem Brachland und Tarrens Mühle ermöglicht sein Inhalt Brine, den Trank zur Beschwörung und Besänftigung des Elementargeistes des Wassers zu brauen."}},faq={{q="Wofür wird der Leere blaue Wasserschlauch verwendet?",a="Der Leere blaue Wasserschlauch bringt Wasser aus dem Brunnen tief in den Sternenstaubruinen in Eschental zurück zu Brine. Sie verwendet es, um einen Trank aus reinem Wasser zu brauen.",al={"was bewirkt der leere blaue wasserschlauch","leerer blauer wasserschlauch verwendung","warum habe ich den leeren blauen wasserschlauch"}},{q="Wer gibt Euch diesen Wasserschlauch?",a="Brine gibt Euch den Wasserschlauch bei ihrer Hütte im südlichen Brachland, südlich von Camp Taurajo nahe der Grenze zu Razorfen.",al={"wer gibt den leeren blauen wasserschlauch","wo bekommt man den blauen wasserschlauch"}},{q="Wo muss der Wasserschlauch gefüllt werden?",a="Füllt ihn am zentralen Brunnen tief in den Sternenstaubruinen im südwestlichen Eschental, gleich hinter Lake Mystral nahe dem Gebirgskamm des Steinkrallengebirges.",al={"wo den leeren blauen wasserschlauch füllen","blauer wasserschlauch fundort","wo fülle ich ihn"}},{q="Warum braucht Brine Wasser aus Eschental?",a="Brine möchte ein Fläschchen mit dem reinsten Wasser herstellen, das auf Kalimdor bekannt ist. Die unberührten heiligen Quellen der Nachtelfenruinen liefern die makellose letzte Zutat für die Zwiesprache mit den Elementargeistern des Wassers.",al={"warum wasser aus eschental","warum wasser aus den sternenstaubruinen"}}},fx={["6fa6361d"]={q="Was ist der leere blaue Wasserschlauch?",a="Der leere blaue Wasserschlauch ist ein rituelles Gefäß, das Schamanenlehrlingen während ihrer Prüfungen anvertraut wird. Er wurde vom Einsiedler Brine im südlichen Brachland gegeben und ist so gestaltet, dass er unberührtes Wasser von heiligen Orten sicher sammeln und transportieren kann, ohne dessen spirituelle Kraft zu korrumpieren.",al={"leerer blauer wasserschlauch","was ist der blaue wasserschlauch","zweck des blauen wasserschlauchs"}}},fp="20,175,15.406.0,19.413.0,42.163.0,29.113.0,35.152.0,41.209.0"}
P.entries["item:empty-brown-waterskin"] = {n="Leerer brauner Wasserschlauch",s="Brine gibt einem Schamanenlehrling im Brachland einen leeren Wasserschlauch.",h="Brine gibt einem Schamanenlehrling im Brachland einen leeren Wasserschlauch.",kw={"brachland","brine","call of water","quilboar","sapta","schamane","wasserschlauch"},ang={["class:Shaman"]="Als Schamane ist das Tragen dieses Wasserschlauchs ein Übergangsritus auf dem Weg zu Eurem Wassertotem. Es zeigt das Gleichgewicht zwischen der Ehrfurcht vor den Elementen und dem harten Kampf ums Überleben."},sec={{t="Eine Lektion in Knappheit",b="Brine gibt dem Schamanenlehrling einen leeren Lederschlauch für die erste Prüfung des Call of Water. Der Lehrling trägt ihn zum Wasserloch unter ihrer Behausung und kehrt dann mit dem gefüllten Schlauch zurück. Einheimische Quilboar bewachen das Becken und schätzen sein Wasser. Wasser ist im Brachland knapp, daher kann selbst eine kleine Oase Leben erhalten und Gewalt entfachen."}},faq={{q="Wofür wird der Leere braune Wasserschlauch verwendet?",a="Schamanenlehrlinge schöpfen Wasser aus dem natürlichen Teich unter Brines Hütte im Brachland. Gefüllt wird der Schlauch benötigt, um elementares Sapta zuzubereiten.",al={"wasserschlauch zweck","was bewirkt der braune wasserschlauch","verwendung des leeren braunen wasserschlauchs"}},{q="Wer stellt diesen Wasserschlauch bereit?",a="Brine, eine Einsiedlerin im Südlichen Brachland, gibt den Wasserschlauch Schamanen, die ihre elementare Pilgerreise antreten, um mit den Geistern des Wassers Zwiesprache zu halten.",al={"wer gibt den wasserschlauch","brauner wasserschlauch questgeber","wo gibt es den leeren wasserschlauch"}},{q="Warum verteidigen die Quilboar die Wasserquelle?",a="Im gesamten Brachland regnet es selten, und Wasser ist knapp. Für die Quilboar bedeutet selbst ein kleines Wasserloch Reichtum und Überleben, daher bewachen sie es und greifen jeden an, der daraus schöpft.",al={"warum greifen quilboar an","quilboar wasser","warum wird das becken bewacht"}},{q="Was geschieht, sobald der Schlauch gefüllt ist?",a="In die Oase unter Brines Hügel getaucht, wird der Schlauch zu einem Vollen braunen Wasserschlauch. Wenn Ihr ihn Brine zurückbringt, kann sie Euer Verständnis für das Gleichgewicht der Natur prüfen, bevor sie Euch für seltenere Gewässer um die Welt schickt.",al={"was tun nach dem füllen","wasserschlauch abgeben","vollen braunen wasserschlauch abgeben"}}},fx={["805e4eda"]={q="Was ist der leere braune Wasserschlauch?",a="Der leere braune Wasserschlauch ist ein einfaches Gefäß, das angehenden Schamanen vom Einsiedler Brine im südlichen Brachland gegeben wird. Er dient als Lehrmittel auf dem Weg zur Kommunikation mit den Geistern des Wassers. Um die Water Sapta zu verdienen, müsst Ihr dieses Gefäß zu einem nahegelegenen Wasserloch bringen, das von wilden Stachelebern bewacht wird, und es mit reiner Flüssigkeit füllen, während Ihr beobachtet, wie sich Leben und Konflikt auf den ariden Ebenen um das knappe Nass drehen.",al={"was ist der leere braune wasserschlauch","hintergrund zum leeren braunen wasserschlauch","brauner wasserschlauch"}}},fp="21,67,20.333.0,43.140.0,28.148.0,48.184.0,37.217.0"}
P.entries["item:empty-cleansing-bowl"] = {n="Leere Säuberungsschale",s="In Auberdine trägt die Leere Säuberungsschale Mondbrunnenwasser gegen die Verderbnis der Blackwood. Mit Nahrungsproben vermischt, ergibt das Wasser eine Mahlzeit, die den dämonischen Einfluss der Satyrn auf die Furbolgs kurzzeitig bricht.",h="In Auberdine trägt die Leere Säuberungsschale Mondbrunnenwasser gegen die Verderbnis der Blackwood.",kw={"auberdine","blackwood","säuberungsschale","dunkelküste","leere säuberungsschale","mondbrunnen","thundris windweaver","xabraxxis"},ang={["class:Druid"]="Als Druide nutzt Ihr Mondbrunnenwasser, um unnatürliche Leiden zu brechen. Das entspricht Eurer Berufung, das verletzte Gleichgewicht der Natur in der gesamten Dunkelküste wiederherzustellen.",["race:NightElf"]="Als Nachtelf seht Ihr, wie Elunes Mondbrunnen dämonische Verderbnis aufheben können. Die Reinigung lässt hoffen, dass Eure alten Verbündeten, die Furbolgs, gerettet werden können."},sec={{t="Ein Gefäß der Reinigung",b="In Auberdine gibt Thundris Windwirker Abenteurern die Leere Säuberungsschale, um heiliges Wasser aus dem örtlichen Mondbrunnen zu holen. Die Nachtelfen haben erfahren, dass Satyrn verzauberte Talismane nutzen, um die nördlichen Blackwood-Furbolgs in dämonischen Wahnsinn zu treiben. Taucht die Schale in den Mondbrunnen und vermischt dann ihr Wasser mit Nüssen, Getreide und Früchten, die Ihr bei den Furbolgs gesammelt habt. Die gesegnete Mahlzeit gibt den betroffenen Kreaturen kurzzeitig den Verstand zurück und enthüllt den Satyraufseher hinter ihrem Wahnsinn."}},faq={{q="Was mache ich mit der Leeren Säuberungsschale?",a="Bringt die Schale zum Mondbrunnen von Auberdine und taucht sie in das gesegnete Wasser, um eine Gefüllte Säuberungsschale zu erhalten. Sammelt dann Getreide-, Nuss- und Fruchtproben im nördlichen Lager der Blackwood-Furbolgs, um sie mit dem Wasser zu vermischen.",al={"leere säuberungsschale verwendung","wie leere säuberungsschale benutzen","wo säuberungsschale füllen"}},{q="Warum brauchen die Nachtelfen diese Schale im Kampf gegen die Verderbnis der Furbolgs?",a="Die Talismane der Satyrn binden die Blackwood-Furbolgs mit dunkler Magie. Thundris Windwirker nutzt die Schale für eine geweihte Mischung, die ihre Raserei kurzzeitig bricht und ihren verborgenen Gebieter Xabraxxis hervorlockt.",al={"warum säuberungsschale","säuberungsschale zweck"}},{q="Wer stellt die Leere Säuberungsschale bereit?",a="Thundris Windwirker, ein Nachtelfengelehrter in Auberdine, gibt Euch die Schale, wenn er Euch bittet, die Quelle der Verderbnis der Blackwood entlang des Klippenquells aufzudecken.",al={"wer gibt säuberungsschale","säuberungsschale questgeber"}},{q="Was geschieht, sobald die Mischung zubereitet ist?",a="Stellt die zubereitete Mischung beim Freudenfeuer des nördlichen Lagers ab. Sie reinigt die Furbolgs in der Nähe lange genug, um Xabraxxis' Zorn zu wecken, sodass Ihr den Satyr erschlagen und seinen Talisman der Verderbnis erbeuten könnt.",al={"säuberungsschale freudenfeuer","säuberungsschale aufstellen"}}},fx={["2a179129"]={q="Was ist die leere Säuberungsschale?",a="Die leere Säuberungsschale ist ein rituelles Gefäß, das Euch von Thundris Windwirker in Auberdine anvertraut wird. Sie wurde dazu erschaffen, die geheiligten Wasser eines Mondbrunnens zusammen mit wilden Lebensmitteln aufzunehmen, und dient als wesentliche Komponente für die Zubereitung eines reinigenden Opfers, das die dämonische Verderbnis aufheben kann, von der die lokale Tierwelt und die Furbolgs befallen sind.",al={"was ist die leere säuberungsschale","hintergrund zur säuberungsschale","zweck der leeren säuberungsschale"}}},fp="20,209,24.479.0,43.211.0,70.206.1,38.169.0,42.193.1"}
P.entries["item:empty-cliffspring-falls-sampler"] = {n="Leere Probe der Klippenquellfälle",s="Bei Cliffspring Falls an der Dunkelküste sammeln junge Druiden Wasser, um ein Gift zu untersuchen, das die örtliche Tierwelt tötet. Der Zirkel des Cenarius gibt ihnen leere Probefläschchen für Wasser vom Höhleneingang.",h="Bei Cliffspring Falls an der Dunkelküste sammeln junge Druiden Wasser, um ein Gift zu untersuchen, das die...",kw={"alanndarian nachtweise","zirkel des cenarius","cliffspring falls","cure poison","dunkelküste","dendrite sternenschauer","probefläschchen"},ang={["class:Druid"]="Als Druide sammelt Ihr als Initiationsritus Wasser bei der von Naga besetzten Höhle und erlernt anschließend Cure Poison.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Naga die Tierwelt und Auberdine bedrohen, indem sie das Wasser in den Wäldern der Dunkelküste verseuchen."},sec={{t="Den verseuchten Wassern nachspüren",b="Cliffspring Falls versorgt die nördliche Dunkelküste mit Wasser. Gift im Quellgebiet gefährdet die örtliche Tierwelt. Als ein zehrendes Gift die Hirsche der Region zu töten begann, gab Dendrite Sternenschauer vom Zirkel des Cenarius jungen Druiden aus Mondlichtung leere Probefläschchen. Sie müssen an einem Höhleneingang bei den Wasserfällen Wasser sammeln, wo es von feindseligen Naga wimmelt."},{t="Ein Rezept zur Heilung",b="Alanndarian Nachtweise nimmt das gefüllte Probefläschchen in Auberdine entgegen. Das verschmutzte Wasser bestätigt, dass üble Wirkstoffe das Grundwasser vergiften. Durch die Untersuchung der Verunreinigung können Alanndarian und die Druiden des Cenarius ein Gegengift entwickeln. Sie können dem Novizen auch grundlegende druidische Heilriten beibringen."}},faq={{q="Wozu dient dieses Probefläschchen?",a="Druiden nutzen das leere Probefläschchen, um verseuchtes Wasser vom Höhleneingang bei Cliffspring Falls an der Dunkelküste zu sammeln. Die Probe hilft den Kräuterkundigen des Cenarius, das Gift zu bestimmen, das die örtliche Tierwelt befällt, und ein Gegenmittel zu finden.",al={"probefläschchen verwendung","wozu dient das cliffspring-probefläschchen","leeres probefläschchen zweck"}},{q="Wo wird die Wasserprobe entnommen?",a="Das Wasser wird am Eingang der Höhle nahe Cliffspring Falls gesammelt, hoch in den nordöstlichen Hügeln der Dunkelküste. Am Eingang wimmelt es von feindseligen Naga.",al={"wo probefläschchen füllen","cliffspring-probefläschchen fundort","füllstelle für probefläschchen"}},{q="Wer erhält den gefüllten Behälter?",a="Das gefüllte Probefläschchen geht an Alanndarian Nachtweise in Auberdine. Sie ist eine nachtelfische Heilerin und vertritt dort den Zirkel des Cenarius.",al={"wer erhält das gefüllte probefläschchen","wo probefläschchen abgeben","alanndarian probefläschchen"}},{q="Warum werden bei Cliffspring Falls Proben genommen statt an anderen Flüssen?",a="Cliffspring Falls ist die Hauptsüßwasserquelle für die nördliche Dunkelküste. Dendrite Sternenschauer führte die Krankheit, die die Hirsche der Region tötet, auf dieses Quellgebiet zurück, weshalb eine direkte Probe zur Entwicklung eines Heilmittels nötig ist.",al={"warum cliffspring falls","was vergiftet die dunkelküste","cliffspring gift"}}},fx={["0413bdcd"]={q="Was ist die leere Probe der Klippenquellfälle?",a="Es ist ein spezialisiertes Gefäß, das Druiden des Zirkels des Cenarius zur Verfügung gestellt wird, um eine unkontaminierte Wasserprobe von den Cliffspring Falls in der Dunkelküste zu entnehmen. Da man annimmt, dass die Wasserfälle verseucht sind, ist ein steriler, dafür vorgesehener Behälter unerlässlich, um die toxische Flüssigkeit zu untersuchen, ohne die Probe zu kontaminieren oder den Träger zu schädigen.",al={"was ist die probe der klippenquellfälle","gegenstand klippenquell-probe"}},dccecdc8={q="Woher stammt die leere Probe der Klippenquellfälle und wer hat sie hergestellt?",a="Die Probe wird von den Druiden des Zirkels des Cenarius in der Mondlichtung bereitgestellt, speziell durch Dendrite Sternenschauer. Da der Zirkel spürte, dass etwas Unnatürliches begann, die Tierwelt der Dunkelküste zu vergiften, bereiteten sie diese Behälter vor, damit vertrauenswürdige Lehrlinge reine Proben direkt von den vermuteten Kontaminationsstellen sichern können.",al={"wer gab mir die klippenquell-probe","wer hat die probe hergestellt","ursprung der probe"}}},fp="31,185,32.333.0,19.295.1,36.199.0,32.147.0,34.125.0,63.208.0"}
P.entries["item:empty-dreadmist-peak-sampler"] = {n="Leere Glutnebelgipfelprobe",s="Am Glutnebelgipfel sammeln Druiden Wasser aus einem verseuchten Teich, um herauszufinden, was die Tiere im nördlichen Brachland krank macht. Die Probe könnte Tonga Runentotem helfen, ein Heilmittel zu finden.",h="Am Glutnebelgipfel sammeln Druiden Wasser aus einem verseuchten Teich, um herauszufinden, was die Tiere im...",kw={"brachland","burning blade","dendrite sternenschauer","glutnebelgipfel","leere glutnebelgipfelprobe","the principal source","tonga runentotem"},ang={["class:Druid"]="Als Druide sammelt Ihr mit diesem Gefäß eine Probe und lernt, Vergiftungen zu heilen, Leiden in der Wildnis zu erkennen und zu lindern.",["faction:Horde"]="Als Mitglied der Horde tragt Ihr dieses Probengefäß, um Tonga Runentotem im Wegekreuz zu helfen, den ökologischen Verfall in den Ebenen des nördlichen Brachlands aufzuhalten."},sec={{t="Der Fäulnis auf der Spur",b="Dendrite Sternenschauer vermutet, dass die Teiche auf dem Glutnebelgipfel mit einer Krankheit zusammenhängen, die Gazellen befällt und das nördliche Brachland heimsucht. Die Teiche beeinflussen das Wetter, und er fürchtet, dass sie die Fäulnis verbreiten. Deshalb schickt er Druiden-Initianden mit leeren Probengefäßen den Berg hinauf, um Wasser zu schöpfen. Die Burning Blade, ein dämonenanbetender Kult, hat sich inzwischen auf den Höhen eingenistet."},{t="Eine entscheidende Probe",b="Druiden tragen das leere Probengefäß zum Teich auf dem Glutnebelgipfel und sammeln dessen Wasser. Dann bringen sie die Probe zu Tonga Runentotem im Wegekreuz. Er kann damit ein Heilmittel entwickeln und die heimische Tierwelt schützen."}},faq={{q="Wozu dient die Leere Glutnebelgipfelprobe?",a="Druiden nutzen die Leere Glutnebelgipfelprobe, ein leeres cenarisches Gefäß, um Wasser aus dem verseuchten Teich auf dem Glutnebelgipfel zu schöpfen. Sie bringen die Probe zu Tonga Runentotem, um ihm zu helfen, ein Heilmittel für erkrankte Wildtiere zu entwickeln.",al={"was bewirkt dieser gegenstand","glutnebelprobe verwendung","warum habe ich dieses probengefäß"}},{q="Wohin muss dieses Probengefäß gebracht werden?",a="Tragt das Probengefäß zum hoch gelegenen Teich auf dem Glutnebelgipfel, nordwestlich vom Wegekreuz im Brachland, und entnehmt eine Wasserprobe.",al={"wo das probengefäß füllen","probengefäß fundort","wie die leere glutnebelgipfelprobe füllen"}},{q="Wer stellt das Probengefäß bereit?",a="Dendrite Sternenschauer stellt das Probengefäß im Auftrag des Zirkels des Cenarius bereit. Anschließend schickt er den Druiden los, um sich mit Tonga Runentotem abzustimmen.",al={"wer gibt das probengefäß","wer hat diese quest begonnen"}},{q="Warum ist es so wichtig, das Wasser auf dem Glutnebelgipfel zu untersuchen?",a="Die Teiche auf dem Glutnebelgipfel beeinflussen das Wetter und den Nebel in der Region. Der Kult der Burning Blade hat den Gipfel verderbt, und verseuchtes Wasser fließt über die Ebenen und vergiftet die dortigen Kreaturen.",al={"warum der teich auf dem glutnebelgipfel","warum ist das wasser verdorben"}}},fx={cf2d7f72={q="Was ist die leere Glutnebelgipfelprobe?",a="Es ist ein spezialisiertes Gefäß, das Hordedruiden von Dendrite Sternenschauer vom Zirkel des Cenarius anvertraut wird. Sein einziger Zweck ist es, Wasser, das aus den erhöhten Becken auf dem Glutnebelgipfel entnommen wurde, sicher zu halten und zu transportieren, damit es sicher analysiert werden kann, ohne dass etwas verschüttet wird oder die Probe weiter kontaminiert wird.",al={"was ist die glutnebelgipfelprobe","gegenstand leere glutnebelgipfelprobe","glutnebelgipfelprobe"}}},fp="28,165,18.362.0,18.213.1,56.217.0,41.124.0,25.133.0,58.188.0"}
P.entries["item:empty-leaden-collection-phial"] = {n="Leere bleierne Sammelphiole",s="Ozzie Wechselvolt sammelt Gnomeregans radioaktiven Niederschlag in einer bleiernen Phiole. Er hofft, die Rückstände könnten helfen, seine geplagten Artgenossen zu heilen, oder ein außerordentlich starkes Getränk ergeben.",h="Ozzie Wechselvolt sammelt Gnomeregans radioaktiven Niederschlag in einer bleiernen Phiole.",kw={"leere bleierne sammelphiole","niederschlag","gnogaine","gnomeregan","kharanos","bleierne phiole","ozzie wechselvolt","strahlung"},ang={["profession:Engineering"]="Die bleierne Phiole verbindet eine Abschirmung aus Schwermetall mit einer Saugvorrichtung, um flüchtige Partikel aus der Umgebung sicher zu sammeln. Sie ist ein praktisches Werk gnomischer Ingenieurskunst.",["race:Gnome"]="Für die vertriebenen Gnome bleibt Gnomeregans Untergang eine offene Wunde. Jeder Versuch, die Folgen seines giftigen Niederschlags rückgängig zu machen, ist von persönlicher Bedeutung, wie exzentrisch der Forscher auch sein mag."},sec={{t="Ein abgeschirmtes Gefäß",b="Ozzie Wechselvolt fertigte eine bleierne Phiole an, um die in Gnomeregan verbliebene Strahlung zu sammeln. Die Belüftungsschächte der Stadt fluteten einst ihre Tunnel mit giftiger Strahlung, um die Trogg-Bedrohung auszumerzen. Die überlebenden Verteidiger wurden zu Lepragnomen, und die eindringenden Bestien wurden verstrahlt.\n\nGrünes Licht haftet noch immer an verstrahlten Invasoren und Plünderern, die durch die Ruinen streifen. Das Blei schirmt den Benutzer ab, während die Phiole die gefährlichen Rückstände einsaugt. Nach dem Versiegeln wird die gesammelte Substanz zu einer Vollen bleiernen Sammelphiole für Ozzies Experimente."}},faq={{q="Wofür wird die Phiole verwendet?",a="Die Phiole sammelt radioaktiven Niederschlag von verstrahlten Invasoren und verstrahlten Plünderern nahe Gnomeregans oberflächennahen Tunneln. Darin versiegelt wird die gesammelte Substanz zu einer Vollen bleiernen Sammelphiole für die Forschung.",al={"was macht die phiole","leere bleierne sammelphiole verwenden","zweck der phiole"}},{q="Warum besteht die Phiole aus Blei?",a="Das Blei schirmt den Benutzer gegen Gnomeregans tödlichen radioaktiven Niederschlag ab. Ohne Schutz können Lebewesen schwer an der Strahlenkrankheit erkranken, und Gnome können zu Lepragnomen werden.",al={"warum eine phiole aus blei","warum bleiern"}},{q="Wer hat dieses Sammelgerät erschaffen?",a="Ozzie Wechselvolt, ein gnomischer Tüftler, hat die Phiole angefertigt. Er arbeitet in Kharanos in Dun Morogh und gibt sie jenen, die sich in Gnomeregans giftige Randgebiete wagen wollen.",al={"wer hat die phiole hergestellt","ozzie wechselvolt phiole","wer hat mir diese phiole gegeben"}},{q="Was hofft Ozzie mit dem gesammelten Niederschlag zu erreichen?",a="Ozzie und sein Mitarbeiter Razzle hoffen, mit dem gesammelten Niederschlag ein Heilmittel für die von der Katastrophe geplagten Lepragnome zu entwickeln. Ozzie räumt auch ein, dass ihre Rezeptur zu starkem Rum oder einem Mittel gegen Haarausfall werden könnte.",al={"warum niederschlag sammeln","gnogaine zweck","was stellt ozzie her"}}},fx={["8d10cd55"]={q="Was ist die leere bleierne Sammelphiole?",a="Es ist ein schwerer, abgeschirmter Behälter, der speziell dafür entwickelt wurde, radioaktiven Niederschlag von den kontaminierten Kreaturen zu ernten, die durch die Ruinen von Gnomeregan streifen, und diesen sicher zu lagern. Die aus dickem Blei konstruierte Phiole schützt ihren Träger vor dem gefährlichen smaragdgrünen Leuchten und ermöglicht es Gnomforschern, die toxischen Rückstände zu untersuchen, ohne der Krankheit zu erliegen, die die gefallene Stadt verformt hat.",al={"was ist die leere bleierne sammelphiole","bleierne sammelphiole","leere phiole gnomeregan"}}},fp="29,173,17.509.0,27.207.0,30.178.0,35.159.0,59.218.0"}
P.entries["item:empty-red-waterskin"] = {n="Leerer roter Wasserschlauch",s="In Tarrens Mühle ist der Leere rote Wasserschlauch für einen Brunnen bestimmt, den die Seuche nicht berührt hat. Brine gibt ihn Schamanenanwärtern für ihre Elementarprüfungen.",h="In Tarrens Mühle ist der Leere rote Wasserschlauch für einen Brunnen bestimmt, den die Seuche nicht berührt...",kw={"brine","call of water","leerer roter wasserschlauch","vorgebirge des hügellands","tarrens mühle","water sapta"},ang={["class:Shaman"]="Als Schamane tragt und füllt Ihr diesen Wasserschlauch als ersten Schritt, um das Wassertotem zu meistern und Eure Sinne auf die widerstandsfähigen Geister des Wassers einzustimmen.",["race:Orc"]="Als Ork hört Ihr, wie Brine den reinen Brunnen von Tarrens Mühle mit Kriegshäuptling Thrall vergleicht, einem Leuchtfeuer der Stärke und Hoffnung, das unermessliches Leid erträgt."},sec={{t="Ein Gefäß für reines Wasser",b="Brine gibt Schamanenanwärtern einen schlichten roten Wasserschlauch für die Prüfungen von Call of Water. Sie tragen ihn über das Meer nach Tarrens Mühle im Vorgebirge des Hügellands. Die Verlassenen halten die Stadt besetzt, doch ihr zentraler Brunnen liefert noch immer frisches Quellwasser. Mit dem gefüllten Schlauch gelangt eine Probe zurück zu Brine, die sie für die Prüfung des Anwärters zu einer Phiole mit reinstem Wasser vermischt."}},faq={{q="Wofür wird der Leere rote Wasserschlauch verwendet?",a="Schamanen verwenden den Schlauch bei den Prüfungen von Call of Water, um Quellwasser aus dem Brunnen von Tarrens Mühle zu sammeln. Gefüllt wird er zu einem Vollen roten Wasserschlauch.",al={"leerer roter wasserschlauch verwendung","was tun mit rotem wasserschlauch"}},{q="Wer stellt diesen Wasserschlauch bereit?",a="Brine, eine orkische Schamanin und Einsiedlerin auf einem Hügel im südlichen Brachland, gibt den Wasserschlauch Schamanenanwärtern, die ihre Elementarprüfungen durchlaufen.",al={"wer gibt den roten wasserschlauch","roter wasserschlauch questgeber"}},{q="Warum gerade Wasser aus Tarrens Mühle sammeln?",a="Tarrens Mühle steht unter der Kontrolle der Verlassenen, doch der zentrale Brunnen bleibt unverdorben. Brine sieht in der reinen Quelle Hoffnung und Leben, die in einem unheiligen Land fortbestehen.",al={"warum wasser aus tarrens mühle","tarrens mühle brunnen hintergrund"}},{q="Was geschieht, nachdem der Wasserschlauch gefüllt wurde?",a="Nachdem Ihr den Schlauch am Brunnen gefüllt habt, bringt Ihr ihn zu Brine ins Brachland zurück. Sie vermischt sein Wasser mit anderen seltenen Proben zu einer Phiole mit reinstem Wasser. Islen Wasserdeuter verwendet diese Phiole, um die Water Sapta herzustellen.",al={"wie weiter mit rotem wasserschlauch","vollen roten wasserschlauch abgeben"}}},fx={["29d0aa45"]={q="Was ist der leere rote Wasserschlauch?",a="Es ist ein leeres Gefäß, das Schamanenlehrlingen anvertraut wird, die die Prüfungen von Call of Water durchlaufen. Es wurde dazu erschaffen, Flüssigkeit sicher über große Entfernungen zu transportieren, und sein spezifischer Zweck ist es, reines Brunnenwasser aus dem Vorgebirge des Hügellands zu sammeln und zu bewahren, damit es später zu einer elementaren Sapta gebraut werden kann.",al={"was ist der leere rote wasserschlauch","gegenstand roter wasserschlauch","hintergrund zum leeren roten wasserschlauch"}}},fp="19,143,23.347.0,41.140.0,28.131.0,47.156.0,43.210.0"}
P.entries["item:empty-sampling-tube"] = {n="Leere Probenröhre",s="In Auberdine gibt Euch Thundris Windwirker eine Leere Probenröhre, um den Klippenquell zu untersuchen. Nachtelfengelehrte erforschen die Verderbnis, die Dunkelküste bedroht.",h="In Auberdine gibt Euch Thundris Windwirker eine Leere Probenröhre, um den Klippenquell zu untersuchen.",kw={"auberdine","der klippenquell","dunkelküste","leere probenröhre","nebelrand","thundris windweaver","wasserprobe"},ang={["class:Druid"]="Als Druide könnt Ihr helfen aufzudecken, wie die Verderbnis des Teufelswalds Dunkelküstes Flüsse erreicht und die heimischen Wildtiere krank macht.",["race:NightElf"]="Als Nachtelf aus Auberdine könnt Ihr helfen, den Klippenquell zu untersuchen und zu verhindern, dass sein verderbtes Wasser Euren Küstenzufluchtsort am Nebelrand vergiftet."},sec={{t="Die Gewässer prüfen",b="Dunkelküstes Wasserläufe werden faulig, während sich die Fäulnis in der Wildnis ausbreitet. In Auberdine untersucht Thundris Windwirker diese Veränderung. Er gibt Euch eine leere Glasröhre für Wasser aus dem Klippenquell. Nehmt die Probe aus dem Becken unter dem ersten Wasserfall nördlich der Stadt. Nachtelfische Naturforscher werden sie untersuchen, um mehr über die Verderbnis zu erfahren, die zum Nebelrand fließt."},{t="Der Quelle nachspüren",b="Blackwood-Furbolgs leben in Lagern entlang der Flussufer. Windwirker vermutet, dass sie unter der Fäulnis leiden und sie verbreiten, statt sie zu verursachen. Die Probe bestätigt, dass die Verunreinigung von den verseuchten Höhen des Teufelswalds im Osten herabfließt. Sie könnte helfen, ein Heilmittel zu entwickeln und ein gezieltes Vorgehen gegen die Fäulnis zu planen."}},faq={{q="Wozu dient die Leere Probenröhre?",a="Sammelt mit der Leeren Probenröhre Wasser aus dem verderbten Klippenquell nördlich von Auberdine. Bringt die Probe zu Thundris Windwirker, der die fauligen Stoffe untersucht, die sich in Dunkelküste ausbreiten.",al={"warum habe ich diese röhre","was macht die probenröhre","zweck der röhre"}},{q="Wo soll die Wasserprobe entnommen werden?",a="Füllt die Röhre am ersten Wasserfall des Klippenquells nördlich von Auberdine. Das Becken liegt unter einer Brücke, bevor das Wasser in den Nebelrand strömt.",al={"wo röhre füllen","wo liegt der klippenquell","füllstelle der probenröhre"}},{q="Wer hat diese Röhre bereitgestellt?",a="Thundris Windwirker gibt Euch die Röhre. Er ist ein nachtelfischer Naturforscher, der die Bedrohungen für das Land um Auberdine untersucht.",al={"wer gibt die röhre","questgeber der röhre","thundris windweaver"}},{q="Was verschmutzt den Klippenquell?",a="Blackwood-Furbolgs leben entlang der Flussufer und tragen zur Verschmutzung bei. Doch die Verderbnis stammt aus dem verseuchten Wald des Teufelswalds, hoch in den Bergen im Osten.",al={"warum ist der fluss grün","was hat das wasser verderbt","verderbnis im klippenquell"}}},fx={["54012ea9"]={q="Was ist die leere Probenröhre?",a="Es ist ein sauberes, speziell vorbereitetes Glasfläschchen, das Euch gegeben wird, um Wasser aus dem The Cliffspring River zu sammeln. Thundris Windwirker benötigt ein unkontaminiertes Gefäß, um eine reine Probe der fauligen Jauche zu sichern, die derzeit nördlich von Auberdine ins Meer fließt.",al={"was ist die leere probenröhre","hintergrund zur leeren probenröhre","über die leere probenröhre"}},b354763d={q="Warum möchte Thundris eine in dieser Röhre gesammelte Probe?",a="Die Gewässer der Dunkelküste werden rapide krank und Thundris vermutet, dass die üble Verderbnis, die den The Cliffspring River hinabfließt, die Küste von Auberdine erreicht. Durch die Untersuchung einer frischen Probe, die in dieses Gefäß gefüllt wurde, hofft er festzustellen, ob lokale Blackwood-Furbolgs oder dunklere Verderbnisse aus dem östlichen Hochland von Teufelswald dafür verantwortlich sind, was den Nachtelfen eine Grundlage für ihre Gegenmaßnahmen bieten würde.",al={"warum ist leere probenröhre begehrt","warum cliffspring-wasser sammeln","thundris probe warum"}}},fp="19,155,18.379.0,18.293.1,47.203.0,47.166.0,23.115.0,40.156.1"}
P.entries["item:empty-water-tube"] = {n="Leere Wasserphiole",s="In Auberdine steht die Leere Wasserphiole bereit, um heiliges Mondbrunnenwasser für den roten Kristall auf den östlichen Klippen der Dunkelküste zu sammeln.",h="In Auberdine steht die Leere Wasserphiole bereit, um heiliges Mondbrunnenwasser für den roten Kristall auf...",kw={"as water cascades","auberdine","dunkelküste","leere wasserphiole","teufelswald","mondbrunnen","phiole mit mondbrunnenwasser","roter kristall"},ang={["class:Druid"]="Als Druide bringt Ihr Mondbrunnen tiefe Ehrfurcht entgegen. Ihr verlasst Euch auf ihr unverdorbenes Wasser, um Anomalien zu untersuchen und verderbte Lande wie den Teufelswald von seltsamen Störungen zu reinigen.",["race:NightElf"]="Als Nachtelf betrachtet Ihr den Umgang mit geweihtem Mondbrunnenwasser als heilige Pflicht. Die Kaldorei verehren Mondbrunnen als heilige, von Elune gesegnete Wasserreservoirs."},sec={{t="Ein Gefäß für gesegnetes Wasser",b="Schildwachen und Gelehrte suchen reine Mondessenz, um den geheimnisvollen roten Kristall am östlichen Gebirgskamm der Dunkelküste zu untersuchen. Gewöhnliches Glas oder Flaschen können geweihtes Wasser verunreinigen, daher erhalten Forscher, die Auberdines Mondbrunnen aufsuchen, diese versiegelte Phiole. Sie tragen das gefüllte Gefäß die Berghänge hinauf, um herauszufinden, wie das fremdartige Mineral auf Elunes Magie reagiert."},{t="Teufelswalds Schatten ergründen",b="Der Teufelswald liegt jenseits der Berge östlich der Dunkelküste, vergiftet von dämonischer Verderbnis. Auberdines Verteidiger vermuten, dass der unheilvolle tiefrote Monolith nahe den Klippen mit jenem verwüsteten Wald verbunden sein könnte. Die Forscher hoffen, dass Mondbrunnenwasser, das über sein Gitterwerk fließt, die innere Struktur des Kristalls offenbart, ohne eine katastrophale Freisetzung der darin gefangenen Macht auszulösen."}},faq={{q="Wozu dient die Leere Wasserphiole?",a="In Auberdine erhaltet Ihr den leeren Behälter, um Mondbrunnenwasser zur Untersuchung des bizarren roten Kristalls auf den östlichen Höhen der Dunkelküste zu schöpfen.",al={"leere wasserphiole zweck","warum habe ich eine leere wasserphiole","was mit wasserphiole tun"}},{q="Wo soll die Phiole gefüllt werden?",a="Taucht die Phiole in den Mondbrunnen in Auberdine, um sie zu füllen. Das gefüllte Gefäß wird zu einer Phiole mit Mondbrunnenwasser.",al={"wo wasserphiole füllen","wo leere wasserphiole füllen","wasserphiole füllen ort"}},{q="Warum wird Mondbrunnenwasser für den Kristall benötigt?",a="Mondbrunnenwasser trägt Elunes mächtige, reinigende Magie in sich. Gelehrte glauben, dass es Hinweise auf Herkunft und Zusammensetzung des roten Kristalls offenbaren wird, wenn man es über ihn gießt.",al={"warum mondbrunnenwasser","was bewirkt mondbrunnenwasser beim kristall","roter kristall mondbrunnenwasser"}},{q="Warum sorgen sich Auberdines Bewohner wegen des Kristalls?",a="Der Kristall liegt nahe dem hohen Gebirgskamm über dem Teufelswald, einem von der Brennenden Legion schwer verderbten Wald. Örtliche Beobachter fürchten, dass eine Verbindung zu jener verseuchten Wildnis die Dunkelküste bedrohen könnte.",al={"ist der kristall gefährlich","kristall gefahr dunkelküste","warum roten kristall untersuchen"}}},fx={["8160d8ef"]={q="Was ist die Leere Wasserphiole?",a="Es ist ein einfaches, leeres Glasfläschchen, das Ihr in Auberdine erhaltet, damit Ihr Wasser aus dem Mondbrunnen des Dorfes schöpfen könnt. Sobald sie gefüllt ist, werdet Ihr ihren gesegneten Inhalt verwenden, um den geheimnisvollen, außerirdischen roten Kristall zu testen, der an den Bergen der Dunkelküste liegt.",al={"was ist leere wasserphiole","leere wasserphiole","phiole für mondbrunnenwasser"}}},fp="16,128,27.358.0,24.372.1,44.140.0,32.104.0,45.158.0,56.186.0"}
P.entries["item:enchanted-agate"] = {n="Enchanted Agate",s="Der Enchanted Agate aktiviert die Verteidigung des Turms von Arathor. Skuerto gibt ihn Euch, bevor Ihr hineingeht, um Trelanes verbliebene Gegenstände zu suchen.",h="Der Enchanted Agate aktiviert die Verteidigung des Turms von Arathor.",kw={"agat","verteidigung","enchanted agate","sockel","skuerto","der turm von arathor","trelane"},sec={{t="Am Turm",b="Im Lager nahe dem Turm von Arathor gibt Skuerto Euch den Enchanted Agate. Drückt ihn gegen einen Sockel nahe dem Fuß des Turms, wenn Ihr bereit seid, ihn zu betreten. Der Edelstein aktiviert die Verteidigung des Turms und macht Euch den Weg zu Trelanes verbliebenen Gegenständen frei."}},faq={{q="Was bewirkt der Enchanted Agate?",a="Der Enchanted Agate aktiviert die Verteidigung des Turms von Arathor, wenn Ihr ihn gegen einen Sockel nahe seinem Fuß drückt.",al={"enchanted agate verwenden","zweck des agats","was bewirkt der edelstein"}},{q="Wo benutze ich den Enchanted Agate?",a="Drückt den Enchanted Agate gegen einen der Sockel nahe dem Fuß des Turms von Arathor.",al={"wo den agat verwenden","turmsockel","fundort des agats"}},{q="Wer gibt mir den Enchanted Agate?",a="Skuerto gibt Euch den Enchanted Agate im Lager nahe dem Turm von Arathor.",al={"wer gab mir den agat","skuerto agat","von wem ist der agat"}},{q="Warum nehme ich den Enchanted Agate mit in den Turm?",a="Der Edelstein aktiviert die Verteidigung des Turms, bevor Ihr hineingeht, um Trelanes verbliebene Gegenstände zu finden.",al={"warum agat im turm","agat für trelane","wofür ist der edelstein"}}},fp="15,144,12.248.0,33.113.0,35.93.0,33.76.0,51.90.0"}
P.entries["item:enchanted-gaea-seeds"] = {n="Verzauberte Gaeasamenkörner",s="In Sonnenfels sind Verzauberte Gaeasamenkörner für das Verbrannte Tal bestimmt. Druidische Magie hilft ihnen, in ascheersticktem Boden Wurzeln zu schlagen und Kalimdors verwüstetes Land allmählich zu heilen.",h="In Sonnenfels sind Verzauberte Gaeasamenkörner für das Verbrannte Tal bestimmt.",kw={"das verbrannte tal","verzauberte gaeasamenkörner","gaeasamenkorn","wiedergeburt","steinkrallengebirge","sonnenfels","tammra windwhisper"},ang={["class:Druid"]="Als Druide helft Ihr, die Wiedergeburt zu fördern und widerstandsfähiges Leben in ein Land zurückzulocken, das von Verwüstung und Flächenbränden verzehrt wurde.",["race:Tauren"]="Als einer der Shu'halo von Sonnenfels pflanzt Ihr verzauberte Samen in spiritueller Verantwortung, ehrt damit die Earth Mother und gewinnt verwundetes Land zurück."},sec={{t="Ein Funke in der Asche",b="Druiden der Horde arbeiten daran, die tiefen Narben im Steinkrallengebirge zu heilen. In Sonnenfels verzaubert Tammra Windfeld rohe Gaeasamen, damit sie Verderbnis und elementarer Fäulnis standhalten. In fruchtbare Erdhügel unter dem Ruß des Verbrannten Tals gepflanzt, können sie selbst in unwirtlichem Boden Wurzeln schlagen. Doch feindselige Feuerelementare und eingedrungene Harpyien beherrschen noch immer das Tal."},{t="Das Versprechen der Erneuerung",b="Die Samen sind Teil des Kampfes um die Zukunft des Steinkrallengebirges. Ihre verzauberten Hüllen widerstehen anhaltender Verderbnis und geben einheimischen Pflanzen wieder Halt. Das zurückkehrende Grün soll aufgewühlte Feuerelementare besänftigen, wilde Harpyien verdrängen und der Entwaldung durch den unerbittlichen Holzeinschlag der Venture Company entgegenwirken."}},faq={{q="Wofür werden Verzauberte Gaeasamenkörner verwendet?",a="Pflanzt Verzauberte Gaeasamenkörner in fruchtbare Erdhügel im Verbrannten Tal. Aus ihnen sollen widerstandsfähige Pflanzen wachsen, die der Verderbnis trotzen und beginnen, das von Feuer und Krieg gezeichnete Land zu heilen.",al={"gaeasamen zweck","was bewirken verzauberte gaeasamenkörner","warum gaeasamen pflanzen"}},{q="Wer hat diese Samen erschaffen oder verzaubert?",a="Rohe Gaeasamen werden in der umliegenden Wildnis gesammelt und zu Tammra Windfeld in Sonnenfels gebracht. Sie verzaubert sie, damit sie im lebensfeindlichen, aschedurchsetzten Boden des Verbrannten Tals überleben können.",al={"wer hat die samen erschaffen","tammra windwhisper samen","wie werden gaeasamen hergestellt"}},{q="Warum müssen sie im Verbrannten Tal gepflanzt werden?",a="Im Verbrannten Tal hat die Umweltzerstörung das Steinkrallengebirge am härtesten getroffen. Zornige Feuerelementare und Harpyien überrennen es, und das Pflanzen der Samen in verbliebene Erdhügel bringt neues Leben, das die Unruhen der Region besänftigen soll.",al={"wo werden sie gepflanzt","warum verbranntes tal","verbranntes tal bepflanzung"}},{q="Welche Gefahren drohen den gepflanzten Samen?",a="Feindselige Feuerelementare, die aus dem Brand hervorgingen, und aggressive Bloodfury-Harpyien, die in den Ruinen nisten, bedrohen die gepflanzten Samen. Die nahe gelegenen Betriebe der Venture Company bringen weitere industrielle Zerstörung.",al={"gefahren im verbrannten tal","was zerstört das land"}}},fx={["2eba8b82"]={q="Was sind Verzauberte Gaeasamenkörner?",a="Verzauberte Gaeasamenkörner sind widerstandsfähige, magisch behandelte Samen, die von Tammra Windfeld in Sonnenfels vorbereitet wurden. Sie wurden entwickelt, um der Umweltfäulnis zu widerstehen, und dienen als starker Katalysator für die Wiedergeburt, der fähig ist, auf verwüsteter Erde Wurzeln zu schlagen und den langen Prozess der Heilung des versengten Geländes einzuleiten.",al={"was sind verzauberte gaeasamenkörner","verzauberte gaeasamenkörner hintergrund","was ist verzauberte gaeasamenkörner"}}},fp="20,170,20.351.0,22.319.0,39.185.0,37.193.0,45.237.0,36.201.0"}
P.entries["item:enchanted-resonite-crystal"] = {n="Verzauberter Resonitkristall",s="Im Steinkrallengebirge hat Mor'rogal Resonitkristalle mit schamanischer Magie verändert. Er schuf den Verzauberten Resonitkristall, um das Fass zu zerschlagen, das Goggeroc gefangen hält.",h="Im Steinkrallengebirge hat Mor'rogal Resonitkristalle mit schamanischer Magie verändert.",kw={"earthen arise","verzauberter resonitkristall","goggeroc","mor'rogal","resonitfass","resonitkristall","steinkrallengebirge"},ang={["class:Shaman"]="Als Schamane könnt Ihr erkennen, wie elementare Kraft die Magie schwächt, die lebenden Stein bindet.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr Mor'rogal helfen, das empfindliche Gleichgewicht des Steinkrallengebirges zu schützen, indem Ihr uralte Bedrohungen aufhaltet, bevor sie Außenposten der Region gefährden."},sec={{t="Brecher uralten Steins",b="In den Höhlen des Steinkrallengebirges besitzen rohe Resonitkristalle ungewöhnliche harmonische und erdverbundene Eigenschaften. Schamane Mor'rogal spürte Gefahr in einem versiegelten unterirdischen Fass und veränderte die Kristalle daher mit seinen Elementarkräften. Der Verzauberte Resonitkristall kann das verstärkte Resonitfass zerschlagen und Goggeroc, einen riesigen Irdenen, wecken, solange er von seinem langen Schlaf noch benommen ist."},{t="Die Bedrohung durch Goggeroc",b="Mor'rogal fürchtet, ein ungebändigter uralter Irdener könnte eine Katastrophe über das Steinkrallengebirge und weite Teile Kalimdors bringen. Er will mit dem verzauberten Kristall das Fass zerschlagen und Goggeroc wecken, solange dieser geschwächt ist. So bleibt eine kurze Gelegenheit, ihn zu vernichten, bevor seine volle elementare Macht zurückkehrt."}},faq={{q="Wozu dient der Verzauberte Resonitkristall?",a="Der Kristall zerschlägt das Resonitfass tief in den von Kobolden bevölkerten Höhlen des Steinkrallengebirges und befreit Goggeroc, einen schlummernden Irdenen.",al={"verzauberter resonitkristall verwendung","was bewirkt der kristall","resonitfass zerschlagen"}},{q="Wer hat diesen verzauberten Kristall erschaffen?",a="Schamane Mor'rogal schuf den Kristall, indem er rohen Resonit mit seinen schamanischen Kräften erfüllte. Er schwächt die schlafende Kreatur im Fass und legt sie frei.",al={"wer hat den kristall erschaffen","mor'rogal kristall","verzauberter resonit erschaffer"}},{q="Warum muss Goggeroc geweckt und vernichtet werden?",a="Mor'rogal fürchtet, die unübertroffene Macht eines uralten Irdenen könnte das Steinkrallengebirge und Kalimdor gefährden. Der Kristall weckt Goggeroc, solange er vorübergehend geschwächt und dadurch verwundbar ist.",al={"warum goggeroc töten","ist goggeroc gefährlich","goggeroc bedrohung"}},{q="Was soll ich mit dem Kristall tun, nachdem ich Goggeroc besiegt habe?",a="Bringt den Verzauberten Resonitkristall zu Mor'rogal zurück und bestätigt, dass Goggeroc getötet wurde.",al={"resonitkristall zurückbringen","verzauberten resonitkristall abgeben"}}},fx={ed58de6b={q="Was ist der Verzauberte Resonitkristall?",a="Es ist ein veränderter Mineraltalisman, der von Mor'rogal in Sonnenfels mit schamanischer Macht durchdrungen wurde. Resonitkristalle sind natürlich vorkommende Mineralien, die in den Höhlen des Steinkrallengebirges gefunden werden. Sobald er magisch verwandelt wurde, dient dieser Kristall als Schlüssel und Hammer, der speziell dafür entwickelt wurde, das Resonitgefäß zu zertrümmern, das den schlafenden Irdenen-Riesen Goggeroc enthält.",al={"was ist verzauberter resonitkristall","verzauberter resonitkristall hintergrund","bedeutung resonitkristall"}},d1731b4b={q="Warum möchte Mor'rogal den Verzauberten Resonitkristall?",a="Mor'rogal benötigt den Kristall, um Goggeroc zu befreien und zu eliminieren, bevor der Eirdene mit voller Kraft erwacht. Er fürchtet, dass ein entfesselter Eirdener eine beispiellose Gefahr darstellt, die das gesamte Steinkrallengebirge verwüsten könnte. Das Zertrümmern des Gefäßes zwingt Goggeroc dazu, in einem stark geschwächten Zustand zu erwachen, was Euch die einzige gangbare Möglichkeit gibt, ihn niederzustrecken.",al={"warum möchte man verzauberten resonitkristall","warum braucht mor'rogal den kristall","warum verzauberter resonitkristall"}}},fp="26,153,24.383.0,22.282.1,48.143.1,35.146.0,44.177.0,59.96.0"}
P.entries["item:encrypted-memorandum"] = {n="Verschlüsseltes Memorandum",s="Im Coldridgetal weist das Verschlüsselte Memorandum neuen Schurken heimlich den Weg zu ihrem Lehrer. Solm Hargrin tarnt seine Einladung als offizielle Mitteilung und ruft Halunken im Exil dazu auf, zusammenzuhalten.",h="Im Coldridgetal weist das Verschlüsselte Memorandum neuen Schurken heimlich den Weg zu ihrem Lehrer.",kw={"ambossar","das coldridgetal","dun morogh","verschlüsseltes memorandum","gnomeregan","schurkenlehrer","solm hargrin"},ang={["class:Rogue"]="Als Schurke könnt Ihr diesem codierten Brief zu Eurem Lehrer in Ambossar folgen und seinem Ruf in Dun Morogh nachkommen.",["race:Gnome"]="Als Gnom lebt Ihr nach Gnomeregans Fall unter zwergischen Verbündeten. Diese Notiz ruft gnomische Schurken im Stillen dazu auf, zusammenzuhalten und zu überleben."},sec={{t="Ein diskreter Ruf",b="In Ambossar halten Schurken ihre Anwesenheit geheim. Ihr Lehrer, Solm Hargrin, erreicht Rekruten durch das Verschlüsselte Memorandum, statt sie vor aller Augen anzusprechen. Das codierte Pergament wirkt wie eine Anweisung ferner Vorgesetzter. Es verrät angehenden Schurken, wo sie einen Mentor finden, ohne dass örtliche Wachen und misstrauische Stadtbewohner darauf aufmerksam werden."},{t="Verbundenheit in Coldridge",b="Solm Hargrins verschlüsselte Botschaft gibt Schurken im Coldridgetal praktische Ratschläge. Gnomeregan ist gefallen, und vertriebene Gnome drängen sich nun neben ihren zwergischen Verbündeten in den verschneiten Siedlungen von Dun Morogh. Die Spannungen schwelen dicht unter der Oberfläche. Solm mahnt seine Schüler, aufeinander achtzugeben, denn die Suche nach Sündenböcken und Vorurteile können dazu führen, dass Schurken für jedes verschwundene Schmuckstück geradestehen müssen."}},faq={{q="Was ist das Verschlüsselte Memorandum?",a="Das Verschlüsselte Memorandum ist ein codiertes Pergament, das angehenden Schurken im Coldridgetal überbracht wird. Es weist sie an, sich ausbilden zu lassen, und wirkt dabei wie eine offizielle Depesche.",al={"was ist das verschlüsselte memorandum","memorandum gegenstand","schurkenn otiz"}},{q="Wer hat dieses Memorandum verfasst?",a="Solm Hargrin hat das Memorandum verfasst. Der Schurkenlehrer in Ambossar tarnt es als offizielle Befehle, um andere Halunken unauffällig zu versammeln.",al={"wer hat das memorandum verfasst","wer hat das verschlüsselte memorandum geschickt","verfasser des memorandums"}},{q="Warum ist die Nachricht verschlüsselt?",a="Schurken im Coldridgetal meiden die Aufmerksamkeit der Öffentlichkeit. Die Tarnung lässt die Einladung wie eine gewöhnliche Amtsangelegenheit wirken, sodass örtliche Behörden und neugierige Beobachter die Ausbildung nicht bemerken.",al={"warum verschlüsselt","warum chiffriert","warum ist es codiert"}},{q="Was will Solm Hargrin?",a="Solm Hargrin will Kampfausbildung, Rat und gegenseitigen Schutz bieten. Er fordert Schurken auf, im dicht bevölkerten Dun Morogh zusammenzuhalten, wo Diebe schnell für verschwundene Gegenstände verantwortlich gemacht werden.",al={"was will solm","warum solm finden","solms absicht"}}},fx={["88db5375"]={q="Warum möchte jemand das Verschlüsselte Memorandum?",a="Das Memorandum ist ausschließlich für Euch bestimmt. Solm Hargrin, der Schurkenausbilder im Coldridgetal, hat es als Einladung für Mitpraktizierende Eurer gemeinsamen Zunft verfasst. Getarnt als offizielle Korrespondenz soll es Euch dazu bewegen, Kontakt mit ihm aufzunehmen, ohne unerwünschte Aufmerksamkeit von den Einheimischen in Ambossar auf Euch zu ziehen.",al={"warum möchte man das verschlüsselte memorandum","wer möchte das verschlüsselte memorandum","zweck verschlüsseltes memorandum"}}},fp="20,202,18.351.0,20.375.1,33.173.0,26.136.0,29.191.0,28.186.0"}
P.entries["item:encrypted-parchment"] = {n="Verschlüsseltes Pergament",s="Im Tal der Prüfungen ruft Verschlüsseltes Pergament vielversprechende junge Ork-Schurken in die Den. Gornek übergibt es Rekruten nach ihren ersten Prüfungen, und seine Chiffre verweist auf Rwag, den verborgenen Ausbilder.",h="Im Tal der Prüfungen ruft Verschlüsseltes Pergament vielversprechende junge Ork-Schurken in die Den.",kw={"durotar","verschlüsseltes pergament","gornek","ork-schurke","rwag","shattered hand","the den","das tal der prüfungen"},ang={["class:Rogue"]="Als Schurke erhaltet Ihr einen Ruf, Euch bei Mentoren mit Verbindungen zur Shattered Hand in den verdeckten Künsten der Horde ausbilden zu lassen.",["race:Orc"]="Als Ork bevorzugt Ihr vielleicht den offenen, ehrenhaften Kampf, doch dieses Schreiben heißt jene willkommen, deren Talente in den leiseren, tödlicheren Überlebenskünsten liegen."},sec={{t="Ein Ruf aus den Schatten",b="Im Tal der Prüfungen beweisen junge Orks unter freiem Himmel ihre Stärke. Wer Begabung für Verstohlenheit, Täuschung und Klingenkunst zeigt, erregt eine andere Art von Aufmerksamkeit. Nachdem sie sich der heimischen Tierwelt gestellt haben, erhalten vielversprechende Ork-Schurken Verschlüsseltes Pergament von Gornek. Seine verschlüsselten Worte rufen jene, die eine Botschaft lesen können, die verborgen bleiben soll."},{t="Verbindungen zur Shattered Hand",b="Die Chiffre führt einen Neuling durch die Den, vorbei an den anderen Clanausbildern, zu Rwag. Dort erfährt der Rekrut, dass die Shattered Hand den Ruf veranlasst hat. Der Orden arbeitet im verdeckten Netzwerk der Horde. Wer seinem Ruf folgt, beginnt die Ausbildung zum Schurken in Spionage und Schattenkünsten."}},faq={{q="Welchen Zweck erfüllt das Verschlüsselte Pergament?",a="Das Verschlüsselte Pergament ist ein verschlüsselter Ruf, der angehende Ork-Schurken zu ihrem Ausbilder Rwag in der Den im Tal der Prüfungen führt.",al={"was ist verschlüsseltes pergament","zweck des pergaments","warum verschlüsseltes pergament"}},{q="Wer schickt Euch das Pergament?",a="Gornek überreicht Euch das Pergament nach Euren ersten Prüfungen im Tal. Seine Botschaft stammt von Rwag, dem Schurkenausbilder.",al={"wer schrieb das pergament","absender des pergaments","wer gab mir das pergament"}},{q="Warum ist die Botschaft verschlüsselt?",a="Rwag und seine Kontakte bei der Shattered Hand bevorzugen Geheimhaltung. Die Chiffre führt Rekruten, die sich für den subtilen Pfad eines Schurken eignen, in ihre verborgenen Reihen.",al={"warum ist es verschlüsselt","warum verschlüsselt","geheime botschaft"}},{q="Welche Organisation steht hinter dem Ruf?",a="Rwag enthüllt, dass die Shattered Hand ihn gebeten hat, nach fähigen Rekruten Ausschau zu halten. Der Orden bildet Schurken in Verstohlenheit und Spionage aus, damit sie der Horde aus den Schatten dienen.",al={"wer will mich ausbilden","shattered hand schurke","welche fraktion hat das geschickt"}},{q="Können Troll-Schurken dieses Pergament verwenden?",a="Nein. Troll-Schurken beginnen ebenfalls im Tal der Prüfungen, erhalten aber stattdessen eine Verschlüsselte Schrifttafel.",al={"troll verschlüsseltes pergament","ist es auch für trolle"}}},fx={["268fdb07"]={q="Was ist das Verschlüsselte Pergament?",a="Das Verschlüsselte Pergament ist ein verschlüsselter Brief, der an vielversprechende junge Orc-Schurken übermittelt wird, die sich im Tal der Prüfungen bewähren. Geschrieben unter Verwendung von Gaunersprache oder einer Chiffre, um neugierige Blicke zu vermeiden, weist es Euch an, Euren Ausbilder Rwag aufzusuchen, der in den Schatten von The Den verborgen ist.",al={"was ist verschlüsseltes pergament","gegenstand verschlüsseltes pergament","was ist dieses pergament"}},fa1aab52={q="Warum erhaltet Ihr das Verschlüsselte Pergament?",a="Das Pergament wird Euch ausgehändigt, weil Ihr die Aufmerksamkeit der The Shattered Hand erregt habt, der Gilde von Attentätern und Spähern, die der Horde dient. Sie möchten Euch in ihre Reihen aufnehmen, Euch in Eurer tödlichen Handwerkskunst unterweisen und sicherstellen, dass Ihr wisst, wo Ihr ihren verdeckten Agenten, Rwag, finden könnt.",al={"warum brauche ich verschlüsseltes pergament","warum verschlüsseltes pergament","zweck verschlüsseltes pergament"}}},fp="19,194,26.324.0,26.280.0,47.132.0,31.117.0,37.147.0,40.163.0,36.98.0"}
P.entries["item:encrypted-rune"] = {n="Verschlüsselte Rune",s="Im Coldridgetal ruft die Verschlüsselte Rune vielversprechende neue Schurken nach Ambossar. Ihre Botschaft fordert sie auf, die Worte zu entziffern und Solm Hargrin aufzusuchen.",h="Im Coldridgetal ruft die Verschlüsselte Rune vielversprechende neue Schurken nach Ambossar.",kw={"ambossar","chiffre","das coldridgetal","dun morogh","verschlüsselte rune","schurke","solm hargrin"},ang={["class:Rogue"]="Als Schurke lernt Ihr durch diesen ersten förmlichen Kontakt die Schurken von Dun Morogh kennen. Eure Ausbildung in Verstohlenheit, schnellen Klingen und Überleben beginnt.",["race:Dwarf"]="Als Zwerg seid Ihr ein weiteres Kind Eisenschmiedes im Coldridgetal. Die Rune ruft Euch dazu auf, die Schatten zu meistern und die Interessen des Klans aus dem Verborgenen zu schützen."},sec={{t="Ein verschlüsselter Ruf",b="Ein neuer Schurke muss die Gaunersprache lesen können, um die Rune zu verstehen. Dabei lernt er das schattenhafte Handwerk kennen, das zum Überleben in der rauen Wildnis von Dun Morogh nötig ist. Ihre Chiffren enthalten einen vertraulichen Ruf von Solm Hargrin, dem Schurkenmentor in Ambossar, an jene, die Talent für Verstohlenheit und List zeigen."},{t="Augen in den Schatten",b="Das Entziffern der Rune führt neue Schurken zu Solm Hargrin in Ambossar. Er hofft, die verdeckten Reihen des Tals zu stärken, während die Spannungen vor Ort zunehmen. Solm lehrt Klingenführung und Verstohlenheit, aber auch Wachsamkeit und Kameradschaft. Da der Frieden brüchig ist, müssen Schurken zusammenhalten."}},faq={{q="Was ist die Verschlüsselte Rune?",a="Die Verschlüsselte Rune trägt eine chiffrierte Botschaft für angehende Schurken im Coldridgetal. Sie weist sie an, sich zur Ausbildung bei Solm Hargrin in Ambossar zu melden.",al={"was ist diese rune","zweck der verschlüsselten rune","was bewirkt die rune"}},{q="Wer hat die Verschlüsselte Rune geschickt?",a="Solm Hargrin, der Schurkenlehrer in Ambossar, schickt die Verschlüsselte Rune, um neue Rekruten im Stillen herbeizurufen.",al={"wer hat sie geschrieben","wer hat das gegeben","absender der rune"}},{q="Wohin soll ich die Rune bringen?",a="Bringt die entzifferten Anweisungen zu Solm Hargrin in Ambossar im Coldridgetal.",al={"wohin gehen","zu wem bringen","wo ist solm"}},{q="Warum ist die Botschaft verschlüsselt?",a="Die Chiffre sorgt dafür, dass nur ein angehender Schurke, der sie lesen kann, dem Ruf folgen kann. Sie hält die Methoden der Schurken vor aller Augen verborgen.",al={"warum eine chiffre","warum ist sie verschlüsselt","warum eine geheime rune"}}},fx={["1ca7ae1e"]={q="Warum wurde Euch die Verschlüsselte Rune geschickt?",a="Solm Hargrin, der Schurkenausbilder in Ambossar, hat die Rune geschickt, um Eure Aufmerksamkeit als aufstrebender Schurke im Coldridgetal zu erregen. Da sich in Dun Morogh zunehmend Ärger zusammenbraut, späht er unter den Zwergen und Gnomen nach fähigen Händen, die wissen, wie man eine kalte Klinge führt und im Schatten bleibt, und lädt Euch ein, ihn für weiteres Training aufzusuchen.",al={"warum habe ich die verschlüsselte rune","warum schickte solm die verschlüsselte rune","zweck verschlüsselte rune"}}},fp="14,147,15.284.0,19.268.0,27.156.0,28.101.0,29.86.0,29.111.0"}
P.entries["item:encrypted-scroll"] = {n="Verschlüsselte Rolle",s="In Todesend ruft eine versiegelte Rolle einen frisch auferstandenen Schurken zu David Trias. Ihre verschlüsselten Worte weisen dem Träger den Weg zum Gasthaus und zu den ersten Schritten in die verdeckten Reihen der Verlassenen.",h="In Todesend ruft eine versiegelte Rolle einen frisch auferstandenen Schurken zu David Trias.",kw={"david trias","todesend","verschlüsselte rolle","schurken der verlassenen","schurkenlehrer","shadowstalkers","tirisfal"},ang={["class:Rogue"]="Als Schurke beginnt Ihr unter den wachsamen Augen des Schurkenkaders der Verlassenen Eure Ausbildung in Heimlichkeit, Schlösserknacken und schmutzigen Kampftechniken.",["race:Undead"]="Als einer der frisch Auferstandenen in Todesend habt Ihr früh die Gelegenheit, eine sinnvolle Aufgabe in Sylvanas’ entstehendem Königreich zu finden."},sec={{t="Ein geheimer Ruf",b="Ein frisch erwachter Verlassener mit einer Begabung für Heimlichkeit erregt in Todesend Aufmerksamkeit. Nachdem sich ein Späher gegen die geistlose Geißel auf dem nahen Friedhof bewährt hat, wird ihm die Verschlüsselte Rolle überreicht. Schurkenlehrer David Trias hat sie versiegelt und fordert den Träger auf, ihn im örtlichen Gasthaus aufzusuchen. Der Ruf bietet einem angehenden Agenten eine Ausbildung im Dienst der Dunklen Fürstin, statt ein zweites Leben als Taschendieb zu verbringen."},{t="Augen der Shadowstalkers",b="Die kurze Botschaft der Rolle fordert den Schurken auf, in Todesend Kontakt aufzunehmen, bevor er tiefer nach Tirisfal vordringt. Trias hält im Auftrag der Shadowstalkers, des verdeckten Arms der Verlassenen, nach vielversprechenden Talenten Ausschau. In Lordaeron setzen die Verlassenen gegen den Scharlachroten Kreuzzug, verbliebene Enklaven der Allianz und die zurückgebliebene Geißel auf lautlose Klingen und gerissene Späher. Wer dem verschlüsselten Ruf folgt, beginnt seinen Weg in dieses verdeckte Netzwerk."}},faq={{q="Welchen Zweck hat die Verschlüsselte Rolle?",a="Die Verschlüsselte Rolle ruft einen frisch auferstandenen Schurken der Verlassenen zu David Trias ins Gasthaus von Todesend, um seine Schurkenausbildung zu beginnen.",al={"was bewirkt die rolle","warum verschlüsselte rolle","zweck der rolle"}},{q="Wer schickt die Verschlüsselte Rolle?",a="Die Verschlüsselte Rolle trägt das persönliche Siegel von David Trias. Er ist der Schurkenlehrer in Todesend und hält nach vielversprechenden Rekruten Ausschau.",al={"wer schrieb die rolle","absender der rolle","von wem stammt die rolle"}},{q="Wer sind die Shadowstalkers, die David Trias erwähnt?",a="Die Shadowstalkers sind eine verdeckt arbeitende Gruppe der Verlassenen aus Schurken, Spähern und Assassinen, die in ganz Lordaeron tätig ist. David Trias prüft neue Talente für ihre Reihen.",al={"wer sind die shadowstalkers","shadowstalkers verlassene","orden der shadowstalkers"}},{q="Wohin bringe ich die Verschlüsselte Rolle, nachdem ich sie gelesen habe?",a="Bringt die Verschlüsselte Rolle zu David Trias im Gasthaus von Todesend.",al={"wo die rolle abgeben","wem die rolle bringen","rolle abgeben"}}},fx={["0c548ac5"]={q="Was ist die Verschlüsselte Rolle?",a="Die Verschlüsselte Rolle ist eine diskrete, chiffrierte Depesche, die an frisch erwachte Schurken in Todesend geliefert wird. Gestempelt mit dem persönlichen Siegel des Schurkenausbilders David Trias, dient sie als erste Vorladung und Vertraulichkeitstest und weist vielversprechende Tarnungsagenten an, sich vorzustellen, bevor sie tiefgreifendere Aufklärungsarbeiten für die Verlassenen übernehmen.",al={"was ist verschlüsselte rolle","was ist diese rolle","info verschlüsselte rolle"}},["496fc5eb"]={q="Warum möchte David Trias Euch mit der Verschlüsselten Rolle kontaktieren?",a="David Trias benutzt die Rolle, um frische Talente unter den neu auferstandenen Verlassenen zu rekrutieren und zu beurteilen. Die Schattenpirscher und die junge Nation benötigen scharfe, fähige Infiltratoren und keine ungeschickten Taschendiebe. Indem er vielversprechende Rekruten leise in die Taverne von Todesend ruft, stellt er sicher, dass angehende Agenten eine ordnungsgemäße Ausbildung erhalten und auf dem Pfad bleiben, dem Geheimdienstnetzwerk der Dunklen Fürstin zu dienen.",al={"warum schickt david trias die rolle","warum ist verschlüsselte rolle begehrt","warum kontaktiert mich verschlüsselte rolle"}}},fp="16,182,16.406.0,26.445.0,44.123.0,31.131.0,53.156.0,54.66.0"}
P.entries["item:encrypted-sigil"] = {n="Verschlüsseltes Siegelzeichen",s="Im Laubschattental ruft das Verschlüsselte Siegelzeichen neu erwachte Nachtelfenschurken zu Frahun Schattenflüsterer. Er beginnt ihre Ausbildung, während sich Gefahren um Teldrassil zusammenbrauen.",h="Im Laubschattental ruft das Verschlüsselte Siegelzeichen neu erwachte Nachtelfenschurken zu Frahun...",kw={"aldrassil","verschlüsseltes siegelzeichen","frahun schattenflüsterer","kaldorei schurke","schurkenlehrer","laubschattental","teldrassil"},ang={["class:Rogue"]="Als Schurke beginnt Ihr Euren Weg, indem Ihr den verborgenen Anweisungen des Siegelzeichens folgt und Euren Mentor trefft.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass verdeckte Agenten lebenswichtige Informationen sammeln, während die Kaldorei mit neuen Vorstößen der Horde konfrontiert sind. Dies ist eine Zeit fragiler Verhältnisse."},sec={{t="Ein verborgener Ruf",b="Neue Kundschafter und Infiltratoren der Nachtelfen im Laubschattental erhalten das Verschlüsselte Siegelzeichen auf diskretem Wege. Ein stiller Bote überbringt es im Auftrag von Frahun Schattenflüsterer. Seine verborgenen Anweisungen weisen jeden Initianden an, sich bei Frahun nahe Aldrassil zu melden. Indem ein Initiand die Wertmarke liest und überbringt, zeigt er, dass er subtilen Anweisungen folgen und geheime Botschaften übermitteln kann."},{t="Augen in den Schatten",b="Frahun erklärt, warum Schurken in einer unruhigen Welt wichtig sind. Zwischen den Nachtelfen und der fernen Horde schwelen Spannungen, doch offener Krieg ist nicht ihre einzige Gefahr. Schurken müssen als ungesehene Augen und Klingen der Kaldorei in ganz Teldrassil Informationen sammeln. Sie müssen lernen, zuzuschlagen, bevor Bedrohungen in den Ästen des Weltbaums Wurzeln schlagen."}},faq={{q="Welchen Zweck hat das Verschlüsselte Siegelzeichen?",a="Das Verschlüsselte Siegelzeichen ruft angehende Nachtelfenschurken zum Beginn ihrer Ausbildung. Seine verborgenen Anweisungen weisen Euch an, Euch bei Frahun Schattenflüsterer nahe Aldrassil zu melden.",al={"was bewirkt das siegelzeichen","wozu dient das verschlüsselte siegelzeichen","warum habe ich das verschlüsselte siegelzeichen"}},{q="Wer schickt das Verschlüsselte Siegelzeichen?",a="Frahun Schattenflüsterer schickt das Verschlüsselte Siegelzeichen. Er bildet im Laubschattental unter den Ästen Aldrassils Schurken aus.",al={"wer hat dieses siegelzeichen geschrieben","wer hat das verschlüsselte siegelzeichen geschickt","von wem ist das siegelzeichen"}},{q="Was will Frahun Schattenflüsterer von mir?",a="Frahun will Eure Bereitschaft beurteilen und Euch über die Gefahren für die Nachtelfen unterrichten, darunter mögliche Zwietracht, die von der Horde geschürt wird. Er unterweist Euch auch in den Grundlagen des Kampfes.",al={"warum will frahun mich sehen","frahun quest","warum mit frahun sprechen"}},{q="Wohin soll ich das Siegelzeichen bringen, nachdem ich es gelesen habe?",a="Bringt das Siegelzeichen zu Frahun Schattenflüsterer nahe Aldrassil im Laubschattental.",al={"wohin das verschlüsselte siegelzeichen bringen","frahun standort","wo ist frahun"}}},fx={f0a92b78={q="Was ist das Verschlüsselte Siegelzeichen?",a="Das Verschlüsselte Siegelzeichen ist eine codierte Nachricht, die an vielversprechende Nachtelf-Schurken geliefert wird, die ihre Reise im Laubschattental beginnen. Markiert mit verborgener Schrift, um sensible Angelegenheiten vor neugierigen Blicken zu schützen, dient sie als offizielle Vorladung des lokalen Schurkenausbilders Frahun Schattenflüsterer, der danach strebt, frische Talente für die schattenhaften Herausforderungen zu bewerten und zu betreuen, denen ihr Volk gegenübersteht.",al={"was ist verschlüsseltes siegelzeichen","verschlüsseltes siegelzeichen hintergrund","was macht das siegelzeichen"}},["66ac44ca"]={q="Warum möchte Frahun Schattenflüsterer, dass das Verschlüsselte Siegelzeichen zurückgebracht wird?",a="Frahun Schattenflüsterer bittet Euch, das Siegelzeichen nach dem Entschlüsseln zu ihm zurückzubringen, um zu bestätigen, dass Ihr die Vorladung erhalten habt und die Geheimhaltungsvorschriften diskret befolgen könnt. Das Vorzeigen des Zeichens bestätigt Eure Identität und Eure Bereitschaft, Eure formale Ausbildung in Heimlichkeit, Informationsbeschaffung und Waffenführung zu beginnen.",al={"warum möchte frahun das siegelzeichen","warum verschlüsseltes siegelzeichen zurückbringen","wer möchte verschlüsseltes siegelzeichen"}}},fp="15,158,16.357.0,19.337.0,43.154.0,30.107.0,43.181.0,45.67.0"}
P.entries["item:encrypted-tablet"] = {n="Verschlüsselte Schrifttafel",s="Im Tal der Prüfungen schickt eine verschlüsselte Tafel angehende Trollschurken zu Rwag. Der Schurkenlehrer ritzt die Botschaft ein und hält seinen Posten im Den.",h="Im Tal der Prüfungen schickt eine verschlüsselte Tafel angehende Trollschurken zu Rwag.",kw={"durotar","verschlüsselte schrifttafel","schurkenlehrer","rwag","shattered hand","the den","das tal der prüfungen"},ang={["class:Rogue"]="Als Schurke erhaltet Ihr die verschlüsselte Schiefertafel als ersten Schritt in die offiziellen Reihen der Horde. Sie verweist Euch auf Rwags Ausbildung im Den.",["race:Troll"]="Als Dunkelspeer-Troll in der Ausbildung in Durotar erhaltet Ihr diese Tafel als Beweis, dass Eure Gewandtheit und Heimlichkeit die Aufmerksamkeit der Ausbilder des Tals geweckt haben."},sec={{t="Ein verborgener Ruf",b="Angehende Trollschurken erhalten die Verschlüsselte Schrifttafel, wenn sie das Tal der Prüfungen erreichen. Ihre verschlüsselten Worte weisen sie zu Rwag, einem Orc-Ausbilder, der in den schattigen Höhlen des Den lebt. Die Schiefertafel hält die Geschäfte der örtlichen Schattenagenten geheim und prüft, ob neue Rekruten ihre Botschaft verstehen können."},{t="Augen der Hand",b="Die Tafel bringt Rekruten mit dem weitreichenden Schattennetzwerk der Horde in Kontakt. Wenn sie sich bei Rwag melden, erfahren die Späher, dass Syndikate wie die Shattered Hand ihre Fortschritte beobachten. Diese Syndikate verlassen sich auf die Ausbilder des Tals, um zu beurteilen, ob angehende Beutelschneider, Spione und Attentäter scharfsinnig genug sind, der neuen Nation zu dienen."}},faq={{q="Wozu dient die Verschlüsselte Schrifttafel?",a="Die Verschlüsselte Schrifttafel weist junge Trollschurken an, sich bei Rwag zu melden, dem Schurkenlehrer im Den im Tal der Prüfungen.",al={"zweck der tafel","was bewirkt die verschlüsselte schrifttafel","warum habe ich die verschlüsselte schrifttafel"}},{q="Wer hat die Botschaft auf der Tafel geschrieben?",a="Rwag hat die Botschaft auf der Tafel geschrieben. Der Schurkenlehrer im Tal der Prüfungen beaufsichtigt die Ausbildung von Dieben, Beutelschneidern und Attentätern im Dienst der Horde.",al={"wer hat die verschlüsselte schrifttafel geschickt","verfasser der tafel","wer hat das geschrieben"}},{q="Wo finde ich Rwag?",a="Rwag befindet sich im Den, einem Höhlenkomplex entlang des nördlichen Bergrückens des Tals der Prüfungen in Durotar.",al={"wo ist rwag","rwag standort","schurkenlehrer im tal der prüfungen finden"}},{q="Was ist die „Hand“, die Rwag erwähnt?",a="Die Hand ist die Shattered Hand, ein geheimer Orden im Schurkennetzwerk der Horde. Rwag berichtet ihr über die Einsatzbereitschaft neuer Agenten aus dem Tal.",al={"welche hand","wer ist die hand","verbindung zur shattered hand"}}},fx={["395214f3"]={q="Was ist die Verschlüsselte Schrifttafel?",a="Die Verschlüsselte Schrifttafel ist eine codierte Steintafel, die speziell an Euch geliefert wird, sobald Ihr Eure Ausbildung im Tal der Prüfungen beginnt. Verschlüsselt, um ihren Inhalt vor neugierigen Blicken zu schützen, dient sie als Vorladung, um Eure Klugheit zu testen und Euch zum lokalen Schurkenausbilder zu führen.",al={"verschlüsselte schrifttafel","was ist verschlüsselte schrifttafel","gegenstand schrifttafel"}},["3f134c2e"]={q="Warum ist die Verschlüsselte Schrifttafel begehrt?",a="Der Schurkenausbilder Rwag sandte die Schrifttafel, um sicherzustellen, dass neu angekommene Schurken ihren Weg zu seinem Unterschlupf finden. Durch das Entschlüsseln der verschlüsselten Nachricht beweist Ihr, dass Ihr über den Verstand verfügt, der von einem Schurken verlangt wird, und erfahrt genau, wo Ihr seinen Rat suchen sollt.",al={"warum möchte man verschlüsselte schrifttafel","warum wird schrifttafel benötigt","wer möchte verschlüsselte schrifttafel"}}},fp="16,149,16.301.0,16.328.0,38.124.0,36.154.0,21.101.0,37.156.0"}
P.entries["item:essence-of-nightlash"] = {n="Nachtseeles Essenz",s="Auf den Dead Fields hinterlässt Nightlashs Niederlage eine Spur, die die Verlassenen mitnehmen können. Hochexekutor Hadrec braucht sie als Beweis, dass die Streitmacht der Geißel hinter den Moderfellgnollen gebrochen wurde.",h="Auf den Dead Fields hinterlässt Nightlashs Niederlage eine Spur, die die Verlassenen mitnehmen können.",kw={"banshee","dead fields","staub","essenz","hadrec","nightlash","moderfell","das grabmal"},ang={["class:Mage"]="Als Magier könnt Ihr die Rückstände vernichteter Banshees untersuchen, um zu erfahren, wie geisterhafte Untote nekrotische Magie an die physische Welt binden.",["race:Undead"]="Als Verlassener wisst Ihr, warum es wichtig ist, Banshees wie Nightlash zu vernichten. Einst selbst Opfer der Herrschaft der Geißel, bekämpfen die Verlassenen die Agenten des Lich King, um Lordaeron für ihr eigenes Volk zu sichern."},sec={{t="Die Banshee der Dead Fields",b="Auf dem verlassenen Gehöft namens Dead Fields im nördlichen Silberwald halten Rudel untoter Moderfellgnolle unter dem Befehl der Geißel ihre Stellung. Angriffe der Verlassenen sind immer wieder gescheitert. Die wilden Gnolle sind nicht die Ursache; ihre geisterhafte Befehlshaberin Nightlash schlägt die Angreifer zurück.\n\nIhre klagende Magie stärkt die Reihen der Gnolle und schlägt die aus dem Grabmal entsandten Streitkräfte in die Flucht. Wird Nightlash getötet, zerfällt ihre unkörperliche Gestalt zu Staub und hinterlässt eine kristalline magische Essenz."},{t="Beweis der Geißelniederlage",b="Banshees hinterlassen keinen körperlichen Leichnam, daher ist Nightlashs Essenz der einzige greifbare Beweis dafür, dass der Geist vernichtet wurde. Hochexekutor Hadrec im Grabmal braucht sie, um zu bestätigen, dass der Stützpunkt der Geißel gefallen ist. Mit diesem Beweis können die Verlassenen ihre nördliche Grenze sichern und die Bedrohung durch die Moderfelle eindämmen."}},faq={{q="Was ist Nachtseeles Essenz?",a="Nightlashs Niederlage hinterlässt kristallinen Staub. Da Geister keine physischen Körper haben, beweist der Rückstand, dass die Banshee der Geißel vernichtet wurde.",al={"nachtseeles essenz","nightlash staub","was ist nachtseeles essenz"}},{q="Wer ist Nightlash?",a="Auf den Dead Fields im nördlichen Silberwald befehligt und stärkt Nightlash die Moderfellgnolle im Dienste der Geißel.",al={"wer ist nightlash","nightlash hintergrundgeschichte","banshee nightlash"}},{q="Wer will diese Essenz?",a="Hochexekutor Hadrec im Grabmal will die Essenz als Beweis dafür, dass Nightlash besiegt wurde. Sie schlug seine Angriffe an der Front zurück.",al={"wer braucht nachtseeles essenz","bei wem essenz abgeben","hochexekutor hadrec"}},{q="Warum arbeiten die Gnolle mit einer Banshee zusammen?",a="Die Moderfellgnolle auf den Dead Fields sind der Seuche des Untodes erlegen und zu Knechten der Geißel geworden. Nightlash wurde entsandt, um sie zu beaufsichtigen und ihnen gegen Patrouillen der Verlassenen magische Unterstützung zu leisten.",al={"gnolle und geißel","moderfell geißel","warum gnolle mit banshee"}}},fx={["13c624cf"]={q="Woher kommt die Nachtseeles Essenz?",a="Die Essenz stammt von der Banshee Nachtseele selbst. Wenn Ihr sie bei The Dead Fields stellt und vernichtet, bricht ihre spektrale Form zusammen und ihre Essenz verwandelt sich in Staub, wobei das Überbleibsel zurückbleibt, das Ihr einsammelt.",al={"ursprung nachtseeles essenz","wie erhält man nachtseeles essenz","wo findet man nachtseeles essenz"}}},fp="20,188,30.494.0,23.314.0,33.148.0,17.114.0,23.133.0,42.188.0"}
P.entries["item:essential-artificial"] = {n="Grundlegendes Artifix",s="In Eisenschmiede helfen Teile des Grundlegenden Artifixes gnomischen Tüftlern und Ingenieuren beim Wiederaufbau nach der Vertreibung. Die Gnome ließen Vorräte zurück, als sie aus Gnomeregan flohen.",h="In Eisenschmiede helfen Teile des Grundlegenden Artifixes gnomischen Tüftlern und Ingenieuren beim...",kw={"künstlicher extrapolator","ingenieurskunst bauteil","grundlegendes artifix","gnomeregan","klockmort spannerspan","tüftlerstadt"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr erkennen, wie diese weitverbreiteten Teile in verschiedene Maschinen und experimentelle Konstruktionen passen.",["race:Gnome"]="Als Gnom helft Ihr durch die Bergung von Bauteilen aus Gnomeregans verstrahlten Korridoren Eurem Volk, seine technologische Überlegenheit wiederherzustellen, während es in Eisenschmiede Zuflucht sucht."},sec={{t="Erfindergeist als Standard",b="Vor dem Fall von Gnomeregan nutzten Tüftler das Grundlegende Artifix als vielseitiges Bauteil. Gnomische Ingenieure bauten es überall in den unterirdischen Hallen in Apparaturen, Uhrwerkwunder und schwere Maschinen ein. Dank seiner einheitlichen Bauweise konnten Schmiede und Maschinisten Teile bedenkenlos austauschen."},{t="Bergung aus der Tiefe",b="Die Trogg-Invasion und die Strahlungskatastrophe trieben die Gnome in verzweifelter Hast aus Gnomeregan. Große Vorräte an Teilen des Grundlegenden Artifixes blieben in schweren, dampfbetriebenen Spendern zurück, den sogenannten künstlichen Extrapolatoren, die über die tieferen Gänge verstreut sind.\n\nIn Tüftlerstadt sucht Handwerksmeister Klockmort Spannerspan wagemutige Abenteurer, die in die verseuchten Ruinen zurückkehren und die Teile bergen. Er braucht sie, damit Forschung und Erfindungen weitergehen können."}},faq={{q="Was ist ein Grundlegendes Artifix?",a="Das Grundlegende Artifix ist ein standardisiertes mechanisches Bauteil. Gnomische Schmiede und Tüftler verwenden es in Experimenten, Maschinen und Apparaturen.",al={"was sind grundlegende artifixe","grundlegendes artifix gegenstand","was ist dieses bauteil"}},{q="Warum wurden sie in Gnomeregan zurückgelassen?",a="Die Trogg-Invasion und die tödliche Strahlung zwangen die Gnome zur überstürzten Flucht. Vorräte an alltäglichen Bauteilen blieben in Lagervorrichtungen zurück.",al={"warum sind sie in gnomeregan","warum zurückgelassen"}},{q="Wer möchte diese Bauteile bergen lassen?",a="Klockmort Spannerspan, ein ehrgeiziger Erfinder in Tüftlerstadt in Eisenschmiede, sucht die Teile für seine Experimente und seine technologische Forschung im Exil.",al={"wer braucht grundlegende artifixe","wer nimmt diese an","klockmort spannerspan quest"}},{q="Wo sind sie in den Ruinen zu finden?",a="Große, dampfbetriebene Behälter, sogenannte künstliche Extrapolatoren, enthalten überall in den tieferen Ebenen des verseuchten Gnomeregan Teile des Grundlegenden Artifixes.",al={"wo sind grundlegende artifixe zu finden","künstlicher extrapolator fundort"}}},fx={["691fb1fc"]={q="Woher kommen Essential Artificials und wer hat sie hergestellt?",a="Essential Artificials sind präzise mechanische Komponenten, die von den Ingenieuren und Schmieden von Gnomeregan vor dem Fall ihrer großen Stadt entworfen und hergestellt wurden. Sie wurden in Massenproduktion für gnomische Technologie gefertigt und in automatisierten Spendern gelagert, die als künstliche Extrapolatoren bekannt sind und in den tieferen Industriekomplexen der Stadt aufgestellt waren.",al={"wer stellte essential artificials her","ursprung essential artificials","woher stammen essential artificials"}}},fp="20,157,24.294.0,23.448.0,32.141.0,40.139.0,37.150.0,38.152.0"}
P.entries["item:etched-note"] = {n="Geätzte Notiz",s="In Camp Narache ruft Lanka Weitschuss einen jungen Taurenjäger zum Beginn seiner Ausbildung. Der Jägerlehrer des Lagers heißt den Neuling in den Traditionen der Jagd willkommen.",h="In Camp Narache ruft Lanka Weitschuss einen jungen Taurenjäger zum Beginn seiner Ausbildung.",kw={"camp narache","geätzte notiz","lanka weitschuss","mulgore","die hochwolkenebene","taurenjäger","aufforderung des lehrers"},ang={["class:Hunter"]="Als Jäger markiert die Notiz Euren förmlichen Eintritt in die Jägertradition. Lankas Lektionen lehren Euch, mit Fernkampfwaffen umzugehen und mit den Wildtieren der Ebenen Zwiesprache zu halten.",["race:Tauren"]="Als Tauren tragt Ihr die Erwartungen Eurer Ältesten und Eurer Blutlinie. Die Notiz fordert Euch auf, Mulgore mit seinem hügeligen Grasland zu meistern, bevor Ihr in ferne Länder reist."},sec={{t="Ein Ruf zur Jagd",b="In Camp Narache bringt ein Läufer jungen Shu'halo eine Botschaft von Lanka Weitschuss, dem Jägerlehrer des Lagers. Die Notiz bezeichnet den Jäger als das Herz des Stammes. Natürlicher Instinkt allein genügt nicht. Der Jäger braucht strenge Unterweisung und tiefe Ehrfurcht vor der Wildnis von Mulgore."},{t="Traditionen der Shu'halo",b="Für die Tauren ist die Jagd heilig und zum Überleben notwendig. Sie ist fest mit dem Stammesleben verwoben. Jäger wirken an der Seite von Kriegern, Schamanen und Druiden, und der Stamm erwartet von ihnen Führung und Schutz. Der Schüler bringt die Notiz zu Lanka, um die Waffenkunst zu erlernen und die Wildtiere verstehen zu lernen. Diese Lektionen bereiten den Schüler darauf vor, die Stämme zu verteidigen und zu versorgen."}},faq={{q="Welchen Zweck hat die Geätzte Notiz?",a="Die Geätzte Notiz fordert einen unerfahrenen Taurenjäger auf, sich bei Lanka Weitschuss in Camp Narache einzufinden. Dort beginnt die geregelte Ausbildung in Schießkunst und Tierkunde.",al={"was bewirkt die notiz","geätzte notiz verwendung","warum habe ich die geätzte notiz erhalten"}},{q="Wer hat diese Notiz geschrieben?",a="Lanka Weitschuss, der Jägerlehrer in Camp Narache, hat die Notiz geschrieben. Er schickt Boten über die Hochebene, um junge Jäger zu finden, die bereit sind zu lernen.",al={"wer hat die geätzte notiz geschickt","wer hat sie geschrieben","geätzte notiz verfasser"}},{q="Warum ist die Jagd für die Tauren so wichtig?",a="Die Jagd sichert das Überleben der Tauren und erhält ihre Spiritualität und Stammestradition. Geschickte Jäger beschaffen Nahrung und Materialien, leben dabei im Einklang mit dem Land und ehren die Geister der Tiere, die sie erlegen.",al={"hintergrund der taurenjäger","warum jagen tauren","jagd in der kultur der tauren"}},{q="Wohin soll diese Notiz gebracht werden?",a="Bringt die Geätzte Notiz zu Lanka Weitschuss nahe dem Pavillon und den Übungsplätzen in Camp Narache auf der Hochwolkenebene.",al={"wohin bringe ich die notiz","bei wem gebe ich das ab","geätzte notiz abgeben"}}},fx={["10b0f74a"]={q="Was ist die Geätzte Notiz?",a="Die Geätzte Notiz ist eine schriftliche Vorladung, die sich speziell an angehende Tauren-Jäger richtet, die im Camp Narache eintreffen. Mit einer kurzen Botschaft des Jägerausbilders des Lagers, Lanka Weitschuss, versehen, erinnert sie Euch daran, dass Jäger das Herz des Stammes sind, und bittet Euch, ihn im Camp Narache aufzusuchen, um mit der Meisterung der Jagdkunst zu beginnen.",al={"was ist geätzte notiz","gegenstand geätzte notiz","geätzte notiz mulgore"}},bd70af04={q="Warum möchte Lanka Weitschuss, dass Ihr ihm die Geätzte Notiz bringt?",a="Lanka Weitschuss lässt die Notiz überbringen, um vielversprechende junge Jäger direkt unter seine Fittiche zu nehmen. Er beabsichtigt, Eure Bereitschaft zu prüfen und Euch in die lebenswichtigen Traditionen der Jagd einzuweisen – vom Umgang mit Fernkampfwaffen bis hin zur Zähmung von Bestien –, um sicherzustellen, dass Ihr den Stamm auf den Ebenen von Mulgore dienen und beschützen könnt.",al={"warum geätzte notiz überbringen","warum möchte lanka geätzte notiz","zweck geätzte notiz"}}},fp="11,154,18.268.0,26.366.0,39.162.0,20.138.0,42.199.0,34.116.0"}
P.entries["item:etched-parchment"] = {n="Geätztes Pergament",s="Im Tal der Prüfungen schickt Gornek neue Jäger zu Jen'shan, um in Durotar ihre ersten Lektionen zu erhalten.",h="Im Tal der Prüfungen schickt Gornek neue Jäger zu Jen'shan, um in Durotar ihre ersten Lektionen zu erhalten.",kw={"durotar","geätztes pergament","gornek","jäger","jen'shan","lehrer","das tal der prüfungen"},ang={["class:Hunter"]="Als Jäger erhaltet Ihr dieses Schreiben als Euren ersten Übergangsritus in Durotar. Es führt Euch zu Jen'shan, die Spurenlesen, den Umgang mit Fernkampfwaffen und das Überleben lehrt.",["faction:Horde"]="Als Mitglied der Horde verfeinert Ihr Euer Handwerk. Für einen Jäger ist dieses Pergament der erste Schritt, um seinen Klan zu ernähren und Durotars Grenzen zu bewachen."},sec={{t="Ein Ruf zur Jagd",b="Junge Orcs und Dunkelspeertrolle beginnen ihre Riten im Tal der Prüfungen. Während sich die Rekruten gegen das örtliche Ungeziefer beweisen, hilft Gornek ihnen, ihre Berufung zu finden. Er gibt das Geätzte Pergament jenen, die Bogen, Schusswaffe und Reißzahn führen werden. Seine Botschaft stammt von Jen'shan, einer erfahrenen Jägerlehrerin, die frische Augen und ruhige Hände sucht."},{t="Die erste Lektion",b="Wer das Pergament zu Jen'shan bringt, beginnt seine Ausbildung zum Jäger in Durotar. Sie lehrt, dass der Pfad der Wildnis Hingabe verlangt. Die Bestien der Wüste zu meistern, erfordert ebenso viel Mühe wie die Magie eines Arkanisten oder die Arbeit eines Schamanen mit den Geistern. Ihr Ruf führt neue Jäger zu Lektionen in Treffsicherheit und im Überleben in der Wildnis."}},faq={{q="Wozu dient das Geätzte Pergament?",a="Das Geätzte Pergament führt neue Jäger im Tal der Prüfungen zu ihrer Lehrerin Jen'shan.",al={"geätztes pergament verwendung","was bewirkt geätztes pergament"}},{q="Wer überreicht dieses Pergament?",a="Gornek gibt das Pergament jungen Jägern nahe The Den im Tal der Prüfungen.",al={"wer gibt geätztes pergament","geätztes pergament questgeber"}},{q="Wer hat das Geätzte Pergament geschrieben?",a="Jen'shan hat die Botschaft geschrieben. Sie ist eine Jägerlehrerin der Trolle im Tal der Prüfungen und bereit, neue Schützen auszubilden.",al={"wer hat geätztes pergament geschickt","verfasser des pergaments"}},{q="Wo ist Jen'shan zu finden?",a="Jen'shan wartet im Tal der Prüfungen in Durotar nahe den Übungsplätzen, um angehende Jäger der Orcs und Trolle zu unterweisen.",al={"wo ist jenshan","jenshan finden"}}},fx={ddc4492f={q="Was ist das Geätzte Pergament?",a="Das Geätzte Pergament ist eine schriftliche Vorladung, die sich speziell an angehende Jäger richtet, die im Tal der Prüfungen eintreffen. Von Gornek überreicht, enthält sie einen direkten Aufruf, den lokalen Jägerausbilder Jen'shan aufzusuchen, damit Ihr lernen könnt, wie Ihr in den rauen roten Einöden von Durotar überlebt und die wilden Bestien meistert, die sie durchstreifen.",al={"was ist geätztes pergament","gegenstand geätztes pergament","über geätztes pergament"}},f14a07d9={q="Warum möchte Jen'shan, dass Ihr Ihr das Geätzte Pergament zurückbringt?",a="Jen'shan bewahrt das Pergament nicht als geschätztes Relikt auf; sie nutzt es als formelle Vorladung, um angehende Jäger zu sich zu rufen. Es abzuliefern bestätigt, dass Ihr ihrem Ruf gefolgt seid und bereit seid, in den tödlichen Künsten des Bogenschießens, der Treffsicherheit und dem Überleben inmitten der wilden Raubtiere von Durotar unterwiesen zu werden.",al={"warum geätztes pergament bringen","warum möchte jenshan das pergament","zweck von geätztem pergament"}}},fp="16,97,21.334.0,16.321.0,33.91.0,29.81.0,31.111.0,28.119.0"}
P.entries["item:etched-rune"] = {n="Geätzte Rune",s="Im Coldridgetal ruft die Geätzte Rune vielversprechende Zwergenjäger nach Ambossar. Jägerlehrer Thorgas Grimson schickt sie, um ihre Ausbildung in der Wildnis einzuleiten.",h="Im Coldridgetal ruft die Geätzte Rune vielversprechende Zwergenjäger nach Ambossar.",kw={"ambossar","das coldridgetal","dun morogh","zwergenjäger","geätzte rune","jägerausbildung","thorgas grimson"},ang={["class:Hunter"]="Als Jäger ruft Euch die Rune zum Jagdhandwerk der Zwerge. Ihr lernt, Fährten zu lesen, Eure Tiergefährten zu respektieren und dank Eures eigenen Verstands in der Wildnis zu überleben.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass behauene Steine und Runen handwerkliches Wissen und dringende Anweisungen durch den Schnee des Coldridgetals tragen."},sec={{t="Ruf der Wildnis",b="Zwergenrunen zieren die Geätzte Rune, die an Neulinge geschickt wird, die in den Schneewehen des Coldridgetals Talent zeigen. Der Gebirgsjäger und Jägerlehrer Thorgas Grimson ruft angehende Fährtenleser nach Ambossar. Dort gehen sie über das bloße Überleben hinaus und erlernen das Jägerhandwerk: Respekt vor den Wildtieren von Dun Morogh, das Aufspüren von Gebirgsraubtieren, die Pflege von Fernkampfwaffen und Ausdauer unter den rauen Elementen."}},faq={{q="Welchen Zweck erfüllt die Geätzte Rune?",a="Die Geätzte Rune ruft angehende Zwergenjäger dazu auf, Thorgas Grimson in Ambossar aufzusuchen, um im Jägerhandwerk unterwiesen zu werden.",al={"was bewirkt die geätzte rune","geätzte rune verwendung","warum habe ich die geätzte rune"}},{q="Wer hat die Geätzte Rune verfasst oder geschickt?",a="Thorgas Grimson, der Jägerlehrer in Ambossar, schickt die Rune an Neulinge im Coldridgetal, die ein Gespür für das Überleben in der eisigen Wildnis zeigen.",al={"wer hat die geätzte rune geschickt","wer hat mir diese rune gegeben","geätzte rune verfasser"}},{q="Wohin bringe ich die Geätzte Rune, nachdem ich sie gelesen habe?",a="Bringt die Geätzte Rune nach Ambossar im Coldridgetal. Thorgas Grimson wartet nahe der Schmiede und den Ausbildungshallen, um Euch das Fährtenlesen, die Waffenpflege und die Jagdtraditionen der Zwerge zu lehren.",al={"wohin bringe ich die geätzte rune","geätzte rune abgeben","thorgas grimson standort"}}},fx={["455fa37e"]={q="Was ist die Geätzte Rune?",a="Die Geätzte Rune ist eine gravierte Steintafel, die Zwergenjägern-Anfängern ausgehändigt wird, wenn sie ihre Ausbildung im Coldridgetal beginnen. Anstelle von gewöhnlichem Pergament dient sie als dauerhafte, mit Runen versehene Nachricht, die die tief verwurzelte Handwerkskunst und Tradition der Zwerge in Bezug auf das Überleben in der Wildnis widerspiegelt.",al={"was ist eine geätzte rune","geätzte rune gegenstand","geätzte rune lore"}},["537b1d7a"]={q="Warum möchte Thorgas Grimson, dass Ihr die Geätzte Rune bringt?",a="Die Rune ist ein formeller Aufruf zum Training, versandt von Thorgas Grimson, dem Jägerausbilder in Ambossar. Sie mit Euch zu führen bestätigt, dass Ihr grundlegende Fähigkeiten im Tal bewiesen habt und bereit seid, ernsthafte Anweisungen im Spurenlesen, in der Waffenwartung und in den Traditionen der Wildnis zu erhalten.",al={"warum möchte thorgas die rune","warum geätzte rune wollen","zweck der vorladung per geätzter rune"}}},fp="11,167,16.386.0,39.131.0,34.159.0,52.177.0"}
P.entries["item:etched-sigil"] = {n="Geätztes Siegelzeichen",s="Im Laubschattental ruft das Geätzte Siegelzeichen neue Nachtelfen-Jäger zu Ayanna Immerlauf.",h="Im Laubschattental ruft das Geätzte Siegelzeichen neue Nachtelfen-Jäger zu Ayanna Immerlauf.",kw={"aldrassil","ayanna immerlauf","geätztes siegelzeichen","jäger","laubschattental","teldrassil"},ang={["class:Hunter"]="Für Euch als Jäger markiert das Geätzte Siegelzeichen den Beginn Eurer Ausbildung im Umgang mit dem Bogen und den Eigenheiten der Tiere unter Ayanna Immerlauf.",["race:NightElf"]="Als Nachtelf erhaltet Ihr das Siegelzeichen im Laubschattental, inmitten der Baumkronentraditionen nachtelﬁscher Waldläufer, die Teldrassil beschützen."},sec={{t="Ruf der Wildnis",b="Neu erwachte Nachtelfen-Jäger erhalten das Geätzte Siegelzeichen, wenn sie das Laubschattental betreten. Seine eingeritzten Zeichen überbringen einen Willkommensgruß von Ayanna Immerlauf, der Jägerausbilderin, die hoch oben in Aldrassils ausgehöhlten Ästen lebt. Das Siegelzeichen schickt jeden Neuling zu ihr, um Bogenschießen und Fährtensuche in der Wildnis sowie die nachtelﬁsche Verbundenheit zwischen Pirschjäger und Tier zu erlernen."}},faq={{q="Welchen Zweck hat das Geätzte Siegelzeichen?",a="Das Geätzte Siegelzeichen ruft einen unerfahrenen Nachtelfen-Jäger dazu auf, Ayanna Immerlauf in Aldrassil aufzusuchen. Dort beginnt die Ausbildung in Überlebenskunst, Fährtensuche und Bogenschießen.",al={"was bewirkt das geätzte siegelzeichen","geätztes siegelzeichen verwendung","warum habe ich dieses siegelzeichen"}},{q="Wer schickt das Geätzte Siegelzeichen?",a="Ayanna Immerlauf, die Jägerausbilderin im Laubschattental, schickt das Geätzte Siegelzeichen.",al={"wer hat das geätzte siegelzeichen geschickt","woher stammt das geätzte siegelzeichen"}},{q="Wohin soll das Siegelzeichen gebracht werden?",a="Bringt das Siegelzeichen zu Ayanna Immerlauf oben auf Aldrassil im Laubschattental.",al={"wohin bringe ich das geätzte siegelzeichen","wem gebe ich das geätzte siegelzeichen"}},{q="Warum erhalten Nachtelfen-Jäger ein Siegelzeichen statt eines Briefes auf Papier?",a="Ayannas Willkommensgruß kommt als geschnitztes Siegelzeichen mit Zeichen der Jagd. Es spricht für sie und ruft jeden neuen Jäger dazu auf, sie in Aldrassil zu finden.",al={"warum ein siegelzeichen statt eines briefes","woraus besteht das siegelzeichen"}}},fx={fbac1def={q="Was ist das Geätzte Siegelzeichen?",a="Das Geätzte Siegelzeichen ist ein mit einer Vorladung versehenes Zeichen für angehende Nachtelfen-Jäger im Laubschattental. Es wird von einem Kurier getragen und Euch bei Eurer Ankunft in Teldrassil überreicht; es dient als offizielle Vorstellung bei Ayanna Immerlauf und lädt Euch ein, Eure formelle Ausbildung in Treffsicherheit und Tierausbildung unter den Zweigen von Aldrassil zu beginnen.",al={"was ist ein geätztes siegelzeichen","geätztes siegelzeichen gegenstand","über das geätzte siegelzeichen"}},e2d33d60={q="Warum möchte Ayanna Immerlauf, dass Ihr ihr das Geätzte Siegelzeichen bringt?",a="Ayanna Immerlauf sendet das Siegelzeichen, um sicherzustellen, dass Ihr wisst, wo Ihr im Laubschattental Anleitung findet. Es ihr oben auf Aldrassil zurückzubringen beweist, dass Ihr ihre Nachricht erhalten habt und bereit seid, Euer Training zu beginnen, um zu lernen, Bögen mit unfehlbarer Präzision zu führen und die wilden Kreaturen von Kalimdor zu respektieren.",al={"warum geätztes siegelzeichen bringen","warum möchte ayanna das siegelzeichen","wer möchte das geätzte siegelzeichen"}}},fp="12,81,20.363.0,40.149.0,27.76.0,32.66.0,68.141.0"}
P.entries["item:explosive-stick-of-gann"] = {n="Dynamitstange von Gann",s="Im südlichen Brachland setzt Gann Steinkeil gestohlene Zwergenpläne gegen Bael Modan ein. Er baute eine Sprengladung, um die Flugmaschine der Zwerge zu sabotieren.",h="Im südlichen Brachland setzt Gann Steinkeil gestohlene Zwergenpläne gegen Bael Modan ein.",kw={"bael modan","dynamitstange von gann","flugmaschine","gann steinkeil","zwergenprospektor khazgorm","stamm der stonespire","brachland"},ang={["profession:Engineering"]="Als Ingenieur könnt Ihr erkennen, wie gestohlene Baupläne gegen die Maschinen der Zwerge eingesetzt wurden.",["race:Tauren"]="Als Tauren könnt Ihr den vertriebenen Stamm der Stonespire rächen und gegen die Prospektoren zurückschlagen, die sich in den heiligen Boden Kalimdors gruben."},sec={{t="Eine Waffe der Vergeltung",b="Zwergenprospektor Khazgorm leitete die Ausgrabung von Eisenschmiede im südlichen Kalimdor. Die Zwerge vertrieben die Tauren der Stonespire aus ihrem angestammten Dorf und verwüsteten ihre heiligen Stätten, um Bael Modan zu errichten. Gann Steinkeil holte Khazgorms Baupläne zurück, um seine vertriebenen und gefallenen Angehörigen zu rächen. Er studierte die Pläne und baute eine Sprengladung, die stark genug war, um schwere Maschinen zu zerstören."},{t="Die Flugmaschine im Visier",b="Gann fertigte die Dynamitstange für die Flugmaschine der Zwerge auf einem Beobachtungsturm über der Ausgrabung an. Für ihn bedeutet die Maschine mehr als ein Transportmittel oder eine Kriegswaffe. Sie steht für die Herrschaft der Allianz über heiligen Taurenboden. Ihre Zerstörung würde den Zwergenaußenposten lahmlegen und einen Schlag für den verlorenen Stamm der Stonespire bedeuten."}},faq={{q="Was ist die Dynamitstange von Gann?",a="Gann Steinkeil fertigte die Sprengladung nach wiederbeschafften Zwergenbauplänen an, um die Maschinen der Prospektoren auf dem Land seiner Ahnen zu sabotieren.",al={"dynamitstange von gann","ganns dynamitstange","ganns bombe"}},{q="Wer hat diese Sprengladung hergestellt?",a="Gann Steinkeil baute die Sprengladung, um seinen Stamm zu rächen, nachdem die Zwerge aus Eisenschmiede bei Bael Modan ihr Dorf zerstört und ihre Heimat im südlichen Brachland entweiht hatten.",al={"wer hat das hergestellt","wer ist gann","gann steinkeil"}},{q="Was soll die Sprengladung in die Luft jagen?",a="Die Ladung soll die Flugmaschine der Zwerge auf einem Turm über der Ausgrabung bei Bael Modan zerstören. Ihre Zerstörung würde die Aufklärung der Ausgrabungsstätte lahmlegen und dem Stamm der Stonespire symbolische Vergeltung bringen.",al={"was soll gesprengt werden","flugmaschine als ziel","wo wird sie eingesetzt"}},{q="Wie lernte ein Tauren, Zwergensprengstoff herzustellen?",a="Gann baute die Dynamitstange nach technischen Bauplänen, die er von Zwergenprospektor Khazgorm erbeutet hatte, dem Leiter der Zwergenausgrabung bei Bael Modan. Er wandte die Technologie der Eindringlinge gegen sie selbst.",al={"wie hat gann sie gebaut","sprengstoffbaupläne","khazgorms pläne"}}},fp="23,148,23.363.0,25.321.1,36.143.0,24.180.0,42.215.0,50.180.0"}
P.entries["item:faded-shadowhide-pendant"] = {n="Verblasster Schattenfellanhänger",s="Im Rotkammgebirge erklingt nun eine Stimme aus dem Verblassten Schattenfellanhänger. Die Schattenfellgnolle trugen ihn, um Morganths Befehle zu empfangen, und die Stimme übermittelt Theocritus’ verzögerten Zauber.",h="Im Rotkammgebirge erklingt nun eine Stimme aus dem Verblassten Schattenfellanhänger.",kw={"elwynn","gnolle","morganth","anhänger","rotkammgebirge","schattenfell","theocritus","turm azora"},ang={["class:Mage"]="Als Magier könnt Ihr erkennen, dass magisches Abfangen selbst bei einfachen oder dunklen Verzauberungen möglich ist. Ein disziplinierter Zauberer kann sie entschlüsseln und unter seine Kontrolle bringen.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr dem Turm Azora, die Schattenfellgnolle zu schwächen, die den Wald von Elwynn und Seenhain bedrohen."},sec={{t="Ein durchbrochenes Netzwerk",b="Die Schattenfellgnolle des Rotkammgebirges folgen Morganth und nutzen verzauberte Anhänger, um ihre Bewegungen zu koordinieren. Von seinem Zufluchtsort am Turm Azora aus untersuchte Erzmagier Theocritus die Talismane und entwickelte einen Zauber, um in ihre Verbindung einzudringen. Wochen vergingen, bevor seine Übertragung sich zeigte. Nun beweist dieser verblasste Anhänger, dass die Nachrichten der Gnolle abgefangen werden können, und gibt Theocritus eine Möglichkeit, Morganths Einfluss einzuschränken."},{t="Das Streben des Magiers",b="Theocritus will den Anhänger untersuchen und herausfinden, wie seine Verzauberung dem Eingriff standgehalten hat. Er hofft, seine Zauberei zu verfeinern und über passende Amulette, die im gesamten Rotkammgebirge getragen werden, lähmende Angriffe zu senden. Der Anhänger muss den Turm Azora im Wald von Elwynn erreichen, wo er seine Arbeit gegen Morganths Herrschaft über die Gnolle der Region beginnen kann."}},faq={{q="Was ist der Verblasste Schattenfellanhänger?",a="Schattenfellgnolle im Rotkammgebirge trugen den Verblassten Schattenfellanhänger, um Morganths Befehle zu empfangen. Der Übertragungszauber von Erzmagier Theocritus hat ihn verändert.",al={"schattenfellanhänger","was ist dieser anhänger","theocritus anhänger"}},{q="Warum spricht eine Stimme aus dem Anhänger?",a="Die Stimme ist der Nachhall eines Zaubers, den Erzmagier Theocritus vor Wochen gewirkt hat. Nach monatelangen Studien fand er einen Zugang zur Kommunikationsverbindung der Anhänger, und die Nachricht zeigt, dass sein Zauber das Netzwerk der Gnolle erreicht hat.",al={"wer spricht","körperlose stimme","theocritus stimme"}},{q="Wer ist Theocritus?",a="Theocritus ist der Erzmagier am Turm Azora im östlichen Wald von Elwynn. Er erforscht dunkle Bedrohungen jenseits der Grenze im Rotkammgebirge, insbesondere den abtrünnigen Zauberer Morganth.",al={"theocritus hintergrundgeschichte","erzmagier theocritus","turm azora magier"}},{q="Wer ist Morganth?",a="Morganth ist ein finsterer, abtrünniger Magiewirker im Rotkammgebirge. Er befehligt die örtlichen Schattenfellgnolle durch verzauberte Anhänger.",al={"morganths identität","wer ist morganth","meister der gnolle"}},{q="Was plant Theocritus mit dem Anhänger?",a="Theocritus plant, die Verzauberung des Anhängers in seinem Labor zu untersuchen. Er hofft, lähmende Angriffe durch das Netzwerk zu senden und jeden Gnoll kampfunfähig zu machen, der einen passenden Anhänger trägt.",al={"warum will theocritus ihn","zweck des anhängers","anhänger als waffen nutzen"}}},fx={["6c0e263d"]={q="Woher stammt der Verblasste Schattenfellanhänger und wer hat ihn hergestellt?",a="Der Anhänger stammt von den Schattenfell-Gnollen aus dem Rotkammgebirge und ihrem dunklen Meister, dem abtrünnigen Magier Morganth. Morganth fertigte oder verzauberte diese Kleinodien als mystische Kanäle, um seine Befehle direkt an die Gnollrudel unter seinem Einfluss weiterzuleiten.",al={"wer hat den verblassten schattenfellanhänger hergestellt","woher stammt der schattenfellanhänger","ursprung des verblassten schattenfellanhängers"}}},fp="24,180,16.416.0,19.330.1,37.166.0,40.203.0,18.163.0,16.120.0,49.182.0"}
P.entries["item:fallen-moonstone"] = {n="Gefallener Mondstein",s="Am Himmelssturzsee im Eschental bergen Nachtelfen heilende Steine aus dem Wasser. Vom Mond gesegnet, kann ein Gefallener Mondstein bei schwerer Schwäche neue Kraft schenken.",h="Am Himmelssturzsee im Eschental bergen Nachtelfen heilende Steine aus dem Wasser.",kw={"eschental","astranaar","gefallener mondstein","himmelssturzsee","mondstein","pelturas weißmond","relara","shadethicket oracle"},ang={["class:Priest"]="Anhängerinnen der Sisterhood of Elune sehen im Mondschein der Steine ein Zeichen heilender Gnade.",["race:NightElf"]="Für die Kaldorei sind Relikte, die mit Elunes Glanz verbunden sind, heilige Werkzeuge zur Bewahrung des Lebens. Sie können göttliche Heilung bringen, wenn die Heilkunst der Sterblichen versagt."},sec={{t="Gaben des Nachthimmels",b="Südöstlich von Astranaar lagen einst viele Gefallene Mondsteine an den Ufern und in den Untiefen des Himmelssturzsees. Nachtelfen schätzten ihre Heilkraft, wenn gewöhnliche Heilmittel versagten. Doch verderbte Shadethicket-Moorbestien überrannten den See, angeführt von einem Shadethicket Oracle. Der Oracle hortete jeden Stein, den er fand, auf einer kleinen Insel inmitten des Sees und nahm den einheimischen Kaldorei damit eine lebenswichtige Heilquelle."},{t="Die Rettung eines Vaters",b="In Astranaar erkrankte die junge Relara Whitemoon schwer. Gewöhnliche Behandlungen senkten ihr Fieber, doch sie blieb ausgezehrt und dem Tode nahe. Ihr blieben nur wenige Atemzüge. Ihr Vater, Pelturas Weißmond, wusste, dass die geballte Macht eines Mondsteins ihre schwindenden Kräfte wiederherstellen konnte. Ein Stein aus dem Hort des Shadethicket Oracle gab Relara die Kraft zum Weiterleben."}},faq={{q="Was ist ein Gefallener Mondstein?",a="Ein Gefallener Mondstein leuchtet voller Magie aus dem Himmelssturzsee im Eschental. Seine heilige Mondenergie kann Nachtelfen, die unter schwerer Schwäche leiden, neue Kraft schenken.",al={"was ist ein gefallener mondstein","gefallener mondstein geschichte","mondstein eschental"}},{q="Wo findet man Gefallene Mondsteine?",a="Gefallene Mondsteine stammen aus dem Himmelssturzsee, südöstlich von Astranaar im Eschental. Einst lagen sie über den Seegrund verstreut, doch die feindseligen Shadethicket-Moorbestien sammelten sie auf einer Insel in der Mitte des Sees.",al={"wo findet man gefallene mondsteine","gefallener mondstein fundort"}},{q="Wer besitzt die Mondsteine am Himmelssturzsee?",a="Der Shadethicket Oracle hortete Gefallene Mondsteine auf einer Insel inmitten des Himmelssturzsees. Der Oracle führt die verderbten Moorbestien dort an.",al={"wer hat den gefallenen mondstein","shadethicket oracle mondstein"}},{q="Warum braucht Pelturas Weißmond einen Gefallenen Mondstein?",a="Pelturas Weißmond braucht einen Gefallenen Mondstein, um seine junge Tochter Relara zu retten. Sie überlebte ein entkräftendes Fieber, blieb jedoch lebensbedrohlich geschwächt, und er wusste, dass die Magie des Steins ihre Kräfte wiederherstellen konnte.",al={"pelturas weißmond tochter","warum mondstein nötig","relara heilung"}}},fp="16,166,22.395.0,20.350.1,27.157.0,34.191.0,48.145.0,52.204.0"}
P.entries["item:fandral-s-message"] = {n="Fandrals Nachricht",s="Fandrals Nachricht bringt Kunde aus Darnassus über das Meer zu Onu an der Dunkelküste. Die versiegelte Depesche betrifft die Lichtung des Orakels auf Teldrassil.",h="Fandrals Nachricht bringt Kunde aus Darnassus über das Meer zu Onu an der Dunkelküste.",kw={"urahne der lehren","auberdine","dunkelküste","darnassus","fandral hirschhaupt","fandrals nachricht","der hain der uralten","onu","die lichtung des orakels"},ang={["class:Druid"]="Als Druide zeigt Euch das Überbringen einer Nachricht zwischen der Enklave des Cenarius in Darnassus und den Urahnen der Lehren an der Dunkelküste die Kluft zwischen Fandral Hirschhaupts Tatendrang und der Geduld der älteren Wächter.",["race:NightElf"]="Als Nachtelf führt Euch diese Depesche von der Krone Teldrassils zu den angestammten Wäldern auf Kalimdors Festland."},sec={{t="Eine Depesche des Erzdruiden",b="Erzdruide Fandral Hirschhaupt schreibt aus der Enklave des Cenarius in Darnassus. Seine versiegelte Depesche richtet sich an Onu, den Urahnen der Lehren, der im Hain der Uralten weilt. Berichte über die Lichtung des Orakels auf Teldrassil haben Fandral erreicht, also schickt er einen Boten mit einer Nachricht für Onu südlich von Auberdine. Die Reise führt über das Meer zur Dunkelküste, vom neuen Weltenbaum zum älteren, schattigen Festland Kalimdors."},{t="Unterschiedliches Zeitmaß",b="Onu sagt, Fandral habe es immer eilig. Der Urahne der Lehren glaubt, dass die Dinge sich im eigenen Tempo der Natur entfalten sollten, wie es die Uralten für richtig halten. Für die gemächlich lebenden Treants der Dunkelküste hebt sich Fandrals Hast von der geduldigen Weisheit ab, die einst Erzdruide Malfurion Sturmgrimm zeigte."}},faq={{q="Was ist Fandrals Nachricht?",a="Fandrals Nachricht enthält eine versiegelte Depesche von Erzdruide Fandral Hirschhaupt an Onu, den Urahnen der Lehren im Hain der Uralten an der Dunkelküste.",al={"fandrals nachricht gegenstand","fandral nachricht","brief des erzdruiden"}},{q="Wer schickt diese Nachricht und warum?",a="Erzdruide Fandral Hirschhaupt schreibt aus Darnassus, nachdem ihn Berichte über die Lichtung des Orakels auf Teldrassil erreicht haben. Er schickt Onu an der Dunkelküste eine Nachricht.",al={"wer hat das geschrieben","warum schickt fandral eine nachricht"}},{q="Wohin muss diese Nachricht gebracht werden?",a="Bringt die Nachricht zu Onu im Hain der Uralten an der Dunkelküste, direkt südlich von Auberdine.",al={"wer erhält die nachricht","wo die nachricht abgeben","fandrals nachricht ziel"}},{q="Was hält Onu von dem Brief?",a="Onu sagt, Fandral habe es immer eilig. Der Urahne merkt an, dass die Natur ihrem eigenen Tempo folgt, eine Wahrheit, die Shan'do Malfurion Sturmgrimm besser verstand.",al={"onus reaktion","was sagt onu"}}},fx={["22d06606"]={q="Warum möchte Onu Fandrals Nachricht?",a="Onu, ein Uralter des Wissens, der im Grove of the Ancients an der Dunkelküste ruht, wartet auf ein Wort von Erzdruide Fandral Hirschhaupt bezüglich des Zustands von Teldrassil. Nachdem er Nachrichten aus der Lichtung des Orakels erhalten hatte, sandte Fandral Euch unverzüglich mit dieser Depesche über das Meer. Onu nimmt die Korrespondenz geduldig entgegen, wenngleich der Uralte leise darüber nachdenkt, dass der rastlose Erzdruide immer viel zu sehr in Eile zu sein scheint, verglichen mit der geduldigen Weisheit, die Shan'do Sturmgrimm einst zeigte.",al={"warum möchte onu die nachricht","warum benötigt onu fandrals brief","warum fandrals nachricht überbringen"}}},fp="17,139,29.410.0,18.276.1,26.142.0,31.142.0,35.96.0,34.149.0"}
P.entries["item:fang-of-bhag-thera"] = {n="Fangzahn von Bhag'thera",s="Bhag'theras Fang beweist das Können eines Jägers im Schlingendorntal. Sire S. J. Erlgadin verlangt ihn als letzte Prüfung in Panther Mastery.",h="Bhag'theras Fang beweist das Können eines Jägers im Schlingendorntal.",kw={"bhag'thera","fangzahn von bhag'thera","nesingwarys expedition","panther","panther mastery","sire s. j. erlgadin","schlingendorntal"},ang={["class:Hunter"]="Als Jäger markiert Bhag'theras Fang die letzte Prüfung in Sire S. J. Erlgadins Panther Mastery."},sec={{t="Der Beweis eines Jägers",b="Erlgadin schickt Euch auf die Jagd nach Bhag'thera, einem schwer fassbaren Panther, der nahe bei Nesingwarys Expedition durch den Dschungel streift. Seine Gruppe konnte die große Bestie nicht fangen, und Eure Jagd wird zeigen, ob Ihr Erlgadins Respekt verdient habt. Bringt ihm den Fang, und er wird Euch einen mächtigen Jäger nennen."}},faq={{q="Wer will Bhag'theras Fang?",a="Sire S. J. Erlgadin von Nesingwarys Expedition bittet Euch, ihm Bhag'theras Fang zu bringen.",al={"wer will ihn","fang für wen"}},{q="Was ist Bhag'thera?",a="Bhag'thera ist ein schwer fassbarer Panther, der im Schlingendorntal durch den Dschungel streift.",al={"wer ist bhag'thera","bhag'thera"}},{q="Warum will Erlgadin den Fang?",a="Der Fang beweist, dass Ihr Bhag'thera gejagt und Euch Erlgadins Respekt als Pantherjäger verdient habt.",al={"warum der fang","wofür ist er"}},{q="Wo finde ich Bhag'thera?",a="Bhag'thera streift nahe bei Nesingwarys Expedition durch den Dschungel im Schlingendorntal.",al={"wo ist bhag'thera","bhag'thera finden"}}},fp="18,141,16.283.0,28.86.0,19.75.0,32.98.0,28.81.0"}
P.entries["item:fang-of-vagash"] = {n="Fangzahn von Vagash",s="In Dun Morogh lauert Vagash den Widdern oberhalb des Gehöfts Bernruh auf. Sein Fangzahn beweist, dass das tödliche Raubtier erlegt wurde.",h="In Dun Morogh lauert Vagash den Widdern oberhalb des Gehöfts Bernruh auf.",kw={"gehöft bernruh","dun morogh","fangzahn von vagash","eisenschmiede","protecting the herd","widder","vagash"},ang={["class:Hunter"]="Vagash durch die eisigen Felsen von Dun Morogh zu verfolgen, stellt die Fähigkeiten eines Jägers im Spurenlesen, Überleben in der Wildnis und Erlegen von Bestien auf die Probe.",["race:Dwarf"]="Auf dem Gehöft Bernruh werden widerstandsfähige Bergwidder für zwergische Gebirgsjäger und Reisende gezüchtet. Vagashs Fangzahn zurückzubringen hilft, Eisenschmiedes geschätzte Reittierzucht zu bewahren."},sec={{t="Trophäe der Jagd",b="Oberhalb des Gehöfts Bernruh jagt Vagash im Schutz der Dunkelheit Widder. Die hohen Felsen bieten wilden Raubtieren Unterschlupf, doch keines hat den örtlichen Gehöften so sehr zugesetzt wie er. Die Truppen von Eisenschmiede sind überlastet, sodass die Hirten ohne den Schutz der Stadtwache auskommen müssen. Sein herausgetrennter Fangzahn liefert den Züchtern den Beweis, dass Vagash tot ist und ihre Weiden wieder sicher sind."}},faq={{q="Wozu dient der Fangzahn von Vagash?",a="Die Züchter auf dem Gehöft Bernruh in Dun Morogh nehmen Vagashs Fangzahn als Beweis dafür an, dass er erlegt wurde. Sie belohnen den Jäger, der ihre Lebensgrundlage beschützt hat.",al={"fangzahn von vagash verwendung","was tun mit fangzahn von vagash","fangzahn von vagash abgeben"}},{q="Wer ist Vagash?",a="Vagash ist eine tödliche Bestie, die in den verschneiten Hügeln oberhalb der Widderweiden von Dun Morogh haust. Nachts fällt er über die Herden her, und die einheimischen Zwerge fürchten ihn.",al={"was ist vagash","wo ist vagash","vagash hintergrundgeschichte"}},{q="Warum hat die Wache von Eisenschmiede Vagash noch nicht getötet?",a="Die Truppen von Eisenschmiede sind überlastet und können nur wenige Soldaten für Patrouillen auf dem Land entbehren. Die Viehzüchter müssen sich auf durchreisende Abenteurer verlassen, um gefährliche Raubtiere zu beseitigen.",al={"warum helfen die wachen nicht","wo ist die armee von eisenschmiede","gebirgsjäger vagash"}}},fx={fc16a334={q="Was ist der Fangzahn von Vagash?",a="Der Fangzahn von Vagash ist eine gewaltige Trophäe, die aus dem Maul von Vagash stammt, einem bösartigen Raubtier, das die Kämme von Dun Morogh durchstreift. Er dient als unbestreitbarer Beweis dafür, dass die bedrohliche Bestie endlich gejagt und erlegt wurde.",al={"was ist der fangzahn von vagash","fangzahn von vagash lore","fangzahn von vagash"}},["695a78ed"]={q="Woher stammt der Fangzahn von Vagash?",a="Dieser Fangzahn ist nicht künstlich hergestellt; er ist ein natürlicher Zahn, der aus dem Kiefer von Vagash selbst gebrochen wurde. Das grausame Ungeheuer hat seinen Bau in den verschneiten Hügeln direkt oberhalb des Gehöfts Bernruh.",al={"woher bekommt man den fangzahn von vagash","wer hat den fangzahn von vagash hergestellt","ursprung des fangzahns von vagash"}},f04ec442={q="Warum möchte Rudra Amberstill den Fangzahn von Vagash?",a="Rudra Amberstill sucht den Fangzahn als physischen Beweis für den Tod des Raubtiers. Vagash hat das Gehöft in der Nacht überfallen und wertvolle Widder verschlungen, was die Existenzgrundlage der Familie Amberstill bedroht, während die Wache von Eisenschmiede zu sehr damit beschäftigt ist, sie zu verteidigen.",al={"warum den fangzahn von vagash wollen","wer möchte den fangzahn von vagash","rudra amberstill fangzahn"}}},fp="14,113,18.370.0,36.155.0,14.145.0,45.163.0"}
P.entries["item:fangore-s-paw"] = {n="Fangors Tatze",s="Im Rotkammgebirge führt Fangore die Shadowhide-Gnolle gegen Seenhain. Seine abgetrennte Tatze beweist Magistrat Solomon seinen Tod und könnte die Gefahr lindern, die sich um die Stadt zusammenzieht.",h="Im Rotkammgebirge führt Fangore die Shadowhide-Gnolle gegen Seenhain.",kw={"fangore","gnoll","seenhain","morganth","tatze","rotkammgebirge","shadowhide","solomon"},ang={["faction:Alliance"]="Als Held der Allianz verschafft Ihr Seenhain Erleichterung, indem Ihr Fangore bezwingt und seine Tatze zurückbringt. Die bedrängte Stadt erhält nur wenig militärische Unterstützung aus Sturmwind."},sec={{t="Trophäe eines gefallenen Häuptlings",b="Lieutenant Fangore führt die Shadowhide-Gnolle durch das Rotkammgebirge. Er dient dem abtrünnigen Magier Morganth und leitet Angriffe auf Handelsstraßen, abgelegene Höfe und die Verteidigungsanlagen rund um den Immerruhsee. Die Gnolle hinterlassen keine Uniformen, Siegel oder Banner, anhand derer sich ihre Toten identifizieren ließen. Deshalb verlangt Magistrat Solomon Fangors Tatze als Beweis für die Hinrichtung des Lieutenants, damit Seenhain inmitten der Gefahren ringsum etwas aufatmen kann."}},faq={{q="Wem gehört diese Tatze?",a="Die Tatze gehört Lieutenant Fangore, einem berüchtigten Anführer unter den Shadowhide-Gnollen im Rotkammgebirge. Er leitet Überfälle und dient dem finsteren Zauberer Morganth.",al={"wer ist fangore","wem gehört diese tatze","fangores identität"}},{q="Warum will Magistrat Solomon die Tatze?",a="Magistrat Solomon hat einen Steckbrief ausgehängt, der Fangore als niederträchtigen Feind von Sturmwind verurteilt. Er verlangt die abgetrennte Tatze als handfesten Beweis dafür, dass der Lieutenant der Shadowhide getötet wurde.",al={"warum fangors tatze sammeln","solomons kopfgeldbeweis","beweis für den magistrat"}},{q="Für wen arbeitet Lieutenant Fangore?",a="Fangore dient Morganth, einem abtrünnigen Anwender dunkler Magie. Morganth bedroht Seenhain von seinem Turm in den östlichen Bergen aus und lenkt die Unternehmungen der Gnolle gegen das Königreich.",al={"fangores meister","wer führt fangore","verbindung zu morganth"}},{q="Wo ist Lieutenant Fangore zu finden?",a="Lieutenant Fangore operiert im Rotkammgebirge inmitten der Lager der feindseligen Shadowhide-Gnolle.",al={"fangores aufenthaltsort","wo ist fangore","fangore finden"}}},fx={["62ed4317"]={q="Woher stammt Fangors Tatze?",a="Die Tatze stammt direkt vom Leichnam von Leutnant Fangore, einem berüchtigten Anführer der Schattenfell-Gnolle, die im Rotkammgebirge leben. Es ist kein künstliches Relikt oder eine Waffe, sondern eine abgetrennte, physische Trophäe, die im Kampf errungen wurde, um zu bestätigen, dass der gefährliche Gnollkommandant ausgeschaltet wurde.",al={"ursprung von fangors tatze","woher stammt fangors tatze","wer hat fangors tatze hergestellt"}}},fp="13,185,28.436.0,28.166.0,41.184.0,38.177.0,34.101.0"}
P.entries["item:faranell-s-parcel"] = {n="Faranell's Parcel",s="Faranell's Parcel bringt eine starke Probe Witherbark-Spinnengifts aus dem Hinterland in die Unterstadt. Apothekermeister Faranell erhält sie zur Untersuchung und für mögliche neue Anwendungen.",h="Faranell's Parcel bringt eine starke Probe Witherbark-Spinnengifts aus dem Hinterland in die Unterstadt.",kw={"das apothekarium","apotheker lydon","faranell","faranell's parcel","apothekermeister faranell","royal apothecary society","spinnengift","unterstadt","witherbark"},ang={["faction:Horde"]="Als Mitglied der Horde bringt Ihr Lydons Giftprobe für die Royal Apothecary Society in die Unterstadt.",["race:Undead"]="Als Mitglied der Verlassenen dient Ihr einer Gesellschaft, deren Apotheker Gifte wie das Witherbark-Gift in diesem Paket untersuchen."},sec={{t="Eine Probe geht nach Süden",b="Im Hinterland schickt Apotheker Lydon Faranell's Parcel an seinen Vorgesetzten, Apothekermeister Faranell, in die Unterstadt. Das Paket enthält Gift vom Spinnengott der Witherbark. Lydon hat seine Stärke an Kaninchen getestet und glaubt, dass Faranell das Gift selbst untersuchen möchte."},{t="Faranells Arbeit",b="Im Apothekarium nimmt Apothekermeister Faranell das Paket entgegen und erfährt, dass Lydon das Gift für außergewöhnlich stark hält. Er arbeitet bereits an neuen Anwendungen dafür. Die Royal Apothecary Society hofft, dass die Probe weitere Verwendungsmöglichkeiten eröffnet."}},faq={{q="Was ist in Faranell's Parcel?",a="Faranell's Parcel enthält eine Probe Gift vom Spinnengott der Witherbark.",al={"was ist im paket","inhalt von faranell's parcel"}},{q="Wer hat das Paket geschickt?",a="Apotheker Lydon stellt Faranell's Parcel zur Lieferung an seinen Vorgesetzten, Apothekermeister Faranell, bereit.",al={"wer gab mir das paket","lydon paket"}},{q="Für wen ist das Paket bestimmt?",a="Apothekermeister Faranell nimmt das Paket im Apothekarium in der Unterstadt entgegen.",al={"wer erhält es","faranells lieferung"}},{q="Warum will Faranell das Gift?",a="Lydon glaubt, dass Faranell das starke Gift selbst testen möchte, und Faranell arbeitet an neuen Anwendungen dafür.",al={"warum gift schicken","was möchte faranell"}},{q="Wie stark ist das Gift?",a="Lydon sagt, ein Tropfen habe beinahe zwei Dutzend Kaninchen getötet, merkt jedoch an, dass einige davon sehr jung und klein waren.",al={"giftstärke","ist das spinnengift stark"}}},fp="17,179,19.290.0,15.252.0,29.84.0,20.101.0,22.84.0,33.120.0,24.98.0"}
P.entries["item:farren-s-report"] = {n="Farrens Bericht",s="In Süderstade hält Leutnant Farren Orinelles Bericht seine Erkenntnisse über die örtlichen Naga fest. Er hofft, dass die Depesche ihm eine Rückkehr nach Sturmwind ermöglicht.",h="In Süderstade hält Leutnant Farren Orinelles Bericht seine Erkenntnisse über die örtlichen Naga fest.",kw={"farren orinelle","farrens bericht","major samuelson","naga","reassignment","redpath","süderstade","burg sturmwind"},ang={["faction:Alliance"]="Für die Allianz offenbart Farrens Bericht die Winkelzüge innerhalb ihres Militärs, während Offiziere im fernen Hillsbrad nach sichereren Posten in Sturmwind streben.",["race:Human"]="Als Mensch der Allianz verbindet Ihr mit der Überbringung von Farrens Bericht das belagerte Süderstade mit dem königlichen Hof in Burg Sturmwind."},sec={{t="Ein Ausweg aus Süderstade",b="Leutnant Farren Orinelle wurde der umkämpften Küste Süderstades, seiner Anführer und seiner abgelegenen Grenzregion überdrüssig. Er schickte Abenteurer aus, um die Naga der Dornenrücken zu jagen und Beweise für ihre Bedrohung zu sammeln. Dann fasste er ihre Erkenntnisse in einem förmlichen Bericht zusammen.\n\nFarren will die Depesche an Major Samuelson schicken, den Hauptmann der Wache in Burg Sturmwind, statt an seinen Befehlshaber, Marshal Redpath. Samuelson bildete Farren aus, und Farren hofft, der Bericht werde seine Fähigkeiten beweisen und ihm eine sofortige Versetzung zu den Annehmlichkeiten Sturmwinds einbringen."}},faq={{q="Was ist Farrens Bericht?",a="Farrens Bericht dokumentiert Leutnant Farren Orinelles Einsätze gegen die Naga der Dornenrücken, die Süderstades Strände bedrohen.",al={"farrens bericht","was ist dieser bericht","orinelles bericht"}},{q="Warum will Farren den Bericht nach Sturmwind bringen lassen?",a="Farren hofft, Süderstade zu verlassen und nach Sturmwind zurückzukehren. Er schickt den Bericht an Major Samuelson, seinen früheren Mentor und Hauptmann der Wache von Sturmwind, in der Hoffnung auf eine günstige Versetzung.",al={"warum bericht nach sturmwind schicken","farrens ziel","warum samuelson"}},{q="Warum hält Farren den Bericht vor Redpath geheim?",a="Farren will einer genauen Prüfung durch Marshal Redpath und die Anführer Süderstades entgehen. Sie könnten es einem Offizier verübeln, eine örtliche Bedrohung zu nutzen, um seine eigene Versetzung in die Sicherheit der Hauptstadt einzufädeln.",al={"warum vor redpath verbergen","alter redpath geheimnis"}},{q="Wie reagiert Major Samuelson, als er den Bericht erhält?",a="Major Samuelson lobt seinen früheren Schüler dafür, dass er die Initiative gegen die Naga von Süderstade ergriffen hat. Er verspricht, den Bericht zu berücksichtigen, wenn er im kommenden Monat die Wachposten neu zuteilt.",al={"samuelsons reaktion","abgabe versetzung"}}},fx={["97a8ff6b"]={q="Woher stammt Farrens Bericht und wer hat ihn verfasst?",a="Das Dokument wurde in Süderstade von Leutnant Farren Orinelle selbst verfasst. Stationiert an der gefährlichen Grenze des Vorgebirges des Hügellands, stellte Farren den Bericht zusammen, der seine Bemühungen gegen die regionalen Murlocs und Naga detailliert, um die Aufmerksamkeit des Oberkommandos in der Hauptstadt auf sich zu ziehen.",al={"wer hat farrens bericht geschrieben","ursprung von farrens bericht","wer hat farrens bericht verfasst"}}},fp="15,148,26.526.0,24.126.0,49.189.0,55.184.0,49.183.1"}
P.entries["item:fathom-core"] = {n="Tiefenkern",s="Unter den Moonshrine Ruins zeichnet der Tiefenkern das Wirken der Elemente in der Tiefschwarzen Grotte auf. Der Irdene Ring sucht ihn, um zu erfahren, wie der Schattenhammer-Kult diese Kräfte für seine eigenen Zwecke einsetzt.",h="Unter den Moonshrine Ruins zeichnet der Tiefenkern das Wirken der Elemente in der Tiefschwarzen Grotte auf.",kw={"tiefschwarze grotte","der irdene ring","tiefenkern","fathomstein","je'neu sancrea","moonshrine ruins","schattenhammer-kult","außenposten von zoram'gar"},ang={["class:Shaman"]="Als Schamane könnt Ihr erkennen, warum der Irdene Ring den Tiefenkern schätzt. Seine Aufzeichnungen können offenbaren, wie andere die Elemente manipulieren.",["faction:Horde"]="Die Bergung des Tiefenkerns unterstützt Je'neu Sancrea und hilft, den Stützpunkt der Horde am Außenposten von Zoram'gar gegen die verderblichen Pläne des Schattenhammer-Kults zu sichern."},sec={{t="Chronik der Elemente",b="In einem uralten Fathomstein unter den Moonshrine Ruins zeichnet der Tiefenkern die Elemente auf. Seine Aufzeichnungen halten ihre Verschiebungen, Störungen und Wogen im Laufe der Zeit fest. Je'neu Sancrea ist ein Schamane des Irdenen Rings am Außenposten von Zoram'gar. Er sucht den Kern, um zu erfahren, wie die Kultisten des Schattenhammers die Elemente der Region für ihre eigenen Zwecke einsetzen."}},faq={{q="Was ist der Tiefenkern?",a="Der Tiefenkern zeichnet die Geschichte der elementaren Aktivitäten in seiner Umgebung auf. Er ruht in einem uralten Fathomstein in den Moonshrine Ruins.",al={"was macht der tiefenkern","tiefenkern hintergrundgeschichte","was ist das"}},{q="Wo befindet sich der Tiefenkern?",a="Der Tiefenkern liegt tief in der Tiefschwarzen Grotte unter der Küste des Eschentals. Er ruht in einem Fathomstein unter den Wassern der Moonshrine Ruins.",al={"tiefenkern fundort","wo ist der tiefenkern zu finden","fathomstein fundort"}},{q="Wer sucht den Tiefenkern und warum?",a="Je'neu Sancrea, ein Schamane des Irdenen Rings am Außenposten von Zoram'gar, sucht den Tiefenkern. Er und sein Zirkel hoffen, mithilfe seiner Aufzeichnungen elementarer Verschiebungen das Wirken des Schattenhammer-Kults in den Ruinen zu verstehen und ihm entgegenzuwirken.",al={"wer braucht den tiefenkern","warum will je'neu den tiefenkern","irdener ring tiefenkern"}},{q="Warum interessiert sich der Schattenhammer-Kult für die Tiefschwarze Grotte?",a="Die Kultisten des Schattenhammers haben sich in den versunkenen Ruinen niedergelassen, um die örtlichen Elemente zu unterwerfen und zu verderben. Sie wollen diese Kräfte finsteren Zwecken dienstbar machen und die Kontrolle über den unterirdischen Tempel erlangen.",al={"schattenhammer-kult tiefschwarze grotte","kultisten in der tiefschwarzen grotte"}}},fp="11,193,19.338.0,24.130.0,33.148.0,34.218.0,61.213.0"}
P.entries["item:feather-charm"] = {n="Federglücksbringer",s="In Ambossar wecken Federglücksbringer das Interesse eines Hexenmeisterausbilders. Frostmane-Novizen tragen diese groben Schmuckstücke, die eine schwache magische Kraft bergen.",h="In Ambossar wecken Federglücksbringer das Interesse eines Hexenmeisterausbilders.",kw={"alamar grimm","ambossar","das coldridgetal","dun morogh","federglücksbringer","frostmane-novize","hexenmeister"},ang={["class:Warlock"]="Als angehender Hexenmeister in Dun Morogh nehmt Ihr Trollzauberwirkern Federglücksbringer ab, um Eure Disziplin unter Beweis zu stellen. Nachdem Ihr die Prüfung bestanden habt, vertraut Alamar Grimm Euch das Ritual zur Beschwörung eines Wichtels an.",["race:Gnome"]="Als gnomischer Hexenmeister in Ambossar studiert Ihr diese einfachen Trollfetische, um die rohe, unverfeinerte Magie zu untersuchen, die primitive Frostmane-Zauberwirker kanalisieren."},sec={{t="Trollschmuck und dunkle Studien",b="Südwestlich von Ambossar tragen Novizen der Frostmähnen Federglücksbringer durch verschneite Höhlen. Ihr Stamm ist für seine territoriale Wildheit bekannt, doch seine jungen Trolle üben sich in primitiver Zauberkunst. Die Glücksbringer bergen eine schwache, aber unverkennbare Macht. Alamar Grimm, der Hexenmeisterausbilder in Ambossar, studiert diese grobe Trollmagie mit Interesse. Er nutzt die Glücksbringer, um angehende Hexenmeister zu prüfen, die ihren ersten Wichtel binden wollen."}},faq={{q="Wer trägt diese Federglücksbringer?",a="Frostmane-Novizen tragen die Glücksbringer in einer verschneiten Höhle südwestlich von Ambossar im Coldridgetal.",al={"woher kommen federglücksbringer","wer lässt federglücksbringer fallen","frostmane-novize glücksbringer"}},{q="Warum will Alamar Grimm sie haben?",a="Alamar Grimm findet die innewohnende Magie der Glücksbringer faszinierend und für die Handwerkskunst der Trolle unerwartet. Er prüft damit die körperliche Belastbarkeit und das magische Potenzial angehender Hexenmeister, bevor er sie lehrt, einen Wichtel zu beschwören.",al={"warum braucht alamar glücksbringer","alamar grimm federglücksbringer","was macht grimm damit"}},{q="Sind die Frostmane-Trolle geübte Magieanwender?",a="Der Stamm der Frostmane gilt als primitiv und feindselig, doch seine Novizen üben sich in einfacher Zauberkunst. Ihre Federglücksbringer bündeln diese einfache Magie und zeigen, dass selbst angehende Frostmane-Zauberwirker arkane oder schamanistische Energien nutzen.",al={"können frostmane-trolle magie nutzen","frostmane-novize magie"}},{q="Wie sehen die Glücksbringer aus?",a="Frostmane-Novizen fertigen einfache Talismane aus Federn und Schnur. Sie tragen sie als Fokusse für ihre ersten magischen Übungen in den kalten Höhlen von Dun Morogh.",al={"federglücksbringer beschreibung","aussehen des federglücksbringers"}}},fx={a2188847={q="Was ist ein Federglücksbringer?",a="Ein Federglücksbringer ist ein grobes magisches Amulett, das von Frostmähn-Trollnovizen in Dun Morogh gefertigt und getragen wird. Obwohl es scheinbar einfache Schmuckstücke sind, die von den primitiven Bergtrollen hergestellt wurden, kanalisieren diese Glücksbringer tatsächlich eine ausgeprägte magische Energie, die die Aufmerksamkeit von Gelehrten und Zauberkundigen auf sich zieht, die die Troll-Mystik studieren.",al={"was ist ein federglücksbringer","federglücksbringer lore","über federglücksbringer"}},["6facee45"]={q="Woher stammen Federglücksbringer und wer stellt sie her?",a="Diese Glücksbringer werden von den angehenden Zauberern des Frostmähn-Stammes gefertigt, die in den eisigen Höhlen südwestlich von Ambossar hausen. Die jungen Trollnovizen verleihen den Federn ihre eigenen aufkeimenden Kräfte und tragen sie als Fokus, während sie ihr rudimentäres Zauberhandwerk im Coldridgetal üben.",al={"wer stellt federglücksbringer her","woher stammen federglücksbringer","ursprung des frostmähn-federglücksbringers"}}},fp="13,143,31.410.0,33.94.0,32.217.0,43.232.0,29.145.0"}
P.entries["item:fel-cone"] = {n="Teufelszapfen",s="In Teldrassil tragen Teufelszapfen Verderbnis unter den Ästen des Baumes. Nachtelfische Verteidiger setzen die Samenkapseln gegen Schwindler in der Nähe ein.",h="In Teldrassil tragen Teufelszapfen Verderbnis unter den Ästen des Baumes.",kw={"dolanaar","teufelszapfen","satyr","seek redemption","syral messerblatt","teldrassil","zenn faulhuf"},ang={["class:Druid"]="Als Druide seht Ihr, wie gesunde Samenkapseln des Waldes zu rauchenden Teufelsüberresten geworden sind. Ihre Verderbnis zeigt, wie zerbrechlich Teldrassils Gleichgewicht ist.",["race:NightElf"]="Als Nachtelf wisst Ihr, dass Teufelszapfen auf eine Krankheit tief in Teldrassils Wurzeln hindeuten. Selbst der junge World Tree ist anfällig für dämonische Verderbnis."},sec={{t="Verderbnis im Blätterdach",b="Unter Teldrassils Ästen zeugen Teufelszapfen von Verderbnis im jungen Baum. Die knorrigen Kiefernzapfen sind herabgefallen und stoßen üblen grünen Rauch aus. Sie liegen gleich östlich von Dolanaar verstreut. Verderbte Magie hat die umliegenden Pflanzen verformt, und die Samenkapseln sind gefährlich, wenn man sie unvorsichtig berührt oder isst."},{t="Eine bittere Medizin",b="Zenn Faulhuf bringt Vorbeikommende mit List dazu, seinen Willen auszuführen. Wenn Reisende auf seine Listen hereinfallen, weisen Syral Messerblatt und die Schildwachen sie an, Teufelszapfen zu sammeln und Faulhuf als harmlosen Imbiss anzubieten. Die Verderbnis eines Zapfens verwandelt den Satyr kurzzeitig in einen harmlosen Frosch."}},faq={{q="Was ist ein Teufelszapfen?",a="Ein Teufelszapfen ist ein verdorbener Kiefernzapfen, der von Teldrassils Ästen herabgefallen ist. Von unnatürlicher Magie befleckt, verströmt er unheimlichen grünen Rauch und birgt unberechenbare Macht, die Verwandlungen bewirken kann.",al={"was sind teufelszapfen","teufelszapfen hintergrundgeschichte","was ist ein teufelszapfen"}},{q="Wo findet man Teufelszapfen?",a="Teufelszapfen liegen auf dem Waldboden unter den Bäumen gleich östlich von Dolanaar in Teldrassil.",al={"wo sind teufelszapfen","teufelszapfen fundort","wie findet man teufelszapfen"}},{q="Warum will der Council of the Forest, dass sie gesammelt werden?",a="Wenn Ihr Zenn Faulhuf unwissentlich geholfen habt, den Geschöpfen der Natur zu schaden, gibt Euch der Council of the Forest Gelegenheit zur Wiedergutmachung. Er fordert Euch auf, Teufelszapfen zu sammeln und Zenn dazu zu bringen, sie zu essen, um ihm eine Lektion zu erteilen.",al={"seek redemption zapfen","warum teufelszapfen sammeln","wer will teufelszapfen"}},{q="Was geschieht, wenn jemand einen Teufelszapfen isst?",a="Der Council of the Forest will Zenn Faulhuf mit den Zapfen eine Lektion erteilen. Er soll einen davon für einen harmlosen Imbiss halten.",al={"was bewirkt ein teufelszapfen","teufelszapfen essen","zenn faulhuf frosch"}}},fx={["5dfa7f39"]={q="Woher stammen Teufelszapfen und wer hat sie hergestellt?",a="Teufelszapfen werden nicht von sterblichen Händen gefertigt; es sind korrumpierte Samenzapfen, die auf natürliche Weise von den Zweigen der Bäume von Teldrassil fallen. Ein fauliger, aufquellender grüner Rauch steigt von ihnen auf, was zeigt, dass die dunkle Verderbnis, die den großen Weltenbaum plagt, tief in seine Samen und sein Erdreich eingedrungen ist.",al={"woher stammen teufelszapfen","wer hat teufelszapfen hergestellt","ursprung von teufelszapfen"}}},fp="8,128,20.285.0,17.270.1,19.172.0,29.89.0,55.211.1,42.126.1"}
P.entries["item:fel-moss"] = {n="Teufelsmoos",s="Überall auf Teldrassil breitet sich Teufelsmoos auf Grells und Grellkin durch die Wälder aus. Seine Verderbnis bedroht die Tierwelt des Weltbaums und die einheimischen Furbolgstämme.",h="Überall auf Teldrassil breitet sich Teufelsmoos auf Grells und Grellkin durch die Wälder aus.",kw={"teufelsmoos","gnarlpine","grell","grellkin","laubschattental","tarindrella","teldrassil","ursal the mauler"},ang={["class:Druid"]="Als Druide des Zirkels des Cenarius seht Ihr Teufelsmoos als ein Krebsgeschwür, das sich in Teldrassil ausbreitet. Seine dämonische Verderbnis zeigt, wie verwundbar der neugeborene Weltbaum ist.",["race:NightElf"]="Als Nachtelf verehrt Ihr Teldrassil als Eure neue Heimat. Teufelsmoos ist ein beunruhigendes Omen dafür, dass der Frieden zwischen seinen heiligen Ästen weiterhin schwer zu finden ist."},sec={{t="Verderbnis am Weltbaum",b="Die Verderbnis hat Teldrassils Äste erreicht. Der Weltbaum wurde gepflanzt, um die Unsterblichkeit der Nachtelfen wiederherzustellen und die natürliche Welt zu heilen, doch Teufelsmoos zeugt vom Verfall. Grells und Grellkin suchen Laubschattental heim, während die unnatürliche, finstere Magie des Mooses an ihnen haftet und von seinen Wucherungen ausstrahlt. Die Dryade Tarindrella sammelt Proben, um herauszufinden, wie tief die Fäulnis in das heilige Blätterdach des Waldes eingedrungen ist."},{t="Saat des Wahnsinns",b="Teldrassils einheimische Furbolgs sind dem Teufelsmoos erlegen. Einst friedlich, verließen sie ihre angestammten Behausungen und schlossen sich zum feindseligen Stamm der Gnarlpine zusammen. Die böse Macht des Mooses treibt sie unter Anführern wie Ursal the Mauler in den Wahnsinn. Krankheit schlägt im Inneren des großen Baumes Wurzeln."}},faq={{q="Was ist Teufelsmoos?",a="Teufelsmoos ist verdorbene pflanzliche Substanz, die auf Teldrassil vorkommt. Seine finsteren Energien haften an Grells und Grellkin und bedrohen die Tierwelt und die einheimischen Furbolgs in der Nähe.",al={"teufelsmoos hintergrund","was ist teufelsmoos","was bewirkt teufelsmoos"}},{q="Woher kommt Teufelsmoos?",a="Rund um Laubschattental tragen Grells und Grellkin Büschel von Teufelsmoos durch Teldrassils Hügel. Seine verderbenden Energien breiten sich durch die Wälder des Weltbaums aus.",al={"wo bekommt man teufelsmoos","teufelsmoos beute","herkunft von teufelsmoos"}},{q="Wie wirkt Teufelsmoos auf die Furbolgs?",a="Die böse Macht des Teufelsmooses hat Teldrassils einheimische Furbolgs erfasst. Sie verließen ihre angestammten Behausungen und bildeten den feindseligen, fremdenfeindlichen Stamm der Gnarlpine, unter Anführern wie Ursal the Mauler in den Wahnsinn getrieben.",al={"verderbnis der furbolgs","warum sind gnarlpine wahnsinnig","gnarlpine teufelsmoos"}},{q="Wer versucht, die Ausbreitung des Teufelsmooses aufzuhalten?",a="In Laubschattental bittet die Dryade Tarindrella junge Verteidiger, Teufelsmoosproben von Grellkin zu sammeln und zu ermitteln, wie tief die Verderbnis den Wald durchdrungen hat. Sie verweist besorgte Beschützer an Druiden wie Athridas Bearmantle in Dolanaar.",al={"wer erforscht teufelsmoos","wer will teufelsmoos","tarindrella quest"}}},fx={["464589e1"]={q="Warum möchte Tarindrella Teufelsmoos?",a="Tarindrella sucht Proben von Teufelsmoos, um zu bestätigen, ob die aggressiven Grells und Grellkin, die das Laubschattental befallen, unter dessen bösartigem Zauber stehen. Indem sie dieses verseuchte Gewächs sichert, hofft sie abzuschätzen, wie weit die Verderbnis fortgeschritten ist, und die Bedrohung zu verstehen, der die nahen Gnarlpine-Furbolgs ausgesetzt sind.",al={"warum teufelsmoos sammeln","tarindrella teufelsmoos","warum möchten sie teufelsmoos"}}},fp="8,162,24.408.0,16.290.1,17.155.0,30.159.0,38.205.0,45.249.0"}
P.entries["item:felix-s-box"] = {n="Felix' Kasten",s="In den Lagern der Frostmähne südwestlich von Ambossar liegt Felix' Kasten, weit entfernt von dem Gnomenflüchtling, der ihn verlor.",h="In den Lagern der Frostmähne südwestlich von Ambossar liegt Felix' Kasten, weit entfernt von dem...",kw={"ambossar","das coldridgetal","dun morogh","felix windenbolz","felix' kasten","frostmähne","gnomeregan","flüchtling"},ang={["profession:Engineering"]="Als Ingenieur wisst Ihr, wie schwer es vertriebene Gnomenhandwerker trifft, wenn sie die Werkzeuge und Behälter verlieren, auf die sie angewiesen sind.",["race:Gnome"]="Als Gnom, der im Coldridgetal beginnt, könnt Ihr einem anderen Vertriebenen helfen, indem Ihr nach der Evakuierung von Gnomeregan Felix' Habseligkeiten zurückholt."},sec={{t="Auf der Flucht aus Gnomeregan verloren",b="Bei dem gescheiterten Versuch, die Bedrohung durch die Troggs zu beseitigen, breitete sich Strahlung in Gnomeregan aus. Felix Windenbolz floh mit den Gnomen ins Coldridgetal und ließ seine Besitztümer und seine Handwerksausrüstung an der verschneiten Straße zurück, um den Dämpfen zu entkommen. Trolle der Frostmähne plünderten die Habseligkeiten, bevor er zurückkehren konnte. Sie brachten seinen Kasten, seine Truhe und seinen Bolzeneimer in ihre Siedlungen südwestlich von Ambossar."},{t="Dilemma eines Flüchtlings",b="Felix ist Gewalt nicht gewohnt und für die Wildnis von Dun Morogh schlecht gerüstet. Er braucht die Hilfe durchreisender Abenteurer in Ambossar, um seine Habseligkeiten zurückzubekommen. Ihre Rückgabe würde dem vertriebenen Handwerker ein Stück Normalität zurückgeben und ihm ermöglichen, seinen Lebensunterhalt zu verdienen. Als Gnomeregan fiel, verlor er alles."}},faq={{q="Was ist Felix' Kasten?",a="Felix' Kasten enthält die persönlichen Habseligkeiten von Felix Windenbolz. Er ist ein Gnomenhandwerker, der aus Gnomeregan floh, nachdem sich Strahlung in der Stadt ausgebreitet hatte.",al={"felix' kasten","was ist dieser kasten","felix' kasten geschichte"}},{q="Wie geriet der Kasten in die Hände der Trolle der Frostmähne?",a="Felix ließ seine Ausrüstung zurück, als er vor den radioaktiven Dämpfen aus Gnomeregan floh. Trolle der Frostmähne brachten die Habseligkeiten vom Straßenrand in ihre Lager südwestlich von Ambossar.",al={"warum haben trolle felix' kasten","wer hat felix' kasten gestohlen","wie ging er verloren"}},{q="Wer ist Felix Windenbolz?",a="Felix Windenbolz ist ein Gnomenflüchtling in Ambossar. Der Fall von Gnomeregan traumatisierte ihn und ließ ihn ohne seine Werkzeuge und persönlichen Habseligkeiten zurück.",al={"felix windenbolz","wer ist felix"}},{q="Welche anderen Gegenstände hat Felix verloren?",a="Die Trolle der Frostmähne nahmen neben dem Kasten auch Felix' Truhe und seinen Bolzeneimer mit. Sie brachten alle drei in ihre Lager südwestlich von Ambossar.",al={"weitere gegenstände von felix","felix' habseligkeiten","felix' verlorene ausrüstung"}}},fx={["8f76c19d"]={q="Warum möchte Felix Windenbolz seinen Kasten zurück?",a="Felix Windenbolz ist ein vertriebener Gnom-Flüchtling, der nach der Überflutung der Stadt durch Strahlung in reiner Panik aus Gnomeregan fliehen musste. Bei seinem verzweifelten Kampf um Sicherheit verlor er seine Werkzeuge und persönliche Ausrüstung an die Frostmähn-Trolle. Als einfacher Handwerker und Flüchtling, der in Ambossar gestrandet ist, fehlen ihm die kämpferischen Fähigkeiten, um die Trolllager selbst zu trotzen, doch er benötigt seinen gestohlenen Kasten und sein Hab und Gut verzweifelt zurück, um sein Leben wieder aufzubauen.",al={"warum möchte felix den kasten","warum felix' kasten finden","zweck von felix' kasten"}}},fp="11,98,34.387.0,20.287.0,20.141.0,49.154.0,25.138.0,32.140.0"}
P.entries["item:felix-s-bucket-of-bolts"] = {n="Felix' Bolzeneimer",s="In Dun Morogh tragen Trolle der Frostmähnen Felix' Bolzeneimer in ihre Lager. Felix Windenbolz vermisst die Werkzeuge, die er aus Gnomeregan mitgebracht hat.",h="In Dun Morogh tragen Trolle der Frostmähnen Felix' Bolzeneimer in ihre Lager.",kw={"ambossar","bolzen","dun morogh","felix","frostmane","gnomeregan","flüchtling","trolle","windenbolz"},ang={["profession:Engineering"]="Als Ingenieur braucht Ihr grundlegende Bauteile, um zu arbeiten. Ein Eimer voller Bolzen zählt, wenn Ihr im Schnee von Dun Morogh neu anfangt.",["race:Gnome"]="Für Euch als Gnom hilft jeder aus Gnomeregan gerettete Eimer voller Bauteile den Flüchtlingen, im Coldridgetal wieder Fuß zu fassen."},sec={{t="Die verstreuten Werkzeuge eines Flüchtlings",b="Felix Windenbolz floh nach der Katastrophe mit den Troggs samt seinen Werkzeugen aus Gnomeregan. Strahlung trieb Tausende Gnome mit allem, was sie tragen konnten, in die eisige Wildnis von Dun Morogh. Felix machte sich nach Ambossar auf, doch Trolle der Frostmähnen aus den Felsen südwestlich der Stadt überfielen ihn. Sie raubten seine Habseligkeiten, darunter seinen Eimer mit Bolzen und Bauteilen, und ließen den Handwerker ohne die Materialien zurück, die er im Exil für sein Handwerk braucht."}},faq={{q="Was ist Felix' Bolzeneimer?",a="Felix Windenbolz' Eimer enthält Bolzen, Beschläge und Material zum Tüfteln. Der verbannte Gnom sucht in Ambossar Zuflucht.",al={"bolzeneimer","felix' eimer","felix' bolzeneimer"}},{q="Wer hat den Eimer gestohlen?",a="Frostmane-Trolle stahlen Felix Windenbolz' Eimer und weitere Habseligkeiten, als er vor der Katastrophe in Gnomeregan floh.",al={"wer nahm die bolzen","trolle stahlen eimer","wer hat felix' bolzen"}},{q="Wohin haben die Trolle ihn gebracht?",a="Frostmane-Trolle trugen den Eimer in ihre Lager in den Felsen südwestlich von Ambossar im Coldridgetal.",al={"wo sind die bolzen","fundort des eimers","felix bolzen lager"}},{q="Warum ist dieser Eimer für Felix wichtig?",a="Felix braucht die Bolzen und Bauteile für sein Handwerk. Gnomische Flüchtlinge flohen mit wenig Besitz aus Gnomeregan, daher zählt grundlegendes Material, während sie fern der Heimat überleben und sich ein neues Leben aufbauen.",al={"warum will felix bolzen","felix windenbolz bolzen bedeutung"}}},fp="23,144,27.424.0,32.120.0,21.109.0,29.107.0,38.160.0"}
P.entries["item:felix-s-chest"] = {n="Felix' Truhe",s="In einem Frostmähnen-Lager südwestlich von Ambossar birgt Felix' Truhe, was er auf der Flucht aus Gnomeregan verlor.",h="In einem Frostmähnen-Lager südwestlich von Ambossar birgt Felix' Truhe, was er auf der Flucht aus Gnomeregan...",kw={"a refugee's quandary","ambossar","das coldridgetal","felix windenbolz","felix' truhe","frostmane","gnomeregan"},ang={["race:Gnome"]="Als Gnom könnt Ihr in Felix' Truhe eine Erinnerung an die chaotische Evakuierung Gnomeregans sehen. Die fliehenden Gnome verloren fast alles an die Wildnis und Plünderer."},sec={{t="Die Verluste eines Flüchtlings",b="Als Troggs und giftiger radioaktiver Niederschlag die Gnome aus Gnomeregan vertrieben, durchquerten Flüchtlinge das verschneite Dun Morogh und trugen, was sie konnten. Frostmähnen-Trolle plünderten die Straßen und überwältigten verstreute Überlebende. Sie brachten Felix Windenbolz' robuste Truhe in ihre Lager in den zerklüfteten Bergen, wo seine Werkzeugsätze und persönlichen Habseligkeiten noch zwischen ihren Vorräten liegen."}},faq={{q="Was befindet sich in Felix' Truhe?",a="Felix Windenbolz' Truhe enthält die persönlichen Habseligkeiten, die er auf der Flucht aus Gnomeregan rettete. Er ließ sie zurück, als er hastig der tödlichen Strahlung entkam. Der Inhalt bedeutet den Trollen wenig, doch er ist aus seinem früheren Leben geblieben.",al={"felix' truhe inhalt","was ist in der truhe","felix' truhe beute"}},{q="Warum haben die Frostmane-Trolle Felix' Habseligkeiten?",a="Frostmane-Trolle überfielen verstreute gnomische Flüchtlinge aus dem Hinterhalt und schleppten ihre Ausrüstung fort. Sie bedrängen Reisende und durchstreifen das Coldridgetal auf der Suche nach Brauchbarem, wobei sie zurückgelassenes Gepäck in ihre Lager bringen.",al={"warum haben trolle felix' truhe","wer hat felix' truhe gestohlen","trolle felix windenbolz"}},{q="Wo befindet sich die Truhe?",a="Felix' Truhe liegt südwestlich von Ambossar im Coldridgetal, nahe den Zelten einer Siedlung der Frostmane-Trolle und anderen geplünderten Vorräten.",al={"wo ist felix' truhe","felix' truhe standort","felix' truhe finden"}}},fx={cd14610d={q="Was ist Felix' Truhe?",a="Felix' Truhe ist ein Behälter mit persönlichen Gegenständen und Werkzeugen von Felix Windenbolz, einem Gnom-Flüchtling, der jetzt in Ambossar Zuflucht sucht. Als Gnomeregan verstrahlt wurde, floh Felix nach Dun Morogh, verlor die Truhe jedoch während seiner chaotischen Flucht an Frostmähn-Trolle.",al={"was ist felix' truhe","felix' truhe","wem gehört felix' truhe"}},bcb95cf5={q="Warum möchte Felix seine Truhe zurück?",a="Felix Windenbolz floh nach dem tragischen Fall von Gnomeregan mit so gut wie nichts. Die Truhe enthält seine persönlichen Gegenstände und praktischen Werkzeuge, wesentliche Vorräte, die er zum Überleben und für einen Neuanfang benötigt, während er bei den Zwergen des Coldridgetals untergekommen ist. Da ihm die kämpferischen Fähigkeiten fehlen, um die Frostmähn-Trolle selbst zu bekämpfen, verlässt er sich auf willige Abenteurer, um sie wiederzubeschaffen.",al={"warum möchte felix seine truhe","warum wird felix' truhe benötigt","warum felix' truhe bergen"}}},fp="13,95,18.350.0,29.235.0,52.192.0,27.135.0"}
P.entries["item:felstalker-hoof"] = {n="Teufelspirscherhuf",s="Im Tal der Prüfungen in Durotar stellen sich junge Schamanen Teufelspirschern, um ihre Bereitschaft zu beweisen. Ihre Hufe bringen sie zu Canaga Erdenrufer, bevor sie lernen, mit den Erdgeistern Zwiesprache zu halten.",h="Im Tal der Prüfungen in Durotar stellen sich junge Schamanen Teufelspirschern, um ihre Bereitschaft zu...",kw={"koven der brennenden klinge","call of earth","canaga erdenrufer","durotar","earth sapta","teufelspirscher","teufelspirscherhuf","das tal der prüfungen"},ang={["class:Shaman"]="Als Schamane beginnt Ihr Euren Weg zur Zwiesprache mit den Erdgeistern, indem Ihr Dämonen erschlagt und ihre Hufe sammelt. Die Prüfung erprobt die Geduld und die unbeugsame Widerstandskraft, die Ihr braucht, um ein Erdtotem zu führen.",["faction:Horde"]="Dämonische Teufelspirscher auf Durotars Übungsgelände erinnern die Horde daran, dass die Verderbnis der Burning Blade noch immer auf ihrem Land lastet."},sec={{t="Die Prüfung eines Schamanen",b="Canaga Erdenrufer schickt junge Schamanen aus, um sich dem dämonischen Verderben zu stellen, das Durotar bedroht. Im Norden des Tals der Prüfungen teilen sich die üblen Familiare des Kovens der Brennenden Klinge das Gelände mit umherstreifenden Teufelspirschern. Einem Teufelspirscher einen Huf abzunehmen, prüft die Ausdauer, die Entschlossenheit und den Geist eines Schamanen. Wer die Bestien bezwingt, ist bereit, die Geheimnisse der Erde zu erlernen und die zeremonielle Sapta für die Zwiesprache mit Elementargeistern vorzubereiten."}},faq={{q="Wofür wird der Teufelspirscherhuf verwendet?",a="Ihr bringt Canaga Erdenrufer im Tal der Prüfungen zwei Teufelspirscherhufe. Sie beweisen, dass Ihr die Kraft und den Geist besitzt, um mit dem Erdelement Zwiesprache zu halten.",al={"was bewirkt der teufelspirscherhuf","huf questgegenstand","warum teufelspirscherhufe sammeln"}},{q="Woher stammen diese Hufe?",a="Die Hufe stammen von dämonischen Teufelspirschern im Koven der Brennenden Klinge und seiner Umgebung, im Norden des Tals der Prüfungen in Durotar.",al={"wo teufelspirscherhuf bekommen","teufelspirscherhuf fundort","wer lässt hufe fallen"}},{q="Wer benötigt diese Hufe?",a="Canaga Erdenrufer, der Schamanenausbilder in der Nähe von The Den im Tal der Prüfungen, verlangt die Hufe während des Rituals Call of Earth.",al={"wer will teufelspirscherhufe","wer gibt den huf ab","canaga erdenrufer quest"}},{q="Kann jeder Abenteurer diese Hufe sammeln?",a="Schamanen suchen während ihrer elementaren Initiation nach Teufelspirscherhufen. Krieger, Hexenmeister und Schurken stellen sich im Tal ihren eigenen Prüfungen und brauchen sie nicht.",al={"können nichtschamanen hufe bekommen","ist der huf nur für schamanen"}}},fx={["1af4909c"]={q="Was ist ein Teufelspirscherhuf?",a="Ein Teufelspirscherhuf ist eine physische Trophäe, die von den dämonischen Teufelspirschern stammt, die von den Kultisten der Burning Blade in Durotar beschworen wurden. Anstatt als Handwerkskomponente zu dienen, wird er von jungen Schamanen, die versuchen, mit den Geistern der Erde in Verbindung zu treten, als Beweis für ihre Kampfkraft mitgenommen.",al={"was ist ein teufelspirscherhuf","teufelspirscherhuf info","was sind teufelspirscherhufe"}}},fp="15,176,16.418.0,37.165.0,32.125.0,26.127.0,40.156.0"}
P.entries["item:fenwick-s-head"] = {n="Fenwicks Kopf",s="Schurken der Verlassenen jagen nun Fenwick Thatros an den Ufern des Lordameresees. Sein Kopf beweist seine Hinrichtung, die auf einen Befehl von Lord Varimathras hin gefordert wird.",h="Schurken der Verlassenen jagen nun Fenwick Thatros an den Ufern des Lordameresees.",kw={"todespirscher","fenwick","lordamere","mennet carkad","schurkenviertel","silberwald","thatros","varimathras"},ang={["class:Rogue"]="Als Schurke beweist Ihr mit der Beschaffung von Fenwicks Kopf, dass Ihr ein verlässlicher Todespirscher unter den aufstrebenden Agenten der Verlassenen seid, und erhaltet Zugang zu fortgeschrittener Ausbildung.",["race:Undead"]="Als Untoter seht Ihr, wie die Verlassenen rivalisierende untote Fraktionen rücksichtslos unterdrücken, die um die Kontrolle über den Silberwald und die Ufer des Lordameresees kämpfen."},sec={{t="Ein Auftrag aus den Schatten",b="Vom Schurkenviertel in Unterstadt aus handelt Mennet Carkad auf dringende Informationen von Schreckenslord Varimathras hin. Fenwick Thatros, ein feindseliger untoter Anführer, hat nahe den verfallenden Docks am Lordameresee im Silberwald Fuß gefasst. Carkad fürchtet, Fenwick könnte feindliche Untote gegen die Verlassenen sammeln. Daher entsendet er vielversprechende Todespirscher, die ihn finden und töten und dann seinen Kopf als Beweis zurückbringen sollen."},{t="Eine Bewährungsprobe",b="Für Agenten der Todespirscher ist die Übergabe von Fenwicks Kopf an Carkad eine Prüfung, die über das Einfordern eines Kopfgeldes hinausgeht. Der abgetrennte Kopf beweist, dass ein Schurke sich einschleichen und ein Attentat verüben kann. Ein Erfolg eröffnet den Weg zu vertiefter und spezialisierterer Unterweisung in den Schattenkünsten durch Meister der Verlassenen."}},faq={{q="Wer war Fenwick Thatros?",a="Lord Varimathras benannte Fenwick Thatros als einen untoten Anführer, der sich im Silberwald verschanzt hatte. Nahe den verfallenen Docks am Lordameresee stellte Fenwick eine unmittelbare Gefahr für die Interessen der Verlassenen in der Region dar.",al={"wer ist fenwick","fenwick thatros hintergrundgeschichte","wer war thatros"}},{q="Wer will Fenwicks Kopf?",a="Mennet Carkad, ein Ausbilder der Todespirscher im Schurkenviertel von Unterstadt, fordert Fenwicks Kopf auf einen dringenden Befehl von Lord Varimathras hin.",al={"wer will den kopf","bei wem abgeben","mennet carkad"}},{q="Wo befindet sich Fenwick Thatros?",a="Späher der Todespirscher verorten Fenwick Thatros bei den verfallenen Docks am Ufer des Lordameresees im Silberwald.",al={"fenwick thatros aufenthaltsort","wo ist fenwick","fenwick finden"}},{q="Warum muss sein Kopf abgetrennt werden?",a="Mennet Carkad verlangt einen greifbaren Beweis dafür, dass die Bedrohung beseitigt wurde, bevor er einen Agenten zur fortgeschrittenen Ausbildung in den Schattenkünsten zulässt.",al={"warum seinen kopf nehmen","warum ihn enthaupten"}}},fx={bc6d2652={q="Woher stammt Fenwicks Kopf?",a="Dieser abgetrennte Kopf stammt von Fenwick Thatros, einem Untoten-Anführer, auf den Ihr in der Nähe der verfallenden Docks am Ufer des Lordameresees im Silberwald trefft. Es ist kein hergestellter Gegenstand, sondern die düsteren Überreste eines gegnerischen Kommandanten, die auf dem Schlachtfeld erbeutet wurden.",al={"herkunft fenwicks kopf","woher bekommt man fenwicks kopf","wer hatte fenwicks kopf"}}},fp="14,163,27.399.0,17.270.0,24.210.0,25.150.0,33.116.0,29.132.0"}
P.entries["item:feralas-a-history-quest-item"] = {n="Feralas: A History",s="Troyas Moonbreeze bittet Euch, Feralas: A History zur Mondfederfeste zurückzubringen. Das Buch ist ihm wichtig, weil er es unbedingt zurückhaben möchte.",h="Troyas Moonbreeze bittet Euch, Feralas: A History zur Mondfederfeste zurückzubringen.",kw={"buch","mondfederfeste","feralas","feralas: a history","rückkehr zu troyas","troyas moonbreeze"},sec={{t="Die Rückgabe",b="Troyas Moonbreeze wartet in der Mondfederfeste auf Feralas: A History. Er bittet Euch, gut auf das Buch aufzupassen und schnell zurückzukehren, denn er möchte es unbedingt zurückhaben."}},faq={{q="Für wen ist das Buch bestimmt?",a="Troyas Moonbreeze wartet in der Mondfederfeste auf Feralas: A History.",al={"wer möchte das buch","wem das buch bringen"}},{q="Was ist Feralas: A History?",a="Es ist ein Buch, das Troyas Moonbreeze Euch bittet, ihm zur Mondfederfeste zurückzubringen.",al={"feralas buch","geschichtsbuch"}},{q="Wohin soll ich das Buch bringen?",a="Bringt Feralas: A History zu Troyas Moonbreeze in die Mondfederfeste.",al={"wohin das buch bringen","ziel des buches"}},{q="Warum möchte Troyas das Buch zurück?",a="Troyas sagt, dass er sich auf Eure Rückkehr freut, nennt aber keinen weiteren Grund.",al={"warum das buch zurückbringen","warum wartet troyas"}}},fp="18,144,10.158.0,20.78.0,27.87.0,25.71.0,29.69.0"}
P.entries["item:fey-dragon-scale"] = {n="Siechdrachenschuppe",s="Rund um den Steinkrallengipfel liefern Feendrachen Schuppen, die Jin'Zil begehrt. Der Hexendoktor der Dunkelspeer verwendet eine davon für ein Gebräu, das die Naturmagie der Nachtelfen verhöhnen soll.",h="Rund um den Steinkrallengipfel liefern Feendrachen Schuppen, die Jin'Zil begehrt.",kw={"feendrache","siechdrachenschuppe","waldmagie","jin'zil","malaka'jin","nal'taszar","der steinkrallengipfel"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr Jin'Zil, die Stellung der Horde im Steinkrallengebirge zu festigen und gegen die Nachtelfen weiter oben an den Hängen vorzugehen.",["race:NightElf"]="Als Nachtelf kennt Ihr Feendrachen als geschätzte Gefährten und Waldhüter der Kaldorei. Dass ihre Schuppen für den tödlichen Spott eines Trollhexendoktors genommen werden, ist ein Frevel an der Natur."},sec={{t="Eine seltene Waldernte",b="Feendrachen durchstreifen die wilden Haine rund um den Steinkrallengipfel. Ihre Schuppen schimmern vor natürlicher Magie. Nachtelfen verehren sie als harmlose Waldgeister und Verbündete. Außenstehende schätzen die Schuppen als seltene magische Zutaten."},{t="Ein höhnisches Gebräu",b="In Malaka'jin mischt Hexendoktor Jin'Zil ein Gebräu, um die Traditionen der Kaldorei zu verhöhnen. Er vermengt eine Siechdrachenschuppe mit Baumharz, Katzenschnurrhaaren und Dutzenden und Aberdutzenden von Renneraugen. Das Ergebnis nennt er „Waldmagie“. Das grausame Gebräu ist für die drei Nachtelfen bestimmt, die er in Käfigen hält."}},faq={{q="Woher stammt diese Schuppe?",a="Feendrachen in den Hochlandhainen rund um den Steinkrallengipfel liefern die Schuppe, darunter Wily Fey Dragons und Nal'taszar.",al={"siechdrachenschuppe beute","wo siechdrachenschuppe finden","wer lässt siechdrachenschuppe fallen"}},{q="Warum will Hexendoktor Jin'Zil eine Siechdrachenschuppe?",a="Hexendoktor Jin'Zil in Malaka'jin will die Schuppe zusammen mit anderen Reagenzien aus dem Wald. Er nennt sein Gebräu höhnisch „Waldmagie“ und bestimmt es für seine eingesperrten nachtelfischen Gefangenen.",al={"warum will jin'zil das","wofür wird die schuppe verwendet","jin'zil waldmagie reagenz"}},{q="Was geschieht, wenn Jin'Zil sein Gebräu fertigstellt?",a="Jin'Zil plant, das fertige Gebräu an seinen drei gefangenen Nachtelfen anzuwenden. Wenn er diesen Plan ausführt, offenbart sich das Schicksal seiner Gefangenen.",al={"was macht jin'zil mit dem gebräu","jin'zil magie ergebnis","gefangene von jin'zil"}}},fx={["9423a9c1"]={q="Was ist eine Siechdrachenschuppe?",a="Eine Siechdrachenschuppe ist eine schimmernde, irisierende Schuppe, die von den schwer fassbaren Feendrachen vom Steinkrallengipfel geerntet wird. Diese mystischen Kreaturen sind eng mit den natürlichen Energien der Wildnis verbunden. Für einen Alchemisten oder Hexendoktor dient die Schuppe als wirksames, magisch abgestimmtes Reagenz, das von der rohen Essenz des uralten Waldes durchdrungen ist.",al={"was ist eine siechdrachenschuppe","siechdrachenschuppe lore","über siechdrachenschuppen"}}},fp="16,160,21.219.0,20.288.1,32.120.0,54.178.0,44.142.1"}
P.entries["item:field-testing-kit"] = {n="Field Testing Kit",s="Das Field Testing Kit ist ein modifiziertes Gerät, mit dem Kreaturgewebe in Tanaris untersucht wird. Für Außeneinsätze benötigt es eine goblinische Energiequelle, die seine Daten speichert.",h="Das Field Testing Kit ist ein modifiziertes Gerät, mit dem Kreaturgewebe in Tanaris untersucht wird.",kw={"apothekerin zinge","basiliskenprobe","bilgewhizzle","field testing kit","hyänenprobe","energiequelle","skorpidenprobe","tanaris"},ang={["profession:Engineering"]="Als Ingenieur zeigen das modifizierte Kit und seine separate Energiequelle den praktischen Ansatz von Gadgetzan bei Feldversuchen."},sec={{t="Ein Kit für Proben",b="Apothekerin Zinge schickt Euch mit dem Field Testing Kit nach Tanaris, um Basilisken, Hyänen und Skorpiden zu untersuchen. Chefingenieur Bilgewhizzle in Gadgetzan stellt die benötigte Energiequelle bereit. Nach der Aktivierung leuchtet und vibriert das Kit. Seine gespeicherten Daten müssen zurückgebracht werden, bevor die Energie aufgebraucht ist."}},faq={{q="Wozu dient das Field Testing Kit?",a="Das Field Testing Kit untersucht das Gewebe von Basilisken, Hyänen und Skorpiden in Tanaris.",al={"was macht das kit","gerät für feldversuche"}},{q="Wer gibt mir das Kit?",a="Apothekerin Zinge stellt Euch das Field Testing Kit für die Arbeit in Tanaris zur Verfügung.",al={"wo bekomme ich das kit","zinge kit"}},{q="Wer versorgt das Kit mit Energie?",a="Chefingenieur Bilgewhizzle in Gadgetzan kann eine Energiequelle für das modifizierte Kit bereitstellen.",al={"energiequelle fürs kit","bilgewhizzle energie"}},{q="Warum leuchtet und vibriert das Kit?",a="Das Kit leuchtet und vibriert, wenn seine Energiequelle aktiviert wird. Das bedeutet, dass es wie vorgesehen funktioniert.",al={"kit leuchtet","kit vibriert"}},{q="Wie lange speichert das Kit seine Daten?",a="Die Energiequelle gibt Euch zwei Stunden, um die benötigten Daten zu sammeln. Ist sie aufgebraucht, werden die gespeicherten Daten zerstört.",al={"zeitlimit fürs kit","energie aufgebraucht"}}},fp="17,149,17.297.0,34.88.0,21.72.0,19.89.0,34.100.0,36.107.0"}
P.entries["item:filled-amethyst-phial"] = {n="Gefüllte Amethystphiole",s="In Teldrassil sammeln Druiden Wasser aus dem Mondbrunnen des Oracle Trees. Corithras Mondzorn nimmt es für die Druiden des Cenarius entgegen, damit sie das gestörte Wachstum des Weltbaums untersuchen können.",h="In Teldrassil sammeln Druiden Wasser aus dem Mondbrunnen des Oracle Trees.",kw={"amethystphiole","corithras mondzorn","crown of the earth","gefüllte amethystphiole","mondbrunnen","die lichtung des orakels","oracle tree","teldrassil"},ang={["class:Druid"]="Als Druide wisst Ihr, dass die Druiden des Cenarius Mondbrunnen als Quellen der Natur- und Astralenergie verehren. Sie verwenden gereinigte Gefäße wie diese Phiole, um Teldrassils verderbtes Ökosystem zu untersuchen.",["race:NightElf"]="Als Kaldorei füllt Ihr diese Phiole in dem Wissen, dass die Drachenaspekte Eure neue Heimat abgelehnt haben. Eure verlorene Unsterblichkeit ist nicht zurückgekehrt."},sec={{t="Wasser des Oracle Trees",b="Im Nordwesten von Teldrassil liegt die Lichtung des Orakels, wo der älteste und mächtigste Mondbrunnen unter dem Oracle Tree ruht. Andere Mondbrunnen auf den Ästen decken den täglichen Bedarf der Nachtelfen, doch dieses Wasser trägt die unverfälschte Essenz von Elune's Grace in sich. Druiden, die über die Gesundheit des Weltbaums wachen, sammeln es in Amethystphiolen für Untersuchungen und rituelle Reinigungen."},{t="Eine mangelhafte Erneuerung",b="Corithras Mondzorn nimmt die Probe entgegen, während Druiden über Teldrassils gestörtes Wachstum wachen. Erzdruide Fandral Hirschhaupt ließ den Baum als Ersatz für das gefallene Nordrassil wachsen, doch die Drachenaspekte weigerten sich, ihn zu weihen. Ohne Nozdormus Segen zur Wiederherstellung der Unsterblichkeit der Nachtelfen oder Alexstraszas Schutz für seine Lebenskraft bleibt Teldrassil im Wachstum gehemmt und von Verderbnis geplagt. Selbst die heiligen Wasser der Lichtung offenbaren das Leiden, das im Weltbaum Wurzeln schlägt."}},faq={{q="Woher stammt das Wasser in dieser Phiole?",a="Das Wasser stammt aus dem Mondbrunnen unter dem Oracle Tree auf der Lichtung des Orakels im Nordwesten von Teldrassil.",al={"wo befüllen","standort des mondbrunnens","brunnen des oracle tree"}},{q="Warum ist der Mondbrunnen auf der Lichtung des Orakels besonders?",a="Der Mondbrunnen auf der Lichtung des Orakels ist der erste und mächtigste Mondbrunnen, der auf Teldrassil erschaffen wurde. Unter dem uralten Oracle Tree birgt er die konzentrierte Essenz von Elunes Macht.",al={"warum lichtung des orakels","bedeutung des mondbrunnens des orakels"}},{q="Wer bittet Euch, dieses Wasser zu sammeln?",a="Corithras Mondzorn, ein in Dolanaar stationierter Nachtelfendruide, bittet Euch, das Wasser für die Rituale von Crown of the Earth zu sammeln.",al={"wer will die phiole","corithras quest"}},{q="Warum untersuchen die Druiden Teldrassils Mondbrunnen?",a="Die Druiden untersuchen Teldrassils Mondbrunnen, weil der Baum ohne den Segen der Drachenaspekte heranwuchs und weiterhin verwundbar ist. Die Proben helfen ihnen, seine Verderbnis und sein gehemmtes Wachstum zu überwachen.",al={"warum das wasser untersuchen","teldrassils krankheit"}}},fx={d7e170ec={q="Was ist die Gefüllte Amethystphiole?",a="Die Gefüllte Amethystphiole ist ein Gefäß, das heiliges Wasser aus dem Mondbrunnen enthält, der unter dem Orakelbaum auf der Lichtung des Orakels liegt. Da er als der erste und mächtigste der Mondbrunnen von Teldrassil bekannt ist, enthält sein schimmerndes Wasser die konzentrierte Essenz von Elune's Grace, was diese Probe für die Kaldorei, die den Gesundheitszustand der Insel untersuchen, von entscheidender Bedeutung macht.",al={"was ist eine gefüllte amethystphiole","gegenstand gefüllte amethystphiole","zweck amethystphiole"}}},fp="21,165,24.345.0,16.457.1,45.100.0,44.173.0,34.125.0,50.195.0"}
P.entries["item:filled-blue-waterskin"] = {n="Voller blauer Wasserschlauch",s="In den Sternenstaubruinen suchen Schamanen Wasser für ihre Prüfungen. Der Volle blaue Wasserschlauch enthält eine reine Probe aus einem uralten Brunnen.",h="In den Sternenstaubruinen suchen Schamanen Wasser für ihre Prüfungen.",kw={"eschental","brine","call of water","voller blauer wasserschlauch","lake mystral","die sternenstaubruinen","schamanenquest"},ang={["class:Shaman"]="Als Schamane sammelt Ihr dieses Wasser als letzten Schritt auf dem Weg zur Beherrschung des Wassers. Ihr überschreitet die Grenzen feindlicher Fraktionen, um mit den reinsten Wasserreservoirs der Natur Zwiesprache zu halten.",["faction:Horde"]="Als Initiand der Horde wagt Ihr Euch nach Norden in die umkämpften Wälder des Eschentals und das angestammte Gebiet der Nachtelfen, um heilige Riten zu vollziehen. Auf dem Weg lauert echte Gefahr."},sec={{t="Heilige Quelle des Eschentals",b="Initianden von Call of Water reisen vom Brachland nach Norden in die dichten Wälder des Eschentals. Jenseits von Lake Mystral schmiegen sich die Sternenstaubruinen an die Berge zwischen dem Eschental und dem Steinkrallengebirge. Wilde Waldtiere bewachen das abgelegene Elfenheiligtum. Inmitten seines Sees birgt ein unberührter Brunnen Wasser, das frei von Verderbnis oder Dürre ist. Ein dort gefüllter blauer Wasserschlauch enthält die Probe, die Schamanenmeister für die rituelle Einstimmung suchen."},{t="Ein Ritus des Einklangs",b="Brine lebt als Einsiedlerin auf einem Hügel im südlichen Brachland. Sie kennt sich mit Wasser gut aus und benötigt diese letzte Probe. Brine vermischt sie mit Wasser aus gegensätzlichen Brunnen und Quellen und destilliert daraus eine reine Essenz als Opfergabe. Die Gabe kann die Elementargeister des Wassers herbeirufen und besänftigen und so die Prüfung eines Initianden vollenden."}},faq={{q="Wo wird das Wasser für diesen Wasserschlauch geschöpft?",a="Das Wasser stammt aus einem kleinen Brunnen inmitten des Sees in den Sternenstaubruinen, im Südwesten des Eschentals jenseits von Lake Mystral.",al={"wo auffüllen","brunnen der sternenstaubruinen","wasserfundort"}},{q="Wer benötigt dieses Wasser?",a="Brine, eine Einsiedlerin im südlichen Brachland, benötigt das Wasser für die Prüfungen von Call of Water, die sie Schamanennovizen auferlegt.",al={"wer will den blauen wasserschlauch","brine wasser","call of water npc"}},{q="Wozu wird diese Probe gesammelt?",a="Brine benötigt diese letzte Probe, um einen Trank aus außergewöhnlich reinem Wasser zu brauen. Er ermöglicht einem angehenden Schamanen, mit den Elementargeistern des Wassers Zwiesprache zu halten und sie zu ehren.",al={"wozu wird er benötigt","wofür wird der volle blaue wasserschlauch verwendet"}},{q="Ist das Gebiet, in dem das Wasser geschöpft wird, gefährlich?",a="Ja. In den Sternenstaubruinen leben feindselige Kreaturen, darunter heimische Elementare und wilde Tiere, die die uralte Elfenlichtung verteidigen.",al={"gefahr in den sternenstaubruinen","ist der brunnen im eschental sicher"}}},fx={["031dd284"]={q="Was ist der Voller blauer Wasserschlauch?",a="Der Voller blauer Wasserschlauch ist ein Ledergefäß, gefüllt mit reinem Quellwasser, das aus einem Brunnen in The Ruins of Stardust, tief in den Wäldern des Eschentals, gesammelt wurde. Er dient als eine der wesentlichen Elementarproben, die ein Schamane für die heiligen Prüfungen von Call of Water benötigt.",al={"was ist ein voller blauer wasserschlauch","gegenstand voller blauer wasserschlauch"}},eff34fc2={q="Woher kommt der Voller blauer Wasserschlauch und wer hat ihn hergestellt?",a="Der Wasserschlauch selbst ist ein leerer Beutel, den Ihr von Brine, einer Eremitin im südlichen Brachland, erhaltet. Er wird zum Vollen blauen Wasserschlauch, sobald Ihr in den Norden in das uralte Elfengebiet des Eschentals reist und frisches Wasser aus dem heiligen Brunnen schöpft, der sich in der Mitte des Sees bei The Ruins of Stardust befindet.",al={"woher stammt der volle blaue wasserschlauch","wer hat den vollen blauen wasserschlauch hergestellt","quelle des vollen blauen wasserschlauchs"}},["320c16da"]={q="Warum möchte Brine den Vollen blauen Wasserschlauch haben?",a="Brine benötigt diese Probe als letzte Komponente einer dreiteiligen Sammlung reinen Wassers aus ganz Azeroth. Indem sie sie mit den anderen von Euch gesammelten Quellen kombiniert, stellt sie eine Phiole mit makellosem, reinem Wasser her, die für die nächste Phase Eures schamanischen Übergangsritus erforderlich ist.",al={"warum braucht brine vollen blauen wasserschlauch","warum wird voller blauer wasserschlauch gesucht","zweck von voller blauer wasserschlauch"}}},fp="21,134,26.430.0,17.310.0,51.136.0,24.110.0,46.160.0,50.135.0"}
P.entries["item:filled-brown-waterskin"] = {n="Voller brauner Wasserschlauch",s="Im Brachland bringt der Volle braune Wasserschlauch frisches Wasser aus dem Teich unter Brines Hütte. Angehende Schamanen bringen ihn zu ihr, um mit dem Brauen von Sapta zu beginnen, das ihnen die Zwiesprache mit Wassergeistern ermöglicht.",h="Im Brachland bringt der Volle braune Wasserschlauch frisches Wasser aus dem Teich unter Brines Hütte.",kw={"brachland","brine","brauner wasserschlauch","call of water","voller brauner wasserschlauch","quilboar","sapta","schamanenquest"},ang={["class:Shaman"]="Als Schamane holt Ihr dieses Wasser als Brines erste praktische Prüfung im Rahmen von Call of Water. Dabei lernt Ihr, das Gleichgewicht des Wassers und die heftigen Leidenschaften zu achten, die es weckt."},sec={{t="Eine lebensspendende Dürre",b="Unter Brines Hütte bietet ein Teich frisches Wasser, das im Brachland selten ist. Die Quilboar in der Nähe kämpfen erbittert darum. Ein Schamanenlehrling erkennt, wie Knappheit die Geschöpfe dazu treibt, das zu verteidigen, was sie am Leben hält."}},faq={{q="Wofür wird der Volle braune Wasserschlauch verwendet?",a="Ihr bringt das Wasser zu Brine in ihrer Hütte im Südlichen Brachland. Damit beginnt sie, Sapta zuzubereiten, einen Trank, der Schamanen erlaubt, Wassergeister wahrzunehmen und mit ihnen Zwiesprache zu halten.",al={"brauner wasserschlauch verwendung","was ist voller brauner wasserschlauch","was tun mit vollem braunem wasserschlauch"}},{q="Woher stammt dieses Wasser?",a="Das Wasser stammt aus einem kleinen Süßwasserteich, ein Stück den Kamm hinab unter Brines abgelegener Hütte. Die örtlichen Quilboar kämpfen erbittert darum.",al={"wo wasser holen","lage des teichs","wo ist die wasserstelle"}},{q="Warum kämpfen die Quilboar um diese Wasserquelle?",a="Regen ist im dürren Brachland äußerst selten, daher feiern die Quilboar Feste, wenn er fällt. Sie verteidigen natürliche Quellen gegen Außenstehende, selbst bis zum Tod.",al={"warum greifen quilboar an","quilboar wasser","warum ist wasser den quilboar heilig"}}},fx={["52b5cef0"]={q="Was ist der Voller brauner Wasserschlauch?",a="Es ist ein einfacher Wasserschlauch, der aus dem Süßwasserteich unterhalb von Brines Hütte im trockenen Brachland gefüllt wurde. Als Teil der Prüfung eines Schamanen gezogen, dient dieses Wasser als reine Elementarprobe und zeigt, wie selbst eine bescheidene Ansammlung von Feuchtigkeit Leben erhalten und Konflikte in einer ausgedörrten Wüste schüren kann.",al={"voller brauner wasserschlauch","was ist ein voller brauner wasserschlauch","was ist der braune wasserschlauch"}}},fp="22,194,21.186.0,44.170.0,32.130.0,49.153.0"}
P.entries["item:filled-cliffspring-falls-sampler"] = {n="Gefüllte Probe der Klippenquellfälle",s="Nahe den Cliffspring Falls in Dunkelküste enthält die Gefüllte Probe der Klippenquellfälle fauliges Wasser aus den Quellgewässern. Der Zirkel des Cenarius braucht sie, um die Krankheit zu untersuchen, die die einheimischen Hirsche befällt.",h="Nahe den Cliffspring Falls in Dunkelküste enthält die Gefüllte Probe der Klippenquellfälle fauliges Wasser...",kw={"alanndarian nachtweise","auberdine","zirkel des cenarius","cliffspring falls","dunkelküste","dendrite sternenschauer","vergiftetes wasser","probe"},ang={["class:Druid"]="Als Druide stellt Ihr Euch einer Bewährungsprobe, indem Ihr dieses verseuchte Wasser beschafft und untersucht. Zugleich legt Ihr damit den Grundstein, um Cure Poison zu meistern.",["race:NightElf"]="Als Nachtelf aus Dunkelküste helft Ihr, die Quellgewässer von Cliffspring zu sichern und Auberdines Ökosystem vor fauliger, fremder Verderbnis zu schützen."},sec={{t="Eine verseuchte Quelle",b="Die Cliffspring Falls führen Wasser aus dem östlichen Hochland durch weite Teile von Dunkelküste. Nun erkranken die einheimischen Hirsche an einer unnatürlichen Krankheit. Auf Bitten von Dendrite Sternenschauer in Mondlichtung schöpfen druidische Initianden Wasser an einem Höhleneingang, wo feindselige Naga hausen. Die Phiole enthält sichtbar fauliges Wasser, ein Beweis dafür, dass die Frischwasserversorgung verseucht ist."},{t="Weg zu einem Heilmittel",b="Alanndarian Nachtweise in Auberdine nimmt das faulige Wasser entgegen, damit der Zirkel des Cenarius es untersuchen kann. Statt es wegzuschütten, untersucht Alanndarian das darin enthaltene Gift. Indem die Druiden die Eigenschaften des Schlamms erforschen, können sie eine heilende Salbe herstellen. Das ist ein wesentlicher Schritt zu einem Ritus, der den Ausübenden Macht über Gift verleiht."}},faq={{q="Was enthält die Gefüllte Probe der Klippenquellfälle?",a="Die Probe enthält verseuchtes Wasser, das an einem Höhleneingang nahe den Cliffspring Falls in Dunkelküste geschöpft wurde. Das Wasser ist sichtbar verfärbt und enthält das Gift, das die einheimischen Hirsche krank macht.",al={"inhalt der probe","welches wasser ist in der phiole","was ist in der probe"}},{q="Wer bittet um diese Wasserprobe?",a="Dendrite Sternenschauer vom Zirkel des Cenarius bittet junge Druiden, die Probe zu sammeln. Alanndarian Nachtweise in Auberdine nimmt sie entgegen, um das Gift zu untersuchen und ein Heilmittel zu entwickeln.",al={"wer will die wasserprobe","wem die probe geben","wer braucht die gefüllte probe"}},{q="Warum sind die Cliffspring Falls so wichtig?",a="Die Cliffspring Falls sind die wichtigste Trinkwasserquelle von Dunkelküste. Die Verderbnis in den Wasserfällen breitet sich durch die örtlichen Wasserläufe aus und schadet der Wildnis.",al={"warum cliffspring falls","bedeutung der cliffspring falls"}},{q="Was lässt das Wasser faulig werden?",a="Feindselige Naga haben eine Höhle nahe den Quellgewässern überrannt, wo das Wasser geschöpft wird. Ihre Anwesenheit fällt mit der Verunreinigung des Wassers und Erkrankungen unter den einheimischen Tieren zusammen.",al={"wer hat das wasser vergiftet","warum sind die wasserfälle vergiftet","naga cliffspring falls"}}},fx={["57552b8f"]={q="Woher kommt die Gefüllte Probe der Klippenquellfälle und wer hat sie hergestellt?",a="Das leere Probenröhrchen aus Glas wird jungen Druiden von Dendrite Sternenschauer in der Mondlichtung im Namen des Zirkels des Cenarius zur Verfügung gestellt. Es wird zur Gefüllten Probe der Klippenquellfälle, sobald Ihr sie zum Eingang der von Nagas verseuchten Höhle neben den Cliffspring Falls an der Dunkelküste bringt und Wasser direkt aus dem besudelten Bach zieht.",al={"ursprung gefüllte probe der klippenquellfälle","wer hat die klippenquellfall-probe hergestellt","wo bekommt man die klippenquellfall-probe"}}},fp="32,189,16.340.0,16.310.1,52.176.0,31.171.0,38.152.0,39.156.0"}
P.entries["item:filled-containment-coffer"] = {n="Gefüllte Verwahrungskästen",s="In Unterstadt fangen Zauberkundige der Verlassenen unberechenbare magische Wesenheiten zu Forschungszwecken ein. Eine Inkantation der Manifestation enthüllt und schwächt Rissbruten im Apothekarium, sodass Magier sie in Kästen einschließen können.",h="In Unterstadt fangen Zauberkundige der Verlassenen unberechenbare magische Wesenheiten zu Forschungszwecken...",kw={"algernon","anastasia hirschbrunn","das apothekarium","arkane störung","inkantation der manifestation","verwahrungskasten","gefüllte verwahrungskästen","rissbrut"},ang={["class:Mage"]="Als Lehrling der Verlassenen lernt Ihr den Umgang mit Verwahrungskästen als praktische Übung in der Bannmagie. Ihr lernt, verborgene magische Wesenheiten zu enthüllen und instabile arkane Energie in greifbare Schutzzauber zu binden.",["race:Undead"]="Als Untoter wisst Ihr, dass die Sicherheit des Apothekariums für die Verlassenen von großer Bedeutung ist. Einen rätselhaften magischen Durchbruch zu untersuchen und einzudämmen, ist ein dringendes Anliegen in Eurer Heimat."},sec={{t="Das Unsichtbare einfangen",b="Magische Störungen plagen Algernons Laden im Apothekarium. Anastasia Hirschbrunn, eine Magierin der Verlassenen, hat arkane Zauberkundige aufgerufen, die dafür verantwortlichen Wesenheiten einzufangen. Risskreaturen sind lebendige magische Energie, für das Auge unsichtbar, und gewöhnliche Käfige können sie nicht halten.\n\nZauberkundige enthüllen die Kreaturen mit einer Inkantation der Manifestation, besiegen sie im Kampf und lassen dann vorbereitete Kästen um sie herum zuschnappen. Die versiegelten Kästen schützen ihre Träger vor unberechenbaren magischen Rückschlägen und bewahren die Kreaturen unversehrt für magische Sektionen."},{t="Arkane Spurensuche",b="Lebendige Manakreaturen stellen in Unterstadt eine ernste Bedrohung dar. Sobald die Bestien in Verwahrungskästen versiegelt sind, werden sie zu Anastasia Hirschbrunn und den Gelehrten der Stadt gebracht. Die Magier der Verlassenen wollen herausfinden, ob die Eindringlinge aus natürlichen Rissen in Azeroths magischem Gefüge stammen oder Vorstöße eines planmäßigen magischen Angriffs auf das Königreich sind."}},faq={{q="Was steckt in einem der Gefüllten Verwahrungskästen?",a="Jeder Kasten enthält eine gefangene Rissbrut, eine unsichtbare Kreatur aus roher magischer Energie, die in Algernons Alchemieladen im Apothekarium erschienen ist.",al={"was ist im kasten","kasteninhalt","monster im gefüllten kasten"}},{q="Wie wird ein Verwahrungskasten gefüllt?",a="Ein Magier liest die Inkantation der Manifestation, um die verborgenen Kreaturen zu enthüllen, und besiegt sie dann im Kampf. Der Magier fängt die verbleibende Energie in einem leeren Kasten ein, bevor sie sich verflüchtigt.",al={"wie kasten füllen","wie die rissbrut einfangen","kasten füllen"}},{q="Wer möchte diese gefüllten Kästen in Unterstadt haben?",a="Anastasia Hirschbrunn, eine angesehene Magierlehrerin im Magieviertel von Unterstadt, bittet um die versiegelten Kästen, um die Störung zu untersuchen, die die Stadt bedroht.",al={"wer nimmt die kästen","questgeber für kästen","anastasia hirschbrunn kasten"}},{q="Warum erforschen die Verlassenen diese Kreaturen?",a="Die Gelehrten von Unterstadt wollen herausfinden, ob die Anomalie durch einen zufälligen Riss im örtlichen Magiefluss oder einen gezielten, koordinierten Angriff einer feindlichen magischen Macht entstand.",al={"warum rissbruten erforschen","grund für risse in unterstadt"}}},fx={d6cc8dac={q="Was ist ein Gefüllter Verwahrungskasten?",a="Ein Gefüllter Verwahrungskasten ist ein verzauberter Behälter, den Magier verwenden, um flüchtige Wesen einzufangen und festzuhalten, die rein aus magischer Energie bestehen, wie zum Beispiel Rissbrut. Sobald die Kreatur sichtbar gemacht und unterworfen wurde, sichert der Kasten sie sicher für den Transport und die Untersuchung, ohne dass ihre magische Essenz entweicht.",al={"was ist ein gefüllter verwahrungskasten","gefüllte verwahrungskästen","gegenstand verwahrungskasten"}},["1e3ef013"]={q="Woher kommt ein Gefüllter Verwahrungskasten und wer hat ihn hergestellt?",a="Die leeren Kästen sind spezialisierte arkanische Geräte, die von Magierausbildern wie Anastasia Hirschbrunn in der Unterstadt bereitgestellt werden. Sie werden gefüllt, wenn ein kundiger Magier unsichtbare magische Entitäten aufspürt – wie jene, die um Algernons Laden im Apothekarium lauern –, sie zwingt, sich zu manifestieren, sie schwächt und sie im Inneren versiegelt.",al={"wer hat den verwahrungskasten hergestellt","ursprung des verwahrungskastens","woher kommen verwahrungskästen"}}},fp="25,201,19.535.0,16.350.0,43.150.0,35.181.0,44.159.0,46.169.0"}
P.entries["item:filled-crystal-phial"] = {n="Gefüllte Kristallphiole",s="In Laubschattental sammeln junge Nachtelfen Wasser aus dem Mondbrunnen nördlich von Aldrassil. Tenaron Sturmgewalt macht dies zu ihrer ersten Lektion über Teldrassils heilige Macht.",h="In Laubschattental sammeln junge Nachtelfen Wasser aus dem Mondbrunnen nördlich von Aldrassil.",kw={"aldrassil","crown of the earth","kristallphiole","gefüllte kristallphiole","mondbrunnen","laubschattental","tenaron sturmgewalt","brunnen der ewigkeit"},ang={["class:Druid"]="Als Druide verehrt Ihr das Mondbrunnenwasser zutiefst und nutzt seine belebende Energie, um verderbte Pflanzen zu pflegen und die großen Bäume zu erhalten.",["race:NightElf"]="Als junger Kaldorei, der seine Ausbildung unter Aldrassil beginnt, füllt Ihr diese Phiole und denkt über das Opfer am Hyjal und Eure heilige Pflicht nach, die Natur zu schützen."},sec={{t="Wasser des Mondbrunnens",b="Tenaron Sturmgewalt schickt junge Nachtelfen aus, um Mondbrunnenwasser zu sammeln, bevor sie in die weite Welt hinausziehen. Der Mondbrunnen liegt in Laubschattental, und sein Wasser birgt Energien, die auf den uralten Brunnen der Ewigkeit zurückgehen. Schildwachen ehren Mondbrunnen als Schreine von Elune. Druiden nutzen ihre heilende Kraft, um die Natur zu pflegen, während die arkane Zauberei der Vorzeit weiterhin verboten bleibt.\n\nMit dem Sammeln des Wassers beginnt eine Lektion über das Opfer am Hyjal und die Fürsorge, die Teldrassil zum Gedeihen braucht."}},faq={{q="Was befindet sich in der Gefüllten Kristallphiole?",a="Die Gefüllte Kristallphiole enthält Wasser aus dem Mondbrunnen nördlich von Aldrassil in Laubschattental. Das Wasser trägt Überreste des uralten Brunnens der Ewigkeit in sich, gesegnet vom Licht Elunes und durch druidische Fürsorge genährt.",al={"welches wasser ist in der phiole","inhalt der phiole","was ist in der kristallphiole"}},{q="Wer bittet Euch, die Phiole zu füllen?",a="Tenaron Sturmgewalt, der hoch oben auf den Ästen von Aldrassil seinen Posten hat, bittet angehende Abenteurer, das Wasser als Aufnahmeritus und Geschichtslektion zu schöpfen.",al={"wer will die phiole","wer gibt die quest zur kristallphiole","tenaron sturmgewalt quest"}},{q="Warum will Tenaron Sturmgewalt dieses Wasser?",a="Tenaron nutzt das Sammeln als erste Lektion über die Geschichte der Nachtelfen nach dem Dritten Krieg. Junge Abenteurer erfahren von Nordrassils Opfer, der Macht der Mondbrunnen und der fortwährenden Pflege Teldrassils.",al={"warum die kristallphiole füllen","zweck von crown of the earth"}},{q="Ist das Wasser gefährlich?",a="Das Wasser birgt mächtige Magie, die im uralten Brunnen der Ewigkeit wurzelt. Druiden und Priesterinnen nutzen es gefahrlos für Segnungen und Heilung, doch leichtfertiger Umgang mit arkaner Magie führte in der Vorzeit zur Katastrophe und bleibt verboten.",al={"ist mondbrunnenwasser gefährlich","ist das wasser magisch"}}},fx={e7bb2009={q="Was ist die Gefüllte Kristallphiole?",a="Die Gefüllte Kristallphiole ist ein zartes Kristallgefäß, das Wasser aus dem Mondbrunnen in Laubschattental enthält. Sie enthält die reine, heilige Flüssigkeit, die mit der uralten Macht des Brunnens der Ewigkeit durchtränkt ist, und soll sowohl als heiliges Opfer als auch als praktische Lektion in der fortwährenden spirituellen Verantwortung Eures Volkes dienen.",al={"was ist eine gefüllte kristallphiole","gefüllte kristallphiole","gegenstand gefüllte kristallphiole"}},e140e7c7={q="Woher kommt die Gefüllte Kristallphiole?",a="Sie wird erschaffen, wenn Ihr eine leere Kristallphiole nehmt, die Euch von Tenaron Sturmgewalt gegeben wurde, und sie direkt in das Wasser des heiligen Mondbrunnens eintaucht, der sich nördlich von Aldrassil in Laubschattental befindet.",al={"ursprung gefüllte kristallphiole","woher stammt die gefüllte kristallphiole","wie erhält man die gefüllte kristallphiole"}}},fp="20,161,22.471.0,40.210.0,31.149.0,43.202.0,25.228.0"}
P.entries["item:filled-cursed-ooze-jar"] = {n="Mit verfluchtem Schlamm gefülltes Glas",s="Im Teufelswald enthält ein mit verfluchtem Schlamm gefülltes Glas eine Probe für Laris Bummelritzel in Eisenschmiede. Der Gnomengelehrte erforscht die uralten Ursprünge der Schlämme auf ganz Azeroth.",h="Im Teufelswald enthält ein mit verfluchtem Schlamm gefülltes Glas eine Probe für Laris Bummelritzel in...",kw={"verfluchter brühschlammer","forscherliga","teufelswald","mit verfluchtem schlamm gefülltes glas","eisenschmiede","laris bummelritzel","schlamm"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr sehen, wie Naturphilosophen in Eisenschmiede die Bewegungen der Verlassenen beobachten. Auch die Royal Apothecary Society hat ein finsteres Interesse daran gezeigt, auf ganz Azeroth Brühschlammproben zu sammeln.",["race:Gnome"]="Als Gnom könnt Ihr verstehen, warum Laris Bummelritzel die Schlammforschung so sehr am Herzen liegt. Er hofft, die vertriebenen Gnome zu ehren und ihren zwergischen Gastgebern in Eisenschmiede ihren geistigen Wert zu beweisen."},sec={{t="Eine kuriose Probe",b="Laris Bummelritzel, ein Gnomenforscher, sieht ein Rätsel in den widerlichen Pfützen und ätzenden Schlämmen, an denen andere vorbeigehen. Schlämme gedeihen auf ganz Azeroth, und Apotheker der Verlassenen sammeln sie mit Sorgfalt. Diese Beobachtungen brachten Bummelritzel auf eine kühne Theorie: Brühschlämmer könnten urzeitliche Sekrete sein, die mit Azeroths Schöpfung verbunden sind. Um eine Probe zu sammeln, trotzt den verheerten Wäldern des Teufelswalds und besiegt einen verfluchten Brühschlammer. Schöpft seine ätzenden Überreste in ein leeres Glas, bevor sie sich auflösen."},{t="Gelehrter Ehrgeiz",b="Laris Bummelritzel hofft, dass seine Brühschlammproben ihm Wissen und einen bleibenden Namen einbringen. Eine bedeutende Entdeckung könnte seinen Ruf in der von Zwergen geführten Forscherliga festigen. Seit dem Fall von Gnomeregan fühlen sich viele Gnomenflüchtlinge in Eisenschmiede gedrängt, ihren zwergischen Gastgebern ihren Wert zu beweisen. Bummelritzel glaubt, dass die Enthüllung der uralten Geheimnisse des Brühschlamms ihnen zeigen wird, dass die Aufnahme der Gnome kein Fehler war."}},faq={{q="Woher stammt dieses Glas?",a="Benutzt einen leeren verfluchten Brühschlammerkrug an den Überresten eines besiegten verfluchten Brühschlammers in den verderbten Landen des Teufelswalds, um ihn zu füllen.",al={"woher kommt der verfluchte brühschlammerkrug","wie erhält man mit verfluchtem schlamm gefülltes glas","brühschlammerkrug fundort"}},{q="Wer möchte diese Brühschlammproben?",a="Laris Bummelritzel, ein Gnomenforscher in der Hall of Explorers in Eisenschmiede, möchte die Proben für seine naturkundlichen Forschungen.",al={"wer braucht brühschlammerkrüge","laris bummelritzel quest","wer gibt den brühschlammerkrug ab"}},{q="Warum erforscht Laris Bummelritzel Brühschlämmer?",a="Laris Bummelritzel erforscht Brühschlämmer, weil er beobachtet, wie die Natur und die Royal Apothecary Society Interesse an ihnen zeigen. Er vermutet, dass Schlämme uralte Sekrete sein könnten, die mit der Entstehung und Entwicklung des Lebens auf Azeroth zusammenhängen, und braucht Proben, um seine Theorie zu prüfen.",al={"warum schlämme erforschen","bummelritzels brühschlammtheorie","warum brühschlamm"}},{q="Warum interessiert sich ein Gnom für die Forscherliga?",a="Nach dem Fall von Gnomeregan fanden Gnomenflüchtlinge bei den Zwergen in Eisenschmiede Zuflucht. Laris Bummelritzel hofft, dass eine bedeutende Entdeckung durch die Forscherliga beweisen wird, dass es richtig war, ihnen Zuflucht zu gewähren.",al={"warum forscherliga","gnome in eisenschmiede"}}},fx={b5982a20={q="Was ist das Mit verfluchtem Schlamm gefüllte Glas?",a="Es ist ein speziell vorbereiteter Probenbehälter, der mit einer frischen Probe gefüllt ist, die einem getöteten verfluchten Schlammwesen im Teufelswald entnommen wurde. Diese garstigen, korrumpierten Schlammwesen gedeihen inmitten des dämonischen Verfalls des besudelten Waldes, was selbst kleine Überreste unbeständig und gefährlich in der Handhabung ohne geeignete Glaswaren macht.",al={"was ist ein mit verfluchtem schlamm gefülltes glas","zweck des mit verfluchtem schlamm gefüllten glases","verfluchtes schlammglas"}}},fp="22,158,18.436.0,17.395.0,30.110.0,29.122.0,39.249.0,50.203.0"}
P.entries["item:filled-dreadmist-peak-sampler"] = {n="Gefüllte Glutnebelgipfelprobe",s="Am Glutnebelgipfel sammeln Druiden der Horde Wasser aus den Gipfelteichen zur Untersuchung. Der Zirkel des Cenarius will herausfinden, was die Tierwelt im nördlichen Brachland vergiftet.",h="Am Glutnebelgipfel sammeln Druiden der Horde Wasser aus den Gipfelteichen zur Untersuchung.",kw={"burning blade","zirkel des cenarius","glutnebelgipfel","druide","gefüllte glutnebelgipfelprobe","brachland","the principal source","tonga runentotem"},ang={["class:Druid"]="Als Druide der Horde sammelt Ihr diese Probe im Rahmen eines Übergangsritus. Dabei lernt Ihr, wie sich Verderbnis durch natürliche Wasserwege ausbreitet, und bereitet Euch darauf vor, heilende Magie zu meistern.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr sehen, wie die Bedrohung durch den Kult der Burning Blade im Gebiet der Horde im Brachland wächst."},sec={{t="Eine verseuchte Quelle",b="Die hohen Klippen des Glutnebelgipfels bergen Teiche, deren Nebel Wetter und Regenfälle im gesamten nördlichen Brachland prägen. Die Burning Blade beten Dämonen an und haben ihren Zirkel auf dem Gipfel errichtet. Bald darauf verdarb das Wasser. Die Druiden des Zirkels des Cenarius vermuten, dass dämonische Rituale die Dämpfe vergiftet haben, die die umliegende Savanne speisen.\n\nSie entsenden Initianden, um mit einem speziellen Sammler eine Probe zu entnehmen. Die üble Flüssigkeit bestätigt ihre Befürchtungen. Ihre Verderbnis kann die Herden unterhalb des Gipfels krank machen."},{t="Heilung für die Savanne",b="Am Wegekreuz untersucht Tonga Runentotem die Probe, um bei der Suche nach einem Gegenmittel zu helfen. Die Burning Blade stehen im Verdacht, das Wasser verseucht zu haben, und seine Eigenschaften helfen dem Zirkel des Cenarius, das Gift zu verstehen.\n\nDurch die Untersuchung der Verderbnis in der Phiole stellen Druiden pflanzliche Heilmittel für sterbende Gazellen her. Sie lernen auch, ihre eigene natürliche Macht über Gift einzusetzen."}},faq={{q="Wo wird diese Wasserprobe entnommen?",a="Die Probe stammt aus einem Teich auf dem Glutnebelgipfel, nordwestlich vom Wegekreuz im Brachland.",al={"wo die probe holen","glutnebelgipfel sammler fundort","wo den sammler füllen"}},{q="Warum ist das Wasser auf dem Glutnebelgipfel verseucht?",a="Der Kult der Burning Blade hat die Höhen des Glutnebelgipfels besetzt, um Dämonen anzubeten. Dendrite Sternenschauer vermutet, dass der Kult die natürlichen Gewässer des Gipfels verseucht hat.",al={"warum ist das wasser am glutnebelgipfel vergiftet","wer hat den glutnebelgipfel vergiftet","burning blade wasser"}},{q="Wer braucht den gefüllten Sammler?",a="Tonga Runentotem braucht den gefüllten Sammler. Er ist ein Druide des Zirkels des Cenarius am Wegekreuz und untersucht die plötzliche Erkrankung der Tierwelt im Brachland.",al={"zu wem den sammler bringen","tonga runentotem sammler","glutnebelgipfelwasser abgeben"}},{q="Wie wirkt sich dieses vergiftete Wasser auf das Brachland aus?",a="Die luftigen Höhen und Teiche des Glutnebelgipfels beeinflussen das örtliche Wetter und den Nebel. Sobald die Dämpfe vergiftet sind, legen sie sich über die Savanne nördlich der Hauptstraße und machen die dort heimischen Gazellen krank.",al={"was bewirkt das wasser","kranke gazellen brachland","glutnebelgipfel nebel wirkung"}},{q="Wofür wird der Sammler nach der Probenentnahme verwendet?",a="Tonga Runentotem untersucht die üble Flüssigkeit, um die Natur ihrer dämonischen Verderbnis zu ergründen. Mit diesem Wissen stellt er dann eine Heilsalbe her, mit der Druiden erkrankte Gazellen behandeln können.",al={"was macht tonga damit","heilmittel gegen das gift","power over poison erforschung"}}},fx={f843c928={q="Was ist die Gefüllte Glutnebelgipfelprobe?",a="Es ist eine spezielle Phiole, die eine gezogene Probe besudelten Wassers enthält, das direkt aus dem hohen Tümpel auf dem Glutnebelgipfel entnommen wurde. Sie wird Druidenlehrlingen vom Zirkel des Cenarius ausgehändigt und dient als entscheidender physischer Beweis für die üble Verderbnis, die derzeit durch die hohen Bergquellen sickert und die Tierwelt auf den nördlichen Ebenen ruiniert.",al={"was ist eine gefüllte glutnebelgipfelprobe","glutnebelgipfelprobe","gefüllte probe druide"}},["2e934816"]={q="Woher kommt die Gefüllte Glutnebelgipfelprobe und wer hat sie hergestellt?",a="Die leere Probenphiole aus Glas wird jungen Druiden, die die Kunst des Heilens von Krankheiten studieren, vom Zirkel des Cenarius in der Mondlichtung zur Verfügung gestellt. Ihr füllt sie persönlich am Gipfeltümpel des Glutnebelgipfels im Brachland, wo sich die dämonenanbetenden Kultisten der Burning Blade versammeln und die natürlichen Quellgewässer verschmutzen, was sich auf das umliegende Klima auswirkt.",al={"wer hat die glutnebelgipfelprobe hergestellt","woher stammt die glutnebelgipfelprobe","ursprung glutnebelgipfelprobe"}},cb57b91c={q="Warum will Tonga Runentotem die Gefüllte Glutnebelgipfelprobe?",a="Tonga Runentotem am Wegekreuz benötigt das Wasser dringend, um die Seuche zu untersuchen, die das nördliche Brachland befällt. Gazellen und die lokale Fauna erkranken schwer, und durch die Analyse dieses üblen Quellenmaterials vom Gipfel hofft Tonga, das unnatürliche Gift zu isolieren und ein wirksames pflanzliches Heilmittel zu brauen, um das Land zu heilen.",al={"warum will tonga die probe","tonga runentotem glutnebelgipfelprobe","warum die gefüllte glutnebelgipfelprobe besorgen"}}},fp="29,164,16.439.0,18.347.1,36.102.0,43.159.0,29.148.0,48.183.0,51.174.0"}
P.entries["item:filled-etched-phial"] = {n="Gefüllte geätzte Phiole",s="In Donnerfels suchen Tauren eine Dryadenphiole mit Mondbrunnenwasser. Seine seltene spirituelle Kraft kann die ewige Flamme um ein heiliges Relikt der Zentauren löschen.",h="In Donnerfels suchen Tauren eine Dryadenphiole mit Mondbrunnenwasser.",kw={"eschental","dryade","geätzte phiole","gefüllte geätzte phiole","galak","mondbrunnen","rau klippenläufer","tausend nadeln","zangen steinhuf"},ang={["race:NightElf"]="Als Nachtelf wisst Ihr, dass Agenten der Horde die heiligsten Stätten des Eschentals entweihen, wenn sie eine Dryadenphiole nehmen und Mondbrunnenwasser abschöpfen.",["race:Tauren"]="Als Tauren versetzt Ihr den Galakzentauren einen Schlag, indem Ihr dieses Wasser beschafft und Cenarius' gemeinsame Naturmagie gegen langjährige Feinde Eures Stammes wendet."},sec={{t="Mondbrunnenwasser und Dryadenkunst",b="Die Phiole muss im Gebiet der Nachtelfen tief im Eschental gefüllt werden. Dryaden rund um Rajenbaum tragen die leeren Gefäße, die dafür gefertigt sind, reine Heiltränke aufzunehmen. Ein heiliger Mondbrunnen nahe dem westlichen Ufer des Falfarren füllt eines mit Wasser, das mit himmlischer Kraft und Naturmacht verbunden ist. Nachtelfen betrachten die Entnahme des Wassers ohne Erlaubnis als Entweihung. Die Tauren brauchen es, um einer Bedrohung weiter südlich zu begegnen."},{t="Ein Schlüssel zur Zentaurenmagie",b="Zangen Steinhuf und Rau Klippenläufer suchten das Wasser wegen der tiefen Bande zwischen Dryaden und Zentauren. Beide führen ihre Abstammung auf Cenarius zurück, und ihre Magie teilt eine urzeitliche Resonanz. In Tausend Nadeln bewacht der Galakklan ein uraltes Relikt hinter einer unnachgiebigen Schutzflamme. Die Flamme soll aus der Zeit der Erschaffung des Zentaurenvolkes stammen. Mondbrunnenwasser in der Dryadenphiole kann den Schutz durchdringen und die Flamme löschen."}},faq={{q="Was befindet sich in der Gefüllten geätzten Phiole?",a="Die Gefüllte geätzte Phiole enthält heiliges Wasser aus einem Mondbrunnen der Nachtelfen im Eschental, nahe dem Falfarren. Dryaden nahe Rajenbaum fertigten das kunstvolle Glasgefäß.",al={"welches wasser ist in der phiole","womit ist die geätzte phiole gefüllt"}},{q="Warum brauchen die Tauren Mondbrunnenwasser?",a="Rau Klippenläufer braucht das geweihte Wasser, um die Schutzflamme um das Relikt der Galakzentauren in Tausend Nadeln zu durchdringen und zu löschen. Dryaden und Zentauren haben mit Cenarius einen gemeinsamen Vorfahren, wodurch das Wasser Macht gegen den uralten Schutz besitzt.",al={"warum mondbrunnenwasser","warum braucht rau mondbrunnenwasser"}},{q="Woher stammt die leere Phiole?",a="Laughing Sisters, Dryaden, die durch die Wälder rund um Rajenbaum im zentralen Eschental streifen, tragen die leeren Phiolen.",al={"wo ist die geätzte phiole zu finden","wie die leere phiole bekommen"}},{q="Wem übergebt Ihr die Gefüllte geätzte Phiole?",a="Nachdem Ihr das Wasser gesammelt habt, bringt Ihr es zuerst zu Zangen Steinhuf auf dem High Rise in Donnerfels. Er weist Euch an, es zu Rau Klippenläufer am Freiwindposten in Tausend Nadeln zu bringen.",al={"wer bekommt die phiole","phiole abgeben"}}},fp="19,147,31.401.0,24.415.1,39.168.0,38.241.1,37.116.0,46.180.0"}
P.entries["item:filled-jade-phial"] = {n="Gefüllte Jadephiole",s="In Dolanaar bringt eine Gefüllte Jadephiole heiliges Wasser aus Sternenhauch zu den zentralen Brunnen zurück. Junge Nachtelfen sammeln es, während sie die Geschichte ihres Volkes kennenlernen.",h="In Dolanaar bringt eine Gefüllte Jadephiole heiliges Wasser aus Sternenhauch zu den zentralen Brunnen zurück.",kw={"corithras mondzorn","crown of the earth","dolanaar","gefüllte jadephiole","jadephiole","mondbrunnen","sternenhauch","teldrassil"},ang={["class:Druid"]="Als Druide verbindet Euch die Pflege der Mondbrunnen mit der heilenden Magie, die Darnassus erhält und die Arbeit des Zirkels des Cenarius zur Pflege des jungen Weltbaums trägt.",["race:NightElf"]="Als junger Kaldorei erfüllt Ihr mit dem Wasserholen Eure heilige Pflicht gegenüber Teldrassil. Corithras lehrt Euch auch, wie die Nachtelfen nach der Schlacht am Hyjal ihre Unsterblichkeit verloren."},sec={{t="Die Wasser von Sternenhauch",b="Druiden in Darnassus schöpfen heiliges Wasser aus Mondbrunnen in ganz Teldrassil, um ihre zentralen Brunnen wieder aufzufüllen. In Dolanaar vertraut Corithras Mondzorn jungen Reisenden eine Jadephiole an, die das reine Wasser sicher verwahrt. Der Mondbrunnen außerhalb von Sternenhauch liegt östlich von Dolanaar. Initianden sammeln sein Wasser, während sie den Weltbaum pflegen."},{t="Eine Lektion in Geschichte",b="Wenn Ihr die Gefüllte Jadephiole nach Dolanaar zurückbringt, erzählt Corithras Mondzorn ein weiteres Kapitel der Geschichte der Kaldorei. Er berichtet, wie Nordrassil nach dem Dritten Krieg brannte und die Nachtelfen ihre Unsterblichkeit verloren. Der Verräter wurde freigelassen, und Shan'do Malfurion Sturmgrimm verschwand."}},faq={{q="Wo wird die Jadephiole gefüllt?",a="Füllt die Jadephiole am heiligen Mondbrunnen außerhalb von Sternenhauch, östlich von Dolanaar auf Teldrassil.",al={"wo die jadephiole füllen","wie die gefüllte jadephiole erhalten","mondbrunnen sternenhauch standort"}},{q="Wer benötigt die Gefüllte Jadephiole?",a="Corithras Mondzorn, ein älterer Nachtelf in Dolanaar, bittet Reisende, das Wasser für das Ritual Crown of the Earth zu holen.",al={"wer will die gefüllte jadephiole","corithras mondzorn questgegenstand"}},{q="Warum wird Mondbrunnenwasser in solchen Phiolen gesammelt?",a="Druiden in Darnassus verwenden eigens gefertigte Gefäße wie die Jadephiole, um reines Wasser aus Teldrassils entlegenen Brunnen herbeizuschaffen und ihre zentralen Mondbrunnen wieder aufzufüllen.",al={"warum mondbrunnenwasser sammeln","wozu dient die jadephiole"}},{q="Welche Geschichte erzählt Corithras bei der Abgabe?",a="Wenn Corithras Mondzorn die gefüllte Phiole erhält, erzählt er von den Folgen der Schlacht am Hyjal. Die Nachtelfen verloren ihre Unsterblichkeit, Illidan Stormrage wurde freigelassen, und Shan'do Malfurion Sturmgrimm verschwand ohne Erklärung.",al={"was erzählt corithras","crown of the earth hintergrundgeschichte"}}},fx={["10c296e8"]={q="Was ist die Gefüllte Jadephiole?",a="Die Gefüllte Jadephiole ist ein speziell angefertigtes Jadegefäß, das heiliges Wasser enthält, das direkt aus dem Mondbrunnen in der Nähe von Sternenhauch geschöpft wurde. Mit Mondenergie und der Anmut der Natur durchtränkt, ist solch geweihtes Wasser für die Nachtelfen lebenswichtig, um das Leben auf Teldrassil zu erhalten und ihre spirituellen Riten durchzuführen.",al={"was ist eine gefüllte jadephiole","gefüllte jadephiole lore","gefüllte jadephiole"}}},fp="17,170,20.330.0,19.278.0,31.102.0,35.120.0,54.161.0,55.239.0"}
P.entries["item:filled-pure-sample-jar"] = {n="Mit einer reinen Probe gefülltes Glas",s="In Eisenschmiede erforscht Laris Bummelritzel, wie Verderbnis lebende Materie verändert. Ein mit einer reinen Probe gefülltes Glas enthält urtümlichen Schleim aus der abgelegenen Wildnis und liefert ihm eine reine Vergleichsprobe.",h="In Eisenschmiede erforscht Laris Bummelritzel, wie Verderbnis lebende Materie verändert.",kw={"mit einer reinen probe gefülltes glas","klebriger schleim","eisenschmiede","laris bummelritzel","schleim","krater von un'goro"},ang={["faction:Alliance"]="Als Entdecker der Allianz könnt Ihr Gelehrten in Eisenschmiede Wissen über abgelegene Orte wie den Krater von Un'Goro bringen.",["race:Gnome"]="Als Gnom könnt Ihr Gelehrten helfen, lebende Materie zu erforschen, indem Ihr verdorbene Schleime aus dem Teufelswald mit reinen Exemplaren aus Un'Goro vergleicht."},sec={{t="Suche nach unverdorbenem Schleim",b="Laris Bummelritzel erforscht Schleime in ganz Azeroth und untersucht, wie Verderbnis lebende Materie verändert. Er entdeckte, dass diese formlosen Kreaturen die Magie und die Bedingungen ihres Lebensraums aufnehmen und dann widerspiegeln. Nachdem er verdorbene Schleime im Teufelswald katalogisiert hatte, suchte er eine reine Vergleichsprobe. Ein mit einer reinen Probe gefülltes Glas enthält urtümlichen Schleim aus der Wildnis des Kraters von Un'Goro, fernab von verdorbenen Stämmen."},{t="Urtümliche Ökologie",b="Schleime verändern sich rasch, daher findet Laris keine reinen Proben in der Nähe von Zivilisation, dämonischen Seuchen oder nekromantischen Rückständen. Die klebrigen Schleime im ungezähmten Becken des Kraters von Un'Goro bleiben von Verderbnis von außen relativ abgeschirmt. Das macht sie zu einem nützlichen Vergleichsmaßstab für Gelehrte in Eisenschmiede."}},faq={{q="Wer möchte diese reinen Proben?",a="Laris Bummelritzel, ein Gnomenforscher in Eisenschmiede, sucht reine Proben, um Azeroths Schleimpopulationen zu erforschen.",al={"laris bummelritzel quest","wer braucht mit einer reinen probe gefülltes glas","wer will die gläser"}},{q="Warum braucht Laris reinen statt verdorbenen Schleim?",a="Laris entdeckte, dass Schleime rasch Eigenschaften ihrer Umgebung aufnehmen, darunter die dämonische Fäulnis des Teufelswalds. Er braucht unverdorbene Proben zum Vergleich mit verdorbenem Schleim, um zu verstehen, wie weit die Verderbnis reicht und wie sie wirkt.",al={"warum reiner schleim","warum reine probe","zweck der schleimforschung"}},{q="Wo lassen sich reine Schleimproben sammeln?",a="Reine Proben stammen von den klebrigen Schleimen in der urtümlichen Wildnis des Kraters von Un'Goro, wo sie von Seuchen von außen abgeschirmt bleiben.",al={"wo reinen schleim finden","fundort mit einer reinen probe gefülltes glas","wo gläser mit reinen proben füllen"}},{q="Was geschieht, sobald die Proben in Eisenschmiede abgeliefert werden?",a="Laris untersucht anhand der Proben, wie Schleime sich an ihre Umwelt anpassen und ihr widerstehen. Er belohnt Abenteurer, die sich in gefährliche Wildnis wagen, um sie nach Eisenschmiede zu bringen.",al={"questbelohnung laris","was macht laris damit"}}},fx={["630b5cc1"]={q="Was ist ein Mit einer reinen Probe gefülltes Glas?",a="Es ist ein luftdichter Glasbehälter, der mit einer unverdorbenen Schlammprobe gefüllt ist. Im Gegensatz zu Schlammwesen, die durch dämonische Energien oder die Seuche korrumpiert sind, stellt die Substanz im Inneren eine unverunreinigte Grundlage des Schlammlebens dar, die sorgfältig für akademische Studien konserviert wurde.",al={"was ist ein mit einer reinen probe gefülltes glas","bedeutung reines probenglas","mit einer reinen probe gefülltes glas"}},e9b3a5fa={q="Woher kommt ein Mit einer reinen Probe gefülltes Glas?",a="Die leeren Behälter werden von Laris Bummelritzel in Eisenschmiede hergestellt und bereitgestellt. Ihr füllt sie selbst vor Ort, indem Ihr zähe Überreste von wilden, unkorrumpierten Schlammwesen erntet, die in unberührten natürlichen Umgebungen wie dem Krater von Un'Goro gedeihen.",al={"ursprung reines probenglas","woher kommen reine proben","wer hat das reine probenglas hergestellt"}}},fp="22,190,30.398.0,18.282.0,29.108.0,54.223.0,41.134.0,57.159.0"}
P.entries["item:filled-red-waterskin"] = {n="Voller roter Wasserschlauch",s="In Tarrens Mühle spendet ein Brunnen klares Quellwasser für die Prüfung eines Schamanen. Der volle rote Wasserschlauch enthält Wasser aus dem Dorfbrunnen, inmitten von Ruinen, die von den Verlassenen gehalten werden.",h="In Tarrens Mühle spendet ein Brunnen klares Quellwasser für die Prüfung eines Schamanen.",kw={"brine","call of water","leerer roter wasserschlauch","voller roter wasserschlauch","sapta","schamane","tarrens mühle"},ang={["class:Shaman"]="Als Schamane stellt Euch das Tragen dieses Wassers auf die Probe: Könnt Ihr selbst in den verfallensten, leidvollsten Winkeln der Welt lebensspendendes Gleichgewicht finden und ehren?",["faction:Horde"]="Als Champion der Horde aus Kalimdor reist Ihr nach Tarrens Mühle, wo die Verlassenen überall in den Östlichen Königreichen gegen Streitkräfte der Allianz kämpfen."},sec={{t="Ein Leuchtfeuer in verseuchten Landen",b="Brine schickt Schamaneninitianden aus ihrer Einsiedelei im Brachland nach Tarrens Mühle, um den Umgang mit Wasser zu erlernen. Die Reise führt ins Vorgebirge des Hügellands, wo Verfall und die Toten die Stadt umgeben. Doch der Brunnen in ihrem Herzen spendet noch immer klares Quellwasser.\n\nFür Brine besteht dieses reine Wasser als Zeichen des Lebens in einem unheiligen Land fort. Sie vergleicht die von Verderbnis unberührte Quelle mit Kriegshäuptling Thralls Entschlossenheit angesichts aller Widrigkeiten. Das Sammeln des Wassers prüft, ob ein Initiand dessen Reinheit auch in feindseliger Umgebung ehrt."}},faq={{q="Was befindet sich im vollen roten Wasserschlauch?",a="Der volle rote Wasserschlauch enthält reines Quellwasser, das aus dem öffentlichen Brunnen im Zentrum von Tarrens Mühle geschöpft wurde.",al={"welches wasser ist darin","wasser aus tarrens mühle","inhalt des roten wasserschlauchs"}},{q="Warum will Brine Wasser aus Tarrens Mühle?",a="Brine sieht die frische Quelle von Tarrens Mühle als seltenes Zeichen der Reinheit inmitten des Verfalls der Verlassenen. Sie braucht das Wasser, um Sapta für die Wasserprüfungen eines Schamanen zu brauen.",al={"warum tarrens mühle","warum brine das braucht","zweck des roten wasserschlauchs"}},{q="Wie bleibt der Brunnen in einer Stadt der Untoten sauber?",a="Niemand weiß, warum die Quelle von der Seuche ringsum unberührt geblieben ist. Brine sagt, die Verlassenen in Tarrens Mühle erkennen oder schätzen die Reinheit der heiligen Quelle in ihrer Mitte womöglich nicht.",al={"warum ist der brunnen nicht verseucht","ist der brunnen von tarrens mühle vergiftet","heiliger brunnen in tarrens mühle"}},{q="Was hat Thrall mit dieser Aufgabe zu tun?",a="Brine vergleicht den sauberen Brunnen in einer zerstörten Stadt mit Thrall. Er ertrug großes Leid und Gefangenschaft und ging daraus stark und unverdorben hervor, um das Volk der Orcs durch dunkle Zeiten zu führen.",al={"vergleich mit thrall","warum thrall erwähnen"}}},fx={c913c28c={q="Woher kommt der Voller roter Wasserschlauch?",a="Ihr erhaltet ihn, indem Ihr einen Leeren roten Wasserschlauch – den Euch Brine im Brachland gegeben hat – bis zum Vorgebirge des Hügellands tragt und reines Wasser aus dem Dorfbrunnen in Tarrens Mühle schöpft. Brine erinnert sich an den Brunnen als eine erstaunliche Quelle frischen Quellwassers, die mitten in einer Siedlung der Verlassenen überdauert hat.",al={"ursprung voller roter wasserschlauch","woher bekommt man den vollen roten wasserschlauch","wer hat den vollen roten wasserschlauch hergestellt"}}},fp="20,170,26.516.0,40.105.0,43.150.0,47.181.0,37.180.0"}
P.entries["item:filled-soul-gem"] = {n="Gefüllter Seelenedelstein",s="Nimboya bittet Euch, den Seelenedelstein nach Grom'gol zu bringen, wo sein Volk Yennikus Rückkehr erwartet.",h="Nimboya bittet Euch, den Seelenedelstein nach Grom'gol zu bringen, wo sein Volk Yennikus Rückkehr erwartet.",kw={"gefüllter seelenedelstein","grom'gol","kin'weelay","gedankenauge","nimboya","seelenedelstein","yenniku","zanzil"},sec={{t="Eine Seele kehrt zurück",b="Bei den Ruinen von Aboraz am Kap des Schlingendorntals wird der Seelenedelstein auf Yennikus Kopf gelegt, um seine Seele einzufangen. Bringt den Gefüllten Seelenedelstein zu Nimboya nach Grom'gol, wo sein Volk seine Rückkehr erwartet."}},faq={{q="Was ist der Gefüllte Seelenedelstein?",a="Der Gefüllte Seelenedelstein enthält Yennikus Seele, die mit dem Seelenedelstein bei den Ruinen von Aboraz eingefangen wurde.",al={"gefüllter edelstein","seelenedelstein mit yenniku","was ist im edelstein"}},{q="Wer ist Yenniku?",a="Yenniku gehört zu Nimboyas Stamm und steht unter dem Willen von Zanzil the Outcast.",al={"geschichte von yenniku","wer ist yenniku","yenniku"}},{q="Wohin bringe ich den Edelstein?",a="Bringt den Gefüllten Seelenedelstein zu Nimboya nach Grom'gol.",al={"wohin mit dem edelstein","wohin den edelstein bringen","nimboya edelstein"}},{q="Wie wurde der Seelenedelstein hergestellt?",a="Kin'weelay formte das Gedankenauge zu einem Seelenedelstein um, der Yennikus Seele einfängt.",al={"gedankenauge edelstein","seelenedelstein füllen","seelenedelstein herstellen"}}},fp="15,92,15.196.0,28.95.1,15.83.0,24.49.0,26.82.1"}
